(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["宗教"]=[{"id":"00009109","register_sub_id":"101","register_pk":"164662","name":"高龍寺位牌堂","kana":"こうりゅうじいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76904461,"lng":140.70010639,"geo_status":"db","era":"昭和8年／平成4年・平成9年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造地上1階地下1階建、瓦葺、建築面積161㎡、左右回廊付","structure_material":"木造地上1階地下1階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"開山堂と金毘羅堂の間に西面して建ち、南北面に開山堂と金毘羅堂へ至る廊下を附属する。桁行5間梁間4間、入母屋造、向拝一間付、桟瓦葺で、鉄筋コンクリート造の地階を持ち、上下階とも内部は位牌を安置する。向拝の虹梁木鼻や虹梁上の彫刻に技巧を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009109"},{"id":"00009102","register_sub_id":"101","register_pk":"164655","name":"高龍寺開山堂","kana":"こうりゅうじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76893753,"lng":140.70030864,"geo_status":"db","era":"明治30年頃／平成4年・平成9年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積156㎡","structure_material":"煉瓦造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本堂の北東側に西面する煉瓦造の堂で、土蔵造風に漆喰仕上とする。桁行14.2メートル梁間9.9メートル、寄棟造桟瓦葺で、銅板葺の一間向拝を設ける。内部は正面1間通を廊下とし、堂内に羅漢像を祀る。函館市内に残る煉瓦造建築の古例となる遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009102"},{"id":"00009105","register_sub_id":"101","register_pk":"164658","name":"高龍寺金毘羅堂","kana":"こうりゅうじこんぴらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76916001,"lng":140.69993091,"geo_status":"db","era":"大正6年／平成8年改修","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山門の東に西面して建つ桟瓦葺の堂。縦長平面の内陣正面に、方3間、入母屋造平入の大間を接続して丁字形をなし、南東に外単を張出す。大間の正面には軒唐破風付の向拝を付し、千鳥破風を重ねる。澤田吉平を棟梁とし、高龍寺境内で最も装飾的な建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009105"},{"id":"00009103","register_sub_id":"101","register_pk":"164656","name":"高龍寺山門及び袖塀","kana":"こうりゅうじさんもんおよびそでへい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76906186,"lng":140.69966024,"geo_status":"db","era":"明治43年頃／平成9年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"山門 木造、瓦葺、面積35㎡ 袖塀 木造、瓦葺、総延長29m、潜戸付","structure_material":"山門 木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内正面に北面して建つ入母屋造桟瓦葺の木造8脚門で、軸部は禅宗様を基調とし、門の左右に桟瓦葺の袖塀を延ばす。本堂を手がけた篠田宗吉の次代となる5代宗吉が棟梁を務めた。蟇股や欄間等に、雲龍や獅子、花鳥等の彫刻を施す、装飾豊かな門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009103"},{"id":"00009107","register_sub_id":"101","register_pk":"164660","name":"高龍寺鐘楼","kana":"こうりゅうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.7688947,"lng":140.6995258,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、銅板葺、面積14㎡","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山門の西に建つ。方1間、入母屋造銅板葺で、布石積基壇上に建ち、軸部は禅宗様を基調とする。柱間は吹放ちとし、組物は二手先で、内部は格天井を張る。細部意匠は山門や金毘羅堂と一連の絵様をもち、水盤舎同様、澤田吉平ら越後大工の普請と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009107"},{"id":"00009106","register_sub_id":"101","register_pk":"164659","name":"高龍寺水盤舎","kana":"こうりゅうじすいばんしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76900832,"lng":140.69987142,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、銅板葺、面積8.7㎡、水盤付","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"金毘羅堂と位牌堂間の前面に南北棟で建つ。方1間入母屋造銅板葺で、東西面に軒唐破風を付す。柱間を吹放ちとし、三斗上に小組格天井を張る。蟇股などの立体的で充実した彫刻は山門や金毘羅堂と類似し、澤田吉平ら越後大工による普請と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009106"},{"id":"00009110","register_sub_id":"101","register_pk":"164663","name":"高龍寺土塀","kana":"こうりゅうじどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76926112,"lng":140.69981744,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"土塀、瓦葺、総延長53m","structure_material":"土塀","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内の北辺、山門袖塀の左右にのびる土塀。高さ3.7メートルで、長さは東側23.7メートル西側29.2メートルを測る。布石積基壇上に建ち、壁は真壁漆喰仕上げで腰を簓子下見板張とする。桟瓦葺屋根の棟には青海波を積み、落ち着いた風格を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009110"},{"id":"00009104","register_sub_id":"101","register_pk":"164657","name":"高龍寺防火塀","kana":"こうりゅうじぼうかべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76921507,"lng":140.70008002,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"煉瓦造、瓦葺、総延長154m","structure_material":"煉瓦造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内の東面及び北面西側を画す煉瓦塀。北面西側塀はフランス積とし、延長約104メートル、高さ約3メートル。東面塀は延長約50メートル、高さ約7メートル、イギリス積とする。延焼を防止するため設けられた、大火が頻発した近代函館を象徴する遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009104"},{"id":"00009108","register_sub_id":"101","register_pk":"164661","name":"高龍寺宝蔵","kana":"こうりゅうじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道函館市船見町21-3","lat":41.76881761,"lng":140.69939398,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積63㎡","structure_material":"煉瓦造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"鐘楼の西に建つ煉瓦造の蔵。桁行9.7メートル、梁間6.1メートルの本体部は、2階建、切妻造桟瓦葺で、壁は漆喰で仕上げ、腰を簓子下見張とする。東妻に煉瓦壁を現した切妻造の蔵前を附属する。耐火性と景観に配慮し、煉瓦造を用いた独特の形式になる蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009108"},{"id":"00009101","register_sub_id":"101","register_pk":"164654","name":"高龍寺本堂","kana":"こうりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道函館市船見町21-1他","lat":41.76866389,"lng":140.70021347,"geo_status":"db","era":"明治32年／昭和63年増築、昭和61年・平成8年・平成11年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積526㎡、左右回廊付","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"函館山麓に北面して建ち、桁行9間梁間8間、入母屋造、正面向拝付、桟瓦葺で、周囲に下屋と縁を廻らし、東西に回廊を付属する。9室構成の堂内は、軸部木太く雄大で、棟梁の篠田宗吉以下、越後の工匠が関わった。大規模で装飾性豊かな近代の曹洞宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009101"},{"id":"00002500","register_sub_id":"101","register_pk":"103490","name":"最創山光岸寺本堂","kana":"さいそうざんこうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道旭川市東鷹栖東1条3丁目272-1","lat":43.824799,"lng":142.417664,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積592㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0047","desc":"市北東部，国道４０号に面する境内の奥に建つ。正面は欄間等に丁寧な彫物を施した桁行３間の向拝が唐破風屋根に覆われる。本堂は立ちが高く，軒下の小壁に蟇股を配した裳階を廻し，組物と蟇股を多用した華やかな内部空間をもつ。道内で有数の本格的寺院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002500"},{"id":"00005790","register_sub_id":"101","register_pk":"106778","name":"順誓寺本堂","kana":"じゅんせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道網走郡津別町字新町16","lat":43.70988818,"lng":144.02547003,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"01 － 0093","desc":"境内奥寄りに東南に面して建つ浄土真宗本堂。桁行７間，梁間７間，正面向拝付，切妻造，鉄板葺。内部柱を円柱とし，外陣では入側柱を成の高い虹梁で固める。内外陣境の彫刻欄間の上部にも絵様虹梁と大斗実肘木を入れ，全体に堅牢で華やかなつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005790"},{"id":"00007711","register_sub_id":"101","register_pk":"108693","name":"正行寺鐘楼","kana":"しょうぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道厚岸郡厚岸町梅香1-19他","lat":43.03622622,"lng":144.84622542,"geo_status":"db","era":"明治41／大正12・平成20改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、銅板葺、面積7.5㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"01-0103","desc":"北面する本堂の北西に南北棟で建つ。入母屋造銅板葺とする方一間の吹放ち鐘楼。唐戸面取の方柱を四方転びに建て、足固貫と内法貫、頭貫、台輪で固める。三斗組で中備に蟇股を配し、一軒疎垂木とし、格天井を張る。明治期に整えられた伽藍景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007711"},{"id":"00014991","register_sub_id":"101","register_pk":"529269","name":"清隆寺本堂","kana":"せいりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道根室市松本町二丁目1-1他","lat":43.328575,"lng":145.57568056,"geo_status":"db","era":"大正14年／昭和50年代改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積258㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"01 - 0170","desc":"根室市街地に位置する真言宗寺院本堂。入母屋造鉄板葺で北面に軒唐破風付向拝を配し千鳥破風を付す。向拝虹梁、木鼻、懸魚の獅子、龍、鳳凰など彫刻秀逸。内部は前方を参詣間、後方を内陣・脇内陣とし内陣を前方に張出す。気仙大工花輪喜久蔵の道内作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014991"},{"id":"00000720","register_sub_id":"101","register_pk":"101710","name":"日本基督教団札幌教会（旧札幌美以教会堂）","kana":"にほんきりすときょうだんさっぽろきょうかい（きゅうさっぽろめそじすときょうかいどう）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道札幌市中央区北1条東1","lat":43.06351193,"lng":141.35710071,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"石造平屋建，鉄板葺，建築面積233㎡","structure_material":"石造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"01 － 0008","desc":"市街地に建つ教会。木造の教会が焼失した後に建てられたもので，木造骨組の表面に石を貼り耐火に備えた構造になる。意匠は全体的にはロマネスク風だが，バラ窓等の細部にはゴシック風の意匠もみられる。市街地のランドマーク的存在として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000720"},{"id":"00015272","register_sub_id":"101","register_pk":"532396","name":"本行寺旧納骨堂","kana":"ほんぎょうじきゅうのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"北海道","address":"北海道釧路市弥生二丁目31他","lat":42.97300833,"lng":144.37698889,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積88㎡、渡廊下付","structure_material":"木造平屋建","registered":null,"register_no":"01 - 0173","desc":"本堂の北に接続する納骨堂。西面して建つ入母屋造妻入鉄板葺で正面に入母屋造庇を付す。内部は一室の板敷で南西に納骨棚を設ける。側廻りは櫛形欄間付の上下窓を並べ、外壁モルタル塗仕上、腰は目地を切り石造風。重厚な外観が本堂とともに境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015272"},{"id":"00015271","register_sub_id":"101","register_pk":"532395","name":"本行寺本堂","kana":"ほんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道釧路市弥生二丁目31他","lat":42.97285,"lng":144.37685556,"geo_status":"db","era":"大正14年／平成4年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋一部2階建一部地階付、銅板葺、建築面積841㎡","structure_material":"木造平屋一部2階建一部地階付","registered":"2025.03.13(令和7.03.13)","register_no":"01 - 0172","desc":"市街地南西の高台にある浄土真宗寺院の本堂。境内中央に西面して建つ木造二階建入母屋造で正面に千鳥破風を飾り入母屋造玄関を付す。小屋組はトラス。和風を基調とし、外壁は目地を切って石造風。外部木鼻彫刻など精緻な左官技術を示す良質な近代和風の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015271"},{"id":"00010541","register_sub_id":"101","register_pk":"201115","name":"カトリック十和田教会","kana":"かとりっくとわだきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県十和田市稲生町162","lat":40.6174021,"lng":141.2128569,"geo_status":"db","era":"昭和7年／昭和39年移築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積165㎡","structure_material":"木造2階建","registered":"2015.08.04(平成27.08.04)","register_no":"02－0100","desc":"角地に建つ木造教会。正面の切妻屋根に鐘塔を戴き、切妻の玄関を張出し、外壁下見板張にアーチ窓を配する。内部は三廊式で側廊上部を回廊とする。身廊両側に柱頭飾を載せた円柱を並べ、連続アーチを架ける。教会建築を多く手掛けたヒンデルによる清楚な教会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010541"},{"id":"00016337","register_sub_id":"101","register_pk":"536404","name":"最勝院庚申堂","kana":"さいしょういんこうしんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59632222,"lng":140.46923889,"geo_status":"db","era":"江戸後期／昭和前期改修、同39年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積3.8㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0110","desc":"聖徳太子堂の南に西面して建つ庚申堂。一間社見世棚造の形式で屋根鉄板葺。井桁に組んだ土台上に円柱を立てて頭貫で固め、三斗を組み、軒は板軒、妻飾は虹梁大瓶束笈形付とする。全体に弁柄塗を施しつつ、海老虹梁、肘木、蟇股の彫刻や彩色など装飾華やか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016337"},{"id":"00016339","register_sub_id":"101","register_pk":"536406","name":"最勝院五智如来堂","kana":"さいしょういんごちにょらいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59643333,"lng":140.46911667,"geo_status":"db","era":"弘化3年(1846)／昭和7年改修、同39年頃移築、平成28年改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0112","desc":"護摩堂の北東に西面して建つ五智如来堂。正面三間、側面三間、切妻造鉄板葺で一間向拝を付す。正面中央間は引分戸、脇間は格子戸、壁は白漆喰塗で腰は竪板張。内部は一室の板敷で背面側を仏壇とする。向拝中備に龍の彫刻を飾り、境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016339"},{"id":"00016334","register_sub_id":"101","register_pk":"536401","name":"最勝院護摩堂","kana":"さいしょういんごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59634167,"lng":140.46895556,"geo_status":"db","era":"文化14年（1817）／江戸末期改修、昭和39年頃移築、平成27年改修","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0107","desc":"弘前城跡の南東に位置する真言宗寺院の護摩堂。境内中央に北面して建つ宝形造銅板葺で、一間向拝を付し、頂部に宝珠を飾る。組物は舟肘木で軒は一軒疎垂木。内部は内外陣からなり、背面側の仏壇中央を須弥壇とする。全体に装飾少なく質実なつくりの護摩堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016334"},{"id":"00016335","register_sub_id":"101","register_pk":"536402","name":"最勝院聖徳太子堂","kana":"さいしょういんしょうとくたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59634444,"lng":140.46922778,"geo_status":"db","era":"江戸後期／大正2年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積2.0㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0108","desc":"護摩堂の東に西面して建つ太子堂。一間四方の宝形造銅板葺で、頂部に宝珠を飾り、四周に切目縁を廻らす。土台建ちの円柱に三斗を組み、軒は二軒扇垂木、中備は菊花の彫刻付蟇股とし、正面に桟唐戸を開く。組物などに彩色を施し、全体に装飾華やかな小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016335"},{"id":"00016341","register_sub_id":"101","register_pk":"536408","name":"最勝院鐘楼","kana":"さいしょういんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59674167,"lng":140.46877222,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造、銅板葺、面積9.5㎡、周囲石柱付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0114","desc":"境内中央に位置する鐘楼。基壇上に建つ一間四方の入母屋造銅板葺で、四隅に几帳面取角柱を内転びに立て、各間隅寄りの控柱とともに地覆、腰貫、飛貫で固める。内部の上部は格天井を張り、格間に龍と草花を描き、中央に梵鐘を吊る。木太く堂々たる姿の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016341"},{"id":"00016342","register_sub_id":"101","register_pk":"536409","name":"最勝院仁王門","kana":"さいしょういんにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.596275,"lng":140.46911667,"geo_status":"db","era":"文政10年（1827）／昭和2年改修、同39年頃移築","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0115","desc":"境内南東部に至る参道の仁王坂に東面して建つ八脚門。切妻造平入鉄板葺。柱は全て角柱で組物は舟肘木、妻飾上部は豕扠首で大斗上に拳鼻を付す特徴的なつくり。両脇間東側は床板敷で棹縁天井とし、かつて仁王像一対を安置。境内の正面構えをつくる仁王門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016342"},{"id":"00016340","register_sub_id":"101","register_pk":"536407","name":"最勝院如意輪観世音菩薩堂","kana":"さいしょういんにょいりんかんぜおんぼさつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59662778,"lng":140.46925556,"geo_status":"db","era":"元治元年（1864）／平成18年改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.8㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0113","desc":"境内東側に西面して建つ六角堂。屋根銅板葺で頂部に露盤宝珠を飾る。土台上に六角柱を立て、地長押、内法長押を廻らし、絵様肘木で桁を受け、軒は一軒扇垂木。正面は桟唐戸を開いて縁を付し、木部は弁柄塗。大振りな持送で隅木を支え、軒廻り賑やかな小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016340"},{"id":"00016336","register_sub_id":"101","register_pk":"536403","name":"最勝院文殊堂","kana":"さいしょういんもんじゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59642222,"lng":140.46920833,"geo_status":"db","era":"江戸後期／昭和前期改修、同39年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積3.7㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0109","desc":"聖徳太子堂の北に西面して建つ文殊堂。一間社見世棚造の形式で屋根鉄板葺とする。井桁に組んだ土台上に角柱を立て、地長押、内法長押を廻らし、頭貫で固め、組物は大斗で軒は板軒、妻飾は虹梁に棟束とする。全体に弁柄塗を施し、簡素ながら丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016336"},{"id":"00016338","register_sub_id":"101","register_pk":"536405","name":"最勝院薬師堂","kana":"さいしょういんやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"青森県","address":"青森県弘前市大字銅屋町63-20他","lat":40.59634722,"lng":140.46912222,"geo_status":"db","era":"文政6年（1823）／昭和前期改修、同39年頃移築","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積2.5㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"02 - 0111","desc":"聖徳太子堂の南西に西面して建つ薬師堂。一間社見世棚造の形式で、屋根鉄板葺。土台上に円柱を立てて、頭貫で固め、地長押、内法長押を廻らす。組物は用いず、軒は板軒とする。全体に簡素ながらも、文殊堂や庚申堂と並び建ち、境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016338"},{"id":"00011617","register_sub_id":"101","register_pk":"210633","name":"法光寺承陽塔","kana":"ほうこうじじょうようとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和中","pref":"青森県","address":"青森県三戸郡南部町大字法光寺字法光寺20-6","lat":40.389355,"lng":141.3234,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造三重塔、銅板葺、建築面積55㎡","structure_material":"木造三重塔","registered":"2017.06.28(平成29.06.28)","register_no":"02-0102","desc":"道元の遺骨を奉安するための三重塔で、総高三三メートル。初層は全て丸柱、上部は内部のみ角柱とし、心柱も角柱を用いる。組物は三手先で間に彫刻を飾り、軒は三層とも二軒繁垂木。戦後に建てられた木造三重塔の中でも最大級の規模を有する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011617"},{"id":"00001468","register_sub_id":"101","register_pk":"102458","name":"盛田牧場馬頭観音堂奥殿","kana":"もりたぼくじょうばとうかんのんどうおくでん","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.70998866,"lng":141.17129604,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、銅板葺、建築面積8.2㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0009","desc":"もと盛田家の稲荷大明神であったが，戦後に現地に移築し，馬頭観音を祀った。屋敷神を祀る社としては規模の大きな正式の１間社流造で，中備蟇股や虹梁等の絵様が流麗で，装飾彫物も質が高い。建築年代は盛田家が農場経営を開始した明治初期頃と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001468"},{"id":"00001470","register_sub_id":"101","register_pk":"102460","name":"盛田牧場馬頭観音堂鳥居","kana":"もりたぼくじょうばとうかんのんどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.71025196,"lng":141.17123035,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、幅2.7m","structure_material":"木造","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0011","desc":"馬頭観音堂は牧場内の木立の中にあり，その参道南側に鳥居が建っている。丸太状の部材を用い，親柱を掘立で建てた素朴な形式で，額束をもつ点で鹿島鳥居と異なる。奥殿・拝殿とともに，牧場景観の構成要素として欠かせない存在になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001470"},{"id":"00001469","register_sub_id":"101","register_pk":"102459","name":"盛田牧場馬頭観音堂拝殿","kana":"もりたぼくじょうばとうかんのんどうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県上北郡七戸町字膝森14-1","lat":40.71009197,"lng":141.17140271,"geo_status":"db","era":"明治40頃","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"02 － 0010","desc":"入母屋造・鉄板葺で正面向拝付の３間堂で，盛田家の稲荷大明神を移築するまでは，馬頭観音を祀っていた。装飾細部の少ない簡素な建物で，建築年代は堂の扁額の年記より，盛田牧場として各種の施設を整えていった明治４０年頃と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001469"},{"id":"00015113","register_sub_id":"101","register_pk":"530537","name":"愛宕神社本殿（旧愛宕山大権現堂）","kana":"あたごじんじゃほんでん（きゅうあたごさんだいごんげんどう）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岩手県","address":"岩手県奥州市江刺愛宕字西下川原197","lat":39.17558889,"lng":141.15461389,"geo_status":"db","era":"正徳4年(1714)／文久2年（1862）・昭和32年改修","year":1714,"year_source":"db","year_min":1714,"year_max":1714,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"03 - 0125","desc":"北上川東岸、かつて下川原御蔵があった集落の鎮守。境内西側の基壇上に東面して建つ宝形造三間堂で正面一間向拝付。三斗を組み、中備は蟇股で十二支彫刻を飾り、軒はせがい造。内部一室で西辺中央に須弥壇を設ける。小壁や組物などに塗装彩色を一部残し貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015113"},{"id":"00011032","register_sub_id":"101","register_pk":"205139","name":"上和野馬頭観世音旧堂","kana":"かみわのばとうかんぜおんきゅうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岩手県","address":"岩手県岩手郡雫石町上野下沢田105","lat":39.706621,"lng":140.924808,"geo_status":"db","era":"江戸中期／明治14改修、大正3移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"03 - 0085","desc":"北面して建つ三間堂で、正面に一間向拝を設ける。前身本堂と伝わり、現在は絵馬堂として用いられる。痕跡から、当初は奥に三間通しの仏壇が設けられていたとみられる。名馬の産地として知られた当地における信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011032"},{"id":"00011031","register_sub_id":"101","register_pk":"205138","name":"上和野馬頭観世音本堂","kana":"かみわのばとうかんぜおんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県岩手郡雫石町上野下沢田105","lat":39.706761,"lng":140.924657,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"03 - 0084","desc":"袖山山麓に東向きに境内を開く。本堂は東面して建つ三間堂で、正面に一間向拝を設ける。正側面に高欄付の縁を廻らし、脇障子を備える。柱上を尾垂木付二手先組物で華やかに飾り、内部板支輪の地紋彫や、向拝周りの立体的な彫刻などに見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011031"},{"id":"00015114","register_sub_id":"101","register_pk":"530538","name":"旧盛岡天主堂","kana":"きゅうもりおかてんしゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"岩手県","address":"岩手県盛岡市厨川五丁目54-1","lat":39.74928611,"lng":141.12535278,"geo_status":"db","era":"大正元年／昭和前期改修、同42年増築、同53年移築","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、鉄板葺一部スレート葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"03 - 0126","desc":"盛岡大学附属高等学校敷地内に建つ。切妻造鉄板葺で正面にスレート葺鐘楼を戴く。三廊式で、正面に玄関、背面に半円形平面の祭壇を付す。身廊は柱頭飾付き円柱を並べてアーチを架けヴォールト天井を張る。ロマネスクを基調とした繊細な意匠の木造天主堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015114"},{"id":"00005819","register_sub_id":"101","register_pk":"106806","name":"日本基督教団一関教会","kana":"にほんきりすときょうだんいちのせききょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県一関市田村町2-14","lat":38.928829,"lng":141.131943,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"03 － 0064","desc":"通りに面して建つ，建築面積１７１㎡，木造平屋建，鉄板葺。聖堂正面右側に尖塔が建つ。小屋組はハンマービームやタイバー等で構成される。外壁は下見板張で２連尖頭アーチ窓を配し，聖堂正面の窓や玄関上部は三葉形アーチ意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005819"},{"id":"00012682","register_sub_id":"101","register_pk":"367586","name":"青葉神社旧愛姫社鞘堂","kana":"あおばじんじゃきゅうめごひめしゃさやどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和6年／昭和中期移築・改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 164","desc":"拝殿の前方に南面して建つ。桁行二間梁間一間、入母屋造銅板葺妻入で、正面に桟唐戸、側面に連子窓を設ける。内部は畳敷で格天井を張る。組物は大斗肘木、妻飾は豕叉首、軒は一軒疎垂木。小規模ながら、拳鼻や肘木に本殿と共通の絵様をもつ上質な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012682"},{"id":"00012681","register_sub_id":"101","register_pk":"367585","name":"青葉神社神饌所及び伝供廊","kana":"あおばじんじゃしんせんじょおよびでんくろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 163","desc":"拝殿の北西方に建つ。神饌所は桁行三間梁間三間、入母屋造銅板葺で、東面南端に設けた切妻造銅板葺の伝供廊で拝殿と接続する。内部は南に廊下、北に板敷の一室を配し、組物は舟肘木、軒は一軒疎垂木とする。拝殿と融和して近代的な社頭景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012681"},{"id":"00012679","register_sub_id":"101","register_pk":"367583","name":"青葉神社透塀","kana":"あおばじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、銅板葺、総延長87m、潜戸付","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 161","desc":"本殿の四周を結界する木造銅板葺の透塀。基壇は切石積、腰は井桁と襷桟付の板張、腰上は木連格子とし、両側面の前方に桟唐戸の潜門を設ける。屋根は肘木付の腕木で軒桁を受け、一軒疎垂木とする。良材を用いた精緻なつくりで、本殿の周辺を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012679"},{"id":"00012678","register_sub_id":"101","register_pk":"367582","name":"青葉神社中門及び祝詞舎","kana":"あおばじんじゃちゅうもんおよびのりとしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"中門 木造、銅板葺、間口3.6m 祝詞舎 木造、銅板葺、面積8.8㎡","structure_material":"中門 木造","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 160","desc":"本殿正面の透塀に開く中門と、その背面に棟を直交して接続する祝詞舎。中門は切妻造銅板葺の四脚門で、組物は大斗肘木、中備は蟇股、軒は一軒。祝詞舎は切妻造銅板葺の吹放ち形式で、豕叉首上の肘木で棟木を受ける。本殿と共通の意匠をもつ上質な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012678"},{"id":"00012680","register_sub_id":"101","register_pk":"367584","name":"青葉神社拝殿","kana":"あおばじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 162","desc":"本殿正面に南面して建つ。桁行五間梁間三間、入母屋造銅板葺、向拝一間付で四周に縁を廻す。組物は大斗肘木、中備は正背面の中央間のみに配する。軒は一軒。内部は畳敷で格天井を張る。整然とした参道の突当りにある近代的な社頭景観の中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012680"},{"id":"00012677","register_sub_id":"101","register_pk":"367581","name":"青葉神社本殿","kana":"あおばじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区青葉町173他","lat":38.28242583,"lng":140.8674,"geo_status":"db","era":"大正13年","year":1924,"year_source":"converted","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 159","desc":"仙台旧城下北端の伊達政宗を祀る神社。本殿は前室付三間社流造銅板葺、向拝一間付で四周に縁を廻す。組物は平三斗で庇を大斗肘木とする。木鼻は幾何学的な意匠だが庇中央間と向拝の蟇股は中世風とするなど、伝統形式や意匠を巧みに構成し直した近代神社本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012677"},{"id":"00008610","register_sub_id":"101","register_pk":"149331","name":"大崎八幡宮旧宮司宿舎","kana":"おおさきはちまんぐうきゅうぐうじしゅくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区八幡4-170","lat":38.27143735,"lng":140.84448562,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"04 － 0086","desc":"社務所の南に渡り廊下を介して繋がる。入母屋造東西棟の主棟北面に、寄棟屋根を付設。桟瓦葺。田字型に4室を配し、北面にトコを備えた社務室を突出する。社務所玄関と同様の緩やかな起りをもつ主棟妻を正面に見せ、社務所と外観の調和が図られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008610"},{"id":"00008609","register_sub_id":"101","register_pk":"149330","name":"大崎八幡宮社務所","kana":"おおさきはちまんぐうしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区八幡4-170","lat":38.27158003,"lng":140.84452527,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"04 － 0085","desc":"参道の西側に東面して建つ。主棟は入母屋造、西に寄棟屋根、東に入母屋造の玄関を付ける。桟瓦葺。トコとトコ脇を設ける主室と次の間を南北に配し、主室西側に貴賓室を付設。貴賓室にはトコと違棚、付書院を備える。玄関の屋根は優美な起りをもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008609"},{"id":"00008611","register_sub_id":"101","register_pk":"149332","name":"大崎八幡宮神馬舎","kana":"おおさきはちまんぐうしんめしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県仙台市青葉区八幡4-170","lat":38.2716811,"lng":140.84516374,"geo_status":"db","era":"大正後期／平成22年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"04 － 0087","desc":"社務所の東方、参道を挟んだ位置に建つ。南北棟の入母屋造桟瓦葺で、西面は縋破風を付け、葺き降ろす。北寄りに床上部、南は東に厩2室を設け、西に土間を通し、物置を突出する。厩は土間に厚板を敷き詰め、内法下を竪板張とするなど、伝統的な仕様を受け継ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008611"},{"id":"00014228","register_sub_id":"101","register_pk":"509618","name":"大高森薬師堂","kana":"おおたかもりやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県東松島市宮戸字瀬戸浜23-1","lat":38.33997778,"lng":141.15129167,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"04 - 0214","desc":"特別名勝松島の宮戸島に所在。公園整備の一環で建設された薬師堂。正面三間側背面二間宝形造桟瓦葺。丸柱を長押で固め組物は舟肘木で軒は一軒疎垂木。正面に板唐戸、側面に連子窓を建てる。向拝を持たず、瓦当に重弁蓮華文を施す等、復古的な様相を示す仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014228"},{"id":"00013476","register_sub_id":"101","register_pk":"504844","name":"大嶽山興福寺書院及び庫裏","kana":"おおだけさんこうふくじしょいんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市南方町本郷大嶽18","lat":38.65590556,"lng":141.18680556,"geo_status":"db","era":"明治中期／大正11年・昭和56年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建一部2階建、銅板及び鉄板葺、建築面積312㎡","structure_material":"木造平屋建一部2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0181","desc":"旧南方町にある天台宗寺院。境内中央に南面して建ち、西は寄棟造の書院、東は正面を入母屋造とした庫裏とし、書院正面東端に唐破風造屋根を付す。書院は前後二列の室配置を基本に素朴に造るが、北西座敷の床構えに色ガラスを用いる等先駆的な試みも見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013476"},{"id":"00016476","register_sub_id":"101","register_pk":"574838","name":"久須師神社拝殿（旧薬師堂）","kana":"くすしじんじゃはいでん（きゅうやくしどう）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県石巻市尾崎字宮下52","lat":38.4278775,"lng":141.30606389,"geo_status":"db","era":"文久2年（1862）／明治11年・同29年・昭和34年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"04 - 0245","desc":"長面浦北岸にある神社の拝殿。西面して建つ桁行三間梁間三間、入母屋造スレート葺で正面に一間向拝を付し、三方に擬宝珠高欄付縁を廻らす。組物は禅宗様の尾垂木付三手先で軒は二軒扇垂木、向拝柱の地紋彫など要所を彫刻で飾る。スレート葺屋根の希少な拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016476"},{"id":"00016343","register_sub_id":"101","register_pk":"536410","name":"西光寺大滝不動堂","kana":"さいこうじおおたきふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"宮城県","address":"宮城県仙台市太白区秋保町馬場字大滝11","lat":38.27412778,"lng":140.603925,"geo_status":"db","era":"文政8年（1825）頃／昭和29年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"04 - 0228","desc":"秋保大滝の南岸に建つ真言宗寺院西光寺の不動堂。宝形造銅板葺、一間向拝付の大型三間堂。軒は三軒。組物は出組で板支輪や小壁、蟇股、向拝廻りなどを華麗な彫刻で飾り、外陣天井格間に草花、内陣天井に双龍の墨画を描く。地域の信仰を集める装飾豊富な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016343"},{"id":"00013921","register_sub_id":"101","register_pk":"508181","name":"孝子堂","kana":"せんねんじこうしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県白石市大鷹沢三沢字熊野堂42","lat":37.99295833,"lng":140.638325,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.8㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"04 - 0209","desc":"歌舞伎の仇討ち演目である白石噺ゆかりの小堂で、話の発端となる水田を見下ろす丘に所在する。方一間宝形造銅板葺向拝付で、虹梁や組物で飾り、四周切目縁で全体に朱漆塗とする。内部は一室で仇を討ち果たした姉妹の像を祀り、文人や花柳界の信仰を集めた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013921"},{"id":"00014708","register_sub_id":"101","register_pk":"518966","name":"津島神社拝殿","kana":"つしまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県登米市迫町佐沼字西佐沼141","lat":38.68434167,"lng":141.19684722,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0218","desc":"本殿の北に建つ入母屋造平入銅板葺の東西棟で北面の三間向拝に軒唐破風を付す。三方に縁を付して脇障子を建て、組物は出組で軒支輪を備え、軒は二軒繁垂木とする。内部は一室の畳敷で、格天井を張る。妻飾や海老虹梁など彫刻で華やかに飾り時代相を示す拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014708"},{"id":"00014707","register_sub_id":"101","register_pk":"518965","name":"津島神社本殿","kana":"つしまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県登米市迫町佐沼字西佐沼141","lat":38.6842,"lng":141.19685,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0217","desc":"仙台藩の要害、佐沼にある神社。境内南寄りに北面する本殿は一間社流造銅板葺で、三方に縁を廻らし、脇障子を建てる。組物は出組とし軒は二軒繁垂木。妻飾は虹梁大瓶束で笈形を付し、頂部には花肘木を重ねて棟木を支える。全体に彫刻が濃密で華やかな本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014707"},{"id":"00014709","register_sub_id":"101","register_pk":"518967","name":"津島神社神輿殿","kana":"つしまじんじゃみこしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県登米市迫町佐沼字西佐沼141","lat":38.68450833,"lng":141.19676667,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.7㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"04 - 0219","desc":"拝殿北西に建つ桁行３間、梁間２間、平屋建入母屋造妻入銅板葺の東西棟。組物は出三斗、軒は一軒繁垂木。東の戸口に両開の格子戸を開く。内部は一室の土間で格天井を張り、中央に神輿を置く。簡素ながらも丁寧なつくりで境内の歴史的景観を形成する神輿殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014709"},{"id":"00012088","register_sub_id":"101","register_pk":"352887","name":"定義如来西方寺御守授所","kana":"ていぎにょらいさいほうじおまもりじゅじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363709,"lng":140.668371,"geo_status":"db","era":"昭和2年／昭和51年曳家、昭和32年・平成20年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.1㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"04-146","desc":"御廟貞能堂の前方、参道南側に建つ。桁行二・九メートル、梁間二・一メートルの小ぶりな建物であるが、屋根を入母屋造銅板葺とするなど本格的な造り。四面に腰長押を廻らし、足元は下見板張、東と北面は全面ガラス戸とし、そのほかは竪板壁に窓や入口を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012088"},{"id":"00012087","register_sub_id":"101","register_pk":"352886","name":"定義如来西方寺御廟貞能堂","kana":"ていぎにょらいさいほうじごびょうさだよしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363831,"lng":140.668266,"geo_status":"db","era":"昭和2年／昭和32年・同43年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積165㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"04-145","desc":"平貞能の墳墓上に建てられた小堂を起源とし、前身堂の部材を一部再用した。六角堂の背後に方形の裏堂が附属する構成で、屋根は銅板葺の六注造宝塔屋根付。周囲に裳階状の廻廊が廻り、正面に向唐破風付向拝を付す。外部を中心に彫刻で飾る特色ある堂宇である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012087"},{"id":"00012091","register_sub_id":"101","register_pk":"352890","name":"定義如来西方寺山門","kana":"ていぎにょらいさいほうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363601,"lng":140.668742,"geo_status":"db","era":"昭和7年／昭和32年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、銅板葺、建築面積25㎡、左右袖塀付","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"04-149","desc":"西方寺境内の旧中心地の入口を画す。三間一戸の二重門で屋根は入母屋造銅板葺とし、上層正面側中央に軒唐破風を付す。虹梁より上部に多量の彫刻を入れ、組物は出組、軒は上層下層とも二軒繁垂木とする。気仙大工の手による、装飾豊かな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012091"},{"id":"00012089","register_sub_id":"101","register_pk":"352888","name":"定義如来西方寺鐘楼堂","kana":"ていぎにょらいさいほうじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363755,"lng":140.668582,"geo_status":"db","era":"昭和7年／昭和32年・同60年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、面積11㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"04-147","desc":"山門奥、参道の北側に建つ木造平屋建、入母屋造銅板葺の鐘楼堂。四隅の円柱を腰貫で固め、内法貫・頭貫の位置に虹梁を重ねて木鼻を出し、台輪を置く。虹梁間には菱格子欄間を入れ、出組、中備蟇股、二軒繁垂木とする。天井は格天井である。装飾豊かな鐘楼堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012089"},{"id":"00012090","register_sub_id":"101","register_pk":"352889","name":"定義如来西方寺手水舎","kana":"ていぎにょらいさいほうじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区大倉字上下1","lat":38.363642,"lng":140.668595,"geo_status":"db","era":"昭和8年頃／昭和32年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、面積2.8㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"04-148","desc":"山門奥にあって参道の南側に建つ切妻造銅板葺の手水舎。四隅に角柱を立て、頭貫の位置に虹梁を入れ、天井は格天井とする。組物は三斗組、中備蟇股、軒は二軒繁垂木である。小ぶりながら装飾豊かで、本格的な意匠を備える境内建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012090"},{"id":"00011035","register_sub_id":"101","register_pk":"205142","name":"當信寺山門","kana":"とうしんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県白石市字本町62","lat":38.0003,"lng":140.622982,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0122","desc":"白石城二之丸大手二之門の部材を用いて建てられたと伝わる。三間一戸門で、上部にはもと櫓部とみられる切妻造瓦葺の鐘楼を載せ、その中央には宝珠形の枠を付けた大きな開口を設ける。幕末の動乱を経て、近世から近代へ移り変わる旧城下の歴史をしのばせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011035"},{"id":"00011034","register_sub_id":"101","register_pk":"205141","name":"當信寺本堂","kana":"とうしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"宮城県","address":"宮城県白石市字本町62","lat":38.000241,"lng":140.623301,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0121","desc":"白石城下の南東に境内を構える。正面一間通りの広縁と、その奥の外陣、そして内陣、脇間からなる浄土宗寺院本堂の特徴的平面である。内陣組物は支輪付出組とし、鏡天井を張る。正面には一間向拝を設け、手挟に籠彫の彫刻を嵌めるなど、要所を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011034"},{"id":"00014997","register_sub_id":"101","register_pk":"529275","name":"日本基督教団岩沼教会","kana":"にほんきりすと きょうだんいわぬまきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県岩沼市桜二丁目37-2","lat":38.10566111,"lng":140.86855556,"geo_status":"db","era":"昭和5年／平成4年・同24年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造平屋一部3階建、銅板葺、建築面積120㎡","structure_material":"石造平屋一部3階建","registered":"2024.08.15(令和6.08.15)","register_no":"04 - 0221","desc":"岩沼市街地に位置する教会。石造平屋建切妻造銅板葺の礼拝堂に宝形造塔屋を付属。外観は石積を現し尖塔アーチ窓を並べる。内部は玄関から東へ礼拝室、講壇を配し、小屋はハンマービームとタイバーを用い天井を折上げる。石造の重厚な外観が地域景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014997"},{"id":"00004308","register_sub_id":"101","register_pk":"105298","name":"新波神社拝殿","kana":"あらわじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市雄和新波字樋口16","lat":39.526939,"lng":140.23093797,"geo_status":"db","era":"明治23","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"05 － 0111","desc":"桁行３間梁行２間規模，入母屋造，鉄板葺，平入の拝殿で，正面に１間の軒唐破風付き向拝を設け，３面に刎高欄付縁を廻らす。柱は円柱，組物は二手先で尾垂木・支輪を備える。軒は二軒繁垂木。各部の彫物に見所がある。棟梁は松本銀蔵らと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004308"},{"id":"00015118","register_sub_id":"101","register_pk":"530542","name":"旧観音寺鐘楼","kana":"きゅうかんのんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市本町168-1","lat":39.31901389,"lng":140.56661111,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、鉄板葺、面積23㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0246","desc":"横手川北岸に張出す高台上に建つ、旧真言宗寺院の袴腰付鐘楼。方一間、入母屋造鉄板菱葺で、柱間に虹梁形頭貫を架けて三斗を組み、軒は二軒繁垂木とする。四方を吹放ち、欄干を廻し、上部中央に梵鐘を吊る。景勝地の蛇の崎に建ち、地域のランドマーク的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015118"},{"id":"00003944","register_sub_id":"101","register_pk":"104934","name":"金嶺山龍源寺本堂","kana":"きんれいざんりゅうげんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市矢島町城内字田屋の下26","lat":39.23160793,"lng":140.13089702,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、茅葺、建築面積441㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"05 － 0096","desc":"桁行２４ｍ梁間１６ｍの大規模な木造寺院建築で，左側に位牌堂へ通ずる廊下を設け，正面東寄りに入母屋造，軒唐破風とした向拝を付ける。棟札から棟梁「佐々木光信」が判明。雄大な茅葺屋根に特色があり，重厚な佇まいが，周囲の杉木立によく溶け込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003944"},{"id":"00015119","register_sub_id":"101","register_pk":"530543","name":"正平寺経蔵","kana":"しょうへいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"秋田県","address":"秋田県横手市田中町58-2","lat":39.31225,"lng":140.56574167,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積30㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0247","desc":"横手城跡南西の旧外町に位置する曹洞宗寺院の経蔵。境内南東に建つ土蔵造切妻造妻入鉄板葺で、北面に向唐破風向拝を付す。外壁モルタル洗出仕上で目地を切り石造風。内部は一室の土間で中央に江戸後期の八角輪蔵を納める。大振りな向拝が華やかな外観の経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015119"},{"id":"00015120","register_sub_id":"101","register_pk":"530544","name":"正平寺山門","kana":"しょうへいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市田中町58-2","lat":39.31258889,"lng":140.565875,"geo_status":"db","era":"明治37年／昭和42年改修","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造、鉄板葺、間口6.9m、袖塀付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"05 - 0248","desc":"境内北東隅、羽州街道に東面して建つ、三間一戸の薬医門で両脇に鉄板葺袖塀を付す。主柱、控柱の冠木上に渡した梁先端に平三斗を配して二軒を支持。妻飾は虹梁大瓶束風で梁側面まで彫刻で飾り、装飾豊富で賑やかな外観。赤門と地域で呼び親しむ大規模な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015120"},{"id":"00004692","register_sub_id":"101","register_pk":"105682","name":"神明社稲荷鳥居","kana":"しんめいしゃいなりとりい","category":"宗教","subcategory":"建築物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26548252,"lng":140.11374948,"geo_status":"db","era":"文化7","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"石造、高さ4.1m、幅3.0m","structure_material":"石造","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0121","desc":"参道入口から石段を上がった位置に建つ石製鳥居。反りのある笠木と島木，柱上に台輪をもつ稲荷鳥居の形式である。全高約４ｍ，柱間約３ｍで，柱高さ３．４ｍに対して２５㎝の内転びを持つ。厚みのある台輪，幅の広い台形の額束に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004692"},{"id":"00004107","register_sub_id":"101","register_pk":"105097","name":"神明社宮殿","kana":"しんめいしゃくうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26470683,"lng":140.1152146,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、板葺、建築面積2㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0109","desc":"本殿内に安置された金箔塗，装飾豊かな宮殿で，寄棟屋根に千鳥破風付きの切妻屋根を載せた屋根の造形は特異。千鳥破風の懸魚には当地を治めた六郷氏の六郷亀甲を用いる。棟札から「大工棟梁尾留川宇左エ門 塗師棟梁小松権之丞 彫師小川松四郎」が判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004107"},{"id":"00004690","register_sub_id":"101","register_pk":"105680","name":"神明社境内社合殿","kana":"しんめいしゃけいだいしゃあいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26462977,"lng":140.11513394,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、鉄板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0119","desc":"桁行４間半，梁間３間の木造平屋建，切妻造の妻入で，屋根を鉄板葺とする。正面柱上に舟肘木を飾り，妻に梁を重ねる。奥から４尺半に円柱を立て，出組，実肘木，蟇股を飾り，一段高く床を張って内陣とする。外陣天井の一部には嘉永５年銘の龍像墨絵がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004690"},{"id":"00004108","register_sub_id":"101","register_pk":"105098","name":"神明社拝幣殿","kana":"しんめいしゃはいへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26477818,"lng":140.11505901,"geo_status":"db","era":"慶応3／大正4増築","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積158㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0110","desc":"桁行３間梁間３間の拝殿と桁行３間梁間２間の幣殿から成る。棟をＴ字形にした社殿で，千鳥破風と軒唐破風付き向拝とによる正面構えをとり，向拝柱と拝殿側柱に架けられた繋虹梁の上には力士像一対を置くなど，装飾性豊かな彫物で正面を飾っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004108"},{"id":"00004106","register_sub_id":"101","register_pk":"105096","name":"神明社本殿","kana":"しんめいしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26471242,"lng":140.11519139,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"05 － 0108","desc":"子吉川左岸近くの高台に位置し，石積基壇上に建つ。神明造の社殿で，桁行３間（３．４３ｍ）梁間２間（３．４ｍ）規模，切妻造，銅板葺とし，棟に千木と勝男木を上げる。縁は隅を放射状とした切目縁で，縁の端近くまで妻壁から離して棟持柱を建てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004106"},{"id":"00004691","register_sub_id":"101","register_pk":"105681","name":"神明社神輿殿","kana":"しんめいしゃみこしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26485908,"lng":140.11507614,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0120","desc":"神明社本殿の左手前に位置し，参道に正面を見せる。桁行１３尺，梁間１０尺半の木造平屋建，切妻造の妻入で，鉄板葺とする。背面に４尺の下屋がつき，片流屋根をかける。正面に上り段を設け，桟唐戸４枚を建込んでいる。外壁は簓子下見板張である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004691"},{"id":"00004693","register_sub_id":"101","register_pk":"105683","name":"神明社両部鳥居","kana":"しんめいしゃりょうぶとりい","category":"宗教","subcategory":"建築物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県由利本荘市吉沢字上林42","lat":39.26504481,"lng":140.11455962,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、高さ4.0m、幅2.7m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"05 － 0122","desc":"稲荷鳥居から石段を登った位置に建つ木製の鳥居。反りのある笠木と島木，柱上に台輪をもち，両柱の前後に袖柱をもつ両部鳥居の形式である。全高約４ｍ，柱間２．７ｍで，柱高２．４ｍに対して１５ｃｍの内転びを持つ。笠木上に鉄板葺の屋根を載せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004693"},{"id":"00009696","register_sub_id":"101","register_pk":"195525","name":"長谷寺大仏殿","kana":"ちょうこくじだいぶつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県由利本荘市赤田字上田表115","lat":39.42843167,"lng":140.10292335,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"05 － 0194","desc":"高さ約八メートルの十一面観音立像を安置する。宝形造銅板葺で周囲に裳階を廻らし、正面に向拝を付ける。上層の軒を扇垂木として正面に観相窓を穿ち、下層は向拝周りを中心として雲龍や花鳥などの立体的な彫刻で飾る。当地では赤田の大仏として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009696"},{"id":"00012468","register_sub_id":"101","register_pk":"367763","name":"東北聖書バプテスト十文字教会","kana":"とうほくせいしょばぷてすとじゅうもんじきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"秋田県","address":"秋田県横手市十文字町字栄町18-1、19-1","lat":39.223415,"lng":140.522049,"geo_status":"geocoded","era":"昭和24年／昭和51年頃改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"05 － 0220","desc":"東と南を街路に面する角地に東面して建つプロテスタント教会堂。木造平屋建、切妻造妻入の大屋根をかけ、正面大棟上に鐘塔を載せ、正面をモルタル大壁で整える。内部に無柱の均質な礼拝空間をつくる。市街中心部のランドマークとして地域に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012468"},{"id":"00010725","register_sub_id":"101","register_pk":"201560","name":"松ヶ崎八幡神社拝殿・幣殿及び本殿覆屋","kana":"まつがさきはちまんじんじゃはいでん・へいでんおよびほんでんおおいや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県由利本荘市松ヶ崎字宮ノ腰102","lat":39.500441,"lng":140.049843,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"05 ‐ 0208","desc":"切妻造の本殿覆屋と拝殿を幣殿で繋ぎ、権現造風の外観をなす。拝殿は正面に間口の広い一間向拝を付け、内部は格天井の格間に花鳥などの彩画を施す。幣殿内には黒漆塗の四本の円柱で囲む上段の舞殿を設け、格天井に龍を描く。舞殿を内設した独特な形式の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010725"},{"id":"00010724","register_sub_id":"101","register_pk":"201559","name":"松ヶ崎八幡神社本殿","kana":"まつがさきはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市松ヶ崎字宮ノ腰102","lat":39.500566,"lng":140.049821,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"05 ‐ 0207","desc":"覆屋内に建つ三間社流造本殿。軒唐破風付、板葺で三方に縁を廻らし、身舎柱上の出組で妻飾を迫出す。軸部を透漆塗として木理を引立て、虹梁の渦紋に草花を織交ぜる。蟇股や頭貫地紋彫などに花鳥や龍の彫刻類を配して極彩色で荘厳するなど、華やかな意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010724"},{"id":"00008616","register_sub_id":"101","register_pk":"149337","name":"森子大物忌神社拝殿及び幣殿","kana":"もりこおおものいみじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県由利本荘市森子字八乙女下99-1","lat":39.30594292,"lng":140.09532601,"geo_status":"db","era":"安政2年(1855)／大正4年増築・昭和25年・昭和48年改修","year":1855,"year_source":"converted","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0189","desc":"本殿の前方に位置する。桁行3間梁間3間で、背面を2間増築する。入母屋造銅板葺、正面に千鳥破風と軒唐破風付1間向拝を付け、背面に切妻屋根を突出する。円柱で、木鼻付出三斗を組み、中備に蟇股を配する。繋虹梁上に飾られる一対の力士像が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008616"},{"id":"00008615","register_sub_id":"101","register_pk":"149336","name":"森子大物忌神社本殿","kana":"もりこおおものいみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県由利本荘市森子字八乙女下99-1","lat":39.30596255,"lng":140.09516072,"geo_status":"db","era":"大正4年／昭和25年改修","year":1915,"year_source":"converted","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡、渡廊付","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"05 － 0188","desc":"八乙女山の中腹に東面して建つ。3間社流造、銅板葺。周囲に高欄付切目縁をまわす。円柱で三斗組とし、妻は二重虹梁大瓶束。正面中央間に両開桟唐戸を装置し、その前方のみ木階を設け、庇の虹梁を高く架け、雲龍の彫刻を飾る。効果的に彫刻装飾が配されている","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008615"},{"id":"00000944","register_sub_id":"101","register_pk":"101934","name":"旧南照寺千手観音堂","kana":"きゅうなんしょうじせんじゅかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町川島字川島平1918","lat":37.16039207,"lng":139.73921165,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積25㎡","structure_material":"木造平屋建","registered":"1998.12.11(平成10.12.11)","register_no":"07 － 0029","desc":"小規模な妻入の仏堂。もと茅葺で，正面１間分は間口いっぱい向拝部分とし，虹梁や組物等で飾る。正面の屋根のみ唐破風造とする独特の構えになる。屋敷地の奥手にあるが，旧街道から直接見通せる位置に建っており，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000944"},{"id":"00002112","register_sub_id":"101","register_pk":"103102","name":"興國山徳昌寺庫裡","kana":"こうこくざんとくしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町田島字寺前甲2970","lat":37.19595874,"lng":139.77897302,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積297㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0050","desc":"本堂北西に建ち，部材の墨書から文政３年の建立とわかる。南北棟で，南面が入母屋造，北面が切妻造になる。平面は６間取形式で，南側に床・棚付の座敷を配し，北側を土間とする。入口側の北妻面を大きくみせ，高い庇を廻すなど，一般民家と異なる外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002112"},{"id":"00002113","register_sub_id":"101","register_pk":"103103","name":"興國山徳昌寺金毘羅堂","kana":"こうこくざんとくしょうじこんぴらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町田島字寺前甲2970","lat":37.19612373,"lng":139.77920627,"geo_status":"db","era":"安永5","year":1776,"year_source":"db","year_min":1776,"year_max":1776,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0051","desc":"本堂の北東に建つ。堂内にある遷宮銘札より安永５年の建立で，大工は地元田島東町の佐藤忠治とわかる。桁行・梁間とも１０尺強の小規模な３間堂であるが，出桁造として深い軒をつくる。側廻りを角柱，組物を三斗と簡素であるが，つくりは正統的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002113"},{"id":"00002111","register_sub_id":"101","register_pk":"103101","name":"興國山徳昌寺本堂","kana":"こうこくざんとくしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県南会津郡南会津町田島字寺前甲2970","lat":37.19591444,"lng":139.77918819,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積327㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"07 － 0049","desc":"田島町の中心街の南，山裾に位置する曹洞宗寺院。本堂は北面して建ち，大工は越後蒲原郡の源蔵であった。平面は基本的に６室構成で，庫裡に接する北西隅に廊下座敷を設ける。全体的にたちの高い比例で，側廻りの柱も長く，江戸末期の造形をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002111"},{"id":"00002507","register_sub_id":"101","register_pk":"103497","name":"善導寺庫裡","kana":"ぜんどうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県郡山市清水台1-1-23","lat":37.397171,"lng":140.381897,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積282㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"07 － 0062","desc":"本堂北側に廊下で連結して建ち，入母屋造の東妻面を正面とする。東西に細長い建物で，鉄板葺の屋根の南面には明かり窓を設ける。６畳間３室と１０畳間４室を並列させ土間廻りを巧みに合わせた平面で，一部を２階建とするなど，近代の造形が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002507"},{"id":"00010557","register_sub_id":"101","register_pk":"201131","name":"善導寺鐘楼","kana":"ぜんどうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"福島県","address":"福島県郡山市清水台1-163-1","lat":37.39709,"lng":140.382176,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造、瓦葺、面積14㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"07－0161","desc":"浄土宗寺院境内の東方に建つ。桁行三間梁間一間、切妻造本瓦葺で、高欄付の縁を廻らせて二階建風とし、法隆寺鐘楼に類似した形態をもつ。文化財保護委員会技官佐藤登の設計になり、人字割束やエンタシス付の太い円柱などに、古代建築意匠の習熟が窺える鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010557"},{"id":"00002506","register_sub_id":"101","register_pk":"103496","name":"善導寺本堂","kana":"ぜんどうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県郡山市清水台1-1-23","lat":37.396957,"lng":140.381775,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"07 － 0061","desc":"入母屋造・桟瓦葺，正面向拝付の本堂建築。棟札より明治４２年の上棟で，棟梁は帝室技芸員の第９代伊藤平左衛門とわかる。舞良戸を多用した簡素な住宅風の外観構成に比べ，彫刻や欄間で飾って彩色を施した内陣廻りは，当時の造形感覚を顕著に示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002506"},{"id":"00012482","register_sub_id":"101","register_pk":"367777","name":"日本聖公会郡山聖ペテロ聖パウロ教会聖堂","kana":"にっぽんせいこうかいこおりやませいぺてろせいぱうろきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"福島県","address":"福島県郡山市麓山二丁目235","lat":37.39521,"lng":140.36998,"geo_status":"geocoded","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋一部2階建、建築面積210㎡、塔屋付","structure_material":"鉄筋コンクリート造平屋一部2階建","registered":"2018.11.02(平成30.11.02)","register_no":"07 － 0197","desc":"市中心部の高台に建つ。鉄筋コンクリート造、東西棟の切妻造で、北面東端に切妻造の玄関、西端に塔屋を突出する。塔屋隅部やバットレスに柱形を表す外観、シザーズトラスとアーチ梁を併用した小屋組など優れたゴシック意匠をみせる教会建築。設計は上林敬吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012482"},{"id":"00001655","register_sub_id":"101","register_pk":"102645","name":"日本基督教団若松栄町教会","kana":"にほんきりすときょうだんわかまつさかえまちきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"福島県","address":"福島県会津若松市西栄町8-36","lat":37.494644,"lng":139.92601,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積208㎡、塔屋付","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"07 － 0039","desc":"木造下見板張りのゴシック式教会堂で、会堂部の外郭はラテン十字を描く。ヴォーリズ設計の福島教会を手本としたと伝えられ、４５度振った玄関部に尖塔付きの角塔をたちあげる。礼拝堂内のタイバーを用いた架構も時代性をよく示しており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001655"},{"id":"00014732","register_sub_id":"101","register_pk":"518990","name":"無能寺山門","kana":"むのうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"福島県","address":"福島県伊達郡桑折町字上町4-2","lat":37.85014444,"lng":140.51776389,"geo_status":"db","era":"元治元年(1864)","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造、瓦葺、間口3.6m、袖塀付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"07 - 0283","desc":"桑折宿に位置する浄土宗寺院の薬医門。参道を西進した境内入口に東面して建つ切妻造桟瓦葺で木太い本柱、控柱の頂部を各々冠木で固める。梁を四筋架け、梁先の大斗実肘木で桁を受け、冠木と桁の間に支輪を設ける。ケヤキの良材を使い、雄大な構えの山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014732"},{"id":"00000559","register_sub_id":"101","register_pk":"101549","name":"上杉神社稽照殿","kana":"うえすぎじんじゃけいしょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"山形県","address":"山形県米沢市丸の内1-4-13","lat":37.90963534,"lng":140.1044605,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造２階建，銅板葺，建築面積149㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1998.07.23(平成10.07.23)","register_no":"06 － 0027","desc":"上杉神社再興時に建築された宝物殿で，設計は伊東忠太の手になると伝える。鉄筋コンクリート造で和風の外観を比較的忠実に再現しており，全体を２層の銅板葺きとし，２階には高欄を廻す。数多くの上杉家由来の品を納める宝物殿として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000559"},{"id":"00009886","register_sub_id":"101","register_pk":"196033","name":"熊野神社拝殿","kana":"くまのじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県村山市大字湯野沢字院内2680-1","lat":38.47930197,"lng":140.29450609,"geo_status":"db","era":"江戸中期／江戸後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"06 － 0147","desc":"本殿前面に建つ方三間の拝殿で、入母屋造鉄板葺、正面一間向拝付とし、四周に切目縁を廻らせる。中央間後寄りの方一間を上段の内陣とし、外陣は虹梁で柱を省く。木鼻形状などの細部意匠に地方的特色を示すとともに、当地方における熊野信仰の様態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009886"},{"id":"00009885","register_sub_id":"101","register_pk":"196032","name":"熊野神社本殿","kana":"くまのじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県村山市大字湯野沢字院内2680-1","lat":38.47934141,"lng":140.29437297,"geo_status":"db","era":"明治14","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"06 － 0146","desc":"山中の境内最奥部に東面して建つ。一間社流造、鉄板葺で、四周に縁高欄を廻らし、正面に浜床と階を設ける。身舎柱に出組をのせ、妻飾は二重虹梁とする。海老虹梁持送や庇の手挟、蟇股、桁隠など各部材を、四神や花鳥を主題とした精緻な彫刻で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009885"},{"id":"00002503","register_sub_id":"101","register_pk":"103493","name":"清風荘（旧宝幢寺書院）","kana":"せいふうそう（きゅうほうどうじしょいん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県山形市東原町2-16-7","lat":38.24563055,"lng":140.34457155,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"06 － 0039","desc":"当地にあった真言宗の巨刹宝幢寺の書院で，北側の池泉回遊式庭園を臨むように建つ。片入母屋の屋根を架けた簡素な外観であるが，内部は高い格式を示す上段の間に端正な床・棚・付書院を設け，用材も吟味されており，上質な書院造の遺構になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002503"},{"id":"00010731","register_sub_id":"101","register_pk":"201566","name":"善寳寺五重塔","kana":"ぜんぽうじごじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772216,"lng":139.767939,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造五重塔、銅板葺、建築面積30㎡","structure_material":"木造五重塔","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0166","desc":"参道の南、五百羅漢堂に相対して建つ。三間五重塔婆、瓦棒銅板葺で、組物は尾垂木付三手先とする。和様を基調としつつ、五重軒のみ扇垂木とする。初重中備に十二神将などの透彫、各重の高欄腰組に蟇股を飾る。均整のとれた塔姿に装飾性を備えた、近代の五重塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010731"},{"id":"00010729","register_sub_id":"101","register_pk":"201564","name":"善寳寺五百羅漢堂","kana":"ぜんぽうじごひゃくらかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772729,"lng":139.768125,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0164","desc":"総門と山門を結ぶ参道に南面して建つ。桁行五間梁間四間、軒は二手先で中備に彫刻や蟇股を付す。内部は奥の仏壇前を通路として左右に雛段状の仏壇を置き、側面から背面の壁際にも仏壇を設けて多数の羅漢像を祀り、参詣者の便を図る。羅漢信仰の様相を示す堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010729"},{"id":"00010732","register_sub_id":"101","register_pk":"201567","name":"善寳寺山門","kana":"ぜんぽうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772544,"lng":139.767939,"geo_status":"db","era":"慶応3","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、銅板葺、建築面積38㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0167","desc":"参道奥に建つ三間一戸二階二重門。入母屋造瓦棒銅板葺で、正背面に軒唐破風と千鳥破風を付す。組物は三手先で、初重は詰組で軒を平行垂木、二重は中備を蟇股として軒を扇垂木とする。虹梁や小壁に施した波紋などの浮彫、獅子鼻など随所を華やかな彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010732"},{"id":"00010733","register_sub_id":"101","register_pk":"201568","name":"善寳寺総門","kana":"ぜんぽうじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772468,"lng":139.768205,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0168","desc":"山門前面の参道に建つ、間口三・三メートルの四脚門。切妻造桟瓦葺で左右の袖塀に潜戸を付し、組物を出組として、桁や妻虹梁を持出す。木鼻や虹梁絵様をはじめ、蟇股や琵琶板なども波や動植物を主題とした立体的な彫刻で装飾し、彫刻大工の高い技術力を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010733"},{"id":"00010728","register_sub_id":"101","register_pk":"201563","name":"善寳寺龍王殿","kana":"ぜんぽうじりゅうおうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772884,"lng":139.766797,"geo_status":"db","era":"天保4／昭和後期改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0163","desc":"伽藍最奥の本堂背面の小高い地に建つ。龍王殿と開山堂を並べ、間に有栖川宮家の霊牌所をつくる独特な平面を持つ。屋根は入母屋造茅葺形銅板葺で、正面に軒唐破風付の向拝と千鳥破風を二連付し、内外とも彫刻や彩画で飾るなど特異な構成と華やかな意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010728"},{"id":"00010730","register_sub_id":"101","register_pk":"201565","name":"善寳寺龍華庵","kana":"ぜんぽうじりゅうげあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県鶴岡市下川字関根100-1","lat":38.772525,"lng":139.768715,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0165","desc":"参道入口北側に南面して建つ。桁行五間梁間四間で正面に向拝を付す。内部は正面一間通りと中央列の三室、奥一間通りに虹梁で分割し、背面に仏壇を張出す。仏壇前の板敷の他は畳敷とする。彫物は控え目だが、中央間鏡天井の雲龍画など要所に華やかさを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010730"},{"id":"00009125","register_sub_id":"101","register_pk":"164678","name":"鳥海山大物忌神社吹浦口ノ宮後神門及び玉垣","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやうしろしんもんおよびたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07526766,"lng":139.8788995,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"後神門 木造、銅板葺、間口2.4m 玉垣 木造、銅板葺、総延長51m","structure_material":"後神門 木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿と摂社月山神社本殿の側面と背面を総延長51メートルの玉垣が囲繞し、背面中央に後神門を構え、神域を区画する。門は一間腕木門で、切妻造銅板葺。角柱を貫で固め、舟肘木で受けた腕木で桁を持出し、一軒疎垂木を配る。両開戸を吊り、貫上に横連子を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009125"},{"id":"00009127","register_sub_id":"101","register_pk":"164680","name":"鳥海山大物忌神社吹浦口ノ宮下拝殿","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやしたはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07434324,"lng":139.87884715,"geo_status":"db","era":"明治12年","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内の最下段に位置し、桁行7間梁間5間、入母屋造銅板葺で、正面に3間向拝を付け、軒をせがいで持出す。内部は中央後方の桁行3間梁間2間を上段として格天井を張り、背面の突出部に宮殿を祀る。特徴的な内部空間をもつ広壮な拝殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009127"},{"id":"00009123","register_sub_id":"101","register_pk":"164676","name":"鳥海山大物忌神社吹浦口ノ宮摂社月山神社本殿","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやせっしゃつきやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07521293,"lng":139.87884001,"geo_status":"db","era":"宝永8年(1711)頃／昭和38年改修","year":1711,"year_source":"db","year_min":1711,"year_max":1711,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿西に並び建ち、一間社流造銅板葺。身舎は円柱、組物連三斗、中備蟇股、二軒繁垂木。本殿と同規模同形式の社殿であるが、脇障子や蟇股、正面の琵琶板、懸魚などの彫刻が異なる。妻飾に加え、繰りの小さい肘木や虹梁絵様など、細部にも独自性が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009123"},{"id":"00009124","register_sub_id":"101","register_pk":"164677","name":"鳥海山大物忌神社吹浦口ノ宮中門及び廻廊","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやちゅうもんおよびかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07515701,"lng":139.8788995,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿と摂社月山神社本殿の前方に位置する。登廊上端に接して妻入の中門を開き、その東西に桁行5間の廻廊が延び、両端間を神饌所として間仕切る。いずれも切妻造銅板葺、角柱で舟肘木を載せ、一軒疎垂木、妻豕扠首。端正な外観を構成し、静謐な空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009124"},{"id":"00009126","register_sub_id":"101","register_pk":"164679","name":"鳥海山大物忌神社吹浦口ノ宮拝殿及び登廊","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやはいでんおよびのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07503804,"lng":139.87889712,"geo_status":"db","era":"昭和18年／平成2年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積116㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本殿と月山神社本殿の中央前方、1段低い位置に建つ。桁行5間梁間3間、入母屋造銅板葺で、正面に1間向拝、背面には方1間の突出を設け、中門への登廊を付ける。円柱で組物は大斗肘木。正面中央3間に板唐戸を吊り、両脇間を連子窓とする。厳粛な佇まいの拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009126"},{"id":"00009122","register_sub_id":"101","register_pk":"164675","name":"鳥海山大物忌神社吹浦口ノ宮本殿","kana":"ちょうかいざんおおものいみじんじゃふくらくちのみやほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町吹浦字布倉1","lat":39.07521412,"lng":139.8789685,"geo_status":"db","era":"宝永8年(1711)頃／昭和38年改修","year":1711,"year_source":"db","year_min":1711,"year_max":1711,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"鳥海山の西方、小高い山の南斜面に占める境内の北奥に南面して建つ中規模の本殿で、一間社流造銅板葺である。身舎は円柱上に連三斗を組み、中備に蟇股を飾る。妻飾は、虹梁上に巻斗と通肘木を2段積上げ、その上に笈形付大瓶束を立てる、特異な形式をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009122"},{"id":"00006704","register_sub_id":"101","register_pk":"107687","name":"鳥海山大物忌神社蕨岡口ノ宮神楽殿","kana":"ちょうかいさんおおものいみじんじゃわらびおかのみやかぐらでん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","lat":38.99643642,"lng":139.94395342,"geo_status":"db","era":"江戸後期／明治初期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"06 － 0090","desc":"西面する境内地の入口から、やや奥の南側に建つ。鐘楼として建立され、神仏分離の際に神楽殿に改められた。南北棟の入母屋造鉄板葺、内転びのある粽付円柱で、吹寄支輪付の出組とし、軒は一軒繁垂木。高欄付の板床で、格天井を張る。歴史的な変遷を物語る遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006704"},{"id":"00006444","register_sub_id":"101","register_pk":"107427","name":"鳥海山大物忌神社蕨岡口ノ宮随神門","kana":"ちょうかいさんおおものいみじんじゃわらびおかのみやずいしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","lat":38.99642528,"lng":139.94359174,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"06 － 0089","desc":"西面する３間１戸八脚門で、切妻造鉄板葺とする。両脇前寄り１間に床を張り、金剛柵をたてる。円柱で、柱上出組とし、中備に蟇股を入れる。軒は二軒繁垂木。妻は二重虹梁大瓶束とし、前方へ持ち出す。伝統的な手法で手固くまとめられた端正な八脚門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006444"},{"id":"00006443","register_sub_id":"101","register_pk":"107426","name":"鳥海山大物忌神社蕨岡口ノ宮本殿","kana":"ちょうかいさんおおものいみじんじゃわらびおかのみやほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡51","lat":38.996952,"lng":139.943863,"geo_status":"db","era":"明治29／昭和28移築","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"06 － 0088","desc":"桁行３間、梁間６間で、切妻造銅板葺とし、１間向拝を付ける。正面が実長で１３．８ｍに及ぶ大型の社殿で、内部は外陣と内陣に分かれ、さらに内々陣を造る。絵様や装飾的要素は少ないが、木割が大きく、直線的意匠でまとめた、壮大な社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006443"},{"id":"00002738","register_sub_id":"101","register_pk":"103728","name":"明善寺本堂","kana":"みょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"山形県","address":"山形県山形市七日町5-9-3","lat":38.249786,"lng":140.341492,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積327㎡、正面左右塔屋付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0046","desc":"伊東忠太の設計による。内部は前半部を６０畳敷の大広間とし，後半部は中央に内陣を設け，両脇を餘間とし，左奥に書院間を張り出している。正面両脇に鐘楼・鼓楼を設け，向拝と入母屋の妻面を重ねて見せる立面に，伊東の作風が良く表れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002738"},{"id":"00002739","register_sub_id":"101","register_pk":"103729","name":"山形聖ペテロ教会礼拝堂","kana":"やまがたせいぺてろきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"山形県","address":"山形県山形市木の実町9-22","lat":38.25287845,"lng":140.33422497,"geo_status":"db","era":"明治43頃","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積187㎡、塔屋付","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"06 － 0047","desc":"山形市街の中心部に位置する木造の教会堂。屋根勾配が急な切妻造で，北妻西側に塔屋を設けている。外壁は下見板張で，窓のほとんどを尖塔アーチ型とするのが特徴。小規模ではあるが，外壁立面，内部のトラス架構など意匠を凝らした建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002739"},{"id":"00010735","register_sub_id":"101","register_pk":"201570","name":"龍頭寺開山堂","kana":"りゅうとうじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡45","lat":38.996242,"lng":139.944123,"geo_status":"db","era":"昭和8／昭和30頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0170","desc":"本堂の背面北寄りに建つ。切妻造平屋建で内部は一室とし、正面と南側面に位牌棚を設ける。外観は妻壁の梁と束組を見せ、壁は下見板張と簡素だが、内部は漆塗を多用し、奥の位牌壇上部欄間には天女や菊、牡丹などの鏝絵を施すなど、凝った意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010735"},{"id":"00010736","register_sub_id":"101","register_pk":"201571","name":"龍頭寺観音堂","kana":"りゅうとうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡45","lat":38.996174,"lng":139.943998,"geo_status":"db","era":"明治8頃","year":1875,"year_source":"db","year_min":1875,"year_max":1875,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0171","desc":"本堂の正面北寄りに建つ。土蔵造、切妻造妻入、桟瓦葺で正面に向拝を付し、東に物置を附属する。腰は海鼠壁とする。内部は正面一間を土間とする他は板間で、奥に仏壇を置き、中央に大柄な観音像を祀る。向拝虹梁廻りの龍を巻付けた彫刻は立体的で秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010736"},{"id":"00010734","register_sub_id":"101","register_pk":"201569","name":"龍頭寺本堂","kana":"りゅうとうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"山形県","address":"山形県飽海郡遊佐町上蕨岡字松ヶ岡45","lat":38.996135,"lng":139.944135,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積316㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"06 ‐ 0169","desc":"敷地中央に西面する。桁行一三間半梁間六間半、入母屋造銅板葺で正面に唐破風玄関を付す。北半を六間取方丈形式の本堂として内陣北に上段の間を設け、南寄りは土間を持つ庫裏とする。柱が太く内外陣廻りや縁上部の虹梁が目を引く、鳥海修験の遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010734"},{"id":"00009897","register_sub_id":"101","register_pk":"196044","name":"足尾キリスト教会","kana":"あしおきりすときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県日光市足尾町赤沢2525","lat":36.63940162,"lng":139.44381014,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"09 － 0214","desc":"足尾銅山の玄関口であった通洞地区の東側、赤沢地区に位置する。南正面の中ほどに玄関を設け、西側を一室の会堂とし、東側を牧師の居住空間とする。足尾で初めての本格的な教会堂であるとともに唯一の現存例であり、当時の銅山従事者の信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009897"},{"id":"00004123","register_sub_id":"101","register_pk":"105113","name":"織姫神社神楽殿","kana":"おりひめじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33909217,"lng":139.44463459,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0110","desc":"社殿地に上がる大階段前の西方に位置する。桁行６．２ｍ梁間３．８ｍ，東西棟，入母屋造，銅板葺の木造平屋建で，低い亀腹上に建つ。軒は一軒疎垂木とし，舟肘木で桁を受け，刎高欄を廻す。小林福太郎設計で，社務所とともに社殿地の下の平地の主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004123"},{"id":"00004122","register_sub_id":"101","register_pk":"105112","name":"織姫神社社殿","kana":"おりひめじんじゃしゃでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33922834,"lng":139.44493583,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積140㎡、本殿透塀折曲り延長29メートル付","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0109","desc":"両崖山南斜面の中腹に石積基壇を築き社殿地とする。正面中央に入母屋造，千鳥破風付きの拝殿を置き，その両側に神輿舎と神饌所，背後に両下造の幣殿，向拝と切妻造の本殿を配する。垂木より上を木造とした鉄筋コンクリート造神社建築で，小林福太郎の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004122"},{"id":"00004124","register_sub_id":"101","register_pk":"105114","name":"織姫神社社務所","kana":"おりひめじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33893355,"lng":139.44457048,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建一部地階付、銅板葺、建築面積102㎡","structure_material":"木造平屋建一部地階付","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0111","desc":"神楽殿の南に建ち，渡廊で繋がる。桁行６間半規模の入母屋造，銅板葺で，東面中央に唐破風車寄を突出して式台玄関を設け，南面西側に床棚付き８畳座敷を配する。崖際のため一部鉄筋コンクリート造地階付きで南面及び西面を２階建に見せる。設計は小林福太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004124"},{"id":"00004125","register_sub_id":"101","register_pk":"105115","name":"織姫神社手水舎","kana":"おりひめじんじゃちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町3889","lat":36.33876652,"lng":139.44461886,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積1.4㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0112","desc":"表参道石段の中途，神楽殿・社務所より一段低い平地に建つ。桁行１．９７ｍ梁間０．７ｍ規模，南北棟，切妻造，銅板葺で，社殿と同様，鉄筋コンクリート造で垂木以上を木造とする。神楽殿や社務所とともに，小林福太郎の設計による境内計画の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004125"},{"id":"00000945","register_sub_id":"101","register_pk":"101935","name":"カトリック松が峰教会","kana":"かとりっくまつがみねきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県宇都宮市松が峰1-1-5","lat":36.5581424,"lng":139.88138783,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造４階建塔屋付，銅板葺，建築面積404㎡","structure_material":"鉄筋コンクリート造４階建塔屋付","registered":"1998.12.11(平成10.12.11)","register_no":"09 － 0013","desc":"大谷石を貼った鉄筋コンクリート造教会堂。階上を聖堂に充てる。両サイドから聖堂にアプローチする正面階段と，八角トンガリ屋根を頂く双塔が荘重な外観を造る。ランドマークとしてもよく知られる。設計は，横浜在住のスイス人建築家マックス・ヒンデル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000945"},{"id":"00014564","register_sub_id":"101","register_pk":"515106","name":"唐澤山神社神楽殿","kana":"からさわやまじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県佐野市栃本町字唐沢山3598-2","lat":36.35378333,"lng":139.599975,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、銅板葺、建築面積21㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0269","desc":"史跡唐沢山城跡二の丸に位置する神楽殿。入母屋造妻入銅板葺、二軒繁垂木、組物舟肘木。繰形付持送で三方切目縁脇障子付とし、擬宝珠高欄を巡らす。内部は三方蔀戸、格天井で奥に神棚付の舞台と、後座に分かれる。祭礼空間として境内の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014564"},{"id":"00014563","register_sub_id":"101","register_pk":"515105","name":"唐澤山神社参拝門","kana":"からさわやまじんじゃさんぱいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35359444,"lng":139.60074444,"geo_status":"db","era":"明治16年／明治41年頃移築","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0268","desc":"神社創建に際して唐沢山山頂に御霊代上屋と共に建てた社殿。切妻造平入銅板葺、二軒繁垂木、正面吹放ち、側面及び背面両脇間を板壁として、背面中央に板扉を吊る。床は四半石敷。当初は門と拝殿を兼ねた役割で、柱は節が多く、創建時の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014563"},{"id":"00014565","register_sub_id":"101","register_pk":"515107","name":"唐澤山神社神橋","kana":"からさわやまじんじゃしんきょう","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3","lat":36.35363889,"lng":139.59909167,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート橋、延長5.0m、幅員3.7m","structure_material":"鉄筋コンクリート橋","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0270","desc":"史跡唐沢山城跡三の丸西方にある四ツ目堀に架かる鉄筋コンクリート造単桁橋。橋長４・６メートル。堀法面に切石積橋台を築き、緩いアーチ形の橋桁を架けて床版を載せる。擬宝珠欄干は御影石で作り、伝統的な石橋風意匠とする近代構法の橋で歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014565"},{"id":"00014562","register_sub_id":"101","register_pk":"515104","name":"唐澤山神社中門祝詞屋及び透塀","kana":"からさわやまじんじゃちゅうもんのりとやおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35383889,"lng":139.60077778,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"中門祝詞屋 木造、銅板葺、間口2.8m 透塀 木造、銅板葺、総延長52m","structure_material":"中門祝詞屋 木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0267","desc":"明治期別格官幣社の本殿を囲む透塀と正面に位置する中門祝詞屋で制限図式の配置。中門祝詞屋は起り付の切妻造妻入銅板葺。透塀は銅板葺で東西に石段と扉を設ける。彫刻は中備蟇股に留めるが、門扉と透塀は菱格子で透かし、腰板にも襷桟を付して優雅な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014562"},{"id":"00014561","register_sub_id":"101","register_pk":"515103","name":"唐澤山神社拝殿","kana":"からさわやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35374722,"lng":139.60073333,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、銅板葺、建築面積42㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0266","desc":"明治期別格官幣社の拝殿。本殿を囲む透塀の外に位置する。入母屋造銅板葺、二軒疎垂木で隅の軒反り優雅。吹寄格天井として、正背面中央間に板扉を立てる他は蔀戸で四方に開放的で縁を巡らす。組物は舟肘木で簡素ながら端正な造りで制限図式の影響を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014561"},{"id":"00014560","register_sub_id":"101","register_pk":"515102","name":"唐澤山神社本殿","kana":"からさわやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"栃木県","address":"栃木県佐野市富士町字富士山1409-3他","lat":36.35393889,"lng":139.60080278,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、銅板葺、建築面積5.1㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"09 - 0265","desc":"史跡唐沢山城跡の本丸に所在する明治期別格官幣社の本殿。一間社流造銅板葺、二軒繁垂木、組物舟肘木とし、前方への屋根の流れが大きく緩やか。四方に切目縁と刎高欄を巡らし浜縁付。菊紋の金具等を除けば装飾は簡素だが、木柄太く制限図式の影響が明らか。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014560"},{"id":"00012291","register_sub_id":"101","register_pk":"531615","name":"旧東照宮宝物館","kana":"きゅうとうしょうぐうほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和後","pref":"栃木県","address":"栃木県日光市山内2281-3","lat":36.75634444,"lng":139.59800556,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"鉄筋コンクリート造2階建地下1階、銅板葺、建築面積958㎡","structure_material":"鉄筋コンクリート造2階建地下1階","registered":"2018.05.10(平成30.05.10)","register_no":"09-244","desc":"日光山内に建つ鉄筋コンクリート造のもと博物館で、設計は岸田日出刀による。一階を執務、二階を展示の空間にあて、周囲に高欄付テラスを廻し正面中央に大階段を設ける。板葺風の緩勾配屋根や壁外に出した梁など、伝統表現が特徴的なモダニズム建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012291"},{"id":"00015002","register_sub_id":"101","register_pk":"529280","name":"桜町二宮神社拝殿及び幣殿","kana":"さくらまちにのみやじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県真岡市物井字東峰高2013-2","lat":36.40796944,"lng":140.01546389,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"09 - 0277","desc":"本殿南の基壇上に建つ拝殿及び幣殿。拝殿は入母屋造銅板葺、正面に一間向拝と千鳥破風を付し、背面に切妻造銅板葺の幣殿を突出する。拝殿は三方に刎高欄付縁を廻らし脇障子を建てる。内部は一室の畳敷で格天井を張る。全体に質実なつくりとした拝殿及び幣殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015002"},{"id":"00015001","register_sub_id":"101","register_pk":"529279","name":"桜町二宮神社本殿","kana":"さくらまちにのみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県真岡市物井字東峰高2013-2","lat":36.40808611,"lng":140.0155,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"09 - 0276","desc":"二宮尊徳没後八十年を記念し、史跡桜町陣屋跡東方に建立した神社本殿。覆屋内の基壇上に南面して建つ一間社流造銅板葺で、三方に刎高欄付縁を廻らし脇障子を建て、正面に木階を付す。円柱に三斗を組み、妻飾は豕扠首とする。装飾を抑えた質実なつくりの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015001"},{"id":"00004121","register_sub_id":"101","register_pk":"105111","name":"長林寺開山堂","kana":"ちょうりんじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町2884","lat":36.34234528,"lng":139.44426786,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積23㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0108","desc":"本堂の背後に建つ。方１５尺の北面に３尺の張出を設けた平面に銅板葺の宝形屋根を架ける。奥正面の張出部を開祖殿とし，屋根北面に天窓を開け，東西壁面上部に引き違い窓を設ける。本堂と同様に小林福太郎の設計による鉄筋コンクリート造の近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004121"},{"id":"00004120","register_sub_id":"101","register_pk":"105110","name":"長林寺本堂","kana":"ちょうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県足利市西宮町2884","lat":36.34227317,"lng":139.44417997,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積153㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"09 － 0107","desc":"鉄筋コンクリート造による寺院建築の好例。設計は小林福太郎。桁行５間梁間４間，寄棟造，青緑釉薬瓦の本瓦葺本堂で，外部側柱を胴張付き円柱，入側柱を六角柱とし，一軒繁垂木や出三斗組，内部の虹梁や天井化粧垂木の手挟等も鉄筋コンクリートで造り上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004120"},{"id":"00004522","register_sub_id":"101","register_pk":"105512","name":"東照宮武徳殿","kana":"とうしょうぐうぶとくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"栃木県","address":"栃木県日光市山内2301","lat":36.75613,"lng":139.600708,"geo_status":"db","era":"大正4／昭和6増改造","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積353㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"09 － 0120","desc":"徳川家康三百年大遠忌に際し，参拝人休憩所として建設。当初は桁行７間梁間４間，土間床の堂で，設計は大江新太郎。改修時に柱を根継して基壇を嵩上げし，四周に裳階を付すとともに内部は床を張り，内法長押を加える。日光における近代和風建築の一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004522"},{"id":"00003058","register_sub_id":"101","register_pk":"104048","name":"日本キリスト教団佐野教会","kana":"にほんきりすときょうだんさのきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"栃木県","address":"栃木県佐野市金屋仲町2431","lat":36.31116441,"lng":139.57780669,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積129㎡、塔屋付","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"09 － 0063","desc":"佐野駅南方に位置する。木造二階建，切妻造とし，主体部と屋根勾配を揃えた塔屋を棟の前方に設ける。外装は下見板張で，正面にバラ窓風の丸窓と尖頭アーチの開口部を左右対称に配し，全体的にゴシック風の造りとしながらも，内部の柱に大斗風の桁受を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003058"},{"id":"00013044","register_sub_id":"101","register_pk":"368350","name":"乃木神社拝殿","kana":"のぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県那須塩原市石林字狩野道上793-2","lat":36.88755278,"lng":140.00278889,"geo_status":"db","era":"大正4年／昭和12年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0251","desc":"背面の本殿との間に幣殿を置き、南面して建つ。桁行五間、梁間三間、切妻造平入銅板葺で、柱間装置を設けない開放的なつくり。太い円柱を並べ長押を廻し、組物は置かない。千木や鞭掛のなどに神明造の細部を取入れた簡明な外観で、静謐な社頭景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013044"},{"id":"00013043","register_sub_id":"101","register_pk":"368349","name":"乃木神社本殿","kana":"のぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"栃木県","address":"栃木県那須塩原市石林字狩野道上793-2","lat":36.88767222,"lng":140.00293889,"geo_status":"db","era":"大正4年／昭和12年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"09 － 0250","desc":"那須塩原市域南東にある乃木希典夫妻を祀る神社。本殿は敷地北奥に南面して建つ、切妻造妻入銅板葺で、直線的な構成で端正な外観をもつ社殿。住吉大社本殿に類似した形式とする一方で、千木の形式を神明造風とするなど、近代らしい自由な構成の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013043"},{"id":"00005249","register_sub_id":"101","register_pk":"106237","name":"一宮家住宅（般若坊）主屋","kana":"いちのみやけじゅうたく（はんにゃぼう）しゅおく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町164","lat":36.45337149,"lng":138.84907355,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部2階建、瓦葺、建築面積650㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0153","desc":"榛名神社の社家町にあり，参道東側の敷地中央に東西棟の宿坊が位置し，南へ折れた南北棟に玄関と台所を配す。東側には２階建の居住部分が接続する。宿坊は棟通りの廊下の両側に８畳または６畳の客室を配し，縁を巡らす。屋根は切妻造，桟瓦葺である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005249"},{"id":"00005250","register_sub_id":"101","register_pk":"106238","name":"一宮家住宅（般若坊）長屋門","kana":"いちのみやけじゅうたく（はんにゃぼう）ながやもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町164","lat":36.45342794,"lng":138.84893475,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0154","desc":"敷地南西隅，参道に西面する桁行６間，梁間２間の長屋門で，北半を門，南半を門番室とする。門番室の東面に桁行３間，梁間２間の土間を付ける。屋根は鉄板平葺で，外壁は真壁造，白漆喰塗で，腰は押縁下見板張とする。社家町の参道の景観を形成し貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005250"},{"id":"00005251","register_sub_id":"101","register_pk":"106239","name":"門倉家住宅（善徳坊）主屋","kana":"かどくらけじゅうたく（ぜんとくぼう）しゅおく","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町176","lat":36.45377696,"lng":138.84957734,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、鉄板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0155","desc":"榛名神社の社家町の住宅を兼ねる宿坊で，参道に西面して建つ間口６間半，奥行４間半の切妻造，鉄板瓦棒葺，平入で，東面南寄りに台所を後方に突き出す。正面中央に式台玄関を備え，南西隅に土間を設ける。小規模ながら同地区最古の宿坊遺構と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005251"},{"id":"00000524","register_sub_id":"101","register_pk":"101514","name":"旧日本基督教団沼田教会紀念会堂","kana":"きゅうにほんきりすときょうだんぬまたきょうかいきねんかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県沼田市都市計画事業沼田市中心市街地土地区画整理事業２－３街区１１５８－２、１１５９－１","lat":36.64495,"lng":139.04760278,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造２階建，スレート葺，建築面積112㎡","structure_material":"木造２階建","registered":"1998.04.21(平成10.04.21)","register_no":"10 － 0026","desc":"生糸貿易で栄えた星野家の寄附によって建てられた会堂を美術館として再利用した建物。市内で数少ない大正期の洋風建築で，外壁の下見板，縦長の上下窓，急勾配の屋根等にその特徴がよくあらわれている。設計・施工は埼玉県和戸町出身の大工小菅幸之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000524"},{"id":"00001039","register_sub_id":"101","register_pk":"102029","name":"光恩寺石蔵","kana":"こうおんじいしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"群馬県","address":"群馬県邑楽郡千代田町大字赤岩甲1041","lat":36.20824974,"lng":139.43982192,"geo_status":"db","era":"昭和8頃","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"石造二階建，瓦葺，建築面積40㎡","structure_material":"石造二階建","registered":"1999.02.17(平成11.02.17)","register_no":"10 － 0038","desc":"客殿の東方に位置し，客殿の妻面に接して建つ。大谷石を用いた２階建，東西棟，平入の石蔵で，南面に半間程度の瓦葺の庇をさしかけて蔵前とし，２階南面にふたつの小庇付き窓を穿つ。庫裏・客殿とともに寺の奥向き部を構成する主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001039"},{"id":"00001038","register_sub_id":"101","register_pk":"102028","name":"光恩寺客殿","kana":"こうおんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県邑楽郡千代田町大字赤岩甲1041","lat":36.20829089,"lng":139.43976157,"geo_status":"db","era":"明治時代後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治時代後期","structure":"木造平屋建，瓦葺，建築面積62㎡","structure_material":"木造平屋建","registered":"1999.02.17(平成11.02.17)","register_no":"10 － 0037","desc":"長屋門を入って突き当たりに位置する。庫裏の北東端に接続する平屋建，瓦葺，切妻造，東西棟の建物で，山を背にし，南前面に庭園を造る。南面の庭園側に縁側を張り出した上質な造りの離れ座敷になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001038"},{"id":"00003813","register_sub_id":"101","register_pk":"104803","name":"正田醤油地内稲荷神社","kana":"しょうだしょうゆちないいなりじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県館林市栄町3-1","lat":36.24760569,"lng":139.52552634,"geo_status":"db","era":"江戸末期／平成14移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"10 － 0111","desc":"八号蔵の南方に位置する。桁行３間梁間２間，東西棟，切妻造，妻入の本殿の前方に，桁行３間梁間２間，南北棟，切妻造，向拝付，平入の拝殿を配した社殿。醸造場敷地内に取込まれているが，地元地区の稲荷として現在も近隣住民から親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003813"},{"id":"00005253","register_sub_id":"101","register_pk":"106241","name":"鐸木家住宅（本坊）門","kana":"たくきけじゅうたく（ほんぼう）もん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"群馬県","address":"群馬県高崎市榛名山町183","lat":36.45387387,"lng":138.85022476,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、銅板葺、間口3.0m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"10 － 0157","desc":"榛名神社二之鳥居から東へ石段を登った高台の敷地西端に建つ。薬医門の形式で本柱の柱間１０尺，本柱と控え柱の間は７尺とする。控え柱の上に大斗と実肘木を組み，虹梁をあげて梁を受ける。屋根は切妻造で銅板葺である。南側に脇門が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005253"},{"id":"00004331","register_sub_id":"101","register_pk":"105321","name":"日本基督教団安中教会温古亭（旧牧師館）","kana":"にほんきりすときょうだんあんなかきょうかいおんこてい（きゅうぼくしかん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県安中市安中3-19-10","lat":36.32925479,"lng":138.89803942,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0120","desc":"牧師館として建設。教会堂とは道を隔てた南側の敷地に東西棟で建つ。切妻造，桟瓦葺の木造平屋建で，もと安中藩家老屋敷の一部と伝える８畳と１０畳の座敷を核とし，東側に玄関と台所など，西側に４畳半の和室を配し，座敷南面には半間幅の縁を付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004331"},{"id":"00004332","register_sub_id":"101","register_pk":"105322","name":"日本基督教団安中教会義圓亭（旧柏木義圓書斎）","kana":"にほんきりすときょうだんあんなかきょうかいぎえんてい（きゅうかしわぎぎえんしょさい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県安中市安中3-19-10","lat":36.32933969,"lng":138.89788562,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0121","desc":"温古亭の北西に位置。桁行２間梁間３間，切妻造，鉄板葺の木造平屋建で，６畳２室の西側に下屋を差し掛けて土間と便所に充て，南面東端に玄関を設ける。真壁造の簡素な建物であるが，たちが高いのが特徴で，開口部が多く，高窓もあり書斎に相応しいつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004332"},{"id":"00004330","register_sub_id":"101","register_pk":"105320","name":"日本基督教団安中教会教会堂（新島襄記念会堂）","kana":"にほんきりすときょうだんあんなかきょうかいきょうかいどう（にいじまじょうきねんかいどう）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"群馬県","address":"群馬県安中市安中3-10-33","lat":36.32959083,"lng":138.89766376,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造平屋一部2階建、銅板葺、建築面積171㎡、鐘塔付","structure_material":"石造平屋一部2階建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0119","desc":"東を正面とした大谷石造のロマネスク会堂で，東南隅部に角形鐘塔を建て，外壁に控壁を付ける。内部は単廊であるが，天井は板張りで，中央をヴォールト状にして三廊式の扱いとし，アプス両脇にはコンポジット式の大理石円柱を建てる。設計は古橋柳太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004330"},{"id":"00004333","register_sub_id":"101","register_pk":"105323","name":"日本基督教団安中教会宣教師館（旧ベーケン邸）","kana":"にほんきりすときょうだんあんなかきょうかいせんきょうしかん（きゅうべーけんてい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"群馬県","address":"群馬県安中市安中3-19-9","lat":36.329124,"lng":138.897827,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積82㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"10 － 0122","desc":"温古亭の西南方に位置する。切妻造，桟瓦葺の木造２階建で，外壁は１階イギリス下見板張，２階モルタル塗とする。南面にベイウィンドーを張出し，屋根に３本の煙突を立ち上げるなど明治大正期の外国人宣教師館を継承したつくりに特徴。教会付属施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004333"},{"id":"00015139","register_sub_id":"101","register_pk":"530563","name":"日本基督教団桐生教会教会堂","kana":"にほんきりすときょうだんきりゅうきょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県桐生市錦町一丁目994-1","lat":36.40679167,"lng":139.33439167,"geo_status":"db","era":"昭和5年／昭和31年増築、同44年・平成4年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積254㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"10 - 0352","desc":"ＪＲ桐生駅南方の市街地に北面して建つ切妻造妻入鉄板葺の教会堂。正面は三連の尖頭アーチの中央を玄関アルコーブとし、上部に三葉形アーチ窓を開けバルコニーを付す。会堂は単廊式で祭壇を尖塔アーチで飾る。上部に現したシザーズトラスが上昇感をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015139"},{"id":"00007002","register_sub_id":"101","register_pk":"107984","name":"日本基督教団島村教会教会堂","kana":"にほんきりすときょうだんしまむらきょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"群馬県","address":"群馬県伊勢崎市境島村2509-2","lat":36.245003,"lng":139.245697,"geo_status":"db","era":"明治30／昭和25増築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積86㎡","structure_material":"木造平屋一部2階建","registered":"2008.04.18(平成20.04.18)","register_no":"10 － 0257","desc":"田園風景の中に建つ木造の小教会堂。屋根は桟瓦葺で北の平屋部を切妻造、南の２階部を半切妻造とし、東面南寄りに切妻屋根の玄関が付く。外壁は下見板張で２階を漆喰塗とする。小屋組はキングポスト・トラス。玄関部の簡素なハーフチンバー風意匠が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007002"},{"id":"00006783","register_sub_id":"101","register_pk":"107765","name":"日本聖公会高崎聖オーガスチン教会聖堂","kana":"にほんせいこうかいたかさきせいおーがすちんきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県高崎市山田町8-1","lat":36.331966,"lng":139.007172,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、スレート葺、建築面積158㎡、鐘塔付","structure_material":"鉄筋コンクリート造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"10 － 0253","desc":"鉄筋コンクリート造平屋建の単廊式教会である。北側道路に面した西端に尖頭アーチの出入口を設ける。交叉部北の角塔形鐘楼は、四隅にバットレスを付ける。屋根はスレート瓦葺。小屋組は木造シザーズ・トラスとする。簡潔な意匠のネオ・ゴシック風教会堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006783"},{"id":"00002508","register_sub_id":"101","register_pk":"103498","name":"前橋カトリック教会聖堂","kana":"まえばしかとりっくきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"群馬県","address":"群馬県前橋市大手町2-14-6","lat":36.389671,"lng":139.065109,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造平屋一部3階建、スレート葺、建築面積375㎡","structure_material":"鉄筋コンクリート造平屋一部3階建","registered":"2001.11.20(平成13.11.20)","register_no":"10 － 0085","desc":"県庁東南方に位置し東面して建つ。正面左右に下部四角，上部八角の塔を立上げた双塔形式の会堂で，内部は３廊式とする。身廊部天井を８分ヴォールトとするなどゴシック式を基調とするが，身廊部の簡明な壁面構成や陸屋根状の側廊部などモダンな取扱いも特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002508"},{"id":"00011451","register_sub_id":"101","register_pk":"210419","name":"歓喜院閼伽井堂","kana":"かんぎいんあかいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.227956,"lng":139.375102,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0162","desc":"仁王門の南に位置し、東面する。木造平屋建、入母屋造銅板葺で、平面は中央に井戸を据えた方三メートルの土間と水天宮を祀る一室よりなる。井戸廻りは木柵を建て込んで開放とする。虹梁や木鼻、支輪には精緻な彫刻を施し、小規模ながら上質の設えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011451"},{"id":"00011453","register_sub_id":"101","register_pk":"210381","name":"歓喜院五社大明神","kana":"かんぎいんごしゃだいみょうじん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228261,"lng":139.374363,"geo_status":"db","era":"天明3年（1783）／平成23年改修","year":1783,"year_source":"db","year_min":1783,"year_max":1783,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0164","desc":"聖天堂背面三社の中央に建つ。桁行五間、梁間二間、切妻造銅板葺で、後方一間に五神を祀り、手前一間を見世棚とする。軸部は弁柄塗とする。軒廻り見世棚上部を虹梁で繋ぎ、妻は彩色を施した笈形付き二重虹梁大瓶束とするなど華やかである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011453"},{"id":"00011449","register_sub_id":"101","register_pk":"210418","name":"歓喜院籠堂","kana":"かんぎいんこもりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228301,"lng":139.375218,"geo_status":"db","era":"明治12年／昭和30年代後半増築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0160","desc":"聖天堂の北東に位置する祈願者のための籠堂。木造二階建、寄棟造桟瓦葺で、南東に唐破風造銅板葺の玄関を付す。平面は一、二階とも八畳六室を二列に並べ、四周に廊下を廻らし、西面に大床を備える。二階には平書院、透彫欄間を備える。境内景観を構成する建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011449"},{"id":"00011452","register_sub_id":"101","register_pk":"210380","name":"歓喜院三宝荒神社","kana":"かんぎいんさんぽうこうじんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228382,"lng":139.374405,"geo_status":"db","era":"天明7年（1787）／平成23年改修","year":1787,"year_source":"db","year_min":1787,"year_max":1787,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0163","desc":"聖天堂背面三社のうち北寄りに建つ。一間社流造、素木造、銅板葺の小社で、庇は浜縁、浜床を設け、四周の高欄は繰型付の板持送りで支持する。軒廻りも独特な形の虹梁や海老虹梁、蟇股や支輪、庇柱木鼻などの彫刻で賑やかに飾り、高い大工技術を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011452"},{"id":"00011450","register_sub_id":"101","register_pk":"210402","name":"歓喜院鐘楼","kana":"かんぎいんしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228332,"lng":139.375005,"geo_status":"db","era":"宝暦11年（1761）／大正期・昭和26年改修","year":1761,"year_source":"db","year_min":1761,"year_max":1761,"year_label":null,"structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0161","desc":"籠堂の西に建つ。石造とコンクリート造の二重の基壇上に建つ入母屋造桟瓦葺の鐘楼。下層は柱間に横板壁を建て込んで四周を囲み、西面に上層への階段を設ける。上層は吹放ちで四周に縁を張出す。後の改造もあって建ちの高い特異な外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011450"},{"id":"00011454","register_sub_id":"101","register_pk":"210420","name":"歓喜院天満社","kana":"かんぎいんてんまんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.22816,"lng":139.374339,"geo_status":"db","era":"天明5年（1785）／平成23年改修","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.8㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0165","desc":"聖天堂背面三社のうち南寄りに建つ。一間社流造、素木造、銅板葺の小社で、庇は浜縁、浜床に木階五級を設け、四周の高欄は繰型付の板持送で支持する。軒廻りの虹梁の形、各部の彫刻など、三宝荒神社とほぼ同じ形で、境内の形成過程を知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011454"},{"id":"00011455","register_sub_id":"101","register_pk":"210421","name":"歓喜院仁王門","kana":"かんぎいんにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.22804,"lng":139.375249,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"11-0166","desc":"参道の奥、聖天堂の正面に建つ五間三戸の大規模な門で、左右に仁王像を安置する。屋根は入母屋造瓦棒銅板葺である。丸柱上の頭貫木鼻と台輪は隅、平ともに突出させ、出組組物で軒を支え、中備に蟇股を据える。中央間虹梁には花鳥の精緻な彫刻を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011455"},{"id":"00011457","register_sub_id":"101","register_pk":"210423","name":"歓喜院平和の塔","kana":"かんぎいんへいわのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.228765,"lng":139.375086,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積17㎡","structure_material":"木造多宝塔","registered":"2017.05.02(平成29.05.02)","register_no":"11-0168","desc":"境内北方の小高い場所に建つ。戦没者の供養と世界恒久平和を祈願して建てられた。総欅造の木造多宝塔で、下層組物は出組とし軒は二軒繁垂木、上層は三手先、軒は二軒扇垂木とする。蟇股など細部に復古的な特徴が見られる、第二次大戦後の記念碑的多宝塔の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011457"},{"id":"00011456","register_sub_id":"101","register_pk":"210422","name":"歓喜院水屋","kana":"かんぎいんみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"埼玉県","address":"埼玉県熊谷市妻沼1511","lat":36.227945,"lng":139.375322,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、面積3.4㎡","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"11-0167","desc":"仁王門の正面南寄りに建つ。桁行一間梁間一間、切妻造桟瓦葺で、柱を内転びとし、中央に石製の水盤を据える。軒廻りは出組で太い虹梁を支え、虹梁、大ぶりの蟇股、支輪に様々な彫刻を施すなど規模に比して豪奢で重厚な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011456"},{"id":"00015290","register_sub_id":"101","register_pk":"532414","name":"越谷久伊豆神社神楽殿","kana":"こしがやひさいずじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷1700","lat":35.90139444,"lng":139.79062778,"geo_status":"db","era":"明治前期／昭和中期改修、同49年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"11 - 0233","desc":"境内の北東、参道の東に建つ神楽殿。正面は方一間の舞台で背面に楽屋を付した、入母屋造妻入銅板葺。舞台の三方に刎高欄付縁を廻らして脇障子を付し、舞台と楽屋境に板戸を建てる。正面寄りの軒は、吹寄の扇垂木とした丁寧なつくりで、参道沿いの景観を演出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015290"},{"id":"00015291","register_sub_id":"101","register_pk":"532415","name":"越谷久伊豆神社手水舎","kana":"こしがやひさいずじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷1700","lat":35.901275,"lng":139.79051944,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、銅板葺、面積4.4㎡、手水鉢付","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"11 - 0234","desc":"神楽殿の南、参道の東に建つ手水舎。方一間入母屋造瓦棒銅板葺で両妻面に軒唐破風を付す。柱を四方転びに立て、組物は出組、軒は二軒繁垂木。斜めに出す丸彫の龍鼻や籠彫の持送、虹梁形頭貫、中備など随所を彫刻で飾り軒唐破風と相まって華麗な外観の手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015291"},{"id":"00015289","register_sub_id":"101","register_pk":"532413","name":"越谷久伊豆神社本殿","kana":"こしがやひさいずじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市越ヶ谷1700","lat":35.90191667,"lng":139.79056111,"geo_status":"db","era":"寛政元年(1789)","year":1789,"year_source":"db","year_min":1789,"year_max":1789,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"11 - 0232","desc":"越谷の市街地中心部に鎮座する神社本殿。南面して建つ三間社流造瓦棒銅板葺で、三方に腰組付縁を廻らし脇障子を建てる。組物は出組、妻飾は二重虹梁大瓶束、軒は二軒繁垂木。庇柱、虹梁形頭貫、木鼻、中備などに精緻な素木の彫刻を付し、装飾華やかな本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015289"},{"id":"00013691","register_sub_id":"101","register_pk":"505207","name":"金剛寺山門","kana":"こんごうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡川島町大字中山字中廓1198","lat":35.98929167,"lng":139.451425,"geo_status":"db","era":"嘉永5年(1852)","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 203","desc":"境内南辺に南面して建つ切妻造桟瓦葺の四脚門。本柱は円柱で冠木で繋ぎ、控柱は角柱で腰貫、頭貫を通して軸部を固める。組物は出組で妻飾は二重虹梁大瓶束とし、軒は二軒繁垂木とする。隅行に獅子鼻を掛けて、冠木上を龍の彫刻で飾った丁寧な造りの山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013691"},{"id":"00013690","register_sub_id":"101","register_pk":"505205","name":"金剛寺大日堂","kana":"こんごうじだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡川島町大字中山字中廓1198","lat":35.98978333,"lng":139.45191667,"geo_status":"db","era":"江戸中期／大正15年・昭和55年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"11 － 202","desc":"本堂東方に南面して建つ。正面一間側背面二間宝形造銅板葺。側廻りは角柱で切目長押、内法長押で緊結し、組物は舟肘木、軒は二軒繁垂木とする。内部は内外陣境に円柱を立て組物は出三斗とし、壁画や天井画を残す。外部の小壁を古式な蟇股や彫刻で飾る仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013690"},{"id":"00013229","register_sub_id":"101","register_pk":"366218","name":"世界無名戦士之墓","kana":"せかいむめいせんしのはか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"埼玉県","address":"埼玉県入間郡越生町大字越生字岡崎935","lat":35.96422778,"lng":139.28939722,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積210㎡","structure_material":"鉄筋コンクリート造3階建","registered":"2020.04.03(令和2.04.03)","register_no":"11 － 0195","desc":"大観山山頂に位置する鉄筋コンクリート造三階建で、東面して建つ。戦後に身元不明の遺骨等を祀った礼拝施設。四分の一円弧平面の納骨室を建上げ、正面にフルーティングを施し、中央に半円形の礼拝室を構える。地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013229"},{"id":"00002519","register_sub_id":"101","register_pk":"103509","name":"日本聖公会川越キリスト教会礼拝堂","kana":"にほんせいこうかいかわごえきりすときょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県川越市松江町2-4-13","lat":35.921143,"lng":139.485352,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、スレート葺、建築面積138㎡、塔屋付","structure_material":"煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"11 － 0036","desc":"立教大学新築のため来日したＷ．ウィルソンの設計により建設。東西に細長い切妻造・平屋建で，外壁煉瓦造，内部は挟み組み式の小屋組を見せ，尖塔アーチの縦長窓や控壁にゴシック様式細部を備える。Ｔ字路の突き当たりに建ち，際だった景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002519"},{"id":"00004946","register_sub_id":"101","register_pk":"105936","name":"日本聖公会熊谷聖パウロ教会門","kana":"にほんせいこうかいくまがやせいぱうろきょうかいもん","category":"宗教","subcategory":"その他工作物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市宮町1-139","lat":36.14678676,"lng":139.38383514,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造、間口4.5m","structure_material":"煉瓦造","registered":"2005.11.10(平成17.11.10)","register_no":"11 － 0090","desc":"鐘塔を兼ねた礼拝堂玄関ポーチに対応した位置に建つ。門の間口は内法で２．２ｍ，東側に脇門を設ける。門柱は煉瓦造で，煉瓦長手２枚角，脇門柱は１枚半角とする。門柱根積部との境に柾立ての層を挟み，礼拝堂と合わせた積み方とするのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004946"},{"id":"00004945","register_sub_id":"101","register_pk":"105935","name":"日本聖公会熊谷聖パウロ教会礼拝堂","kana":"にほんせいこうかいくまがやせいぱうろきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"埼玉県","address":"埼玉県熊谷市宮町1-139","lat":36.14670986,"lng":139.38374942,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積141㎡","structure_material":"煉瓦造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"11 － 0089","desc":"焼過煉瓦を効果的に用いた煉瓦造教会。桁行約１６ｍ，梁行約７ｍ規模の単廊式会堂で，東面北端に鐘塔を建ち上げ下部を玄関ポーチとし，外壁要所に尖頭アーチ窓とバットレスを配す。内部は煉瓦壁を顕わにし，木造シザーストラスを架ける。設計はＷ．ウィルソン。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004945"},{"id":"00014140","register_sub_id":"101","register_pk":"508770","name":"八條八幡神社本殿","kana":"はちじょうはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"埼玉県","address":"埼玉県八潮市大字八條字堤外4069","lat":35.85589722,"lng":139.83876389,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡、覆屋付","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"11-0218","desc":"中川西岸微高地に所在する旧八條村の鎮守で１間社流造社殿。２手先組物に腰組は４手先とし、向拝柱の龍を始め夥しい彫刻で飾る。圧巻は側面羽目板で大日本帝国憲法発布を題材とした彫刻を１枚板浮彫で飾る。時事を題材とした社殿の彫刻は希少で、趣が深い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014140"},{"id":"00006261","register_sub_id":"101","register_pk":"107245","name":"日野岡家住宅長屋門","kana":"ひのおかけじゅうたくながやもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県比企郡鳩山町大字須江407","lat":36.002007,"lng":139.32664339,"geo_status":"db","era":"江戸後期／昭和54・56・平成4改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積74㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"11 － 0107","desc":"丘陵の南裾にあり，南面して建つ。東西棟の寄棟造，もと茅葺で，平面は桁行１５．７ｍ，梁間４．６ｍの規模を有し，中央に門口を構え，両側を部屋とする。軒は出桁造，小屋は扠首組で，正面外壁の腰は押縁下見板張とする。形式は簡素であるが，丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006261"},{"id":"00016490","register_sub_id":"101","register_pk":"574852","name":"林泉寺表門（赤門）","kana":"りんせんじおもてもん（あかもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"宝暦6年（1756）","year":1756,"year_source":"db","year_min":1756,"year_max":1756,"year_label":null,"structure":"木造、瓦葺、間口3.4m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0246","desc":"本堂の西方に西面して建つ一間一戸の四脚門。切妻造桟瓦葺で、主柱は五平柱とし、軸部は腰貫、内法貫、頭貫で固める。棟通りは扇に日の丸の浮彫をあしらった蟇股や、吹寄菱格子で飾るなど意匠上の見所とする。全体を朱塗とし、地域が赤門と呼び親しむ表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016490"},{"id":"00016487","register_sub_id":"101","register_pk":"574849","name":"林泉寺子安観音堂","kana":"りんせんじこやすかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"宝暦12年（1762）／昭和51年改修","year":1762,"year_source":"db","year_min":1762,"year_max":1762,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0243","desc":"本堂西方に南面して建つ子安観音堂。桁行3間梁間3間、入母屋造桟瓦葺で、銅板葺の1間向拝を切下げて付し、四周に縁を廻す。台輪上に三斗を組み、軒は二軒繁垂木。内部は一室の畳敷で棹縁天井を張り、背面側に仏壇を構える。全体に当初形式を良く残す小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016487"},{"id":"00016489","register_sub_id":"101","register_pk":"574851","name":"林泉寺地蔵堂","kana":"りんせんじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"江戸後期／昭和51年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、建築面積7.5㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0245","desc":"境内西方に南面して建つ地蔵堂。三間四方宝形造桟瓦葺で柱間は正面中央間を広くし、三方に縁を廻らす。軸部は角柱で桁を直接支え、軒は一軒繁垂木。内部は板敷の一室で棹縁天井を張り、背面側に通しの仏壇を構える。全体に質実なつくりで、寺観を整える小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016489"},{"id":"00016488","register_sub_id":"101","register_pk":"574850","name":"林泉寺鐘楼堂","kana":"りんせんじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"延享5年（1748）","year":1748,"year_source":"db","year_min":1748,"year_max":1748,"year_label":null,"structure":"木造、瓦葺、面積6.8㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0244","desc":"本堂の南西に位置する鐘楼堂。切石積基壇に建つ方一間、入母屋造桟瓦葺で、面取角柱を四方転びに立て、腰貫・内法貫・頭貫で固め、台輪を廻す。組物は絵様肘木に三斗組を重ねた特徴的な形式で、中備は蟇股。軒は二軒繁垂木。落着いた外観で境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016488"},{"id":"00016486","register_sub_id":"101","register_pk":"574848","name":"林泉寺本堂","kana":"りんせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"延宝元年（1673）頃／寛保2年(1742)頃・文政8年（1825）頃・昭和45年改修","year":1673,"year_source":"db","year_min":1673,"year_max":1673,"year_label":null,"structure":"木造、瓦葺、建築面積171㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0242","desc":"市街地北東に位置する浄土宗寺院の本堂。境内東寄りに西面して建つ入母屋造桟瓦葺で、正面に一間向拝を付す。平面は前方を外陣、後方中央を内陣、両側を脇陣とし、内陣に禅宗様須弥壇を配し、格天井に草花の彩色画を華やかに飾る。境内景観の中核をなす本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016486"},{"id":"00016491","register_sub_id":"101","register_pk":"574853","name":"林泉寺脇門（黒門）","kana":"りんせんじわきもん（くろもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"埼玉県","address":"埼玉県越谷市増林3818","lat":35.91294,"lng":139.81552389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.0m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"11 - 0247","desc":"赤門の南方に西面して建つ一間一戸の薬医門。切妻造桟瓦葺で、主柱間、控柱間に桁を渡して梁を架け、梁上の束で棟木を受け、梁の前後で軒桁を受ける。軒は一軒疎垂木で、門口に板戸を吊る。小規模ながら境内南西の景観をつくり、地域が黒門と呼び親しむ脇門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016491"},{"id":"00016354","register_sub_id":"101","register_pk":"536421","name":"大日堂","kana":"だいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"茨城県","address":"茨城県笠間市箱田字長町2210他","lat":36.39923889,"lng":140.23468333,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"08 - 0322","desc":"市街地の北西に位置し、日本画家木村武山が建立した持仏堂。池に東面して建つ宝形造本瓦葺で頂部の路盤中央に宝珠、四隅に鳳凰を飾る。内部は一室の玉石敷で中央に据えた八角須弥壇に厨子を安置。壁の仏画や天井の花鳥図など、武山が絵筆を揮った渾身の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016354"},{"id":"00015400","register_sub_id":"101","register_pk":"533415","name":"日本聖公会土浦聖バルナバ教会礼拝堂","kana":"にっぽんせいこうかいつちうらせいばるなばきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"茨城県","address":"茨城県土浦市中央一丁目6-イ-1","lat":36.08443611,"lng":140.19705,"geo_status":"db","era":"昭和5年／平成13年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺一部銅板葺、建築面積175㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"08 - 0321","desc":"土浦城跡の西に位置する教会の礼拝堂。平屋建切妻造桟瓦葺の東西棟で、礼拝堂の西に玄関と鐘楼、東に集会室を附属する。鉄筋コンクリート造の壁式構造で、内部は木造トラスの小屋組を現す。四角平面に八角屋根を載せた鐘楼を外観のアクセントとする礼拝堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015400"},{"id":"00003950","register_sub_id":"101","register_pk":"104940","name":"密弘寺不動堂","kana":"みっこうじふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"茨城県","address":"茨城県桜川市真壁町真壁184","lat":36.277584,"lng":140.098633,"geo_status":"db","era":"天保11","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"08 － 0123","desc":"名水不動の名で地元に親しまれる真言宗寺院の小堂。方３間，宝形造，桟瓦葺で，正面に向拝を設け，内部は１室で奥に須弥壇，左右脇壇を造り付ける。丸柱上に出組を組み，軒は二軒繁垂木，頭貫木鼻，向拝回りに篭彫，丸彫の派手な彫刻を付し整った姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003950"},{"id":"00001492","register_sub_id":"101","register_pk":"102482","name":"香雲閣","kana":"かうんかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県香取市香取1697-1","lat":35.88733452,"lng":140.52951259,"geo_status":"db","era":"明治33頃","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積304㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"12 － 0036","desc":"香取神宮社殿の北東に南面して建ち，集会や直会に用いられてきた２階建，寄棟造の和風建築で，一部の造作を除き，明治３３年頃に完成した。１階正面に唐破風造の玄関を設けて大規模ながら均整の取れた外観とし，境内空間に調和した構成要素となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001492"},{"id":"00002134","register_sub_id":"101","register_pk":"103124","name":"香取神宮拝殿・幣殿・神饌所","kana":"かとりじんぐうはいでん・へいでん・しんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県香取市香取1697-1","lat":35.88609531,"lng":140.52871628,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積298㎡","structure_material":"木造平屋建","registered":"2001.04.24(平成13.04.24)","register_no":"12 － 0038","desc":"内務省神社局による昭和１１年からの大修築により建設。重文の本殿（元禄１３年）正面に権現造風に幣殿・拝殿を繋げ，拝殿正面に千鳥破風と軒唐破風を付ける。軸部を黒漆塗，組物・蟇股を極彩色とするなど本殿の意匠と釣り合った体裁をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002134"},{"id":"00016493","register_sub_id":"101","register_pk":"574855","name":"旧茂木佐平治家住宅金宝殿手水舎","kana":"きゅうもぎさへいじけじゅうたくきんぽうでんちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、面積3.4㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0339","desc":"本社の参道北に建つ手水舎。本瓦葺の切妻屋根は照り起りの唐破風形とする。四隅の柱は内転びで龍彫刻を飾る。頭貫は亀甲紋の地紋彫、獅子鼻とし、斗栱間に亀、唐破風懸魚に狐と宝珠の彫刻を飾る。彫刻濃密な近代和風建築で、天井に掲げた雷神の高浮彫が圧巻。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016493"},{"id":"00016492","register_sub_id":"101","register_pk":"574854","name":"旧茂木佐平治家住宅金宝殿本社","kana":"きゅうもぎさへいじけじゅうたくきんぽうでんほんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡、宮殿付","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0338","desc":"茂木佐公園に隣接する旧醤油醸造家の屋敷社。東面して建つ入母屋造妻入本瓦葺で向唐破風向拝付、四周に縁を廻らす。内陣正面は格子戸引分、外陣は畳敷とする。向拝柱は亀甲形の六角柱で龍彫刻を施し、木鼻、蟇股、羽目板など内外を彫刻で濃密に飾った本社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016492"},{"id":"00001247","register_sub_id":"101","register_pk":"102237","name":"九十九里教会","kana":"くじゅうくりきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県山武市松尾町松尾60-1","lat":35.63986121,"lng":140.45620376,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積100㎡","structure_material":"木造平屋建","registered":"1999.08.23(平成11.08.23)","register_no":"12 － 0028","desc":"木造、瓦葺切妻屋根、下見板貼の素朴なキリスト教会堂建築であるが、軒回りを塗込め、正面に入母屋屋根の玄関ポーチを付けるなど後の時代の木造ゴシックの教会堂とは趣を異にする点に特徴がある。ヘボンゆかりの教会として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001247"},{"id":"00001491","register_sub_id":"101","register_pk":"102481","name":"選擇寺本堂","kana":"せんちゃくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県木更津市中央1-5-6","lat":35.384075,"lng":139.923111,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積232㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"12 － 0035","desc":"木更津市街にある昭和５年に建てられた寺院本堂。鉄筋コンクリート造であるが，向拝付の木造３間仏堂の形態を採用し，組物や軒廻り等の細部を忠実に再現している。伝統的様式を踏襲しながら，耐久性を目指した寺院建築として，時代の特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001491"},{"id":"00008649","register_sub_id":"101","register_pk":"149370","name":"大巌寺書院","kana":"だいがんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県千葉市中央区大巌寺町180-1","lat":35.57427987,"lng":140.14610393,"geo_status":"db","era":"江戸末期／昭和30年頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積372㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0152","desc":"本堂の東に南面して建つ。切妻造鉄板葺で、千鳥破風状に窓を設け、正面に中央に入母屋造妻入の玄関を付設する。建築面積372㎡。東半部は2列各3室を並べ、北に畳縁を通し、西寄りに南北に3室を配し、4周に縁を通す。教学の場の雰囲気を残す書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008649"},{"id":"00008648","register_sub_id":"101","register_pk":"149369","name":"大巌寺本堂","kana":"だいがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県千葉市中央区大巌寺町180-1","lat":35.57412996,"lng":140.14590881,"geo_status":"db","era":"江戸中期／明治36年・昭和23年・昭和後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積476㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"12 － 0151","desc":"境内の北奥に南面して建つ。桁行5間梁間4間、寄棟造桟瓦葺を主体部とし、その周囲に下屋をまわし、正面に唐破風造桟瓦葺の向拝を付設する。主体部は外陣と内陣、脇の間等からなり、内陣には須弥壇を構える。18世紀中葉に遡る数少ない浄土宗檀林遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008648"},{"id":"00001173","register_sub_id":"101","register_pk":"102163","name":"長興院山門","kana":"ちょうこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"千葉県","address":"千葉県成田市伊能556","lat":35.83786963,"lng":140.43199424,"geo_status":"db","era":"江戸時代末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸時代末期","structure":"木造楼門，瓦葺，建築面積22㎡","structure_material":"木造楼門","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0015","desc":"総欅造り，楼門形式の門。彫刻をあまり用いないなど簡素な意匠になるが，組物を詰組にするなど細部には工夫もみられる。上層部のせいが高く，内部に十六羅漢を祀る（現在は本堂内に保管）点に，よく時代の特徴があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001173"},{"id":"00007341","register_sub_id":"101","register_pk":"108323","name":"日本福音ルーテル市川教会会堂","kana":"にほんふくいんるーてるいちかわきょうかいかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県市川市市川4-288-14","lat":35.738251,"lng":139.9058721,"geo_status":"db","era":"昭和30／平成5改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建塔屋付、鉄板葺、建築面積148㎡","structure_material":"木造2階建塔屋付","registered":"2008.10.23(平成20.10.23)","register_no":"12 － 0114","desc":"梁間７．３ｍ桁行１７ｍの木造教会堂で、南北棟の切妻造瓦型鉄板葺屋根をもつ単廊式の礼拝堂と、その東面南寄りに建つ４階建の鐘楼からなる。平滑な白色の外壁に、正面や鐘楼上部に丸窓、身廊側面に半円アーチ窓を開ける。ヴォーリズ晩年の作品のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007341"},{"id":"00001168","register_sub_id":"101","register_pk":"102158","name":"茂原昇天教会","kana":"もばらしょうてんきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"千葉県","address":"千葉県茂原市茂原581","lat":35.42448804,"lng":140.29724583,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積113㎡","structure_material":"木造平屋建","registered":"1999.07.08(平成11.07.08)","register_no":"12 － 0010","desc":"木造平屋建、下見板貼、単廊式の礼拝堂で、平面の輪郭はラテン十字形を描く。ハーフティンバー風に仕上げられた身廊部正面の切妻と、正方形と八角形断面のカップルとなったトスカナ式の柱によって支持された玄関ポーチとが端正なファサードを造っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001168"},{"id":"00016495","register_sub_id":"101","register_pk":"574857","name":"よろこび寮表門","kana":"よろこびりょうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田字東中町350-4","lat":35.937995,"lng":139.86641778,"geo_status":"db","era":"大正15年頃／昭和中期改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造、鉄板葺、間口2.1m、脇塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0341","desc":"会堂の東正面、茂木佐公園との境に建つ腕木門。冠木上の板欄間は中央を透かせて門灯を設け、背面は腕木下を控柱で受ける。門口は板扉を両開に吊り、左右に斜めに延ばした袖塀は、竪板張で上部の欄間に丸竹を渡し、笠木を載せる。全体に繊細なつくりの表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016495"},{"id":"00016494","register_sub_id":"101","register_pk":"574856","name":"よろこび寮会堂","kana":"よろこびりょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県野田市野田350","lat":35.94549778,"lng":139.86378583,"geo_status":"db","era":"大正15年／平成17年頃改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"12 - 0340","desc":"茂木佐公園の西に位置する仏教修養団体の会堂。平屋建寄棟造桟瓦葺で全体矩折の平面。東面北寄りに玄関を設け、南に八畳二室の座敷、西側の突出部に居室と水回りを配す。座敷は床柱に檳榔樹、床框や落掛に黒檀など、床廻りに銘木を用いた瀟洒なつくりの会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016494"},{"id":"00001374","register_sub_id":"101","register_pk":"102364","name":"阿豆佐和気命神社旧本殿","kana":"あづさわけのみことじんじゃきゅうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都利島村1","lat":34.52967219,"lng":139.27699138,"geo_status":"db","era":"文久4","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"木造平屋建、板葺、建築面積3.1㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"13 － 0063","desc":"利島は伊豆諸島の大島と新島の間にあり，当社は「延喜式神名帳」にも小社として記されている。棟札より離島における数少ない江戸時代末期の神社本殿建築。簡素であるが本式の細部様式を備えており，類例の少ない２間社流造として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001374"},{"id":"00010927","register_sub_id":"101","register_pk":"208898","name":"御嶽神社社務所","kana":"おんたけじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都大田区北嶺町145-1他","lat":35.586091,"lng":139.681071,"geo_status":"db","era":"昭和5／昭和26改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積154㎡","structure_material":"木造平屋一部2階建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0360","desc":"境内西方に東面して建つ。南北棟の社務所で、中央に起りのある切妻破風と入母屋屋根を架ける玄関を突き出す。玄関の間の南には一五畳の応接室を設け、東側に座敷飾を設ける。床に南洋材などの銘木を用い、折上格天井を張って格式を高める良質な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010927"},{"id":"00010926","register_sub_id":"101","register_pk":"208897","name":"御嶽神社水行堂","kana":"おんたけじんじゃすいぎょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都大田区北嶺町145-1他","lat":35.586177,"lng":139.68115,"geo_status":"db","era":"慶応3（1867）頃","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積18㎡、井戸付","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0359","desc":"境内西方に東面して建つ。東西棟、切妻造妻入で、三間四方の内部を前後二室に区切る。水垢離をするための施設で、井戸を有する。正面の両脇間に花頭窓を開け、頭貫を虹梁として、上部に龍の彫刻欄間を嵌めて飾る。木鼻の形状などに時代的特徴が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010926"},{"id":"00010925","register_sub_id":"101","register_pk":"208896","name":"御嶽神社末社一山神社祖霊社","kana":"おんたけじんじゃまっしゃいっさんじんじゃそれいしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都大田区北嶺町145-1他","lat":35.586321,"lng":139.681145,"geo_status":"db","era":"明治32","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"13-0358","desc":"御嶽神社を創建した一山行者を祀り、境内西方に南面して建つ。東西棟の拝殿から丁字に本殿を突出し、正面に一間向拝を設ける。本殿は後方に祭壇を造り付け、手前を畳敷の幣殿とする。拝殿は折上格天井とし、洋風灯具を吊る。簡明な意匠を持つ近代小規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010925"},{"id":"00013693","register_sub_id":"101","register_pk":"504967","name":"海福寺本堂","kana":"かいふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都目黒区下目黒三丁目679-2","lat":35.62934722,"lng":139.70931111,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"13 － 449","desc":"黄檗宗寺院本堂。入母屋造桟瓦葺で東面する。桁行一三・八メートル、梁間九・八メートルで正面北寄りに向拝を付け、背後に寄棟造の突出部を張出す。北列は正面から広縁、室中、内陣とし奥に須弥壇を設ける。南列は二室の客間。区内で貴重な戦前建立の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013693"},{"id":"00002615","register_sub_id":"101","register_pk":"103605","name":"カトリック神田教会聖堂","kana":"かとりっくかんだきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区西神田1-1-12","lat":35.699387,"lng":139.757355,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋一部2階建、瓦葺、建築面積643㎡","structure_material":"鉄骨鉄筋コンクリート造平屋一部2階建","registered":"2002.02.14(平成14.02.14)","register_no":"13 － 0120","desc":"水道橋南方に位置し街路の角地に立つ。バシリカ形式の三廊式聖堂で，半円アーチを基調とした開口部，ロンバルド帯風の軒蛇腹，四葉をモチーフとした胴蛇腹が外観を飾り，半円アーチのヴォールト天井と玄関脇に集会所を設ける平面を特徴とする。設計ヒンデル。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002615"},{"id":"00013968","register_sub_id":"101","register_pk":"508228","name":"寛永寺葵の間","kana":"かんえいじあおいのま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都台東区上野桜木一丁目10","lat":35.72156944,"lng":139.77468889,"geo_status":"db","era":"江戸末期／大正3年・平成25年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0453","desc":"根本中堂の東に所在する書院造の建築。主座敷一〇畳の北が次の間八畳で、西に一間幅の広縁がつく。主座敷は床の南に下地窓、床脇は地袋棚である。次の間は壁と天井を紙張、北に一畳大の板敷がつく。東に雪隠が接続する。数寄屋風を加味した上質な座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013968"},{"id":"00002369","register_sub_id":"101","register_pk":"103359","name":"寛永寺護国院庫裏","kana":"かんえいじごこくいんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区上野公園10-18","lat":35.71925,"lng":139.769821,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋一部2階建、2階部を除く、瓦葺、建築面積386㎡","structure_material":"木造平屋一部2階建","registered":"2001.10.12(平成13.10.12)","register_no":"13 － 0111","desc":"護国院本堂の西方に建ち，客殿部と住居部から成る。客殿部は，７間×２間規模の中庭を有し，北側に玄関・応接室・役僧室等を，南側に１２畳半の客間と１０畳２室を東西に並べ，四周に縁廊下を廻す。岡田信一郎が手がけた数少ない和風建築のひとつとして貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002369"},{"id":"00013967","register_sub_id":"101","register_pk":"508227","name":"寛永寺根本中堂","kana":"かんえいじこんぽんちゅうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都台東区上野桜木一丁目10","lat":35.721425,"lng":139.77439167,"geo_status":"db","era":"明治12年／昭和60年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積368㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0452","desc":"境内南西に西面して建つ桁行七間、梁間七間の大型仏堂である。入母屋造本瓦葺で、尾垂木付の二手先組物が二軒繁垂木の軒を受ける。内部は後方の三間が内陣で、宮殿廻りはもと土間であった。天井全体を鏡天井とする。根本中堂の形式の本格的な天台宗寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013967"},{"id":"00003521","register_sub_id":"101","register_pk":"104511","name":"神田神社神饌所","kana":"かんだじんじゃしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70198194,"lng":139.76815963,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積19㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0152","desc":"本殿東方に位置し，桁行・梁間各２間，入母屋造，２軒繁垂木，本瓦型銅板葺で，東面に張出しを付す。内部は拭板敷で，南東隅に踏込土間を設ける。小規模ながら高い基壇上に建ち，主要社殿同様全体を弁柄色塗とし，随所に金箔押金具を飾り格式と荘厳を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003521"},{"id":"00003525","register_sub_id":"101","register_pk":"104515","name":"神田神社西門","kana":"かんだじんじゃにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70210451,"lng":139.7677372,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造、銅板葺、間口1.8m、玉垣折曲り延長14m付","structure_material":"鉄骨鉄筋コンクリート造","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0156","desc":"宝庫南方に脇障子風板塀を介して接続する。外側は基壇上に載り，北より第２間に門口を開き，両開桟唐戸を吊り込む。北方に１間，南方には拝殿側面まで矩ね折れ５間に北半と同形式の玉垣を回す。拝殿及び宝庫とともに，複合社殿正側面の構成上欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003525"},{"id":"00003520","register_sub_id":"101","register_pk":"104510","name":"神田神社拝殿","kana":"かんだじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70191154,"lng":139.76783966,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積335㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0151","desc":"中央間を広く取った桁行７間，梁間６間，入母屋造，本瓦型銅板葺で，正面５間に向拝を付し，両脇突出部に切妻屋根を架ける。内部は前方四半敷の土間，後方畳敷床上部とする。社殿群中最大の建物で，伝統的構成を基本にしつつ，装飾や比例に新感覚が充溢する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003520"},{"id":"00003524","register_sub_id":"101","register_pk":"104514","name":"神田神社東門","kana":"かんだじんじゃひがしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70188986,"lng":139.76803507,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造、銅板葺、間口1.8m、玉垣折曲り延長14m付","structure_material":"鉄骨鉄筋コンクリート造","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0155","desc":"神饌所南方に脇障子風板塀を介して接続する。外側は基壇上に載り北より第２間に門口を開き両開桟唐戸を吊り込む。北方に１間，南方には拝殿側面まで矩ね折れに５間，北半と同形式の玉垣を回す。拝殿，神饌所とともに，複合社殿正側面の構成上欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003524"},{"id":"00003519","register_sub_id":"101","register_pk":"104509","name":"神田神社幣殿","kana":"かんだじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70201454,"lng":139.76790848,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積46㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0150","desc":"本殿と拝殿を繋ぐ。間口３３尺，桁行１５尺，両下造，本瓦型銅板葺。内部は拝殿と同高に畳敷の床を張り，台輪上の組物で，中央折上げ，両脇組入天井を受ける。本殿側軸部は金箔押で組物に繧繝彩色を施す。伝統的手法を基本に，随所に新規の納まりが見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003519"},{"id":"00003522","register_sub_id":"101","register_pk":"104512","name":"神田神社宝庫","kana":"かんだじんじゃほうこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.702179,"lng":139.76779079,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積17㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0153","desc":"本殿西方神饌所とほぼ対称の位置に建つ。高床の校倉形式になり，台輪上に大斗舟肘木を載せ，２軒繁垂木の軒を受け，屋根は入母屋造，本瓦型銅板葺とする。伝統的形式を基本としながら，校倉の最下部を肘木で受ける納まりなど，要所に特徴ある新造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003522"},{"id":"00003518","register_sub_id":"101","register_pk":"104508","name":"神田神社本殿","kana":"かんだじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70211098,"lng":139.76799629,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、銅板葺、建築面積63㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0149","desc":"鉄骨鉄筋コンクリート造，入母屋造平入，本瓦型銅板葺で，梁間前方２間を外陣，奥１間を内陣とし，軒は出組，２軒繁垂木とする。伊東忠太が顧問，大江新太郎，佐藤功一が設計の震災復興社殿群の中心建物で，伝統的な木造の繊細な比例，意匠を巧みに踏襲する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003518"},{"id":"00003523","register_sub_id":"101","register_pk":"104513","name":"神田神社瑞垣","kana":"かんだじんじゃみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都千代田区外神田2-16-2","lat":35.70220129,"lng":139.76807525,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄骨鉄筋コンクリート造、銅板葺、延長60m","structure_material":"鉄骨鉄筋コンクリート造","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0154","desc":"本殿周囲を神饌所と宝庫の間で折れ回りに囲う透塀。柱を地，腰，内法の各長押で固め，腕木で出桁を受け，疎垂木，本瓦型銅板葺屋根を載せる。北面中央に門を開き，その他の柱間は上半を連子窓，腰部は吹寄せに襷桟を打つ。社殿群北半の構えに欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003523"},{"id":"00013969","register_sub_id":"101","register_pk":"508229","name":"観音寺客殿","kana":"かんのんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区谷中五丁目107-1","lat":35.72550833,"lng":139.76810833,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積232㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0454","desc":"境内中央の本堂南に並ぶ寄棟造南北棟で、東に切妻屋根に霧除庇を廻した玄関を突出、内玄関は唐破風庇がつく。南側が庫裏で、北側の玄関奥に続き間の客殿を配す。主座敷15畳は、西に畳床、天袋付違い棚を設け、付書院を備える。端正な意匠の寺院殿舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013969"},{"id":"00001561","register_sub_id":"101","register_pk":"102551","name":"観音寺築地塀","kana":"かんのんじついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区谷中5-8-28","lat":35.7253012,"lng":139.76806339,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"練塀、瓦葺、延長37.6m","structure_material":"練塀","registered":"2000.04.28(平成12.04.28)","register_no":"13 － 0076","desc":"観音寺は明和９年（１７７２）の火災で灰燼に帰した後，文政年間頃に再興された。築地塀は境内の南面を画する延長３７．６ｍのいわゆる練り塀で，瓦と粘土を交互に積み重ねて造り，潜り戸一所を備える。浅草と並ぶ江戸有数の寺町であった当時の面影を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001561"},{"id":"00008262","register_sub_id":"101","register_pk":"133904","name":"教證寺客殿","kana":"きょうしょうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都台東区池之端1-104他","lat":35.70934006,"lng":139.76896805,"geo_status":"db","era":"明治36年／大正15年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積74㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0261","desc":"敷地の北東隅に、南側で本堂に接続して建つ。桁行１４ｍ梁間５．５ｍの木造２階建、東西棟の入母屋造桟瓦葺。外壁は下見板張で、妻飾は木連格子とする。東面に大きく開いた廊下を座敷に面して付し、不忍池への眺望を意識していたことが立面に表れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008262"},{"id":"00008261","register_sub_id":"101","register_pk":"133903","name":"教證寺本堂","kana":"きょうしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都台東区池之端1-104他","lat":35.70923775,"lng":139.76893236,"geo_status":"db","era":"安政4年(1857)／大正15年改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積169㎡","structure_material":"土蔵造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"13 － 0260","desc":"敷地中ほどに西面して建つ。桁行９．９ｍ梁間１５ｍの土蔵造、寄棟造妻入桟瓦葺で、正面向拝一間、側背面を葺き降ろす。内部は外陣と内陣、余間等から構成される浄土真宗平面になる。向拝や軒まわりまでを塗り込めた土蔵造仏堂の代表的遺構のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008261"},{"id":"00005107","register_sub_id":"101","register_pk":"106097","name":"キリスト友会フレンズセンター","kana":"きりすとゆうかいふれんずせんたー","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都港区三田4-8-19","lat":35.642616,"lng":139.738281,"geo_status":"db","era":"大正11／昭和5増築","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、スレート葺、建築面積142㎡、地下室付","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"13 － 0190","desc":"宣教師館として建設。木造２階建一部地下室付き，屋根は寄棟造スレート葺，外壁はモルタル塗で，玄関庇，縦長の上げ下げ窓，大きな屋根窓，煉瓦煙突等が外観を特徴付ける。ヴォーリズ建築事務所の設計で，数少ない関東大震災前の西洋館の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005107"},{"id":"00010123","register_sub_id":"101","register_pk":"197956","name":"功運寺庫裏","kana":"こううんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中野区上高田4-14-19","lat":35.712367,"lng":139.678361,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0344","desc":"境内の中央西寄りに南面して建つ木造平屋建で、入母屋造桟瓦葺である。南の玄関から取次ぎ七畳を経て中廊下を南北に通し、東に座敷一一畳と仏間八畳が並び、北に数寄屋風で七畳の方丈を配す。座敷から方丈にかけて縁を廻らす。丁寧な造作の近代和風建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010123"},{"id":"00010125","register_sub_id":"101","register_pk":"197958","name":"功運寺山門","kana":"こううんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都中野区上高田4-14-3","lat":35.711905,"lng":139.678414,"geo_status":"db","era":"大正3／平成22改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0346","desc":"境内南の参道に開く一間高麗門で、切妻造本瓦葺とし、控柱上と左右各二間の袖塀は桟瓦葺とする。本柱は角柱で棟木までのばし、冠木上の女梁と男梁で桁を受ける。軒は二軒繁垂木で、門扉と袖塀は竪格子とする。ケヤキの良材を多用し、施工も上質な山門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010125"},{"id":"00010124","register_sub_id":"101","register_pk":"197957","name":"功運寺鐘楼","kana":"こううんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都中野区上高田4-14-3","lat":35.712134,"lng":139.67838,"geo_status":"db","era":"寛延2頃／大正3移築","year":1749,"year_source":"db","year_min":1749,"year_max":1749,"year_label":null,"structure":"木造、瓦葺、面積6.0㎡","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"13 － 0345","desc":"高い石積基壇上に建つ方一間の鐘楼で、入母屋造本瓦葺である。内転びの粽付円柱を、腰貫、虹梁、頭貫で固め、格天井を張る。台輪上に出組を詰組に配し、軒は二軒繁垂木とする。籠彫の頭貫木鼻、獅子形の虹梁木鼻、虹梁上の蟇股など、要所を豊かな彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010124"},{"id":"00007459","register_sub_id":"101","register_pk":"108441","name":"高岩寺本堂","kana":"こうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都豊島区巣鴨3-51-2","lat":35.73580912,"lng":139.73551071,"geo_status":"db","era":"昭和32／昭和60改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造平屋地下1階建、瓦葺、建築面積267㎡","structure_material":"鉄筋コンクリート造平屋地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"13 － 0237","desc":"通りに南面する敷地の北西に建つ。桁行、梁間とも１５ｍ規模のＲＣ造。入母屋造本瓦葺で、背面に入母屋造屋根を突出し、正面に一間向拝を付け、地下に事務機能を集約する。伝統的な和様を基調としつつ、細部意匠等を単純化する造形的な試みがなされ、質も高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007459"},{"id":"00000952","register_sub_id":"101","register_pk":"132573","name":"廣度院表門及び練塀","kana":"こうどいんおもてもんおよびねりべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都港区芝公園1-8-16","lat":35.65724825,"lng":139.75104854,"geo_status":"db","era":"19世紀初期","year":1805,"year_source":"estimated","year_min":1801,"year_max":1810,"year_label":"19世紀初期","structure":"木造一間一戸薬医門，瓦葺，柱間2.8m，高さ4.6m，練塀左右総延長41.6m附属","structure_material":"木造一間一戸薬医門","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0043","desc":"増上寺境内の子院の一間一戸の薬医門と塀である。練塀は底部に間知石を置き，芯柱を用いずに土と瓦を交互に積み上げて壁体とする構造で，現在では用いられることがない。数多くの子院が集まって形成していた特異な都市景観を知るよすがとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000952"},{"id":"00010269","register_sub_id":"101","register_pk":"199042","name":"金剛院庫裏","kana":"こんごういんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都豊島区長崎1-28","lat":35.72717,"lng":139.695751,"geo_status":"db","era":"昭和9年／平成25年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積304㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0349","desc":"本堂南東側に渡り廊下を介して建つ。東西棟で六間取形式の庫裏と、座敷三室を直列させた客殿を矩の手に接続した平面を持つ。庫裏西正面に入母屋造の玄関を構え、客殿屋根に千鳥破風を飾る。屋根をゆるく起らせ、客殿主室に洗練された造作の座敷飾を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010269"},{"id":"00010268","register_sub_id":"101","register_pk":"199041","name":"金剛院本堂","kana":"こんごういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都豊島区長崎1-28","lat":35.72728,"lng":139.695563,"geo_status":"db","era":"昭和29年／平成25年改修","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積112㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"13-0348","desc":"方三間で宝形造の内陣の前面に、入母屋造で向拝付の外陣を構える。内陣は二重屋根頂部に相輪を戴き、軸部は円柱や皿斗付組物、高欄、軒支輪などを表す。外陣向拝には蟇股を飾る。古典建築の造形を単純化しつつ引用してまとめた鉄筋コンクリート造の寺院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010268"},{"id":"00015156","register_sub_id":"101","register_pk":"530580","name":"西徳寺本堂","kana":"さいとくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区竜泉一丁目74-1","lat":35.72340278,"lng":139.790375,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積445㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"13 - 0514","desc":"国際通り沿いに位置する浄土真宗寺院の本堂。設計は島田藤。基壇上に東面して建つ、鉄筋コンクリート造入母屋造本瓦葺で正面の大階段上に３間向拝を付す。軒は二軒繁垂木、持送りで出桁を受け軒天井を張る。軒廻りや縁高欄など斬新な外観意匠の震災復興本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015156"},{"id":"00003202","register_sub_id":"101","register_pk":"104192","name":"実相寺本堂","kana":"じっそうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都大田区池上2-10-17","lat":35.580021,"lng":139.702911,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、金属葺、建築面積187㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0146","desc":"大正末に浅草より移転。正面６間，側面６間，入母屋造平入，正面向拝付で，側廻柱上に舟肘木を置く。内部は奥中央を内陣，両脇を位牌所とし，内陣前に外陣，両脇客殿を配し，正面及び両側面に畳縁を回す。平面や細部意匠に近代の日蓮宗寺院本堂の展開を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003202"},{"id":"00003203","register_sub_id":"101","register_pk":"104193","name":"実相寺門","kana":"じっそうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都大田区池上2-10-17","lat":35.579906,"lng":139.702728,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、金属葺、間口3.6m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0147","desc":"本堂の前方に通りに南面して建つ。大型の薬医門で軒は二軒半繁垂木とする。柱上組物肘木、男梁、女梁の先端に派手な繰型を付け、冠木上に特徴ある異形の虹梁を架ける。欅材による上質な造りであるとともに、池上本門寺門前に広がる寺町景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003203"},{"id":"00014142","register_sub_id":"101","register_pk":"508772","name":"常行院納骨堂","kana":"じょうぎょういんのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都港区芝公園二丁目11-1","lat":35.65657222,"lng":139.75080833,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積33㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"13-0460","desc":"増上寺の東に位置する寺院の納骨堂。鉄筋コンクリート造、入母屋造桟瓦葺妻入、主体部は太い円柱に長押を廻して花頭窓を設け、唐破風の向拝は角柱で虹梁や蟇股で飾る。内部は一室で地下に納骨棚を備える。重厚な意匠の近代仏堂で、山内寺院の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014142"},{"id":"00011894","register_sub_id":"101","register_pk":"211138","name":"上宮寺鐘楼","kana":"じょうぐうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都渋谷区広尾五丁目2-2","lat":35.650486,"lng":139.719945,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、面積6.2㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-391","desc":"境内の北西隅に南北棟で建つ。方一間、吹放ち形式で、切妻造とする。切石積基壇上に建ち、礎石と礎盤の上に几帳面取の角柱を四方転びで立てる。台輪を置き、三斗で軒を支え、妻面は虹梁上に蟇股で棟木を支える。細部意匠が良質で境内の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011894"},{"id":"00011892","register_sub_id":"101","register_pk":"211136","name":"上宮寺本堂","kana":"じょうぐうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都渋谷区広尾五丁目2-2","lat":35.650522,"lng":139.720162,"geo_status":"db","era":"大正3年／平成17年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積254㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-389","desc":"広尾駅西方にあり西面する真宗寺院本堂。入母屋造妻入で、起り屋根の向拝を突出させる。妻飾の二重虹梁大瓶束や兎毛通しの彫刻で正面を飾る。広い外陣をもち余間左脇に稚子之間を設け、背面に座敷飾りを備えた二室を突出し細長い境内に応じた平面を採る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011892"},{"id":"00011893","register_sub_id":"101","register_pk":"211137","name":"上宮寺本堂応接部","kana":"じょうぐうじほんどうおうせつぶ","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都渋谷区広尾五丁目2-2","lat":35.650421,"lng":139.720165,"geo_status":"db","era":"大正3年頃／平成17年改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"13-390","desc":"本堂の南に廊下を挟んで南北棟で接続する。入母屋造の玄関を張り出し、前室を介して三室を矩折れに配し、内庭に面する東側に畳廊下を付ける。長押を廻らすが、座敷飾りは設けず、簡明な意匠とする。玄関には櫛形欄間を設け落ち着いた表構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011893"},{"id":"00002522","register_sub_id":"101","register_pk":"103512","name":"常照院本堂内陣","kana":"じょうしょういんほんどうないじん","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都港区芝公園1-8-9","lat":35.657635,"lng":139.752014,"geo_status":"db","era":"明和6","year":1769,"year_source":"db","year_min":1769,"year_max":1769,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積25㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0115","desc":"常照院は芝増上寺の子院のひとつ。内陣はもと念仏堂で，戦災を免れ，後に外陣などを加えて本堂の体裁を整えた。方２間半の土蔵造で，正面には重厚な観音扉を設ける。内部は後方に構えた仏壇・厨子，黒漆塗の格天井など，華やかで濃密な空間をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002522"},{"id":"00002525","register_sub_id":"101","register_pk":"103515","name":"心光院表門","kana":"しんこういんおもてもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都港区東麻布1-1-5","lat":35.65802985,"lng":139.74438216,"geo_status":"db","era":"寛保3／昭和25移築","year":1743,"year_source":"db","year_min":1743,"year_max":1743,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0118","desc":"心光院は増上寺別院のひとつ。昭和２５年，戦災を免れた表門とともに現在地に移った。１間１戸四脚門で，屋根本瓦葺，柱はすべて同高になる。軒廻りを２軒吹寄垂木とし，桁行の頭貫を成の高い虹梁型とした特徴があり，別院の門の造形の一端を現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002525"},{"id":"00011480","register_sub_id":"101","register_pk":"210446","name":"心光院本堂","kana":"しんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都港区東麻布一丁目1-1","lat":35.65815806,"lng":139.74447306,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"13-0374","desc":"第二次大戦の空襲で本堂を焼失し、昭和二五年に区画整理で現在地に移転後再建されたもの。木造平屋建、入母屋造桟瓦葺で、柱はヒノキで内陣及び須弥壇後方のみ円柱とする。全体を伝統的な手法でまとめるが、西面の格子ガラス窓などに近代的な要素も併せ持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011480"},{"id":"00004216","register_sub_id":"101","register_pk":"105206","name":"田無神社参集殿","kana":"たなしじんじゃさんしゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都西東京市田無町3-7-4","lat":35.72954772,"lng":139.54383543,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"13 － 0179","desc":"二ノ鳥居の西に，参道を介して社務所と向かい合って建つ。玄関は式台構とし，取次の間の北側に座敷が東西に三室並ぶ。床の間を神殿に見立てた上座敷の意匠，透彫の欄間，磨き丸太の縁桁等を特徴とする近代和風建築。設計は内務省関連の建築家と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004216"},{"id":"00003195","register_sub_id":"101","register_pk":"104185","name":"椿山荘三重塔","kana":"ちんざんそうさんじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都文京区関口2-10-8","lat":35.71251945,"lng":139.72460582,"geo_status":"db","era":"室町末期／大正14移築","year":1556,"year_source":"estimated","year_min":1540,"year_max":1573,"year_label":"室町末期","structure":"木造三重塔、銅板葺、建築面積29㎡","structure_material":"木造三重塔","registered":"2003.03.18(平成15.03.18)","register_no":"13 － 0139","desc":"広島県竹林寺に創建され大正１４年に藤田男爵邸（現椿山荘）に移築。和様を基調に各部に禅宗様を加味し，組物は三手先，軒は各層とも本繁平行垂木。移築時に軸部が改造されたが，外観は細部に至るまで本格的な構成をよくとどめ，苑内の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003195"},{"id":"00015417","register_sub_id":"101","register_pk":"533432","name":"東京カテドラル鐘塔","kana":"とうきょうかてどらるしょうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和中","pref":"東京都","address":"東京都文京区関口三丁目19-1","lat":35.71429722,"lng":139.72605833,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造、高さ62m、建築面積12㎡","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0526","desc":"大聖堂の南に聳える鉄筋コンクリート造、高さ62メートルの鐘塔。平面は変形の菱形で立面は上部を逓減させた鋭い形状。頂部は矩形に刳抜いて４つの鐘を吊り、上部に立てる突芯先端は十字架を象る。大聖堂脇に並び建ち、丹下健三の独創性が発揮された鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015417"},{"id":"00015416","register_sub_id":"101","register_pk":"533431","name":"東京カテドラル聖マリア大聖堂","kana":"とうきょうかてどらるせいまりあだいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都文京区関口三丁目19-1","lat":35.71426944,"lng":139.72658056,"geo_status":"db","era":"昭和39年／平成19年改修","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"鉄筋コンクリート造地上2階地下1階建、建築面積2，554㎡","structure_material":"鉄筋コンクリート造地上2階地下1階建","registered":"2025.08.06(令和7.08.06)","register_no":"13 - 0525","desc":"目白台に位置する教会の大聖堂。８枚のＨＰシェルを立てかけた外観とし、各壁の境界となるガラス面が天頂部の十字架状トップライトへ繋がる。大理石床と膨らみあるコンクリート打放の壁で構成した内部へ天頂部から柔らかな光が注ぐ。丹下健三の代表作の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015416"},{"id":"00002220","register_sub_id":"101","register_pk":"103210","name":"日本基督教団根津教会","kana":"にほんきりすときょうだんねづきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区根津1-19-6","lat":35.719143,"lng":139.762894,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造平屋建、瓦一部金属板葺、建築面積185㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"13 － 0104","desc":"根津神社の門前町の一画に位置する。木造平屋建，切妻造，下見板張の教会堂で，北西隅に玄関，北東隅に聖壇を置く非対称の平面構成に特徴があり，尖頭アーチの窓を開けた切妻の妻面と玄関部のトンガリ屋根を載せた角塔が地域のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002220"},{"id":"00002221","register_sub_id":"101","register_pk":"103211","name":"日本基督教団根津教会門及び塀","kana":"にほんきりすときょうだんねづきょうかいもんおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区根津1-19-6","lat":35.71923437,"lng":139.76288307,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"煉瓦造、間口3.6m、塀延長7.8m","structure_material":"煉瓦造","registered":"2001.08.28(平成13.08.28)","register_no":"13 － 0105","desc":"敷地の北辺を区切る煉瓦造の門と塀。会堂側の塀は会堂妻面が道路から見えるように低く造り，玄関側には，礼拝堂玄関用と談話室玄関用の門として３基の門柱を建てる点に特徴がある。会堂の白と煉瓦の赤がコントラストをなし，地域のシンボルともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002221"},{"id":"00003531","register_sub_id":"101","register_pk":"104521","name":"日本基督教団富士見丘教会","kana":"にほんきりすときょうだんふじみがおかきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都世田谷区代沢2-32-2","lat":35.65920128,"lng":139.67025628,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積262㎡","structure_material":"木造2階建","registered":"2003.09.19(平成15.09.19)","register_no":"13 － 0162","desc":"木造，２階建で，切妻造，東西棟の主体部南西に塔屋を付属する。礼拝堂は中央を広く取って身廊と側廊とに分け，東奥に聖壇を構える。全体に質素平明な意匠だが，外部の薔薇窓風レリーフや塔屋頂部のバトルメント，内部のハンマービームトラスなど要所を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003531"},{"id":"00000953","register_sub_id":"101","register_pk":"101943","name":"日本基督教団本郷中央教会","kana":"にほんきりすときょうだんほんごうちゅうおうきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区本郷3-37-9","lat":35.70733133,"lng":139.76238566,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造３階建塔屋付，建築面積517㎡","structure_material":"鉄筋コンクリート造３階建塔屋付","registered":"1998.12.11(平成10.12.11)","register_no":"13 － 0044","desc":"「中央会堂」（明治２３年，伊藤為吉設計）として親しまれた建物の震災復興建築。春日通りに面し，階下を幼稚園，階上を礼拝堂に充てたゴシック様式による会堂で，東北隅に重厚な角塔を建ち上げる。設計は川崎忍，原案はヴォーゲルとされる。施工は辻組。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000953"},{"id":"00013966","register_sub_id":"101","register_pk":"508226","name":"日本基督教団弓町本郷教会","kana":"にほんきりすときょうだんゆみちょうほんごうきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"東京都","address":"東京都文京区本郷二丁目132-1","lat":35.70678056,"lng":139.75744444,"geo_status":"db","era":"大正15年／昭和28年・同44年・同61年、平成25年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリートブロック造4階建、建築面積321㎡、塔屋付","structure_material":"鉄筋コンクリートブロック造4階建","registered":"2021.10.14(令和3.10.14)","register_no":"13 - 0451","desc":"文京区市街地に建つ教会。外部は茶色の化粧ブロックで、半円アーチ窓を並べる。屋根は陸屋根で通り角地に塔屋を配す。設計者中村鎮が開発した中村式鉄筋コンクリートブロック構造による四階建の建築で、当時数多く開発された特殊ブロック造建築の優品の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013966"},{"id":"00007191","register_sub_id":"101","register_pk":"108173","name":"日本聖公会浅草聖ヨハネ教会","kana":"にほんせいこうかいあさくさせいよはねきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都台東区蔵前2-22-2他","lat":35.70364,"lng":139.792252,"geo_status":"db","era":"昭和4／昭和30改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造2階一部3階建、建築面積271㎡","structure_material":"鉄筋コンクリート造2階一部3階建","registered":"2008.07.08(平成20.07.08)","register_no":"13 － 0232","desc":"隅田川右岸の街区に位置する。西を正面とし、間口９．１ｍ奥行２２ｍのＲＣ造２階建の礼拝堂を北に、ＲＣ造３階建の談話室を南に設け、その間を階段室で繋ぐ。礼拝堂にはバットレスを付け、尖頭アーチ窓を開ける。ゴシック風意匠になるＲＣ造教会の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007191"},{"id":"00015297","register_sub_id":"101","register_pk":"532421","name":"日本聖公会東京教区東京聖十字教会聖堂","kana":"にほんせいこうかいとうきょうきょうくせいじゅうじきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都世田谷区若林四丁目220-5","lat":35.644875,"lng":139.65669167,"geo_status":"db","era":"昭和36年／平成14年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"13 - 0518","desc":"世田谷線松陰神社前駅に程近い閑静な住宅街に位置する聖堂。設計はレーモンド建築設計事務所。角柱状の集成材を内側に曲げてヴォールト形とした無柱の空間に、正面及び腰屋根に設けた窓のカラー膜から柔らかい光が注ぐ。祈りの場に相応しい静謐な空間を創出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015297"},{"id":"00004126","register_sub_id":"101","register_pk":"105116","name":"日本聖公会東京教区東京諸聖徒教会礼拝堂","kana":"にほんせいこうかいとうきょうきょうくとうきょうしょせいときょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都文京区千石2-18-4","lat":35.72389335,"lng":139.73908207,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、金属板葺、建築面積264㎡、鐘楼付","structure_material":"鉄筋コンクリート造2階建","registered":"2004.06.09(平成16.06.09)","register_no":"13 － 0175","desc":"関東大震災後，現在地への移転に伴い建設されたもの。設計は米国人建築家バーガミニ，施工は清水組。第二次世界大戦時に屋根部分を焼失しているが，戦後復興された。コンクリートの量感のある外観が特徴的で，尖塔と共に広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004126"},{"id":"00008824","register_sub_id":"101","register_pk":"162267","name":"日本バプテストキリスト教目白ヶ丘教会礼拝堂","kana":"にほんばぷてすときりすときょうめじろがおかきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"東京都","address":"東京都新宿区下落合2-416-3他","lat":35.71916051,"lng":139.70410665,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積299㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"13 － 0283","desc":"住宅地の角地に建つ礼拝堂。南北棟の切妻造で、鉄筋コンクリート造平屋建、建築面積299㎡に及ぶ。両側面に縦長窓を連続させ、東面北端には尖塔アーチ型の鐘楼を建てる。内部は大きな桁行のアーチで分割して独特の空間を造り、静謐な場とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008824"},{"id":"00009592","register_sub_id":"101","register_pk":"194588","name":"旗岡八幡神社絵馬殿","kana":"はたがおかはちまんじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都品川区旗の台3-852-1","lat":35.60452176,"lng":139.70834262,"geo_status":"db","era":"昭和3頃／昭和20頃・昭和37頃移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"13 － 0296","desc":"旗の台の高台にある境内南東隅に建つ。桁行三間梁間二間、入母屋造銅板葺で、下部を吹放し、小壁を竪板張とする。江戸時代には武士の崇敬を集め、近代に至るまで多くの絵馬が奉納された。木柄は細いが伸びやかで開放的。区内では戦災を免れた貴重な神社建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009592"},{"id":"00002524","register_sub_id":"101","register_pk":"103514","name":"妙定院上土蔵","kana":"みょうじょういんかみどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都港区芝公園4-9-8","lat":35.65396012,"lng":139.74683978,"geo_status":"db","era":"文化8","year":1811,"year_source":"db","year_min":1811,"year_max":1811,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0117","desc":"妙定院境内の東辺にあり，熊野堂の北側に建ち，近世後期の境内構成をよく伝えている。切妻造，桟瓦葺，妻入の２階建土蔵で，北面に観音扉を開き，戸前の庇を設ける。棟札より熊野堂より遅れて實譽宝観の時の上棟と判り，現在も収蔵庫として用いられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002524"},{"id":"00002523","register_sub_id":"101","register_pk":"103513","name":"妙定院熊野堂","kana":"みょうじょういんくまのどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都港区芝公園4-9-8","lat":35.65389289,"lng":139.74683122,"geo_status":"db","era":"寛政8","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積23㎡","structure_material":"土蔵造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"13 － 0116","desc":"妙定院は芝増上寺の子院のひとつで，旧山内の南辺，赤羽川沿いにある。熊野堂は棟札より二世・進譽仰願が起立主と判明する。寄棟造，妻入の土蔵造で，内部は前１間半を外陣，奥１間を内陣として仏壇を設ける。近世後期に広まった土蔵造小堂の良好な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002523"},{"id":"00002758","register_sub_id":"101","register_pk":"103748","name":"妙福寺祖師堂（旧七面大明神堂）","kana":"みょうふくじそしどう（きゅうしちめんだいみょうじんどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都大田区南千束2-2-7","lat":35.60129783,"lng":139.69162467,"geo_status":"db","era":"天保4","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"13 － 0130","desc":"もと天保４年再建の七面大明神堂で，後に曳屋されて祖師堂となった。前側を外陣，奥に内陣・内々陣を延ばした平面を持つ奥行の深い三間堂で，桟瓦葺の屋根は正面入母屋造，背面寄棟造になる。規模は小さいが，洗足池畔の景観のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002758"},{"id":"00009717","register_sub_id":"101","register_pk":"195546","name":"祐天寺表門","kana":"ゆうてんじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.637245,"lng":139.69646227,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.6m、左右潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0302","desc":"駒沢通りに面する境内北辺に建ち、仁王門の前面に位置する。高麗門、切妻造桟瓦葺で、建ちが高く、冠木と棟木の間に竪格子をはめる。左右には潜戸をつけ、雄大な構えをもつ。境内の表門として、都内に残る有力寺院に見合った格式ある構えを今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009717"},{"id":"00009715","register_sub_id":"101","register_pk":"195544","name":"祐天寺地蔵堂","kana":"ゆうてんじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.63729569,"lng":139.69677422,"geo_status":"db","era":"天明8／寛政12増築","year":1788,"year_source":"db","year_min":1788,"year_max":1788,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0300","desc":"正面三間側面五間で、正面寄棟造、背面入母屋造、向拝付とする。内部は内外陣に分けられ、背面一間をさらに虹梁等で区切って須弥壇を設け、厨子を安置する。内陣を折上格天井、外陣を江戸町火消の各組の纏を描いた格天井とし、内外陣境に欄間を嵌めて飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009715"},{"id":"00009716","register_sub_id":"101","register_pk":"195545","name":"祐天寺地蔵堂門","kana":"ゆうてんじじぞうどうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.6372243,"lng":139.69661241,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0301","desc":"地蔵堂の前方に西面して建つ薬医門で、左右袖塀付。組物等の絵様刳形は時代相応のもので、妻飾では虹梁上の邪鬼で化粧棟木を受ける。天井の鏡板に火消組の纏七種を陽刻する独創的な意匠で、地蔵堂が江戸町火消の信仰と密接に結びついていたことを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009716"},{"id":"00009714","register_sub_id":"101","register_pk":"195543","name":"祐天寺書院","kana":"ゆうてんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.63633914,"lng":139.69672901,"geo_status":"db","era":"明治28／平成21改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積329㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0299","desc":"本堂西方に北面する東西棟の寄棟造で、正面中央に玄関を構える。西寄りを板間とし、東側には前後二列に三室ずつ配る。南側の庭に面して主たる三室を並べ、東端室には大振りのトコと違棚を構え、風格ある座敷をなしている。都内では数少ない大規模書院の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009714"},{"id":"00012304","register_sub_id":"101","register_pk":"531628","name":"祐天寺鐘楼","kana":"ゆうてんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒五丁目1067-1","lat":35.63681667,"lng":139.69648056,"geo_status":"db","era":"享保14年(1729)／昭和7年改修","year":1729,"year_source":"db","year_min":1729,"year_max":1729,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"13-410","desc":"本堂北西方に位置する。桁行を広めた方一間吹放ち形式で、軒を一軒繁垂木とし、東西棟で切妻造、本瓦形銅板葺の屋根をかける。組物は三斗組、中備は木鼻付平三斗であり、妻面に虹梁をかけ笈形付大瓶束で飾る。細部絵様に江戸中期の意匠を示す鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012304"},{"id":"00009713","register_sub_id":"101","register_pk":"195542","name":"祐天寺本堂","kana":"ゆうてんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.6365057,"lng":139.69700741,"geo_status":"db","era":"万延元／明治27移築・明治31・明治45増築・昭和35・平成21改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積379㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0298","desc":"万延元年に宝形造の内々陣、明治三一年に入母屋造の外陣、同四五年にそれらを繋ぐ内陣を設けて複合する。内々陣の室内は出組に折上格天井とし、幕末に活躍した絵師による草花図等で飾る。内陣と外陣は一体的な大空間となって、格調ある室内空間を実現する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009713"},{"id":"00009718","register_sub_id":"101","register_pk":"195547","name":"祐天寺水屋","kana":"ゆうてんじみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都目黒区中目黒5-1067-1","lat":35.63685786,"lng":139.69670283,"geo_status":"db","era":"弘化3","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造、銅板葺、面積3.0㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0303","desc":"本堂と仁王門の間に南北棟で建つ。方一間、入母屋造銅板葺で、角柱を内転びに立て、四方を吹き放つ。頭貫を虹梁様とし、隅と中備に三斗を置いて丸桁を受け、ケヤキの板支輪で折上天井を支える。天井中央に龍の丸彫を飾るなど、要所の彫刻も目を引く秀作である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009718"},{"id":"00014773","register_sub_id":"101","register_pk":"519031","name":"大山寺本堂","kana":"おおやまでらほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県伊勢原市大山字宝珠山727","lat":35.42930278,"lng":139.23936944,"geo_status":"db","era":"明治18年／昭和42年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積248㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"14 - 0341","desc":"大山の中腹に東面して建つ真言宗寺院本堂。桁行五間梁間五間、入母屋造瓦型銅板葺。前二間を外陣、後三間を内陣と脇陣に画す密教系本堂で、太い柱が林立し雄大。正面の軒唐破風付向拝は木鼻の龍を始め彫刻が横溢し圧巻。大山詣の隆盛を伝える大型の近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014773"},{"id":"00002623","register_sub_id":"101","register_pk":"103613","name":"正眼寺庫裏","kana":"しょうげんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県足柄下郡箱根町湯本562","lat":35.22855388,"lng":139.10029684,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、亜鉛鉄板葺、建築面積147㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"14 － 0067","desc":"東西に長い敷地の西側に位置する。銅板瓦棒葺，入母屋造，平入とし，前面に縁を廻し，真壁造とする。本堂に繋がる渡廊下が，内部の廊下と接続し，ほぼ中廊下式の平面を構成する。北東隅の八畳間に付書院を設ける。本堂と並列し，境内の景観に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002623"},{"id":"00010943","register_sub_id":"101","register_pk":"208914","name":"清浄光寺石垣及び築地塀","kana":"しょうじょうこうじいしがきおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.34696389,"lng":139.48723611,"geo_status":"db","era":"江戸末期／大正15頃改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石垣 石造、総延長53m 築地塀 土塀、瓦葺、総延長22m","structure_material":"石垣 石造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0216","desc":"境内南入口に建つ総門の東西に矩折れにのびて、門前の広場を区画する。安山岩切石を高さ一・九メートルに精緻に布積し、上端に延石を廻らせる。築地塀は惣門の東西方向のみ残る。熨斗瓦を丁寧に配し、屋根に桟瓦を葺く。近世以来の門前の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010943"},{"id":"00010939","register_sub_id":"101","register_pk":"208910","name":"清浄光寺宇賀神社","kana":"しょうじょうこうじうがじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.349198,"lng":139.488459,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0212","desc":"境内北奥に鎮座する。正面一間側面二間の前面に向拝を付け、全体に入母屋造妻入、軒唐破風付の屋根をかける。正背面の妻破風を火灯枠風とし、水引虹梁に籠彫持送を付し、上面に蓑束を立てて菖蒲桁を受けるなど特異性を示す。向拝廻りを彫刻で濃密に飾る境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010939"},{"id":"00010938","register_sub_id":"101","register_pk":"208909","name":"清浄光寺回向堂","kana":"しょうじょうこうじえこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348834,"lng":139.488646,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0211","desc":"本堂北西方の高台に建つ、方一間裳階付の堂。屋根は宝形造銅板葺で、内部は床張の一室として身舎に折上小組格天井を張る。細部は和様基調で組物は身舎出組、裳階三斗とし、仏壇上に中世風意匠の蟇股を飾る。丁寧なつくりの堂で、境内に静謐さを醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010938"},{"id":"00010936","register_sub_id":"101","register_pk":"208907","name":"清浄光寺小書院","kana":"しょうじょうこうじこじょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.349088,"lng":139.487642,"geo_status":"db","era":"明治前期／昭和前期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0209","desc":"御番方後方の山裾に渡廊下を介して建ち、遊行上人の公式法務や賓客接待に使用される。東西棟の寄棟造銅板葺で、内部は南北二列に三室ずつ並べ、両列とも西奥室に床を構えて周囲に縁を廻らし、対面所風の平面を持つ。開放的で、細部造作に気品を備えた書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010936"},{"id":"00010935","register_sub_id":"101","register_pk":"208906","name":"清浄光寺御番方","kana":"しょうじょうこうじごばんかた","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348771,"lng":139.487759,"geo_status":"db","era":"大正2／昭和前期改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積226㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0208","desc":"境内北西を占める住居部の正面中央に建つ。入母屋造銅板葺で、正面の軒唐破風付の大振りな入母屋玄関は精緻な彫刻で飾り、遊行上人の出立などに用いる。内部は六間取方丈形式で、上間奥室に床などの座敷飾りを備える。寺格に相応しい品格を備えた接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010935"},{"id":"00010940","register_sub_id":"101","register_pk":"208911","name":"清浄光寺鐘楼","kana":"しょうじょうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348318,"lng":139.488216,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、銅板葺、面積11㎡","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0213","desc":"本堂南西の苑路沿いの石積基壇上に東西棟で建つ。方一間、吹放し形式の鐘楼で、切妻造銅板葺である。八角の四本柱を内転びに立てて貫三段で固め、三斗を組み、両妻の絵様虹梁上の大瓶束で棟木を受ける。内部は格天井を張る。境内中枢部の景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010940"},{"id":"00010942","register_sub_id":"101","register_pk":"208913","name":"清浄光寺惣門","kana":"しょうじょうこうじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.34695833,"lng":139.48740556,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、銅板葺、間口5.0m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0215","desc":"境内の南端入口に建つ大型の冠木門。本柱は見付〇・七メートルの面取角柱を間口五メートルに立て、上端を頭巾金物で覆う。控柱との間を貫で固め、小屋根を架けて高麗門風とする。高さ七・二メートルを測る黒色の正門で、塀と共に古刹の門前に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010942"},{"id":"00010941","register_sub_id":"101","register_pk":"208912","name":"清浄光寺手水舎","kana":"しょうじょうこうじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.347958,"lng":139.488464,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0214","desc":"本堂前方に南北棟で建つ。方一間吹放し形式で、切妻造桟瓦葺。几帳面取角柱を内転びに立て、頭貫と台輪を廻らし、出組を詰組とする。妻飾りは二重虹梁大瓶束に流水の笈形を飾る。頭貫木鼻を籠彫とし、中備を鳥獣等の彫物とするなど、精緻な彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010941"},{"id":"00010937","register_sub_id":"101","register_pk":"208908","name":"清浄光寺百間廊下","kana":"しょうじょうこうじひゃっけんろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.34878528,"lng":139.48835727,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0210","desc":"本堂と御番方を繋ぐ長い廊下で、境内の起伏により勾配や段差をもち、屈曲してのびる。梁間一間の切妻造桟瓦葺で、漆喰塗外壁に長押を廻らし、火灯窓を並べる。要所に御廟所や宇賀神社の礼拝所を備え、宗教施設としての性格も備えており、境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010937"},{"id":"00010934","register_sub_id":"101","register_pk":"208905","name":"清浄光寺本堂","kana":"しょうじょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市西富一丁目208","lat":35.348438,"lng":139.488671,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積841㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0207","desc":"境内奥寄りに南面する、入母屋造で桁行梁間とも三〇メートル規模の大堂。内陣の三面に広い外陣と脇陣を配する時宗本堂の特徴を示し、各陣とも高く格天井を張り広壮な内部を創る。正面の向拝や内部小壁の彫刻も秀逸で、総本山寺院らしい荘厳と華麗さを備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010934"},{"id":"00014577","register_sub_id":"101","register_pk":"515119","name":"總持寺仮真殿","kana":"そうじじかりしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見二丁目2119","lat":35.50633889,"lng":139.66918333,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0326","desc":"能登から鶴見への本山移転に際し真牌を祀った開山堂で現在は位牌堂。入母屋造平入桟瓦葺、正面側に切妻造相の間を設け、擬宝珠高欄付階段とその両側の廊下で信徒位牌堂と繋がる独特な構成。内部は一室で格天井と位牌壇を備え、背面で納骨堂の常照殿と繋がる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014577"},{"id":"00004713","register_sub_id":"101","register_pk":"105703","name":"總持寺香積台","kana":"そうじじこうしゃくだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50641859,"lng":139.67150828,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階建、瓦葺、建築面積814㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0094","desc":"伽藍中心部の南東に位置し，禅宗寺院のいわゆる庫裏に相当する。西面して建つ大規模な２階建で，１階は事務室，２階は大広間とする。瓦葺，切妻造，妻入で，正面には切妻造の玄関を備え，妻壁に虹梁・蟇股・窓を巧みに配し，豪放な外観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004713"},{"id":"00004718","register_sub_id":"101","register_pk":"105708","name":"總持寺虎嘯窟","kana":"そうじじこしょうくつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506763,"lng":139.669312,"geo_status":"db","era":"安政年間／明治44移築","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政年間","structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0099","desc":"仏殿の西方に南面して建つ貫首の居住施設。寄棟造，桟瓦葺，吹放しの庇を架ける。内部は１５畳と１７．５畳の座敷を東西に並べ，東・南・西の３方を畳敷広縁とする。各室とも床・棚を備え，蟻壁を廻し，彫刻欄間や彩色板戸を用いるなど，丁寧な書院造になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004718"},{"id":"00014578","register_sub_id":"101","register_pk":"515120","name":"總持寺虎嘯窟渡廊下","kana":"そうじじこしょうくつわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見二丁目1878-3","lat":35.50664444,"lng":139.66918889,"geo_status":"db","era":"明治44年頃","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"14 - 0327","desc":"放光堂と虎嘯窟を矩折に繋ぐ渡廊下。切妻造桟瓦葺、組物舟肘木、真壁造格子窓腰板張とする。虎嘯窟側に玄関を屋根葺下ろしで設け、放光堂寄り二間を二重虹梁蟇股として屋根を切上げ、床組み太鼓橋状にして床下を通路とする。貫首が使用した造りの良い渡廊下。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014578"},{"id":"00004716","register_sub_id":"101","register_pk":"105706","name":"總持寺御霊殿","kana":"そうじじごれいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50757924,"lng":139.66974521,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0097","desc":"仏殿の後方にあり，後醍醐天皇像を祀る。南から拝殿・幣殿・奥殿が連続し，組物や中備蟇股を備えた社殿建築。奥殿はもこし付の入母屋造，ほぼ方３間の拝殿は，正面の縁を広くして庇柱を建てて縋破風とし，さらに１間向拝を設け，独特な権現造風の構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004716"},{"id":"00004712","register_sub_id":"101","register_pk":"105702","name":"總持寺三松関","kana":"そうじじさんしょうかん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50574663,"lng":139.67338666,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"門 木造、瓦葺、間口6.4m、番所 木造平屋建、瓦葺、建築面積45㎡","structure_material":"門 木造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0093","desc":"東面して建つ切妻造，本瓦葺の１間高麗門で，両側に潜門を設け，北には真壁造，平屋建の小規模な番所が接続し，南には築地塀が延びる。門は総欅造で，細部のつくりも丁寧で充実し，間口６．４ｍの規模を持ち，伽藍の入口を飾るに相応しい雄大な構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004712"},{"id":"00004726","register_sub_id":"101","register_pk":"105716","name":"總持寺三宝殿","kana":"そうじじさんぽうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50443924,"lng":139.67256431,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0107","desc":"低い基壇上に建つ入母屋造，桟瓦葺，妻入の建物で，伽藍の南方にある。１２畳大の前室と，最奥に祭神を祀る２４畳大の部屋からなる。この３方には縁を廻し，前面には円柱をたて，吹放しで舟底天井とした空間と１間の向拝を設ける。独特な構成になる社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004726"},{"id":"00004715","register_sub_id":"101","register_pk":"105705","name":"總持寺紫雲台","kana":"そうじじしうんだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.507252,"lng":139.671692,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積820㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0096","desc":"伽藍中心の東にあり，僧侶・檀信徒等の会見に使われる施設。西面して建つ入母屋造で，軒唐破風付の向拝を設け，４周に縁を廻す。桁行１８間半で，軸部もたちが高く，外観は壮大な構成を見せ，大小に間仕切られた内部は，低平で落ち着いた書院造の空間になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004715"},{"id":"00004720","register_sub_id":"101","register_pk":"105710","name":"總持寺鐘鼓楼","kana":"そうじじしょうくろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.5062276,"lng":139.66961599,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積16㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0101","desc":"放光堂と衆寮の間にある。桁行３間，梁間２間，入母屋造，桟瓦葺の楼造で，１・２階とも平面は同大で通柱とし，１階を通路，化粧屋根裏の２階中央に鐘を吊る。古風な高欄付縁や連子窓などと，禅宗様の双折桟唐戸や花頭窓，吹寄の垂木を巧妙に調和させている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004720"},{"id":"00004721","register_sub_id":"101","register_pk":"105711","name":"總持寺衆寮","kana":"そうじじしょうりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50605717,"lng":139.66980462,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積373㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0102","desc":"伽藍中心部，仏殿の南西に東面して建つ。ほぼ方形平面とした入母屋造，桟瓦葺で，内部は基本的に土間で，壁際に畳敷の床を設け，高く棹縁天井を張る。軒は１軒疎垂木，軸部は角柱，側廻りに舟肘木を配し，舞良戸を多用するなど，簡明な住宅建築の形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004721"},{"id":"00004725","register_sub_id":"101","register_pk":"105715","name":"總持寺鐘楼","kana":"そうじじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.504559,"lng":139.672028,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、瓦葺、建築面積30㎡","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0106","desc":"伽藍の南方，基壇上に建つ切妻造，本瓦葺の吹放し鐘楼。方形の平面で，各辺は中央２，両側１の比で円柱を配し，隅部外側に角柱を斜めにたてる。軸部は挿肘木や貫を巧妙に駆使し，木鼻や蟇股などの装飾細部を要所に設ける。卓越した造形感覚が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004725"},{"id":"00004722","register_sub_id":"101","register_pk":"105712","name":"總持寺大僧堂","kana":"そうじじだいそうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50574255,"lng":139.66983865,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積688㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0103","desc":"衆寮の南，壇正積基壇に東面して建つ。入母屋造，瓦棒銅板葺，内部は土間で，４周側廻りを通路，内側の壁際等には座禅用の畳敷の床を設ける。棹縁天井を張るが，中央２本の独立円柱上には独特な挿肘木を組む。花頭窓，弓欄間など，禅宗様の建築細部を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004722"},{"id":"00004714","register_sub_id":"101","register_pk":"105704","name":"總持寺待鳳館","kana":"そうじじたいほうかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506851,"lng":139.671509,"geo_status":"db","era":"大正4／昭和32移築改造","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1100㎡、正面車寄付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0095","desc":"香積台の北側にある迎賓館施設。主体部は大正４年竣工の尾張徳川家旧書院を移築したもので，これに関東大震災で被災した大正元年竣工の建物の玄関部を附属する。玄関部は唐破風造で，主体部は良材を用いた端正なつくりになり，床・棚の座敷飾も充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004714"},{"id":"00004727","register_sub_id":"101","register_pk":"105717","name":"總持寺放光観音台座","kana":"そうじじひかりかんのんだいざ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50479054,"lng":139.66959827,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"石造、面積43㎡","structure_material":"石造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0108","desc":"伽藍の南西方にある高７尺の花崗岩製台座。基底部は方形平面で，隅に変化をもたせ，その中心に六角形平面で内転びの台座本体を載せる。下部は刳型が繋がり，中央部の各面には梵字を飾り，頂部隅には花弁型装飾をつけるなど，細部まで行き届いた造形になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004727"},{"id":"00004723","register_sub_id":"101","register_pk":"105713","name":"總持寺百間廊下及び門","kana":"そうじじひゃっけんろうかおよびもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50624021,"lng":139.67051858,"geo_status":"db","era":"大正4頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積514㎡、門3所付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0104","desc":"仏殿の南方にある。東西方向の桁行１４２ｍ，梁間３．６ｍで，間に３つの門を設ける。廊下は角柱に舟肘木をのせ，虹梁で繋ぎ，柱間にガラス戸を入れる。各門は桁行１間梁間１間，切妻造で，桟瓦葺屋根を架ける。仏殿前面の空間を効果的に分節する役割をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004723"},{"id":"00004717","register_sub_id":"101","register_pk":"105707","name":"總持寺仏殿（大雄宝殿）","kana":"そうじじぶつでん（だいゆうほうでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506985,"lng":139.669968,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積475㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0098","desc":"伽藍中心部，壇正積基壇上に南面して建つ。方３間，１重もこし付で，入母屋造，本瓦葺，身舎は尾垂木付の３手先組物とする。身舎に比べもこしの柱間を狭くし，内部空間を中央に建つ柱２本で前後に区分するなど，創意工夫を凝らし，内外とも荘厳な構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004717"},{"id":"00004719","register_sub_id":"101","register_pk":"105709","name":"總持寺放光堂","kana":"そうじじほうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.506409,"lng":139.669388,"geo_status":"db","era":"安政年間／明治44移築","year":1856,"year_source":"estimated","year_min":1854,"year_max":1859,"year_label":"安政年間","structure":"木造平屋建、瓦葺、建築面積650㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0100","desc":"檀信徒の位牌を祀る建物で，仏殿西方に東面して建つ。入母屋造，桟瓦葺，桁行３０ｍに及ぶ雄大な規模を持つ。内部は正面１間通りを土間とし，床上部は奥中央に仏壇，左右に位牌壇を構え，広大な空間をつくる。各部の彫物や虹梁の絵様に幕末期の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004719"},{"id":"00004724","register_sub_id":"101","register_pk":"105714","name":"總持寺向唐門","kana":"そうじじむかいからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県横浜市鶴見区鶴見2-1-1","lat":35.50581635,"lng":139.6708507,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造、檜皮葺、間口6.2m、袖塀63m付","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"14 － 0105","desc":"仏殿の南，百間廊下の前面にある。切妻造，檜皮葺の四脚門で，前後に唐破風を付ける。木鼻や頭貫など彫りの深い細部を備え，両側面の花狭間や組物間彫物などを精緻につくる。桁行約６ｍと大規模で，両側に築地塀が延び，仏殿前方の重厚な景観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004724"},{"id":"00010947","register_sub_id":"101","register_pk":"208918","name":"高部屋神社拝殿及び幣殿","kana":"たかべやじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県伊勢原市下糟屋2202","lat":35.406348,"lng":139.320448,"geo_status":"db","era":"慶応元（1865）","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、茅葺一部銅板葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0220","desc":"本殿前面に建ち、桁行三間梁間二間、入母屋造茅葺の拝殿正面に向拝を付し、背面に幣殿を張出す。特に向拝廻りでは、虹梁の浮彫で亀付の渦紋、菖蒲桁下部から向拝柱頂部に巻き付く龍彫刻など、躍動的で濃密な彫刻で飾り、彫物大工後藤家の力量を発揮している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010947"},{"id":"00010946","register_sub_id":"101","register_pk":"208917","name":"高部屋神社本殿","kana":"たかべやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県伊勢原市下糟屋2202","lat":35.406464,"lng":139.320471,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0219","desc":"境内奥に南面する五間社流造で、三方に縁を廻らして脇障子をたて、前面に浜床を設ける。関東大震災倒壊後の再建時に、身舎柱や正面建具、蟇股、擬宝珠など、正保四年建立の旧社殿の部材を再用する。震災復興造営の一例を示し、県内で希少な五間社社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010946"},{"id":"00010949","register_sub_id":"101","register_pk":"208920","name":"日本基督教団大磯教会門柱及び塀","kana":"にほんきりすときょうだんおおいそきょうかいもんちゅうおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県中郡大磯町大磯字茶屋町1348-1","lat":35.30718976,"lng":139.31375641,"geo_status":"db","era":"昭和12頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"門柱 コンクリート造、間口2.0m 塀 コンクリート造、総延長5.0m","structure_material":"門柱 コンクリート造","registered":"2016.02.25(平成28.02.25)","register_no":"14-0222","desc":"東海道に面する敷地を画す間口二メートルの門柱一対と、左右に屈曲してのびる塀で、コンクリート造、人造石洗出し仕上げとする。門柱は唐戸面を施し、頂部に三筋の溝を表す。塀は束間にアーチ形の開口を設け、要石風の飾りを付け、アール・デコ風に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010949"},{"id":"00010948","register_sub_id":"101","register_pk":"208919","name":"日本基督教団大磯教会礼拝堂","kana":"にほんきりすときょうだんおおいそきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県中郡大磯町大磯字茶屋町1348-1","lat":35.306991,"lng":139.313707,"geo_status":"db","era":"昭和12／昭和25改修","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"14-0221","desc":"東海道旧大磯宿の短冊形敷地前寄りに北面して建つ。正面中央と左右に切妻造の張出しを設けて正面に尖塔アーチの玄関を構える。内部は単廊式で奥にゴシック風アーチの祭壇を設ける。外壁は下見板張で、旧宿場の近代的景観に寄与する木造教会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010948"},{"id":"00003204","register_sub_id":"101","register_pk":"104194","name":"日本基督教団横須賀上町教会・付属めぐみ幼稚園","kana":"にほんきりすときょうだんよこすかうわまちきょうかい・ふぞくめぐみようちえん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県横須賀市上町2-43","lat":35.27243625,"lng":139.67011517,"geo_status":"db","era":"昭和5頃／昭和25増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積187㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2003.03.18(平成15.03.18)","register_no":"14 － 0074","desc":"市中心部に近い住宅街に建設され，上町教会の名で親しまれている教会建築。外装下見板張で，尖頭アーチ型の上げ下げ窓を礼拝堂の各側面に配する。切妻屋根の道路側に設けられた塔屋に十字架を掲げ，歴史的な街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003204"},{"id":"00008428","register_sub_id":"101","register_pk":"134824","name":"寶金剛寺庫裏","kana":"ほうこんごうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県小田原市国府津字八幡上2038他","lat":35.28565845,"lng":139.20813814,"geo_status":"db","era":"寛政12年（1800）／昭和33年改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"14 － 0168","desc":"旧東海道に近い山裾に所在し、庫裏は境内奥に西面して建つ。桁行一二メートル梁間一二メートル、切妻造桟瓦葺である。南寄りの玄関後方に座敷を並べ、北側に豪壮な軸組を現した大広間を配する。県下に類例の少ない近世の真言宗寺院庫裏である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008428"},{"id":"00014339","register_sub_id":"101","register_pk":"511328","name":"本覚寺大門","kana":"ほんがくじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目303-2","lat":35.31776111,"lng":139.55247222,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口3.2m、両袖脇透塀付","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0317","desc":"本堂北の小路に開く門。一間一戸の高麗門で門扉を省略する。切妻造桟瓦葺、両側面に袖壁を付す。軸部は円柱の親柱を立てて内法に梁を渡し、二段の絵様肘木で丸桁を支持する。袖壁は腰を板壁、腰貫上を縦格子窓。境内北辺を画し、寺院の風格を示す木太い門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014339"},{"id":"00014333","register_sub_id":"101","register_pk":"511322","name":"本覚寺客殿","kana":"ほんがくじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31713611,"lng":139.55274167,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0311","desc":"本堂の南東に北面する客殿。入母屋造桟瓦葺の東西棟で、北面東寄りに入母屋造妻入の式台玄関を付し、銅板葺の庇を三方に巡らす。内部は１０畳の座敷を三室並べ、西側を上座敷として床構えを設ける。関東大震災後の再建で、伽藍中枢の景観をつくる広壮な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014333"},{"id":"00014334","register_sub_id":"101","register_pk":"511323","name":"本覚寺庫裏","kana":"ほんがくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31709722,"lng":139.55289167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0312","desc":"客殿の東に北面する庫裏。切妻造桟瓦葺の東西棟で、北面西寄りに入母屋造妻入の玄関を付す。内部は四室を田の字に配し、南西間を床付き座敷とし、南西面に矩折れに廊下が廻る。関東大震災後の再建で、床下や軸部に古材を転用し、伽藍復興の様相を伝える庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014334"},{"id":"00014336","register_sub_id":"101","register_pk":"511325","name":"本覚寺鐘楼","kana":"ほんがくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31751389,"lng":139.55269722,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、瓦葺、面積12㎡","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0314","desc":"本堂の北東に位置する鐘楼。桁行一間、梁間一間、入母屋造桟瓦葺で石積基壇上に建つ。四隅の円柱を腰貫、飛貫、虹梁型頭貫で固め、上部は干支透彫欄間で飾る。組物は出組で軒は二軒繁垂木。関東大震災後の再建で、寺院の歴史的景観をつくる装飾豊富な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014336"},{"id":"00014337","register_sub_id":"101","register_pk":"511326","name":"本覚寺手水舎","kana":"ほんがくじてみずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31735833,"lng":139.55279167,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、銅板葺、面積4.6㎡","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0315","desc":"本堂の東に位置する手水舎。桁行一間、梁間一間、切妻造銅板葺。四隅に几帳面取角柱を建て虹梁型頭貫を渡し、獏、唐獅子彫刻の木鼻を架ける。柱上は枠肘木を載せて虹梁を架け、欄間を龍や鳳凰の彫刻で飾る。小規模ながら質の高い彫刻で華やかに飾る手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014337"},{"id":"00014335","register_sub_id":"101","register_pk":"511324","name":"本覚寺分骨堂","kana":"ほんがくじぶんこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31758611,"lng":139.55231389,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0313","desc":"本堂の北に東面し、日蓮の分骨を納める廟堂。桁行１間、梁間１間の身舎に裳階を付し、屋根は宝形造桟瓦葺。内部は身舎内の須弥壇は彩色塗装で荘厳し、後方壇に分骨を納める多宝小塔を安置。関東大震災後の再建で、伽藍中枢に雄大な景観を形成する分骨堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014335"},{"id":"00014332","register_sub_id":"101","register_pk":"511321","name":"本覚寺本堂","kana":"ほんがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31737222,"lng":139.55239722,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0310","desc":"若宮大路の東に位置する日蓮宗寺院本堂。境内中央西寄りに東面し、正面七間、入母屋造桟瓦葺で、正面に軒唐破風の向拝を付す。日蓮宗の伝統的平面ながら、建登せ柱で小屋組はトラスとして軽量化を図る。関東大震災を乗り越えた１０代伊藤平左衛門による本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014332"},{"id":"00014338","register_sub_id":"101","register_pk":"511327","name":"本覚寺楼門","kana":"ほんがくじろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県鎌倉市小町一丁目302-1","lat":35.31730556,"lng":139.55311111,"geo_status":"db","era":"安政2年(1855)／明治9年移築・平成25年改修","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造2階建、瓦葺、建築面積30㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"14 - 0316","desc":"夷堂橋西詰にある伽藍東辺の楼門。桁行三間、梁間二間、入母屋造桟瓦葺で二軒繁垂木、組物は出三斗、中備は間斗束とする。下層両脇間に金剛力士像を安置する。上層は一室の板敷、鏡天井とする。寺院の主要な表構えをつくり、滑川沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014338"},{"id":"00011912","register_sub_id":"101","register_pk":"211077","name":"蓑毛地蔵堂","kana":"みのげじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原724","lat":35.416759,"lng":139.228414,"geo_status":"db","era":"18世紀前半／昭和50年頃改修","year":1705,"year_source":"estimated","year_min":1701,"year_max":1750,"year_label":"18世紀前半","structure":"木造平屋建、鉄板葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-251","desc":"不動堂の北東に東面する三間堂。寄棟造、平入で、一間向拝を付ける。内部は背面中央に六角形の仏壇を置き、両脇は柱間幅に仏壇を構える。組物は拳鼻付大斗絵様肘木で、軒はせがい造。向拝の水引虹梁や木鼻、蟇股、手挟の細部意匠に時代相応の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011912"},{"id":"00011910","register_sub_id":"101","register_pk":"211075","name":"蓑毛大日堂","kana":"みのげだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原721","lat":35.416437,"lng":139.227903,"geo_status":"db","era":"享保14年（1729）","year":1729,"year_source":"db","year_min":1729,"year_max":1729,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-249","desc":"大山の登山口にある敷地の中央に南面して建つ。桁行四間、梁間三間、寄棟造、妻入で、一間向拝を付ける。内部は中央柱を境に外陣、内陣とし、内陣中央間背面に厨子、両脇に仏壇を構える。組物は尾垂木付二手先で、向拝廻りの彫刻は牡丹の手挟など華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011910"},{"id":"00011913","register_sub_id":"101","register_pk":"211078","name":"蓑毛大日堂仁王門","kana":"みのげだいにちどうにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原721","lat":35.416106,"lng":139.227887,"geo_status":"db","era":"19世紀前半","year":1805,"year_source":"estimated","year_min":1801,"year_max":1850,"year_label":"19世紀前半","structure":"木造平屋建、鉄板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-252","desc":"大日堂の南面に建つ仁王門。三間一戸八脚門、入母屋造で、両脇間前方に二王像を安置する。妻飾は虹梁太瓶束笈形付。粽付の円柱を頭貫で固め、台輪上に出三斗とし、正面と背面中央間のみ中備を肩に雲形が付いた蟇股とし、境内の表構えを良好に形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011913"},{"id":"00011911","register_sub_id":"101","register_pk":"211076","name":"蓑毛不動堂","kana":"みのげふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県秦野市蓑毛字上川原723","lat":35.416615,"lng":139.228164,"geo_status":"db","era":"17世紀末／昭和50年頃改修","year":1695,"year_source":"estimated","year_min":1688,"year_max":1700,"year_label":"17世紀末","structure":"木造平屋建、銅板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14-250","desc":"大日堂北東の小高い場所に建つ。桁行四間、梁間三間、入母屋造、妻入で、一間向拝を付ける。内部は中央柱を境に外陣、内陣とし、内陣中央間背面に厨子を構える。側柱は角柱で上部を丸めて粽状にし、拳鼻付三斗を置く。近年の改造を受けるが境内で最も古い建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011911"},{"id":"00013698","register_sub_id":"101","register_pk":"505219","name":"龍口寺鐘楼","kana":"りゅうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31153333,"lng":139.48966111,"geo_status":"db","era":"明治14年／昭和44年移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造、瓦葺、面積21㎡","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 295","desc":"本堂南東の基壇に南北棟で建つ入母屋造本瓦葺、吹放し形式の鐘楼。長方形平面で規模が大きく、軸部は禅宗様を基調とし、四本の丸柱を内転びに立て、組物は三斗詰組とする。虹梁形内法貫と頭貫の間に蟇股を飾り格天井を張る。意匠簡明ながら力感のある鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013698"},{"id":"00013697","register_sub_id":"101","register_pk":"505217","name":"龍口寺大書院","kana":"りゅうこうじだいしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31131667,"lng":139.48993611,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、瓦葺、建築面積399㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 294","desc":"境内南東に建つ。入母屋造妻入の正面に切妻造の平屋と入母屋造庇付の式台を張出す等巧みに屋根を重層させた豪壮な外観とする。一階に大小六室を配し、二階は大広間二室で折上格天井の広闊な空間とし、室ごとに異なる意匠の座敷飾を備えた大規模な接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013697"},{"id":"00013699","register_sub_id":"101","register_pk":"505221","name":"龍口寺手水舎","kana":"りゅうこうじちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31137222,"lng":139.48950278,"geo_status":"db","era":"慶応3年(1867)","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造、瓦葺、面積5.1㎡、水盤付","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 296","desc":"参道東側、妙見堂の向いに南北棟で建つ。桁行一間梁間一間、起り付きの切妻造桟瓦葺。禅宗様を基調とし組物は出組詰組。内転びの四本の角柱や頭貫に地紋彫を施し、木鼻に波に亀、妻飾に丸彫で雲龍の彫刻を飾る等、幕末らしい技巧性が随所にみられる手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013699"},{"id":"00013696","register_sub_id":"101","register_pk":"505215","name":"龍口寺妙見堂","kana":"りゅうこうじみょうけんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"神奈川県","address":"神奈川県藤沢市片瀬三丁目2822","lat":35.31135556,"lng":139.48931111,"geo_status":"db","era":"享保5年(1720)／明治後期改修","year":1720,"year_source":"db","year_min":1720,"year_max":1720,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"14 － 293","desc":"本堂に向かう参道の西側に東面して建つ。桁行四間梁間三間、入母屋造、妻入、向拝付で、正面と北側面に縁を廻らす。台輪上に平三斗を組み、軒は二軒繁垂木とする。内部は一室で格天井を張り、後方一間を仏壇として塗装などで荘厳し、妙見菩薩像を安置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013696"},{"id":"00005942","register_sub_id":"101","register_pk":"106927","name":"蒼柴神社拝殿","kana":"あおしじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市悠久町707","lat":37.432415,"lng":138.882401,"geo_status":"db","era":"天明元","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0228","desc":"本殿の前方，石積基壇上に建つ。桁行５間，梁間３間規模，入母屋造，銅板葺で，背面中央に桁行３間，切妻造の幣殿を本殿側に突出す。向拝は３間で中央間を軒唐破風とし，正面に千鳥破風を付けて全体の棟通りを十字形につくるなど特徴的な屋根構成をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005942"},{"id":"00005941","register_sub_id":"101","register_pk":"106926","name":"蒼柴神社本殿","kana":"あおしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市悠久町707","lat":37.432407,"lng":138.882721,"geo_status":"db","era":"天明元","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積14㎡、覆屋付","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0227","desc":"覆屋内に納まる一間社流造，こけら葺の社殿。長岡藩の作事で，棟札から番匠棟梁安達藤佐衛門吉高らが判明。妻飾りは二重虹梁で，虹梁を出組と蛇腹支輪で持ち出し，中備の唐獅子丸彫で棟を受ける。二手先詰組の腰組や背側面の板羽目の浮彫など装飾面で傑出。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005941"},{"id":"00013086","register_sub_id":"101","register_pk":"368256","name":"荒川神社拝殿及び幣殿","kana":"あらかわじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市桃崎浜187","lat":38.14094167,"lng":139.40725,"geo_status":"db","era":"天保12年（1841）／昭和46年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0527","desc":"本殿前面に接続する拝殿及び幣殿は、入母屋造、茅葺形銅板葺で、規模の大きな拝殿の後方に幣殿を張出し、その左右に神饌所と神輿庫を附属する。彫刻豊かな向拝を付け、内部も太い虹梁を四筋架けて大瓶束を立てるなど、重厚な軸部と装飾的細部をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013086"},{"id":"00013085","register_sub_id":"101","register_pk":"368255","name":"荒川神社本殿","kana":"あらかわじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市桃崎浜187","lat":38.14091667,"lng":139.40743333,"geo_status":"db","era":"天保12年（1841）／昭和46年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0526","desc":"北前船で栄えた桃崎浜の高台の境内奥に西面する。建ちの高い一間社流造、茅葺形銅板葺で、正側面に縁を廻らし脇障子をたてる。妻飾を出組で持出し、大瓶束の笈形や虹梁絵様、虹梁上彫刻などを流麗な波涛紋とする。装飾豊かな社殿で北前船交易の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013085"},{"id":"00013706","register_sub_id":"101","register_pk":"505231","name":"淡島神社拝殿","kana":"あわしまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県胎内市新栄町3601-2","lat":38.04726111,"lng":139.40070556,"geo_status":"db","era":"大正15年／昭和5年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 550","desc":"宿場として栄えた旧中条町に位置する。桁行三間、梁間二間、入母屋造桟瓦葺、平入で、正面に一間向拝を付す。向拝の虹梁形頭貫は渦紋を波形とし、龍の彫刻を載せ、木鼻に獏を付すなど、向拝回りに意匠を凝らす。旧宿場町の神社拝殿として景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013706"},{"id":"00005947","register_sub_id":"101","register_pk":"106932","name":"石動神社拝殿","kana":"いするぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市五反田町上ノ山447","lat":37.45923481,"lng":138.77472559,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.7㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0230","desc":"本殿の前方，石基壇上に建つ。正面の柱間２．８ｍ，梁間２．８ｍ規模の入母屋造，銅板葺，平入拝殿。向拝柱に根曲材を用い，正面上部を櫛形に見せているのが特徴で，水引虹梁上部の龍や木鼻の唐獅子の彫物も躍動的で見応えがある。技巧的な技術に優れ，貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005947"},{"id":"00007196","register_sub_id":"101","register_pk":"108178","name":"石動神社拝殿","kana":"いするぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区白新町1-1-11","lat":37.920849,"lng":139.217545,"geo_status":"db","era":"江戸末期／平成16改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0297","desc":"本殿の前方、幣殿を介して繋がる。桁行３間梁間２間で正・側面に高欄付切目縁をまわす。入母屋造桟瓦葺で正面に一間向拝を付ける。正面には桟唐戸、側面には板戸をたて、内部は格天井の１室とする。向拝は前後に拳鼻付の三斗組とし、貘の木鼻を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007196"},{"id":"00005946","register_sub_id":"101","register_pk":"106931","name":"石動神社本殿","kana":"いするぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県長岡市五反田町上ノ山447","lat":37.459198,"lng":138.7747785,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0229","desc":"覆屋内に納まる。正面柱間３尺規模の一間社流造，こけら葺で，素木でつくる。軒は二軒繁垂木で，向拝の組物は出組とする。地元の大工高木要助元久によるもので，水引虹梁上部の龍などの彫物に見所があり，海老虹梁に根曲材を用いているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005946"},{"id":"00007195","register_sub_id":"101","register_pk":"108177","name":"石動神社本殿","kana":"いするぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区白新町1-1-11","lat":37.92086962,"lng":139.21745769,"geo_status":"db","era":"寛政8／平成16移築","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.4㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0296","desc":"境内地の中央小高い位置に建つ。切妻造桟瓦葺、桁行２間梁間１間規模。側・背面は横板壁で、縁をまわさない。柱を腰長押、頭貫、台輪で固め、軒桁と虹梁を架す。虹梁上に間斗束をたて、木鼻付大斗肘木を介して棟木を支持する。絵様や蟇股などによく時代を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007195"},{"id":"00007199","register_sub_id":"101","register_pk":"108181","name":"稲荷神社拝殿及び幣殿","kana":"いなりじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3293","lat":37.91559075,"lng":139.22079212,"geo_status":"db","era":"文化12頃／平成13改修","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0300","desc":"本殿の正面に建つ。拝殿は桁行３間梁間２間、入母屋造桟瓦葺で、正面に千鳥破風と一間向拝を付ける。幣殿は拝殿背面中央間と本殿正面を繋ぐ両下造で、桁行３間梁間１間である。本殿と同時に建立された社殿で、いずれも格天井で、天井板に花鳥などを描く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007199"},{"id":"00007198","register_sub_id":"101","register_pk":"108180","name":"稲荷神社本殿","kana":"いなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3293","lat":37.915627,"lng":139.220886,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0299","desc":"境内の東北隅に西面して建つ。桁行３間梁間２間規模の切妻造本殿。正・側面に高欄付の切目縁をまわし、正面に木階を付ける。柱は上部粽付の円柱で、組物は出組とし、支輪をまわす。妻は二重虹梁大瓶束で２段に持ち出す。規模が大きく、見応えのある構造をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007198"},{"id":"00000681","register_sub_id":"101","register_pk":"101671","name":"彌彦神社石橋","kana":"いやひこじんじゃいしばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70502161,"lng":138.82774389,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，幅6.4m，長さ4.5m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0026","desc":"一之鳥居の奥，御手洗川に架けられた石造桁橋で，橋長４．５ｍ，橋幅５．４ｍ，前後に各一間の袖高欄をつける。橋板は７枚石で，緩やかな太鼓橋とする。高欄は，親柱・地覆石・斗・架木ともすべてをひとつの石から彫り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000681"},{"id":"00000669","register_sub_id":"101","register_pk":"101659","name":"彌彦神社石廊下","kana":"いやひこじんじゃいしろうか","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70675864,"lng":138.82583714,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，長さ5.7m，幅3.6m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0014","desc":"本殿と幣殿とを繋ぐ。遷宮式の際にはこの石廊下の上に木造の覆屋を架けた。石積三段で基壇を造り，瑞垣の潜り戸通り筋に三段の石階段を設ける。本殿基壇へは三段の石階段で，また幣殿の裏扉へは五段の石階段で連絡する造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000669"},{"id":"00000668","register_sub_id":"101","register_pk":"101658","name":"彌彦神社一之鳥居","kana":"いやひこじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70491975,"lng":138.82769391,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造，銅板葺，高さ8.5m","structure_material":"木造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0013","desc":"表参道の突き当たり，境内への入口に位置し，手前右手に社号標，左手に制札台を従える。柱間約６ｍ，高さ約８．４ｍの規模で，四脚建て両部鳥居の形式をとる。笠木の屋根は銅板葺，朱塗りで境内地のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000668"},{"id":"00000677","register_sub_id":"101","register_pk":"101667","name":"彌彦神社絵馬殿","kana":"いやひこじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.7056993,"lng":138.8276617,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積132㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0022","desc":"手水舎の手前，やや奥まったところに建つ。反りのある箕甲付入母屋屋根の前後に千鳥破風を構えているところに特徴がある。境内地に隣接して存在した陸上競技場（現在は競輪場）で開催された競技会の入賞額などが掲げられ神社活動の一端を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000677"},{"id":"00000671","register_sub_id":"101","register_pk":"101661","name":"彌彦神社楽舎","kana":"いやひこじんじゃがくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70637904,"lng":138.8274164,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積58㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0016","desc":"舞殿と並び建ち，東に玄関を付す。内部は畳敷で，橋掛廊下入口の左手，舞殿側に奥行一間六畳分の床を高くした楽座を設けている。舞殿と対比して，石積基壇，舟肘木，一軒疎乗木，桟瓦葺など仕様を控えめにしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000671"},{"id":"00000682","register_sub_id":"101","register_pk":"101672","name":"彌彦神社狛犬","kana":"いやひこじんじゃこまいぬ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70642756,"lng":138.8265943,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，高さ2.1m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0027","desc":"かっての三之鳥居（現在は随身門）前に建立。伊東忠太の図案により，新海竹太郎が原型を作成している。招魂社系の神社によくみられる両足を突っ張ったタイプの狛犬で，細身で精悍な顔立ちをしている。東京の名石工酒井八右衛門の代表作でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000682"},{"id":"00000676","register_sub_id":"101","register_pk":"101666","name":"彌彦神社鼓楼","kana":"いやひこじんじゃころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70603168,"lng":138.82690729,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積5.9㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0021","desc":"旧社務所に隣接して建てられていたが，昭和３７年新社務所が完成した際に現在地に移築された。桁行梁間とも８尺，軒高１６尺の規模で，高欄付きの縁を回し，箕甲付切妻屋根を架け，下部を袴腰とする。現在も時を告げる鼓楼として機能しつづけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000676"},{"id":"00000675","register_sub_id":"101","register_pk":"101665","name":"彌彦神社斎館（旧勅使館）","kana":"いやひこじんじゃさいかん（きゅうちょくしかん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70663569,"lng":138.82776675,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積149㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0020","desc":"二之鳥居から神馬舎のところで折れた突き当たりに建つ勅使の宿泊施設で，１０畳の書院座敷，１０畳間，２０畳間，６畳二間から成り，西北に湯殿・便所を配し，東で社務所（現在は宝物殿が建つ）に連絡していた。神社の格の高さを示す建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000675"},{"id":"00000672","register_sub_id":"101","register_pk":"101662","name":"彌彦神社参集殿（旧拝観所）","kana":"いやひこじんじゃさんしゅうでん（きゅうはいかんじょ）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70642202,"lng":138.82757934,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積169㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0017","desc":"舞殿での神楽を観覧するための施設。舞殿・楽舎と平行して建ち，東に玄関を付す。北側片廊下の細長い建物で，南面の蔀戸を上げて神楽を拝観する。入母屋造，桟瓦葺，舟肘木など楽舎にほぼ準じた仕様となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000672"},{"id":"00000664","register_sub_id":"101","register_pk":"101654","name":"彌彦神社伺候所","kana":"いやひこじんじゃしこうじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70681621,"lng":138.82603537,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積73㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0009","desc":"神社の宿直所に相当する施設。拝殿の後方右手に位置し，祝詞舎とは渡廊下で連絡し，最奥部は階段となり前庭に通じる。内部は床付１０畳間と１２畳間とから成り，前面に高欄付の縁側を設ける。外見は神饌所と同様のものとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000664"},{"id":"00000662","register_sub_id":"101","register_pk":"101652","name":"彌彦神社神饌所","kana":"いやひこじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70659264,"lng":138.82588796,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積73㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0007","desc":"神社の台所に相当する施設。拝殿の後方左手に位置し，渡廊下で祝詞舎とつながれ，最奥部に階段があり前庭に通じる。入母屋造，平を正面とした寝殿風の建物で，正面４間に蔀戸を建て込み，前面に高欄付の縁を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000662"},{"id":"00000680","register_sub_id":"101","register_pk":"101670","name":"彌彦神社神木石柵","kana":"いやひこじんじゃしんぼくいしだな","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70611634,"lng":138.82791146,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，延長32.8m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0025","desc":"神木は二之鳥居手前右手のやや高地，旧本殿跡の手前に位置する。石柵はこの神木を取り囲むよう不等辺七角形のプランを有し，自然石を積んだ基壇の上に建てられている。柵の高さは１．２ｍで，正面幅１．５ｍ，７段の階段上に石扉２枚を釣り込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000680"},{"id":"00000678","register_sub_id":"101","register_pk":"101668","name":"彌彦神社制札台","kana":"いやひこじんじゃせいさつだい","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70489871,"lng":138.82760034,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造，銅板葺","structure_material":"木造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0023","desc":"一之鳥居に向かって左手前に位置する。石積基壇に建ち，周囲に木製玉垣をめぐらす。柱間１．３５ｍ，棟高約３ｍの規模で，柱より腕木を出して銅板葺切妻屋根を架ける。檜材を用い，腕木を舟肘木と巻斗で支えるなど小規模ながら格の高い仕様をとっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000678"},{"id":"00000667","register_sub_id":"101","register_pk":"101657","name":"彌彦神社摂社草薙神社","kana":"いやひこじんじゃせっしゃくさなぎじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70670812,"lng":138.82688369,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0012","desc":"摂末社８棟のうち焼失した３棟の復興建築のひとつで，横並び８棟のうち向かって左より２棟目にあたる。四代目の草薙神を祭る。今山神社，乙子神社と同規模同型式で，浜床・三方縁・脇障子付，銅板葺，一間社流造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000667"},{"id":"00000674","register_sub_id":"101","register_pk":"101664","name":"彌彦神社手水舎","kana":"いやひこじんじゃちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.7058456,"lng":138.82786224,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積7.０㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0019","desc":"表参道から二之鳥居方向に折れる地点に建つ。銅板葺き反り付き切妻屋根の前後に唐破風を付ける。四方の隅柱に転びをつけ，２本宛の控柱を添わす。天井は格天井，軒は二軒繁乗木で，三斗組を備えるなど舞殿とほぼ同様の仕様としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000674"},{"id":"00000673","register_sub_id":"101","register_pk":"101663","name":"彌彦神社二之鳥居","kana":"いやひこじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70600183,"lng":138.82763365,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造，高さ6.4m","structure_material":"石造","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0018","desc":"表参道を手水舎のところで左に折れ，しばらく行った石階段の上に建つ。稲田石による石造鳥居で，明神鳥居の形式をとる。柱間４．５ｍ，高さ約６ｍ，笠木石の長さ８．４ｍの規模で，この鳥居から社殿がはじめて望見できることになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000673"},{"id":"00000660","register_sub_id":"101","register_pk":"101650","name":"彌彦神社祝詞舎","kana":"いやひこじんじゃのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70672961,"lng":138.82591536,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積66㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0005","desc":"幣殿と拝殿の間に位置する。屋根は切妻で，棟の一方を幣殿の棟に突きつけ，他方は拝殿屋根の妻に納める。内部は桁行方向に大虹梁を架け，それに梁間方向の虹梁を二重に載せ，化粧屋根裏とする。当初は畳敷であった。神饌所と伺候所との連絡口をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000660"},{"id":"00000661","register_sub_id":"101","register_pk":"101651","name":"彌彦神社拝殿","kana":"いやひこじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70665838,"lng":138.82610438,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積165㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0006","desc":"桁行９間，梁間５間の規模で，入母屋造，妻入とし，後方左右に神饌所と伺候所を従え，前面に唐破風の向拝を付けて正面性を強調した造りとする。内部は桁行方向に大虹梁を架けて無柱の室内を造っている。近代建築家のてがけた神社建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000661"},{"id":"00000659","register_sub_id":"101","register_pk":"101649","name":"彌彦神社幣殿","kana":"いやひこじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70674533,"lng":138.82587279,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積28㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0004","desc":"拝殿・祝詞舎の最奥部に位置し，内部を畳敷とする。平面的には一体であるが，外見上は本殿と同様の三間社流造の形式をとり，祝詞舎側に張りだした奥行一間の階段付大床を納める。背面は石階段と石廊下で本殿と連絡している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000659"},{"id":"00000658","register_sub_id":"101","register_pk":"101648","name":"彌彦神社本殿","kana":"いやひこじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70679212,"lng":138.82576888,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積26㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0003","desc":"明治４５年焼失の再建社殿。再建にあたり，弥彦山を背負う位置に社殿を移す。再建の設計は伊東忠太と桐山平太郎，監督は奥本五一。飾金具の意匠は大江新太郎ら明治神宮造営局のグループがあたる。本殿は焼失前と同様の流造を採用し，屋根は銅板葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000658"},{"id":"00000670","register_sub_id":"101","register_pk":"101660","name":"彌彦神社舞殿","kana":"いやひこじんじゃまいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70640232,"lng":138.8272642,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建橋掛廊下付，銅板葺，建築面積33㎡","structure_material":"木造平屋建橋掛廊下付","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0015","desc":"拝殿に向かう参道中程の右手，摂末社の下段に位置する。亀腹基壇の上に腰組付の高欄を回し，四方を吹き放ちとした舞台建築で，隣接する楽舎から突きだした橋掛廊下を付す。屋根は入母屋造であるが，これのみ扇乗木とし他との違いを際出させている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000670"},{"id":"00000663","register_sub_id":"101","register_pk":"101653","name":"彌彦神社瑞垣・裏門","kana":"いやひこじんじゃみずがき・うらもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70682378,"lng":138.82568966,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造棟門，銅板葺，及び左右瑞垣56.2mよりなる","structure_material":"木造棟門","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0008","desc":"本殿を囲む垣で，正面は幣殿に発し，側面９間建て，正面寄りに潜り門をとり，背面７間建ての中央に裏門を設ける。石製基壇上に建ち，内側に控えの柱をとり，柱間に組格子の狭間を建て込む。屋根は両流れ銅板葺で，裏門は平入唐破風屋根とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000663"},{"id":"00006654","register_sub_id":"101","register_pk":"107637","name":"内島見観音堂","kana":"うちしまみかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区内島見字屋敷付47","lat":37.94025,"lng":139.20137,"geo_status":"db","era":"元治2","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0271","desc":"境内中央北寄りに南面して建つ３間堂。入母屋造桟瓦葺で、１間向拝を付ける。円柱で柱上出組とし、軒は二軒繁垂木。向拝は方柱で唐獅子や龍などの彫刻を飾る。前寄り２間を畳敷の外陣、後寄り２間を内陣とし仏壇を構える。地域の人々の信仰を聚める仏堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006654"},{"id":"00006655","register_sub_id":"101","register_pk":"107638","name":"内島見仁王堂","kana":"うちしまみにおうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市北区内島見字屋敷付47","lat":37.940025,"lng":139.201614,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造、瓦葺、面積19㎡","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"15 － 0272","desc":"本堂の南に南面して建つ。３間１戸八脚門で、入母屋造桟瓦葺。円柱で出組を置き、軒は二軒繁垂木。両脇間は前１間を吹放ち、後１間を正面のみ腰壁とし他を板壁で囲う。床板敷で、仁王像を安置。天井は彩色画を描く格天井。堂々とした外観が境内景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006655"},{"id":"00007201","register_sub_id":"101","register_pk":"108183","name":"開市神社拝殿","kana":"かいちじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3294-1","lat":37.915176,"lng":139.221039,"geo_status":"db","era":"明治4／昭和44移築改修","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0302","desc":"稲荷神社拝殿の南方に北面して建つ。桁行３間梁間２間、入母屋造桟瓦葺の拝殿で、後に側・背面１間通りが増築された。正面には一間向拝を付けるが、柱や貫、桁を鳥居風に造る。軒をせがい造の一軒繁垂木するなど、社殿としては珍しい仕様を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007201"},{"id":"00005948","register_sub_id":"101","register_pk":"106933","name":"願興寺経蔵","kana":"がんこうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市関原町1-1019","lat":37.45524357,"lng":138.77607547,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造平屋建、鉄板葺、建築面積21㎡、唐破風向拝付","structure_material":"土蔵造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0233","desc":"石基壇の上に建つ。１辺３．３ｍ，六角形平面の土蔵造経蔵で，屋根は宝形につくり鉄板で葺き，正面に唐破風造の向拝を付ける。地元の大工高木家によるものとされ，向拝の懸魚等の彫物は見事な出来映え。腰部に回した生子鉄板は当初のもので貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005948"},{"id":"00001580","register_sub_id":"101","register_pk":"102570","name":"木揚場教会","kana":"きあげばきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市中央区礎町通1-1957","lat":37.92003838,"lng":139.04895389,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、瓦葺、建築面積343㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0052","desc":"浄土真宗大谷派の説教施設で，明治４３年の火災後，大正１５年に再建された。木造で，一階は真宗仏堂とし，前半の二階を一室の道場とする。玄関付・２階建・寄棟造の前半と，これに直交する平屋建で入母屋造の大屋根を組み合わせた特異な形態となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001580"},{"id":"00011093","register_sub_id":"101","register_pk":"205200","name":"敬覚寺本堂","kana":"きょうかくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新潟市江南区酒屋町606-1","lat":37.833063,"lng":139.065263,"geo_status":"db","era":"大正8／平成18改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積327㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0435","desc":"明治三六年の酒屋大火後に再建された。入母屋造桟瓦葺、桁行七間、梁間六間。南面して建ち、正面に一間向拝を付ける。外陣、矢来内、内陣を並べ、内陣は後門形式で左右余間とする。側柱は角柱とし、その他は円柱。典型的な真宗本堂の形式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011093"},{"id":"00011924","register_sub_id":"101","register_pk":"210931","name":"顕法寺本堂","kana":"けんぽうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1154","lat":37.945595,"lng":139.325552,"geo_status":"db","era":"明治43年／平成15年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積418㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-466","desc":"城下町の南端に東面する日蓮宗寺院本堂。桁行五間で、中央間は二間分の間口をもち、広縁・外陣境と外陣・内陣境には直径一・五尺の丸柱を立て虹梁で繋ぐ豪壮な造り。鬼子母神を祀り、細部彫刻にも柘榴を彫る。正面の千鳥破風、向拝の軒唐破風に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011924"},{"id":"00008849","register_sub_id":"101","register_pk":"162292","name":"極楽寺経蔵","kana":"ごくらくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36109428,"lng":138.54709897,"geo_status":"db","era":"文政10年(1827)／万延元年(1860)・平成22年改修","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"土蔵造平屋一部2階建、瓦葺、建築面積47㎡、輪蔵付","structure_material":"土蔵造平屋一部2階建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0358","desc":"庫裏の北に位置し、桁行７．３ｍ梁間５．６ｍ、土蔵造、正面寄棟造、背面切妻造桟瓦葺で、正面側は棟に宝珠を飾り宝形造風に見せる。正面に唐破風造の向拝を付設。内部は前後二室に分け、前室に八角輪蔵を設ける。特殊な形態になる経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008849"},{"id":"00008847","register_sub_id":"101","register_pk":"162290","name":"極楽寺庫裏","kana":"ごくらくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36080678,"lng":138.54706902,"geo_status":"db","era":"江戸後期／平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0356","desc":"本堂の北に東面して建つ。切妻造妻入桟瓦葺で、妻は梁と貫を重ねて飾り、下方に下屋を設ける。東面南寄りが入口で土間とし、その奥の三間×三間半を広い畳敷とし、胴差で固め、小壁は漆喰仕上げで貫を二段に通すなど、伝統的な民家の雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008847"},{"id":"00008851","register_sub_id":"101","register_pk":"162294","name":"極楽寺山門","kana":"ごくらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36127098,"lng":138.54718882,"geo_status":"db","era":"江戸後期／平成22年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、鉄板葺、間口2.7m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0360","desc":"境内の北端に位置し、五平の本柱を間口２．７ｍに、奥行２．１ｍに控柱を立てる。柱を冠木や梁で固め、三斗組で中備に蟇股をおく。妻飾は笈形付大瓶束とし、軒は二軒繁垂木で、切妻造鉄板葺とする。棟を主・控柱の中間とするなど特異な形態になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008851"},{"id":"00008848","register_sub_id":"101","register_pk":"162291","name":"極楽寺書院","kana":"ごくらくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.3607379,"lng":138.54697618,"geo_status":"db","era":"江戸末期／平成22年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0357","desc":"庫裏西奥と本堂を繋ぐ。八畳二室を南北に並べ、それぞれの東面に幅一間の畳廊下を配し、東・西面に榑縁を通す。主室にトコや棚、付書院を構え、次の間境には欄間を飾る。書院に繊細な障子をたて、棹縁を黒漆仕上げとする棹縁天井を張るなど、意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008848"},{"id":"00008850","register_sub_id":"101","register_pk":"162293","name":"極楽寺鐘楼","kana":"ごくらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36104936,"lng":138.54729663,"geo_status":"db","era":"江戸末期／平成22年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積8.7㎡","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0359","desc":"経蔵の東に位置する。南北棟の入母屋造桟瓦葺、方一間の吹放ち鐘楼。高い石積基壇上に礎盤を置き、四方転びに円柱をたて、貫や台輪で固める。柱上三斗組とし、中備に蟇股を飾る。格天井を張り、軒は二軒繁垂木である。堅実なつくりになる鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008850"},{"id":"00008846","register_sub_id":"101","register_pk":"162289","name":"極楽寺本堂","kana":"ごくらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市若葉町2-1","lat":37.36057917,"lng":138.54701212,"geo_status":"db","era":"宝暦8年(1758)／文化6年(1809)増築、大正7年・平成22年改修","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積343㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"15 － 0355","desc":"東面して建つ仏堂。正面は入母屋造妻入とし、唐破風造の向拝を付設。切石積基壇上に建ち、舟肘木を置き、腕木を持ち出す。内部は前後二列各四室からなり、正面に奥行二間の広縁を通す。後列南から第二室を内々陣とし須弥壇を構える。大規模な浄土宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008846"},{"id":"00001906","register_sub_id":"101","register_pk":"102896","name":"西永寺経蔵","kana":"さいえいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17834007,"lng":138.74676392,"geo_status":"db","era":"嘉永1頃","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積13㎡","structure_material":"土蔵造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0108","desc":"本堂前方の左手に位置し，ほぼ北面して建つ。本堂と同時期の再建とみられる。土蔵造，方２間，切妻造，妻入，もと板葺で，正面に切妻造の向拝を付ける。内部は，円柱２本と組物とで仏壇を構え，仏壇両脇から両側面に経棚を配するなど本格的な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001906"},{"id":"00001908","register_sub_id":"101","register_pk":"102898","name":"西永寺庫裏及び廊下","kana":"さいえいじくりおよびろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.1785779,"lng":138.74633317,"geo_status":"db","era":"嘉永元年頃","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積284㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0110","desc":"本堂の北方に建ち，本堂と廊下で結ばれる。本堂と同時期の再建とみられ，庫裏は，切妻造，妻入で，本堂と同様に正面を東にとる。外装，内部は大きく改変を受けてはいるが，庫裏の書院座敷などは当初の型式と格式をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001908"},{"id":"00001907","register_sub_id":"101","register_pk":"102897","name":"西永寺鐘楼","kana":"さいえいじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17847738,"lng":138.74688131,"geo_status":"db","era":"嘉永1頃","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0109","desc":"経蔵の北方，境内に入って直ぐ左手に位置し，高い基壇上に建つ。本堂と同時期の再建とみられる。切妻造，平入，もと茅葺で，４本角柱を内転びに建て，梁中央に載せた地棟状の横架材に鐘を吊す。今も毎日午前１１時に時を告げていることで親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001907"},{"id":"00001905","register_sub_id":"101","register_pk":"102895","name":"西永寺本堂","kana":"さいえいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17836007,"lng":138.7463698,"geo_status":"db","era":"嘉永1","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積480㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0107","desc":"信濃川左岸近くに位置する真宗本堂で，天保６年焼失後の再建になる。棟梁は柏崎の篠田總吉。間口約１９ｍ，入母屋造，平入，向拝１間のやや規模の大きな本堂で，もと茅葺の急勾配屋根をあげる。平面・構造は真宗寺院の法式に則り，内外の彫刻が特に優れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001905"},{"id":"00011923","register_sub_id":"101","register_pk":"210930","name":"三光寺本堂","kana":"さんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新発田市諏訪町二丁目390甲","lat":37.945133,"lng":139.329783,"geo_status":"db","era":"大正5年／平成11年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積333㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-465","desc":"寺町通りに西面する浄土宗寺院本堂。外陣の前面に一間幅の板間を取り込み、向拝一間を付け、背面には後堂、開山堂を張り出す。外陣中央間の柱は直径一・四尺の磨き丸太を用い、内陣廻り以外は柱間を虹梁や貫で繋がず内法の高い空間を特色とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011923"},{"id":"00010762","register_sub_id":"101","register_pk":"201597","name":"慈眼寺山門","kana":"じげんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県小千谷市平成二丁目273-1","lat":37.307499,"lng":138.793284,"geo_status":"db","era":"明治25頃／平成18改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、金属板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"15 ‐ 0423","desc":"境内入口に北面して建つ三間一戸楼門。屋根は入母屋造の正背面に軒唐破風を付ける。禅宗様を基調とし、組物は腰組とも三手先で、上部は尾垂木付とする。板支輪に波紋や鶴などを陽刻し、上部蟇股は龍彫刻とする。安定感ある容姿で細部意匠も見応えのある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010762"},{"id":"00009142","register_sub_id":"101","register_pk":"164695","name":"慈光寺回廊","kana":"じこうじかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63685347,"lng":139.19282141,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山門両側面後間から、南側の東司と北側の禅堂に延びる回廊。桁行総延長27.8メートル梁間1.8メートル、両下造桟瓦葺。正面側は漆喰壁で花頭窓を穿ち、腰に下見板を張る。背面側は内法を吹放つ。境内を結界するとともに、伽藍正面の景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009142"},{"id":"00009143","register_sub_id":"101","register_pk":"164696","name":"慈光寺経蔵","kana":"じこうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63668691,"lng":139.19292849,"geo_status":"db","era":"寛政6年(1794)","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積35㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"伽藍の南西側に北面して建ち、土蔵造、桁行5.8メートル梁間6.0メートル、切妻造桟瓦葺で、正面に下屋を付ける。内部に八角輪蔵を納め、背面の張出しに宮殿を祀る。外壁は上部を横板張、腰を下見板張とする。境内の入口脇にあって、古刹の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009143"},{"id":"00009140","register_sub_id":"101","register_pk":"164693","name":"慈光寺庫裏","kana":"じこうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.6367464,"lng":139.19313372,"geo_status":"db","era":"宝暦9年(1759)／昭和62年改修","year":1759,"year_source":"db","year_min":1759,"year_max":1759,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積374㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本堂南西隅に接続し、北面して建つ。桁行26.7メートル梁間14.1メートル、入母屋造銅板葺で、上手の本堂側に丈室や書院、下手に韋駄天内陣や土間、典座寮などを配し、正面側を土縁とする。江戸後期における曹洞宗寺院の伽藍構成を伝える大型の庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009140"},{"id":"00009144","register_sub_id":"101","register_pk":"164697","name":"慈光寺虚空蔵堂","kana":"じこうじこくうぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市別所字上1318","lat":37.67178151,"lng":139.16853485,"geo_status":"db","era":"宝暦4年(1754)","year":1754,"year_source":"db","year_min":1754,"year_max":1754,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"慈光寺境内から約5キロメートル北西の飛地境内に東面して建つ。正面5間奥行6間、宝形造銅板葺。後半部を畳敷の内陣として正側面3方に縁を廻し、前半部を土間の外陣として木階を設ける。外陣入隅柱間に3間分の梁を架けるなど、特異な内部構成を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009144"},{"id":"00009141","register_sub_id":"101","register_pk":"164694","name":"慈光寺山門","kana":"じこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63679696,"lng":139.19285413,"geo_status":"db","era":"天明5年(1785)","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造、瓦葺、間口5.8m","structure_material":"木造","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"伽藍の西正面中央に建ち、南北に回廊が取付く。3間1戸八脚門、切妻造桟瓦葺で正面左右に四天王像を祀る。軸部は禅宗様を基調とし、組物は三斗で中備蟇股、妻飾は二重虹梁蟇股とする。木部は赤色塗で、素木造を基本とする境内において印象を異にしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009141"},{"id":"00009139","register_sub_id":"101","register_pk":"164692","name":"慈光寺禅堂及び衆寮","kana":"じこうじぜんどうおよびしゅうりょう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63695757,"lng":139.19288685,"geo_status":"db","era":"江戸後期／昭和62年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"本堂北西隅に接続し、南面して建つ。桁行24.5メートル梁間11.1メートル、入母屋造銅板葺である。正面1間を土間通路とし、後方の西半を禅堂として須弥壇を中心に単を並べ、東半を衆寮とする。江戸後期における曹洞宗寺院の禅堂の形式をよくとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009139"},{"id":"00009138","register_sub_id":"101","register_pk":"164691","name":"慈光寺本堂","kana":"じこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県五泉市蛭野870","lat":37.63692783,"lng":139.19318726,"geo_status":"db","era":"宝暦13年(1763)／昭和30年頃・平成19年改修","year":1763,"year_source":"db","year_min":1763,"year_max":1763,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積526㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"山麓の伽藍東奥に西面する。桁行9間梁間8間、入母屋造銅板葺で背面に懸造の開山堂を張出す。平面は6間取の周囲に廊下と縁を廻らし、正面広縁の前半を土間とする。室中の座敷飾りや蟇股等の細部を丁寧につくり、内外ともに整った姿をもつ曹洞宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009138"},{"id":"00005951","register_sub_id":"101","register_pk":"106936","name":"地蔵堂","kana":"じぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市地蔵1-6","lat":37.454796,"lng":138.863098,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積23㎡","structure_material":"煉瓦造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0234","desc":"石基壇の上に建つ。４．８ｍ四方の正方形平面をもつ煉瓦造イギリス積の小堂で，屋根は切妻造，鉄板葺とし，正面に木造の向拝を付ける。小規模ながら，入口や側面の窓はアーチとし，丁寧に造る。軒廻りを斜めに持ち出す煉瓦積技法が使われ貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005951"},{"id":"00015431","register_sub_id":"101","register_pk":"533446","name":"常敬寺山門","kana":"じょうきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目117-1","lat":37.11105833,"lng":138.23831944,"geo_status":"db","era":"江戸後期／昭和30年代改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.3m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0608","desc":"裏寺町通りに東面する薬医門。切妻造桟瓦葺で、五平の本柱上に載せた冠木で男梁を受け、本柱と控柱を貫二段で固める。軒は一軒繁垂木。組物を用いず質実なつくりとするが、妻飾の大振りの蟇股が目を惹く。軸部を弁柄塗で仕上げ、地域が赤門と呼び親しむ山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015431"},{"id":"00015430","register_sub_id":"101","register_pk":"533445","name":"常敬寺鐘楼","kana":"じょうきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目117-1","lat":37.11091389,"lng":138.23779167,"geo_status":"db","era":"寛政4年（1792）／昭和60年頃改修","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0607","desc":"本堂の南東に位置し、基壇上に建つ鐘楼。桁行二間梁間一間入母屋造銅板葺。建ちが高い転びのある角柱を台輪と三段の貫で固め、実肘木付三斗で丸桁を受け、軒は一軒繁垂木とする。中備は西面のみに蟇股を飾る。簡素ながらも境内の歴史的な景観を整える鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015430"},{"id":"00015429","register_sub_id":"101","register_pk":"533444","name":"常敬寺本堂","kana":"じょうきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目117-1","lat":37.11111944,"lng":138.237525,"geo_status":"db","era":"享保16年（1731）／昭和63年改修","year":1731,"year_source":"db","year_min":1731,"year_max":1731,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積308㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0606","desc":"旧高田城下の裏寺町通りに建つ浄土真宗寺院の本堂。桁行一六・四メートル、梁間一六・七メートル、入母屋造銅板葺で正面に向拝を付す。内外陣、左右両余間を配する典型的な真宗本堂平面で、内外陣境には法輪の金箔欄間彫刻を飾る。江戸中期の真宗本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015429"},{"id":"00013073","register_sub_id":"101","register_pk":"368357","name":"浄善寺本堂","kana":"じょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市柿崎区柿崎字仲町6389-1他","lat":37.27746389,"lng":138.39031667,"geo_status":"db","era":"昭和3年／平成5年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄骨鉄筋コンクリート造2階建、建築面積501㎡、鐘塔及び塔屋付","structure_material":"鉄骨鉄筋コンクリート造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0514","desc":"市街地に建つ真宗寺院本堂。敷地南に西面して建ち、桁行２７・１メートル規模で、鉄骨鉄筋コンクリート造二階建。正面に尖塔を三基設け、内部は内外陣、余間などからなる真宗本堂の典型を示す。インド風を基調とし、独創的な内外観を実現した本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013073"},{"id":"00013532","register_sub_id":"101","register_pk":"504899","name":"浄福寺本堂","kana":"じょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市柿崎区柿崎字諏訪町6654-1","lat":37.27856389,"lng":138.39213056,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階地下1階建、瓦葺、建築面積395㎡","structure_material":"鉄筋コンクリート造2階地下1階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0545","desc":"旧北国街道に程近い境内に西面して建つ。防火を意図した鉄筋コンクリート造の真宗本堂で、桁行二四メートル梁間一六メートルとし、エンタシス付の丸柱を配した向拝の両脇に二階建の建屋を張出す独特の外観。コンクリートで重厚かつ優美な内外観をつくり出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013532"},{"id":"00008663","register_sub_id":"101","register_pk":"149384","name":"正法寺観音堂","kana":"しょうぼうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01328453,"lng":138.34542492,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0336","desc":"本堂の西南に東面して建つ。桁行8.3ｍ梁間5.8ｍ、入母屋造桟瓦葺、向拝1間。南半部に東西に内陣と外陣を並べ、北半部に物置と脇間を設ける。内・外陣境に虹梁や木鼻付の組物を備えて間仕切り、内陣には須弥壇を構える。近世境内仏堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008663"},{"id":"00008665","register_sub_id":"101","register_pk":"149386","name":"正法寺蔵","kana":"しょうぼうじくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01321272,"lng":138.3457501,"geo_status":"db","era":"享和2年(1802)／明治30年改修","year":1802,"year_source":"converted","year_min":1802,"year_max":1802,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0338","desc":"本堂と護国蔵の間に東西棟で建つ。桁行5.5ｍ梁間4.5ｍ、置屋根形式の切妻造桟瓦葺、1階北面に下屋を設け出入口とし、2階南面に窓を穿ち、それぞれ掛子塗の両開戸を吊る。外壁は腰を板張とした漆喰仕上げで、開口部まわりを鳥居形に造り、寺紋を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008665"},{"id":"00008664","register_sub_id":"101","register_pk":"149385","name":"正法寺護国蔵","kana":"しょうぼうじごこくくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01304393,"lng":138.34575149,"geo_status":"db","era":"宝永元年(1704)／寛政7年(1795)・明治30年改修","year":1704,"year_source":"converted","year_min":1704,"year_max":1704,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積34㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0337","desc":"本堂の南方、参道に西面する。方5.0ｍ、宝形造桟瓦葺、向拝1間。外壁は漆喰仕上げの大壁造とし、内部は真壁で、板敷、根太天井。中央に仏壇を構え、その側・背面を経典棚とする。軒は台輪上三斗組、中備蟇股。二軒半繁垂木。江戸期の標準的規模の経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008664"},{"id":"00008667","register_sub_id":"101","register_pk":"149388","name":"正法寺山門","kana":"しょうぼうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01295186,"lng":138.34562734,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0340","desc":"境内南面に開く四脚門。切妻造桟瓦葺、正面軒唐破風付。本柱を円柱、控柱を方柱とし、本柱は棟木まで延ばす。虹梁や貫で軸部を固め、平三斗を置き、海老虹梁で繋ぐ。二軒繁垂木。本柱間虹梁上に龍、虹梁や木鼻に霊獣の彫刻を施すなど、表情豊かな装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008667"},{"id":"00008666","register_sub_id":"101","register_pk":"149387","name":"正法寺鐘楼","kana":"しょうぼうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01312623,"lng":138.34552551,"geo_status":"db","era":"文政3年(1820)／明治31年改修","year":1820,"year_source":"converted","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造、瓦葺、面積6.6㎡","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0339","desc":"観音堂の南に位置する、方一間吹放ちの鐘楼。南北棟の入母屋造桟瓦葺。石積基壇上に礎石を置き、方柱を内転びにたて、貫や台輪で固め、三斗組とする。中備は蟇股または蓑束。天井は格天井で格間に絵を描く。二軒半繁垂木。安定した外観になる小規模鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008666"},{"id":"00008662","register_sub_id":"101","register_pk":"149383","name":"正法寺本堂","kana":"しょうぼうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市泉甲504","lat":38.01345823,"lng":138.34555341,"geo_status":"db","era":"享保6年(1721)／明治30年改修","year":1721,"year_source":"converted","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積343㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"15 － 0335","desc":"境内北寄りに南面して建つ。桁行19ｍ梁間16ｍ、入母屋造桟瓦葺、向拝1間。6間取方丈形式で、正面に広縁、側背面に廊下を付け、背面中央を葺き降ろして開山堂とする。側柱は方柱で、正面大斗肘木、他舟肘木、二軒半繁垂木。近世における曹洞宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008662"},{"id":"00012142","register_sub_id":"101","register_pk":"352941","name":"関山神社宮殿","kana":"せきやまじんじゃくうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県妙高市大字関山4804","lat":36.933772,"lng":138.213395,"geo_status":"db","era":"寛政2年(1790)／文化15年(1818)・昭和35年改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積4.6㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"15-477","desc":"一間社流造、こけら葺で、軒唐破風を付す。三方に切目縁を廻し、脇障子を設ける。組物は三斗、中備蟇股で妻飾は虹梁間斗束。向拝を海老虹梁で繋ぎ、内寄りに手挟を付ける。赤色塗装を基調に向拝柱や正面両折戸を黒漆塗、彫刻を彩色し華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012142"},{"id":"00012141","register_sub_id":"101","register_pk":"352940","name":"関山神社本殿・幣殿・拝殿","kana":"せきやまじんじゃほんでん・へいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県妙高市大字関山4804","lat":36.933769,"lng":138.21351,"geo_status":"db","era":"文政元年(1818)／昭和2年・同45年改修","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"15-476","desc":"妙高山北山麓に東面して建つ。入母屋造妻入で、向唐破風造の向拝一間を付す。桁行七間、梁間三間の堂内に拝殿、幣殿、本殿を納め、後方左右に神饌所・控室を付す特徴的な平面をもつ。尾垂木付二手先組物で随所に彫刻を施し、細部意匠も秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012141"},{"id":"00005793","register_sub_id":"101","register_pk":"106781","name":"世尊寺赤門","kana":"せそんじあかもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97231917,"lng":138.3693252,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.3m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0212","desc":"境内南寄り，本堂の正面に建つ。四脚門，切妻造，桟瓦葺。本柱，控柱ともに円柱，粽付とし，貫で固める。梁行貫上に太瓶束を立てて母屋を受けるが，棟木，母屋，桁を各々海老虹梁で繋ぐ。組物は平三斗。禅宗様を基調とするが，随所に独特な技法と意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005793"},{"id":"00005791","register_sub_id":"101","register_pk":"106779","name":"世尊寺表門","kana":"せそんじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97280938,"lng":138.36926986,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0210","desc":"境内北隅の参道入口で道路に面して建つ。一間の腕木門，切妻造，桟瓦葺。軸部は本柱の前後に控柱を立て，本柱と貫を通して固める。軒は腕木で軒桁を受け，棟木から軒桁に厚板を掛け渡して化粧野地とする。太い柱を使い境内正面の重厚な景観を形成してる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005791"},{"id":"00005795","register_sub_id":"101","register_pk":"106783","name":"世尊寺家財蔵","kana":"せそんじかざいぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.972424,"lng":138.368881,"geo_status":"db","era":"天保2／明治20移築","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造2階建、瓦葺、建築面積30㎡","structure_material":"木造2階建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0214","desc":"境内のほぼ中央，書院に至る参道に面して建つ。桁行６．５ｍ，梁間４．５ｍ，木造２階建，切妻造，桟瓦葺。南面と西面に下屋が取り付く。外観は正面側を漆喰仕上げ，側面等を下見板張とする。２階の窓は漆喰の額縁を鳥居形に造る丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005795"},{"id":"00005787","register_sub_id":"101","register_pk":"106775","name":"世尊寺書院","kana":"せそんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97244321,"lng":138.36861905,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0209","desc":"本堂西北隅に廊下を介して接続。桁行９ｍ，梁間１０ｍ。木造平屋建，入母屋造，桟瓦葺，側廻りにガラス引戸を建て込む。内部は和室４室をほぼ田の字型に配し，四周に縁を廻らす。鷹の間には２間幅の床の間を設ける。屋根を高くつくり，威厳のある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005787"},{"id":"00005794","register_sub_id":"101","register_pk":"106782","name":"世尊寺宝蔵","kana":"せそんじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.972221,"lng":138.368881,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積14㎡","structure_material":"土蔵造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0213","desc":"境内南端の高台に建つ。桁行３ｍ，梁間４ｍ，土蔵造平屋建，切妻造，屋根は置屋根，桟瓦葺。妻入として庇柱を立て，正面庇を延ばす。庇柱には木鼻付絵様虹梁を通し，柱上には絵様実肘木を置く。扉廻りの漆喰彫刻は技巧的で，特に正面意匠が華やかである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005794"},{"id":"00005782","register_sub_id":"101","register_pk":"106770","name":"世尊寺本堂","kana":"せそんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市竹田643","lat":37.97233874,"lng":138.36879704,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積301㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"15 － 0208","desc":"境内南西の山裾に東面して建つ。桁行１７．５ｍ，梁間１５．５ｍの身舎の両側に下屋が付く。木造平屋建，切妻造，桟瓦葺，正面向拝付。側廻りは柱上の絵様実肘木で桁を受け，軒は一軒繁垂木。内部は正面一間を外陣として内陣を広く取る。日蓮宗寺院の大型本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005782"},{"id":"00010574","register_sub_id":"101","register_pk":"201148","name":"善徳寺経堂","kana":"ぜんとくじきょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市吉川区国田51","lat":37.190093,"lng":138.429889,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積33㎡","structure_material":"土蔵造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"15－0409","desc":"土蔵造の経蔵に木軸の覆堂を架け、置屋根状に宝形造瓦葺の屋根を載せる。覆堂は下部を簓子下見板張、上部を開放として飛貫位置に虹梁を組み、南正面に唐破風造の向拝を付す。向拝廻りの鳳凰や龍の彫刻は池山甚太郎の手になり、精緻で躍動感のある優作である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010574"},{"id":"00012518","register_sub_id":"101","register_pk":"367813","name":"善良寺庫裏","kana":"ぜんりょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市西栄町1293","lat":38.051853,"lng":139.400818,"geo_status":"geocoded","era":"天明5年（1785）／昭和前期移築、昭和55年・平成18年改修","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積324㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0492","desc":"本堂北側に東面して建つ。切妻造銅板葺の平屋建で正面南端に切妻造の玄関と渡廊下、背面南端に宝形造の御殿が接続する。内部は玄関から連なる控間付の書院、その奥の小書院、北側の大書院等からなる。下越地方における江戸後期真宗寺院庫裏の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012518"},{"id":"00012517","register_sub_id":"101","register_pk":"367812","name":"善良寺本堂","kana":"ぜんりょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市西栄町1293","lat":38.051853,"lng":139.400818,"geo_status":"geocoded","era":"寛政6年（1794）／明治44年・昭和47年・同62年・平成21年改修","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積327㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"15 － 0491","desc":"旧中条町中心部の真宗寺院。本堂は東正面の入母屋造銅板葺、向拝一間付。側廻りは出組、中備蟇股、二軒繁垂木とする。正面の中備に大ぶりで独特な形態の蟇股を用い、向拝虹梁の木鼻には躍動感のある龍の彫刻を施す。下越地方の江戸後期真宗本堂の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012517"},{"id":"00013081","register_sub_id":"101","register_pk":"368360","name":"大輪寺経蔵","kana":"だいりんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県胎内市東本町2069-2","lat":38.05576944,"lng":139.40818333,"geo_status":"db","era":"安政4年（1857）／昭和15年・平成15年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造平屋建、金属板葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0522","desc":"境内南東方に南北棟で西面して建つ。置屋根形式の平屋建で、正面に向拝を付け、壁は中塗仕上として腰に下見板を張る。内部は一室とし、東に仏壇を設ける。向拝海老虹梁は葡萄に栗鼠を丸彫りし、また仏壇回りには雲龍の彫刻を付すなど時代の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013081"},{"id":"00013080","register_sub_id":"101","register_pk":"368359","name":"大輪寺庫裏","kana":"だいりんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県胎内市東本町2067-3","lat":38.056,"lng":139.40828889,"geo_status":"db","era":"大正9年／平成15年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造2階一部平屋建、金属板葺、建築面積370㎡","structure_material":"木造2階一部平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0521","desc":"本堂の東側に、軒唐破風付の表玄関を経て接続し、南北棟の入母屋造で建つ。二列に室を並べ、西列は天井を高めて、東列は二階を設けて衆寮などに供する。表玄関東脇の飯台座は一六畳大の板間とする。建ちの高い近代的な禅院庫裏である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013080"},{"id":"00013083","register_sub_id":"101","register_pk":"368362","name":"大輪寺山門","kana":"だいりんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市東本町2069-2","lat":38.05571111,"lng":139.4079,"geo_status":"db","era":"文久3年（1863）／昭和31年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造2階建、瓦葺、建築面積19㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0524","desc":"境内中軸の中央に建つ二階建鐘楼門。一間一戸門であるが、扉は持たず開放的に作る。下層は成の高い彫刻付きの頭貫を入れて広く開口を取る。上層は三間に割り、台輪を入れて尾垂木付二手先を組み、中備や支輪、頭貫に彫刻を施す。大工の高い技量がうかがえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013083"},{"id":"00013084","register_sub_id":"101","register_pk":"368363","name":"大輪寺総門","kana":"だいりんじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県胎内市東本町2069-2","lat":38.05528056,"lng":139.40772778,"geo_status":"db","era":"嘉永5年（1852）頃／昭和37年改修","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造、銅板葺、間口3.0m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0525","desc":"米沢街道に面した境内南辺中央に開く四脚門。山門、本堂と直線に並び、境内の中軸を成す。石積基壇上に建ち、本柱を円柱、控柱を角柱とする。切妻造、瓦棒銅板葺の屋根をかける。姿形は端整で、細部意匠にも優れており、境内の正面を飾るに相応しい門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013084"},{"id":"00013082","register_sub_id":"101","register_pk":"368361","name":"大輪寺土蔵","kana":"だいりんじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県胎内市東本町2067-3","lat":38.05563333,"lng":139.40806944,"geo_status":"db","era":"昭和3年／昭和61年移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積35㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0523","desc":"庫裏の南方に南北棟で建つ。隣地で鍛冶を営んだ三國家の家財蔵を曳家した。置屋根形式の二階建で、西面して下屋を付ける。漆喰仕上で、腰は海鼠壁、水切りなどには黒漆喰を用いて対比的に見せる。小庇には鶴亀の鏝絵を付けるなど、見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013082"},{"id":"00013079","register_sub_id":"101","register_pk":"368358","name":"大輪寺本堂","kana":"だいりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県胎内市東本町2067-3","lat":38.05609722,"lng":139.40802222,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積337㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0520","desc":"米沢街道沿いの市街地に境内を占める曹洞宗寺院。本堂は境内中軸北寄りに南面して建つ六間取の方丈形式。大間回りを太い虹梁で固め、正面広縁はもとは前半を土間とした。簡明な意匠ながら、要所に彫刻欄間を嵌め、須弥壇回りのみ円柱に出組を組んで荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013079"},{"id":"00010571","register_sub_id":"101","register_pk":"201145","name":"高田別院鐘楼","kana":"たかだべついんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106154,"lng":138.238742,"geo_status":"db","era":"文化3年（1806）／平成18年改修","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造、銅板葺、面積18㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"15－0406","desc":"本堂南東に建つ、方一間、吹放ち形式の鐘楼で、入母屋造銅板葺。切込み接ぎの石積基壇上に建ち、粽付丸柱を礎盤上に立て、腰貫、飛貫、頭貫で固め、台輪を廻し尾垂木付二手先組物を詰組とする。頭貫下には彫刻欄間を嵌める。境内南の景観を構成する鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010571"},{"id":"00010572","register_sub_id":"101","register_pk":"201146","name":"高田別院大門","kana":"たかだべついんだいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106284,"lng":138.239516,"geo_status":"db","era":"文政10年（1827）","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造、瓦葺、面積64㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"15－0407","desc":"本堂正面、道路に面して建つ大型の三間三戸八脚門。禅宗様の尾垂木付三手先組物で軒を大きく張り出し、入母屋造の大屋根を支持する。軸部はケヤキの素木造とし、随所に精緻な彫刻や地紋彫を施して賑やかに飾るなど、高い大工技術を示す。別院に相応しい大門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010572"},{"id":"00010573","register_sub_id":"101","register_pk":"201147","name":"高田別院塀","kana":"たかだべついんへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106282,"lng":138.239529,"geo_status":"db","era":"文政10年（1827）","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造、瓦葺、総延長56m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"15－0408","desc":"大門の左右に取り付き、前方に矩折れにのびる塀で、各々長さ二八メートルとし、切妻造の屋根を架ける。、切石布積基壇に建ち、表側壁面は築地塀形式の白壁に五本の定規筋を引き、裏側は竪板張とする。また大門脇に潜戸を開ける。大門とともに別院の寺格を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010573"},{"id":"00010570","register_sub_id":"101","register_pk":"201144","name":"高田別院本堂","kana":"たかだべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"新潟県","address":"新潟県上越市寺町二丁目字大六5437-1","lat":37.106378,"lng":138.238412,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鋼板葺、建築面積552㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"15－0405","desc":"鉄筋コンクリート造で再建された真宗大谷派別院の本堂。内部の内陣は伝統的な真宗本堂に倣うが、外陣は畳敷の無柱空間とし集会場機能を兼ねる。外観は当時「印度風」と称された特異な形態で、ヴォールト屋根や正面ポーチの尖塔飾りなど特徴的な外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010570"},{"id":"00012139","register_sub_id":"101","register_pk":"352938","name":"潮音寺観音堂","kana":"ちょうおんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県小千谷市大字小栗田字岡田962","lat":37.331608,"lng":138.790463,"geo_status":"db","era":"文化14年(1817)","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"15-474","desc":"本堂の北東に南面する。入母屋造の三間堂で軒唐破風付の向拝一間を付す。内陣後方に須弥壇を設け中央に厨子を安置する。組物は三手先で霊鳥や霊獣の彫刻を付し、中備や欄間も濃密に飾る。彫刻は向拝廻りでは躍動感があり、内外陣境は繊細で高い技量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012139"},{"id":"00012140","register_sub_id":"101","register_pk":"352939","name":"潮音寺山門","kana":"ちょうおんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県小千谷市大字小栗田字岡田961","lat":37.33129,"lng":138.790425,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"15-475","desc":"本堂の東方に建つ。間口二・九メートル、切妻造の四脚門。本柱、控柱とも円柱で頭貫と台輪で固める。組物は三斗組、中備は拳鼻付三斗。妻面は本柱から挿肘木と皿斗付巻斗、実肘木で頭貫を受け、妻飾は笈形付大瓶束で、細部まで彫刻を施し整った意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012140"},{"id":"00013068","register_sub_id":"101","register_pk":"368323","name":"長願寺本堂","kana":"ちょうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新発田市下興野字下堅田108","lat":37.93560556,"lng":139.27054444,"geo_status":"db","era":"寛延3年（1750）／大正2年改修","year":1750,"year_source":"db","year_min":1750,"year_max":1750,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積 364㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"15 － 0509","desc":"市南西にある境内中央に南面して建つ真宗寺院本堂。入母屋造で、正面に三間幅の一間向拝を付し、外陣周囲の広縁を堂内に取り込む。内陣は後門形式で、余間の背後に法衣の間を設け、東面余間脇に堂座敷を張出す。真宗本堂の典型に沿いつつ特異な形式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013068"},{"id":"00007742","register_sub_id":"101","register_pk":"128614","name":"長谷寺内門","kana":"ちょうこくじうちもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97645636,"lng":138.41766462,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.8m、左右袖塀及び潜り付","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"15-0318","desc":"宝蔵の脇にたち、参道と本堂の敷地を画する。袖塀と潜りを脇に付ける一間一戸薬医門。本柱、控柱とも円柱。本柱控柱間の頭貫端が、本柱前方に出て、その上に木鼻付平三斗を梁行に組み、梁を支持する。背面は桁行に三斗詰組。簡素ながら、特殊な架構になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007742"},{"id":"00007738","register_sub_id":"101","register_pk":"108720","name":"長谷寺奥の院","kana":"ちょうこくじおくのいん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97701184,"lng":138.41686479,"geo_status":"db","era":"江戸中期／昭和52改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0314","desc":"観音堂西方の小高い位置に南面して建つ。方三間宝形造。円柱で、平三斗組とし、二軒繁垂木。正・側面中央を開口、正面両脇を格子窓とし、他は板壁。内部は一室で、中央間後寄りに円柱を建て、正面に両開桟唐戸、側面を板壁とし、本尊を安置する。簡明な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007738"},{"id":"00006815","register_sub_id":"101","register_pk":"107797","name":"長谷寺廻廊及び札所","kana":"ちょうこくじかいろうおよびふだしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97684442,"lng":138.4173727,"geo_status":"db","era":"明治前期／平成13改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋一部2階建、鉄板葺、建築面積44㎡","structure_material":"木造平屋一部2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0287","desc":"鐘堂と観音堂を繋ぐ廊下で、参道石段沿いに建つ。南北棟の鉄板葺、幅１．８ｍ長さ１７ｍに及び、参道側を上部横連子腰竪板壁、反対側を全面竪板壁とする。観音堂際を桁行３．７ｍ梁間３．０ｍ２階建、切妻造鉄板葺の札所とし、２階参道側に切子格子の窓を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006815"},{"id":"00007737","register_sub_id":"101","register_pk":"108719","name":"長谷寺観音堂","kana":"ちょうこくじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.9768152,"lng":138.4175758,"geo_status":"db","era":"元禄4／宝暦10・明治21改修","year":1691,"year_source":"db","year_min":1691,"year_max":1691,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積191㎡、厨子3基付","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0313","desc":"山腹に南面して建つ。規模の大きな五間堂で、外陣及び内陣、脇陣からなり、内陣後方の各間に厨子を安置する。側柱を方柱、入側柱を円柱とする。側まわりは木鼻付平三斗で、内陣正面を支輪付二手先とし、内陣天井に梵字を飾る。江戸中期における密教本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007737"},{"id":"00007739","register_sub_id":"101","register_pk":"108721","name":"長谷寺経蔵","kana":"ちょうこくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97693366,"lng":138.41715222,"geo_status":"db","era":"寛政11","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積24㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0315","desc":"観音堂の西方に東面して建つ。桁行４．９ｍ梁間４．９ｍの土蔵造で、東西棟の桟瓦葺置屋根とし、出入口に切妻造屋根を掛ける。腰板張の白漆喰仕上げとし、開口部上部に唐破風の鏝絵を飾る。内部は一室で、中央に六角輪蔵を備え、輪蔵内に傅大士を祀る壇を作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007739"},{"id":"00006813","register_sub_id":"101","register_pk":"107795","name":"長谷寺庫裏","kana":"ちょうこくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.9766009,"lng":138.41789452,"geo_status":"db","era":"江戸後期／昭和53改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、茅葺（鉄板仮葺）、建築面積366㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0284","desc":"本堂の東方に南面して建つ、入母屋造妻入茅葺（鉄板仮葺）の建物。桁行１９ｍ梁間１４ｍで、西面南寄りに本堂の玄関、北寄りに２階建の奥茶の間が続く。南面奥行３間を土間とし、その奥を床上とし居室を設ける。太い軸組が、棟高の高い風格ある外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006813"},{"id":"00006814","register_sub_id":"101","register_pk":"107796","name":"長谷寺護摩堂","kana":"ちょうこくじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97663983,"lng":138.41751633,"geo_status":"db","era":"明治前期／昭和59改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0285","desc":"本堂西方の高い位置、仁王門から観音堂への参道に西面して建つ。桁行７．４ｍ梁間７．１ｍの切妻造桟瓦葺で、南面に本堂への廊を付設する。内部は西正面に広縁、東に南・北２室を設け、南室に不動尊を安置し、護摩壇を置く。仏壇まわりを組物や木鼻などで飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006814"},{"id":"00006817","register_sub_id":"101","register_pk":"107799","name":"長谷寺米蔵","kana":"ちょうこくじこめぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97641151,"lng":138.41788811,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0289","desc":"庫裏の南方、中之蔵の東に、西面して建つ。桁行８．２ｍ梁間４．５ｍ、切妻造桟瓦葺の置屋根で、西面に切妻造桟瓦葺の小規模な蔵前を付ける。外壁は上部を漆喰仕上げとし、腰簓子下見板張。庫裏正面への通路両脇に中之蔵と建ち並び、重厚な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006817"},{"id":"00006966","register_sub_id":"101","register_pk":"107948","name":"長谷寺鐘堂","kana":"ちょうこくじしょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97667473,"lng":138.41748937,"geo_status":"db","era":"江戸中期／Ｍ9移築改修・Ｓ59改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、鉄板葺、建築面積7.4㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0286","desc":"護摩堂の北に隣接して建つ。２層からなる楼門風の鐘堂で、南北棟の入母屋造鉄板葺。下層は桁行３．２ｍ梁間２．３ｍで、廊下として使われる。上層は四周に高欄付の縁をまわし、円柱上に平三斗を組み、二軒繁垂木とする。腰組の龍など秀逸な装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006966"},{"id":"00006967","register_sub_id":"101","register_pk":"107949","name":"長谷寺寺務所","kana":"ちょうこくじてらむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97640668,"lng":138.41807615,"geo_status":"db","era":"安政4／昭和中期・53・平成13改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0290","desc":"庫裏の東方、東西棟で建つ。桁行１９ｍ梁間５．４ｍで、切妻造桟瓦葺とする。柱を半間ごとに建て、貫を数段通す。真壁造で、正・側面等に簓子下見板を張り、軒は出桁を四周にまわす。もとは東半部が家畜小屋、西半部が納屋で、小屋裏に茅を保管した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006967"},{"id":"00006816","register_sub_id":"101","register_pk":"107798","name":"長谷寺中之蔵","kana":"ちょうこくじなかのくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.9764052,"lng":138.41777648,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0288","desc":"本堂の東南に位置する。桁行５．５ｍ梁間４．５ｍ規模の２階建土蔵。切妻造桟瓦葺の置屋根。北面に両開戸をたて、切妻造桟瓦葺の蔵前を付ける。外壁は下見板を張り、一部に漆喰壁を見せる。南面は高い石垣上に建ち、山腹に構える伽藍景観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006816"},{"id":"00007741","register_sub_id":"101","register_pk":"108723","name":"長谷寺仁王門","kana":"ちょうこくじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97604879,"lng":138.41763446,"geo_status":"db","era":"享保3／天明元改修","year":1718,"year_source":"db","year_min":1718,"year_max":1718,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0317","desc":"境内南端の山麓に建つ。三間一戸八脚門、切妻造桟瓦葺。両端間を囲い、後間に仁王像を安置し、中央の通路には扉をたてない。円柱で、禅宗様出組を詰組とし、二軒繁垂木。妻は特徴的な蟇股を使う二重虹梁蟇股。支輪等に彫物を施す。伽藍正面を画する質の高い門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007741"},{"id":"00007740","register_sub_id":"101","register_pk":"108722","name":"長谷寺宝蔵","kana":"ちょうこくじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97639908,"lng":138.41768065,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"15-0316","desc":"観音堂から下がった中段、本堂の西南に位置する。桁行４．５ｍ梁間４．５ｍの土蔵造２階建、東西棟の切妻造妻入桟瓦葺置屋根とし、東正面に切妻造桟瓦葺屋根を掛ける。白漆喰仕上げで、腰に下見板を張る。南・西面は高く石垣を造り、参道石段の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007740"},{"id":"00006812","register_sub_id":"101","register_pk":"107794","name":"長谷寺本堂","kana":"ちょうこくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97667776,"lng":138.41762009,"geo_status":"db","era":"安永6／平成17改修","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造平屋一部2階建、茅葺（銅板仮葺）、建築面積409㎡","structure_material":"木造平屋一部2階建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0283","desc":"山腹に南面して建つ桁行２１ｍ梁間１４ｍの寄棟造茅葺（鉄板仮葺）の仏堂。非対称の六間取方丈形式を基本に、後列両端室を前後２室に分け、南・西面に広縁、東面に居室を設ける。後列中室に須弥壇を構え、二手先組物や蟇股を飾る。規模壮大な講堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006812"},{"id":"00006818","register_sub_id":"101","register_pk":"107800","name":"長谷寺味噌蔵","kana":"ちょうこくじみそぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市長谷字豊13","lat":37.97646371,"lng":138.41811184,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積13㎡","structure_material":"土蔵造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0291","desc":"庫裏の東、寺務所の北に建つ。桁行４．５ｍ梁間３．０ｍの妻入で、切妻造桟瓦葺の置屋根とする。中塗仕上げ腰下見板張とし、北と東面に窓を開け、西正面に引込み戸をたて、庇を付ける。内部は板壁で、土間とする。庫裏東面にある生活に関する施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006818"},{"id":"00011920","register_sub_id":"101","register_pk":"210927","name":"長徳寺行在所","kana":"ちょうとくじあんざいしょ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946418,"lng":139.32191,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、銅板葺、建築面積109㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"15-462","desc":"庫裏の南に接続する。新発田の豪商白勢家の新潟別邸のうち明治天皇のための行在所を移築したもの。一階は玉座と推定される一〇畳を中心に三室を配し、二階に二室を設ける。長押を廻さず数寄屋風意匠とし、床脇や建具などの意匠は大正期らしい瀟洒な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011920"},{"id":"00011919","register_sub_id":"101","register_pk":"210926","name":"長徳寺庫裏","kana":"ちょうとくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946616,"lng":139.322045,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積427㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-461","desc":"本堂の西に廊下を介して接続する。居室部となる二四畳の客間や一二畳のチャノマ等の諸室の奥に三室の新御殿を設け、廊下を隔てて矩折れに古御殿二室を配する。居室部は差鴨居で柱間を広く造り、ダイドコロ上部の梁組に時代相応の特徴を見せる大規模な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011919"},{"id":"00011922","register_sub_id":"101","register_pk":"210929","name":"長徳寺山門及び塀","kana":"ちょうとくじさんもんおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946994,"lng":139.322482,"geo_status":"db","era":"天保12年（1841）","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"山門 木造平屋建、瓦葺、間口3.0m 塀 木造、瓦葺、総延長16m","structure_material":"山門 木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-464","desc":"境内の北面に開く四脚門。切妻造、桟瓦葺で、両脇の潜戸と矩折の塀を付ける。本柱は角柱、控柱は面取角柱とし、腰貫、頭貫で固め、妻面は笈形付き大瓶束で棟木を受ける。細部意匠には江戸後期の特徴が見られ、控柱は腰貫より下に反りを付ける形状とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011922"},{"id":"00011921","register_sub_id":"101","register_pk":"210928","name":"長徳寺鐘楼","kana":"ちょうとくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946817,"lng":139.322584,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-463","desc":"本堂と山門を結ぶ参道の東に南面する。基壇上に建ち、石造礎盤上に几帳面取の角柱を立て、腰貫と虹梁型頭貫で固める。台輪を廻し中備は蟇股、格天井を張る。参道側のみ虹梁絵様は波や菊を彫り、屋根入母屋造の妻飾にも波形彫刻の拝懸魚を飾り正面性を重視する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011921"},{"id":"00011918","register_sub_id":"101","register_pk":"210925","name":"長徳寺本堂","kana":"ちょうとくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新発田市大栄町二丁目甲1203","lat":37.946478,"lng":139.322299,"geo_status":"db","era":"嘉永3年（1850）／昭和59年改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積510㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"15-460","desc":"新発田城跡の南にある真宗大谷派寺院本堂。側背面は舟肘木だが、正面は出組で両端は龍の尾垂木を付け向拝の蟇股や手挟も力量ある彫刻で飾る。典型的な真宗本堂平面で西側の余間脇に床の間・床脇のある座敷二室を付す。天井は小組格天井で、虹梁や蟇股も上質。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011918"},{"id":"00005950","register_sub_id":"101","register_pk":"106935","name":"長福寺山門","kana":"ちょうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市宮本東方町1592","lat":37.442951,"lng":138.743195,"geo_status":"db","era":"安永3","year":1774,"year_source":"db","year_min":1774,"year_max":1774,"year_label":null,"structure":"木造、銅板葺、間口4.5m、袖塀付","structure_material":"木造","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0232","desc":"本堂の西方前方に建つ。門口４．５ｍ規模の１間１戸四脚門で，南北の両脇に矩折の袖塀を従える。屋根は切妻造，銅板葺で，軒は二軒繁垂木につくる。骨格は木太く，堂々とした構えをとる。棟札から年代があきらかで，彫物や絵様にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005950"},{"id":"00005949","register_sub_id":"101","register_pk":"106934","name":"長福寺本堂","kana":"ちょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県長岡市宮本東方町1592","lat":37.442787,"lng":138.743713,"geo_status":"db","era":"安政2","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積449㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0231","desc":"西を正面として建つ。桁行７間，梁間６間規模，入母屋造で，正面に３間の向拝をのばす。内部は梁行を５間とし，前方３間を外陣，後方２間を内陣・余間とし，外陣矢来前の桁行方向に虹梁３本を渡す。地元の大工棟梁高木甚兵衛元綱の作。幕末期真宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005949"},{"id":"00014783","register_sub_id":"101","register_pk":"519041","name":"二王子神社本殿・幣殿及び拝殿","kana":"にのうじじんじゃほんでん・へいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和後","pref":"新潟県","address":"新潟県新発田市田貝2010","lat":37.90508333,"lng":139.45028333,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積306㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"15 - 0587","desc":"市街地南東の二王子岳の中腹に位置する神社。入母屋造妻入鉄板葺の南北棟で、北面に軒唐破風付の向拝を配す。内部は１室の畳敷とし、上・下拝殿及び幣殿を段差を設けて階段上に並べて格天井を張り、本殿を南へ突出させる。軒柱が周囲を巡る壮大な外観の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014783"},{"id":"00013703","register_sub_id":"101","register_pk":"505229","name":"日本基督教団燕教会","kana":"にほんきりすときょうだんつばめきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県燕市中央通二丁目3361他","lat":37.66584167,"lng":138.93013333,"geo_status":"db","era":"昭和5年／昭和39年・同45年増築","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積206㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"15 － 547","desc":"市の中心部に位置。木造二階建切妻造桟瓦葺。西面し、奥に細長い平面を持ち、前面に便所、背後に倉庫を突出する。一階に旧保育園、二階に礼拝所を配し、外壁は下見板張で二階に半円アーチ窓を並べ、正面妻に十字架を掲げる。地域の景観を形成する木造教会。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013703"},{"id":"00007197","register_sub_id":"101","register_pk":"108179","name":"古峯神社本殿","kana":"ふるみねじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区白新町1-1-11","lat":37.920746,"lng":139.21750614,"geo_status":"db","era":"天保8／明治期移築","year":1837,"year_source":"db","year_min":1837,"year_max":1837,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0298","desc":"覆屋内に東面して建つ。軒唐破風付の隅木入一間社春日造で、両側面に千鳥破風を付ける。屋根こけら葺。組物は出組とし、支輪を四周にまわし、妻は二重虹梁大瓶束とする。軸部等に地紋彫、扉や壁面には浮彫、向拝に龍などの丸彫を施し、彫物装飾で社殿を充たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007197"},{"id":"00006821","register_sub_id":"101","register_pk":"107803","name":"本光寺大門","kana":"ほんこうじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00592984,"lng":138.27968276,"geo_status":"db","era":"弘化3／昭和48移築","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造、瓦葺、間口2.5m、両脇潜付","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0294","desc":"通りに面して建つ、潜り付１間薬医門。切妻造桟瓦葺。本柱を粽付円柱、控えを方柱とし、礎盤上に建てる。妻面に虹梁状の貫を２段に架し、大瓶束や木鼻、笈形、立ち上がりの大きい海老虹梁などを用い、見応えのある架構を造る。禅宗様を意識した秀逸な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006821"},{"id":"00006820","register_sub_id":"101","register_pk":"107802","name":"本光寺鐘楼","kana":"ほんこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00590615,"lng":138.27974484,"geo_status":"db","era":"明治19／昭和48移築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造、瓦葺、面積6.5㎡","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0293","desc":"本堂の東北に東西棟で建つ。方１間吹放ち鐘楼で、基壇上に内転びのある方柱を建て、腰貫と内法貫を入れ、虹梁状の頭貫と台輪で固める。組物は平三斗組、中備は木鼻付平三斗。妻は虹梁大瓶束で、軒を二軒繁垂木とする。伝統的な様式になる標準的な吹放ち鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006820"},{"id":"00006822","register_sub_id":"101","register_pk":"107804","name":"本光寺塀","kana":"ほんこうじへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00596036,"lng":138.27969092,"geo_status":"db","era":"江戸末期／昭和48移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、延長14m","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0295","desc":"大門の東西、通り沿いに建つ。東側折曲り延長９．０ｍ西側折曲り延長４．８ｍで、総高２ｍに及ぶ。高さ１ｍの凝灰岩基礎上に土台を置き、柱を建て貫を通し、漆喰仕上げ真壁とする。腕木により桁を介し板軒を支持し、桟瓦を葺く。落ち着いた佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006822"},{"id":"00006819","register_sub_id":"101","register_pk":"107801","name":"本光寺本堂","kana":"ほんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市沢根篭町字浜方39","lat":38.00577831,"lng":138.27974463,"geo_status":"db","era":"江戸後期／昭和10改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積177㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"15 － 0292","desc":"通りの南側に占める敷地のほぼ中央に位置し、北面して建つ。桁行１１ｍの３間堂で、切妻造桟瓦葺。正面から広縁、外陣、矢来内とし、その奥に内陣と左右余間を配する標準的な浄土真宗本堂平面になる。外観は簡明ながら、組物や欄間など丁寧な造作になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006819"},{"id":"00013977","register_sub_id":"101","register_pk":"508237","name":"本成寺表玄関","kana":"ほんじょうじおもてげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62245,"lng":138.94462778,"geo_status":"db","era":"明治28年頃／昭和前期・平成23年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0558","desc":"客殿と庫裏の間を繋ぐ桟瓦葺の南北棟である。東面中央の玄関唐破風には懸魚を三つ飾る。内部は、表玄関の間一〇畳の北が小会議室で、南の応接室は昭和前期改装の洋室である。西には南北廊下を通して客殿と庫裏を結ぶ。重厚な式台玄関が境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013977"},{"id":"00013975","register_sub_id":"101","register_pk":"508235","name":"本成寺客殿","kana":"ほんじょうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62263333,"lng":138.944725,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積571㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0556","desc":"本堂南西に東面して建つ入母屋造の桟瓦葺で向拝を付す。桁行七間の中央三間が格天井の内陣で背面中央に須弥壇を置き脇壇を設ける。南北両脇は棹縁天井の外陣で、四周に縁を廻らせ、北の寂光殿へ渡廊下が延びる。内部は柱を減らして広く伸びやかな空間をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013975"},{"id":"00013976","register_sub_id":"101","register_pk":"508236","name":"本成寺庫裏","kana":"ほんじょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62229722,"lng":138.94452222,"geo_status":"db","era":"明治28年／昭和56年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積567㎡","structure_material":"木造平屋一部2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0557","desc":"境内南西に建つ入母屋造桟瓦葺で、東正面に妻を見せ、北寄りに内玄関、南に御大途玄関を開く。床上中央の囲炉裏の間は二四畳の二室で、前身本堂の柱を削り直した夫婦柱が立つ。南側の寺務所は元は土間であった。客殿南に並び建ち、境内空間を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013976"},{"id":"00013978","register_sub_id":"101","register_pk":"508238","name":"本成寺大書院","kana":"ほんじょうじだいしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62263611,"lng":138.94441389,"geo_status":"db","era":"明治32年頃／平成23年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0559","desc":"客殿の背面と太鼓橋で結ぶ切妻造桟瓦葺である。庫裏の北に中庭を介して接続する。中庭に面して一二間半三室からなる対面の間、中庭西に一〇畳二室の内対面の間を配す。中庭側と内対面の間の南から西に土縁がつくのは雪国らしい。落着いた造作の座敷群である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013978"},{"id":"00013974","register_sub_id":"101","register_pk":"508234","name":"本成寺本堂","kana":"ほんじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県三条市西本成寺一丁目3861他","lat":37.62291111,"lng":138.94537778,"geo_status":"db","era":"明治36年／昭和32年・平成11年改修","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積881㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0555","desc":"三条市街に所在する法華宗陣門流の総本山である。入母屋造の本瓦型金属板葺で、正面の三間向拝は唐破風を三つの懸魚で飾る。内陣は凸型に突出して床を一段高める。背面の突出は後方の真骨塔の遙拝所である。優秀な彫刻を各所に飾る富山大工による壮大な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013974"},{"id":"00009932","register_sub_id":"101","register_pk":"196079","name":"宮川神社拝殿及び幣殿","kana":"みやがわじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県柏崎市大字宮川字向山4027","lat":37.45316677,"lng":138.61205032,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"15 － 0388","desc":"三間四方で正面に一間向拝の付く拝殿と、間口一間で両側に下屋の取付く幣殿からなる。拝殿の組物は出組、中備に蟇股を入れ、向拝虹梁上には龍の丸彫を飾る。拝殿妻飾の虹梁に彫られた左右対称形の渦紋や、蟇股、肘木の繰形などに、棟梁の篠田宗吉の特徴が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009932"},{"id":"00009931","register_sub_id":"101","register_pk":"196078","name":"宮川神社本殿","kana":"みやがわじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県柏崎市大字宮川字向山4027","lat":37.4531325,"lng":138.61198388,"geo_status":"db","era":"文政12","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積4.5㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"15 － 0387","desc":"一間社流造こけら葺の本殿。身舎正面は方立と彫刻付の小脇板を構えて扉を省き、内部に木階二級を設け、その奥を内陣と内々陣に仕切る。組物二手先で中備を蟇股とし、妻は大瓶束に雲紋をあしらった笈形を付ける。頭貫や彫刻の意匠に凝り、時代相応の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009931"},{"id":"00005264","register_sub_id":"101","register_pk":"106252","name":"妙光寺三重小塔","kana":"みょうこうじさんじゅうのしょうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市西蒲区角田浜1056","lat":37.7974558,"lng":138.83017548,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造三重塔、金属板葺、建築面積1.0㎡","structure_material":"木造三重塔","registered":"2006.03.02(平成18.03.02)","register_no":"15 － 0197","desc":"参道脇の池泉の北岸に建つ木造三重，チタン葺の高さ５．２ｍの小塔である。柱を円柱とし，軒を尾垂木を付けた四手先組物で支え，三手と四手の間を軒支輪とし，台輪中央の中備に蟇股を置く。各重に高欄付きの縁を廻す。建設当初の姿を留め，境内景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005264"},{"id":"00005265","register_sub_id":"101","register_pk":"106253","name":"妙光寺山門","kana":"みょうこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県新潟市西蒲区角田浜1056","lat":37.79721241,"lng":138.83027527,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"15 － 0198","desc":"本堂と中門を結ぶ軸線上に建つ。桁行１５尺，梁間１３尺とし，切妻造，桟瓦葺の四脚門で，門扉を付けない。出組，実肘木で丸桁を受け，妻側は二重虹梁蟇股の上に大瓶束をのせ，棟木を支える。頭貫の象鼻や獅子鼻，軒支輪の彫物等に江戸後期の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005265"},{"id":"00005266","register_sub_id":"101","register_pk":"106254","name":"妙光寺鐘楼","kana":"みょうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区角田浜1056","lat":37.7971505,"lng":138.83011102,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、面積12㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"15 － 0199","desc":"境内南側の山際に建つ。桁行１０．４尺，梁間９．７尺で，入母屋造，桟瓦葺とし，角柱四本を内転びに建て，飛貫や頭貫で固める。出三斗で軒桁を支え，中備を蟇股とする。格天井や懸魚等に意匠的特色が見られ，三重小塔，山門と共に境内の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005266"},{"id":"00008437","register_sub_id":"101","register_pk":"134833","name":"楞厳寺山門","kana":"りょうごんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市柿崎区芋島字経ケ峯2727-2","lat":37.24412541,"lng":138.4511316,"geo_status":"db","era":"江戸中期／元文元年（1736）改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、茅葺、間口3.5m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0331","desc":"本堂の南方に南面して建つ、切妻造茅葺の四脚門。本柱と袖柱を地覆と腰長押、頭貫で固め、柱上に大斗を置き、虹梁を架け、中央に蟇股を載せ、棟木を支持。冠木上中央に間斗束を置く。軒は二軒繁垂木。床は四半石敷で、両開戸をたてる。雄渾な雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008437"},{"id":"00008436","register_sub_id":"101","register_pk":"134832","name":"楞厳寺本堂","kana":"りょうごんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県上越市柿崎区芋島字経ケ峯2727-1","lat":37.24461941,"lng":138.45126633,"geo_status":"db","era":"江戸中期／昭和32年・平成20年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積368㎡、鐘楼付","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"15 － 0330","desc":"南面して建つ、桁行二二メートル梁間一六メートル、入母屋造銅板葺の本堂。八間取方丈形式とし、正面に大縁と露縁を通す。側まわりは方柱で、舟肘木を置く。内陣は正面を円柱とし、上部に出組を飾り、来迎壁や須弥壇等を構える。江戸中期の標準的な曹洞宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008436"},{"id":"00002902","register_sub_id":"101","register_pk":"103892","name":"蓮華峰寺大門","kana":"れんげぶじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83562744,"lng":138.28779664,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造、高さ3.7m","structure_material":"石造","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0120","desc":"蓮華峰寺は佐渡島にある真言宗の古刹である。大門は切石を積み上げた高さ約三．七メートルの東西一対の石柱で，西側の石柱に「昭和三年八月一日 青柳貞秀建之」の刻銘がある。北からの参道の入口にあり，寺の入口を示すランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002902"},{"id":"00002910","register_sub_id":"101","register_pk":"103900","name":"蓮華峰寺御霊屋覆屋","kana":"れんげぶじおたまやおおいや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.8365661,"lng":138.28825638,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0129","desc":"東照宮と台徳院御霊屋の覆屋で，切妻造桟瓦葺。側背面三方は板壁で，現状は正面も格子窓付きの板壁で閉ざすが，これは最近のもので，もとは正面開放であった。先々代住職が大正期に建てたと伝える。御霊屋とともに保存を図る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002910"},{"id":"00002913","register_sub_id":"101","register_pk":"103903","name":"蓮華峰寺唐門","kana":"れんげぶじからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83499272,"lng":138.28806386,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積8.54㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0132","desc":"金堂前庭と庫裏客殿の一郭を分ける四脚門で，唐破風はない。親柱を棟木近くまで立ち上げ，側柱とは海老虹梁で繋ぐ禅宗様四脚門の様式で，様式上江戸時代中期の建築と見られる。親柱筋の中央上部には成の高い蟇股を入れるなど雄大な意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002913"},{"id":"00002914","register_sub_id":"101","register_pk":"103904","name":"蓮華峰寺客殿","kana":"れんげぶじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.835396,"lng":138.28804,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積396㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0133","desc":"金堂南方にあり，前身客殿が明治３０年の水害で倒壊した後に建てられた。桁行２４．６メートル，梁間１６．１メートルの山内最大の建築で内部は８室構成で，それと矩の手に巡る広縁からなる。近代の大規模客殿として評価できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002914"},{"id":"00002905","register_sub_id":"101","register_pk":"103895","name":"蓮華峰寺経蔵","kana":"れんげぶじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83604591,"lng":138.28785673,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造平屋建、瓦葺、建築面積34㎡","structure_material":"土蔵造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0124","desc":"鐘楼堂北側に建つ切妻造，桟瓦葺，妻入の土蔵で，正面に１間の向拝を付ける。内部は板張で，化粧棟木に半間毎の化粧垂木をあらわす。向拝細部の様式から江戸時代中期の建築と見られ，近世寺院に見られる土蔵造経蔵の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002905"},{"id":"00002915","register_sub_id":"101","register_pk":"103905","name":"蓮華峰寺護摩堂","kana":"れんげぶじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83560196,"lng":138.287994,"geo_status":"db","era":"元禄3","year":1690,"year_source":"db","year_min":1690,"year_max":1690,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0134","desc":"客殿北側に渡り廊下で接続する入母屋造妻入，桟瓦葺の三間堂。棟札によって元禄３年の建築年代が判明する。組物を出組とし，軒を二軒繁垂木とする。蓮華峰寺の三間堂の中では年代的にも技法的にも中庸を占めるものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002915"},{"id":"00002903","register_sub_id":"101","register_pk":"103893","name":"蓮華峰寺地蔵堂","kana":"れんげぶじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83591727,"lng":138.28851345,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0121","desc":"金堂東方にある末寺宝積院の本堂で，佐渡四国古遍路第一番札所。建物は正面３間，側面３間，屋根宝形造，桟瓦葺で，背面軒下に仏壇を張り出す。棟札により明治２６年の建築が明らかである。蓮華峰寺伽藍及び地方の札所を構成する要素として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002903"},{"id":"00005077","register_sub_id":"101","register_pk":"106067","name":"蓮華峰寺鐘楼堂","kana":"れんげぶじしょうろうどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83607962,"lng":138.28825876,"geo_status":"db","era":"慶長20","year":1615,"year_source":"db","year_min":1615,"year_max":1615,"year_label":null,"structure":"木造2階建、銅板葺、建築面積19㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0123","desc":"金堂北東の台地上にある袴腰付きの鐘楼。上層は桁行３間，梁間２間で四方に腰組付の縁を巡らせ，組物は出組で寄棟造，茅葺形銅板葺の屋根を掛ける。正当な手法からなる鐘楼で，幕末期の改造は大きいが，なお桃山建築の特徴を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005077"},{"id":"00002909","register_sub_id":"101","register_pk":"103899","name":"蓮華峰寺台徳院御霊屋","kana":"れんげぶじだいとくいんおたまや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.8366461,"lng":138.28815652,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、柿葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0128","desc":"台徳院御霊屋は，東照宮と同じくこけら葺の一間社であるが，東照宮は屋根が入母屋造であるのに対し，切妻造妻入である。軸部や軒の彫刻や彩色，組物の形式等は東照宮と同様で，同時期に建てられたと見られる。小規模ながら精緻な技巧を凝らし，残りも良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002909"},{"id":"00002908","register_sub_id":"101","register_pk":"103898","name":"蓮華峰寺東照宮","kana":"れんげぶじとうしょうぐう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83655341,"lng":138.28829063,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、柿葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0127","desc":"八角堂北側の覆屋内に台徳院霊屋と東照宮が左右に並んで建つ。東照宮はこけら葺の一間社で，軸部の外部全体を彫刻，彩色で埋め，組物を三手先とし，軒も彫刻付きの板軒（二軒）とするなど，豪華な仕様を採る。彫刻絵様から江戸時代中期の建築と見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002908"},{"id":"00002916","register_sub_id":"101","register_pk":"103906","name":"蓮華峰寺独鈷堂","kana":"れんげぶじどっこどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.835701,"lng":138.286636,"geo_status":"db","era":"元和8","year":1622,"year_source":"db","year_min":1622,"year_max":1622,"year_label":null,"structure":"石造平屋建、石葺、建築面積3.0㎡","structure_material":"石造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0135","desc":"金堂前庭から西の谷を分け入った奥にある泉の傍に建つ切妻造妻入の石祠。昭和５４年に水害で倒壊し修理されているが，この時に採用されなかった部材に元和八年の刻銘がある。正面を三間に割り，石棟の両端には鬼面を現わすなど，丁寧な仕事を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002916"},{"id":"00002904","register_sub_id":"101","register_pk":"103894","name":"蓮華峰寺仁王門","kana":"れんげぶじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83586515,"lng":138.28805226,"geo_status":"db","era":"文政5","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0122","desc":"金堂東南にある東を正面とする八脚門で両脇間後方に金剛力士を収める。入母屋造桟瓦葺で総円柱，組物二手先の格式の高い細部を持つ。石製の礎盤１２個にはそれぞれ寄進者の名前が刻まれており，崇敬を集めた様子が偲ばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002904"},{"id":"00002906","register_sub_id":"101","register_pk":"103896","name":"蓮華峰寺八角堂","kana":"れんげぶじはっかくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83633634,"lng":138.28830542,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0125","desc":"経蔵北側に建つ銅板葺の八角円堂。江戸時代中期の建築と見られ，内部は柱間毎の三角形の小室に分かれ，それぞれに宮殿を収める。軒の組物は絵様肘木や彫刻を多用した三手先で，全体で雲中の竜を表現するなど異色の造形を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002906"},{"id":"00002907","register_sub_id":"101","register_pk":"103897","name":"蓮華峰寺八祖堂","kana":"れんげぶじはっそどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83649876,"lng":138.28797352,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0126","desc":"金堂北側の丘の上に立つ入母屋造，茅葺形銅板葺の三間堂。組物を異例の五手先とするため，茅葺形と相俟って特に屋根の大きい印象を受ける。内部も虹梁や太瓶束等からなる架構を見せ，全体に彩色を施した迫力のあるもので，八角堂とともに異色の造形を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002907"},{"id":"00002912","register_sub_id":"101","register_pk":"103902","name":"蓮華峰寺密厳堂","kana":"れんげぶじみつげんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83627386,"lng":138.28729366,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0131","desc":"金堂西方に建つ三間堂で，佐渡四国六番札所。宝形造桟瓦葺で，前面に一間向拝を付ける。天保１５年の建築と伝え，小規模な堂であるが組物を出組とし，内部の支輪等に彫刻をあしらうなど，密度の高い仕事である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002912"},{"id":"00002911","register_sub_id":"101","register_pk":"103901","name":"蓮華峰寺無明橋","kana":"れんげぶじむみょうばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県佐渡市小比叡","lat":37.83660497,"lng":138.28717952,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造桁橋、橋長4.1m、幅員1.6m","structure_material":"石造桁橋","registered":"2002.08.21(平成14.08.21)","register_no":"15 － 0130","desc":"奥院弘法堂に至る参道にある石造桁橋。寛政１２年(１８００)の資料に「奥之院御廟之橋」として出てくる。反りをもち、中央の橋脚上の桁受で３筋の橋桁を受ける構造で，３６枚の橋板裏にそれぞれ梵字を刻む。意匠だけでなく技法にも見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002911"},{"id":"00001909","register_sub_id":"101","register_pk":"102899","name":"西永寺六和亭（旧永徳寺本堂）","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲87-8","lat":37.17874536,"lng":138.74651559,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2000.10.18(平成12.10.18)","register_no":"15 － 0111","desc":"庫裏の前方に西面して建つ。もと境内に在った別の寺院本堂で，昭和１０年代に廃寺となった後，現在地に移築された。正面２間半，奥行４間の寄棟造，妻入で，内部は内陣，外陣に分かれ，梁などに絵様を彫るなど小規模ながら整った御堂になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001909"},{"id":"00000679","register_sub_id":"101","register_pk":"101669","name":"彌彦神社神符授与所","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70577465,"lng":138.82801627,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積41㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0024","desc":"表参道が二之鳥居に向かって折れる地点の手前右手，手水舎の向かいに建つ。瓦葺切妻屋根，舟肘木仕様の建物で，銅板葺の裳階は後補である。神苑沿いの東参道からのアプローチを考慮して妻面の構成に意を凝らした造りとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000679"},{"id":"00000665","register_sub_id":"101","register_pk":"101655","name":"彌彦神社摂社乙子神社","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.7066673,"lng":138.82698942,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0010","desc":"摂末社８棟のうち焼失した３棟の復興建築のひとつで，横並び８棟（右端の十柱神社は重要文化財）のうち向かって左より５棟目にあたる。焼失前と同様形式の一間社流造で，浜床・三方縁・脇障子付の社殿になり，屋根を銅板葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000665"},{"id":"00000666","register_sub_id":"101","register_pk":"101656","name":"彌彦神社摂社今山神社","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県西蒲原郡弥彦村大字弥彦2898","lat":37.70669137,"lng":138.82692138,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積5.0㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"15 － 0011","desc":"摂末社８棟のうち焼失した３棟の復興建築のひとつで，横並び８棟のうち向かって左より３棟目にあたる。五代目の今山大神を祭る。七代目を祭る乙子神社と同規模同型式で，浜床・三方縁・脇障子付き，銅板葺，一間社流造とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000666"},{"id":"00007200","register_sub_id":"101","register_pk":"108182","name":"稲荷神社神輿庫","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県新潟市北区葛塚字相生町3293","lat":37.91548643,"lng":139.22094043,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0301","desc":"本殿の南方に位置する。桁行４．５ｍ梁間３．６ｍの切妻造桟瓦葺で、正面に一間向拝を付ける。方柱で三斗組とし、妻は二重虹梁蟇股。軒は一軒疎垂木。内部は床モルタルの１室で、格天井の天井板には花鳥を描く。切妻社殿風の特異な外観になる神輿庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007200"},{"id":"00005270","register_sub_id":"101","register_pk":"106258","name":"有礒正八幡宮釣殿","kana":"ありそしょうはちまんぐうつりどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県高岡市横田町3-1-1","lat":36.74985266,"lng":137.00346675,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"16 － 0076","desc":"桁行３間，梁間２間の規模で，南北棟の銅板葺で，柱を角柱とし，組物を置かずに直接桁を受ける。柱間を蔀戸とし，内側に御簾をかける。幣殿と床高を揃え，両側面に縁と高欄を設ける。本殿と幣殿，拝殿をつなぐ空間として境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005270"},{"id":"00005271","register_sub_id":"101","register_pk":"106259","name":"有礒正八幡宮拝殿及び幣殿","kana":"ありそしょうはちまんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県高岡市横田町3-1-1","lat":36.74975352,"lng":137.00341909,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"16 － 0077","desc":"拝殿は１室で，正側面の各間に板戸を建て込み，正面に向拝を付ける。幣殿は一段高い板敷の床とし，左右に翼室を張出す。屋根は両殿を一体化し，八棟造，銅板葺とし，棟に千木，鰹木を置く。社殿の正面を構成し，伝統技法を用いつつ変化に富んだ外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005271"},{"id":"00005269","register_sub_id":"101","register_pk":"106257","name":"有礒正八幡宮本殿","kana":"ありそしょうはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市横田町3-1-1","lat":36.74990742,"lng":137.00349609,"geo_status":"db","era":"明治16","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"16 － 0075","desc":"桁行２間半，梁間２間半の規模で，屋根は東西棟の入母屋造の前後に千鳥破風を付して銅板葺とし，棟に千木と鰹木を置く。組物は拳鼻付の平三斗で中備に蟇股を置き，軒は二軒繁垂木とする。正面及び両側面に縁と高欄を廻し，両側面に脇障子を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005269"},{"id":"00011674","register_sub_id":"101","register_pk":"210690","name":"櫟原神社一の鳥居","kana":"いちはらじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768409,"lng":137.340344,"geo_status":"db","era":"安政7年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"石造、間口4.6m、高さ4.5m","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"16-0130","desc":"境内西寄りに置かれた石造明神鳥居。拝殿へは矩折れに続く。間口四・六メートル、高さ四・五メートルの規模で、内転びの柱に貫を通し、その中央には額束を建てる。柱頭には台輪を載せて笠木・島木を受けている。北陸街道沿いの歴史的景観をいまに伝える鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011674"},{"id":"00011675","register_sub_id":"101","register_pk":"210691","name":"櫟原神社二の鳥居","kana":"いちはらじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768535,"lng":137.34035,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"石造、間口3.5m、高さ3.9m","structure_material":"石造","registered":"2017.06.28(平成29.06.28)","register_no":"16-0131","desc":"一の鳥居を入って矩折れに進み、拝殿を望む方向に建つ石造鳥居。間口三・五メートル、高さ三・九メートルの規模で、貫の両端を柱の外に延ばさない中山鳥居である。均整のとれた鳥居で、滑川旧市街地の東端部にあって、拝殿前の境内景観を整える鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011675"},{"id":"00011673","register_sub_id":"101","register_pk":"210689","name":"櫟原神社拝殿","kana":"いちはらじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768701,"lng":137.340561,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積156㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0129","desc":"入母屋造正背面中央に、切妻造を突出させる構成で、屋根は桟瓦葺。入母屋造部分は前方を拝殿、後方を薬殿と称し、背面突出部は前方を幣殿、奥を祭文殿とする。祭文殿は床高を上げ、前面に木階三級を付す。独特の構成を取る拝所建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011673"},{"id":"00011672","register_sub_id":"101","register_pk":"210688","name":"櫟原神社本殿","kana":"いちはらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県滑川市神明町1177","lat":36.768838,"lng":137.340701,"geo_status":"db","era":"明治5年","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.0㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0128","desc":"櫟原神社は滑川旧市街地の東端部に位置する。石垣を設けた高い位置に建つ切妻造平入の一間社で、屋根は銅板葺。正面に唐破風屋根の向拝を設け、三方に切目縁を廻らし高欄、脇障子を設ける。総欅造りで、井波の彫刻師の手になる脇障子などの彫刻も質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011672"},{"id":"00012320","register_sub_id":"101","register_pk":"531644","name":"歓盛寺山門","kana":"かんせいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県高岡市二塚1316","lat":36.70496389,"lng":137.002875,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口4.7m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"16-139","desc":"東西棟の切妻造桟瓦葺、三間一戸薬医門で、境内正面に建つ。組物は実肘木付三斗、格天井を張り、軒は一軒繁垂木とする。妻飾の虹梁大瓶束笈形付、中備蟇股、冠木廻り等を精緻な彫刻で飾る。瑞龍寺の脇門を移築したとも伝わり、風格ある寺観をかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012320"},{"id":"00012319","register_sub_id":"101","register_pk":"531643","name":"歓盛寺離座敷","kana":"かんせいじはなれざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県高岡市二塚1316","lat":36.70515278,"lng":137.00240278,"geo_status":"db","era":"明治39年","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"16-138","desc":"尼僧学林の講師控所として建てられた。総二階建、東西棟の切妻造桟瓦葺で、本堂背面下手に接続する。上下階にそれぞれ八畳二室を置き、奥の部屋はともに座敷飾の床を備える。質素ながら丁寧なつくりで、最初期の曹洞宗尼僧教育の様子を伝える貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012319"},{"id":"00012318","register_sub_id":"101","register_pk":"531642","name":"歓盛寺本堂","kana":"かんせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県高岡市二塚1316","lat":36.70503333,"lng":137.00253611,"geo_status":"db","era":"江戸中期／明治18年・同39年・平成13年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積308㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"16-137","desc":"庄川左岸の田園地帯にあり、東面して建つ。入母屋造桟瓦葺、内部は八間取方丈形式で、前面に幅一間の広縁を通し、中央南寄りに向拝、背面に開山堂を張出す。側廻りは舟肘木。全体に簡明なつくりで、当地における江戸中期の曹洞宗末寺本堂の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012318"},{"id":"00000203","register_sub_id":"101","register_pk":"101193","name":"大楽寺庫裏","kana":"だいらくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市立町2-9","lat":36.78037222,"lng":137.0879726,"geo_status":"db","era":"明治2","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造2階建，瓦葺，建築面積399㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0013","desc":"切妻造、妻入で、数寄屋風の大広間、梁をみせた民家風の部屋等をもつ大規模な庫裏。棟札から明治２年９月の大火直後の建築と知られる。古くからの大伽藍を偲ばせる建物であり、小学校の仮校舎に使用されたとも伝える等、その存在が広く知られた建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000203"},{"id":"00000202","register_sub_id":"101","register_pk":"101192","name":"大楽寺本堂","kana":"だいらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"富山県","address":"富山県射水市立町2-9","lat":36.78031887,"lng":137.08823176,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積263㎡","structure_material":"土蔵造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"16 － 0012","desc":"桁行７間、梁間１１間と大規模な土蔵造の本堂。屋根は切妻造、桟瓦葺になる。平面は浄土宗本堂の伝統的な様式を踏襲しており、奥行きの深い構成になる。正面の向拝は明治２２年の改築で、獅子頭はじめ柱や虹梁を漆喰塗とする精巧な構えとなり見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000202"},{"id":"00012321","register_sub_id":"101","register_pk":"531645","name":"白山宮鞘堂","kana":"はくさんぐうさやどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"富山県","address":"富山県南砺市上梨字家平713他","lat":36.41125,"lng":136.930525,"geo_status":"db","era":"宝暦10年(1760)／大正10年増築、昭和55年移築","year":1760,"year_source":"db","year_min":1760,"year_max":1760,"year_label":null,"structure":"木造平屋建、茅葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"16-140","desc":"五箇山の上梨地区にある白山宮本殿の鞘堂。入母屋造茅葺妻入、軸部は角柱に絵様肘木を載せ、軒はせがい造とし、正面を虹梁と蟇股で飾る。内部は土間の内陣に本殿を安置し、外陣は板敷で格天井に天井絵を描く。豪雪地帯における信仰形態を反映した宗教施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012321"},{"id":"00011669","register_sub_id":"101","register_pk":"210685","name":"養照寺本堂","kana":"ようしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県滑川市領家町551他","lat":36.762329,"lng":137.335636,"geo_status":"db","era":"大正5年頃／平成22年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積452㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"16-0125","desc":"滑川旧市街の西端に建つ。本堂は入母屋造桟瓦葺、桁行五間、梁間六間、向拝三間の規模で、正面及び両側面前半に切目縁を巡らす。向拝以外は全て円柱で、外陣を一室として広くとり、各柱間に虹梁を架け装飾豊かな内部空間とする。滑川の歴史を伝える真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011669"},{"id":"00003408","register_sub_id":"101","register_pk":"104398","name":"尾山神社東神門","kana":"おやまじんじゃひがししんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市尾山町11-1","lat":36.565441,"lng":136.656158,"geo_status":"db","era":"江戸後期／明治3・昭和38移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2003.07.01(平成15.07.01)","register_no":"17 － 0070","desc":"もと金沢城二ノ丸唐門と伝えられる。卯辰山招魂社神門として移されていたものを昭和３８年現在地に移築。１間１戸の向唐門で，屋根は桟瓦葺。主柱は円柱，控柱は角柱で，両開き桟唐戸をたて，頭貫上は蟇股と波彫刻，桁上は大瓶束と雲竜彫刻をあしらう。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003408"},{"id":"00003962","register_sub_id":"101","register_pk":"104952","name":"金沢神社拝殿","kana":"かなざわじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市兼六町1-3","lat":36.56050133,"lng":136.66285031,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0092","desc":"本殿の北前方に建つ。入母屋造，桟瓦葺，妻入で，正側面に刎高欄付切目縁，正面に向拝を付ける。軒は三斗組，一軒半繁垂木，妻は虹梁豕叉首とする。内部は主体部を格天井，本殿側は両下屋根の釣殿形式とし，釣殿部分に高欄付の反り橋を設けるなど特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003962"},{"id":"00003961","register_sub_id":"101","register_pk":"104951","name":"金沢神社本殿（旧明倫堂鎮守）","kana":"かなざわじんじゃほんでん（きゅうめいりんどうちんじゅ）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市兼六町1-3","lat":36.56043459,"lng":136.6629181,"geo_status":"db","era":"寛政6","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"17 － 0091","desc":"はじめ藩校の鎮守として建築された。大型の流造社殿で，身舎円柱上に連三斗，妻は虹梁大瓶束で，虹梁で繋ぐ向拝は水引虹梁，連三斗を備える。間口の広い平面で，身舎正面にも虹梁型頭貫を通し中備蟇股を置き，胡麻殻決りの幣軸を付けて特徴ある構えにつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003961"},{"id":"00001377","register_sub_id":"101","register_pk":"102367","name":"時習庵土蔵（旧実性院土蔵）","kana":"じしゅうあんどぞう（きゅうじっしょういんどぞう）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市大聖寺神明町20","lat":36.30416089,"lng":136.30675435,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"17 － 0038","desc":"主屋の後方に位置し，背後の山際に建つ２階建ての土蔵。平成９年に現在地に移築の際，腐食していた１階壁体部分はコンクリートに改めている。もとは加賀藩の枝藩大聖寺藩主前田家の菩提寺である実性院にあったもので，天明年間の建築と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001377"},{"id":"00008445","register_sub_id":"101","register_pk":"134841","name":"聖興寺北土蔵","kana":"しょうこうじきたどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52319965,"lng":136.56521147,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0216","desc":"南蔵の北側、裏玄関を挟んで建つ。南北棟で、切妻造桟瓦葺の置屋根とする。桁行三・七メートル梁間四・一メートルの土蔵造二階建。内部は竪板張で、一、二階とも一室。外壁は漆喰仕上げで、腰を黒漆喰、通り側は腰石貼とし、重厚な印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008445"},{"id":"00008440","register_sub_id":"101","register_pk":"134836","name":"聖興寺客殿","kana":"しょうこうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市西新町23-3他","lat":36.5232646,"lng":136.56485427,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦及び銅板葺、建築面積421㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0211","desc":"大きな唐破風造の玄関を構える大式台を南正面に配し、その北奥に南北二室からなる仏間、その東北に十二畳半を二室南北に並べ、その東西に土縁などを設ける。金の壁紙、黒塗の格天井を張り、漆塗と螺鈿細工の欄間を飾るなど、華美な意匠になる接客空間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008440"},{"id":"00008443","register_sub_id":"101","register_pk":"134839","name":"聖興寺庫裏","kana":"しょうこうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52313471,"lng":136.56501055,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積245㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0214","desc":"客殿大式台の東南に西面して建つ。木造二階建、切妻造桟瓦葺。西面に大きく妻を見せ、庇を付設し、玄関や中玄関を開ける。妻面の庇より上方は、上半部を束や貫、舟肘木等で飾り、下半部は下見板張とし、格子付の大きい窓を穿つ。近代的な庫裏の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008443"},{"id":"00008442","register_sub_id":"101","register_pk":"134838","name":"聖興寺座敷","kana":"しょうこうじざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52324024,"lng":136.56506331,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積140㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0213","desc":"茶室と客殿の間の中庭南方に位置する。木造二階建、寄棟造桟瓦葺。一階は前後二列に各三室を配し、西・南・東面に廊下を通し、北面に土縁を設ける。二階も同様に間仕切り、南北に縁を付設する。主要室にトコや棚を設ける和風建築で、接客や居室として使われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008442"},{"id":"00008447","register_sub_id":"101","register_pk":"134843","name":"聖興寺山門","kana":"しょうこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52288913,"lng":136.56456811,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0218","desc":"切妻造本瓦葺の四脚門。出組とし、妻側は中備に蟇股、平側は中央に出組、その間に蟇股を置く。さらに妻は持ち出した虹梁上に笈形付大瓶束をたてるなど密度の濃い軒まわりとする。本柱間の龍彫物や、木鼻や扉まわりの彫刻など、高い装飾性を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008447"},{"id":"00008446","register_sub_id":"101","register_pk":"134842","name":"聖興寺鐘楼","kana":"しょうこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52292161,"lng":136.56449504,"geo_status":"db","era":"江戸中期／昭和51年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0217","desc":"本堂の南方に位置し、戸室石を積み上げた高い基壇上に建つ。入母屋造桟瓦葺の方一間吹放ち鐘楼。粽付の円柱を四方転びにたて、貫や台輪で固め、三斗組を置く。中備は木鼻付平三斗。一軒疎垂木で、格天井を張る。安定した外観をもつ、瀟洒な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008446"},{"id":"00006715","register_sub_id":"101","register_pk":"107698","name":"聖興寺草風庵","kana":"しょうこうじそうふうあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52293589,"lng":136.56430135,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積61㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"17 － 0167","desc":"千代尼堂の南側に東面して建つ。南北棟の入母屋造に、東西棟の入母屋造屋根を付ける凸型の構成を取る。正面中央の突出する部分が広間８畳で、北に茶室４畳、背面から南側に水屋等、正面に土庇を設ける。穏やかな意匠でまとめられた、開放的な草庵風茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006715"},{"id":"00008441","register_sub_id":"101","register_pk":"134837","name":"聖興寺茶室","kana":"しょうこうじちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1他","lat":36.52334781,"lng":136.5652135,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0212","desc":"客殿の東方、中庭を挟んだ位置に建つ。入母屋造桟瓦葺で、寥々庵や翠光軒、暢音堂と称する茶室や座敷を中心に水屋や土縁が配され、東北隅に待合や雪隠を付設する。寥々庵は二畳台目で、磨丸太のトコ柱や竹の框が用いられる。品格のある近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008441"},{"id":"00006714","register_sub_id":"101","register_pk":"107697","name":"聖興寺千代尼堂","kana":"しょうこうじちよにどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"石川県","address":"石川県白山市中町56-1","lat":36.52301904,"lng":136.56429881,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積14㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"17 － 0166","desc":"通りに南面する境内の西寄りに東面して建ち、北側に千代尼塚がある。千代尼１５０回忌に記念事業で造られた宝形造茅葺（銅板仮葺）の堂宇。方１間半規模で、背面に仏壇を付ける。天井は化粧垂木を放射状に配し、側面には丸窓を穿つ。数寄屋風仏堂の佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006714"},{"id":"00008439","register_sub_id":"101","register_pk":"134835","name":"聖興寺本堂","kana":"しょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県白山市西新町23-3","lat":36.52320168,"lng":136.56461276,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積577㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0210","desc":"境内中央後方に南面して建つ。桁行二一メートル梁間二二メートル、入母屋造本瓦葺で、正面に一間向拝を付ける。外陣や柵内、内陣などからなる典型的な真宗本堂平面になる。総円柱で、側まわりを二手先斗栱詰組とするなど、風格ある外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008439"},{"id":"00008444","register_sub_id":"101","register_pk":"134840","name":"聖興寺南土蔵","kana":"しょうこうじみなみどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県白山市西新町24-1","lat":36.52311847,"lng":136.56519726,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"17 － 0215","desc":"庫裏の東方、境内の東端に位置する。南北棟で、切妻造桟瓦葺の置屋根とする。桁行九・一メートル梁間四・三メートルの土蔵造二階建。内部や妻面は漆喰仕上げ。通り側の東面は中塗仕上げとし、鳥居型に一、二階の窓を囲い、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008444"},{"id":"00006827","register_sub_id":"101","register_pk":"107809","name":"總持寺祖院香積台","kana":"そうじじそいんこうしゃくだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県輪島市門前町門前壱2-1他","lat":37.286171,"lng":136.769745,"geo_status":"db","era":"昭和29頃","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造2階建、瓦葺、建築面積584㎡、廊下付","structure_material":"木造2階建","registered":"2008.03.07(平成20.03.07)","register_no":"17 － 0172","desc":"仏殿の西に所在する２階建の庫裏。切妻造妻入桟瓦葺で、下屋庇をまわす。内部は多くの居室や大台所を間仕切り、北正面から東面の下屋と東面の廊下が回廊の一部をなす。正面は中央間口を２間とし、その両脇や２階に花頭風窓に格子を設け、開放的な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006827"},{"id":"00006831","register_sub_id":"101","register_pk":"107813","name":"總持寺祖院禅悦廊","kana":"そうじじそいんぜんえつろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県輪島市門前町門前壱2-1他","lat":37.28642535,"lng":136.76988121,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"17 － 0176","desc":"山門と香積台を繋ぐ、南北３３ｍの廊下。両下造桟瓦葺で、大祖堂正面を一段切り上げる。伽藍正面側の西面は花頭風の窓を穿ち、格子を設け、腰板壁、小壁漆喰仕上げとし、東面は花頭を略す。床土間で、化粧屋根裏天井。大祖堂正面の威風ある構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006831"},{"id":"00006830","register_sub_id":"101","register_pk":"107812","name":"總持寺祖院白山井戸","kana":"そうじじそいんはくさんいど","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県輪島市門前町門前壱2-1他","lat":37.28647442,"lng":136.76994155,"geo_status":"db","era":"明治45頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、面積5.3㎡","structure_material":"木造","registered":"2008.03.07(平成20.03.07)","register_no":"17 － 0175","desc":"回廊内、大祖堂正面の西方に位置する。井桁組の井戸に、方１間吹放ち宝形造桟瓦葺の井戸屋を設ける。柱間各２．３ｍで、方柱を頭貫と台輪で固め、三斗組とし、中備に蟇股を入れる。一軒扇垂木で、格天井を張る。重厚な建造物群の中、軽やかな佇まいになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006830"},{"id":"00009266","register_sub_id":"101","register_pk":"194059","name":"宝円寺庫裏","kana":"ほうえんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県金沢市宝町358","lat":36.5597853,"lng":136.67011098,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積385㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0243","desc":"本堂東側に建ち、木造二階建、建築面積三八五平方メートル、切妻造桟瓦葺で、本堂寄りに玄関を構える。北面庭側に客間や方丈の間を配し南半は台所などとし、二階は廊下の両側に座敷などを並べる。伝統的平面の一階と広い接客施設の二階を併せ持つ大型の庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009266"},{"id":"00009267","register_sub_id":"101","register_pk":"194060","name":"宝円寺山門及び築地塀","kana":"ほうえんじさんもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市宝町358","lat":36.55934407,"lng":136.67038547,"geo_status":"db","era":"明治32年頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"山門 木造、瓦葺、間口2.8m 築地塀 木造、瓦葺、総延長8.4m","structure_material":"山門 木造","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0244","desc":"境内入口に建つ山門と左右の塀である。山門は大型の一間薬医門、切妻造桟瓦葺で、男梁上の三斗で軒桁を受け、冠木上には龍を象った蟇股を飾る。築地塀は精緻な石積基礎上に建ち、両端を前方に出した配置とする。禅院の結界に相応しい厳格な構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009267"},{"id":"00009265","register_sub_id":"101","register_pk":"194058","name":"宝円寺本堂","kana":"ほうえんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市宝町358","lat":36.55966038,"lng":136.6698314,"geo_status":"db","era":"明治5年頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積666㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0242","desc":"境内奥に南東面して建つ。桁行二四・八メートル梁間一八・一メートル、入母屋造桟瓦葺で、正面に軒唐破風付の玄関を構え、背面に開山堂を張出す。堂内は内陣と大間を中心に四列八室を配し、縁を廻らせる。標準的な曹洞宗本堂平面をもつ藩主菩提寺の大型本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009265"},{"id":"00005273","register_sub_id":"101","register_pk":"106261","name":"本泉寺手水舎","kana":"ほんせんじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市二俣町子8","lat":36.55833969,"lng":136.76501804,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、面積5.7㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"17 － 0146","desc":"本堂前方南東寄に建つ木造桟瓦葺の手水舎。断面六角形の柱３本を内転びに立て，アーチ状の梁を渡して丸桁を支える。屋根棟頂部には帽子状の石を据える。大工石崎清左衛門の手になり，明治初期の新しい建築様式への取り組みを表す独特な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005273"},{"id":"00016661","register_sub_id":"101","register_pk":"579145","name":"龍門寺本堂","kana":"りゅうもんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和後","pref":"石川県","address":"石川県七尾市小島町リ15","lat":37.04881,"lng":136.953249,"geo_status":"db","era":"江戸前期／昭和29年改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積346㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"17 - 0323","desc":"市街地西方の山中に位置する曹洞宗寺院の本堂。境内中央に南面して建つ、寄棟造平入桟瓦葺で正面西寄りに向唐破風造の向拝を付す。平面は八間取で正面に土間と広縁を通した典型的な方丈形式の本堂。内陣正面に円柱を立て、虹梁や拳鼻の絵様に古式を残す仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016661"},{"id":"00005272","register_sub_id":"101","register_pk":"106260","name":"若草教会（旧日本基督教団金沢教会）礼拝堂","kana":"わかくさきょうかい（きゅうにほんきりすときょうだんかなざわきょうかい）れいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市若草町13-44","lat":36.54472476,"lng":136.65965604,"geo_status":"db","era":"明治24／昭和30移築","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積172㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"17 － 0145","desc":"礼拝堂，祈祷室，和室をＬ字に配する木造平屋建。和室部のみ２階建とし，屋根は急勾配の切妻造，桟瓦葺とする。プロテスタントらしい装飾を排除した内部空間は，天井を張らずに吹き抜けとし，挟み梁とタイ・バーを組合わせた軽快な小屋組を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005272"},{"id":"00000042","register_sub_id":"101","register_pk":"101032","name":"小浜聖ルカ教会","kana":"おばませいるかきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県小浜市千種2-14-3-1","lat":35.50181897,"lng":135.74765567,"geo_status":"db","era":"明治30／昭和6改造","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"煉瓦造・木造2階建、瓦葺、建築面積144㎡","structure_material":"煉瓦造・木造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"18 － 0001","desc":"明治30年に建設された煉瓦造の教会堂を昭和６年に改造し，煉瓦造の１階部に木造の礼拝堂が２階にのる形とした建物。改造時の設計はバーガミニー，施工は奈良の大木吉太郎である。両者は聖公会の教会を多く手がけたが，その作風をよく示した一例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000042"},{"id":"00006711","register_sub_id":"101","register_pk":"107694","name":"願念寺本堂","kana":"がんねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県福井市石新保町18字下屋敷割35","lat":36.14818766,"lng":136.10842192,"geo_status":"db","era":"文化3／大正7増築","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積434㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"18 － 0057","desc":"通り北側の敷地西端に東面して建つ７間堂。１間向拝を付ける入母屋造で、越前赤桟瓦で葺く。柱上二手先組物を置き、軒は二軒繁垂木。内部は浄土真宗の特徴的な平面になり、外陣の彩色画や矢来内の龍の墨画、内陣前の彫刻など華やかな装飾が施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006711"},{"id":"00007486","register_sub_id":"101","register_pk":"108468","name":"西光寺表門","kana":"さいこうじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県鯖江市杉本町31字向垣内42-1","lat":35.98246869,"lng":136.17004313,"geo_status":"db","era":"江戸前期／江戸中期移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口3.1m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0078","desc":"七曲りに西面する一間薬医門。本柱上に冠木を渡し、男梁を架け、その上に木鼻付三斗を組み、格天井を張る。軒は二軒繁垂木、妻は虹梁大瓶束で笈形を付ける。屋根は切妻造桟瓦葺。間口に対して成の高い門で、木鼻や絵様など近世初頭に遡る意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007486"},{"id":"00008451","register_sub_id":"101","register_pk":"134847","name":"聖徳太子堂","kana":"しょうとくたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県越前市平和町58","lat":35.89957554,"lng":136.1627955,"geo_status":"db","era":"嘉永元年（1848）／明治16年改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"18 － 0086","desc":"旧武生市の市街地に位置する。正面一間側面二間、正・側面に組高欄付の切目縁をまわし、正面に一間向拝、背面に仏壇を付設。宝形造桟瓦葺で、笏谷石の相輪を飾る。円柱で三斗組、一軒半繁垂木。内部は一室とし、格天井を張る。地域で護持される堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008451"},{"id":"00013377","register_sub_id":"101","register_pk":"368555","name":"陽願寺客殿","kana":"ようがんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市本町154","lat":35.900025,"lng":136.16398611,"geo_status":"db","era":"昭和17年頃","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造2階建、瓦葺、建築面積71㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0207","desc":"洋館の西に接続する南北棟で二階建の入母屋造。桁行中央に階段室を設け、二階南の一〇畳主座敷に、床、棚、書院を設け、南に縁を付す。階段から北は上下階とも六畳二室で、二階は数寄屋風座敷、一階北室は内仏の間とする。寺院内の私的空間の有り様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013377"},{"id":"00013373","register_sub_id":"101","register_pk":"368460","name":"陽願寺庫裏","kana":"ようがんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.89998056,"lng":136.16455278,"geo_status":"db","era":"明治前期／昭和30年代増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積292㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0203","desc":"本堂北に建つ切妻造の東西棟で、東正面の妻壁を大虹梁と海老虹梁で飾る。東の玄関は上部に重厚な小屋組を現す。北の台所は土間に床板を張り、中央の板敷は小屋裏を居室とする。南の式台玄関を対面所から移築するなど、一部改造があるが近世以来の様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013373"},{"id":"00013375","register_sub_id":"101","register_pk":"368462","name":"陽願寺御殿","kana":"ようがんじごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.9,"lng":136.16417222,"geo_status":"db","era":"明治35年頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積169㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0205","desc":"対面所の西に続く東西棟である。西の座敷と東の次の間は各一〇畳で、座敷の西面に大床を設け、南に畳敷の広縁を通し、落縁と土縁が付く。座敷北の御座の間は奥の六畳を上段に造り、床、棚、書院を設ける。本山門主の接遇を想定した上質な空間を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013375"},{"id":"00013380","register_sub_id":"101","register_pk":"368466","name":"陽願寺鐘楼","kana":"ようがんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.89960556,"lng":136.16488333,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0210","desc":"境内東辺中央に開く山門南側の南北棟で入母屋造。反りのある切石積基壇に建ち、礎盤上に円柱を立てる。虹梁形内法貫は木鼻を獅子とする。頭貫と台輪は彫刻で飾る。組物は出組詰組で、軒は二軒扇垂木とする。禅宗様を基調とした手の込んだ造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013380"},{"id":"00013374","register_sub_id":"101","register_pk":"368461","name":"陽願寺対面所","kana":"ようがんじたいめんしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.89996389,"lng":136.16435278,"geo_status":"db","era":"明治前期／明治44年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0204","desc":"庫裏の西に続く東西棟。東から広間二〇畳と使者の間一六畳で、対面所一六畳は西面に床と棚を飾る。使者の間と対面所の南は一間幅の畳敷広縁とする。欄間は竹の節である。対面所の西背後の松の間は六畳の小座敷で控の間とする。高い格式を備えた接遇施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013374"},{"id":"00013379","register_sub_id":"101","register_pk":"368465","name":"陽願寺土蔵","kana":"ようがんじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.90013889,"lng":136.16402778,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積51㎡","structure_material":"土蔵造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0209","desc":"境内の北西隅に建つ東西棟である。東妻に瓦葺の下屋を付し南半に戸口を設け、北半に漬物小屋を造る。外壁は白漆喰塗に簓子下見張とし、妻壁も塗込めて母屋の形を見せる。小屋組は緩い曲がりの梁に束立で棟木と母屋を受ける。境内背後の景観を構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013379"},{"id":"00013378","register_sub_id":"101","register_pk":"368464","name":"陽願寺納骨堂","kana":"ようがんじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市本町154","lat":35.900025,"lng":136.16484722,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造平屋地下1階建、瓦葺、建築面積21㎡","structure_material":"鉄筋コンクリート造平屋地下1階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0208","desc":"境内の北東隅に建つ宝形造で相輪を戴く。洗出しの基壇をもち、南正面扉口を門形の枠で飾り、両側面は出窓状に壁面を張り出し縦長窓を開く。背面下屋の仏壇両脇から基壇内の納骨室に到る。正側面の高窓から、柔らかく外光を取込むなどの造形を試みている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013378"},{"id":"00013372","register_sub_id":"101","register_pk":"368459","name":"陽願寺本堂","kana":"ようがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市本町154","lat":35.899725,"lng":136.16434444,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積617㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0202","desc":"武生中心市街の真宗寺院で、境内中央に東面して建つ寄棟造の大型本堂である。外陣には広縁と落縁を廻らすが、両側面の広縁奥寄りを堂内化して外陣を拡張する。内外陣境は金箔と彩色で飾る。北余間に鞘の間を取り込んで御簾の間とするなど、高い寺格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013372"},{"id":"00013376","register_sub_id":"101","register_pk":"368463","name":"陽願寺洋館","kana":"ようがんじようかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県越前市本町154","lat":35.89996944,"lng":136.16403889,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0206","desc":"御殿の南面落縁から西に続く東西棟で寄棟造とする。中央の応接室は、南面を台形平面のベイウインドウとし、庭への扉口を設ける。西は書斎で両室とも漆喰塗天井に中心飾りを付す。北に片廊下を通し、御殿との間は便所とする。落ち着いた意匠の応接空間である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013376"},{"id":"00000209","register_sub_id":"101","register_pk":"101199","name":"市川教会","kana":"いちかわきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県西八代郡市川三郷町市川大門907","lat":35.56280619,"lng":138.49989896,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積91㎡","structure_material":"木造平屋建","registered":"1997.06.12(平成9.06.12)","register_no":"19 － 0011","desc":"木造平屋建、桟瓦葺の簡素な建物で、天然石の高基礎上に建つ。内部は一室で、正面に半円形の祭壇を設け聖餐台を置く。袴越屋根及び切妻とする玄関妻壁の意匠が特徴的で、漆喰仕上げとする独特の外観は、「今昔通り」と呼ぶ道筋の中心的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000209"},{"id":"00014803","register_sub_id":"101","register_pk":"519061","name":"旧松亭稲荷社","kana":"きゅうしょうていいなりしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲府市中央三丁目263-1他","lat":35.66136667,"lng":138.57482778,"geo_status":"db","era":"明治24年","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積0.1㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"19 - 0174","desc":"敷地北西に位置し、切石積基壇に建つ一間社流造の屋敷神。組物は平三斗、軒は一軒繁垂木とし、屋根は鉄板葺で棟は成の高い箱棟風とする。妻飾は虹梁大瓶束。三方に縁を廻らし、正面に木階を付す。懸魚に透彫りの彫刻を付し、敷地北西の景観をつくる稲荷社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014803"},{"id":"00016373","register_sub_id":"101","register_pk":"536440","name":"昌福寺大玄関及び小玄関","kana":"しょうふくじおおげんかんおよびしょうげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55866944,"lng":138.46401667,"geo_status":"db","era":"安政4年（1857）／明治5年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0189","desc":"本堂と庫裏の間で東向きに構える大玄関と、北側の庫裏に接続する小玄関。大玄関は入母屋造妻入桟瓦葺で前一間を吹放ちの式台とし、虹梁に菊花など流麗な彫刻を飾る。小玄関は両下造の廊下状でかつては前面に出入口があった。規模雄大で格式あるつくりの玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016373"},{"id":"00016378","register_sub_id":"101","register_pk":"536445","name":"昌福寺旧七面堂","kana":"しょうふくじきゅうしちめんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55833056,"lng":138.46388889,"geo_status":"db","era":"天保6年（1835）／平成24年改修","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積27㎡","structure_material":"土蔵造及び木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0194","desc":"本堂南側に東面して建ち、かつて七面大明神を祀った。土蔵造入母屋造妻入桟瓦葺の前面に、切妻造妻入の拝所を設ける。主体部は軒裏まで塗込め、腰に水切を廻し、南北面に小窓を開く。内部は格天井で格間に墨絵や川柳を飾る。当地の七面信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016378"},{"id":"00016372","register_sub_id":"101","register_pk":"536439","name":"昌福寺庫裏","kana":"しょうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55882222,"lng":138.46409722,"geo_status":"db","era":"安政4年（1857）／平成24年改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0188","desc":"本堂の北側に大玄関及び小玄関を介し、東面して建つ庫裏。正面切妻造、背面入母屋造で妻入桟瓦葺とし、内部は土間と広間の上部に豪壮な梁組を現す。正面は軸部を化粧で見せ、上部の虹梁大瓶束、両脇の海老虹梁、特異な形式の火灯窓など装飾性も豊かな庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016372"},{"id":"00016379","register_sub_id":"101","register_pk":"536446","name":"昌福寺山門","kana":"しょうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55847778,"lng":138.46445833,"geo_status":"db","era":"寛政2年（1790）／平成27年改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0195","desc":"本堂正面の境内入口で東面する高麗門。切妻造桟瓦葺で左右に段違屋根の袖塀を設ける。門は本柱を太い楣で固め、柱上の拳鼻付大斗実肘木で棟木を受け、男梁端の実肘木で桁を受ける。木鼻や肘木など随所に華やかな絵様を施す。古刹の表構えをつくる大型の山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016379"},{"id":"00016374","register_sub_id":"101","register_pk":"536441","name":"昌福寺書院","kana":"しょうふくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.558875,"lng":138.46384444,"geo_status":"db","era":"安政5年（1858）／平成24年改修","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0190","desc":"庫裏の西後方に南北棟で建つ書院。入母屋造桟瓦葺で妻飾を雲紋の蟇股や笈形で飾る。座敷は三室を一列に並べて南東面に広縁と濡縁を廻らした開放的なつくり。南端室は西面に間口二間の大床を構え、北端室に床、棚、書院を設えるなど上質なつくりの書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016374"},{"id":"00016377","register_sub_id":"101","register_pk":"536444","name":"昌福寺鐘楼堂","kana":"しょうふくじしょうろうどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55833333,"lng":138.46420556,"geo_status":"db","era":"安永7年（1778）","year":1778,"year_source":"db","year_min":1778,"year_max":1778,"year_label":null,"structure":"木造2階建、瓦葺、建築面積9.4㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0193","desc":"本堂に至る参道の南側に東面し、大振りの自然石積基壇上に建つ鐘楼。方一間、袴腰付、入母屋造妻入桟瓦葺。高欄付の縁を波紋の持送で支え、上層組物は出組、中備は蟇股とし板支輪に地紋彫を施す。軒は二軒繁垂木。持送など賑やかで細部意匠も凝った鐘楼堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016377"},{"id":"00016371","register_sub_id":"101","register_pk":"536438","name":"昌福寺本堂","kana":"しょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55849167,"lng":138.46391667,"geo_status":"db","era":"元文6年（1741）／明治6年改修","year":1741,"year_source":"db","year_min":1741,"year_max":1741,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積317㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0187","desc":"富士川右岸の境内に東面して建つ日蓮宗寺院本堂。桁行約二〇メートル、入母屋造桟瓦葺、正面向拝付。前面に吹放ちの外陣を通し、六室を配す。堂内中央は内陣と内々陣で、両室は格天井中央を折上げ、格間に彩画を飾り荘厳する。下山大工の力量を示す大型本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016371"},{"id":"00016376","register_sub_id":"101","register_pk":"536443","name":"昌福寺虫切加持堂","kana":"しょうふくじむしきりかじどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55870278,"lng":138.46377778,"geo_status":"db","era":"文化9年（1812）／昭和前期改修","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積60㎡、渡廊下付","structure_material":"土蔵造及び木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0192","desc":"本堂北西に東面して建ち、夜泣や癇癪封じの祈祷をする仏堂。宝形造の前面に入母屋造妻入で軒唐破風付の拝所を接続し、桟瓦葺とする。主体部は土蔵造で腰に七宝風紋様を表し正面に掛子塗土戸を開き、内部格天井に菊花を描く。虫切加持の中核となる特異な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016376"},{"id":"00016375","register_sub_id":"101","register_pk":"536442","name":"昌福寺渡廊下","kana":"しょうふくじわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡富士川町青柳町483","lat":35.55876389,"lng":138.46394167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積8.8㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"19 - 0191","desc":"庫裏南西隅から書院南東隅に架かる廊下。平行四辺形平面で桁行四間梁間一間、両下造桟瓦葺、床面を反橋状とするが、屋根と軒を直線につくる。柱を桁行の貫で固め、梁を架けて桁を受ける。両側面の手摺は束を千鳥に配る。書院前面の庭空間に風情を添える廊下。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016375"},{"id":"00013991","register_sub_id":"101","register_pk":"508251","name":"冨士山元祠","kana":"ふじさんげんし","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県富士吉田市上吉田字浅間下1-1","lat":35.47303333,"lng":138.79406111,"geo_status":"db","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"19 - 0163","desc":"北口本宮冨士浅間神社に隣設。北面し、切妻造金属板葺の正面に唐破風向拝、東西に下屋、南に神殿を付す。正面に縁を通し内部北列は踏込床を囲んで板敷、南列は畳敷三室とし中央奥に正面三間の神殿を配す。土足で祈祷を受ける富士講の形態を残す神殿兼拝所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013991"},{"id":"00011300","register_sub_id":"101","register_pk":"209137","name":"御岳公会堂（旧金櫻神社参籠所）","kana":"みたけこうかいどう（きゅうかなざくらじんじゃさんろうじょ）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県甲府市御岳町字上村2368-1","lat":35.767867,"lng":138.556438,"geo_status":"db","era":"昭和10頃／昭和54改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積125㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"19－0084","desc":"金櫻神社境内にあった参籠所を移築し、地区の公会堂としたもの。木造平屋建、鉄板葺であるが、移築前は檜皮葺であったと伝え、小屋組や主要部材は旧状をよく残す。京呂組の架構で内部に柱を建てない大空間など、参籠所としての特色を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011300"},{"id":"00013390","register_sub_id":"101","register_pk":"368475","name":"身延山久遠寺莚師堂","kana":"みのぶさんくおんじえんしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4226","lat":35.38408611,"lng":138.4285,"geo_status":"db","era":"明治9年／平成3年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0153","desc":"中心伽藍北側上方に東面して建つ。桁行四間梁間正面一間背面二間、入母屋造妻入で正面に向拝を付す。内部は前後に二分し、内陣に石造五輪塔を祀る。側柱上の絵様肘木で桁を受ける。内外とも簡素な意匠としつつ扇と天女の蟇股などで向拝回りの装飾性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013390"},{"id":"00013391","register_sub_id":"101","register_pk":"368476","name":"身延山久遠寺奥之院思親閣鐘堂","kana":"みのぶさんくおんじおくのいんししんかくしょうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4222","lat":35.39718889,"lng":138.41723611,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、銅板葺、面積13㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0154","desc":"身延山頂に所在する思親閣の鐘堂で、方一間、入母屋造瓦棒銅板葺。内転びの四本丸柱を虹梁形内法貫と頭貫で固め、各面の虹梁形内法貫上に大瓶束を立てる。組物は出組詰組で、内部は出三斗で鏡天井を受ける。軸部堅牢で軒の出も深く、安定感ある姿形の鐘撞堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013391"},{"id":"00012350","register_sub_id":"101","register_pk":"531674","name":"身延山久遠寺甘露門及び門番所","kana":"みのぶさんくおんじかんろもんおよびもんばんしょ","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38058333,"lng":138.42608333,"geo_status":"db","era":"明治元年／昭和16年移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"甘露門 木造、瓦葺、間口4.5m、左右袖塀及び東方潜り付 門番所 木造、瓦葺、建築面積12㎡","structure_material":"甘露門 木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-126","desc":"本坊域南面に建つ。甘露門は切妻造本瓦葺の高麗門で、左右に袖塀と潜りを付す。本柱上の大斗実肘木で直接棟木を受け、貫や腕木の先端を木鼻風につくる。門番所は入母屋造本瓦葺、門背面東側に接続する。規模も雄大で風格ある表構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012350"},{"id":"00012346","register_sub_id":"101","register_pk":"531670","name":"身延山久遠寺旧書院","kana":"みのぶさんくおんじきゅうしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38155278,"lng":138.42695833,"geo_status":"db","era":"明治9年／平成23年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-122","desc":"大客殿の東北方に建つ。東西棟の入母屋造本瓦葺で、正側面に下屋を付す。内部は上段の間と座敷三室を一列に配し、両側面に畳廊下と縁を通す。長押を二段廻して高くつくった天井、室境を飾る透彫の欄間彫刻など重厚な外観と対比的な内部意匠が特色である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012346"},{"id":"00013386","register_sub_id":"101","register_pk":"368472","name":"身延山久遠寺御真骨堂","kana":"みのぶさんくおんじごしんこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38198333,"lng":138.42592222,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土蔵造平屋建、銅板葺、建築面積106㎡、木造宝塔付","structure_material":"土蔵造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0149","desc":"仏殿西側の傾斜地に建つ前室廊下付の八角円堂で、外部漆喰塗で東西に唐破風付窓を付す。八角平面の内陣須弥壇に金色の宝塔を安置する。周囲の入側に天女等の彫刻を施した海老虹梁を架ける。軸部、組物、彫刻とも金箔や極彩色を施し、格別な荘厳の堂内を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013386"},{"id":"00012342","register_sub_id":"101","register_pk":"531666","name":"身延山久遠寺御真骨堂拝殿","kana":"みのぶさんくおんじごしんこつどうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38170278,"lng":138.42583056,"geo_status":"db","era":"明治14年／平成13年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-118","desc":"本坊域中央の高台に南面して建つ。桁行三間梁間四間、入母屋造平入で、軒唐破風付の向拝を設ける。尾垂木付二手先の組物、二軒扇垂木の深い軒など禅宗様を基調とし、細部彫刻も秀逸。祖師堂と同じ六〇〇年遠忌の再建で、当時の意匠と造形が凝縮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012342"},{"id":"00012356","register_sub_id":"101","register_pk":"531680","name":"身延山久遠寺三昧堂","kana":"みのぶさんくおんじさんまいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3620","lat":35.38300278,"lng":138.42134167,"geo_status":"db","era":"文政5年(1823)／昭和16年移築","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-132","desc":"西谷の高台に南面して建つ。桁行四間梁間三間、入母屋造妻入、正面に向唐破風の向拝を設ける。後方の奥行三間は増築。側廻りは尾垂木付三手先組物の詰組、向拝廻りを緻密な彫刻で充溢し、内部を二重折上格天井とするなど江戸後期の充実したつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012356"},{"id":"00012352","register_sub_id":"101","register_pk":"531676","name":"身延山久遠寺三門","kana":"みのぶさんくおんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3567","lat":35.37895556,"lng":138.42385556,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積295㎡","structure_material":"木造2階建","registered":"2018.05.10(平成30.05.10)","register_no":"19-128","desc":"本坊域への参道口に南面して建つ。本瓦形銅板葺、五間三戸の二階二重門。下層は木鼻付三手先詰組、二軒繁垂木、上層は尾垂木付三手先詰組、二軒扇垂木で、左右の山廊は正面には花頭窓を設ける。規模雄大かつ精緻なつくりで、近代における禅宗様二重門の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012352"},{"id":"00012349","register_sub_id":"101","register_pk":"531673","name":"身延山久遠寺時鐘楼","kana":"みのぶさんくおんじじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38080833,"lng":138.42599167,"geo_status":"db","era":"昭和27年／平成25年改修","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-125","desc":"方一間袴腰付の鐘楼で、屋根は南北棟の入母屋造桟瓦葺。擬宝珠高欄付の縁を三手先腰組で受け、組物間は一二支の彫刻で飾る。上層は粽付円柱を虹梁形頭貫で固め、台輪を廻らして出組の詰組とする。全体にたちの高いつくりで、本坊域入口の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012349"},{"id":"00012359","register_sub_id":"101","register_pk":"531683","name":"身延山久遠寺思親閣仁王門","kana":"みのぶさんくおんじししんかくにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4222","lat":35.39696667,"lng":138.41719722,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-135","desc":"奥之院にある三間一戸八脚門。切妻造瓦棒銅板葺、両端部の前方は土間、後方は板床に壇を設けて仁王像を安置する。軸部は内法虹梁・頭貫で固める。軒廻りは出組に中備蟇股と支輪を付け、妻飾は二重虹梁である。充実した意匠で格調ある表構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012359"},{"id":"00012355","register_sub_id":"101","register_pk":"531679","name":"身延山久遠寺常唱殿","kana":"みのぶさんくおんじじょうしょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3630","lat":35.38160833,"lng":138.42003889,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積341㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-131","desc":"西谷の入口に南面して建つ。入母屋造檜皮葺で、正面に向唐破風の式台玄関を設け、北西に上段の間を接続する。四五畳の広間は祖廟塔に正対する西面を全面ガラス窓とし、折上格天井を張る。復古調の蟇股や舟肘木を用いるなど洗練された意匠の瀟洒な和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012355"},{"id":"00012347","register_sub_id":"101","register_pk":"531671","name":"身延山久遠寺新書院","kana":"みのぶさんくおんじしんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.381325,"lng":138.42694722,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-123","desc":"大客殿東側の人工地盤上に建つ。東西棟の入母屋造桟瓦葺、妻飾は木連格子、側廻りは舟肘木とする。内部は二四畳間を三室並べ、四周に畳縁と縁を廻す。東室と西室には座敷飾を備え、各室とも格天井を高く張る。格式を備えた質の高いつくりの近代書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012347"},{"id":"00012357","register_sub_id":"101","register_pk":"531681","name":"身延山久遠寺水行堂","kana":"みのぶさんくおんじすいぎょうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3620","lat":35.382875,"lng":138.42118889,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造、瓦葺、面積23㎡、水盤付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-133","desc":"苦修練行の一つである水行の場で三昧堂の南西方にある。桁行五・七メートル梁間四メートル、東西棟の切妻造桟瓦葺、吹放ち形式で、水盤を据える。軸部は几帳面取の角柱を虹梁形頭貫で固め、出組の詰組に中備蓑束とし、軒支輪を付けるなど丁寧なつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012357"},{"id":"00012358","register_sub_id":"101","register_pk":"531682","name":"身延山久遠寺瑞門","kana":"みのぶさんくおんじずいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3620","lat":35.38282222,"lng":138.42138333,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-134","desc":"三昧堂の南東方を区切る一間一戸薬医門。切妻造桟瓦葺で、袖塀を左右に延ばす。親柱と控柱を貫で固め、台輪上に大斗舟肘木で軒桁を受け、親柱と控柱の中間に棟木を通す。柱から組物まで木太くつくり、三昧堂の表構えを重厚に固める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012358"},{"id":"00013393","register_sub_id":"101","register_pk":"368478","name":"身延山久遠寺総門茶屋","kana":"みのぶさんくおんじそうもんちゃや","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4007","lat":35.369275,"lng":138.42659167,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0156","desc":"総門内側の参道に西面して建つ。木造平屋建、入母屋造桟瓦葺で正面に下屋を設ける。素木造の簡素な外観で、入口回りの土間を吹放し、内部は二列に並べた和室を基本とする。往時には広大な境内入口で参詣者を接待した施設で、日蓮宗寺院の茶所としても希少。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013393"},{"id":"00012341","register_sub_id":"101","register_pk":"531665","name":"身延山久遠寺祖師堂及び御供所","kana":"みのぶさんくおんじそしどうおよびごくうしょ","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38195278,"lng":138.42506111,"geo_status":"db","era":"明治14年／平成3年・同6年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"祖師堂 木造平屋建、銅板葺、建築面積851㎡ 御供所 木造平屋建、瓦葺、建築面積32㎡","structure_material":"祖師堂 木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-117","desc":"本坊域の大本堂東に南面して建つ。いわゆる撞木造で、側廻りは二手先組物、妻飾は虹梁大瓶束に蟇股を加え向拝に軒唐破風を付す。宗祖六〇〇年遠忌の再建で、豪壮な外観や広大な中陣を含む深遠な内部、精緻な彫刻で飾る内陣など総本山としての威容を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012341"},{"id":"00013387","register_sub_id":"101","register_pk":"368473","name":"身延山久遠寺祖師堂前香炉屋","kana":"みのぶさんくおんじそしどうまえこうろや","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38168056,"lng":138.42500278,"geo_status":"db","era":"明治12年","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、銅板葺、面積4.2㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0150","desc":"祖師堂正面に建つ香炉の覆屋。方一間、宝形造瓦棒銅板葺。禅宗様を基調とし、組物は二手先、軒は二軒扇垂木とする。虹梁形内法貫の中央を湾曲させて花頭枠風とし、獅子鼻や中備の龍彫物も緻密で秀逸。鏡天井に躍動的な龍彫刻を飾る。見応えある意匠の小舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013387"},{"id":"00013389","register_sub_id":"101","register_pk":"368474","name":"身延山久遠寺祖廟域水屋","kana":"みのぶさんくおんじそびょういきみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3628","lat":35.38126944,"lng":138.41944167,"geo_status":"db","era":"昭和19年","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造、檜皮葺、面積10㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0152","desc":"祖廟拝殿手前に東西棟で建つ。桁行一間梁間一間、切妻造檜皮葺で、巨石を加工した水盤を据える。四本柱と桁に太い丸太を使い、梁や垂木、切裏甲等も丸太で構成する。丸太主体の簡素な直線的意匠で、良材を選び、施工も丁寧。拝殿と統一感ある社頭景観を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013389"},{"id":"00012354","register_sub_id":"101","register_pk":"531678","name":"身延山久遠寺祖廟塔","kana":"みのぶさんくおんじそびょうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3628","lat":35.38201667,"lng":138.41836667,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"石造平屋建、建築面積11㎡、石柵付","structure_material":"石造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-130","desc":"日蓮聖人が隠棲した草庵跡地である西谷にある。鉄筋コンクリート造、八角形平面で、乱石積基壇の周囲を石柵で囲い、内部に五輪塔を安置する。上すぼまりの塔身は大理石張とし、笠石は軒先上部に反りがつき頂部に相輪を戴せる。高さ一二メートルの壮大な廟塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012354"},{"id":"00013388","register_sub_id":"101","register_pk":"368556","name":"身延山久遠寺祖廟拝殿","kana":"みのぶさんくおんじそびょうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3628","lat":35.38193056,"lng":138.41878333,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0151","desc":"桁行五間梁間二間の背面に突出を設けて凸字形平面とし、切妻造檜皮葺屋根に千鳥破風を飾る。軸部から軒に至るまで丸太を使い、垂木は詰打とする。床は平石敷の立礼式とし、突出部は一段高く張る。簡明で木太い軸部構成による、重厚な土間床の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013388"},{"id":"00012344","register_sub_id":"101","register_pk":"531668","name":"身延山久遠寺大客殿","kana":"みのぶさんくおんじだいきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38129167,"lng":138.42668611,"geo_status":"db","era":"明治19年／明治後期・昭和46年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積531㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-120","desc":"仏殿納牌堂の東に西面して建つ。入母屋造平入の長大な客殿で、内部は二十畳の上段を含む畳敷の広間五室とする。正面中央に向唐破風の式台付大玄関を設け、東端に入母屋の小玄関を配する。雄大かつ豪壮な外観で総本山の接客機能に相応しい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012344"},{"id":"00012351","register_sub_id":"101","register_pk":"531675","name":"身延山久遠寺太子堂","kana":"みのぶさんくおんじたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3567","lat":35.37927778,"lng":138.42357222,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積30㎡","structure_material":"土蔵造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-127","desc":"三門の北西方に東面して建つ。方三間、宝形造桟瓦葺で、正面に切妻起屋根の向拝を付す。側廻りは三段積の布石上に腰石張とし、上部を漆喰塗で軒先まで塗籠める。内部は奥一間の内陣に仏壇を構え、外陣には格天井を張る。太子信仰の様相を伝える堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012351"},{"id":"00012348","register_sub_id":"101","register_pk":"531672","name":"身延山久遠寺大鐘楼","kana":"みのぶさんくおんじだいしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38145,"lng":138.42474444,"geo_status":"db","era":"明治15年／昭和14年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、面積24㎡","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"19-124","desc":"祖師堂の前方に建つ方三間の吹放ち形式の鐘楼。東西棟の入母屋造本瓦葺で、切石積基壇に太い円柱を立てて、貫で固めるが、中央間は内法虹梁大瓶束とする。組物は三手先詰組で、二軒繁垂木の深い軒を支えた重厚なつくりであり、丸彫や籠彫の彫刻で要所を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012348"},{"id":"00012343","register_sub_id":"101","register_pk":"531667","name":"身延山久遠寺仏殿納牌堂","kana":"みのぶさんくおんじぶつでんのうはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38157222,"lng":138.42625,"geo_status":"db","era":"昭和6年／平成25年改修","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1016㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-119","desc":"桁行七間梁間六間、向拝三間の仏殿が南面して建ち、東西に納牌堂が附属する。仏殿は側廻り二手先組物で、内部には建登せ柱や虹梁を多用する。近代における諸機能の複合化を入母屋造の仏殿に宝形造の二重屋根の納牌堂が連続した独創的な外観でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012343"},{"id":"00012345","register_sub_id":"101","register_pk":"531669","name":"身延山久遠寺法喜堂","kana":"みのぶさんくおんじほうきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4252","lat":35.38095556,"lng":138.426525,"geo_status":"db","era":"明治16年／昭和46年・平成23年改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積625㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-121","desc":"大客殿の南方に西面して建つ。桁行一〇間梁間九間、入母屋造妻入で、内部は正面側の土間部に大黒柱や梁に巨木を用い、重厚な軸組と架構をみせる。出入口両側に連続する花頭窓や妻飾の二重虹梁間に連続する大瓶束など、堂々たる構成の中に近代の意匠が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012345"},{"id":"00013392","register_sub_id":"101","register_pk":"368477","name":"身延山久遠寺発軫閣","kana":"みのぶさんくおんじほっちんかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡身延町身延4007","lat":35.36914167,"lng":138.42603611,"geo_status":"db","era":"元文4年（1739）／昭和55年改修","year":1739,"year_source":"db","year_min":1739,"year_max":1739,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"19 － 0155","desc":"総門内側で参道に直交する石段上に建つ。入母屋造妻入、向拝付の主体部の前面左右に張出しを設ける。内部は畳敷の内外陣と、左右の脇間からなる。内陣鏡天井に飛天を描き、外陣格天井の格間に龍を陽刻する等豊かな装飾をもつ。山中境内入口に建つ堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013392"},{"id":"00012353","register_sub_id":"101","register_pk":"531677","name":"身延山久遠寺本地堂","kana":"みのぶさんくおんじほんちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"山梨県","address":"山梨県南巨摩郡身延町身延3567","lat":35.38261111,"lng":138.42530278,"geo_status":"db","era":"嘉永5年(1852)／平成24年改修","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"19-152","desc":"本坊域背後に南面して建つ。方形の楼造で、正面中央に蔀戸、側面中央に引違格子戸を入れる。三手先で擬宝珠高欄付の縁を受け、上層は尾垂木付三手先と二軒繁垂木で深い軒をつくる。宝形造の屋根は頂部に宝珠を載せる。均整の取れた外観で細部も充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012353"},{"id":"00011129","register_sub_id":"101","register_pk":"205236","name":"山縣神社手水屋","kana":"やまがたじんじゃちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657319,"lng":138.52181,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、銅板葺、面積5.1㎡","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0079","desc":"境内南、参道の西に建つ。桁行一間、梁間一間、切妻造、屋根を銅板一文字葺とする。円形の礎石上に丸柱を垂直に立て、長押と桁で固め、豕扠首で棟木を受ける。軒は直材の疎垂木で化粧小舞を見せる。自然石による手水石を据える。本殿などと意匠を統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011129"},{"id":"00011130","register_sub_id":"101","register_pk":"205237","name":"山縣神社鳥居","kana":"やまがたじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657206,"lng":138.521776,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"鉄筋コンクリート造、高さ6.8m、間口4.5m","structure_material":"鉄筋コンクリート造","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0080","desc":"境内南端の参道入口に建つ。鉄筋コンクリート造、表面モルタル洗出仕上げの神明鳥居で、柱間四・五メートル、高さ六・八メートルの規模を持つ。円柱を掘立柱風に垂直に建て、角材の貫で繋ぎくさびの造形をつくり、丸材の笠木を載せる。近代における鳥居の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011130"},{"id":"00011128","register_sub_id":"101","register_pk":"205235","name":"山縣神社拝殿","kana":"やまがたじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657753,"lng":138.522282,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0078","desc":"本殿の正面に建つ。桁行三間、梁間二間、切妻造、銅板葺で、礎石建の丸柱、妻面の豕扠首、屋根の千木や堅魚木、破風の鞭掛など本殿と共通の意匠とする。室内床は石敷で、天井は疎垂木と化粧小舞の化粧屋根裏とするが、屋根と傾斜が異なり二重の構造を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011128"},{"id":"00011127","register_sub_id":"101","register_pk":"205234","name":"山縣神社本殿","kana":"やまがたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県甲斐市篠原190-1","lat":35.657888,"lng":138.522415,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0077","desc":"江戸時代中期の思想家・山縣大弐を祀る神社の本殿で、境内北奥に南面して建つ。規模は二間四方、銅板葺の神明造で棟に千木・勝男木を飾る。白漆喰の基壇を持ち、身舎は基壇上に土台を置いて柱を立てる。棟持柱を内転とするなど典型的な神明造の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011127"},{"id":"00016511","register_sub_id":"101","register_pk":"574873","name":"頥氣神社菅原社","kana":"いけじんじゃすがわらしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"天保6年（1835）","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、板葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0683","desc":"本殿西側の覆屋内に建つ小規模社殿。総ケヤキの一間社流造板葺で三方に縁を廻らし、正面に木階と浜縁を設ける。庇の虹梁形頭貫は絵様の彫りが深く、木鼻は象鼻とし、上部に波に鶴の彫刻を横溢し意匠を集中する。覆屋内で保存が良く、豊かな装飾を施した小社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016511"},{"id":"00016510","register_sub_id":"101","register_pk":"574872","name":"頥氣神社拝殿及び祝詞殿","kana":"いけじんじゃはいでんおよびのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"文政3年（1820）／昭和50年代改修","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積92㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0682","desc":"本殿の前方に建つ拝殿及び祝詞殿。横長で大型の向拝付拝殿の背面に祝詞殿を突出し、拝殿は入母屋造茅葺（鉄板仮葺）で祝詞殿は切妻造鉄板葺。拝殿は三方を吹放つ板敷の一室で天井張らず小屋組を現し、祝詞殿は棹縁天井を張る。当社の歴史を伝える中心的社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016510"},{"id":"00016512","register_sub_id":"101","register_pk":"574874","name":"頥氣神社宝蔵庫","kana":"いけじんじゃほうぞうこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0684","desc":"拝殿及び祝詞殿の東に西面して建つ祭礼道具の収納蔵。建ちの高い二階建切妻造平入で、屋根は桟瓦葺の置屋根形式とし、入口上部に下屋を付す。小屋は細い曲がり梁を用いた和小屋。外壁はモルタル塗で腰や鉢巻に目地切を施すなど、近代的な特徴を示す土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016512"},{"id":"00016509","register_sub_id":"101","register_pk":"574871","name":"頥氣神社本殿","kana":"いけじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西寺尾字柳島1006","lat":36.57565389,"lng":138.19637889,"geo_status":"db","era":"文政3年（1820）","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.5㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"20 - 0681","desc":"松代城跡北方に位置する神社の本殿。南北に長い敷地の奥、高い石垣上に建つ総ケヤキの一間社流造で正面に木階と浜縁を設け、屋根は銅板葺。庇中備や身舎正面の小壁、妻面、脇障子を飾る動植物や雲紋などの華やかな彫刻が目を惹く。地元大工による上質な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016509"},{"id":"00013543","register_sub_id":"101","register_pk":"504910","name":"上田聖ミカエル及諸天使教会堂","kana":"うえだせいみかえるおよびしょてんしきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県上田市中央三丁目4402-1","lat":36.40280278,"lng":138.25518889,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建一部地階付、瓦葺、建築面積171㎡","structure_material":"木造平屋建一部地階付","registered":"2021.02.04(令和3.02.04)","register_no":"20 － 0567","desc":"市中心部にある木造教会堂。道路に西面して建つ入母屋造妻入で、撞木造とし、四周に下屋を廻して正面に入母屋玄関を付す。内部は面取角柱を立て三廊式とし、欄間や高窓の障子、格天井などに伝統建築の要素を取り入れる。近代和風の教会堂として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013543"},{"id":"00008282","register_sub_id":"101","register_pk":"133924","name":"恵明寺山門","kana":"えみょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西条字表村482","lat":36.55625256,"lng":138.19733999,"geo_status":"db","era":"延宝5年(1677)","year":1677,"year_source":"db","year_min":1677,"year_max":1677,"year_label":null,"structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0365","desc":"伽藍正面に位置する一間棟門。切妻造桟瓦葺。粽付の面取方柱を礎石上に建て、上部に三斗を組み、棟木を支持する。本柱間は楣で固め、男梁女梁を前後に出し、軒桁を支持する。一軒半繁垂木。独特の構造になるが、中備の蟇股や絵様など時代相応である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008282"},{"id":"00008281","register_sub_id":"101","register_pk":"133923","name":"恵明寺鐘楼","kana":"えみょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西条字表村482","lat":36.55621312,"lng":138.19714498,"geo_status":"db","era":"天保4年(1833)","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0364","desc":"本堂の東方、門との間に位置する。桁行一間梁間一間、２階建の鐘楼。入母屋造桟瓦葺。石積基壇上に建ち、柱は四方転びで、直接に桁や梁を支持。軒は一軒疎垂木。１階の下半部を竪板張、他を漆喰仕上げとし、袴腰風に見せる。特異な形態になる鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008281"},{"id":"00008280","register_sub_id":"101","register_pk":"133922","name":"恵明寺本堂","kana":"えみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町西条字表村482","lat":36.55630077,"lng":138.19685357,"geo_status":"db","era":"天保4年(1833)","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"20 － 0363","desc":"象山東麓の境内中央に位置する。桁行五間梁間六間、入母屋造桟瓦葺で、一重裳階付仏殿風の外観とする。正面中央三間に桟唐戸をたて、両端に花頭窓を穿つ。内部は中央４ｍ四方に几帳面取の方柱を建て、その奥に壇を構える。地方における黄檗宗仏殿の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008280"},{"id":"00014812","register_sub_id":"101","register_pk":"519070","name":"加茂神社上屋","kana":"かもじんじゃうわや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市大字西長野字加茂裏213","lat":36.65643333,"lng":138.17758056,"geo_status":"db","era":"嘉永7年（1854）／明治7年改修","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0634","desc":"境内の西に位置する上屋は、一間社流造の形式で桟瓦葺。組物は大斗実肘木で軒は一軒繁垂木とし、妻飾は棟束に笈形を付す。内部は一室で竿縁天井を張り、床を上下段に分け、上段に本殿を安置する。本格的なつくりとした覆屋で、境内の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014812"},{"id":"00014813","register_sub_id":"101","register_pk":"519071","name":"加茂神社拝殿及び祝詞殿","kana":"かもじんじゃはいでんおよびのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字西長野字加茂裏213","lat":36.65640833,"lng":138.17769722,"geo_status":"db","era":"明治7年／明治前期・同18年増築、令和2年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"拝殿 木造平屋建、茅葺（銅板仮葺）、建築面積66㎡ 祝詞殿 木造平屋建、銅板葺、建築面積20㎡","structure_material":"拝殿 木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0635","desc":"入母屋造平入茅葺（銅板仮葺）で、東に軒唐破風付き向拝、西に両下造銅板葺の祝詞殿を付して上屋と接続する。組物は平三斗、軒は一軒扇垂木。三方に高欄付き縁を廻らし脇障子を建てる。内部は一室の畳敷で格天井を張る。向拝廻りを彫刻で飾った華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014813"},{"id":"00014811","register_sub_id":"101","register_pk":"519069","name":"加茂神社本殿","kana":"かもじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字西長野字加茂裏213","lat":36.65643333,"lng":138.17758056,"geo_status":"db","era":"慶應4年（1868）","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0633","desc":"善光寺の南西に位置する神社。上屋内に安置する本殿は東面する一間社流造で、屋根は板を刻んでこけら葺風とした板葺。組物は身舎を出組、庇を出三斗、軒は二軒繁垂木、妻飾は虹梁大瓶束。軒唐破風上に千鳥破風を付し、庇の中備に龍の彫刻を入れ華やかな本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014811"},{"id":"00013108","register_sub_id":"101","register_pk":"368266","name":"旧片山家住宅主屋（小内八幡神社社務所）","kana":"きゅうかたやまけじゅうたくしゅおく（おうちはちまんじんじゃしゃむしょ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県中野市大字安源寺字石原566-1","lat":36.73819722,"lng":138.331625,"geo_status":"db","era":"明治前期／昭和前期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、茅葺（金属板仮葺）、建築面積187㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0553","desc":"中野市市街地西方の小内八幡神社境内にあり、同社神主片山家の住宅として建てられた。当初、屋根は茅葺で、平面は南側下手を土間、上手を四間取の座敷とした。霊壇の間と呼ぶ潔斎の場を持つなど、農家住宅とは異なる社家住宅の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013108"},{"id":"00004545","register_sub_id":"101","register_pk":"105535","name":"旧徳善院庫裏（極意家宿坊）","kana":"きゅうとくぜんいんくり（ごくいけしゅくぼう）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市戸隠3354","lat":36.74158576,"lng":138.08620033,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、茅葺、建築面積305㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0183","desc":"旧本堂の東方に南北棟で建つ。桁行１１間梁間７間半規模，入母屋造，茅葺の外観総２階建で，もとは南半を土間・勝手等とし，西北隅に床・書院付きの１２畳半座敷を置く。たちの高い巨大な茅葺屋根が特徴的で，戸隠における宿坊建築の遺構例として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004545"},{"id":"00004544","register_sub_id":"101","register_pk":"105534","name":"旧徳善院本堂（極意家神殿）","kana":"きゅうとくぜんいんほんどう（ごくいけしんでん）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市戸隠3354","lat":36.74169997,"lng":138.08598142,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺一部鉄板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"20 － 0182","desc":"戸隠神社中社の南に隣接した敷地に位置する。桁行６間半梁間５間規模，寄棟造，茅葺で，中央を仏間（現在は神殿），東を客座敷，西を居間兼書斎とする。文化８年の焼失後の再建と伝え，改造はあるが，大きな茅葺屋根は往時の戸隠の宿坊景観をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004544"},{"id":"00014012","register_sub_id":"101","register_pk":"508272","name":"行善寺本堂","kana":"ぎょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上水内郡信濃町大字古間541","lat":36.80006667,"lng":138.21056111,"geo_status":"db","era":"文政13年(1830)／昭和51年・令和2年改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積259㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"20 - 0599","desc":"北国街道古間宿に位置。桁行七間梁間七間、入母屋造鉄板葺で三間向拝を付す。正側面に縁を廻す。軒は斜めの出梁に天井を張り木負を受け化粧軒を出す。内部は前方を外陣、背後中央を内陣、両脇を余間とする真宗の通例をとる。宿場町に建つ近世に遡る真宗寺院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014012"},{"id":"00012526","register_sub_id":"101","register_pk":"367821","name":"熊野出速雄神社随神門","kana":"くまのいずはやおじんじゃずいじんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字中ノ峯5454","lat":36.535843,"lng":138.250427,"geo_status":"geocoded","era":"文化14年（1817）頃／昭和54年改修","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0529","desc":"境内正面の参道上に南面して建つ八脚門。東西棟の切妻造桟瓦葺で、組物は出三斗、軒は二軒繁垂木、中備は蟇股と間斗束、妻飾は二重虹梁で蕪懸魚を吊る。細身ながら具象的で躍動感ある虹梁等の絵様が時代感覚を表している。森厳な境内の表構えを華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012526"},{"id":"00012525","register_sub_id":"101","register_pk":"367820","name":"熊野出速雄神社摂社侍従大神社拝殿","kana":"くまのいずはやおじんじゃせっしゃじじゅうおおかみしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字中ノ峯5454","lat":36.535843,"lng":138.250427,"geo_status":"geocoded","era":"弘化3年（1846）頃／明治10年・昭和54年改修","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0528","desc":"皆神山頂に鎮座する神社の摂社で、南面して建つ。桁行三間梁間五間、入母屋造銅板葺で、正面に千鳥破風と軒唐破風の向拝を付す。内部は下拝殿と拝殿に分け、背面の突出部に本殿を安置する。出組、二軒繁垂木で、虹梁絵様など細部に時代の特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012525"},{"id":"00005833","register_sub_id":"101","register_pk":"106819","name":"荒神堂","kana":"こうじんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代762","lat":36.569038,"lng":138.202057,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0276","desc":"木造平屋建，桁行７間，梁間３間半，入母屋造，桟瓦葺の妻入で向拝がつく。出組実肘木で中備は蟇股，二軒繁垂木とする。四周に高欄付の縁を巡らす。正面の１間通を吹放ち，入側に格子戸，側面を板戸とする。正面の妻飾りや向拝意匠など，正面を重視した外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005833"},{"id":"00013105","register_sub_id":"101","register_pk":"368263","name":"光林寺経蔵","kana":"こうりんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原2329","lat":36.60151389,"lng":138.12661389,"geo_status":"db","era":"慶応元年（1865）／昭和40年改修","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"土蔵造平屋建、金属板葺、建築面積52㎡、八角輪蔵付","structure_material":"土蔵造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0550","desc":"境内南寄りの石積基壇上に北面して建つ宝形造鉄板葺の経蔵。土蔵造、外壁漆喰塗で軒先まで板軒状に塗込め、正面入口と側面の窓に花頭枠をつくる。内部は一室で、彫刻や塗装により装飾された八角輪蔵を納める。比較的規模が大きく、境内景観を特徴づける経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013105"},{"id":"00013107","register_sub_id":"101","register_pk":"368265","name":"光林寺山門","kana":"こうりんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原2329","lat":36.60183889,"lng":138.12693056,"geo_status":"db","era":"文政9年（1826）","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造、瓦葺、間口3.4m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0552","desc":"境内東辺中ほどの入口に東面して構える門。一間薬医門、切妻造桟瓦葺で、側背面の各柱間に虹梁を架けて華やかな絵様を施し、正面の冠木上に絡み合う四頭の龍彫刻を彫るなど、堅牢な軸部を構成するとともに、随所を飾る華やかな彫刻や絵様にも見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013107"},{"id":"00013106","register_sub_id":"101","register_pk":"368264","name":"光林寺鐘楼","kana":"こうりんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原2329","lat":36.60199167,"lng":138.12696667,"geo_status":"db","era":"天保元年（1830）","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、瓦葺、面積8.9㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"20 － 0551","desc":"境内北東隅の石垣上に築いた石積基壇に建つ吹放し形式の鐘楼。入母屋造桟瓦葺で、禅宗様を基調とし、組物は出組詰組である。虹梁形内法貫と頭貫の間に龍彫刻、台輪上の組物間の松と鷹の彫刻など、随所を力強い彫刻で飾る。高台の境内のシンボルとなる鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013106"},{"id":"00015446","register_sub_id":"101","register_pk":"533461","name":"光林寺本堂","kana":"こうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井小松原字境内2329","lat":36.60191389,"lng":138.12654722,"geo_status":"db","era":"寛政12年（1800）／昭和53年改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0669","desc":"川中島を見下ろす高台にある浄土宗寺院の本堂。東面して建つ寄棟造茅葺形銅板葺屋根で向拝付き。側柱は角柱、入側柱は円柱で虹梁で繋ぎ、格天井を張る。内外ともに多彩な彫刻で装飾し、向拝の鳳凰彫刻や内部虹梁上の笈形付大瓶束は特に大振りで目を惹く本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015446"},{"id":"00016662","register_sub_id":"101","register_pk":"579146","name":"駒形嶽駒弓神社本殿","kana":"こまがたたけこまゆみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市大字上松字駒形東平1997","lat":36.673531,"lng":138.189704,"geo_status":"db","era":"文久3年（1863）頃／昭和42年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積46㎡、神殿付","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0686","desc":"善光寺北方の境内に南面する。間口三間奥行四間の前半を南北棟の入母屋造、向拝一間軒唐破風付、後半を東西棟の入母屋造とする撞木造。茅葺（鉄板仮葺）。内部は内外陣に二分し、内陣奥に一間社流造の神殿を配す。屋根形式や神殿を祀る点に地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016662"},{"id":"00014362","register_sub_id":"101","register_pk":"511351","name":"下今井諏訪神社神楽殿","kana":"しもいまいすわじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.15876111,"lng":137.91015,"geo_status":"db","era":"万延元年(1860)／明治16年改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0607","desc":"下今井の氏神の神楽殿で、鳥居と拝殿の中間に位置する。入母屋造桟瓦葺、軒は出桁で支え元茅葺。正面に龍の鏝絵欄間と虹梁を掲げ、四方吹放ち、腕木で高欄付縁を廻らす。床下に残る炉は祭事用で、水管理の会合も行ったと伝わり、境内の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014362"},{"id":"00014359","register_sub_id":"101","register_pk":"511348","name":"下今井諏訪神社諏訪社","kana":"しもいまいすわじんじゃすわしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.1589,"lng":137.90975833,"geo_status":"db","era":"寛延3年(1750)／昭和13年改修","year":1750,"year_source":"db","year_min":1750,"year_max":1750,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.0㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0604","desc":"下今井の水田と社叢に囲まれた氏神の本殿。一間社流造で元こけら葺、二軒繁垂木、身舎円柱、向拝角柱で浜縁付。内部は内外陣に分ける。緩い曲りの海老虹梁や絵様等時代相を示し、水引虹梁上の、波に兎の透かし彫り欄間と諏訪の神紋入蟇股は洗練された意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014359"},{"id":"00014360","register_sub_id":"101","register_pk":"511349","name":"下今井諏訪神社八幡社","kana":"しもいまいすわじんじゃはちまんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.15892222,"lng":137.90976111,"geo_status":"db","era":"寛政2年(1790)／大正4年移築・昭和13年改修","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0605","desc":"下今井氏神の諏訪社の北側に並ぶ相殿で、南耕地集落から移築したもの。一間社流造、二軒繁垂木、身舎円柱、向拝角柱で浜縁付。内部は内外陣に分ける。強い曲りの海老虹梁や装飾性の増した絵様等、諏訪社と異なる時代相を示す。向拝欄間に鳳凰の丸彫りを付す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014360"},{"id":"00014361","register_sub_id":"101","register_pk":"511350","name":"下今井諏訪神社八坂社","kana":"しもいまいすわじんじゃやさかしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井字原田2971-2","lat":36.15884444,"lng":137.90973333,"geo_status":"db","era":"嘉永4年(1851)／大正4年移築・昭和13年改修","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0606","desc":"下今井氏神の諏訪社の南に並ぶ相殿で、北耕地集落から移築したもの。一間社流造、二軒繁垂木、身舎円柱、向拝角柱で浜縁付。内部は外陣を広くとる。向拝欄間に立体的な丸彫りの龍を配し、身舎頭貫等の横に潰れた渦の絵様は諏訪社・八幡社とは異なる時代相。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014361"},{"id":"00005811","register_sub_id":"101","register_pk":"106798","name":"常徳院門","kana":"じょうとくいんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市元善町615","lat":36.659523,"lng":138.186508,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0268","desc":"敷地の東辺中央，街路に面して開く薬医門形式の表門である。間口は８尺で，４尺控えて控柱が立つ。屋根は切妻造，桟瓦葺である。男梁の正面側を木鼻に造り，出桁上の組物と実肘木で桁を受けている。門扉は両開の板戸で，左手の脇塀に潜戸を設けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005811"},{"id":"00010778","register_sub_id":"101","register_pk":"201613","name":"證蓮寺山門","kana":"しょうれんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字寺町1299","lat":36.560879,"lng":138.202658,"geo_status":"db","era":"江戸中期／明治19頃移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0490","desc":"境内の西辺中央に構える。間口二・一メートルの四脚門形式、切妻造桟瓦葺で、棟両端に鯱を飾る。軸部を黒色塗とし、桟唐戸を吊る。彫刻等の装飾を抑えた端正な外観ながら、規模や構造は市内の歴代藩主霊屋の表門と類似し、風格のある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010778"},{"id":"00010776","register_sub_id":"101","register_pk":"201611","name":"證蓮寺聖徳太子堂","kana":"しょうれんじしょうとくたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県長野市松代町松代字寺町1300他","lat":36.56075,"lng":138.202815,"geo_status":"db","era":"大正元","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0488","desc":"境内南側に北面して建つ、切妻造妻入、桟瓦葺。正面に向拝状の下屋を付し、妻壁に唐草など、堂内の組物間に雲龍や瑞獣などの鏝絵を施し、巧緻な左官技術を見せると共に、内外を華やかに飾立てる。大火後に市民の浄財により再建された堂で、往時の隆盛を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010776"},{"id":"00010777","register_sub_id":"101","register_pk":"201612","name":"證蓮寺鐘楼","kana":"しょうれんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市松代町松代字寺町1299他","lat":36.5608,"lng":138.202722,"geo_status":"db","era":"大正元頃","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、面積8.2㎡","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0489","desc":"境内南西隅に位置し、高い亀甲積基壇上に建つ方一間吹放ち形式の鐘楼。南北棟の入母屋造で桟瓦を葺き、軒は二軒繁垂木である。面取角柱を四方転びに立て、柱上に三斗、中備に蟇股を配する。通りからも望見され、松代城下の景観に寄与する鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010777"},{"id":"00010775","register_sub_id":"101","register_pk":"201610","name":"證蓮寺本堂","kana":"しょうれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市松代町松代字寺町1299他","lat":36.560942,"lng":138.203036,"geo_status":"db","era":"明治20","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積221㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"20 ‐ 0487","desc":"松代城下南東部の寺町に境内を構える。桁行一四メートルの堂で、正面に一間向拝を付す。平面は標準的な真宗寺院本堂形式で、外陣中央間と矢来内の間に絵様虹梁を架けて結界を表す。棟の短い寄棟造屋根を持ち、松代における寺院本堂の特徴的な外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010775"},{"id":"00015008","register_sub_id":"101","register_pk":"529286","name":"白髯神社拝殿","kana":"しらひげじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市鬼無里日影字祖山4957","lat":36.67226111,"lng":137.99149444,"geo_status":"db","era":"明治11年／大正12年・平成29年改修","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0647","desc":"長野市西方の山間、重文の本殿の東に建つ拝殿。入母屋造平入鉄板葺で正面に軒唐破風付向拝を配し千鳥破風を飾る。柱に直接桁を載せ、軒は二軒繁垂木。三方に擬宝珠高欄付縁を廻らし脇障子を建てる。内部は一室の板敷で竿縁天井。破風を重ね外観華やかな拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015008"},{"id":"00015447","register_sub_id":"101","register_pk":"533462","name":"善敬寺本堂","kana":"ぜんきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市吉田三丁目968","lat":36.66848611,"lng":138.21991389,"geo_status":"db","era":"元文元年（1736）／明治37年・昭和57年改修","year":1736,"year_source":"db","year_min":1736,"year_max":1736,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積621㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"20 - 0670","desc":"北国街道沿いに位置する浄土真宗寺院の本堂。境内東寄りに西面して建つ入母屋造銅板葺で正面に三間向拝を付す。内部は内外陣、左右両余間とし、内外陣廻りに円柱を多用し外陣正側面に広縁と落縁を付す。外陣中央間の鏡天井に描く龍が目を惹く規模雄大な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015447"},{"id":"00016380","register_sub_id":"101","register_pk":"536447","name":"善光寺雲上殿本殿","kana":"ぜんこうじうんじょうでんほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県長野市箱清水三丁目1775","lat":36.67043056,"lng":138.18866111,"geo_status":"db","era":"昭和24年／昭和63年頃・平成24年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"鉄骨鉄筋コンクリート造及び鉄筋コンクリート造地上3階地下1階建、鉄板葺、建築面積733㎡","structure_material":"鉄骨鉄筋コンクリート造及び鉄筋コンクリート造地上3階地下1階建","registered":"2025.11.17(令和7.11.17)","register_no":"20 - 0674","desc":"善光寺の中軸線の北方、大峰山南麓に位置する納骨堂。設計は沖津清。中央に鉄骨鉄筋コンクリート造鉄板葺の多宝塔を配し、東西に鉄筋コンクリート造二階建の翼堂を延ばした独創的な形式。コンクリートで寺院建築の細部意匠まで巧みに表現した大規模納骨堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016380"},{"id":"00013394","register_sub_id":"101","register_pk":"368479","name":"善光寺鐘楼","kana":"ぜんこうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市大字長野字元善町491イ","lat":36.66122222,"lng":138.18815833,"geo_status":"db","era":"嘉永6年（1853）／大正15年改修","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造、檜皮葺、面積33㎡","structure_material":"木造","registered":"2020.08.17(令和2.08.17)","register_no":"20 － 0563","desc":"本堂の南東に位置し、切石積基壇上に建つ吹放し形式で、入母屋造檜皮葺の鐘楼。南無阿弥陀仏に因み六本の柱を立て、頭貫の木鼻は獅子の彫刻で飾る。軒は二軒扇垂木で、中央の柱間に鐘釣梁を渡し梵鐘を吊る。雄大な本堂の近傍にあって、境内の一角を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013394"},{"id":"00013395","register_sub_id":"101","register_pk":"368480","name":"善光寺仁王門","kana":"ぜんこうじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県長野市大字長野字元善町469","lat":36.65848333,"lng":138.18754167,"geo_status":"db","era":"大正7年／昭和52年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"20 － 0564","desc":"本堂正面に伸びる参道上、門前町の中に南面して建つ。三間一戸八脚門、切妻造銅板葺で、正背面に軒唐破風を付す。柱上木鼻の正面を獅子、側面を獏、妻飾を龍の彫刻で飾る。正面側の両脇間に一対の仁王像を安置する。古刹の境内入口を引き締める重厚な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013395"},{"id":"00014816","register_sub_id":"101","register_pk":"519074","name":"前山寺庫裏","kana":"ぜんさんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.34115278,"lng":138.19783611,"geo_status":"db","era":"文政13年(1830)／平成13年改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積256㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0638","desc":"本堂東側に玄関を介して南面して建つ、切妻造平入桟瓦葺の庫裏である。建ちの高い妻面には三段に重ねた梁と束、貫を現す。内部は西寄りに出入口を設け、東の土間では縦横に組んだ太い梁組を見せる。本堂、三重塔などとともに、境内の歴史的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014816"},{"id":"00014817","register_sub_id":"101","register_pk":"519075","name":"前山寺玄関","kana":"ぜんさんじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.34107222,"lng":138.19769167,"geo_status":"db","era":"江戸末期／平成13年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0639","desc":"本堂と庫裏の間に位置する東西棟で、屋根を桟瓦葺とする。南に入母屋造の式台を張出し、内部は北に東西二室を並べ、西室に座敷飾を構える。式台は前面に虹梁形頭貫を渡し、奥に舞良戸を建て、妻飾の大瓶束に大振りな笈形を付すなど豊かな装飾と格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014817"},{"id":"00014818","register_sub_id":"101","register_pk":"519076","name":"前山寺山門","kana":"ぜんさんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.34118056,"lng":138.19728889,"geo_status":"db","era":"江戸後期／昭和8年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、間口2.7m、左右袖塀付","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0640","desc":"本堂西側の石段上部、三重塔の正面に北面して建つ一間一戸の薬医門で、屋根は切妻造茅葺である。軸部太く、本柱、控柱上部を桁で固め、桁上に梁を四筋架けて持ち出し、先端で軒桁を支持する。木太く、質実なつくりの山門で、古刹の境内の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014818"},{"id":"00014815","register_sub_id":"101","register_pk":"519073","name":"前山寺本堂","kana":"ぜんさんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県上田市大字前山字上神戸300","lat":36.341175,"lng":138.197475,"geo_status":"db","era":"江戸中期／江戸後期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積267㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"20 - 0637","desc":"独鈷山北麓に位置する真言宗寺院の本堂。境内下段中央に南面して建つ寄棟造茅葺。正面に付す唐破風造向拝は頭貫と虹梁の間を雲竜彫刻で飾る。内部は六間取方丈形式を基本とし、北列東端を座敷二室に分け、南に広縁を通す。大型茅葺本堂が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014815"},{"id":"00005156","register_sub_id":"101","register_pk":"106146","name":"象山神社絵馬殿","kana":"ぞうざんじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.55957724,"lng":138.1960378,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0224","desc":"境内中央西寄りにある。東面した入母屋造，銅板葺で，低い基壇上に建ち，角柱を立てて舟肘木を受ける。出桁を用いて深い軒をつくる。側廻りは腰と小壁を板張とし，他を開放とする。屋根の妻に木連格子を用いる。休憩所を兼ねた，簡素なつくりの絵馬殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005156"},{"id":"00005157","register_sub_id":"101","register_pk":"106147","name":"象山神社斉館","kana":"ぞうざんじんじゃさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.55959786,"lng":138.19672811,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0225","desc":"境内南，社務所の北東にある。入母屋造，桟瓦葺で，正面に唐破風造の玄関，南に入母屋造，北に切妻造の突出部を各々設ける。真壁造，角柱に舟肘木という和風の外観であるが，たちの高いつくりや縦長窓に加え，内部を洋室とするなど，和洋を組み合わせた建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005157"},{"id":"00005158","register_sub_id":"101","register_pk":"106148","name":"象山神社社務所","kana":"ぞうざんじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.559391,"lng":138.196533,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積229㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0226","desc":"境内南に西面して建つ。入母屋造，銅板葺の南北に細長い建物で，北寄りに切妻造玄関を設ける。南半は西と東に座敷や式台玄関を突出し，複雑な屋根を巧みに処理している。真壁造で，角柱に舟肘木をあげた端正な外観で，床・棚付の座敷等は上質なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005158"},{"id":"00005154","register_sub_id":"101","register_pk":"106144","name":"象山神社拝殿・祝詞殿","kana":"ぞうざんじんじゃはいでん・のりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.55998276,"lng":138.19622086,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積132㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0222","desc":"拝殿は南面して建つ向拝付の入母屋造で，両側面後ろ寄りに切妻造の神饌所を設け，後方には切妻造の祝詞殿（幣殿）を突出する。拝殿は正側面とも蔀戸を用い，住宅風である。装飾細部を抑えた簡明な意匠で，複雑で変化に富んだ構成を纏めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005154"},{"id":"00005155","register_sub_id":"101","register_pk":"106145","name":"象山神社宝殿","kana":"ぞうざんじんじゃほうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.559765,"lng":138.196045,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0223","desc":"境内中央西寄りにある。東面した切妻造，銅板葺で，切石積基壇上に建ち，角柱を立てて舟肘木を受ける。外壁は腰までを板張，上部を漆喰壁とし，両側面に縦連子窓を設ける。小規模であるが，通風口や縁・階段の形式等に工夫を凝らしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005155"},{"id":"00005153","register_sub_id":"101","register_pk":"106143","name":"象山神社本殿","kana":"ぞうざんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県長野市松代町松代1502","lat":36.56012866,"lng":138.19619562,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0221","desc":"３間社流造，二軒繁垂木，銅板葺である。軸部は身舎が円柱，庇が角柱，組物は実肘木付の三斗組，身舎と庇を水平の繋虹梁で結び，妻飾は虹梁上に蟇股を乗せる。四周に縁を廻し，脇障子はなく，伝統様式に則った本殿建築で，装飾の少ない古風な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005153"},{"id":"00010285","register_sub_id":"101","register_pk":"199058","name":"玉依比賣命神社拝殿","kana":"たまよりひめのみことじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565453,"lng":138.215707,"geo_status":"db","era":"嘉永7年（1854）","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0462","desc":"手前に入母屋造妻入の板の間を置いて向拝を付け、一段高い後方に、間口が広く中央を上段の祝詞所とする入母屋造平入の主体部を建て、さらに中央奥に最上段の二畳を張出す。変化に富んだ平面をもち、巧みに演出された内部空間と複雑な屋根形状をもつ拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010285"},{"id":"00010284","register_sub_id":"101","register_pk":"199057","name":"玉依比賣命神社本殿","kana":"たまよりひめのみことじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565498,"lng":138.21561,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0461","desc":"天王山南麓に東面して建つ三間社流造の本殿で、正面に縁と木階を設ける。身舎柱上に舟肘木を置き、庇柱上の出三斗で海老虹梁尻を受ける。身舎正面は三間とも板唐戸を吊るが、内部は一室で、奥の半間に祭壇を構える。全体に装飾を抑えた、端正な意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010284"},{"id":"00010287","register_sub_id":"101","register_pk":"199060","name":"玉依比賣命神社宗形社拝殿及び本殿覆屋","kana":"たまよりひめのみことじんじゃむなかたしゃはいでんおよびほんでんおおいや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565312,"lng":138.216314,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積13㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0464","desc":"境内東方に南面して建つ。桁行三間梁間二間、寄棟造茅葺（鉄板仮葺）、妻入で、側背面を竪板張、正面は開放とする。床板張の内部は前後二室に分け、上段の後室に本殿を鎮座し、拝殿となる前室との境に格子をたてる。近世の境内の様相を良好に伝える境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010287"},{"id":"00010286","register_sub_id":"101","register_pk":"199059","name":"玉依比賣命神社宗形社本殿","kana":"たまよりひめのみことじんじゃむなかたしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東条字内田443","lat":36.565425,"lng":138.215775,"geo_status":"db","era":"元禄6年（1693）","year":1693,"year_source":"db","year_min":1693,"year_max":1693,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積0.5㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"20-0463","desc":"境内東方の覆屋内に南面して建つ。小規模な一間社流造で、三方に縁を廻らして脇障子をたて、正面に木階と浜床を付け、こけら葺とする。柱は全て角柱で、身舎の組物は三斗、庇は連三斗とし、中備蟇股、妻飾は虹梁大瓶束である。小社ながら本格的な構えの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010286"},{"id":"00009949","register_sub_id":"101","register_pk":"196096","name":"長明寺経蔵","kana":"ちょうめいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県長野市松代町東寺尾字屋敷3881-2他","lat":36.57030647,"lng":138.20560434,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積30㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0443","desc":"境内北方に南面して建つ。五・五メートル四方の土蔵造で、出入口と東西面の窓を花頭窓とする。出入口上方には唐草の鏝絵を飾る。内部は煉瓦敷の土間で、六角輪蔵を納める。輪蔵は垂下柱に出組を載せる装飾的なものとする。境内景観を引き締める経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009949"},{"id":"00009950","register_sub_id":"101","register_pk":"196097","name":"長明寺三門","kana":"ちょうめいじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東寺尾字屋敷3881-2他","lat":36.57011,"lng":138.2054594,"geo_status":"db","era":"寛政8","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造2階建、瓦葺、建築面積33㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0444","desc":"桁行三間の楼門で、下層全体を吹放しとする。上層は尾垂木付の三手先を詰組とし、内部の須弥壇に文殊菩薩などを祀る。素木造で、組物や垂木の木口に胡粉を塗る。当地の同時期の寺社建築には珍しく、彫刻を抑え、正統的な様式による力強い造形になる門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009950"},{"id":"00009948","register_sub_id":"101","register_pk":"196095","name":"長明寺本堂","kana":"ちょうめいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町東寺尾字屋敷3881-2他","lat":36.5701459,"lng":138.20585682,"geo_status":"db","era":"明和4／明治後期改修","year":1767,"year_source":"db","year_min":1767,"year_max":1767,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0442","desc":"境内中央に西面して建つ。内陣と両脇間を上段として前面を外陣、さらに正面一間通りを広縁とする。浄土宗寺院本堂の特徴的な平面を示し、内陣廻りは組物や彫刻欄間で荘厳する。虹梁絵様や蟇股の意匠も優秀で、江戸後期の当地域を代表する浄土宗寺院本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009948"},{"id":"00014366","register_sub_id":"101","register_pk":"511355","name":"續麻・今井（兼平）神社神楽殿","kana":"つうそ・いまい（かねひら）じんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14133333,"lng":137.90234167,"geo_status":"db","era":"嘉永6年(1853)／昭和22年移築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0611","desc":"續麻社・兼平社の正面の鳥居内側に建つ神楽殿。切妻造平入桟瓦葺で、元は茅葺。正面中央柱間と、背面間口一杯に差鴨居を入れ、北側面西間を開放、他は貫で固める。内部は一室の板敷で天井を張らず小屋を現す。本殿前の歴史的景観を構成し、祭礼空間となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014366"},{"id":"00014364","register_sub_id":"101","register_pk":"511353","name":"續麻・今井（兼平）神社兼平社","kana":"つうそ・いまい（かねひら）じんじゃかねひらしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14154722,"lng":137.9019,"geo_status":"db","era":"天保4年(1833)／昭和35年改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.4㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0609","desc":"上今井の氏神を祀る本殿。續麻社の南に並ぶ。一間社流造銅板葺、正面に唐破風、千鳥破風を重ねる。内部は内外陣に分け、脇障子と腰組付の縁を三面に廻す。向拝柱筋と菖蒲桁筋に各々精緻な彫刻を施した手挟みを付し、虹梁欄間の龍彫刻等全体を華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014364"},{"id":"00014365","register_sub_id":"101","register_pk":"511354","name":"續麻・今井（兼平）神社神明社","kana":"つうそ・いまい（かねひら）じんじゃしんめいしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14146944,"lng":137.90183611,"geo_status":"db","era":"安永9年(1780)／天保12年（1841）改修・大正4年・昭和22年移築","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0610","desc":"上今井の氏神を祀る神社に合祀した神明社で、兼平社の南に建つ。一間社見世棚造、切妻造平入銅板葺、柱は床下を八角とした円柱で、梁、桁を架けて束で棟木を支え板軒とする。正面格子戸で、内部は内外陣に分けて宮殿を安置する。素木造で簡明な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014365"},{"id":"00014363","register_sub_id":"101","register_pk":"511352","name":"續麻・今井（兼平）神社續麻社","kana":"つうそ・いまい（かねひら）じんじゃつうそしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市大字今井1077","lat":36.14159444,"lng":137.90192222,"geo_status":"db","era":"安政6年(1859)／昭和10年改修・同22年移築","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.1㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"20 - 0608","desc":"上今井の氏神を祀る本殿。兼平社の北に並ぶ。一間社流造銅板葺、二軒繁垂木、三面切目縁で脇障子付、階、浜縁を付す。曲りの強い海老虹梁で向拝を付し、正面建具は青海波の格子戸を建て、内部は内外陣に分ける。向拝水引虹梁や手挟等を彫刻で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014363"},{"id":"00012527","register_sub_id":"101","register_pk":"367822","name":"典厩寺閻魔堂","kana":"てんきゅうじえんまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井杵淵字中村999","lat":36.57666,"lng":138.18428,"geo_status":"geocoded","era":"万延元年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0530","desc":"川中島古戦場の南方にある曹洞宗寺院の仏堂で、境内東南隅に北面して建つ。正面・側面とも6･2メートルの宝形造桟瓦葺で、裳階を廻し、内部には巨大な閻魔像を安置する。舟肘木の組物や登梁風の大疎垂木など独特な形態で、地域の歴史と信仰の様相を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012527"},{"id":"00012528","register_sub_id":"101","register_pk":null,"name":"典厩寺山門","kana":"てんきゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市篠ノ井杵淵字中村999、1000-イ","lat":36.57666,"lng":138.18428,"geo_status":"geocoded","era":"江戸中期／明治19年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"20 － 0531","desc":"3代松代藩主・真田幸道霊屋の表門を移築したもので、境内東面南寄りに建つ。切妻造桟瓦葺の四脚門で、軸部は五平の本柱と冠木を組んで梁をかけ、梁上の大きな蟇股で棟木を受ける。簡明ながら良材を多用した丁寧なつくりで、門前景観を格式高く演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012528"},{"id":"00010139","register_sub_id":"101","register_pk":"197972","name":"徳運寺庫裏","kana":"とくうんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字入山辺字院地4527-1","lat":36.221275,"lng":138.045188,"geo_status":"db","era":"安政3／平成5改修","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積428㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0449","desc":"本堂の東側に式台を介して南北棟で建つ。当地方に特徴的な本棟造民家に類した形式を持ち、桁行一二間、梁間八間と大規模になる。南寄りを土間の玄関とし、床上部は、奥三室の座敷の前面に、オエ等各室を配する。当地域における江戸末期の大型禅院庫裏の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010139"},{"id":"00010140","register_sub_id":"101","register_pk":"197973","name":"徳運寺山門及び高塀","kana":"とくうんじさんもんおよびたかべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大字入山辺字院地4526","lat":36.221064,"lng":138.044826,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"山門 木造、瓦葺、間口4.2m 高塀 木造、瓦葺、総延長8.2m","structure_material":"山門 木造","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0450","desc":"境内の南正面を画す門と塀。山門は薬医門形式で、梁の持送りや妻飾の笈形に彫りの深い彫刻を施す。山門の左右には高塀が取付き、右方三・六メートル、左方四・六メートルを測る。高塀は真壁とし、壁面を漆喰で仕上げる。凛とした佇まいで、境内正面を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010140"},{"id":"00010138","register_sub_id":"101","register_pk":"197971","name":"徳運寺本堂","kana":"とくうんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市大字入山辺字院地4526","lat":36.221406,"lng":138.044819,"geo_status":"db","era":"嘉永6／昭和50改修","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積392㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"20 － 0448","desc":"寄棟造銅板葺の方丈型本堂で、南面して建つ。平面は八間取の前面に二間幅の広縁を通す、大型の堂である。南西隅に鎮守堂を張出し、金比羅大権現等を祀る。全体に装飾は抑えめで、側廻りは柱上に台輪を廻らして三斗を置く。起りのある大屋根が風格を醸す本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010138"},{"id":"00005771","register_sub_id":"101","register_pk":"106759","name":"長野聖救主教会","kana":"ながのせいきゅうしゅきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県長野市大字西長野6","lat":36.656319,"lng":138.182053,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積138㎡","structure_material":"煉瓦造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"20 － 0264","desc":"煉瓦造平屋建で北面して建つ。奥行１４．５ｍの単廊式会堂に祭壇を突出する。屋根は切妻造，鉄板葺である。正面は尖頭アーチの入口上部にバラ窓を飾り，両脇に尖頭アーチの窓を開く，側壁と隅部にはバットレスをつける。西洋中世風の小会堂の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005771"},{"id":"00014485","register_sub_id":"101","register_pk":"513899","name":"日本聖公会中部教区稲荷山諸聖徒教会","kana":"にっぽんせいこうかいちゅうぶきょうくいなりやましょせいときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県千曲市大字稲荷山字伊勢宮198-2他","lat":36.53153889,"lng":138.10249167,"geo_status":"db","era":"昭和8年／同62年改修、平成15年増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積167㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"20 - 0630","desc":"稲荷山宿近くの善光寺街道沿いにある教会。基壇に建つ鉄筋コンクリート造切妻造で、両側面にバットレス風柱形を付し、外壁モルタル仕上。単廊式で軸線上に会衆席・至聖所・聖所を並べ、地下に納骨堂を配す。地方の近代鉄筋コンクリート造教会として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014485"},{"id":"00011958","register_sub_id":"101","register_pk":"211102","name":"日本聖公会中部教区飯山復活教会","kana":"にほんせいこうかいちゅうぶきょうくいいやまふっかつきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県飯山市大字飯山2278-イ-1","lat":36.854274,"lng":138.36443,"geo_status":"db","era":"昭和7年／平成16年増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"20-517","desc":"切妻造、妻入で棟上に鐘塔を戴き、外壁は下見板張に尖頭アーチ窓を並べる。玄関ポーチの入口を尖頭アーチ形の洗出し仕上げとし、下見板を扇状に張る。単廊式で会衆席と前室、祭壇等を配し、会衆席と前室は当初から畳敷であった。昭和初期の瀟洒な木造教会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011958"},{"id":"00012735","register_sub_id":"101","register_pk":"367638","name":"日本聖公会中部教区岡谷聖バルナバ教会","kana":"にほんせいこうかいちゅうぶきょうくおかやせいばるなばきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長野県","address":"長野県岡谷市本町四丁目4840-2他","lat":36.06472889,"lng":138.04668583,"geo_status":"db","era":"昭和3年／昭和39年増築・平成25年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋一部2階建、金属板葺、建築面積121㎡","structure_material":"木造平屋一部2階建","registered":"2019.03.29(平成31.03.29)","register_no":"20 － 539","desc":"市中心部にある単廊式の木造教会。切妻造妻入、南正面の中央に切妻屋根の玄関ポーチ、左右に招屋根風の張出しを設けた連山のような印象的な立面で、玄関ポーチ妻の社寺風の装飾や会衆席の畳敷など和風の要素を取り入れる。地域に根ざした独特な姿の教会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012735"},{"id":"00013730","register_sub_id":"101","register_pk":"505267","name":"日本聖公会松本聖十字教会","kana":"にほんせいこうかいまつもとせいじゅうじきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県松本市開智一丁目200-1","lat":36.24033889,"lng":137.96548889,"geo_status":"db","era":"明治43年／昭和32年移築改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"20 － 569","desc":"松本城北西に南面して建つ木造教会。急勾配の切妻屋根に赤色瓦を葺き、南東側に鐘塔を建てる。三廊式で小屋はシザーストラスを組む。身廊側面や窓に尖頭アーチを用いるなどゴシックを基調とする一方、祭壇の小屋に絵様付木鼻を付すなど独自の意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013730"},{"id":"00009947","register_sub_id":"101","register_pk":"196094","name":"梅翁院山門","kana":"ばいおういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字田町984-2他","lat":36.56640521,"lng":138.20370225,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.7m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0441","desc":"本堂南正面に南面して構える。間口二・七メートルの一間薬医門で、東西に袖塀を附属し東側に潜戸を開く。拳鼻付の大瓶束で棟木を受け、軒は二軒繁垂木とする。扉には八双金具と乳金具を打つ。簡明ながら重厚な意匠を持ち、伽藍の正面を飾るに相応しい門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009947"},{"id":"00009946","register_sub_id":"101","register_pk":"196093","name":"梅翁院本堂","kana":"ばいおういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代字田町984-2他","lat":36.56669788,"lng":138.20368856,"geo_status":"db","era":"文久元／昭和28・昭和60頃改修","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"20 － 0440","desc":"松代城下東寄りに構える境内に、南面して建つ。六間取方丈型の平面とし、前土間を持つ。組物は、側廻りでは柱上に舟肘木を置き、内陣は三斗を組む。要所に虹梁を架けて装飾とするほかは簡素な意匠とする。当地における近世の曹洞宗寺院本堂の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009946"},{"id":"00015010","register_sub_id":"101","register_pk":"529288","name":"離山神社拝殿・祝詞殿及び本殿上屋","kana":"はなれやまじんじゃはいでん・のりとでんおよびほんでんうわや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町清野字離山1917","lat":36.56071111,"lng":138.19368333,"geo_status":"db","era":"文化13年（1816）／平成27年改修","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積74㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0649","desc":"境内南辺に建つ入母屋造東西棟の拝殿の北に、両下造南北棟の祝詞殿と切妻造東西棟の本殿覆屋を接続する複合社殿で屋根総桟瓦葺とする。拝殿は正面に向拝を付して、側面は斜面上に縁を張出し、懸造とする特異な形式。丘上の高低差を巧みに利用した雄大な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015010"},{"id":"00015009","register_sub_id":"101","register_pk":"529287","name":"離山神社本殿","kana":"はなれやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町清野字離山1917","lat":36.56077778,"lng":138.19371111,"geo_status":"db","era":"江戸中期／文化13年(1816)改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"20 - 0648","desc":"松代城跡南西の小山に鎮座する本殿。境内北の覆屋内に南面して建つ、一間社流造こけら葺で三方に刎高欄付縁を廻らし、脇障子を建てる。身舎桁下に連三斗を組み軒は二軒繁垂木。妻飾は束を大瓶束とした豕扠首形式。全体に塗装彩色を残し、丁寧なつくりの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015009"},{"id":"00005183","register_sub_id":"101","register_pk":"106173","name":"法蔵寺庫裏","kana":"ほうぞうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30242269,"lng":137.90577938,"geo_status":"db","era":"江戸中期／明治4・40移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積402㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0251","desc":"境内中央の南寄りにある。切妻造，妻入で，北妻面を正面とし，四周に下屋を廻し，玄関に軒唐破風を設ける。軒は出桁造，真壁造であるが，北と西の外壁は軒裏まで漆喰塗とする。規模大で，内外ともよく当初形式を保持しており，この地域における庫裏の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005183"},{"id":"00005184","register_sub_id":"101","register_pk":"106174","name":"法蔵寺書院","kana":"ほうぞうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30230862,"lng":137.9059378,"geo_status":"db","era":"江戸中期／明治4・40移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0252","desc":"庫裏の南東隅にある。南北棟の切妻造で，西面に下屋を設け，屋根は桟瓦葺である。平面は１０畳間の２室に縁を廻した形式で，奥に床・棚・付書院を備える。規模は小さいが，良材を多用した丁寧なつくりで，この地域における書院建築の傾向を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005184"},{"id":"00005182","register_sub_id":"101","register_pk":"106172","name":"法蔵寺鐘楼門","kana":"ほうぞうじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30258344,"lng":137.90544165,"geo_status":"db","era":"寛政5頃","year":1793,"year_source":"db","year_min":1793,"year_max":1793,"year_label":null,"structure":"木造、2階2重、瓦葺、建築面積75㎡","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0250","desc":"境内正面の西入口にある。３間１戸２階２重門で，入母屋造，桟瓦葺屋根を架ける。低い切石積基壇上に建ち，初層は円柱を立て丸桁を受ける。上層は吹放しで，円柱に出組をあげ，格天井を張って中央に銅鐘を吊る。彫刻等の細部から大隅流棟梁の作と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005182"},{"id":"00005185","register_sub_id":"101","register_pk":"106175","name":"法蔵寺土蔵","kana":"ほうぞうじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科5716","lat":36.30223576,"lng":137.90582842,"geo_status":"db","era":"安政元","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0253","desc":"庫裏の南後方にあり，化粧棟木下端の墨書から年代が明確。東西棟の２階建土蔵造で，屋根は置屋根式とし，北面に下屋を設け，桟瓦葺とする。下屋は３方を壁で厳重に囲い，戸口を２カ所を設ける。内壁は化粧板張とするなど，全体に堅牢で丁寧なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005185"},{"id":"00005140","register_sub_id":"101","register_pk":"106130","name":"祝神社拝殿","kana":"ほうりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代567","lat":36.56340328,"lng":138.20322097,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0208","desc":"桁行７間，梁間３間規模，入母屋造，桟瓦葺，妻入。正面向拝は唐破風付きで，彫刻で飾る。内部は２室で，奥間の床を一段高くする。正面１間を吹放し，３方に縁を廻す。鬼瓦には六連銭を表す。本殿と同年代の建立で，一体となって歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005140"},{"id":"00005139","register_sub_id":"101","register_pk":"106129","name":"祝神社本殿","kana":"ほうりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町松代567","lat":36.56342549,"lng":138.20338191,"geo_status":"db","era":"文化9","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0207","desc":"銅板葺の二間社流造の社殿で，縁及び浜床を高くとり，均整のとれた外観を示す。脇障子に唐獅子を表し，向拝中備の龍や木鼻の象など，各所に彫物をあしらい華やかに飾る。松代町方の総鎮守神，産土神として地元で親しまれてきた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005139"},{"id":"00004959","register_sub_id":"101","register_pk":"105949","name":"無量寺庫裏","kana":"むりょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36109889,"lng":137.99742655,"geo_status":"db","era":"文化7～9","year":1811,"year_source":"estimated","year_min":1810,"year_max":1812,"year_label":"文化7～9","structure":"木造平屋一部2階建、茅葺（鉄板仮葺）、建築面積337㎡","structure_material":"木造平屋一部2階建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0195","desc":"本堂の東にあり，玄関付の廊下で接続する。南北に細長い平面で，北半が居室部，南半が土間になり，一部２階を設け，西面中央に出入口をつける。屋根は寄棟造，茅葺（鉄板覆）とする。たちの高い軸部や側廻りの壁面構成など，造形的にも本堂との共通性がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004959"},{"id":"00004963","register_sub_id":"101","register_pk":"105953","name":"無量寺衆寮","kana":"むりょうじしゅりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36121169,"lng":137.99691597,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積94㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0199","desc":"本堂の南西方にある。東西棟の寄棟造，茅葺（鉄板覆），桁行９間半，梁間３間で，中央に幅１間半の通路を設け，左右は部屋とし，一時は住居に用いた。たちの高い軸組，出桁造の軒廻りなどから，本堂などと同時期の建築と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004963"},{"id":"00004960","register_sub_id":"101","register_pk":"105950","name":"無量寺鐘楼堂","kana":"むりょうじしょうろうどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36113938,"lng":137.99710381,"geo_status":"db","era":"文化12","year":1815,"year_source":"db","year_min":1815,"year_max":1815,"year_label":null,"structure":"木造、瓦葺、建築面積7.4㎡","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0196","desc":"本堂の南正面にある方一間袴腰付の鐘楼で，低い切石積基壇上に建つ。屋根は南北棟の切妻造，桟瓦葺，八角形柱をたて吹放ちとし，四周に高欄を廻す。両側は野物風の梁上に棟束をたて，彫刻を施した笈形を付ける。棟札から大工は出雲崎の宮下治郎七と判明する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004960"},{"id":"00004962","register_sub_id":"101","register_pk":"105952","name":"無量寺土蔵","kana":"むりょうじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36095922,"lng":137.99743117,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"土蔵造2階建、瓦葺、建築面積33㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0198","desc":"庫裏南東に隣接して建ち，立地上，南側の基礎は谷積で高く築いている。土蔵造２階建，東西棟の切妻造，桟瓦葺で，北面に戸口を設け，庇をつける。外壁は南・西・北面の腰を海鼠壁とし，垂木まで漆喰塗とするが，開口部は設けない。厳重で堅牢なつくりの土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004962"},{"id":"00004961","register_sub_id":"101","register_pk":"105951","name":"無量寺宝物殿","kana":"むりょうじほうもつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.3613209,"lng":137.99767236,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0197","desc":"庫裏の北方に位置し，棟札から建築年代が明確である。土蔵造２階建，東西棟の切妻造，桟瓦葺で，南面中央に戸口を設け，庇をつける。外壁は漆喰塗で４周の腰を海鼠壁とし，軒廻りは鉢巻を廻す。戸口や窓の開口部には縁取をつける。全体に丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004961"},{"id":"00004958","register_sub_id":"101","register_pk":"105948","name":"無量寺本堂","kana":"むりょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県松本市会田岩井堂3111","lat":36.36130745,"lng":137.99736793,"geo_status":"db","era":"文化7～9","year":1811,"year_source":"estimated","year_min":1810,"year_max":1812,"year_label":"文化7～9","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積322㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"20 － 0194","desc":"曹洞宗寺院の本堂で，南面して建つ。正面側に土間と広縁を設けた八間取平面で，屋根は寄棟造，茅葺（鉄板覆）とする。たちの高い軸組とし，出桁造で深い軒をつくる。外観は装飾が少なく簡素であるが，内陣廻りには江戸後期らしい多彩な彫物を用いている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004958"},{"id":"00014156","register_sub_id":"101","register_pk":"508786","name":"明徳寺山門","kana":"めいとくじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字菖蒲沢2833","lat":36.54278889,"lng":138.23165,"geo_status":"db","era":"正徳3年(1713)頃／昭和38年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2022.02.17(令和4.02.17)","register_no":"20-0601","desc":"本堂の正面に建つ３間１戸楼門の鐘楼門。礎石上に丸柱を立て、貫、虹梁等で固め、挿肘木と木鼻付頭貫を延ばし２階の縁葛を受ける。二階は中央間に開口を開け、両脇に花頭窓を付す。屋根は入母屋造桟瓦葺だが旧は茅葺で、参道石段上の雄大な景観を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014156"},{"id":"00014155","register_sub_id":"101","register_pk":"508785","name":"明徳寺本堂","kana":"めいとくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市松代町豊栄字菖蒲沢2833","lat":36.54278333,"lng":138.23200278,"geo_status":"db","era":"正徳3年(1713)頃／宝暦3年(1753)・明治中期・昭和38年・同50年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積276㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"20-0600","desc":"松代南東の旧関屋村に位置。桁行９間梁間７間、寄棟造鉄板葺で箱棟を高く掲げ、西面する。内部は六室構成に加えて南列に座敷を設け、前面土間を室に改修する。中央奥の内陣回りに丸柱を立て須弥壇を据える。曹洞宗の典型的平面を持つ江戸中期に遡る本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014155"},{"id":"00016667","register_sub_id":"101","register_pk":"579151","name":"湯福神社拝殿及び祝詞殿","kana":"ゆぶくじんじゃはいでんおよびのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"長野県","address":"長野県長野市箱清水三丁目1-2","lat":36.66315,"lng":138.184919,"geo_status":"db","era":"文政12年（1829）／明治12年、大正11年増築、昭和37年改修","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積126㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0691","desc":"本殿前面に南面する。桁行三間梁間五間、入母屋造茅葺形銅板葺、向拝一間、軒唐破風付。内部は横長平面で格天井の拝殿の後方に凸型平面の祝詞座を上段として張出し、西に神饌所を設ける。向拝の虹梁形の頭貫と桁の間を仙人彫刻で埋めるなど見応えあるつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016667"},{"id":"00016666","register_sub_id":"101","register_pk":"579150","name":"湯福神社本殿","kana":"ゆぶくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"長野県","address":"長野県長野市箱清水三丁目1-2","lat":36.663273,"lng":138.184941,"geo_status":"db","era":"文久3年（1863）／明治12年増築","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"20 - 0690","desc":"善光寺北西の境内奥に南面する三間社流造、銅板葺。擬宝珠高欄付縁を廻らし、脇障子を建てる。庇は間口三間分を広い一間として中備に龍彫刻を飾る。妻は二重虹梁大瓶束を出組で持出し、虹梁間に力士を配す。大規模で、幕末らしい華やかな彫刻で飾られた本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016666"},{"id":"00005453","register_sub_id":"101","register_pk":"106441","name":"皆楽座","kana":"かいらくざ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岐阜県","address":"岐阜県各務原市鵜沼羽場町1-217","lat":35.40437998,"lng":136.9213839,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"21 － 0081","desc":"市東部の津島神社境内南寄りに建つ。桁行１５ｍ，梁間１０ｍとした切妻造，桟瓦葺，妻入で，正面以外の三方に下屋を廻す。舞台正面の軒を彫刻持送板で出桁を支えて高くし，本殿に向かって構える。囃子座，楽屋，廻舞台，奈落を完備した本格的なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005453"},{"id":"00007031","register_sub_id":"101","register_pk":"108013","name":"加佐美神社拝殿","kana":"かさみじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県各務原市蘇原古市場町5-1-1","lat":35.42249304,"lng":136.8654821,"geo_status":"db","era":"延享3／文政2・天保2改修","year":1746,"year_source":"db","year_min":1746,"year_max":1746,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0159","desc":"本殿と幣殿の南、一段下がった位置に石積基壇上に建つ。入母屋造桟瓦葺。桁行５間梁間２間、全面板床で、棹縁天井。小壁を板壁とし、周囲の内法貫下は開放とする。両端を根肘木で受ける虹梁を正・背面中央間に一段高く架けるなど、割拝殿の名残を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007031"},{"id":"00007030","register_sub_id":"101","register_pk":"108012","name":"加佐美神社幣殿","kana":"かさみじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県各務原市蘇原古市場町5-1-1","lat":35.42261179,"lng":136.86547496,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0158","desc":"本殿の正面に建つ、桁行１１ｍ梁間５．１ｍの幣殿。切妻造桟瓦葺とし、中央間を切り上げ、棟を高くする。正面は中央間が約１ｍ奥に入り、引違格子戸を建て、両脇間は格子戸嵌殺しとする。中央間のみ柱上に舟肘木。本殿正面の厳粛な礼拝空間を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007030"},{"id":"00007029","register_sub_id":"101","register_pk":"108011","name":"加佐美神社本殿","kana":"かさみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県各務原市蘇原古市場町5-1-1","lat":35.422676,"lng":136.865479,"geo_status":"db","era":"貞享4／江戸後期改修","year":1687,"year_source":"db","year_min":1687,"year_max":1687,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0157","desc":"加佐美山南麓に南面する。規模の大きな３間社流造。屋根檜皮葺。正面に千鳥破風と軒唐破風を付ける。身舎の正・側面に高欄付の切目縁をまわし、正面に木階と浜床を設ける。円柱上に支輪付出組とし、二重虹梁大瓶束の妻を一段持ち出す。見応えのある構造になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007029"},{"id":"00006481","register_sub_id":"101","register_pk":"107464","name":"上の島神明神社社務所","kana":"かみのしましんめいじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.36854428,"lng":136.83911034,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0140","desc":"境内の中央西方に東面して建つ。桁行６間、梁間３間で、入母屋造桟瓦葺とする。南北に３室が並び、北が土間と板敷、中央が式台と８畳、南がトコと違棚を構える座敷とし、座敷には縁がまわる。緩やかな勾配の屋根をもち、丁寧に造られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006481"},{"id":"00006485","register_sub_id":"101","register_pk":"107468","name":"上の島神明神社太鼓橋","kana":"かみのしましんめいじんじゃたいこばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.3685919,"lng":136.83924021,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造桁橋、橋長5.7m、幅員2.7m","structure_material":"石造桁橋","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0142","desc":"境内の中央、拝殿の前方に位置し、池に架かる。石造桁橋で、アーチの高さは１．５ｍで、中央を束で支え、束両脇には唐草文様を彫り出す石版を飾る。橋両端には擬宝珠高欄を付け、架木を蟇股状の石で支える。大きく反り上がり、躍動的な雰囲気を漂わせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006485"},{"id":"00006482","register_sub_id":"101","register_pk":"107465","name":"上の島神明神社手水舎","kana":"かみのしましんめいじんじゃちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.36865766,"lng":136.83916507,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、面積7.0㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0141","desc":"境内の西側、社務所の北に位置する。桁行１間、梁間１間の規模で、切妻造桟瓦葺とする。柱は面取方柱で内転びとし、内法貫と頭貫で固め、柱上に大斗肘木を組む。妻は虹梁上に大瓶束をたて、軒は一軒疎垂木。虹梁や木鼻の絵様などは穏やかな意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006482"},{"id":"00006483","register_sub_id":"101","register_pk":"107466","name":"上の島神明神社鳥居","kana":"かみのしましんめいじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.368103,"lng":136.839233,"geo_status":"db","era":"昭和10／平成7修理","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、高さ8.2m、幅6.0m","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0144","desc":"境内の正面に建ち、木製で表面を銅板で覆う。幅６．０ｍ、高さ８．２ｍと規模が大きい。柱は径７０ｃｍの円柱で、足下には礎石状に石を巻き、柱上に笠木をのせ、貫で固め、貫は柱内で止まる。簡潔な意匠であるが、大規模で風格がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006483"},{"id":"00006484","register_sub_id":"101","register_pk":"107467","name":"上の島神明神社蕃塀","kana":"かみのしましんめいじんじゃばんぺい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.36843233,"lng":136.83923533,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造目隠塀、延長3.8m","structure_material":"石造目隠塀","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0143","desc":"敷地中央、太鼓橋の前方に位置する。石造の蕃塀。基壇上に円柱の主柱を立て、入母屋造屋根を架け、柱間には連子窓をあけ、上部には波に龍、腰壁には虎と唐獅子の彫刻を置く。前後に控えとして擬宝珠柱を設ける。規模が大きく、豊かな彫物を飾るなど特異な蕃塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006484"},{"id":"00006480","register_sub_id":"101","register_pk":"107463","name":"上の島神明神社幣殿","kana":"かみのしましんめいじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.368973,"lng":136.839264,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0139","desc":"幣殿は本殿の前に南北棟として建つ。桁行３間、梁間３間の規模で、入母屋造妻入銅板葺とする。正・背面中央を開口とし、他は格子窓で腰板壁とし、周囲に縁を廻す。方柱で平三斗を組み、軒は二軒繁垂木である。木鼻の彫物以外は装飾を控え、堅実な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006480"},{"id":"00006479","register_sub_id":"101","register_pk":"107462","name":"上の島神明神社本殿","kana":"かみのしましんめいじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市川島松倉町2232-1","lat":35.369034,"lng":136.83926472,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"21 － 0138","desc":"南面する浜縁付一間社流造で、側・背面を２間とし、屋根は銅板葺とする。身舎は円柱で出組、向拝は几帳面取方柱で連三斗を２段に組み、軒は二軒繁垂木。中備や脇障子ほかに瑞龍や植物、雲紋などの彫刻が飾られる。構造と装飾がバランスよくまとめられた遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006479"},{"id":"00000827","register_sub_id":"101","register_pk":"101817","name":"熊野神社目隠門","kana":"くまのじんじゃめかくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県加茂郡八百津町八百津4102-1","lat":35.47591831,"lng":137.1399211,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"石造目隠塀，幅3m，高さ2m","structure_material":"石造目隠塀","registered":"1998.10.09(平成10.10.09)","register_no":"21 － 0017","desc":"拝殿の真正面にあって，これを塞ぐように建つ石造の目隠門。門は左右の親柱に付属する小さな控柱で支え，屋根をかける簡素な形式になる。壁面の上部は波に龍を浮き彫りにし，下部には獅子のレリーフで飾り，中央部は連子をはめる特異な門として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000827"},{"id":"00009606","register_sub_id":"101","register_pk":"194602","name":"酒波神社鐘楼","kana":"さかなみじんじゃしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市日吉町字南垣外4088","lat":35.40744738,"lng":137.24372428,"geo_status":"db","era":"江戸中期／明治42移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、銅板葺、建築面積8.9㎡","structure_material":"木造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0215","desc":"本殿の東方に東西棟で建つ。方一間袴腰付鐘楼で、入母屋造とし、四周に縁を廻す。方柱を腰貫、頭貫と台輪で固め、三斗組とし、中備に平三斗を置く。軒は二軒繁垂木で、妻は豕扠首。廃仏毀釈により梵鐘を失った後は祭器蔵と称し、現在も下層に神輿を納める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009606"},{"id":"00009605","register_sub_id":"101","register_pk":"194601","name":"酒波神社本殿","kana":"さかなみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県瑞浪市日吉町字南垣外4088","lat":35.40734744,"lng":137.24351964,"geo_status":"db","era":"元禄15","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"21 － 0214","desc":"境内北方に建ち、三間社流造銅板葺で、三方に高欄付切目縁を廻し、正面に一間幅の木階を設ける。全体を赤色塗とし蟇股彫刻に彩色を施す。頭貫木鼻に雲紋を陽刻し、妻飾は虹梁を出組で二段持出し、意匠を凝らす。建立年代の判明する神社本殿として市内最古。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009605"},{"id":"00014385","register_sub_id":"101","register_pk":"511374","name":"真龍寺玄関及び茶室","kana":"しんりゅうじげんかんおよびちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.45489722,"lng":136.785475,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0295","desc":"百々ヶ峰南麓の浄土真宗寺院の本堂と庫裏を繋ぐ渡り廊下と、その南側の唐破風玄関、北側の切妻造茶室からなる建物。茶室は四畳半で西面に床構え、床脇に円窓、東に水屋を配す。茶室と廊下境壁の腰を無双窓として来客を知る。寺院の機能的な玄関と接客空間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014385"},{"id":"00014387","register_sub_id":"101","register_pk":"511376","name":"真龍寺山門","kana":"しんりゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.45465,"lng":136.785325,"geo_status":"db","era":"昭和23年","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0297","desc":"浄土真宗寺院の境内南正面に開く山門。切妻造桟瓦葺、二軒繁垂木の薬医門で、袖塀に潜りを設ける。正面蟇股は精緻な龍を彫り、内部に小組格天井を張る。鐘楼棟梁の弟子の作で、地元大工の仕事ぶりを伝え、百々ケ峰を背にして地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014387"},{"id":"00014386","register_sub_id":"101","register_pk":"511375","name":"真龍寺鐘楼","kana":"しんりゅうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.4547,"lng":136.785225,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造、瓦葺、面積6.4㎡","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0296","desc":"百々ヶ峰を背に山門と並ぶ浄土真宗寺院の鐘楼。入母屋造桟瓦葺、二軒、三斗組、格天井を張る。乱石積基壇に、内転びの礎盤付円柱を貫・虹梁・頭貫で固めた方一間吹放ちとする。本堂棟梁の弟子の作で、地元大工の仕事ぶりを伝え、歴史的な伽藍景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014386"},{"id":"00014384","register_sub_id":"101","register_pk":"511373","name":"真龍寺本堂","kana":"しんりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"岐阜県","address":"岐阜県岐阜市長良2509-1","lat":35.45493889,"lng":136.78534722,"geo_status":"db","era":"明治14年頃／大正9年・令和2年改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"21 - 0294","desc":"百々ヶ峰を背に境内を構える浄土真宗寺院の本堂。入母屋造桟瓦葺、向拝を構え正面７間で規模大きく、平面は内外陣間に矢来内、内陣左右に余間を配す等、真宗本堂の典型。長大な虹梁で柱を省略して外陣を大空間とし、小組格天井、金箔押し彫刻欄間で荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014384"},{"id":"00005613","register_sub_id":"101","register_pk":"106601","name":"貞照寺稲荷堂","kana":"ていしょうじいなりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40728966,"lng":136.95891335,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0100","desc":"宝物館西隣にほぼ東面して建つ。東西棟の切妻造，銅板葺，妻入で，軒は一軒とする。平面は縦長で，前を板敷として奥に棚を設け，正面と両側面に切目縁を設ける。真壁造で，角柱を貫，長押で固めて舟肘木を載せ，正面妻飾に蟇股をつける。簡素だがつくりは丁寧。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005613"},{"id":"00005608","register_sub_id":"101","register_pk":"106596","name":"貞照寺庫裏","kana":"ていしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.407597,"lng":136.959656,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積218㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0095","desc":"本堂の北東，池の東に建つ。東西棟の入母屋造で，南面に唐破風造の玄関を突出し，桟瓦葺とする。内部は玄関奥に応接間，この西に１６畳の大広間や８畳の床の間，東に板間と土間を配する。良材を用い，凝った欄間など，つくりも上質で，当時の和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005608"},{"id":"00005609","register_sub_id":"101","register_pk":"106597","name":"貞照寺書院","kana":"ていしょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40771528,"lng":136.95967664,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0096","desc":"南北棟の寄棟造，桟瓦葺で，南は庫裏北側に接続している。平面は北を床・棚付の８畳，南を６畳とし，西に縁を設け，室境の小壁に障子，側廻り小壁にガラス戸を入れて開放的にする。皮付桜材の床柱，棚上の網代天井など，要所に数寄屋風意匠を盛り込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005609"},{"id":"00005614","register_sub_id":"101","register_pk":"106602","name":"貞照寺浄水舎","kana":"ていしょうじじょうすいしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.407162,"lng":136.960098,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、瓦葺、面積5.0㎡","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0101","desc":"門の南東に位置する。横長平面の吹放し形式で，屋根は東西棟の切妻造，桟瓦葺，軒は一軒とする。四隅に内転びの角柱を立てて内法貫で固め，舟肘木を載せて桁を受ける。妻飾は蟇股で絵様肘木を載せて棟木を受ける。小規模であるが，境内構成上，欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005614"},{"id":"00005612","register_sub_id":"101","register_pk":"106600","name":"貞照寺宝物庫","kana":"ていしょうじほうもつこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40706357,"lng":136.95916834,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積125㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0099","desc":"本堂南に北面して建つ。鉄筋コンクリート造，高床式の平屋建で，切妻造屋根を架ける。四周に庇を廻した側廻りは，下部を校倉風とし，上部は角柱を現して縦格子窓，連子窓を設ける。内部１室でガラス天井とする。近代の材料や技術で伝統様式を再構成した事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005612"},{"id":"00005607","register_sub_id":"101","register_pk":"106595","name":"貞照寺本堂","kana":"ていしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.40742958,"lng":136.95915839,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0094","desc":"桁行，梁間とも中央間が広い方５間堂。屋根は入母屋造，正面千鳥破風付，向拝軒唐破風付，瓦棒銅板葺である。軸部から軒廻りまで正統的なつくりで，側面・背面は霊験記の彫物で飾る。鉄筋コンクリート造舞台付の高床上にあり，際だった堂姿を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005607"},{"id":"00005611","register_sub_id":"101","register_pk":"106599","name":"貞照寺門","kana":"ていしょうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"岐阜県","address":"岐阜県各務原市鵜沼宝積寺町5-189","lat":35.407303,"lng":136.959946,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、銅板葺、面積29㎡","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"21 － 0098","desc":"入母屋造，銅板葺，正面と背面に千鳥破風，軒唐破風を付けた八脚門で，仁王像を安置する。軸部は円柱を貫で固め，出組の詰組，軒支輪付で，二軒隅扇垂木とする。内法貫上は精緻な彫物欄間で飾る。調和のとれた外観で，細部も充実し，境内東の正面に相応しい門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005611"},{"id":"00014827","register_sub_id":"101","register_pk":"519085","name":"南宮大社斎館御炊屋","kana":"なんぐうたいしゃさいかんおすいや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.36022222,"lng":136.52676389,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0302","desc":"御炊屋は北棟の北東に渡廊下で接続する切妻造平入桟瓦葺の東西棟。間取りは南に廊下を通し、その北に同規模の部屋を東西に２室並べ、各室南半は板床、北半は土間の台所とし、北面に窓と戸口を開ける。披露宴に欠かせない炊事施設で、斎館北東の構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014827"},{"id":"00014828","register_sub_id":"101","register_pk":"519086","name":"南宮大社斎館回廊","kana":"なんぐうたいしゃさいかんかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.36000278,"lng":136.52642778,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造、瓦葺、建築面積20㎡","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0303","desc":"南庭を囲う回廊は切妻造桟瓦葺の単廊。北棟南面西寄りと南棟西端を連絡する内向きの動線で、南庭の南西に矩折れに廻り、南庭側を吹き放つ。外壁の南面は真壁で漆喰仕上とし、西面は連子窓を開けて、腰と内法に長押を打ち、斎館の格式ある表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014828"},{"id":"00014825","register_sub_id":"101","register_pk":"519083","name":"南宮大社斎館北棟","kana":"なんぐうたいしゃさいかんきたとう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.36015556,"lng":136.52659167,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造2階建、瓦葺、建築面積380㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0300","desc":"境内東端に西面して建つ北棟は、二階建切妻造の東西棟で、正面に片流れの車寄を付す。内部は中廊下を通し、南に大広間、北に控の間を各二室一対で配す。二階西室は西に祭壇を設けた儀式殿の間で格天井を張り、祭壇廻りを錺金具で荘厳した華やかな婚礼施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014825"},{"id":"00014826","register_sub_id":"101","register_pk":"519084","name":"南宮大社斎館南棟","kana":"なんぐうたいしゃさいかんみなみとう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岐阜県","address":"岐阜県不破郡垂井町宮代字峰1734-1","lat":35.35998333,"lng":136.52665,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"21 - 0301","desc":"南棟は平屋建切妻造桟瓦葺の東西棟で北面東寄りを北へ延ばし北棟と接続。内部は中庭沿いに片廊下を廻らし、西から座敷２室、神職の潔斎用風呂、東端を管理人室、北に座敷２室を配す。座敷境の欄間は杉板に梅や竹などを透彫とし、婚礼の華やかさを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014826"},{"id":"00007037","register_sub_id":"101","register_pk":"108019","name":"法誓寺本堂","kana":"ほうせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岐阜県","address":"岐阜県加茂郡八百津町久田見2757","lat":35.520515,"lng":137.189377,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積819㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"21 － 0165","desc":"境内中央に東面して建つ。桁行２６ｍ梁間２５ｍに及ぶ大規模な仏堂。入母屋造桟瓦葺で、正面に３間向拝を付ける。正・側面に広縁と落縁を設け、内部は外陣と矢来内、内陣からなる浄土真宗独特の平面になる。外陣を小組格天井とするなど入念なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007037"},{"id":"00015456","register_sub_id":"101","register_pk":"533471","name":"小梳神社拝殿及び幣殿","kana":"おぐしじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県静岡市葵区紺屋町7-13","lat":34.97355833,"lng":138.38634444,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積147㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"22 - 0342","desc":"本殿前面に建つ鉄筋コンクリート造社殿。南から下拝殿、上拝殿、幣殿とし、下拝殿は入母屋造向拝付で両側に下屋を付し、幣殿左右に祭器殿と神饌殿を張出し全体エ字形平面とする。幣殿を含め屋根を重ねた抑揚感ある外観を呈する。戦後間もない耐火構造の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015456"},{"id":"00015455","register_sub_id":"101","register_pk":"533470","name":"小梳神社本殿","kana":"おぐしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県静岡市葵区紺屋町7-13","lat":34.97366111,"lng":138.38641389,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積20㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"22 - 0341","desc":"市街地中心部の境内奥に南面する、建ちの高い鉄筋コンクリート造の一間社。切妻造平入銅板葺で、正側面に高欄付縁を廻らし脇障子を建てる。組物は平三斗で、頭貫に大仏様風の特異な木鼻を付す。軒廻りや妻部を含めコンクリートにより丁寧に造形された社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015455"},{"id":"00010307","register_sub_id":"101","register_pk":"199080","name":"可睡斎瑞龍閣","kana":"かすいさいずいりゅうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県袋井市久能2915-1","lat":34.774365,"lng":137.920128,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺及び銅板葺、建築面積638㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0198","desc":"木造二階建、妻入り、入母屋造桟瓦葺で下屋を廻らし、正面に唐破風玄関を構える。一階は大振りな座敷飾を備えた六間取、二階は大広間の周囲に畳廊下を廻らし、各室ごとに異なる主題に因む欄間や絵襖で華やかに飾る。規模雄大で優美な内装をもつ迎賓施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010307"},{"id":"00010308","register_sub_id":"101","register_pk":"199081","name":"可睡斎東司","kana":"かすいさいとうす","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県袋井市久能2915-1","lat":34.774479,"lng":137.919985,"geo_status":"db","era":"昭和12年頃","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0199","desc":"約八メートル四方の規模をもつ東司で、南辺に小便器、北東面に大便器室を並べ、中央の壇上に烏枢沙摩明王を祀る。天井は周囲に吹寄せの格縁を廻らして内側に網代天井を張り、中央に天蓋風の飾りを設ける。欄間に組子細工を飾るなど、風雅な意匠を持つ東司。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010308"},{"id":"00011960","register_sub_id":"101","register_pk":"354923","name":"旧東泉院宝蔵","kana":"きゅうとうせんいんほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県富士市今泉八丁目1428-1","lat":35.166707,"lng":138.686666,"geo_status":"db","era":"安政4年（1857）","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積42㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"22-242","desc":"旧東泉院境内に南面して建つ。桁行七・三メートル梁間四・五メートル、土蔵造二階建、切妻造で、南面に下屋を設けて戸口を開き、二階に窓を設ける。外壁は漆喰塗で鉢巻を廻らし、南面の腰を海鼠壁、他を簓子下見板張とする。富士修験に係る東泉院唯一の遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011960"},{"id":"00002546","register_sub_id":"101","register_pk":"103536","name":"清水寺庫裏","kana":"きよみずでらくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区音羽町27-8","lat":34.979099,"lng":138.396683,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積249㎡","structure_material":"木造平屋一部2階建","registered":"2001.11.20(平成13.11.20)","register_no":"22 － 0077","desc":"鉄筋コンクリート造本堂の南東方に建つ。入母屋造玄関をもつ木造平屋建，入母屋造，妻入の庫裏と木造２階建，寄棟造の奥書院から成る。庫裏の北側には西から８畳規模の応接室，８畳，１０畳の表書院を並べる。本堂と同じ古宇田實の設計による近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002546"},{"id":"00001710","register_sub_id":"101","register_pk":"102700","name":"清水寺鐘楼","kana":"きよみずでらしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県静岡市葵区音羽町27-8","lat":34.979588,"lng":138.396225,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0068","desc":"方一間、四方吹き放しの鐘台で、屋根は入母屋造、本瓦葺とする。本柱と間柱上に尾垂木付の組物を置いて華やかな軒廻りとする。青銅鋳物製の隅支柱に蓮をモチーフとする意匠を施し、蟇股や木鼻の意匠にも特色がある。設計は東京美術学校の古宇田實。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001710"},{"id":"00001112","register_sub_id":"101","register_pk":"102102","name":"清水寺本堂","kana":"きよみずでらほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市葵区音羽町27-8","lat":34.97925962,"lng":138.39652784,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建，建築面積186㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"22 － 0040","desc":"清水山公園に隣接した境内地に建つ鉄筋コンクリート造の本堂。正面７間に円柱を配し、中央３間は二手先として向拝風に切り上げた軒を支える。設計は神戸高等工業学校長古宇田実で、東京の島藤が請負った。切妻屋根を持つ特異な形態の本堂として知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001112"},{"id":"00010305","register_sub_id":"101","register_pk":"199078","name":"玄妙寺経蔵","kana":"げんみょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県磐田市見付字西坂2598","lat":34.727044,"lng":137.856033,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積13㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"22-0196","desc":"境内南東隅に西面して建ち、鉄筋コンクリート造、切妻造セメント瓦葺である。外壁は人造石洗出しで、柱形や軒蛇腹を表し、石造風に化粧目地を切る。正面に扉口、北面に窓を設けて庇を付け、鉄扉を開く。耐火性を重視した、戦前のコンクリート造経蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010305"},{"id":"00010306","register_sub_id":"101","register_pk":"199079","name":"玄妙寺門柱及び塀","kana":"げんみょうじもんちゅうおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県磐田市見付字玄妙小路2440-1他","lat":34.72705201,"lng":137.85561599,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土塀、延長16m","structure_material":"土塀","registered":"2014.12.19(平成26.12.19)","register_no":"22-0197","desc":"境内西辺を画す門柱と土塀で、いずれも三和土を成型した中空ブロックを積む。門柱は五段積として頂部に宝形造屋根を載せ、土塀は版築基礎上に四段布積し、同じ三和土で切妻屋根を造る。左官技法を駆使した独特な構造の門塀で、当地の建築技術を伝える希少例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010306"},{"id":"00001517","register_sub_id":"101","register_pk":"102507","name":"光長寺御宝蔵","kana":"こうちょうじごほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県沼津市岡宮1055","lat":35.12821517,"lng":138.87498897,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積41㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2000.02.15(平成12.02.15)","register_no":"22 － 0062","desc":"法華宗大本山光長寺境内の東北隅に建つ鉄筋コンクリート造の六角堂。銅板葺の屋根は尖塔状に反り上がり，モルタルで造られた虹梁・木鼻・蟇股・大瓶束が向拝柱，外壁を飾る。モルタルの外装材としての可能性を示した作品。設計は金田恭介，施工は内田金五郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001517"},{"id":"00011137","register_sub_id":"101","register_pk":"205244","name":"松蔭寺開山堂","kana":"しょういんじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県沼津市原字東畑128-1","lat":35.123299,"lng":138.800171,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積19㎡","structure_material":"石造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0222","desc":"境内南寄りに建ち、坐禅堂を接続する。一辺二・七メートルの六角形平面で屋根は六注の桟瓦葺とし、露盤上に宝珠を飾る。壁体は伊豆石積で内外ともに漆喰仕上げとし、石製の軒蛇腹を廻らす。内部は須弥壇を設け、白隠像を祀る。独自性の高い構造形式をもつ堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011137"},{"id":"00011138","register_sub_id":"101","register_pk":"205245","name":"松蔭寺山門","kana":"しょういんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"静岡県","address":"静岡県沼津市原字東畑128-1","lat":35.123932,"lng":138.800309,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"22 - 0223","desc":"境内北正面で旧東海道に向かって構える、間口三・〇メートルの一間薬医門、切妻造石瓦葺である。五平の本柱に冠木を渡し、控柱筋では差物と桁を重ねて堅固に組む。石瓦は長さ一メートルの伊豆石切石を三段に葺く。古刹の門前を特徴付ける希少な屋根の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011138"},{"id":"00000249","register_sub_id":"101","register_pk":"101239","name":"真珠院鐘楼","kana":"しんじゅいんしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"静岡県","address":"静岡県静岡市清水区梅ヶ谷608","lat":35.04490945,"lng":138.45085274,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造，建築面積26㎡","structure_material":"鉄筋コンクリート造","registered":"1997.07.15(平成9.07.15)","register_no":"22 － 0004","desc":"鉄筋コンクリート造の鐘楼。基壇上に袴腰や縁を取り付け、柱や長押㎡垂木等にペイント塗装を施す。袴腰の部分に鐘楼建造の由来を刻した石版をはめ込む。設計及び施工は市内の桜井康弘。寺院景観を構成する要素として訪れる人に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000249"},{"id":"00001617","register_sub_id":"101","register_pk":"102607","name":"大中寺恩香殿","kana":"だいちゅうじおんこうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県沼津市中沢田457","lat":35.12288621,"lng":138.85432566,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0064","desc":"大中寺は沼津市郊外に位置する梅園で名高い臨済宗寺院であり，恩香殿は沼津御用邸に滞在中の皇族の観梅などの際の休息所として建築された。広間と前室の三方に広縁を廻し，広間背後に茶室を設ける。敷地の高低差を活かし庭園と一体的な景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001617"},{"id":"00001618","register_sub_id":"101","register_pk":"102608","name":"大中寺通玄橋","kana":"だいちゅうじつうげんばし","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県沼津市中沢田457","lat":35.12276328,"lng":138.85437166,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、橋長6m","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"22 － 0065","desc":"庫裏から恩香殿の南妻側に通じる太鼓橋風の渡り廊下で，切妻造の屋根を架ける。高欄や垂れ壁などのデザインに特色がある。庫裏の建て替えに伴ってわずかに位置を変更しているが，恩香殿と同時期の建築であり一体の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001618"},{"id":"00013117","register_sub_id":"101","register_pk":"368376","name":"大福寺庫裏","kana":"だいふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区三ヶ日町福長字寺中219","lat":34.82928056,"lng":137.54970278,"geo_status":"db","era":"大正後期／昭和20年代移築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積308㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"22 － 0282","desc":"製糸工場の事務所兼迎賓館を移築し庫裏としたもの。建ちの高い二階建で、一階は正面中央に入母屋造の玄関を据え、中廊下を通し南北に上質な座敷を並べ、外周部に縁を廻す。土間や根太天井等の民家の特性を示し、大正期の製糸工場の一端を伝える近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013117"},{"id":"00012916","register_sub_id":"101","register_pk":"368098","name":"方広寺行在所","kana":"ほうこうじあんざいしょ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84903889,"lng":137.61545278,"geo_status":"db","era":"明治元年／明治18年移築・改修、昭和前期改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積167㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 266","desc":"新居宿本陣・飯田家の明治天皇行在所を移築したもので、三笑閣北方に南面して建つ。寄棟造桟瓦葺妻入。四周に下屋を廻し、正面西端に起り屋根の玄関、東側面北端に茶室を付す。南に24畳の次の間、北に上段の間を配する。格式を備えた上質な書院建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012916"},{"id":"00012919","register_sub_id":"101","register_pk":"368101","name":"方広寺開山堂","kana":"ほうこうじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84838056,"lng":137.61428056,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 269","desc":"観音堂の西側に南面して建つ。桁行3間梁間3間、入母屋造本瓦葺。各面に両折桟唐戸と花頭窓を設ける。内部は土間四半敷で、背面中央に拝所を出して昭堂に接続する。組物は尾垂木付二手先の詰組、中備は間斗束、妻飾は虹梁大瓶束。華麗な佇まいの礼拝施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012919"},{"id":"00012925","register_sub_id":"101","register_pk":"368107","name":"方広寺神楽堂","kana":"ほうこうじかぐらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84799444,"lng":137.61426944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 275","desc":"半僧坊拝殿の南方に北面して建つ平屋建、正面吹放しの土間舞台。一軒疎垂木、入母屋造桟瓦葺。南面に下屋で幅半間の上段を通し、格天井、壁縦板張とする。東面にある切妻造の控室は化粧屋根裏、内壁漆喰塗。水屋とともに半僧坊前の祭礼空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012925"},{"id":"00012918","register_sub_id":"101","register_pk":"368100","name":"方広寺観音堂","kana":"ほうこうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84843889,"lng":137.61443889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 268","desc":"本堂の西側に南面して建つ。正面1間側背面2間、宝形造桟瓦葺で、両側面前半に張出し部を設け、正面に擬宝珠高欄付の切目縁を通す。内部は竿縁天井の一室で、後方に仏壇を設けて観音菩薩像を安置する。小規模ながら均整の取れた外観で境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012918"},{"id":"00012928","register_sub_id":"101","register_pk":"368110","name":"方広寺三重塔","kana":"ほうこうじさんじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84738333,"lng":137.61625278,"geo_status":"db","era":"大正12年／昭和中期増築、平成11年改修","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造三重塔、瓦葺、建築面積11㎡、門塀付","structure_material":"木造三重塔","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 278","desc":"本堂の南方、沢を隔てた山頂に西面して建つ。各重とも方3間、組物は尾垂木付三手先、二軒繁垂木、本瓦葺である。乱石積基壇の正面中央を突出して切妻造の棟門を構え、四周に板塀を廻す。もと京都府技手・安井楢次郎の設計で、古典的な和様の構成をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012928"},{"id":"00012914","register_sub_id":"101","register_pk":"368096","name":"方広寺三笑閣","kana":"ほうこうじさんしょうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84868611,"lng":137.61552778,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階一部地下１階建、瓦葺、建築面積524㎡","structure_material":"木造2階一部地下１階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 264","desc":"大庫裡の東側に接続する接客施設。入母屋造桟瓦葺二階建を東西に並べ、東を南北棟、西を東西棟とする。2階は各大座敷で、1階は東に小座敷、西に厨房と水場を配し、両棟間には食堂を設ける。大庫裡とともに大本山にふさわしい広壮な接客空間を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012914"},{"id":"00012929","register_sub_id":"101","register_pk":"368111","name":"方広寺山門","kana":"ほうこうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84878611,"lng":137.61784444,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 279","desc":"本堂の南東方、沢沿いの参道上に南面して建つ。入母屋造本瓦葺の三間一戸二重門で、組物は下層を出組、上層を尾垂木付二手先、中備は間斗束、中央間を双斗とする。妻飾は虹梁大瓶束。軒は二軒繁垂木。精緻なつくりで、格式ある大本山の表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012929"},{"id":"00012911","register_sub_id":"101","register_pk":"368093","name":"方広寺知客寮","kana":"ほうこうじしかりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84861389,"lng":137.61500833,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 261","desc":"本堂の東面北端に接続する役僧の詰所。南北棟の入母屋造桟瓦葺、二軒疎垂木で、南に本堂と大庫裡をつなぐ幅二間の廊下を通し、北に14畳座敷と6畳控室、物置を配して東北二面に縁を廻す。本堂、大庫裡と並び建ち、境内中心部の壮大な景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012911"},{"id":"00012927","register_sub_id":"101","register_pk":"368109","name":"方広寺七尊菩薩堂拝殿","kana":"ほうこうじしちそんぼさつどうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84776944,"lng":137.61442222,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 277","desc":"本堂の南西方、沢を隔てた山腹に東面して建つ。桁行3間梁間2間、切妻造桟瓦葺、壁縦板張で、正面中央間に出入口を設ける。内部は板敷、竿縁天井とする。背面中央間を開放して覆屋内に安置する流造の七尊菩薩堂を臨み、神前に静謐な礼拝空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012927"},{"id":"00012915","register_sub_id":"101","register_pk":"368097","name":"方広寺宗務本院","kana":"ほうこうじしゅうむほんいん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84905278,"lng":137.61544167,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 265","desc":"大庫裡北側の高台に南面して建つ宗務総長の執務室。切妻造桟瓦葺の平屋建で、西南北三面に下屋を廻し、渡廊下で大庫裡に接続する。前後2列6室を配して西北隅を座敷とし、西北二面に縁を廻す。知客寮、大庫裡とともに大本山の寺務空間の構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012915"},{"id":"00012920","register_sub_id":"101","register_pk":"368102","name":"方広寺昭堂","kana":"ほうこうじしょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.848475,"lng":137.61395278,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 270","desc":"開山堂北面に接続する開祖をまつる堂宇。桁行2間梁間2間、宝形造銅板葺で、正面中央に出入口を設ける。内部は格天井の一室で、奧に仏壇を設ける。尾垂木付二手先詰組に中備間斗束を加え、虹梁や肘木に丁寧な絵様を彫るなど、上質な意匠をもつ祠堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012920"},{"id":"00012913","register_sub_id":"101","register_pk":"368095","name":"方広寺鐘楼","kana":"ほうこうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84821111,"lng":137.61514167,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積15㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 263","desc":"本堂の正面東寄りに建つ。方一間袴腰付の形式で、入母屋造桟瓦葺である。上層は吹放しで四周に廻した縁を二手先腰組で支持し、格天井を張る。組物は二手先、中備は間斗束として、二軒繁垂木の軒を受ける。玉石積基壇上にあって、本堂前広場で存在感を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012913"},{"id":"00012917","register_sub_id":"101","register_pk":"368099","name":"方広寺禅堂","kana":"ほうこうじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84911667,"lng":137.61568889,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 267","desc":"行在所東方の崖下に南面して建つ。入母屋造桟瓦葺妻入、正背面中央の出入口を両折桟唐戸とし、正面両脇に花頭窓を設ける。内部は土間四半敷の一室で、棟通りに達磨像を安置し、両側に畳敷の高床を設け、竿縁天井を張る。臨済宗寺院の構成要素となる附属建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012917"},{"id":"00012930","register_sub_id":"101","register_pk":"368112","name":"方広寺総門","kana":"ほうこうじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84809722,"lng":137.61840833,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口4.4m、左右袖塀付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 280","desc":"山門南方の参道入口に南面して建つ。切妻造桟瓦葺の一間高麗門で、扉は備えず、左右に矩折れの袖塀を付す。親柱は木鼻付の楣貫で固め、棟木との間に格子を入れ、二段の挿肘木で軒桁を受ける。良材を用いた丁寧なつくりで、門前景観を格調高く演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012930"},{"id":"00012912","register_sub_id":"101","register_pk":"368094","name":"方広寺大庫裡","kana":"ほうこうじだいくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84840833,"lng":137.61522222,"geo_status":"db","era":"大正前期／平成2年頃改修","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、瓦葺、建築面積513㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 262","desc":"南北棟の切妻造桟瓦葺の長大な庫裡で、本堂の東側に西面して建つ。正面中央の唐破風玄関の左右に入母屋の突出部を付した特徴的な表構えをもつ。北は展示室などの公的空間、南は事務室などの業務空間とする。豪壮な外観で、大本山にふさわしい格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012912"},{"id":"00012910","register_sub_id":"101","register_pk":"368092","name":"方広寺勅使玄関","kana":"ほうこうじちょくしげんかん","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84826944,"lng":137.614725,"geo_status":"db","era":"大正4年／平成22年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡、左右築地塀付","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 260","desc":"本堂の西面南端に接続する賓客用玄関。間口1間奥行2間、向唐破風本瓦葺の屋根をかけ、左右に築地塀を付す。正面に桟唐戸を構え、床は四半敷、天井は木舞打茨垂木の現しとする。虹梁大瓶束の妻飾、菊花紋付の虹梁上蟇股など、本堂の表構えを格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012910"},{"id":"00012921","register_sub_id":"101","register_pk":"368103","name":"方広寺勅使門","kana":"ほうこうじちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84820556,"lng":137.61442222,"geo_status":"db","era":"明治40年／昭和10年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、間口4.1m、左右築地塀付","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 271","desc":"凹形に後退した開山堂正面の石垣上に南面して建つ四脚門で、左右前方に築地塀を延ばす。切妻造銅板葺で、前後に軒唐破風を付す。扉は桟唐戸、組物は平三斗、妻飾は虹梁大瓶束笈形付で、冠木上の蟇股には菊花紋をあしらう。開山堂の表構えを重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012921"},{"id":"00012923","register_sub_id":"101","register_pk":"368105","name":"方広寺半僧坊真殿","kana":"ほうこうじはんそうぼうしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84852222,"lng":137.61388889,"geo_status":"db","era":"明治21年","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 273","desc":"拝殿北面に接続する半僧坊をまつる堂宇。桁行3間梁間3間、入母屋造桟瓦葺、側背面に縁を廻し、二軒繁垂木とする。内部は格天井の一室で、奧に仏壇を設ける。組物は出組、中備は蟇股、妻飾は虹梁大瓶束。建ちの低い構成と軒の深い緩やかな屋根に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012923"},{"id":"00012922","register_sub_id":"101","register_pk":"368104","name":"方広寺半僧坊拝殿","kana":"ほうこうじはんそうぼうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84846111,"lng":137.613975,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺及び瓦葺、建築面積183㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 272","desc":"中心部の北西方に南面して建つ。桁行三間梁間五間、向拝一間で、背面中央に祈祷所を出して真殿に接続する。入母屋造銅板葺の正面千鳥破風付、向拝軒唐破風付。尾垂木付二手先の組物や虹梁大瓶束の妻飾、龍丸彫の海老虹梁など、外観を華やかな意匠で整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012922"},{"id":"00012924","register_sub_id":"101","register_pk":"368106","name":"方広寺札場","kana":"ほうこうじふだば","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84831111,"lng":137.61383333,"geo_status":"db","era":"明治21年頃／昭和49年頃改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積45㎡、渡廊下付","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 274","desc":"半僧坊拝殿の西側に東面して建つ。入母屋造銅板葺の平屋建で、北面を矩折れの渡廊下で拝殿に接続する。組物や妻飾はなく簡素だが、軒は二軒隅扇垂木で丁寧につくる。内部は3室を並べる。権現造風の真殿・拝殿とともに境内北西部の森厳な景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012924"},{"id":"00012909","register_sub_id":"101","register_pk":"368091","name":"方広寺本堂","kana":"ほうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84845833,"lng":137.61485833,"geo_status":"db","era":"大正4年／平成22年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積735㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 259","desc":"浜松市街北西方にある臨済宗寺院。本堂は境内中心部に南面して建つ整形六間取の方丈形式で、正面に広縁を通し、側背面に廊下を廻す。懸造状に張出した正面の刎高欄付の切目縁や入母屋造桟瓦葺の大屋根、三重虹梁大瓶束の妻飾など、大本山の威容を存分に示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012909"},{"id":"00012926","register_sub_id":"101","register_pk":"368108","name":"方広寺水屋","kana":"ほうこうじみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"静岡県","address":"静岡県浜松市北区引佐町奥山1577-1","lat":34.84798611,"lng":137.61433333,"geo_status":"db","era":"明治26年頃","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"22 － 276","desc":"神楽堂の東側に並んで建つ。切妻造桟瓦葺の起り屋根、吹放しの長方形平面で、鏡天井を張り、中央に手水石を据える。内転びの角柱を内法虹梁と頭貫で固め、台輪を廻す。組物は平三斗、一軒疎垂木とする。丁寧なつくりで、半僧坊前の景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012926"},{"id":"00008287","register_sub_id":"101","register_pk":"133929","name":"安久美神戸神明社神楽殿","kana":"あくみかんべしんめいしゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76799185,"lng":137.39454176,"geo_status":"db","era":"明治18年／昭和5年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0324","desc":"拝殿南西側に妻を東面して建て、桁行６．４ｍ梁間４．５ｍ、入母屋造及び切妻造桟瓦葺である。拝殿側の東・北面を開放できる構成とし、舞台に舟底天井を張り、アト座北面に切戸口、南面に社務所への出入口を開け、鏡板に松を描くなど、能舞台の諸要素を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008287"},{"id":"00008288","register_sub_id":"101","register_pk":"133930","name":"安久美神戸神明社神庫","kana":"あくみかんべしんめいしゃしんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76793236,"lng":137.39482254,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積30㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0325","desc":"拝殿南東側に神楽殿と対向して建つ。 桁行５．５ｍ梁間４．５ｍ、鉄筋コンクリート造平屋建、正面向拝付、寄棟造桟瓦葺である。外観は土蔵風として軒反りや隅木を作り、内部も柱型や隅木などを表す。伝統形式の土蔵を鉄筋コンクリート造で表現した神庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008288"},{"id":"00008289","register_sub_id":"101","register_pk":"133931","name":"安久美神戸神明社手水舎","kana":"あくみかんべしんめいしゃてみずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76775628,"lng":137.39470118,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、銅板葺、建築面積10㎡","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0326","desc":"拝殿前方の鳥居脇に建ち、桁行３．５ｍ梁間２．９ｍ、木造平屋建、切妻造、茅葺型銅板葺である。円柱を四方転びに建て、豕扠首組で棟木を受ける。素木の直材を基本とし、神明造を基調とした本殿などと調和した外観をもち、統一感のある境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008289"},{"id":"00008286","register_sub_id":"101","register_pk":"133928","name":"安久美神戸神明社幣殿及び拝殿","kana":"あくみかんべしんめいしゃへいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76811796,"lng":137.39470594,"geo_status":"db","era":"昭和5年／昭和45年改修","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積144㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0323","desc":"本殿の前面に位置し、 桁行１８ｍ梁間４．８ｍの拝殿後方に、５．５ｍ四方の幣殿を張り出す。屋根は切妻造銅板葺で、棟上に千木と堅魚木をあげ、拝殿両端の神饌置場と楽舎を落棟とする。本殿と同じく、角南隆の設計による大型拝殿で、風格ある外観をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008286"},{"id":"00008285","register_sub_id":"101","register_pk":"133927","name":"安久美神戸神明社本殿","kana":"あくみかんべしんめいしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊橋市八町通3-17","lat":34.76825597,"lng":137.39473212,"geo_status":"db","era":"昭和5年／昭和45年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"23 － 0322","desc":"境内北端に鎮座し、桁行三間梁間二間、神明造銅板葺で、周囲に縁をめぐらして木階を設け、棟に千木と堅魚木をあげる。直線的な部材構成や両妻に立つ棟持柱など神明造の制式に則ったつくりで、要所を錺金具で飾る。内務省神社局の角南隆による神社建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008285"},{"id":"00014159","register_sub_id":"101","register_pk":"508789","name":"朝日神社透塀（蕃塀）","kana":"あさひじんじゃばんぺい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区錦三丁目2219-1","lat":35.16883611,"lng":136.90392778,"geo_status":"db","era":"文化6年(1809)／昭和33年移築","year":1809,"year_source":"db","year_min":1809,"year_max":1809,"year_label":null,"structure":"木造、銅板葺、延長4.5m","structure_material":"木造","registered":"2022.02.17(令和4.02.17)","register_no":"23-0564","desc":"市街地に所在する旧城下の神社透垣で、大鳥居の西隣に位置する。切妻造銅板葺で疎垂木とし腕木に繰形を施す。規模は延長三間で円柱に長押付、各間連子窓に腰板壁とし、石製の控え柱で支える。尾張地方に多い形式の神前目隠し塀で、地域の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014159"},{"id":"00011966","register_sub_id":"101","register_pk":"211104","name":"安長寺山門","kana":"あんちょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市梅坪町五丁目14-1","lat":35.100129,"lng":137.15752,"geo_status":"db","era":"天保3年（1832）","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"23-505","desc":"豊田市西部の高台にあり東面する。一間一戸の楼門で、上層に三尊仏を安置していた。屋根は入母屋造で妻飾は虹梁大瓶束で渦状の笈形を付す。下層は柱を内転びに立て、絵様肘木と持送りで縁葛を支え、上層の組物は二手先で板支輪を地紋彫とし、大工の技量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011966"},{"id":"00014850","register_sub_id":"101","register_pk":"519110","name":"牛田八幡社覆殿","kana":"うしだはちまんしゃおおいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00089722,"lng":137.06878333,"geo_status":"db","era":"安政3年(1856)頃","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0604","desc":"内部に本殿を安置する桁行三間梁間二間、入母屋造桟瓦葺、正面一間向拝付の覆屋。正側面に擬宝珠高欄付の縁を廻らし、脇障子を建てる。身舎組物は出組で妻飾は虹梁大瓶束。向拝の虹梁形頭貫廻りや手挟などを彫刻で飾る。本格的な本殿形式の構成になる覆殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014850"},{"id":"00014851","register_sub_id":"101","register_pk":"519111","name":"牛田八幡社中殿及び袖廊","kana":"うしだはちまんしゃちゅうでんおよびそでろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00081667,"lng":137.06879167,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0605","desc":"覆殿の南面に位置する。入母屋造妻入、桟瓦葺とした中殿の両側面前寄りに、棟を直交して切妻造桟瓦葺の袖廊を付したＴ字平面で、西袖廊を神饌所、東を神具庫とする。中殿は土間で格天井を張り、正面の虹梁廻りや妻飾に、龍や虎、鶴の彫刻を密度高く配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014851"},{"id":"00014852","register_sub_id":"101","register_pk":"519112","name":"牛田八幡社拝殿","kana":"うしだはちまんしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00068889,"lng":137.06881389,"geo_status":"db","era":"明治15年","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0606","desc":"中心社殿の南端に位置する拝殿。南面して建つ桁行三間梁間三間、入母屋造桟瓦葺。組物は拳鼻付の出組として支輪を彫刻で満たす。二軒繁垂木、妻飾は虹梁大瓶束。内部は一室の拭板敷とし小組格天井を張る。南面の虹梁上や組物間など彫刻で華やかに飾った拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014852"},{"id":"00014849","register_sub_id":"101","register_pk":"519109","name":"牛田八幡社本殿","kana":"うしだはちまんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市牛田町宮本14","lat":35.00090278,"lng":137.06878333,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積1.7㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0603","desc":"猿渡川北岸に位置する神社本殿。境内北の覆殿内に南面して建つ一間社流造こけら葺。正側面に擬宝珠高欄付縁を廻らし脇障子を建てる。身舎組物は出三斗、庇は三斗で中備は蟇股、妻飾は虹梁大瓶束。軸部や組物に塗装や彩色を残し、小社ながら整った意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014849"},{"id":"00005187","register_sub_id":"101","register_pk":"106177","name":"雲興寺鐘楼","kana":"うんこうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県瀬戸市白坂町131","lat":35.22233528,"lng":137.14492252,"geo_status":"db","era":"文化7","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造、瓦葺、建築面積28㎡","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0209","desc":"境内中心部，本堂南にある。桁行２間，梁間２間の袴腰付鐘楼で，入母屋造，桟瓦葺である。出組で縁を支え，軸部は円柱を立て，柱頭の外部に長押を廻し，二手先組物に中備を蟇股とする。棟札から年代等が明確で，地域における江戸後期の基準作のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005187"},{"id":"00013121","register_sub_id":"101","register_pk":"368278","name":"永住寺開山堂及び位牌堂","kana":"えいじゅうじかいさんどうおよびいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.902575,"lng":137.49830556,"geo_status":"db","era":"明治26年","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0537","desc":"本堂北背後に続く切妻造の南北棟に開山堂と位牌堂を収める。前方の開山堂は奥行２間で前面円柱間に虹梁形鴨居を渡し、仏壇前には３連の虹梁を架ける。仏壇は中央間に花頭口を設けて仏龕を張出す。続く位牌堂は奥行７間で、東西両側に位牌壇を設け高窓を開く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013121"},{"id":"00013125","register_sub_id":"101","register_pk":"368282","name":"永住寺経蔵","kana":"えいじゅうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90271111,"lng":137.49858056,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0541","desc":"境内の北東、書院北方に南面して建つ、方１０尺規模の土蔵造である。屋根は宝形造とし、軒は一軒疎垂木とする。外壁は漆喰塗である。正面に木階２級を設け、戸口は土塗戸を引分ける。内部は板敷、棹縁天井で北奥に壇を設ける。伽藍を構成する小建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013125"},{"id":"00013122","register_sub_id":"101","register_pk":"368279","name":"永住寺庫裡及び書院","kana":"えいじゅうじくりおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90235556,"lng":137.49862222,"geo_status":"db","era":"文化7年（1810）","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積702㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0538","desc":"本堂東に書院が接続し、中庭や廊下などを介して南の庫裡へ続く。庫裡南の土間に竈を置き、北西に広い板敷を設ける。西の土間通路は矩折れに書院南の玄関に至る。書院は北に１５畳２室を並べ、東室に床棚を設ける。曹洞宗伽藍を特徴づける大規模な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013122"},{"id":"00014487","register_sub_id":"101","register_pk":"513901","name":"永住寺山門","kana":"えいじゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90178889,"lng":137.49858611,"geo_status":"db","era":"寛政6年（1794）","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"23 - 0586","desc":"曹洞宗寺院の伽藍南に開く表門。切妻造本瓦葺の四脚門、二軒繁垂木、柱は円柱で礎盤に立て、控柱間に虹梁を架け、棟持柱の主柱と貫で繋ぐ。大工は信州立川流、妻面の挿肘木の斗組は特徴的で、虹梁廻りを立体的な彫刻で飾る。総じて重厚で華やかな総欅造の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014487"},{"id":"00013124","register_sub_id":"101","register_pk":"368281","name":"永住寺衆寮","kana":"えいじゅうじしゅりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90218333,"lng":137.49828889,"geo_status":"db","era":"享保7年（1722）","year":1722,"year_source":"db","year_min":1722,"year_max":1722,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積105㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0540","desc":"本堂の南西に東面して建つ、切妻造の南北棟である。南の禅堂との間に一段低く屋根を架ける。内部は東に土間を通し、床上部は２列６室で東列が南から８畳と６畳２室、西列が６畳と４・５畳２室である。禅宗伽藍を構成する特徴的な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013124"},{"id":"00013123","register_sub_id":"101","register_pk":"368280","name":"永住寺禅堂","kana":"えいじゅうじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90228611,"lng":137.49825278,"geo_status":"db","era":"享保7年（1722）","year":1722,"year_source":"db","year_min":1722,"year_max":1722,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0539","desc":"本堂南西に東面して建つ切妻造の南北棟で、正面に切妻向拝を付す。内部は前面に土間を通し南北を引違戸とする。床上は両脇間と奥の１間幅を板敷、中央を畳敷とする。西背面の張出しを仏壇とする。中央の畳敷は元土間であった。禅宗伽藍の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013123"},{"id":"00014486","register_sub_id":"101","register_pk":"513900","name":"永住寺鎮守殿","kana":"えいじゅうじちんじゅでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90210833,"lng":137.49830556,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"23 - 0585","desc":"曹洞宗寺院の伽藍南西端、稲荷信仰と習合する吒枳尼天を祀る小堂。入母屋造妻入、二軒半繁垂木で正面に向拝を付し、内部は内・外陣を虹梁で分け、共に格天井とする。内々陣壇上に一間社流造宮殿を置く。豊川稲荷に近い土地柄を示し、歴史的伽藍を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014486"},{"id":"00013120","register_sub_id":"101","register_pk":"368277","name":"永住寺本堂","kana":"えいじゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市字裏野3","lat":34.90241667,"lng":137.498375,"geo_status":"db","era":"元禄10年（1697）／享保2年（1717）改修","year":1697,"year_source":"db","year_min":1697,"year_max":1697,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積298㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"23 － 0536","desc":"境内中央に南面して建つ、入母屋造桟瓦葺の本堂。２列６室平面で、後列中央を内陣とする。前面に畳敷広縁を通し、東面と西面を畳縁とする。内陣前の２柱と来迎柱は円柱で他は角柱である。広縁は元は縁と土間で書院に通じており、曹洞宗本堂の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013120"},{"id":"00009299","register_sub_id":"101","register_pk":"194092","name":"圓明寺庫裏","kana":"えんめいじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38211626,"lng":136.94177009,"geo_status":"db","era":"江戸末期／明治中期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積314㎡","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0353","desc":"本堂南西側に東面して建つ。木造平屋一部二階建、建築面積三一四平方メートル、切妻造桟瓦葺で正面を下屋とする。内部は入口付近を土間とし北側に座敷を並べる。城下の町家を移築したもので、起り屋根や、上下階の正面各間に建てた格子などに名残をとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009299"},{"id":"00009301","register_sub_id":"101","register_pk":"194094","name":"圓明寺山門","kana":"えんめいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38199919,"lng":136.94194998,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、銅板葺、間口2.5m","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0355","desc":"境内の南正面に構える四脚門形式の山門。桁行二・五メートル梁間二・一メートル、切妻造銅板葺で正面に軒唐破風を付ける。本柱は円柱、控柱を几帳面取角柱とし、正面は虹梁と蟇股を二段重ねて華やかなつくりとする。伊藤平左衛門による材工ともに良質な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009301"},{"id":"00009300","register_sub_id":"101","register_pk":"194093","name":"圓明寺鐘楼","kana":"えんめいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38205772,"lng":136.94203849,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積9㎡","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0354","desc":"境内東側、庫裏と向き合って基壇上に建つ、入母屋造本瓦葺の吹放し鐘楼。三メートル四方の平面で、軸部は禅宗様を基調とし、組物は二手先詰組、妻飾は虹梁大瓶束とする。深い軒には強い軒反りをもたせるなど本格的なつくりで、境内景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009300"},{"id":"00009298","register_sub_id":"101","register_pk":"194091","name":"圓明寺僧寮","kana":"えんめいじそうりょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38220192,"lng":136.94187288,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0352","desc":"本堂と庫裏の間に建ち、木造平屋建、建築面積九〇平方メートル、切妻造桟瓦葺で、本堂側の東面に切妻造の式台玄関を構える。東側に一間幅の廊下を通し、西側には北から四畳半など四室を配する。玄関廻りに良材を用いた、丁寧なつくりになる接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009298"},{"id":"00009297","register_sub_id":"101","register_pk":"194090","name":"圓明寺本堂","kana":"えんめいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券595","lat":35.38230899,"lng":136.94196996,"geo_status":"db","era":"江戸前期／元禄2年改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0351","desc":"境内北奥に建ち、桁行一五・三メートル梁間一六・七メートル、入母屋造本瓦葺で、一間向拝を付ける。堂内は後門形式の内陣と余間、外陣を配し、外陣後寄りに矢来内を画し、前面を広縁とする。全て角柱とする点や細部に古式をとどめる浄土真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009297"},{"id":"00014835","register_sub_id":"101","register_pk":"519095","name":"大目神社本殿","kana":"おおまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県瀬戸市巡間町1","lat":35.22003889,"lng":137.13156111,"geo_status":"db","era":"文化2年(1805)／昭和52年改修","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0589","desc":"赤津の大目森の丘に位置する神社本殿。南面する三間社流造銅板葺で、三方に擬宝珠高欄付の縁を廻らし、木階と浜床を付す。組物は平三斗、軒は二軒繁垂木、妻飾は豕扠首。正面柱間は吹放ち、柱筋から北に寄せて幣軸構えとする形式で、当地域の特徴を示す本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014835"},{"id":"00002772","register_sub_id":"101","register_pk":"103762","name":"花岳寺本堂","kana":"かがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市吉良町岡山山王山67","lat":34.84333,"lng":137.082275,"geo_status":"db","era":"貞享1","year":1684,"year_source":"db","year_min":1684,"year_max":1684,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"23 － 0059","desc":"吉良氏の菩提寺となった臨済宗寺院本堂。入母屋造，桟瓦葺で，六間取りの典型的な形式をとるが，仏壇の構えや木割が細い点に古式を伝える。建具等一部に改造はあるが主要材はほとんど当初材が残り，１７世紀後期における地域の禅宗本堂を知る上で重要な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002772"},{"id":"00004775","register_sub_id":"101","register_pk":"105765","name":"覚王寺庫裏","kana":"かくおうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.353275,"lng":136.922256,"geo_status":"db","era":"天保11","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積400㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0201","desc":"南北棟で煙出付の切妻造，妻入，桟瓦葺で，本堂とは西面の廊下で繋がる。平面は南側を土間とし，床上部は棟通りで東西に分かれ，北西部に１５畳大で床・棚付の座敷を設ける。桁行２４ｍに及ぶ雄大な規模で，禅宗寺院庫裏らしく，南妻面は海老虹梁などで飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004775"},{"id":"00004778","register_sub_id":"101","register_pk":"105768","name":"覚王寺山門","kana":"かくおうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.35293265,"lng":136.92191531,"geo_status":"db","era":"明治35","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口3.2m、潜門及び左右袖塀付","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0204","desc":"１間１戸薬医門で，左右に潜門と塀を附属し，段違いの屋根を連続する。軒は二軒繁垂木，切妻造，桟瓦葺の屋根で，組物は三斗，妻飾は虹梁・大瓶束とする。虹梁等の絵様は彫りが深いが華美ではなく，総欅になる丁寧なつくりで，正面入口に相応しい品格を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004778"},{"id":"00004777","register_sub_id":"101","register_pk":"105767","name":"覚王寺鐘楼","kana":"かくおうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.35319266,"lng":136.921753,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、建築面積29㎡","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0203","desc":"本堂南方にある。切石積基壇上に建ち，袴腰を簓子下見板張，擬宝珠高欄付の縁は出組詰組で受け，中備に蟇股を入れる。組物は出組詰組，蟇股・軒支輪を設ける。二軒繁垂木，入母屋造，桟瓦葺で，板天井には天女を描く。手の込んだつくりの方１間の袴腰付鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004777"},{"id":"00004776","register_sub_id":"101","register_pk":"105766","name":"覚王寺大日堂","kana":"かくおうじだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.35327262,"lng":136.92178307,"geo_status":"db","era":"寛政6","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0202","desc":"本堂の南西にあり，東を正面とする。８畳大の１室の背面に仏壇を張り出した平面で，１間向拝を設け，正面と両側面に切目縁をつける。屋根は宝形造，桟瓦葺で，仏壇廻りでは丸柱で組物を用いる。簡素なつくりの小堂であるが，近世の境内構成を伝える上で貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004776"},{"id":"00004774","register_sub_id":"101","register_pk":"105764","name":"覚王寺本堂","kana":"かくおうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県丹羽郡扶桑町大字高雄字南屋敷135","lat":35.353355,"lng":136.922012,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積354㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0200","desc":"ほぼ南面して建つ入母屋造，桟瓦葺，方丈形式の本堂。正面に広縁を設けた６間取平面で，室中と上間・下間は境を竹の節欄間として格天井を連続させ，上奥間の２室構成やつし２階は独特である。装飾は控えているが，たちの高い外観は江戸後期の造形とみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004774"},{"id":"00008698","register_sub_id":"101","register_pk":"149419","name":"カトリック主税町教会司祭館","kana":"かとりっくちからまちきょうかいしさいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市東区主税町3-33","lat":35.18047258,"lng":136.91429225,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"converted","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階地下1階建、瓦葺、建築面積126㎡","structure_material":"木造2階地下1階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0335","desc":"信者会館の東に接して建つ。木造2階地下1階建、建築面積126㎡。寄棟造桟瓦葺、逆Ｌ字形屋根で、東面に小屋根を突き出す。北面西寄りに庇をかけ、玄関とする。外壁は下見板張、ペンキ塗。東面に1、2階通しのベイウインドゥを設け、外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008698"},{"id":"00008697","register_sub_id":"101","register_pk":"149418","name":"カトリック主税町教会信者会館","kana":"かとりっくちからまちきょうかいしんじゃかいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区主税町3-33","lat":35.18054933,"lng":136.91419866,"geo_status":"db","era":"明治中期／昭和55年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積89㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0334","desc":"主税町の角地に敷地を占める。北面する木造2階建、桁行11ｍ梁間8.2ｍ。寄棟造桟瓦葺、中央に切妻造玄関を構える。中廊下式平面になり、南面にベランダを設ける。外壁は下見板張で、白いペンキが塗られる。コロニアルスタイルを基本とする明治期洋館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008697"},{"id":"00008699","register_sub_id":"101","register_pk":"149420","name":"カトリック主税町教会煉瓦塀","kana":"かとりっくちからまちきょうかいれんがべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区主税町3-33","lat":35.18096113,"lng":136.91447756,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"煉瓦造、延長29m","structure_material":"煉瓦造","registered":"2011.07.25(平成23.07.25)","register_no":"23 － 0336","desc":"敷地北側、主税町筋沿い建つ。煉瓦造で、延長29ｍ、高さ2.1ｍ、厚さ35㎝。切石を2段積み、その上にイギリス積とし、上部は笠石状に張り出す。敷地内側には3.7ｍ間隔で、幅22㎝、出12㎝の控柱を付ける。主税町の伝統的な町並みを構成する一要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008699"},{"id":"00003649","register_sub_id":"101","register_pk":"104639","name":"興禅寺庫裏","kana":"こうぜんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市羽黒城屋敷16","lat":35.35315882,"lng":136.94923375,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積312㎡","structure_material":"木造平屋一部2階建","registered":"2003.12.01(平成15.12.01)","register_no":"23 － 0062","desc":"木造一部２階建，切妻造，本瓦葺。本堂東に位置する南北棟で，西側の接客部と東側の居住部に二分し，各々表から土間，板間，座敷で構成する。居住部の土間と板間は洋室に改装された。妻に表した小屋組の虹梁，太瓶束，海老虹梁や煙出しの越屋根が目をひく。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003649"},{"id":"00005620","register_sub_id":"101","register_pk":"106608","name":"興禅寺山門","kana":"こうぜんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字羽黒字城屋敷16","lat":35.35273138,"lng":136.94901341,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0224","desc":"切妻造，本瓦葺の四脚門で，本堂前方に南面して建ち，左右にＬ字型の築地塀を延ばす。軸部は親柱を円，控柱を角とし，三斗を組む。妻飾は虹梁大瓶束笈形，軒は二軒繁垂木とする。化粧材は総欅で，木目が美しい鏡天井，精緻で流麗な装飾細部等，造形的にも優作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005620"},{"id":"00005619","register_sub_id":"101","register_pk":"106607","name":"興禅寺本堂","kana":"こうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字羽黒字城屋敷16","lat":35.353165,"lng":136.948929,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積332㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0223","desc":"南面して建つ。六間取平面で，南・東・西の各面に入側を廻し，四周切目縁付で，背面に後堂を出す。出組，二軒で寄棟造の屋根を架け，四周に舟肘木，二軒の下屋を廻す。方丈形式の本堂では珍しい二重屋根の堂々たる外観を構成し，地域の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005619"},{"id":"00010168","register_sub_id":"101","register_pk":"198001","name":"財賀寺三十三観音堂","kana":"ざいがじさんじゅうさんかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山3","lat":34.874317,"lng":137.356939,"geo_status":"db","era":"寛政12","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0416","desc":"本堂の南東に西面して建つ。桁行三間梁間二間の切妻造平入で、正面中央間は実長二間と広くとって差鴨居を入れる。堂内は間仕切のない一室で、中央に框を入れて奥一間に仏壇を造作し、三十三観音を祀る。江戸後期に当地で流行した観音霊場巡礼を反映する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010168"},{"id":"00010167","register_sub_id":"101","register_pk":"198000","name":"財賀寺本堂","kana":"ざいがじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山3","lat":34.874762,"lng":137.356812,"geo_status":"db","era":"文政6／昭和3・昭和後期改修","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0415","desc":"山中の伽藍上段に建つ五間堂で、前側梁間二間を外陣、後半を内陣と両脇陣、後陣とする。外陣は、桁行の三間梁で天井を支持する、当地方に散見される架構をもつ。棟梁岡田五左衛門の特徴が架構以外の細部にも認められる。地方的特色を備え、規模も充実した本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010167"},{"id":"00010169","register_sub_id":"101","register_pk":"198002","name":"財賀寺文殊堂","kana":"ざいがじもんじゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山3","lat":34.873548,"lng":137.355654,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0417","desc":"伽藍中段に南面して建つ。入母屋造妻入で、正面に向拝を設ける。間口三間で、前一間を板敷の外陣、中三間を護摩壇を設ける内陣、背面に仏壇を張出して屋根を縋破風状とする。棟梁は岡田五左衛門で、蟇股などにその特徴が見られる。地域信仰の様相を伝える堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010169"},{"id":"00014162","register_sub_id":"101","register_pk":"508792","name":"西心寺山門","kana":"さいしんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県安城市川島町西屋敷16","lat":34.92736667,"lng":137.10609722,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造、瓦葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2022.02.17(令和4.02.17)","register_no":"23-0567","desc":"安城市東端の真宗寺院本堂の東正面に建つ四脚門。切妻造桟瓦葺、両脇に袖塀を設ける。主柱は円柱、控柱は几帳面取角柱、いずれも礎石、礎盤上に立つ。主柱に冠木を架け、虹梁で控柱と繋ぎ、三斗組。冠木を地紋彫とし、龍をはじめ随所に彫刻を飾る華麗な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014162"},{"id":"00014161","register_sub_id":"101","register_pk":"508791","name":"西心寺本堂","kana":"さいしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県安城市川島町西屋敷16","lat":34.92748333,"lng":137.10579722,"geo_status":"db","era":"天保6年(1835)","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積326㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"23-0566","desc":"安城市東端に位置。桁行９間梁間７間、入母屋造桟瓦葺で向拝を付す。妻に鰭を波型とする懸魚を付す。内部は表側を外陣、中央を矢来内、奥を内陣及び余間とする真宗寺院本堂の典型。中規模だが用材を吟味し、特徴的な彫刻等、地域の岡田大工の遺構として重要。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014161"},{"id":"00006609","register_sub_id":"101","register_pk":"107592","name":"西蓮寺蔵","kana":"さいれんじくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38212455,"lng":136.942551,"geo_status":"db","era":"明治期／昭和12移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0276","desc":"庫裏の東南に西面して建つ。桁行３．６ｍ梁間３．３ｍの規模で、切妻造妻入桟瓦葺とする。正面は漆喰塗とし、１階には庇を設け、北寄りに両開土戸を構え、２階には窓を穿ち、持送り付の庇を付ける。内部は１、２階とも１室の板敷とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006609"},{"id":"00006607","register_sub_id":"101","register_pk":"107590","name":"西蓮寺庫裏","kana":"さいれんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38220265,"lng":136.942413,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0274","desc":"本堂の東、南面して建つ。桁行６間半梁間６間の規模で、切妻造平入桟瓦葺とする。東端を土間とし、西側に座敷４室を田字型に配し、南に１間幅の畳縁、北に板敷を設ける。細い木柄を組み上げ和小屋を造る。住宅風の外観になる庫裏である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006607"},{"id":"00006608","register_sub_id":"101","register_pk":"107591","name":"西蓮寺山門","kana":"さいれんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38200537,"lng":136.9421971,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.1m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0277","desc":"本堂の正面、通りに南面して建つ。切妻造桟瓦葺の１間薬医門で、両側に潜戸を設ける。男梁上に三斗組、中備に蟇股を置き、その上に虹梁大瓶束で妻を造る。二軒疎垂木。木鼻を透かし彫りにするなど時代が下がるが、扉の八双金具等は古風である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006608"},{"id":"00006737","register_sub_id":"101","register_pk":"107720","name":"西蓮寺書院","kana":"さいれんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.3822041,"lng":136.94234629,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積91㎡","structure_material":"木造2階建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0275","desc":"本堂と庫裏の間に南面して建つ。桁行４間梁間６間規模の２階建で、切妻造平入桟瓦葺とし、正面西寄りに入母屋造屋根を突き出し、式台とする。室内はトコと違棚をもつ主室と次の間を南北に並べる。一部に前身建物材を再用。繊細な意匠になる書院建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006737"},{"id":"00006606","register_sub_id":"101","register_pk":"107589","name":"西蓮寺本堂","kana":"さいれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券539","lat":35.38220774,"lng":136.94222619,"geo_status":"db","era":"宝暦10／平成8改修","year":1760,"year_source":"db","year_min":1760,"year_max":1760,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0273","desc":"寺内町のほぼ中央、通りに南面する寺地の中央に南面して建つ。入母屋造本瓦葺の５間堂で１間向拝を付ける。外陣内部を柱列で仕切らず、矢来内も設けず、内陣も当初は間口一杯の仏壇とする平面形式をもつ浄土真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006606"},{"id":"00004583","register_sub_id":"101","register_pk":"105573","name":"實成寺山門","kana":"じつじょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県あま市中萱津南宿254","lat":35.18679876,"lng":136.84334824,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0187","desc":"本堂の前方，やや北寄りに東面して建つ。四脚門，切妻造，本瓦葺で，礎盤上に親柱，控柱とも丸柱を立て，頭貫と妻虹梁で固め，軒は二軒疎垂木で，木舞打ちとする。丸柱は粽付で，親柱を上部に延ばした禅宗様の大型の山門で，寺観正面の構えに欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004583"},{"id":"00004582","register_sub_id":"101","register_pk":"105572","name":"實成寺本堂","kana":"じつじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県あま市中萱津南宿254","lat":35.18683442,"lng":136.84288642,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積246㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"23 － 0186","desc":"桁行５間，梁間６間，宝形造，桟瓦葺で，正側面に１間幅の縁を廻し，正面に向拝１間を付す。内部は前方２間を外陣，後方中央間口３間，奥行４間を内陣，両脇を脇陣とし，内陣後方に来迎柱を後退し須弥壇を構える。平面や軸部構成に日蓮宗本堂の古式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004582"},{"id":"00003432","register_sub_id":"101","register_pk":"104422","name":"実相寺庫裡","kana":"じっそうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市上町下屋敷15","lat":34.87639452,"lng":137.03659987,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"23 － 0061","desc":"方丈東方に玄関部を介して接続する。桁行１４．７ｍ，梁間１５．４ｍ，入母屋造妻入，桟瓦葺（もと茅葺）で，南東隅に部屋を張り出す。前面土間とその奥の床上部は間仕切がなく，大梁を縦横に架け豪壮な大空間を造る。簡素だが禅宗伽藍構成上欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003432"},{"id":"00003431","register_sub_id":"101","register_pk":"104421","name":"実相寺方丈","kana":"じっそうじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県西尾市上町下屋敷15","lat":34.87642142,"lng":137.03631362,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"23 － 0060","desc":"吉良氏建立になる臨済宗寺院方丈で，室中を中心とした６間取平面の中心部を残す。改造により両側面広縁が撤去され，屋根も切妻造となるが，内法の低い内部など江戸初期の雰囲気をよく残す。木柄の太い大型の建物で，東方の庫裡とともに伽藍の中核を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003431"},{"id":"00004773","register_sub_id":"101","register_pk":"105763","name":"寂光院山門","kana":"じゃっこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.39622183,"lng":136.96227365,"geo_status":"db","era":"天保7","year":1836,"year_source":"db","year_min":1836,"year_max":1836,"year_label":null,"structure":"木造、瓦葺、間口2.2m、袖塀付","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0199","desc":"境内入口に建つ。形式は１間１戸薬医門で，二軒繁垂木，屋根は切妻造，本瓦葺である。組物は三斗で，妻は詰組，背面は中備に龍の彫物を入れる。妻飾は大瓶束で，両側には牡丹を彫った笈形をつける。木太いつくりで，虹梁・木鼻の絵様に時代の特徴がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004773"},{"id":"00004771","register_sub_id":"101","register_pk":"105761","name":"寂光院随求堂","kana":"じゃっこういんずいぐどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.39537404,"lng":136.96345738,"geo_status":"db","era":"文化2","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0197","desc":"本堂西に東面して建ち，渡廊下で結ばれる。桁行５間，梁間３間，一軒，入母屋造，桟瓦葺で，４周に擬宝珠高欄付の切目縁を廻す。軸部は角柱で床下部を高くつくり，縁を絵様付持送り板で受ける。側廻りに蔀戸を多用した住宅風の外観は籠堂の性質を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004771"},{"id":"00004772","register_sub_id":"101","register_pk":"105762","name":"寂光院弁天堂","kana":"じゃっこういんべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.39561562,"lng":136.96372042,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0198","desc":"本堂北方の高所にある。ほぼ正六角形の平面をもつ小堂で，前半を吹放しで板床張の見世棚風とし，中央境に格子戸を設け，後方を板壁で囲った内陣とする。柱や屋根を六角形につくり，天井の棹や垂木は放射状に配る。弁天像台座裏の墨書銘と同時期と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004772"},{"id":"00004770","register_sub_id":"101","register_pk":"105760","name":"寂光院本堂","kana":"じゃっこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字継鹿尾字杉ノ段12","lat":35.395348,"lng":136.963638,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡、渡廊付","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0196","desc":"桁行５間，梁間５間，寄棟造，正面１間向拝付，桟瓦葺で，４周に切目縁を廻す。前２間分を吹放しで小組格天井の外陣とし，後方の内陣には禅宗様須弥壇を構え，厨子を置く。軸部は円柱で，組物は出組とする。装飾を押さえた伝統的形式になる本格的な本堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004770"},{"id":"00004767","register_sub_id":"101","register_pk":"105757","name":"春江院庫裏","kana":"しゅんこういんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06213869,"lng":136.93414308,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積387㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0193","desc":"書院の北にある。南北棟の切妻造，桟瓦葺，２階建で，北面に下屋を降ろし，東面北寄に玄関を配する。北東隅の吹抜土間は豪放な梁組を現すが，１階・２階とも中廊下式とした近代的な平面構成で，洋風意匠の階段手摺子など，伝統の中に近代的要素が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004767"},{"id":"00004768","register_sub_id":"101","register_pk":"105758","name":"春江院山門","kana":"しゅんこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06272272,"lng":136.93446466,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0194","desc":"境内の北入口に北面して建つ。正面の控柱は後世の補強材で，形式は１間１戸薬医門で，二軒疎垂木，屋根は切妻造，本瓦葺である。組物は三斗と簡素であるが，妻飾には大柄の板蟇股を用い，意匠の要にする。虹梁・木鼻・蟇股の絵様には時代の特徴が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004768"},{"id":"00004769","register_sub_id":"101","register_pk":"105759","name":"春江院鐘楼","kana":"しゅんこういんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06221724,"lng":136.93432045,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造、瓦葺、建築面積22㎡","structure_material":"木造","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0195","desc":"本堂北にある。玉石で築いた基壇上に建ち，袴腰は簓子下見板張，縁には擬宝珠高欄を廻す。組物は出三斗の詰組であるが，壁付を横広がりとし，二軒扇垂木，入母屋造，桟瓦葺で，格天井の格間には彩色を施す。禅宗様意匠になる均整のとれた方１間の袴腰付鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004769"},{"id":"00004766","register_sub_id":"101","register_pk":"105756","name":"春江院茶室","kana":"しゅんこういんちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06189779,"lng":136.93401552,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺一部檜皮葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0192","desc":"書院の西にあり，尾州久田流茶道の開祖である下村實栗の作になる草庵風茶室。床を入れて４畳ほどと小規模だが，杉皮葺屋根は格子状に組んだ竹で押さえ，格子だけでなく，棹縁天井の棹や化粧屋根裏の垂木や木舞を竹とするなど，竹を多用した独特の構成になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004766"},{"id":"00004765","register_sub_id":"101","register_pk":"105755","name":"春江院不老閣","kana":"しゅんこういんふろうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06180438,"lng":136.9340138,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0191","desc":"書院の南西方にある切妻造，下屋庇付の平屋建で，外観は簡素な建物。内部は南に床付８畳の一の間，北に４畳半の二の間を配し，南と西に縁を廻す。磨き丸太の床柱，床脇の網代天井，丸垂木に木舞打とした縁の化粧屋根裏など，数寄屋の趣向が凝らされている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004765"},{"id":"00004764","register_sub_id":"101","register_pk":"105754","name":"春江院本玄関及び書院","kana":"しゅんこういんほんげんかんおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.06190821,"lng":136.93423421,"geo_status":"db","era":"江戸後期／明治12移築増改造","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0190","desc":"書院は本堂の西に建つ平屋建で，その間を本玄関が繋ぐ。本玄関は廊下と和室からなり，北面中央に式台を設ける。書院は床・棚・付書院のある１２畳間と床付の１８畳間からなり，Ｌ字型に広縁がつき，建具や欄間が繊細で，襖絵や板絵などもよく残る瀟洒な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004764"},{"id":"00004763","register_sub_id":"101","register_pk":"105753","name":"春江院本堂","kana":"しゅんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市緑区大高町字西向山5","lat":35.0618638,"lng":136.9343648,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積424㎡","structure_material":"木造平屋建","registered":"2005.07.12(平成17.07.12)","register_no":"23 － 0189","desc":"北を正面とする入母屋造，正面向拝付，本瓦葺の本堂。正面に広縁を設けた６間取平面で，北と東に切目縁を廻す。軸部は来迎柱を除いて角柱で，長押・貫で結ぶ。妻飾の虹梁・蟇股・懸魚などに江戸後期らしい装飾を施すが，簡明で端正な方丈形式のつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004763"},{"id":"00009303","register_sub_id":"101","register_pk":"194096","name":"祥雲寺弘法堂","kana":"しょううんじこうぼうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券5-1","lat":35.37901025,"lng":136.93839225,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0357","desc":"境内中央北寄りに南面する。桁行一四・二メートル梁間六メートル、入母屋造桟瓦葺で、正面に一間向拝を付ける。内部は東寄りに一〇畳三室を並べ落縁を廻らす。各室は格天井を張り、北奥に仏壇を備える。西端は物置とする。弘法大師を祀り大師堂ともよばれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009303"},{"id":"00009304","register_sub_id":"101","register_pk":"194097","name":"祥雲寺鐘楼","kana":"しょううんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券5-1","lat":35.37884274,"lng":136.9383775,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0358","desc":"弘法堂と参道を挟んで向き合う。方一間、袴腰付、入母屋造桟瓦葺である。玉石積の基壇上に建ち、擬宝珠高欄付縁を廻らし、上層は円柱を頭貫・台輪で固め、組物三斗、中備蟇股とし格天井を張る。装飾を抑えた端正なつくりの鐘楼で穏やかな境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009304"},{"id":"00009302","register_sub_id":"101","register_pk":"194095","name":"祥雲寺本堂","kana":"しょううんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券5-1","lat":35.37876184,"lng":136.93804152,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積263㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0356","desc":"境内奥に東面し、桁行一五・一メートル梁間一四・二メートル、入母屋造桟瓦葺。内部は方丈型六間取形式で正面に広縁を配し、内陣は来迎柱を立てて須弥壇をおき小組格天井を張る。二軒疎垂木の軒廻りや柱上の舟肘木がやや復古的な形式で穏やかな印象を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009302"},{"id":"00005189","register_sub_id":"101","register_pk":"106179","name":"浄照寺庫裏","kana":"じょうしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市若林西町向屋敷62","lat":35.031528,"lng":137.099701,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0211","desc":"本堂東にある。長大な平入建物で，屋根は切妻造段違，桟瓦葺である。正面の南面東端を玄関，その奥の土間は豪放な梁組を見せ，床上部は３室を２列に配する。軸部は差物を多用した堅固な構法である。墨書から年代と棟梁が明確で，この地域の庫裏の指標となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005189"},{"id":"00005190","register_sub_id":"101","register_pk":"106180","name":"浄照寺書院","kana":"じょうしょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県豊田市若林西町向屋敷62","lat":35.03176731,"lng":137.09959472,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0212","desc":"本堂の北方にある。東西棟の切妻造で，四面に下屋を廻し，桟瓦葺とする。平面は８畳２室と６畳２室を田の字形とし，四周を縁で囲む。規模が小さく，下見板張の外観は素朴であるが，良材を吟味して用い，繊細な板欄間など瀟洒な数寄屋風のつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005190"},{"id":"00005188","register_sub_id":"101","register_pk":"106178","name":"浄照寺本堂","kana":"じょうしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県豊田市若林西町向屋敷62","lat":35.03155817,"lng":137.09936117,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積480㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"23 － 0210","desc":"南東を向いて建つ。正側面ともに約２０ｍと規模が大きく，入母屋造，桟瓦葺，向拝付で，平面は吹放の縁，外陣，矢来と続き，内陣は本間とその両側の余間及び飛檐間からなり，後堂がつく。伝統的な形式を踏襲しつつ，絵様細部や彫物等に近代の造形が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005188"},{"id":"00006610","register_sub_id":"101","register_pk":"107593","name":"浄誓寺本堂","kana":"じょうせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字東古券256","lat":35.381672,"lng":136.941833,"geo_status":"db","era":"文化5／平成7改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積191㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0272","desc":"犬山城東南の寺内町に所在する。通りに北面する境内の中央に東面して建つ。入母屋造本瓦葺で、正面に１間向拝を設ける。堂内は外陣と矢来内、内陣からなり、内陣は後門形式となる。小組格天井を張り、龍などの豊かな彫刻が施される近世浄土真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006610"},{"id":"00006604","register_sub_id":"101","register_pk":"107587","name":"常満寺山門","kana":"じょうまんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券281","lat":35.38348552,"lng":136.937958,"geo_status":"db","era":"江戸末期／明治10移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0270","desc":"通りから西に入った位置に東面して建つ。犬山城松の丸裏門を移築した、切妻造桟瓦葺の１間薬医門。太い木柄で、組物はなく、軒は一軒疎垂木とする。装飾のない簡明な意匠ながら、豪放な気風を有しており、城門としての風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006604"},{"id":"00006605","register_sub_id":"101","register_pk":"107588","name":"常満寺鐘楼","kana":"じょうまんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券281","lat":35.38337552,"lng":136.9375191,"geo_status":"db","era":"寛政8","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0267","desc":"本堂の南方に東西棟で建つ。四周に縁を廻す方１間吹放ちの袴腰付鐘楼で、入母屋造桟瓦葺とする。方柱を頭貫と台輪で固め、三斗組とし、中備に蟇股を置く。軒は一軒疎垂木で、妻は木連格子とする。伸びやかな屋根勾配をもつ鐘楼で、境内景観を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006605"},{"id":"00012552","register_sub_id":"101","register_pk":"367847","name":"真宗大谷派名古屋別院東門及び土塀","kana":"しんしゅうおおたにはなごやべついんひがしもんおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区橘二丁目8-55","lat":35.151138,"lng":136.901276,"geo_status":"geocoded","era":"江戸後期／平成28年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"東門 木造、瓦葺、間口4.2m、左右袖塀及び北方潜戸付 土塀 土塀、瓦葺、総延長9.8m","structure_material":"東門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0523","desc":"市中心部にある境内東面に開く門と両脇に延びる土塀。切妻造本瓦葺の一間一戸高麗門で、本柱を木鼻付の楣で固め、3筋の腕木で軒桁を受ける。量感ある部材を用いて規模雄大につくり、大寺院の風格ある表構えを形成する。戦災を免れて市内に残る希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012552"},{"id":"00014026","register_sub_id":"101","register_pk":"508286","name":"瑞芳院本堂及び庫裡","kana":"ずいほういんほんどうおよびくり","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県一宮市中町一丁目4-1","lat":35.29513611,"lng":136.79879722,"geo_status":"db","era":"文化10年（1813）／大正4年移築","year":1813,"year_source":"db","year_min":1813,"year_max":1813,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"23 - 0563","desc":"濃尾地震被害からの復興に際し妙興寺から移築した方丈形式の本堂で、桁行北側に庫裏が連なる。切妻造桟瓦葺で妻飾りを木連格子と懸魚とし、四周に下屋を廻らす。内陣は小組格天井で正面に筬欄間を構えて須弥壇に花頭口を並べる。市街地に歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014026"},{"id":"00008127","register_sub_id":"101","register_pk":"132525","name":"瀬戸永泉教会礼拝堂","kana":"せとえいせんきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県瀬戸市杉塚町5","lat":35.22658164,"lng":137.10536807,"geo_status":"db","era":"明治33年／昭和5年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"23 － 0321","desc":"旧道南側の敷地に西面して建つ。桁行１１ｍ梁間７．４ｍの木造平屋建、切妻造桟瓦葺妻入とし、正面に玄関ポーチを付設。外装下見板張で、半円に近い尖塔アーチ形の上下窓や六角形の窓を配する。トラス組で真束の上下二ヶ所に貫を通す。小規模な教会堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008127"},{"id":"00012371","register_sub_id":"101","register_pk":"531695","name":"善行寺玄関座敷","kana":"ぜんぎょうじげんかんざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15540278,"lng":136.87452778,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-510","desc":"本堂の東に隣接する玄関座敷。八畳と六畳の座敷を並べ、前に本堂、後ろに庫裏とつなぐ廊下を配する。切妻造本瓦葺平入で、正面中央に間口二間幅で入母屋の式台玄関を構える。妻飾の木連格子や玄関両脇間の花頭窓など、格式ある表構えをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012371"},{"id":"00012375","register_sub_id":"101","register_pk":"531699","name":"善行寺山門","kana":"ぜんぎょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15506944,"lng":136.8744,"geo_status":"db","era":"宝暦5年(1755)／江戸後期・昭和53年改修","year":1755,"year_source":"db","year_min":1755,"year_max":1755,"year_label":null,"structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"23-514","desc":"境内の南面中央に開く切妻造の四脚門。組物は大斗絵様肘木、妻飾は虹梁大瓶束、軒は一軒疎垂木である。親柱筋の冠木と棟木の間には虹梁を入れ、中備に滝と波を模した躍動感あふれる彫刻の蟇股を入れて意匠を凝らす。境内正面の構えを華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012375"},{"id":"00012372","register_sub_id":"101","register_pk":"531696","name":"善行寺鐘楼","kana":"ぜんぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15515833,"lng":136.87428333,"geo_status":"db","era":"明治29年頃／昭和53年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、面積7.6㎡","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"23-511","desc":"本堂の南西方に位置し、高い乱石積基壇に建つ。方一間、吹放ち形式で、南北棟の入母屋造本瓦葺とする。粽付円柱を貫で固めて台輪を載せ、組物は木鼻付出組の詰組、天井は小組格天井、二軒扇垂木である。均整のとれた禅宗様の鐘楼で、細部意匠も良質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012372"},{"id":"00012373","register_sub_id":"101","register_pk":"531697","name":"善行寺太鼓楼","kana":"ぜんぎょうじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15513056,"lng":136.8745,"geo_status":"db","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋一部3階建、瓦葺、建築面積50㎡","structure_material":"木造平屋一部3階建","registered":"2018.05.10(平成30.05.10)","register_no":"23-512","desc":"山門の北東方に建つ。東西棟の切妻造で、屋根中央西寄りに方一間宝形造の楼を載せ、四周に下屋を廻らす。内部は後世に居室化されているが、もと納屋で、西半には中二階や楼への上り口が残る。浄土真宗寺院の伽藍構成を特徴づける太鼓楼として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012373"},{"id":"00012374","register_sub_id":"101","register_pk":"531698","name":"善行寺手水舎","kana":"ぜんぎょうじちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15510833,"lng":136.87434722,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、面積4.5㎡、手水鉢付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"23-513","desc":"山門の北西方に建つ。桁行二・四メートル梁間一・八メートルで、南北棟の切妻造桟瓦葺。角柱を四方転びに立て、内法貫で固め、組物をつくらず、柱頂部で直接桁を受ける。軒は一軒疎垂木である。極めて簡素なつくりの手水舎で、境内に欠かせない構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012374"},{"id":"00012370","register_sub_id":"101","register_pk":"531694","name":"善行寺本堂","kana":"ぜんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中川区愛知町4132","lat":35.15536111,"lng":136.87436667,"geo_status":"db","era":"宝永3年(1706)／文化元年(1804)・昭和51年改修、大正4年増築","year":1706,"year_source":"db","year_min":1706,"year_max":1706,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積277㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"23-509","desc":"桁行五間梁間五間、入母屋造本瓦葺、向拝一間付の真宗本堂で南面して建つ。内部は外陣の柱を省略し、矢来内にかけて一面に小組格天井を張る。背面の御成りの間は近代の増築。尾張藩の御大工･伊藤平左衛門の手により、虹梁や組物など細部の造作が充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012370"},{"id":"00006495","register_sub_id":"101","register_pk":"107478","name":"専念寺庫裏","kana":"せんねんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券262","lat":35.382847,"lng":136.937744,"geo_status":"db","era":"元禄2／平成16改修","year":1689,"year_source":"db","year_min":1689,"year_max":1689,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積216㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0263","desc":"本堂の東に南面して建つ。桁行２１ｍ梁間１１ｍの規模で、切妻造妻入桟瓦葺とする。正面側に土間などを配し、後寄りの床上部は縦に２分する。西側の座敷はトコなどを設ける接客用で、東側は内向の居室とする。江戸中期に遡る庫裏として注目される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006495"},{"id":"00006338","register_sub_id":"101","register_pk":"107321","name":"専念寺本堂","kana":"せんねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字西古券262","lat":35.38289924,"lng":136.93750309,"geo_status":"db","era":"寛文13／平成16改修","year":1673,"year_source":"db","year_min":1673,"year_max":1673,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積228㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"23 － 0262","desc":"境内の北奥に南面して建つ。入母屋造桟瓦葺の７間堂で、正面に１間向拝を付ける。正面１間通りの広縁と、その奥の外陣、そして内陣、脇間からなる浄土宗寺院本堂の特徴的平面となる。内陣まわりの中敷居痕跡や、来迎柱組物絵様など古式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006338"},{"id":"00010789","register_sub_id":"101","register_pk":"201624","name":"善立寺玄関","kana":"ぜんりゅうじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956417,"lng":137.170418,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0432","desc":"本堂の東に接続して建つ。座敷三室に一列を並べ、南北西の三方に縁をまわして、本堂と庫裏を繋ぐ。南面中央には唐破風玄関を張出す。南面廊下を含め、各室は棹縁天井とし、玄関は格天井とする。全体に簡明な中で、玄関廻りの格式を高め、正面構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010789"},{"id":"00010790","register_sub_id":"101","register_pk":"201625","name":"善立寺山門","kana":"ぜんりゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956329,"lng":137.170057,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0433","desc":"境内の西南隅に建つ。間口三・二メートルの高麗門で、冠木上の小壁の建ちが低く、本屋根と控柱上の軒を同高に納める。門扉は下部を銅板張の板壁とし、上部を金剛柵状の格子とする。城門を思わせる古式な姿形を見せ、境内の表構えに重厚な趣を与えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010790"},{"id":"00010788","register_sub_id":"101","register_pk":"201623","name":"善立寺七面堂","kana":"ぜんりゅうじしちめんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956548,"lng":137.170154,"geo_status":"db","era":"江戸後期／明治後期・昭和44改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0431","desc":"本堂の西に建つ、間口二間半、奥行六間、入母屋造妻入の奥に深い堂で、正面に一間向拝を付す。中古に本堂へと繋がる東側の室を拡張している。内陣まわりの来迎柱上には出組を載せ、極彩色を施して荘厳する。江戸後期における七面大明神信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010788"},{"id":"00010787","register_sub_id":"101","register_pk":"201622","name":"善立寺本堂","kana":"ぜんりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県岡崎市祐金町一丁目31","lat":34.956526,"lng":137.170304,"geo_status":"db","era":"享保19／昭和5・同中期改修","year":1734,"year_source":"db","year_min":1734,"year_max":1734,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0430","desc":"境内に南面して建ち、桁行六間梁間七間、正面一間向拝付、左に七面堂、右に玄関が接続する。平面は正面を広縁、奥を内陣と両脇陣に分け、日蓮宗本堂の特徴を示す。来迎柱のみ円柱として禅宗様須弥壇を置き、上方を極彩色で飾る。内陣の装飾密度を高めた本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010787"},{"id":"00010785","register_sub_id":"101","register_pk":"201620","name":"崇覚寺本堂","kana":"そうがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市中区橘二丁目601","lat":35.152626,"lng":136.900608,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積323㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0428","desc":"名古屋市街地に境内を構える真宗寺院本堂。標準的な真宗本堂平面で外陣内の柱を省き、比較的規模が大きい。絵様は明瞭かつ伸びやかで、棟梁の八代伊藤平左衛門守富の特徴を示す。架構なども規式に則りながら、小組格天井を全面的に張るなど闊達な造形を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010785"},{"id":"00009771","register_sub_id":"101","register_pk":"195600","name":"瀧神社本殿","kana":"たきじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市大海字宮ノ前1","lat":34.93855734,"lng":137.54966019,"geo_status":"db","era":"寛文12","year":1672,"year_source":"db","year_min":1672,"year_max":1672,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0392","desc":"覆屋内に納まる一間社流造、こけら葺の社殿で、三方に縁を廻し、正面に木階五級を付す。頭貫には大振りな木鼻を付け、三斗実肘木で桁を受ける。妻飾は虹梁大瓶束。水引虹梁上の中備に透蟇股を備える。海老虹梁の絵様等、細部意匠も時代相応のもので、質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009771"},{"id":"00005078","register_sub_id":"101","register_pk":"106068","name":"長母寺庫裡","kana":"ちょうぼじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市東区矢田町字寺畑2161","lat":35.19693,"lng":136.945145,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積361㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0037","desc":"本堂の東側に建ち，本堂とは廊下および客間と接続し，北西隅に茶室が繋がっている。切妻造・妻入・桟瓦葺で，桁行９間梁間５間の雄大な規模をもち，内部の梁組も重厚である。棟札より大工棟梁は川合半七で，建築年代が明確な庫裡として貴重な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005078"},{"id":"00001418","register_sub_id":"101","register_pk":"102408","name":"長母寺山門","kana":"ちょうぼじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市東区矢田町字寺畑2161","lat":35.196396,"lng":136.944824,"geo_status":"db","era":"18世紀後半","year":1795,"year_source":"estimated","year_min":1751,"year_max":1800,"year_label":"18世紀後半","structure":"木造薬医門、瓦葺、間口4.8m、奥行き1.7m","structure_material":"木造薬医門","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0038","desc":"３間１戸の薬医門で，切妻造・本瓦葺，桁行約４．８ｍと規模も大きい。主柱は五平とし，棟木を板蟇股と蓑束で受け，細部絵様から１８世紀後半と推定される。低い基壇上に建ち，両側に鍵形の築地塀を備えた姿は，地域の景観に欠かせないものとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001418"},{"id":"00001417","register_sub_id":"101","register_pk":"102407","name":"長母寺本堂","kana":"ちょうぼじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市東区矢田町字寺畑2161","lat":35.19698072,"lng":136.94493814,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積202㎡","structure_material":"木造平屋建","registered":"1999.11.18(平成11.11.18)","register_no":"23 － 0036","desc":"長母寺は平安末期の創建で，鎌倉中期に臨済宗に改宗し，現在に至っている。無住和尚の説教に発するという「尾張万歳」発祥の地として広く知られている。本堂は方丈形式の建物で，濃尾大地震後の再建であるが，由緒ある寺院の中心建築として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001417"},{"id":"00009971","register_sub_id":"101","register_pk":"196118","name":"知立神社祭文殿及び廻廊","kana":"ちりゅうじんじゃさいもんでんおよびかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01313077,"lng":137.04111012,"geo_status":"db","era":"明治20／大正期・昭和29改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0398","desc":"幣殿と拝殿の間に建つ。中央に四脚門形式で切妻造の祭文殿を構え、左右の廻廊は棟を落としてのばす。また祭文殿の前後に幣殿と拝殿へ両下造の渡りを設け、屋根は総檜皮葺とする。左右対称平面で両翼の廻廊は複廊とし、軸部木太く重厚感のある社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009971"},{"id":"00009972","register_sub_id":"101","register_pk":"196119","name":"知立神社摂社親母神社","kana":"ちりゅうじんじゃせっしゃうばがみしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01305702,"lng":137.04128997,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、檜皮葺、建築面積8.5㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0399","desc":"拝殿の東方に南面して建つ、一間社流造、檜皮葺である。正側面三方に縁を廻らし、軒は二軒繁垂木とする。柱頂を木鼻付の頭貫で固め、実肘木付の三斗を組む。妻飾は虹梁大瓶束とし、束上に三斗を置く。摂社としては規模が大きく、本格的な形式となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009972"},{"id":"00009973","register_sub_id":"101","register_pk":"196120","name":"知立神社茶室","kana":"ちりゅうじんじゃちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01277067,"lng":137.0406301,"geo_status":"db","era":"明治期／昭和43移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0400","desc":"桁行三間半梁間二間半、東西棟の入母屋造桟瓦葺で、東に玄関を設ける。西側の四畳半茶室と三畳の水屋は懸造風に縁を廻らす。茶室は、面皮柱を使い、トコ柱の背側にナンテンの曲材を組込むなど、数寄屋を加味した開放的な構成になる。社叢景観に趣を添える茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009973"},{"id":"00009970","register_sub_id":"101","register_pk":"196117","name":"知立神社拝殿","kana":"ちりゅうじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01298053,"lng":137.04113644,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0397","desc":"桁行六間梁間三間、切妻造妻入、檜皮葺で、間口一間、切妻造の向拝を設けて屋根を重ね、正面性を強調する。平面は前方二間分を土間として奥を板敷とする。縦長に配置され、後方の祭文殿や廻廊とともに、尾張造と呼ばれる社殿配置の三河地方への伝播を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009970"},{"id":"00009969","register_sub_id":"101","register_pk":"196116","name":"知立神社幣殿","kana":"ちりゅうじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01322617,"lng":137.04110417,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺、建築面積50㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0396","desc":"桁行五間梁間三間、切妻造妻入で、檜皮葺とする。組物を持たず、両妻は二重梁を束で支えて化粧棟木を受け、破風の拝みに猪目懸魚を吊る。内部は板敷の一室で、棹縁天井を張り、長押等に釘隠を打ち、本殿への礼拝空間を整える。簡素な意匠になる幣殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009969"},{"id":"00009968","register_sub_id":"101","register_pk":"196115","name":"知立神社本殿","kana":"ちりゅうじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市西町神田12","lat":35.01334778,"lng":137.0410692,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"23 － 0395","desc":"東海道池鯉鮒宿の傍らに位置する。三間社流造、檜皮葺で、正面に板唐戸をたてた身舎内部を前後二室に仕切り、庇部分は左右を板壁として前室状とする。正側面に刎高欄付の縁を付ける。妻飾は虹梁大瓶束形式で、出組で一手持ち出す。規模充実し質も高い本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009968"},{"id":"00013556","register_sub_id":"101","register_pk":"504923","name":"徳雲寺弁天堂","kana":"とくうんじべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県西尾市吉良町吉田八ツ田45","lat":34.79453056,"lng":137.06547222,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積6.3㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"23 － 0559","desc":"本堂東方の基壇上に南面して構え、池の端に建つ。屋根は妻入で、正面入母屋造、背面切妻造とする。規模は正面一間、背側面二間で、奥に仏壇を構えて弁財天を祀る。外壁は下見板張とし正面のみ簓子を付ける。小規模な堂ながら気品を備え、篤い信仰を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013556"},{"id":"00013555","register_sub_id":"101","register_pk":"504922","name":"徳雲寺本堂","kana":"とくうんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県西尾市吉良町吉田伝蔵荒子19","lat":34.79461389,"lng":137.06517778,"geo_status":"db","era":"明治16年","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"23 － 0558","desc":"布施行者で知られる尼僧颯田本真が開いた、三河湾干拓地に寺地を構える浄土宗寺院。本堂は東面して建ち、北に玄関棟を付す。正面三間側面八間の奥行の深い寄棟造妻入の堂で、四天柱のほかは角柱を用いる。装飾を抑えた素朴な外観で念仏道場の趣を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013555"},{"id":"00009293","register_sub_id":"101","register_pk":"194086","name":"徳授寺位牌堂","kana":"とくじゅじいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37781148,"lng":136.93986466,"geo_status":"db","era":"昭和9年／平成18年改修","year":1834,"year_source":"db","year_min":1834,"year_max":1834,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0347","desc":"本堂背面に接続し南北棟で建つ。桁行一二・二メートル梁間五・七メートル、入母屋造及び切妻造桟瓦葺で、内部は南半を位牌堂、北半を開山堂とする。玉石積基礎に建ち、外観は漆喰塗で腰に竪板を張り、開山堂の左右に花頭窓を穿つ。境内景観を構成する位牌堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009293"},{"id":"00009294","register_sub_id":"101","register_pk":"194087","name":"徳授寺玄関","kana":"とくじゅじげんかん","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37755069,"lng":136.93994746,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0348","desc":"本堂東側の庫裏に渡る廊下南面に構える玄関。間口三・八メートル奥行二・七メートル、向唐破風造桟瓦葺である。正面の頭貫と虹梁の間に龍彫刻を飾り、虹梁上の大瓶束には波に菊を表した華やかな笈形を付す。唐破風に吊る鳳凰の兎毛通しとともに見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009294"},{"id":"00009296","register_sub_id":"101","register_pk":"194089","name":"徳授寺山門","kana":"とくじゅじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37705767,"lng":136.93961958,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0350","desc":"境内入口に南北棟で建つ。桁行二・八メートル梁間一・八メートル、切妻造桟瓦葺の薬医門形式で、左右に長さ一・一メートルの袖塀を付し、木部全体を赤色に塗る。古刹の正門に相応しい大型の薬医門で、女梁の絵様や反りの強い垂木形状には古式が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009296"},{"id":"00009295","register_sub_id":"101","register_pk":"194088","name":"徳授寺鐘楼","kana":"とくじゅじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37733559,"lng":136.9399646,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0349","desc":"境内の南東側に建つ鐘楼で、方一間、袴腰付、入母屋造桟瓦葺である。亀甲石積の基壇上に建ち、腰組は二手先で擬宝珠高欄付縁を支持し、上層も二手先組物で小組格天井を張り、軒は二軒繁垂木である。丁寧なつくりの鐘楼で、境内景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009295"},{"id":"00009292","register_sub_id":"101","register_pk":"194085","name":"徳授寺本堂","kana":"とくじゅじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市大字犬山字南古券232","lat":35.37765348,"lng":136.93982659,"geo_status":"db","era":"明治29年／平成18年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積235㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0346","desc":"境内奥に南面し、桁行一五・一メートル梁間一四・二メートル、入母屋造桟瓦葺である。内部は方丈型六間取形式で正面に広縁を配し、内陣は来迎壁を設けて須弥壇をおき、小組格天井を張る。外陣は室境の柱を省き、欄間は竹の節欄間として広闊な外陣空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009292"},{"id":"00010606","register_sub_id":"101","register_pk":"201180","name":"名古屋カテドラル聖ペトロ聖パウロ大聖堂","kana":"なごやかてどらるせいぺとろせいぱうろだいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市東区葵1-1208","lat":35.17275,"lng":136.923908,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋一部2階地下1階建、銅板葺、建築面積928㎡、搭屋及び階段付","structure_material":"鉄骨鉄筋コンクリート造平屋一部2階地下1階建","registered":"2015.08.04(平成27.08.04)","register_no":"23－0423","desc":"市街地に建つ鉄骨鉄筋コンクリート造の教会堂。ゴシック様式基調で外壁をコンクリート打ち放しとし、双塔に透模様の尖塔を戴く。柱通りの内部に尖頭アーチを架け、外部にバットレスを付して高大な無柱空間を創出し、小屋を現した天井とともに昇高性を強調する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010606"},{"id":"00012553","register_sub_id":"101","register_pk":"367848","name":"七所神社本殿","kana":"ななしょじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県名古屋市南区笠寺町字天満12","lat":35.095226,"lng":136.934906,"geo_status":"geocoded","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、檜皮葺、建築面積4.0㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"23 － 0524","desc":"市南部に鎮座し、本殿は境内のほぼ中央に南面して建つ。一間社流造、檜皮葺で、正側面に切目縁を廻して脇障子を立て、正面に木階と浜縁を設ける。三斗の上に肘木を重ねて五斗を並べた組物や波形彫刻の蟇股の正面中備など、小社ながら細部を丁寧につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012553"},{"id":"00014840","register_sub_id":"101","register_pk":"519100","name":"鳴海杻神社祭文殿","kana":"なるみてがしじんじゃさいもんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.34748889,"lng":136.94257778,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0594","desc":"本殿と拝殿間に位置。桁行五間梁間一間切妻造妻入正面向拝一間付の細長い南北棟の前面両脇に棟を直交し桁行三間梁間一間半入母屋造の東西棟を付す。総桟瓦葺。内部は一室の板敷で本殿に向かって床を上げ鏡天井を高く張る。変化のある屋根で社頭景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014840"},{"id":"00014842","register_sub_id":"101","register_pk":"519102","name":"鳴海杻神社社務所","kana":"なるみてがしじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.34699167,"lng":136.94269722,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0596","desc":"境内南東、参道入口の東に位置。平屋建入母屋造平入桟瓦葺、西正面中央に切妻造玄関を付す。正面に廊下を通し、北に床付８畳座敷と６畳次の間を配する。南は廊下を挟んで６畳社務所、台所を東西に並べる。簡素な意匠ながら、境内入口脇の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014842"},{"id":"00014841","register_sub_id":"101","register_pk":"519101","name":"鳴海杻神社拝殿","kana":"なるみてがしじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.34736389,"lng":136.94256389,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0595","desc":"祭文殿前方に位置。桁行三間梁間三間入母屋造桟瓦葺。円柱を地覆、地長押、内法長押、頭貫で固める。組物は台輪上に出三斗とし、軒は２軒繁垂木。内部は一室の板敷で天井は小組格天井を張る。四周を吹放ちとした軽快な建物ながら基壇上に建つ堂々たる拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014841"},{"id":"00014844","register_sub_id":"101","register_pk":"519104","name":"鳴海杻神社藩塀","kana":"なるみてがしじんじゃばんぺい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109-1","lat":35.34723889,"lng":136.94255278,"geo_status":"db","era":"大正6年頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、銅板葺、延長3.3m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0598","desc":"拝殿と南前方の鳥居間に位置。柱間３間切妻造銅板葺の障壁。両端の円柱は前後の角柱の控柱と貫二段で繋ぐ。柱上部に腕木２段を重ね軒桁を受け、軒は一軒繁垂木。腰長押、内法長押間は連子窓とし腰は縦板張。尾張独特の目隠塀で境内景観のアクセントとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014844"},{"id":"00014843","register_sub_id":"101","register_pk":"519103","name":"鳴海杻神社弁天堂","kana":"なるみてがしじんじゃべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.3469,"lng":136.942475,"geo_status":"db","era":"元治2年(1865)","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0597","desc":"参道入口の西の湧水池東岸に位置。正面３間側面２間半宝形造桟瓦葺で正面に向拝一間、三方に縁を付す。内部は八畳の１室で、格天井の鏡板に絵画を描く。背面は三分して、中央に金箔貼の宮殿を安置する。境内最古の堂宇で湧水池に浮かぶ点景をつくる弁天堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014843"},{"id":"00014839","register_sub_id":"101","register_pk":"519099","name":"鳴海杻神社本殿","kana":"なるみてがしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県犬山市大字羽黒字成海郷109","lat":35.347575,"lng":136.94259167,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"23 - 0593","desc":"五条川南岸に位置する式内社。１間社入母屋造檜皮葺（銅板仮葺）。正面に千鳥破風、向拝に軒唐破風を付す複雑な屋根構成。組物は出組で腰組は三手先。正面両折桟唐戸に桐紋を付す。脇障子、海老虹梁、蟇股、木鼻、懸魚など随所に彫刻を施す、意匠優秀な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014839"},{"id":"00009761","register_sub_id":"101","register_pk":"195590","name":"日本福音ルーテル岡崎教会教会堂","kana":"にほんふくいんるーてるおかざききょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県岡崎市伝馬通4-54","lat":34.95740632,"lng":137.1726235,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積137㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0382","desc":"木造平屋建で北面し、切妻造妻入、桟瓦葺で、正面玄関に庇を付け、棟上に尖塔を立てて十字架を戴く。内部は三廊式で身廊にキングポストトラスを架け、側廊は間仕切により小部屋に分割できるよう工夫される。白壁と赤屋根のコントラストが映える教会建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009761"},{"id":"00009291","register_sub_id":"101","register_pk":"194084","name":"日本福音ルーテル復活教会","kana":"にほんふくいんるーてるふっかつきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県名古屋市東区徳川町2303","lat":35.1861601,"lng":136.93213476,"geo_status":"db","era":"昭和28年／昭和35年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋一部2階建、スレート葺、建築面積177㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2012.08.13(平成24.08.13)","register_no":"23 － 0345","desc":"木造平屋建、建築面積一七七平方メートル、切妻造スレート葺。南面中央の二階建玄関部に尖塔を建てる。外壁は腰を下見板張、上部をモルタル塗とする。単廊上部にはシザース・トラスの小屋組を見せ、西側内陣上部は十字架形の窓で飾る。明快な意匠の小会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009291"},{"id":"00009464","register_sub_id":"101","register_pk":"194257","name":"如意寺山門","kana":"にょいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.14128821,"lng":137.22627014,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0362","desc":"境内東辺の本堂正面に開く四脚門で、切妻造桟瓦葺。門柱は沓石に立つ円柱で両開の桟唐戸を吊る。控柱は角柱。組物は出三斗とし、中備は冠木上に平三斗、控柱の虹梁上に蟇股とする。妻飾は大瓶束笈形付き。軒は二軒繁垂木とする。内部は小組格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009464"},{"id":"00009463","register_sub_id":"101","register_pk":"194256","name":"如意寺書院","kana":"にょいじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.141544,"lng":137.22560151,"geo_status":"db","era":"江戸後期／明治42年増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積184㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0361","desc":"本堂の北に位置する木造平家建、切妻造桟瓦葺。現本堂造営時の仮堂として建設したと伝える。西から上段の間九畳、中の間一二畳、広間一八畳が並び、南から東へ広縁を廻らす。後に北広縁を半間拡幅して西寄りに二室を設け、北西に湯殿と便所を増築している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009463"},{"id":"00009465","register_sub_id":"101","register_pk":"194258","name":"如意寺鐘楼","kana":"にょいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.1411502,"lng":137.22617615,"geo_status":"db","era":"宝暦5年頃","year":1755,"year_source":"db","year_min":1755,"year_max":1755,"year_label":null,"structure":"木造、瓦葺、面積8.8㎡","structure_material":"木造","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0363","desc":"境内南寄り、石積基壇上に建つ入母屋造桟瓦葺。沓石に内転び角柱を立て、腰貫、飛貫、頭貫で固め、台輪を廻らす。組物は出三斗、中備は蟇股。妻飾は虹梁大瓶束。軒は二軒繁垂木。内部は四辺中央から出した腕木上に菱形枠の鏡天井を張り、周囲は格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009465"},{"id":"00009466","register_sub_id":"101","register_pk":"194259","name":"如意寺太鼓楼","kana":"にょいじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.14138814,"lng":137.22617496,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0364","desc":"山門の北西に位置する木造平家建、入母屋造桟瓦葺。屋根中央に棟の向きを違えた入母屋造桟瓦葺の太鼓櫓を載せる。外壁は鉄板張に改修。内部は西側二間半を茶所、東側二間を物置に間仕切る。太鼓櫓外壁は押縁下見板張で、四周を無双窓とする。軒は一軒疎垂木。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009466"},{"id":"00009462","register_sub_id":"101","register_pk":"194255","name":"如意寺本堂","kana":"にょいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊田市力石町黒見175","lat":35.14125133,"lng":137.22568598,"geo_status":"db","era":"文政6年","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積474㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"23 － 0360","desc":"正面七間の真宗本堂で、入母屋造桟瓦葺、三間幅の向拝がつく。妻飾は二重虹梁大瓶束。外部組物は出三斗で中備を略す。正面から両側面へ廻る広縁と落縁は表から三間位置で止め、飛檐の間との間を板間とする。外陣と矢来内は格天井、内陣は折上格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009462"},{"id":"00010171","register_sub_id":"101","register_pk":"198004","name":"八所神社拝殿","kana":"はっしょじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山2","lat":34.875114,"lng":137.356704,"geo_status":"db","era":"文政9","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0419","desc":"桁行三間梁間二間、入母屋造桟瓦葺。柱頭に頭貫木鼻を付け、三斗に拳鼻と実肘木を組み、中備に蟇股を置く。正背面の中央間を広めて開口部とし、正面両脇間に窓を設ける他は横板壁とする。内部は拭板敷で棹縁天井とする。本殿とともに神仏習合の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010171"},{"id":"00010170","register_sub_id":"101","register_pk":"198003","name":"八所神社本殿","kana":"はっしょじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊川市財賀町観音山2","lat":34.875217,"lng":137.356704,"geo_status":"db","era":"享保9","year":1724,"year_source":"db","year_min":1724,"year_max":1724,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積0.8㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0418","desc":"財賀寺本堂後方の石段上に境内を開く。一間社流造、こけら葺の社殿で、基壇上に建つ。正面二軒、背面一軒の繁垂木とする。妻飾は虹梁大瓶束笈形付とし、束上に大斗と実肘木を置いて化粧棟木を受ける。規模は小さく簡素ながら、江戸時代中期の姿をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010170"},{"id":"00015461","register_sub_id":"101","register_pk":"533476","name":"普門寺十王堂","kana":"ふもんじじゅうおうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74428611,"lng":137.47270278,"geo_status":"db","era":"嘉永5年（1852）／昭和63年頃・平成3年改修","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0613","desc":"本堂の南東、参道に東面して建つ小堂。桁行３間梁間３間、片入母屋造妻入桟瓦葺で、軒は一軒疎垂木、妻飾は虹梁大瓶束とする。堂内は内外陣からなり、外陣北端を格子戸で仕切り、各室板敷で竿縁天井とする。簡素ながら参道に妻飾をみせ境内景観をつくる仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015461"},{"id":"00015462","register_sub_id":"101","register_pk":"533477","name":"普門寺鐘楼門","kana":"ふもんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.744925,"lng":137.47270278,"geo_status":"db","era":"宝永4年（1707）／昭和28年・平成11年改修","year":1707,"year_source":"db","year_min":1707,"year_max":1707,"year_label":null,"structure":"木造2階建、銅板葺、建築面積15㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0614","desc":"境内中央、本坊の前に南面して建つ一間一戸の楼門。上層は桁行３間、梁間３間、入母屋造銅板葺、組物は出組で絵様肘木とし、軒は二軒繁垂木。内部は一室の板敷で、竿縁天井を張り、中央に鐘を吊る。軒出が大きく雄大な姿の鐘楼門で境内の主要な構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015462"},{"id":"00015459","register_sub_id":"101","register_pk":"533474","name":"普門寺大師堂","kana":"ふもんじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74551667,"lng":137.47179444,"geo_status":"db","era":"嘉永7年（1854）／平成2年改修","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0611","desc":"本堂の北に東面して建つ大師堂。宝形造銅板葺の三間堂で正面に一間向拝を付し、三方に縁を廻らす。組物は平三斗で軒は二軒繁垂木。内部は一室で中央後方に来迎柱を立てて須弥壇を配す。天井は格天井で格間に植物を極彩色で描く。軒出大きく軽快な姿の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015459"},{"id":"00015463","register_sub_id":"101","register_pk":"533478","name":"普門寺仁王門","kana":"ふもんじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74408611,"lng":137.47275,"geo_status":"db","era":"江戸中期／平成8年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0615","desc":"境内入口に南面して建つ仁王門。寄棟造銅板葺の八脚門で、組物は二手先、軒は二軒繁垂木。中央間は通路で扉を吊らず、虹梁形内法貫上に彫刻付蟇股を飾る。両脇間の後方に金剛柵と横連子を付し、仁王像一対を安置する。彫刻など細部意匠も端正で上質な八脚門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015463"},{"id":"00015460","register_sub_id":"101","register_pk":"533475","name":"普門寺弁天堂（旧龍神宮）","kana":"ふもんじべんてんどう（きゅうりゅうじんぐう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74561389,"lng":137.47182778,"geo_status":"db","era":"正徳4年（1714）／宝暦5年（1755）・安政3年（1856）移築、平成11年改修","year":1714,"year_source":"db","year_min":1714,"year_max":1714,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0612","desc":"大師堂北の池に東面し、覆屋内に建つ小社。入母屋造杮葺の一間社で正面に千鳥破風を飾り向拝を付す。身舎の組物は出組、軒は二軒繁垂木とし頭貫木鼻に鶏の頭形を飾る。向拝は虹梁形頭貫を龍2頭の尾を絡めて火灯形とするなど、独創的な意匠で装飾豊富な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015460"},{"id":"00015458","register_sub_id":"101","register_pk":"533473","name":"普門寺本堂","kana":"ふもんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県豊橋市雲谷町字ナベ山下7","lat":34.74537778,"lng":137.47171389,"geo_status":"db","era":"元禄6年（1693）／昭和31年・平成11年改修","year":1693,"year_source":"db","year_min":1693,"year_max":1693,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"23 - 0610","desc":"船形山南東斜面に位置する真言宗寺院本堂。境内西側に東面して建つ寄棟造銅板葺の五間堂。前方2間を外陣、後方2間を内陣、背面1間を後陣とし、内陣後方に須弥壇を配す。外陣は桁行３間の虹梁形頭貫を架け、海老虹梁で側柱と繋ぐ架構などに地域的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015458"},{"id":"00008492","register_sub_id":"101","register_pk":"134888","name":"報光寺本堂","kana":"ほうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県江南市古知野町本郷114","lat":35.33806789,"lng":136.87065405,"geo_status":"db","era":"安政2年(1855）／昭和35年改修","year":1855,"year_source":"db","year_min":1855,"year_max":1855,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積576㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"23 － 0329","desc":"境内の西南寄りに東面して建つ。桁行二二メートル梁間二六メートル、入母屋造本瓦葺、向拝三間を付ける。大間と外陣、内陣及び余間からなり、周囲一間通りを入側とし、外陣に面した正・側面を吹き放つ。総円柱で、三斗組とするなど本格的仕様になる大型真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008492"},{"id":"00011968","register_sub_id":"101","register_pk":"211106","name":"宝珠院書院","kana":"ほうしゅいんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"愛知県","address":"愛知県西尾市吉良町吉田石池18","lat":34.796049,"lng":137.069196,"geo_status":"db","era":"昭和4年／昭和後期改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-507","desc":"本堂北東に縁で接続する。東西棟の寄棟造、桟瓦葺で、上ノ間と次ノ間からなり、四周に広縁を廻らす。上ノ間は、三畳の大床と、一畳の踏込をもつ床脇を備え、いずれも格天井を張る壮大な造り。付書院も備え、格式ある近代和風の書院建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011968"},{"id":"00011969","register_sub_id":"101","register_pk":"211107","name":"宝珠院忠魂堂","kana":"ほうしゅいんちゅうこんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県西尾市吉良町吉田石池18","lat":34.795893,"lng":137.068828,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-508","desc":"本堂の南西に東面する戦没者慰霊のために建てられた一間堂。宝形造、桟瓦葺で一間向拝を付ける。内部は六畳の奥に厨子を安置し、格天井を張り荘厳する。向拝廻りでは、中備蟇股や手挟の彫刻に日章旗を施すなど時代性を反映した意匠が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011969"},{"id":"00011967","register_sub_id":"101","register_pk":"211105","name":"宝珠院本堂","kana":"ほうしゅいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県西尾市吉良町吉田石池18","lat":34.796027,"lng":137.068983,"geo_status":"db","era":"延宝3年（1675）／安永9年（1780）、昭和後期改修","year":1675,"year_source":"db","year_min":1675,"year_max":1675,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"23-506","desc":"境内北西方に南面する。入母屋造、桟瓦葺の七間堂で、背面に後堂を張り出す。側廻りは柱上に組物を置かず直接軒桁を載せるのに対し、内陣廻りは粽付円柱に台輪を廻らして出組とし、中備蟇股や欄間を彫刻で荘厳する。江戸中期の浄土宗寺院本堂の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011967"},{"id":"00006500","register_sub_id":"101","register_pk":"107483","name":"本光寺山門","kana":"ほんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県岡崎市上青野町字新井1","lat":34.922127,"lng":137.123184,"geo_status":"db","era":"文政10","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造楼門、瓦葺、建築面積25㎡、左右潜戸及び袖塀付","structure_material":"木造楼門","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0250","desc":"本堂の東、通りに面して建つ。入母屋造桟瓦葺の３間１戸楼門。下層の側まわりは開放とし、上層は正・背面中央に桟唐戸を建て、他を格子を嵌めた板壁とする。組物は出組詰組。内部に釈迦如来など三尊を安置。標準的な楼門で、手堅い意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006500"},{"id":"00006499","register_sub_id":"101","register_pk":"107482","name":"本光寺本堂","kana":"ほんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"愛知県","address":"愛知県岡崎市上青野町字新井1","lat":34.922115,"lng":137.122726,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積502㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0249","desc":"境内中央の後方に東面して建つ。入母屋造桟瓦葺で、３間向拝を正面に付ける。典型的な浄土真宗平面で、三方に広縁と落縁を廻し、内陣は後門形式とする。内陣まわりを黒漆地に金箔張の彫刻や絵様で荘厳しており、近代らしい装飾意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006499"},{"id":"00011513","register_sub_id":"101","register_pk":"210541","name":"梵音寺本堂","kana":"ぼんのんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15652111,"lng":137.011535,"geo_status":"db","era":"寛政10年（1798）／昭和後期改修","year":1798,"year_source":"db","year_min":1798,"year_max":1798,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0476","desc":"蓮教寺の塔頭で、境内西側に東面して建つ。桁行三間半、梁間三間、正面入母屋造、背面切妻造、桟瓦葺である。内部は六畳の外陣と四畳の内陣の正側面に縁を廻す。龍の彫刻欄間や向拝虹梁の彫刻など細部にも意を凝らし、境内景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011513"},{"id":"00006768","register_sub_id":"101","register_pk":"107750","name":"真清田神社北門及び透塀","kana":"ますみだじんじゃきたもんおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市真清田1-2-1","lat":35.30788542,"lng":136.80213505,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"北門 木造、銅板葺、間口2.7m、袖塀付、透塀 木造、銅板葺、総延長99m","structure_material":"北門 木造","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0252","desc":"北門は本殿の真北に位置し、北門から透塀が東西方向に繋がる。北門は間口２．７ｍ、切妻造の薬医門。透塀は東側に１０間、西側に１１間、さらに南へ１３間延び、南から３間は屋根を一段下げ、中央に引違戸をたてる。優れた境内景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006768"},{"id":"00006769","register_sub_id":"101","register_pk":"107751","name":"真清田神社祭文殿","kana":"ますみだじんじゃさいもんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"愛知県","address":"愛知県一宮市真清田1-2-1","lat":35.307545,"lng":136.802063,"geo_status":"db","era":"昭和31","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積232㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"23 － 0251","desc":"本殿の正面、渡殿を介して繋がる。桁行１２ｍ、梁間８．９ｍ、切妻造銅板葺の建物で、身舎は天井が高く、広い一室で、四周に１間幅の下屋を廻す。正面に拝殿、背面に渡殿、両側面に翼廊が付き、複雑な外観を形成するが、細部は簡潔明瞭な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006769"},{"id":"00005618","register_sub_id":"101","register_pk":"106606","name":"真清田神社本殿及び渡殿","kana":"ますみだじんじゃほんでんおよびわたどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県一宮市真清田1-2-1","lat":35.30771803,"lng":136.80209918,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積186㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"23 － 0222","desc":"南面して建つ。本殿は三間社流造で，四周に縁を廻し，三斗組，二軒繁垂木，妻飾は二重虹梁である。前面に両下造で，中央格天井，両側間を化粧屋根裏とした渡殿が繋がる。檜材を用い，蟇股など装飾細部を最少限に抑え，優れた比例と荘厳な造形を達成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005618"},{"id":"00010808","register_sub_id":"101","register_pk":"201643","name":"萬福寺山門","kana":"まんぷくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市上重原町本郷27","lat":34.99452,"lng":137.025211,"geo_status":"db","era":"天保15","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造、瓦葺、間口5.4m","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0451","desc":"境内東方の正面に構える入母屋造本瓦葺の門。四脚門形式ながら、棟通りの両端より内側に円柱を立てて門口とする。組物は拳鼻付二手先詰組で、さらに各間に蟇股を置く。軒は二軒繁垂木。比較的規模が大きく組物廻りに技巧を凝らし、境内表構えに重厚さを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010808"},{"id":"00010807","register_sub_id":"101","register_pk":"201642","name":"萬福寺鐘楼","kana":"まんぷくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知立市上重原町本郷27","lat":34.994392,"lng":137.025155,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0450","desc":"境内南東方の切石積基壇上に建つ方一間吹放ち形式の鐘楼で、南北棟の入母屋造桟瓦葺である。礎盤上に内転びに立てる円柱を貫で固め、台輪上の組物は拳鼻付の出組を詰組に、軒は二軒扇垂木とする。禅宗様を基調とし装飾密度の高い鐘楼で、境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010807"},{"id":"00010806","register_sub_id":"101","register_pk":"201641","name":"萬福寺本堂","kana":"まんぷくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県知立市上重原町本郷27","lat":34.994502,"lng":137.024563,"geo_status":"db","era":"明治32／平成26改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積603㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"23 ‐ 0449","desc":"境内中央に東面して建つ。標準的な真宗本堂平面をもつ大型の堂で三間向拝を付す。内陣や余間の折上小組格天井では内陣を二重に折上げ、矢来内や外陣を小組格天井とする。明治期に西三河で活躍した棟梁小野田又蔵の最盛期の作となる、規模雄大で意匠華やかな堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010806"},{"id":"00007211","register_sub_id":"101","register_pk":"108193","name":"湊築島弁天社","kana":"みなとちくしまべんてんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県豊橋市湊町7-2","lat":34.77193112,"lng":137.38468442,"geo_status":"db","era":"寛政7","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"23 － 0304","desc":"湊町公園の池中の築島に建つ、三間社入母屋造向拝付。屋根は本瓦葺である。三方に擬宝珠高欄付の縁がめぐり、木階３級がつく。外陣は吹放ちで格天井を草木画で飾り、内陣正面に格子戸をたて込み、背面に内々陣を突出する。組物は平三斗実肘木、二軒繁垂木とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007211"},{"id":"00010172","register_sub_id":"101","register_pk":"198005","name":"明眼院旧多宝塔","kana":"みょうげんいんきゅうたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県海部郡大治町大字馬島字北割114","lat":35.174392,"lng":136.820345,"geo_status":"db","era":"慶安2／明治中期・昭和45改修","year":1649,"year_source":"db","year_min":1649,"year_max":1649,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"23 － 0420","desc":"方三間の多宝塔であったが、濃尾地震後に上層を欠失した。四天柱に直径九寸の円柱、側廻りに七寸の面取角柱を立て、屈曲の強い海老虹梁で繋ぐ。側廻りは拳鼻付三斗で外部出組とし、中備に蟇股と蓑束を置き格天井を張る。尾張地方に多く残る多宝塔の遺例の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010172"},{"id":"00003870","register_sub_id":"101","register_pk":"104860","name":"明治村聖ザビエル天主堂","kana":"めいじむらせいざびえるてんしゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34548462,"lng":136.98969604,"geo_status":"db","era":"明治23／昭和48移築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積575㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0104","desc":"もと外周壁を煉瓦造とする木造会堂。平面は三廊式で，身廊壁面を三層構成とするゴシック様式。木製の束ね柱やトリフォリウム，リブ・ヴォールトと，漆喰塗内壁の対比が美しい。外壁にはバットレスを付け，薔薇窓，尖頭アーチ形の開口，小尖塔などで飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003870"},{"id":"00003875","register_sub_id":"101","register_pk":"104865","name":"明治村大明寺聖パウロ教会堂","kana":"めいじむらだいみょうじせいぱうろきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.346291,"lng":136.990967,"geo_status":"db","era":"明治12／平成6移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積172㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0109","desc":"木造平屋建，入母屋造，桟瓦葺。正面に切妻の玄関廊をつけ，鐘楼を載せる。外観は真壁造の和風意匠であるが，内部は三廊式のゴシック様式を実現している。身廊は木製束ね柱と漆喰塗の四分ヴォールトで飾り，側廊には竿縁天井を曲面に張る。大工は大渡伊勢吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003875"},{"id":"00003863","register_sub_id":"101","register_pk":"104853","name":"明治村ハワイ移民集会所","kana":"めいじむらはわいいみんしゅうかいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県犬山市内山1博物館明治村内","lat":35.34386176,"lng":136.9914945,"geo_status":"db","era":"明治22頃／昭和44移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2004.02.17(平成16.02.17)","register_no":"23 － 0097","desc":"基督教組合派の岡部次郎牧師が建設した教会。バルーン・フレーム構造の平屋建で，鉄板葺の切妻屋根は軒先で緩勾配とする。隅柱付の下見板張で上げ下げ窓を開く。正面軒高にコーニスを飾り，換気口や入口上ペディメントと共に反復する三角形で意匠をまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003863"},{"id":"00009770","register_sub_id":"101","register_pk":"195599","name":"八平神社玉垣","kana":"やひらじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"愛知県","address":"愛知県新城市出沢字八ノ平102-1","lat":34.94255304,"lng":137.5356601,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造、瓦葺、延長28m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0391","desc":"本殿の四方を囲み、正面五間、側面四間、両下造、桟瓦葺である。正面中央間に両折れの格子戸を備える。そのほかは土台上の柱を腰貫、内法貫で固め、竪板壁を張る。山林の中の神域を画す玉垣で、本殿と一体となって森厳な雰囲気の境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009770"},{"id":"00009769","register_sub_id":"101","register_pk":"195598","name":"八平神社本殿","kana":"やひらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字八ノ平102-1","lat":34.94253626,"lng":137.53571293,"geo_status":"db","era":"元禄13／大正7改修","year":1700,"year_source":"db","year_min":1700,"year_max":1700,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.7㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0390","desc":"龍泉寺東側の境内に位置する銅板葺の流造社殿。身舎は間口一間、奥行二間で、内陣を三室に区画する。庇柱は角柱として木階を設け、正側面に縁を廻らす。背面柱筋に脇障子をたて、琵琶板に格狭間様の彫刻を飾る。江戸中期の当地域における小規模社殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009769"},{"id":"00009765","register_sub_id":"101","register_pk":"195594","name":"龍泉寺開山堂及び位牌堂","kana":"りゅうせんじかいざんどうおよびいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.94228737,"lng":137.53556207,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0386","desc":"本堂の背面に渡殿を介して接続する。切妻造桟瓦葺で、腰高に簓子下見板を張る。内部は渡殿から奥に位牌堂、開山堂を配し、徐々に床高を上げる構成をもつ。位牌堂は左右に位牌壇を設え、開山堂は、入口や後部の仏壇の要所に絵様虹梁を架け渡し、漆塗などで荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009765"},{"id":"00009766","register_sub_id":"101","register_pk":"195595","name":"龍泉寺観音堂及び御茶堂","kana":"りゅうせんじかんのんどうおよびおちゃどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.94207036,"lng":137.53560347,"geo_status":"db","era":"観音堂 文政5 御茶堂 昭和10","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0387","desc":"本堂の南西方に東面して建つ。観音堂は方三間の小規模な堂で、後方一間を仏壇として三十三観音を祀る。御茶堂は観音堂南側に接続し、観音堂参拝者に茶を接待する場となっている。総体に簡素な建築ながら当地域における観音信仰の一端を伺い知ることができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009766"},{"id":"00009767","register_sub_id":"101","register_pk":"195596","name":"龍泉寺庫裏","kana":"りゅうせんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.9422374,"lng":137.53579478,"geo_status":"db","era":"天保14／平成19改修","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積148㎡","structure_material":"木造平屋一部2階建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0388","desc":"本堂の東に南北棟で建つ切妻造桟瓦葺で、本堂との間に南向きの玄関と二室をおいて接続する。中央に立てた大黒柱の北側に四室を、南側の旧土間には調理場などを配する。伽藍景観の一角を担うとともに、江戸末期の地方における禅院庫裏の一例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009767"},{"id":"00009768","register_sub_id":"101","register_pk":"195597","name":"龍泉寺鐘楼","kana":"りゅうせんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.9420618,"lng":137.5358576,"geo_status":"db","era":"昭和30","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、瓦葺、面積6.7㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0389","desc":"庫裏の南方に東西棟で建つ。方一間吹放ちの鐘楼で、基壇上に几帳面取角柱を内転びに立て、腰貫と内法貫を通し、虹梁状の頭貫と台輪で固める。組物は三斗で、中備を省く。入母屋造桟瓦葺で、軒は一軒繁垂木、天井は格天井を張る。伝統的な形式の吹放ち鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009768"},{"id":"00009764","register_sub_id":"101","register_pk":"195593","name":"龍泉寺本堂","kana":"りゅうせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県新城市出沢字的場田30・31合併地1","lat":34.94220028,"lng":137.53567343,"geo_status":"db","era":"文政3","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"23 － 0385","desc":"山あいに所在する境内の奥に、南面して建つ。入母屋造桟瓦葺で、正面中央間に虹梁を架ける。内部は六間取の前面に広縁を通す平面で、中列奥の内陣に須弥壇を構え、大間との境は円柱を絵様虹梁で繋ぎ、欄間に雲龍や唐獅子の彫刻を飾るなど華やかな意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009764"},{"id":"00011510","register_sub_id":"101","register_pk":"210538","name":"蓮教寺庫裏","kana":"れんきょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15635306,"lng":137.01204111,"geo_status":"db","era":"宝暦13年（1763）／昭和後期改修","year":1763,"year_source":"db","year_min":1763,"year_max":1763,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0473","desc":"本堂の東側にある庫裏。桁行九間半、梁間四間、切妻造桟瓦葺、妻入で、側背面に下屋が付く。南を土間とし、北は東西三列の居室を並べ、仏間はトコと付書院を構える。外観は真壁漆喰塗で、妻面は小屋束や梁を現す。簡素な造りながら、風格ある佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011510"},{"id":"00011512","register_sub_id":"101","register_pk":"210540","name":"蓮教寺山門及び脇塀","kana":"れんきょうじさんもんおよびわきべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15621611,"lng":137.01168111,"geo_status":"db","era":"文化9年（1812）／平成12年改修","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"山門 木造、瓦葺、間口3.7m 脇塀 木造、瓦葺、総延長23m","structure_material":"山門 木造","registered":"2017.05.02(平成29.05.02)","register_no":"23-0475","desc":"本堂正面の参道に建つ四脚門。切妻造、本瓦葺で、両脇に真壁漆喰塗の脇塀が矩折れに続く。主柱は丸柱、控柱は几帳面取の角柱で、妻面は笈形付き大瓶束で棟木を受ける。軸部は木太く重厚な造りで、随所に意匠を凝らした彫刻で華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011512"},{"id":"00011509","register_sub_id":"101","register_pk":"210537","name":"蓮教寺書院","kana":"れんきょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15659889,"lng":137.01203,"geo_status":"db","era":"文化9年（1812）／昭和30年頃・平成27年改修","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0472","desc":"本堂背面に廊下を介して接続する。桁行七間半、梁間六間半、切妻造、桟瓦葺。平面は東西二列に各三室を並べる六間取で、東西両側に広縁を設け、西面南端には玄関を付ける。上段の間は付書院を備え、天井は格天井とするなど、高い格式を備えた上質な書院建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011509"},{"id":"00011511","register_sub_id":"101","register_pk":"210539","name":"蓮教寺鐘楼","kana":"れんきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15635111,"lng":137.01158111,"geo_status":"db","era":"明治15年","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"23-0474","desc":"山門の西側に東西棟で建つ。桁行一間梁間一間、入母屋造本瓦葺の鐘楼。玉石積みの基壇上に丸柱を四方転びに立て、腰貫、内法貫を入れ、虹梁状の頭貫と台輪で固める。天井は折上小組格天井で、軒は二軒扇垂木。妻飾には亀の彫刻が施され、華やかな意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011511"},{"id":"00011508","register_sub_id":"101","register_pk":"210536","name":"蓮教寺本堂","kana":"れんきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県名古屋市名東区高針四丁目864","lat":35.15647306,"lng":137.01187889,"geo_status":"db","era":"宝暦8年（1758）／宝暦14年（1764）・文化9年（1812）増築、平成16年改修","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡、太鼓楼付","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"23-0471","desc":"市東部の丘陵地にある真宗高田派寺院本堂。桁行五間、梁間五間、寄棟造本瓦葺で、南面し向拝一間を付ける。鼓楼付の玄関、両側面後方下屋は後の増築である。内部は外陣、矢来内と続き、奥に内陣と両脇に余間を配し、後堂を設ける典型的な真宗本堂平面で上質な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011508"},{"id":"00009615","register_sub_id":"101","register_pk":"194611","name":"蓮慶寺大門","kana":"れんけいじおおもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"愛知県","address":"愛知県知多郡阿久比町大字植大字石坂37-1他","lat":34.91634777,"lng":136.91936928,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0379","desc":"境内の南東隅に位置し、本堂正面に東面して建つ四脚門。切妻造本瓦葺、二軒繁垂木。本柱を円柱、控柱を几帳面取角柱とし、石製礎盤上に建つ。格天井を張り、組物は実肘木拳鼻付平三斗の詰組、妻は二重虹梁で上段に笈形付大瓶束を立てる。規模壮大で質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009615"},{"id":"00009616","register_sub_id":"101","register_pk":"194612","name":"蓮慶寺土塀","kana":"れんけいじどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"愛知県","address":"愛知県知多郡阿久比町大字植大字石坂37-1他","lat":34.91642564,"lng":136.91942273,"geo_status":"db","era":"昭和26","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造、瓦葺、総延長17m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0380","desc":"境内の南東隅、大門の南北両脇に矩折れに接続する脇塀及び土塀からなる。布石積基礎を高く積み、脇塀は南北各二間、切妻造桟瓦葺とし、土塀は東へ各四間、東西棟切妻造桟瓦葺で、いずれも腰下竪板張、上部漆喰塗である。大門とともに境内正面の意匠を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009616"},{"id":"00009614","register_sub_id":"101","register_pk":"194610","name":"蓮慶寺本堂","kana":"れんけいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛知県","address":"愛知県知多郡阿久比町大字植大字石坂37-1","lat":34.91641915,"lng":136.91887555,"geo_status":"db","era":"文化8","year":1811,"year_source":"db","year_min":1811,"year_max":1811,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積538㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"23 － 0378","desc":"境内南西隅に東面して建つ。桁行九間梁間八間半、入母屋造本瓦葺で、向拝三間を付ける。前方を外陣、後方を内陣及び余間と飛檐の間とし、外陣三方を広縁及び切り目縁で囲み、背面に後堂がつく。内陣を上々段、二重折上格天井とし、格調高い大規模な真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009614"},{"id":"00014246","register_sub_id":"101","register_pk":"509636","name":"恵日山観音寺観音堂","kana":"えにちざんかんのんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和後","pref":"三重県","address":"三重県津市大門447","lat":34.72066389,"lng":136.51322222,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積305㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"24 - 0313","desc":"津城下中心部に位置し、津観音で知られる寺院本堂。戦災焼失した旧国宝本堂を建築史家村田治郎により復元。鉄筋コンクリート造寄棟造本瓦葺の五間堂で、正面に向拝を付け、四周に縁を廻す。出三斗や蓑束、建具等外廻り意匠によく旧態を伝える復興建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014246"},{"id":"00015467","register_sub_id":"101","register_pk":"533482","name":"大村神社本殿","kana":"おおむらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県伊賀市阿保1555","lat":34.67034167,"lng":136.18373056,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"24 - 0336","desc":"重文大村神社宝殿の東脇に北面して建つ本殿。正面一間、背面三間、側面二間の入母屋造妻入檜皮葺で正面に向拝を付し、周囲に刎高欄付縁を廻らす。身舎は円柱上に三斗を組み、軒は二軒繁垂木。内陣正面三箇所は幣軸構え。入母屋造の屋根が宝殿と呼応する社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015467"},{"id":"00009777","register_sub_id":"101","register_pk":"195606","name":"開化寺観音堂","kana":"かいかじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊賀市小田町1077","lat":34.7707066,"lng":136.12206276,"geo_status":"db","era":"江戸後期／明治22・昭和11移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0162","desc":"境内南東に西面して建つ。桁行四間梁間三間、入母屋造妻入、本瓦葺で、向拝三間を付ける。堂内は前寄り一間を広縁とし、後方三間を内陣とする。内陣奥に仏壇を設けて厨子を安置する。仏壇や向拝周りなどの細部意匠を凝らし、時代的特徴をよく示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009777"},{"id":"00009778","register_sub_id":"101","register_pk":"195607","name":"開化寺三重塔","kana":"かいかじさんじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"三重県","address":"三重県伊賀市小田町1077","lat":34.77067805,"lng":136.12180102,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造三重塔、瓦葺、建築面積4.0㎡","structure_material":"木造三重塔","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0163","desc":"境内南西に、東面して建つ。木造三間三重塔、本瓦葺で、総高一一メートルを測る。初重は繁垂木で中備蟇股、二重は扇垂木で同蓑束、三重は板軒として組物や軒裏などを雲紋彫刻で満たすなど、各重ごとに異なる意匠が特徴。県下では希少な三重塔の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009778"},{"id":"00009779","register_sub_id":"101","register_pk":"195608","name":"開化寺門","kana":"かいかじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊賀市小田町1077","lat":34.77061856,"lng":136.12190096,"geo_status":"db","era":"江戸末期／明治期移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"24 － 0164","desc":"境内南入口に構える薬医門である。梁で持出した虹梁上の出組組物でさらに丸桁を持出し、軒を深める。虹梁上には彫刻化した蟇股をおき、背面では二重虹梁の各段に同様の蟇股を千鳥に配する。また妻飾大瓶束の笈型なども立体的な彫刻を多用する装飾性豊かな門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009779"},{"id":"00013259","register_sub_id":"101","register_pk":"366248","name":"西方寺木枯亭","kana":"さいほうじこがらしてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"三重県","address":"三重県鈴鹿市寺家三丁目2904","lat":34.82400278,"lng":136.58131667,"geo_status":"db","era":"明治前期／昭和40年頃・平成24年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積85㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"24 － 0274","desc":"市東部の伊勢湾沿岸に位置し、境内東寄りに建つ本堂の西側に接続し南面して建つ。木造平屋建、切妻造桟瓦葺で、正面本堂寄りに式台玄関を突出する。内部正面側に鞘の間、奥は二列に二室ずつ配し、西側二室には床、棚を備えるなど、境内を構成する上質な書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013259"},{"id":"00008708","register_sub_id":"101","register_pk":"149429","name":"寂照寺観音堂","kana":"じゃくしょうじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町101","lat":34.47698385,"lng":136.72128367,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0106","desc":"金毘羅堂の南に西面して建つ。入母屋造妻入本瓦葺で、正面に1間向拝を付ける。正面4.8ｍ奥行7.7ｍ。外壁を漆喰の大壁とし、土蔵風に造る。内部は畳敷で、棹縁天井、背面に接して仏壇を設ける。金毘羅堂と並び建ち、伽藍景観を特色づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008708"},{"id":"00008707","register_sub_id":"101","register_pk":"149428","name":"寂照寺金毘羅堂","kana":"じゃくしょうじこんぴらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町101","lat":34.4770473,"lng":136.72137066,"geo_status":"db","era":"天保10年(1839)","year":1839,"year_source":"converted","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0105","desc":"旧伊勢街道東に占める境内の東に位置する。桁行3間梁間3間の入母屋造妻入本瓦葺。乱積基壇上に建ち、柱は正面のみ円柱。平三斗、一軒半繁垂木。内部は板床で、背面1間通りに壇を構える。周囲棹縁で、中央の鏡天井に龍を描く。幕末における小仏堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008707"},{"id":"00008709","register_sub_id":"101","register_pk":"149430","name":"寂照寺山門","kana":"じゃくしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市中之町101","lat":34.47721116,"lng":136.72107452,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0107","desc":"金毘羅堂の西方に位置する。1間1戸薬医門、切妻造本瓦葺。本柱間を冠木、本・控柱間に女梁に支持させた男梁や貫、控柱間は虹梁と桁で固める。妻は笈形付大瓶束とし、軒は一軒疎垂木。鰭付三花懸魚。装飾を排し、欅の良材を用いた手堅い仕事を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008709"},{"id":"00009621","register_sub_id":"101","register_pk":"194617","name":"寿量寺旧大黒殿","kana":"じゅりょうじきゅうだいこくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"三重県","address":"三重県桑名市大字桑名字伝馬町2363","lat":35.05764843,"lng":136.6902871,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積16㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0154","desc":"東海道に東面する境内の北方に南面する。桁行四・四メートル梁間二・九メートル、ヴォールト状の屋根をかける鉄筋コンクリート造で妻入とする。正面向拝では、フルーティングを施した角柱に枠肘木を置いて唐破風屋根を受ける。近代和風建築として特異な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009621"},{"id":"00009622","register_sub_id":"101","register_pk":"194618","name":"寿量寺鐘楼","kana":"じゅりょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"三重県","address":"三重県桑名市大字桑名字伝馬町2363","lat":35.05749376,"lng":136.69019668,"geo_status":"db","era":"昭和10頃","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"鉄筋コンクリート造、面積7.5㎡","structure_material":"鉄筋コンクリート造","registered":"2013.06.21(平成25.06.21)","register_no":"24 － 0155","desc":"境内南方に建つ。方一間、宝形造鉄筋コンクリート造。柱間上部をアーチで繋ぎ、洗い出して文様をつける。伝統的な鐘楼の形態を基調とし、簡略化された和風の意匠とアーチとの折衷を試みた、当地域での鉄筋コンクリート技術を知る上で欠くことのできない建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009622"},{"id":"00008706","register_sub_id":"101","register_pk":"149427","name":"誓元寺山門","kana":"せいがんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市赤堀2-2009-1","lat":34.96055465,"lng":136.60699563,"geo_status":"db","era":"明治45年","year":1912,"year_source":"converted","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0104","desc":"境内東辺中央に位置する。間口3.1ｍの四脚門で、両脇に袖塀を付け、潜りを開ける。切妻造本瓦葺。本柱が円柱、控柱が方柱で、礎盤上にたつ。支輪付出組、二軒繁垂木。冠木と楣間には彫刻を飾り、桟唐戸を装置。本格的な仕様で、風格ある伽藍正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008706"},{"id":"00008705","register_sub_id":"101","register_pk":"149426","name":"誓元寺鐘楼","kana":"せいげんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"三重県","address":"三重県四日市市赤堀2-2009-1","lat":34.96046506,"lng":136.60688216,"geo_status":"db","era":"明治45年","year":1912,"year_source":"converted","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造、瓦葺、面積48㎡","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"24 － 0103","desc":"境内の東南、高い玉石の亀甲積基壇上に建つ。方1間吹放ちとする鐘楼。礎盤上に円柱を内転びにたて、貫や台輪で固め、支輪付出組を組む。柱間中央にも出組を置き、その間に蟇股を飾る。二軒繁垂木。入母屋造桟瓦葺。高度な石積技術や堅実な木工技能がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008705"},{"id":"00009980","register_sub_id":"101","register_pk":"196127","name":"中山寺経蔵","kana":"ちゅうざんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県伊勢市勢田町410","lat":34.47785769,"lng":136.70855653,"geo_status":"db","era":"元禄15／平成18改修","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0170","desc":"本堂の南方に東面して建つ。土蔵造平屋建、宝形造桟瓦葺の経蔵。正面に一間向拝を付け、向拝以外の軒裏を塗り込めて防火性を高める。内周の棚に教典を納め、厨子には観音像を祀る。内部は床を張って鏡天井とする。堅牢な外観の経蔵で、境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009980"},{"id":"00009981","register_sub_id":"101","register_pk":"196128","name":"中山寺山門","kana":"ちゅうざんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市勢田町410","lat":34.47773366,"lng":136.70897643,"geo_status":"db","era":"元禄12頃／平成18改修","year":1699,"year_source":"db","year_min":1699,"year_max":1699,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0171","desc":"境内の東辺に開く。一間一戸の薬医門で、角柱の本柱上に太い冠木を置き、男梁を載せ、屋根は切妻造本瓦葺とする。本柱からは腕木状に女梁を伸ばし、斗を置いて男梁を支える。妻飾は棟束に板蟇股様の笈形を付ける。全体に装飾を控えて、簡明で重厚な意匠となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009981"},{"id":"00009979","register_sub_id":"101","register_pk":"196126","name":"中山寺本堂","kana":"ちゅうざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県伊勢市勢田町410","lat":34.47800939,"lng":136.70872142,"geo_status":"db","era":"明暦2／元文3・安政6改修","year":1656,"year_source":"db","year_min":1656,"year_max":1656,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積283㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"24 － 0169","desc":"六間取方丈型の本堂で、室中の間口は三間半、上間と下間の間口を各二間、正側面に一間幅の広縁、背面に半間の廊下を廻す。正面の落縁を堂内に取り込む点は特徴的である。臨済宗寺院の方丈型本堂としての規式をよく留め、規模も大きい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009979"},{"id":"00016674","register_sub_id":"101","register_pk":"579158","name":"長慶寺庫裏","kana":"ちょうけいじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市蔵持町里2565","lat":34.639498,"lng":136.104711,"geo_status":"db","era":"天明元年（1781）／江戸末期増築、昭和後期改修","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積237㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0344","desc":"本堂の北東に位置する庫裏。平屋建東西棟の切妻造桟瓦葺で、西に入母屋造の角屋を延ばし、南面中央に式台を構える。内部の東はかつての土間、西は前後７室を配し、南西の床構え付き座敷は庭に面して広縁を廻らす。床廻りの貼付壁など古刹の格式を示す庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016674"},{"id":"00016673","register_sub_id":"101","register_pk":"579157","name":"長慶寺本堂","kana":"ちょうけいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県名張市蔵持町里2565","lat":34.639366,"lng":136.104491,"geo_status":"db","era":"享保12年（1727）","year":1727,"year_source":"db","year_min":1727,"year_max":1727,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"24 - 0343","desc":"市街地北西に位置する真言宗寺院の本堂。境内西側に東面して建つ一重入母屋造裳階付で正面に一間向拝を付す。軸部は円柱で組物は出三斗、軒は二軒繁垂木とする。内部は内・外陣、両脇陣からなり、内陣奥に須弥壇を構える。向拝の木鼻や中備蟇股など彫刻秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016673"},{"id":"00010829","register_sub_id":"101","register_pk":"201664","name":"片山寺土蔵","kana":"へんざんじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"三重県","address":"三重県度会郡南伊勢町阿曽浦16","lat":34.276007,"lng":136.583706,"geo_status":"db","era":"文化4","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積21㎡","structure_material":"土蔵造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0230","desc":"境内西方の一段高い位置に南面して建つ二階建土蔵。切妻造、置屋根式桟瓦葺で正面出入口に下屋を張出し、東面二階に窓を開ける。外壁は簓子下見板張として、妻面は鉢巻のみ漆喰塗を表す。小規模ながら、入江を臨む独特な風致に築かれた庭園の一画を彩る土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010829"},{"id":"00010828","register_sub_id":"101","register_pk":"201663","name":"片山寺本堂","kana":"へんざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県度会郡南伊勢町阿曽浦16","lat":34.275878,"lng":136.583861,"geo_status":"db","era":"延宝5／大正前期・平成2改修","year":1677,"year_source":"db","year_min":1677,"year_max":1677,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"24 ‐ 0229","desc":"阿曽浦集落の急峻地に構える境内に南面して建つ。平面は六間取の方丈形式で、仏間背面に眠蔵をもつなど古式を備える。軸部や内装は簡明ながら、屋根を本瓦葺として重厚な趣をもつ。地方禅院における江戸中期の方丈型本堂の好例であり、歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010828"},{"id":"00008128","register_sub_id":"101","register_pk":"132526","name":"三瀬谷神社本殿","kana":"みせだにじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県多気郡大台町佐原439","lat":34.39701196,"lng":136.40594746,"geo_status":"db","era":"元禄3年(1690)／大正3年移築","year":1690,"year_source":"db","year_min":1690,"year_max":1690,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"24 － 0088","desc":"東南に正面を向ける一間社。入母屋造銅板葺で、正面に千鳥破風と軒唐破風付向拝を付設する。三方に擬宝珠高欄付切目縁をまわし、正面に木階を付ける。円柱で、尾垂木付の二手先斗栱、中備蟇股。軒天井を張り、二軒繁垂木が深い軒を持ち出す。気品ある社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008128"},{"id":"00004365","register_sub_id":"101","register_pk":"105355","name":"妙華寺本堂","kana":"みょうげじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"三重県","address":"三重県津市久居二ノ町1743","lat":34.67263702,"lng":136.47324096,"geo_status":"db","era":"安政4","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積264㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"24 － 0051","desc":"真宗高田派寺院の本堂。桁行５間梁間６間半の主体部は，表側を大間，奥を中央内陣，両脇余間，後堂に区画し，両側面後方下屋を楽の間とする。向拝の装飾的な構成や，寄棟造，桟瓦葺の屋根を錣葺とする等特徴ある外観をもち，地域の歴史景観に欠かせない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004365"},{"id":"00002401","register_sub_id":"101","register_pk":"103391","name":"安養院阿弥陀堂","kana":"あんよういんあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07986721,"lng":135.86870759,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0170","desc":"西教寺の塔頭で，参道東端の総門と道路を隔てた位置にある。敷地西側の阿弥陀堂は乱石積基壇上に東面して建ち，入母屋造，桟瓦葺で，４周に切目縁を廻し，正面１間を広縁とする。禅宗寺院の方丈建築を意識しつつ，内部空間や細部の造形に近代的要素がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002401"},{"id":"00002409","register_sub_id":"101","register_pk":"103399","name":"安養院蔵","kana":"あんよういんくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07994817,"lng":135.86876448,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積30㎡","structure_material":"土蔵造2階建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0178","desc":"阿弥陀堂の北側に並立して建つ。総２階建，寄棟造，桟瓦葺，妻入で，外壁は腰をモルタル塗，上部を漆喰塗とし，東面に銅板葺の庇を設ける。派手さはないが，東面の出入口廻りは漆喰で鳥居型につくり，内部の壁も幅広の縦板壁とするなど，技術的な質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002409"},{"id":"00002402","register_sub_id":"101","register_pk":"103392","name":"安養院庫裡","kana":"あんよういんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.079742,"lng":135.868942,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0171","desc":"敷地のほぼ中央に，北面して建つ。入母屋造，妻入で，ゆったりとした桟瓦葺の大屋根を架け，４周に下屋庇を廻し，西側には切妻造の台所棟を連結する。側廻りは角柱に舟肘木をあげ，内部は均整のとれた比例で室内空間をつくり，欄間などの細部は繊細である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002402"},{"id":"00002406","register_sub_id":"101","register_pk":"103396","name":"安養院地蔵堂","kana":"あんよういんじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.079636,"lng":135.86871069,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0175","desc":"庫裡南側に南面して建つ宝形造，桟瓦葺の小堂。部材の風蝕程度から，江戸末期頃の建築と思われる。内部は１室で，４周に軒支柱を立てて，背面を仏壇，左側面を物置にする。全体に質素であるが，正面は時代に相応しい豪華な彫刻欄間を設け，意匠を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002406"},{"id":"00002403","register_sub_id":"101","register_pk":"103393","name":"安養院書院","kana":"あんよういんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07956228,"lng":135.8688391,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0172","desc":"庫裡南側にあり，西南隅が聖天堂と接続する。入母屋造，桟瓦葺，妻入で，内部は床構えのある居室と炊事場からなり，庭に面した東と南に矩折れの廊下を設ける。規模は小さいが，床の構成や土壁の仕上げなど，趣がある瀟洒な室内意匠を備えた住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002403"},{"id":"00002407","register_sub_id":"101","register_pk":"103397","name":"安養院聖天堂","kana":"あんよういんしょうてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07951386,"lng":135.868729,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0176","desc":"天保期の絵図や，細部の様式から江戸後期と考えられ，安養院で最古の仏堂。内陣を核として，前面へ凸状の外陣を設け，右手に炊事場，左手には書院が接続する。土蔵造で宝形屋根の内陣と入母屋造の外陣などを巧みに処理した複雑で特異な形態の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002407"},{"id":"00002405","register_sub_id":"101","register_pk":"103395","name":"安養院弁天堂","kana":"あんよういんべんてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07970328,"lng":135.86858148,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0174","desc":"敷地西側のほぼ中央の小高い地に東面して建つ。方形平面で背面に仏壇部を張り出し，正面と両側面に擬宝珠高欄付の縁を廻し，軒は深くつくる。小規模だが，軸部を長押で固め，組物を三斗，建具を板扉と連子窓，内部を小組格天井とした正統的な和様の仏堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002405"},{"id":"00002404","register_sub_id":"101","register_pk":"103394","name":"安養院門","kana":"あんよういんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.07992921,"lng":135.86893803,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0173","desc":"安養院は恵心僧都源信につらなる安養尼の遺跡の旧地と伝えるが，現在の建物は昭和初期に山口玄洞氏の寄付で再興された。敷地北側にある門は切妻造，桟瓦葺の１間１戸薬医門で，軒廻りや組物は簡素であるが，絵様細部は大柄で，堂々とした外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002404"},{"id":"00002408","register_sub_id":"101","register_pk":"103398","name":"安養院礼拝堂","kana":"あんよういんれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.0795448,"lng":135.868622,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0177","desc":"聖天堂西側にあり，渡廊下で連絡している。桁行３間，梁間２間，入母屋造，桟瓦葺の小規模な建物。角柱に舟肘木をあげて，桁を受ける。１軒疎垂木であるが，緩やかに反った軒をつくり，木連格子の妻飾や正面と両側面に設けた連子窓など，丁寧な造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002408"},{"id":"00007751","register_sub_id":"101","register_pk":"108732","name":"ヴォーリズ記念病院礼拝堂","kana":"う゛ぉーりずきねんびょういんれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市北之庄町480-1","lat":35.15235718,"lng":136.08910328,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積97㎡、石段及び渡廊下付","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"25-0276","desc":"敷地北西の小高い位置に南面して建つ。木造平屋建、建築面積９７㎡、切妻造妻入桟瓦葺で、正面に石段、西方に渡廊下を付ける。玄関ホールの北に小屋組を現す単廊式礼拝堂、東に牧師室、西に控室と便所を配す。半円アーチを開ける白いモルタル壁が木立に映える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007751"},{"id":"00003434","register_sub_id":"101","register_pk":"104424","name":"円寿院本堂","kana":"えんじゅいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市南清水町150","lat":35.14320869,"lng":136.21604503,"geo_status":"db","era":"正徳元","year":1711,"year_source":"db","year_min":1711,"year_max":1711,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0224","desc":"集落西北にある浄土宗本堂。桁行３間，梁間４間，入母屋造，向拝１間で，軒は二軒繁垂木とする。梁間を前後に分け，前方を外陣，奥は中央に一段高く内陣を取り，左右に脇陣を配す。簡素な小堂だが，木太く，内外陣境の欄間や小壁の彫刻など入念な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003434"},{"id":"00000855","register_sub_id":"101","register_pk":"101845","name":"近江神宮神楽殿","kana":"おうみじんぐうかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03276349,"lng":135.85224025,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積162㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0077","desc":"正面三間奥行四間，東西棟の入母屋造建物で，東南端に切妻屋根の車寄玄関を張出し，廻廊側の正面に唐破風をつける。北面と西面に廊下を回し，北で参集所に，西で神饌所に連絡する。第二期工事分の核となる施設で，時節にもかかわらず上質に仕上げられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000855"},{"id":"00000854","register_sub_id":"101","register_pk":"101844","name":"近江神宮神楽殿廻廊","kana":"おうみじんぐうかぐらでんかいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03269031,"lng":135.85246273,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積64㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0076","desc":"外院北部の北端に位置する神楽殿の前面をコの字型に囲う廊。外側を連子窓，内側を開放とし，桁行六間の東廊は虹梁中央の束上に化粧棟木を載せて南北棟の入母屋屋根を架け，各五間の北・南廊は海老虹梁により内外の柱を繋ぎ，内側柱筋に棟を上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000854"},{"id":"00000852","register_sub_id":"101","register_pk":"101842","name":"近江神宮北神門","kana":"おうみじんぐうきたしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03240635,"lng":135.85120396,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造八脚門，銅板葺，建築面積15㎡","structure_material":"木造八脚門","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0074","desc":"神楽殿に対応した門で，外院北部の入口にあたる。三間三戸の八脚門で，円形本柱と角形控柱の上部を海老虹梁で繋ぎ，本柱の上に平三斗を載せて化粧棟木を，控柱は大斗肘木で軒桁を支え，反り付きの切妻屋根を架ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000852"},{"id":"00000838","register_sub_id":"101","register_pk":"101828","name":"近江神宮後門","kana":"おうみじんぐうこうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造棟門，檜皮葺，幅2.7m","structure_material":"木造棟門","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0060","desc":"本殿の真後ろ，内内院の西面を限る透塀の中央に位置する切妻造，檜皮葺の門で，扉に連子を入れて透塀との連続性を持たせながら，屋根を一段高くするとともに反りを緩やかに付けて透塀を分節している。中門と同様，内内院の重要な結界要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000838"},{"id":"00000864","register_sub_id":"101","register_pk":"101854","name":"近江神宮斎館","kana":"おうみじんぐうさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03336067,"lng":135.85286378,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積98㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0086","desc":"勅使玄関の北に接続する入母屋造の建物で，この棟のみ軸線を３０度程振る。８畳と床付１０畳の二間構成で，南と東の二面に畳敷の広縁を回し，東面に高欄付の縁をつける。８畳間は棹縁天井，１０畳の書院座敷は格天井とし，落着きある空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000864"},{"id":"00000865","register_sub_id":"101","register_pk":"101855","name":"近江神宮斎館玄関","kana":"おうみじんぐうさいかんげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03331676,"lng":135.85276132,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積27㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0087","desc":"斎館西面と社務所西棟の北端を結ぶ通路の中央部から北に突出させた切妻造，瓦葺の玄関。斎館の裏玄関にあたる。正面に縦長の桟唐戸を四枚建込み，長押上に細かい縦桟の欄間を入れる。舟肘木を用い，妻飾は豕叉首で，破風に簡素な懸魚をつけて立面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000865"},{"id":"00000858","register_sub_id":"101","register_pk":"101848","name":"近江神宮参集所","kana":"おうみじんぐうさんしゅうじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03291864,"lng":135.85236612,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積155㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0080","desc":"神楽殿に接続し，神楽殿の北面崖際より北に伸びる一部二階建，瓦葺の南北棟建物で，１０畳間を四間並べ，北端東面に通用玄関を，西に参集所玄関への接続部を張りだす。１０畳四間は一室空間になり，南端に床の間を設け，東面は連続の出窓とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000858"},{"id":"00000860","register_sub_id":"101","register_pk":"101850","name":"近江神宮参集所玄関","kana":"おうみじんぐうさんしゅうじょげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03310892,"lng":135.8523954,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺一部瓦葺，建築面積101㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0082","desc":"東西棟，入母屋造の建物で，南に登廊に接続する張出し部を，北に千鳥破風を頂く玄関車寄を突出させ，東面で社務所に連絡する。主屋部は真壁造で，腰を簓子下見とするが，玄関車寄は舟肘木を用いるなど正面に相応しい意匠でまとめあげられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000860"},{"id":"00000859","register_sub_id":"101","register_pk":"101849","name":"近江神宮参集所登廊","kana":"おうみじんぐうさんしゅうじょのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03301817,"lng":135.85238076,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺一部瓦葺，建築面積12㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0081","desc":"神饌所，神楽殿から参集所，社務所を経て北端の斎館までは登廊や廊下により結ばれているが，参集所登廊はそのほぼ中間に位置し，ここにのみ防火区画を設ける。階段中途の踊場に防火扉を設置し，防火壁を卯建状に立ち上げて上面に瓦を葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000859"},{"id":"00000867","register_sub_id":"101","register_pk":"101857","name":"近江神宮参拝者休憩所","kana":"おうみじんぐうさんぱいしゃきゅうけいじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.0312559,"lng":135.85252127,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積75㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0089","desc":"第二鳥居の左手後方に位置する。平屋建，瓦葺，切妻屋根の四周に庇を回す外観を呈する。内部は身舎部分を棹縁天井，庇部分は化粧小屋裏をあらわし，丸柱と差肘木により特徴ある架構を造る。節のある材を効果的に用いて味わいある内部空間をつくりあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000867"},{"id":"00000861","register_sub_id":"101","register_pk":"101851","name":"近江神宮社務所Ⅰ","kana":"おうみじんぐうしゃむしょいち","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03313527,"lng":135.8528023,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積246㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0083","desc":"ロの字型平面の東棟と南棟部分。東棟は南北棟の入母屋造建物で，東面の中央に唐破風の車寄を突出させて貴賓玄関とし，右手を応接間，左手を脇玄関・宮司室とする。棟を落とした南棟は，事務室を主とし，南面の中央に通用玄関を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000861"},{"id":"00000862","register_sub_id":"101","register_pk":"101852","name":"近江神宮社務所Ⅱ","kana":"おうみじんぐうしゃむしょに","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.0332026,"lng":135.85260909,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積175㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0084","desc":"ロの字型平面の北棟と西棟部分で，北棟は１０畳８畳の二間構成で斎館の付属館的性格をもち，西棟は炊事場・浴室等の棟で瓦葺の寄棟屋根を架ける。北棟の棟は西棟の棟より高く，西棟の棟を越えて西面に千鳥破風をつくり，浴室上部の湯気抜きとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000862"},{"id":"00000848","register_sub_id":"101","register_pk":"101838","name":"近江神宮宿衛舎","kana":"おうみじんぐうしゅくえいしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03205214,"lng":135.85225488,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積39㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0070","desc":"楼門・神符授与所・外廻廊とともに外院を形成する。楼門の南袖塀に取付く東西棟，切妻屋根の建物で，神符授与所と同様に外廻廊の一間分を閉鎖して玄関とする。構造・規模・形式も神符授与所と同じで，両妻側に小庇をつけて立面を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000848"},{"id":"00000839","register_sub_id":"101","register_pk":"101829","name":"近江神宮神庫","kana":"おうみじんぐうじんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積８㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0061","desc":"本殿の左手後方，内内院の南西隅に位置する南北棟の切妻造，檜皮葺，平入の揚床式倉庫で，柱は面取角柱とし，組物は舟肘木を用いる。横板を落込んで壁をつくり，妻飾は豕叉首として，破風に懸魚を付ける。本殿の背後を整える重要な構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000839"},{"id":"00000856","register_sub_id":"101","register_pk":"101846","name":"近江神宮神饌所","kana":"おうみじんぐうしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03281911,"lng":135.85212315,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積53㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0078","desc":"第一期工事分の施設で，内院と同レベルの段の北方に位置し，第二期工事で神楽殿と結ばれる。南北棟の入母屋造建物で，南北両面に玄関口を設け，腰を竪羽目，腰長押以上を横板落込みとし，西北に簓子下見の付属屋を張りだす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000856"},{"id":"00000857","register_sub_id":"101","register_pk":"101847","name":"近江神宮神饌所登廊","kana":"おうみじんぐうしんせんしょのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03279569,"lng":135.8521817,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積９㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0079","desc":"神楽殿の裏通路中央から階段で昇り，神饌所の当初からの東口である舞良戸に繋げる。外部竪羽目の簡素な登廊で，両接続部は切妻屋根とし，階段部は天井を棹縁天井として片流れの屋根を架けて外観に変化をもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000857"},{"id":"00000847","register_sub_id":"101","register_pk":"101837","name":"近江神宮神符授与所","kana":"おうみじんぐうしんぷじゅよじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03225998,"lng":135.852331,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積39㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0069","desc":"第二期工事分に属し，内院の下の敷地東端に位置し，楼門・宿衛舎・外廻廊とともにいわゆる外院を形成する。楼門の北袖塀に取付く東西棟，切妻屋根の建物で，柱は角柱と丸柱を使い分ける。舟肘木を用い，妻飾は豕叉首とし，懸魚をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000847"},{"id":"00000841","register_sub_id":"101","register_pk":"101831","name":"近江神宮透塀（南部）","kana":"おうみじんぐうすきべい（なんぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造，檜皮葺，長さ36m","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0063","desc":"翼廊南端に発し，内内院の南面を限り，西面で神庫の背面に接続する。構造･規模･形式は北部のものと同様とする。手前より三間目を連子の引戸とするのも同様。控えの斜材は鉄筋コンクリート製で，当初からのものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000841"},{"id":"00000840","register_sub_id":"101","register_pk":"101830","name":"近江神宮透塀（北部）","kana":"おうみじんぐうすきべい（ほくぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造，檜皮葺，長さ36m","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0062","desc":"翼廊北端から発し，内内院の北面と西面を限り後門に連なる。土台建ちの面取角柱に秤肘木をのせ，檜皮葺の小屋根を置く。柱間は腰を１枚板，腰長押と内法長押の間を連子窓とする。五間目以西の棟を一段高め，内内院敷地の高低差に応じた造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000840"},{"id":"00000850","register_sub_id":"101","register_pk":"101840","name":"近江神宮外廻廊（南部）","kana":"おうみじんぐうそとかいろう（なんぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03198774,"lng":135.85224903,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積15㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0072","desc":"外院の南翼廊にあたるところで，宿衛舎に取付く。当初は北翼廊と同様七間＋三間の規模を有した。北翼廊と同仕様であるが，東面は高床風とせずに，土間床上に高欄をつける。三間分を残すのみではあるが，外院を構成するうえで欠くことのできないものである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000850"},{"id":"00000849","register_sub_id":"101","register_pk":"101839","name":"近江神宮外廻廊（北部）","kana":"おうみじんぐうそとかいろう（ほくぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03232439,"lng":135.85239832,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積60㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0071","desc":"外院の翼廊にあたるところで，神符授与所に取付き，北端で西に矩折れて外透塀に接続する。切妻屋根，吹放ちの単廊で，外側に高床風の縁をせりだし高欄をまわす。柱は丸柱で，舟肘木を用い，妻飾を豕叉首として簡素な懸魚をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000849"},{"id":"00000851","register_sub_id":"101","register_pk":"101841","name":"近江神宮外透塀（南部）","kana":"おうみじんぐうそとすきべい（なんぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03237708,"lng":135.85126836,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造，銅板葺，建築面積10㎡","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0073","desc":"外院北翼廊の端部に発し，北神門に取付く五間分の屋根塀で，神楽殿・神楽殿廻廊に連なる外院北部（北神門地）の東面を限る。土台立ちの角柱に秤肘木を載せて小屋根を支える。柱間は腰長押と内法長押の間に連子窓を入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000851"},{"id":"00000853","register_sub_id":"101","register_pk":"101843","name":"近江神宮外透塀（北部）","kana":"おうみじんぐうそとすきべい（ほくぶ）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03248832,"lng":135.85130642,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造，銅板葺，延長8m","structure_material":"木造","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0075","desc":"北神門に取付き，神楽殿廻廊に向かう四間分の屋根塀で，南外透塀とともに外院北部の東面を限る。仕様は南外透塀と同様とする。第二期工事分の箇所で，楼門・外廻廊等とともに朱塗と白壁に仕上げられ第一期工事による素木造の社殿群と対照をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000853"},{"id":"00000846","register_sub_id":"101","register_pk":"101836","name":"近江神宮外拝殿","kana":"おうみじんぐうそとはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03226291,"lng":135.85191238,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積157㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0068","desc":"内院敷地の東端に位置する桁行五間梁間三間，入母屋造の建物で，東面に高欄付の縁をせりだして懸造り風につくり，中央間に外院からの登石階段を割込ませる。正面石階段の上と背面中央とに唐破風をつけて割拝殿風にしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000846"},{"id":"00000869","register_sub_id":"101","register_pk":"101859","name":"近江神宮第一鳥居","kana":"おうみじんぐうだいいちとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03134665,"lng":135.855797,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造鳥居，幅7.3m","structure_material":"木造鳥居","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0091","desc":"表参道の入口に位置する鳥居で，第二期工事において建立される。反りのある棟木と島木，内転びの丸柱に角断面の貫と額束を入れた典型的な明神鳥居の形式をとる。幅約７ｍ。社域を明示するとともに，近江神宮のランドマークにもなっている鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000869"},{"id":"00000870","register_sub_id":"101","register_pk":"101860","name":"近江神宮第二鳥居","kana":"おうみじんぐうだいにとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03164524,"lng":135.85266472,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造鳥居，幅6.4m","structure_material":"木造鳥居","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0092","desc":"第一期工事分に係わる鳥居で，表参道の突き当たりの石階段を昇りきった地点に建つ。第一鳥居と同形式の明神鳥居で，幅約６ｍとやや小振りのものとする。参拝者は，この鳥居をくぐり右に折れて，手水舎の先左手の石階段を昇り楼門に向かうことになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000870"},{"id":"00000835","register_sub_id":"101","register_pk":"101825","name":"近江神宮中門","kana":"おうみじんぐうちゅうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03240928,"lng":135.85138546,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積７㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0057","desc":"登廊を昇りきったところに位置し，板唐戸をもって内内院の入口とする。切妻造，檜皮葺，桁行一間梁間一間の規模で，渡廊とは棟続きであるが，板唐戸の上部は，渡廊側を蟇股・斗・舟肘木とし，登廊側を豕叉首として体裁を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000835"},{"id":"00000868","register_sub_id":"101","register_pk":"101858","name":"近江神宮手水舎","kana":"おうみじんぐうちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03194968,"lng":135.85263251,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積18㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0090","desc":"第二鳥居の右手奥，楼門へ向かう石階段の左手脇に位置する。第一期工事分に属する施設で，内転びの隅柱に２本宛の控柱を添わせ，組物は舟肘木を用い，一軒疎垂木，銅板葺（当初は檜皮葺）の切妻屋根を架ける。妻飾は豕叉首とし，破風に懸魚をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000868"},{"id":"00000863","register_sub_id":"101","register_pk":"101853","name":"近江神宮勅使玄関","kana":"おうみじんぐうちょくしげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03324943,"lng":135.8528345,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積22㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0085","desc":"社務所東棟と斎館（貴賓館）との間に設けられた勅使のための玄関で，東面中央に軽快な唐破風をつける。舟肘木を用いた品格ある構えを見せ，内部は一間幅を中央で土間と廊下とに振分け，玄関の突当たりに棚を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000863"},{"id":"00000845","register_sub_id":"101","register_pk":"101835","name":"近江神宮内院廻廊（南部）","kana":"おうみじんぐうないいんかいろう（なんぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03214289,"lng":135.85168697,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積129㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0067","desc":"内院は，内拝殿と一文字状の翼廊（各四間），外拝殿と同状の翼廊（各四間），内拝殿翼廊と外拝殿翼廊とを結ぶ北面の廊（八間）と南面の廊（八間）とにより囲われる。構造・規模・形式等は北廻廊と同様とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000845"},{"id":"00000844","register_sub_id":"101","register_pk":"101834","name":"近江神宮内院廻廊（北部）","kana":"おうみじんぐうないいんかいろう（ほくぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03247661,"lng":135.851807,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積129㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0066","desc":"内拝殿から北へ降り，更に北面で石階段を降り，外拝殿から北に伸びた翼廊に接続して内院を囲う。外側を連子窓，内側を開放とする単廊で，丸柱に舟肘木を用い，小屋組は豕叉首，軒は一軒とする。内院全体が当初は檜皮葺（現在は銅板葺）であった。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000844"},{"id":"00000843","register_sub_id":"101","register_pk":"101833","name":"近江神宮内拝殿","kana":"おうみじんぐうないはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積100㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0065","desc":"内院の西端，石階段付基壇上に建つ桁行五間梁間三間，入母屋造の建物で，背面に床を更に高くした三間×一間の張り出し部を設けて登廊に接続させる。天井は折上小組格天井。一旦内院内に展開した参拝動線を登廊越しの本殿へ向けて絞り込む役割を果たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000843"},{"id":"00000842","register_sub_id":"101","register_pk":"101832","name":"近江神宮登廊","kana":"おうみじんぐうのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積33㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0064","desc":"切妻造，銅板葺（当初は檜皮葺），桁行三間の単廊で，柱は丸柱，舟肘木を用い，豕叉首と斗で化粧棟木を支える。柱間は腰を板壁，腰長押と内法長押の間を硝子障子とする。社殿構成上の見せ所になり，棟は曲線を描いて内内院と内院をダイナミックに繋ぐ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000842"},{"id":"00000833","register_sub_id":"101","register_pk":"101823","name":"近江神宮祝詞舎","kana":"おうみじんぐうのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03235366,"lng":135.85164599,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積13㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0055","desc":"いわゆる「近江造」の特徴を示すところで，形態上は本殿の前面に張りだした切妻の向拝部を祝詞舎とするが，平面上は本殿前面の凸形状の浜縁部を祝詞舎に充てる。桁行一間梁間一間の規模で，全面吹放ちとし，三方に高欄付の縁を回す。天井は小組格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000833"},{"id":"00000832","register_sub_id":"101","register_pk":"101822","name":"近江神宮本殿","kana":"おうみじんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03235366,"lng":135.85164599,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積53㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0054","desc":"皇紀２６００年に合わせて新営された神社建築で，内務省神社局による集大成作品。設計は角南隆と谷重雄。傾斜地に対応した社殿の配置構成に特色がある。本殿は，三間社流造，檜皮葺で，棟に千木と堅魚木をあげて聖域地を明示させている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000832"},{"id":"00000837","register_sub_id":"101","register_pk":"101827","name":"近江神宮翼廊（南部）","kana":"おうみじんぐうよくろう（なんぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03086156,"lng":135.85322501,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積22㎡，神饌弁備所を含む","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0059","desc":"中門に取付く一文字状の翼廊の南部分で，構造・規模・形式は翼廊北部分と同様とするが，桁行四間のうち南端の二間分を板唐戸（北面と南面）と連子窓（東面と西面）とにより囲って弁備所（仮神饌所）に充てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000837"},{"id":"00000836","register_sub_id":"101","register_pk":"101826","name":"近江神宮翼廊（北部）","kana":"おうみじんぐうよくろう（ほくぶ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03245612,"lng":135.85136204,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積22㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0058","desc":"中門に取り付き，内内院の東面を限る。渡廊に直交する一文字状の翼廊の北部分で桁行は四間。切妻屋根，檜皮葺で，外側を連子窓，内側を開放とする。柱は丸柱で，舟肘木を用い，小屋組は豕叉首，軒は一軒とし，化粧垂木には反りを付けずに簡明な造りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000836"},{"id":"00000871","register_sub_id":"101","register_pk":"101861","name":"近江神宮脇鳥居","kana":"おうみじんぐうわきとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03353046,"lng":135.85368051,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造鳥居，幅5.4m","structure_material":"木造鳥居","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0093","desc":"第一期工事の掉尾を飾る施設で，昭和１５年１２月３０日に竣工奉告祭を執行している。斎館（貴賓館）に通じる脇参道の入口に位置する。第一鳥居・第二鳥居と同型式の明神鳥居で，幅約５．４ｍと三つの鳥居のなかでは最も小振りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000871"},{"id":"00000834","register_sub_id":"101","register_pk":"101824","name":"近江神宮渡廊","kana":"おうみじんぐうわたろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市神宮町1-1","lat":35.03235366,"lng":135.85164599,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，檜皮葺，建築面積26㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"25 － 0056","desc":"内内院の入口にあたる中門から祝詞舎に向けて伸びた梁間一間桁行三間の吹放ち廊下。柱は丸柱，舟肘木を用い，化粧棟木を虹梁・蟇股・斗で支える。屋根は切妻造，檜皮葺で，妻先を本殿向拝の下に重ね，本殿から登廊へ連なる屋根面のリズムを造りだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000834"},{"id":"00002777","register_sub_id":"101","register_pk":"103767","name":"大鳥神社神楽殿","kana":"おおとりじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.9124984,"lng":136.22236794,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0195","desc":"拝殿東方に建つ。方１間，入母屋造，妻入で，正側面３方に刎高欄付木口縁を巡らす。面取角柱上に舟肘木を置く簡素な施設だが，建具は３方舞良戸建て，内部背面は鏡板張りで老松を描き，神楽殿の構えを完備する。小規模ながら社殿構成上欠かせない建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002777"},{"id":"00002781","register_sub_id":"101","register_pk":"103771","name":"大鳥神社社務所","kana":"おおとりじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.912453,"lng":136.221832,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積177㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0199","desc":"社殿の南西に東面して建つ。入母屋造，桟瓦葺で，正面中央に向唐破風造の式台を付ける。内部は２列６室に分け，南端に土間を設ける。内法・天井長押を廻し，主座敷には床・棚・付書院を備え，端正な彫刻欄間を入れるなど，簡明洗練された意匠にまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002781"},{"id":"00002778","register_sub_id":"101","register_pk":"103768","name":"大鳥神社神饌所","kana":"おおとりじんじゃしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91243958,"lng":136.22206484,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0196","desc":"拝殿西方，神楽殿に相対する位置に建つ。入母屋造，平入，北端１間通りを踏込土間とし出入口を開き，これより南の床上部の西・南面開口部の外に刎高欄付木口縁を矩折れに廻す。小規模ながら軸部は面取角柱，舟肘木で，開口部は半蔀を吊る本格的な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002778"},{"id":"00002775","register_sub_id":"101","register_pk":"103765","name":"大鳥神社祝詞殿（中門）","kana":"おおとりじんじゃのりとでん（ちゅうもん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91255292,"lng":136.2221946,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造、檜皮葺、建築面積12㎡、左右透塀延長66m付","structure_material":"木造","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0193","desc":"鎌倉時代以来佐々木氏の尊崇を得た神社。貞享２年建立の本殿が残るが，他は大正４年火災後の再建になる。祝詞殿は本殿前に建つ桁行２間，梁間１間，前後唐破風造の建物で，左右矩折れに透塀を付属する。巧みな構成と優美な意匠で社殿中核の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002775"},{"id":"00002776","register_sub_id":"101","register_pk":"103766","name":"大鳥神社拝殿","kana":"おおとりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.912678,"lng":136.222168,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0194","desc":"祝詞殿前方に独立して建つ。方３間，入母屋造，妻入で，４周に刎高欄付木口縁を巡らす。柱間は吹放しで，正背面中央間の内法を一段高くし，内部は二重折上小組格天井とする。細い木割と深い軒の出による優美な外観は社殿の中心にあって最も目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002776"},{"id":"00002779","register_sub_id":"101","register_pk":"103769","name":"大鳥神社神輿蔵","kana":"おおとりじんじゃみこしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91252346,"lng":136.2219903,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0197","desc":"神饌所の北に建つ。土蔵造，寄棟造，本瓦葺で，正面に桟瓦葺の庇を付け，２箇所の戸口を開く。内部は壁・床とも板張りで竿縁天井を張り，御輿，祭器を収める。丁寧な仕事になる堅牢な造りであるとともに，出の大きな軒蛇腹，換気用の丸い小窓など特徴を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002779"},{"id":"00002780","register_sub_id":"101","register_pk":"103770","name":"大鳥神社楼門","kana":"おおとりじんじゃろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県甲賀市甲賀町鳥居野782","lat":34.91225024,"lng":136.22226284,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造楼門、檜皮葺、建築面積27㎡、左右透塀延長77m付","structure_material":"木造楼門","registered":"2002.06.25(平成14.06.25)","register_no":"25 － 0198","desc":"三間一戸，切妻造の楼門で，左右折れ廻りに透塀を廻し境内を区切る。腰組は三手先，上層は出三斗とし，中備は蟇股，間斗束，妻は二重虹梁蟇股である。柱の隅延び，垂木・桁の反増し等中世の技法を忠実に踏襲した優美な意匠となる。設計は京都府技師亀岡末吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002780"},{"id":"00003252","register_sub_id":"101","register_pk":"104242","name":"乎加神社玉垣","kana":"おかじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17721025,"lng":136.18434858,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、銅板葺、延長52m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0212","desc":"幣殿の両脇から左右に若干延びて，本殿，祝詞殿を囲む。延長５２ｍで，石垣を築いた上に木造で塀を廻らし，屋根は銅板葺とする。内側には控柱を設け，各柱間には菱格子を嵌めている。本殿等同時期の建設と伝えられ，本殿廻りの内外を画す建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003252"},{"id":"00003254","register_sub_id":"101","register_pk":"104244","name":"乎加神社手水舎","kana":"おかじんじゃちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17673093,"lng":136.18454841,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積7.7㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0214","desc":"境内の入り口付近に位置する桁行２間梁間１間規模，入母屋造の手水舎。柱はやや内転びとし，木鼻付虹梁形頭貫，蟇股，菱格子欄間など各種の装飾を備える。小規模ではあるが本格的な形式を備え，近代社殿建築の特徴を示す建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003254"},{"id":"00003251","register_sub_id":"101","register_pk":"104241","name":"乎加神社祝詞殿","kana":"おかじんじゃのりとでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.177044,"lng":136.18431072,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0211","desc":"本殿と幣殿とを繋ぐ桁行２間梁間１間，切妻造の社殿。幣殿に合わせて床を高く張り，内法長押上の小壁には菱格子欄間を入れ開放的なつくりとする。本殿と同時期の建設と伝えられ，社殿構成上欠くことのできない建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003251"},{"id":"00003253","register_sub_id":"101","register_pk":"104243","name":"乎加神社拝殿","kana":"おかじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.176846,"lng":136.18425814,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0213","desc":"幣殿の正面に建つ桁行３間梁間３間の社殿。この地域によく見られる床を設けない構成で，天井は折り上げ格天井とする。屋根は檜皮葺に銅板を被せる入母屋造で，軒は二軒とする。豪壮な土間建ちの拝殿であり，社殿景観上欠くことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003253"},{"id":"00003250","register_sub_id":"101","register_pk":"104240","name":"乎加神社幣殿","kana":"おかじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17699562,"lng":136.18430104,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0210","desc":"本殿・祝詞殿の前面に位置する桁行７間梁間２間，入母屋造の社殿で，正面に唐破風屋根の拝所を設ける。中央３間は一段高い切妻屋根とし，両脇は入母屋造とする。建ちの高い本殿と対置される建築で，荘厳な外観が特徴の近代神社建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003250"},{"id":"00003249","register_sub_id":"101","register_pk":"104239","name":"乎加神社本殿","kana":"おかじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市神郷町字森9","lat":35.17711783,"lng":136.18432545,"geo_status":"db","era":"明治初期／明治25移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0209","desc":"桁行３間，梁間２間，独立棟持柱を有する神明造の社殿。屋根は檜皮葺とし，棟に千木と堅魚木７本を載せる。四周に縁を廻らし，正面以外は板壁とする。明治２２年の伊勢神宮遷宮に際し別宮を譲り受け，２５年に当地に移築したものと伝えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003249"},{"id":"00001621","register_sub_id":"101","register_pk":"102611","name":"海門山満月寺浮御堂","kana":"かいもんさんまんげつじうきみどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.109852,"lng":135.92157,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡、長さ17m・幅員2.6m石橋附属","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0126","desc":"琵琶湖上に建つ三間仏堂で，湖畔から延びる長さ約１７ｍの石橋が附属する。平安中期に湖上安全と衆生救済を願って千体の阿弥陀仏を奉る堂を建てたのを始まりと伝える。近江八景のひとつ「堅田の落雁」で知られる景勝地の重要な構成要素。設計は西崎辰之助。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001621"},{"id":"00001622","register_sub_id":"101","register_pk":"102612","name":"海門山満月寺観音堂","kana":"かいもんさんまんげつじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.11002793,"lng":135.9212681,"geo_status":"db","era":"明和3","year":1766,"year_source":"db","year_min":1766,"year_max":1766,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0127","desc":"琵琶湖畔に営まれた臨済宗寺院満月寺の本堂。入母屋造の三間堂で内部は瓦の四半敷とし，本尊木造聖観音座像（重要文化財）を安置する。近年の修理で正面の柱間装置を変更し，向拝を増設するなどの変更はあるが，湖上の浮御堂とともに一体の寺観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001622"},{"id":"00001623","register_sub_id":"101","register_pk":"102613","name":"海門山満月寺客殿","kana":"かいもんさんまんげつじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.10989945,"lng":135.92101624,"geo_status":"db","era":"宝暦4","year":1754,"year_source":"db","year_min":1754,"year_max":1754,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0128","desc":"琵琶湖に向かって東面して建ち，北側面に式台付大玄関を構える。屋根は入母屋造で，もとこけら葺。内部は，前列に八畳と十畳の客間，後列に内玄関と仏間を配し，正面及び南側面に広縁を廻す。四間取り形式の客殿の姿を良く伝える。地元大工吉兵衛の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001623"},{"id":"00001624","register_sub_id":"101","register_pk":"102614","name":"海門山満月寺山門","kana":"かいもんさんまんげつじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.11006669,"lng":135.92105172,"geo_status":"db","era":"文化9","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造楼門、瓦葺、建築面積3㎡","structure_material":"木造楼門","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0129","desc":"境内西北部の入口に西面して建つ楼門で，初層軸部の周囲に漆喰塗りの袴腰を付けたいわゆる竜宮造の形式になる。上層は桁行二間，梁間一間で四周各間に菱格子窓を構える。高欄や腰組などの細部に特色がある。扉はなく，東方正面に浮御堂を見通すことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001624"},{"id":"00001625","register_sub_id":"101","register_pk":"102615","name":"海門山満月寺茶室（玉鈎亭）","kana":"かいもんさんまんげつじちゃしつ（ぎょくこうてい）","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田1-16-18","lat":35.10970048,"lng":135.92096231,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0130","desc":"昭和９年の台風で倒壊した前身浮御堂の古材を天井などの一部に用いて建築，昭和６３年に客殿南から現在地に移築された。七畳下座床の席と四畳向切枡床の席が水屋を介して繋がっていたが，移築に伴い水屋を撤去，現在は２席が東西に接し，棟をＬ型に連ねる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001625"},{"id":"00012174","register_sub_id":"101","register_pk":"352974","name":"瓦屋寺開山堂","kana":"かわらやじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124312,"lng":136.183708,"geo_status":"db","era":"元禄13年(1700)／昭和前期改修","year":1700,"year_source":"db","year_min":1700,"year_max":1700,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-412","desc":"本堂の南西方の高台に建つ。開山堂、相の間、礼堂からなる。開山堂は方二間、宝形造、瓦葺で、土台上に粽付円柱を立て、台輪を廻し出三斗を組む。側面前方に花頭窓を穿ち、禅宗様の意匠をみせる。禅宗寺院の開山堂の形式をよく残しており貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012174"},{"id":"00012175","register_sub_id":"101","register_pk":"352975","name":"瓦屋寺経堂（海印蔵）","kana":"かわらやじきょうどう（かいいんぞう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124234,"lng":136.183882,"geo_status":"db","era":"享保10年（1725)","year":1725,"year_source":"db","year_min":1725,"year_max":1725,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡、輪蔵付","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-413","desc":"本堂の南方に北面して建つ。方三間、宝形造、桟瓦葺。角柱で組物は平三斗、各面中央間に桟唐戸をたてこみ、正面両端間のみ花頭窓を穿つ。内部中央に八角輪蔵を置く。四隅の火打梁上に太瓶束を立て四方に桁を廻し、側柱と海老虹梁で繋ぐ架構に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012175"},{"id":"00012178","register_sub_id":"101","register_pk":"352978","name":"瓦屋寺庫裏","kana":"かわらやじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124859,"lng":136.183889,"geo_status":"db","era":"明治4年","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積379㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-416","desc":"本堂後方に南面する。正面は、中央に向唐破風造の式台玄関を付け、東側に出入口二所を開き腰海鼠壁を施す。内部は前後二列に七室を配し、奥座敷は床の間、床脇、付書院を設け良質な意匠をもつ。土間上部に壮大な梁組をみせ、式台玄関の細部意匠も秀逸な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012178"},{"id":"00012173","register_sub_id":"101","register_pk":"352973","name":"瓦屋寺地蔵堂","kana":"かわらやじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124623,"lng":136.183506,"geo_status":"db","era":"正保年間(1644-1647)／昭和前期改修","year":1646,"year_source":"estimated","year_min":1644,"year_max":1647,"year_label":"正保年間(1644-1647)","structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-411","desc":"本堂西に渡廊下で接続する。桁行三間、梁間四間、切妻造、桟瓦葺。組物は舟肘木で、内部や小屋組は改変されているが、堂内後方仏壇の前面柱はもと来迎柱で、上部に三斗を組む。柱は角柱で、木太く、正面の桟唐戸もよく残る。本堂とともに伽藍を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012173"},{"id":"00012177","register_sub_id":"101","register_pk":"352977","name":"瓦屋寺鐘楼","kana":"かわらやじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124572,"lng":136.183837,"geo_status":"db","era":"正保年間(1644-1647)","year":1646,"year_source":"estimated","year_min":1644,"year_max":1647,"year_label":"正保年間(1644-1647)","structure":"木造、瓦葺、面積9.2㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"25-415","desc":"本堂前方で賓頭盧堂の北に建つ。方一間、切妻造、桟瓦葺で、礎盤上に一六面取角柱を四方転びに立て、腰貫、飛貫、頭貫で固める。組物は造らず、化粧棟木を受ける実肘木の絵様にわずかに装飾をみせる。木柄が太く堂々たる構えで、境内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012177"},{"id":"00012176","register_sub_id":"101","register_pk":"352976","name":"瓦屋寺賓頭盧堂","kana":"かわらやじびんずるどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124489,"lng":136.183853,"geo_status":"db","era":"文政元年(1818)","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-414","desc":"本堂前方に西面して建つ。方一間、宝形造、桟瓦葺。角柱で台輪を廻し、組物は出組の詰組で、軒は扇垂木とする。正面に桟唐戸をたてこみ、内部は土間で賓頭盧像を安置し、棹縁天井を張る。小規模ながら、細部まで禅宗様の意匠でまとめられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012176"},{"id":"00012172","register_sub_id":"101","register_pk":"352972","name":"瓦屋寺本堂","kana":"かわらやじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部瓦屋寺町436","lat":35.124648,"lng":136.183705,"geo_status":"db","era":"正保2年(1645)","year":1645,"year_source":"db","year_min":1645,"year_max":1645,"year_label":null,"structure":"木造平屋建、茅葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"25-410","desc":"箕作山の境内に南面する。桁行三間、梁間四間、入母屋造、茅葺で向拝一間。堂内は一室で中央後寄りに須弥壇、背面両端に脇壇を設ける。円柱に台輪を載せ組物は出三斗で、正面中備は頭貫下に蟇股、上に間斗束を重ねる。和様と禅宗様を巧みに取り入れた本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012172"},{"id":"00014041","register_sub_id":"101","register_pk":"508301","name":"観音正寺護摩堂","kana":"かんのんしょうじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14505278,"lng":136.16067222,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0491","desc":"繖山に所在する古刹の仏堂。地蔵堂南に西面して建つ。三間四方、正面入母屋造背面切妻造桟瓦葺で向拝が付く。内部は一室で棹縁天井とし、奥一間に仏壇を設ける。安永建立の元三大師堂の部材を再用して建立した近代の仏堂で、境内の変遷を知る上でも貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014041"},{"id":"00014040","register_sub_id":"101","register_pk":"508300","name":"観音正寺地蔵堂","kana":"かんのんしょうじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14510556,"lng":136.16059167,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0490","desc":"繖山に所在する古刹の小堂。本堂南に西面して建つ。二間四方宝形造桟瓦葺。丸柱で平三斗を置き、軒は一軒繁垂木。正面に切目縁と庇を設け、中央間を半蔀、両脇を花頭窓とする。内部は一室で奥半間を仏壇とし、虹梁を架ける。巡礼寺院の様相を伝える仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014040"},{"id":"00014039","register_sub_id":"101","register_pk":"508299","name":"観音正寺書院","kana":"かんのんしょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14459167,"lng":136.16116111,"geo_status":"db","era":"寛政8年(1796)","year":1796,"year_source":"db","year_min":1796,"year_max":1796,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積231㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0489","desc":"繖山に所在する古刹の書院。境内中央南寄りに西面する。入母屋造桟瓦葺で正面北寄りに唐破風玄関を構える。平面は六室とし、南に土間、北と東に入側縁を配す。上段の間は折上小組格天井とする書院座敷。江戸後期の姿をよく留め、山岳大寺院の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014039"},{"id":"00014045","register_sub_id":"101","register_pk":"508305","name":"観音正寺書院庭門","kana":"かんのんしょうじしょいんにわもん","category":"宗教","subcategory":"その他工作物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14478611,"lng":136.16081111,"geo_status":"db","era":"天保15年（1844)","year":1844,"year_source":"db","year_min":1844,"year_max":1844,"year_label":null,"structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0495","desc":"書院北側の庭園を矩折に囲む土塀の西面に開く。一間一戸薬医門で、切妻造桟瓦葺、軒は一軒疎垂木とする。本柱、控柱とも角柱で、間口に両開きの板戸を吊る。五平の本柱を冠木上まで貫通させて栓でとめるのは珍しい。書院と一体で残る近世遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014045"},{"id":"00014043","register_sub_id":"101","register_pk":"508303","name":"観音正寺鐘堂","kana":"かんのんしょうじしょうどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14443333,"lng":136.16126667,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、瓦葺、面積10㎡","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0493","desc":"繖山に所在する古刹の鐘堂。境内南端に位置する。切妻造本瓦葺、方一間八角柱内転びの鐘楼で、各間二本の角柱の間柱を立て、本柱と間柱を腰貫と二本の飛貫で連結する。両妻虹梁上に大瓶束をのせ、内側に虹梁を架け渡し鐘を吊る。延暦寺鐘楼と共通する構造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014043"},{"id":"00014044","register_sub_id":"101","register_pk":"508304","name":"観音正寺手水舎","kana":"かんのんしょうじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14485278,"lng":136.16075833,"geo_status":"db","era":"昭和3年頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、面積1.5㎡","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0494","desc":"繖山に所在する札所寺院の手水舎。書院庭門の北に建つ南北棟で西面する。切妻造銅板葺、石製控柱を添えた本柱二本を虹梁で繋ぎ、控柱を添えた肘木で腕木を支え、腕木は桁を受ける。本柱上に平三斗、虹梁中央に蟇股を置く。巡礼寺院の歴史的景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014044"},{"id":"00014042","register_sub_id":"101","register_pk":"508302","name":"観音正寺札堂","kana":"かんのんしょうじふだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県近江八幡市安土町石寺字繖山2","lat":35.14496667,"lng":136.16072222,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0492","desc":"札所寺院の小堂。護摩堂南に西面して建つ。桁行三間、梁間二間、切妻造桟瓦葺平入、組物は大斗絵様肘木。正面は各間に虹梁形差物を入れ、半蔀を吊る。内部は一室で奥半間を仏壇とし虹梁を架ける。もとは三十三観音を祀り、巡礼寺院における特徴的な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014042"},{"id":"00003433","register_sub_id":"101","register_pk":"104423","name":"玉宝院本堂","kana":"ぎょくほういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市北清水町296","lat":35.143585,"lng":136.21698,"geo_status":"db","era":"天保4","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積137㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0223","desc":"集落のほぼ中央に位置する浄土宗本堂。桁行３間，梁間５間，入母屋造，正面向拝１間で，梁行きを前後に分け前方２間を外陣とし，後方は中央の内陣と左右脇陣を取る。組物や蟇股など細部意匠に優れ，後陣の下屋屋根を唐破風状にするなど，特異な納まりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003433"},{"id":"00013746","register_sub_id":"101","register_pk":"505299","name":"弘誓寺表門","kana":"ぐぜいじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13393611,"lng":136.19948333,"geo_status":"db","era":"享保6年(1721)","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 477","desc":"境内の南辺中央に位置し南面する四脚門。切妻造本瓦葺で両開き板戸を建てる。本柱は円柱で棟木下まで伸ばし、角柱の控柱の間に海老虹梁を架けて固め、桁行は楣を渡して中央に龍彫を嵌めた蟇股を載せる。急勾配でたちの高い屋根が参道起点の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013746"},{"id":"00006408","register_sub_id":"101","register_pk":"107391","name":"弘誓寺経蔵","kana":"ぐせいじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190327,"lng":136.157227,"geo_status":"db","era":"天保6","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積28㎡","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0250","desc":"鐘楼の西に隣接し、宝形造桟瓦葺で、正面に向拝１間を付ける。一軒疎垂木で軒を塗り込め、向拝には虹梁や木鼻に絵様を施し、中備は大きく猪目を開ける特異な形になる。堂内は１室で、床拭板張、棹縁天井で、三方に棚を付設する。軽快な佇まいの経蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006408"},{"id":"00013742","register_sub_id":"101","register_pk":"505291","name":"弘誓寺庫裏","kana":"ぐぜいじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13438056,"lng":136.199575,"geo_status":"db","era":"文化2年(1805)","year":1805,"year_source":"db","year_min":1805,"year_max":1805,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積310㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 473","desc":"本堂西に玄関を介して接続する。切妻造桟瓦葺。南面し、切妻造の玄関を付す。妻飾は二重虹梁大瓶束笈形付で脇に海老虹梁を架け華美に飾る。平面は南半を台所、玄関、表の間、北半は二列六室として北西に床付座敷を配する。本堂とともに伽藍枢要の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013742"},{"id":"00006406","register_sub_id":"101","register_pk":"107389","name":"弘誓寺庫裏門","kana":"ぐせいじくりもん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190624,"lng":136.157516,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0253","desc":"庫裏の正面、太鼓堂の北側に連続して建つ。切妻造桟瓦葺で、太鼓堂側に潜戸と両開戸を立て、北側に部屋を設ける長屋門である。外壁は漆喰塗で、腰に竪板を張り、部屋正面には出格子窓を付ける。簡潔ながら、桁行８．８ｍに及ぶ規模を有し風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006406"},{"id":"00013743","register_sub_id":"101","register_pk":"505293","name":"弘誓寺玄関","kana":"ぐぜいじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13434444,"lng":136.199775,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺一部檜皮葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 474","desc":"庫裡・本堂間の中央に位置する。庫裏と本堂を結ぶ廊下の前方に式台、背後に四室を配する。屋根は切妻造桟瓦葺で、式台は唐破風造の檜皮葺。背後の四室は西に床付の座敷を配し、中央に二室、東に一室配する。式台の虹梁や破風廻りに彫刻を多用した大型の玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013743"},{"id":"00006407","register_sub_id":"101","register_pk":"107390","name":"弘誓寺鐘楼","kana":"ぐせいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.19029869,"lng":136.15728092,"geo_status":"db","era":"万治3","year":1660,"year_source":"db","year_min":1660,"year_max":1660,"year_label":null,"structure":"木造、瓦葺、面積8.5㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0249","desc":"境内の東南隅、通り近くに位置する。石積基壇上に建ち、桁行１間梁間１間で、四方を吹放す。南北棟の切妻造本瓦葺。柱は内転びの円柱で、柱上に大斗絵様肘木を置き、一軒疎垂木の化粧屋根裏とする。直截簡明な姿で、笈形など細部も秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006407"},{"id":"00013745","register_sub_id":"101","register_pk":"505297","name":"弘誓寺鐘楼堂","kana":"ぐぜいじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.1338,"lng":136.19960833,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、建築面積13㎡","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 476","desc":"境内の東南に位置。高い石積基壇の上に四本の円柱を内転びに立て、腰貫、内法貫、頭貫で軸部を固める。組物は三斗で中備は蟇股である。妻は虹梁大瓶束として棟木を受ける。屋根は切妻造本瓦葺。境内では現存最古と考えられる。境内東南隅の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013745"},{"id":"00006405","register_sub_id":"101","register_pk":"107388","name":"弘誓寺太鼓堂","kana":"ぐせいじたいこどう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190552,"lng":136.157471,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積28㎡、鼓楼付","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0252","desc":"茶所の北側に隣接して建つ。境内からは切妻造桟瓦葺に東西棟の入母屋造桟瓦葺の２階をのせるが、道路側からは２層櫓風の外観に見せる。２階は各面とも中央に柱を立てその両側に窓を穿ち、内部の中央に太鼓を吊る。真宗寺院らしい景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006405"},{"id":"00006749","register_sub_id":"101","register_pk":"107732","name":"弘誓寺茶所","kana":"ぐせいじちゃじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.190468,"lng":136.15739938,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造2階建、瓦葺、建築面積120㎡","structure_material":"木造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0251","desc":"本堂の前方、表大門の北に隣接して建つ。入母屋造桟瓦葺の２階建で、道路側に短い切妻屋根を出す。内部は南端に土間を設け、その北側西寄りに棹縁天井の広い板間とする。２階も畳敷などの部屋を間仕切り、小屋組をみせる。真宗寺院の茶所の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006749"},{"id":"00013744","register_sub_id":"101","register_pk":"505295","name":"弘誓寺中門","kana":"ぐぜいじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市建部下野町282","lat":35.13424722,"lng":136.19962778,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"25 － 475","desc":"玄関への入口となる門。一間薬医門で柱間に両開きの腰舞良戸を建て屋根は桟瓦葺。背面に控柱を立て本柱と梁で繋ぎ、軒桁を受ける。垂木は疎らで反りが強い。板戸の橘の透彫や鬼瓦の井桁紋、瓦当の橘紋などに井伊家との関連を示す。小規模ながら格調ある門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013744"},{"id":"00006403","register_sub_id":"101","register_pk":"107386","name":"弘誓寺本堂","kana":"ぐせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市躰光寺町979","lat":35.19067,"lng":136.157104,"geo_status":"db","era":"宝暦3","year":1753,"year_source":"db","year_min":1753,"year_max":1753,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積657㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"25 － 0248","desc":"境内の中央に東面して建つ。入母屋造本瓦葺で、正面に３間向拝を付け、桁行２２ｍ、梁間２０ｍに及ぶ。妻は二重虹梁大瓶束で、花頭窓を穿つ。内部は浄土真宗本堂の典型的な平面で、内陣は後門形式。近世中葉の近江地方における大規模で良質な真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006403"},{"id":"00011522","register_sub_id":"101","register_pk":"210472","name":"荒神山神社神楽殿","kana":"こうじんやまじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23339694,"lng":136.19770194,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0396","desc":"境内の西南角に東面する。桁行三間、梁間三間、入母屋造、桟瓦葺。前方二間は舞台で正側面を半蔀とし、祭事には開放する。引違板戸を介し後方一間は楽屋で、背面中央間を出入口とする他は漆喰壁とする。保存状態も良く神社の祭事に欠かせない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011522"},{"id":"00011521","register_sub_id":"101","register_pk":"210471","name":"荒神山神社神饌所","kana":"こうじんやまじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23352889,"lng":136.19794389,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0395","desc":"拝殿の東縁に接続する。桁行二間、梁間二間、入母屋造、桟瓦葺。南面二間は中敷居を入れ、舞良戸を建て込む。内部は板敷の一室で、西北角に物入を作り、西面に板戸の出入口を設ける。妻飾は木連格子で、拝殿と一体となった社殿景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011521"},{"id":"00011523","register_sub_id":"101","register_pk":"210473","name":"荒神山神社鳥居","kana":"こうじんやまじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1872地先","lat":35.23389389,"lng":136.19755194,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"石造、高さ9.0m、幅9.0m","structure_material":"石造","registered":"2017.05.02(平成29.05.02)","register_no":"25-0397","desc":"荒神山下の参道入口に立つ。柱間九・〇メートル、高さ九・〇メートルの大規模な石造明神鳥居。礎石上に直径約八六センチメートルの石柱を内転びで立て、貫と島木、笠木で固める。地元有志の発起の下、立てられたもので、神社の歴史を今に伝える鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011523"},{"id":"00011519","register_sub_id":"101","register_pk":"210469","name":"荒神山神社拝殿","kana":"こうじんやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23352194,"lng":136.19788194,"geo_status":"db","era":"明治28年","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0393","desc":"本殿の前面に渡殿を介して建つ。桁行三間、梁間三間、入母屋造、桟瓦葺。入母屋造妻入の向拝一間を付け正側面に縁を廻らす。組物は舟肘木で妻飾は木連格子とする。正背面中央間を両折桟唐戸とする以外は半蔀戸を吊る。優美な向拝が社殿景観を整える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011519"},{"id":"00011518","register_sub_id":"101","register_pk":"210468","name":"荒神山神社本殿","kana":"こうじんやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23361306,"lng":136.19782694,"geo_status":"db","era":"明治12年／昭和18年・平成8年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0392","desc":"荒神山山頂に南面して建つ。三間社流造、向拝一間付の社殿。前室付とし正面に両折桟唐戸を装置する。総檜造の上質な造りで、向拝の水引虹梁や蟇股に彫刻が見られるものの装飾が少なく、柱上は舟肘木、妻飾は豕扠首とするなど、復古的な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011518"},{"id":"00011520","register_sub_id":"101","register_pk":"210470","name":"荒神山神社渡殿","kana":"こうじんやまじんじゃわたりどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県彦根市清崎町1931","lat":35.23356111,"lng":136.197845,"geo_status":"db","era":"明治28年／昭和18年・平成8年改修","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積10㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"25-0394","desc":"本殿と拝殿を繋ぐ南北棟の建物。桁行二間、梁間一間、切妻造銅板葺。両側面は腰長押、内法長押を内外に廻らし、格子窓を入れる。内部は拭板張で棹縁天井を張る。組物は舟肘木で拝殿と共通した意匠を見せ、社殿景観を構成する要素の一つとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011520"},{"id":"00003435","register_sub_id":"101","register_pk":"104425","name":"弘誓寺本堂","kana":"こうせいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市中一色町380","lat":35.14577424,"lng":136.2449888,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"25 － 0225","desc":"桁行約１４ｍ，梁間約１５ｍ，入母屋造で，正面に３間分の広い向拝を付す。三方吹き放しの縁を回した外陣の先に一段高く矢来を取り，その奥中央に後門形式の内陣，両脇に余間を配す。縁先に軒支柱を立てた形式で，近世末浄土真宗大型本堂の姿をよくとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003435"},{"id":"00004985","register_sub_id":"101","register_pk":"105975","name":"西願寺本堂","kana":"さいがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県近江八幡市船木町1246","lat":35.14040162,"lng":136.07637331,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、茅葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"25 － 0232","desc":"前半が外陣，後半が内陣と両脇陣からなる平面構成で，周囲に広縁等を廻し，正面に向拝を設ける。屋根は入母屋造，茅葺で，４周に桟瓦葺の下屋を廻し，向拝は一段切り上げる。外観民家風の浄土宗本堂で，年代は構造形式や細部から１７世紀中期頃と推定される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004985"},{"id":"00002281","register_sub_id":"101","register_pk":"103271","name":"西教寺灌頂蔵","kana":"さいきょうじかんちょうぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08183466,"lng":135.86612138,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0157","desc":"浴室と内司課蔵との間に南面して建つ。切妻造・平入，桟瓦葺で，南面中央に観音開扉を設け，蔵前の庇をつける。軒廻りは一軒で垂木を塗籠め，外壁は腰を縦板張とする。内部は２階建で内司課蔵よりたちが高く，軒廻りの扱いにも造形の違いがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002281"},{"id":"00002274","register_sub_id":"101","register_pk":"103264","name":"西教寺観瀾亭","kana":"さいきょうじかんらんてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081406,"lng":135.865875,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0150","desc":"伽藍の西側，重文の客殿と新書院の間の背後に建つ。南側入母屋造・北側寄棟造で桟瓦葺，平屋建。内部は床の間・棚付の８畳間と棚のある６間畳の２室からなる。内外とも朱の砂壁で，面皮長押を用い，波をあしらった板欄間など，数寄屋風の瀟洒な建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002274"},{"id":"00002272","register_sub_id":"101","register_pk":"103262","name":"西教寺客殿通用門","kana":"さいきょうじきゃくでんつうようもん","category":"宗教","subcategory":"その他工作物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081062,"lng":135.867142,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、檜皮葺、間口2.1m","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0148","desc":"客殿の南面を区切る板塀の間に設けられた平唐門。面取角柱の親柱に腕木をつけて軒桁を受け，棟木は舟肘木で受ける。垂木は大疎とし，屋根は檜皮葺，妻に彫物懸魚をつける。簡素な意匠であるが，全体の比例が良好で，近代和風の建築技量があらわれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002272"},{"id":"00002271","register_sub_id":"101","register_pk":"103261","name":"西教寺御廟","kana":"さいきょうじごびょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08107307,"lng":135.86552032,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0147","desc":"伽藍の南西，本堂の西の高台にある。四半敷の基壇に建ち，平面は桁行１間・梁間２間だが方形で，正面に向拝を設ける。屋根は宝形造で，軒は二軒繁垂木，組物が二手先で先端に絵様をつけた尾垂木を組む。蟇股や手挟など彫刻が豊かで，江戸末期の造形を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002271"},{"id":"00002285","register_sub_id":"101","register_pk":"103275","name":"西教寺宗祖大師殿","kana":"さいきょうじしゅうそだいしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080486,"lng":135.86673,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積312㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0161","desc":"明治１１年真盛宗別派独立に伴い，本堂南の一段低い地に建設された。入母屋造・桟瓦葺，正面軒唐破風付で，丸柱・舟肘木の軸部，疎垂木・木舞打の軒廻り，擬宝珠高欄付の縁など，格式の高い住宅建築の意匠になる。内部の小組格天井や筬欄間なども繊細である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002285"},{"id":"00002286","register_sub_id":"101","register_pk":"103276","name":"西教寺宗祖大師殿唐門","kana":"さいきょうじしゅうそだいしでんからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080345,"lng":135.867004,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造四脚門、瓦葺、間口4.2m、左右袖塀全長3m及び築地塀全長38m付","structure_material":"木造四脚門","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0162","desc":"大師殿の正面，東面して建つ１間１戸の四脚門で，両側に折曲がりの築地塀が延びる。屋根は檜皮葺で，入母屋造・前後軒唐破風付。組物は三斗組と簡素だが，虹梁上に配された龍や獅子など多彩な彫刻，彫物欄間や板欄間，精緻な飾金具など，華やかな造形である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002286"},{"id":"00002287","register_sub_id":"101","register_pk":"103277","name":"西教寺宗祖大師殿通用門","kana":"さいきょうじしゅうそだいしでんつうようもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080544,"lng":135.867004,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平唐門、瓦葺、間口3.0m、左右袖塀全長3m及び築地塀全長43m付","structure_material":"木造平唐門","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0163","desc":"大正期の伽藍整備の一環で建設された。大師殿の西側，基壇上に建つ１間１戸の平唐門で，両側に折曲がりの築地塀が延びる。屋根は檜皮葺で，軒は大疎垂木。通用門のため簡素なつくりであるが，規模が大きく，棟通りの大柄な蟇股が意匠の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002287"},{"id":"00002288","register_sub_id":"101","register_pk":"103278","name":"西教寺宗祖大師殿水屋","kana":"さいきょうじしゅうそだいしでんみずや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080601,"lng":135.867172,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造、瓦葺、建築面積4.4㎡","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0164","desc":"唐門などともに大正期の伽藍整備で建設された。六角形平面で円形花型の水盤を覆い，桟瓦葺屋根で宝珠をのせる。長押で固めた６本柱で，六角に組んだ桁を支える。通用門と対面した位置に建ち，大師殿伽藍の北側の景観上，欠かせない存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002288"},{"id":"00002273","register_sub_id":"101","register_pk":"103263","name":"西教寺書院","kana":"さいきょうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081608,"lng":135.866089,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積490㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0149","desc":"大正６年の不断（常）念仏十五万大法会に際し客殿北側に対面して建てられた。桁行１３間，梁間９間，入母屋造，桟瓦葺で，内部は南側４室の表書院と北側６室の裏書院からなる。伝統的な書院造を踏襲しながら，全体に木太く，端正で力強い造形となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002273"},{"id":"00002275","register_sub_id":"101","register_pk":"103265","name":"西教寺新座敷","kana":"さいきょうじしんざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081207,"lng":135.865875,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0151","desc":"重文の客殿の背後，南西に建つ。東西棟で，東面切妻造・西面入母屋造，桟瓦葺，平屋建。内部は観瀾亭と同じく床の間・棚付の８畳間と棚のある６畳間の２室からなる。内外とも白漆喰壁だが，柱や長押にはベンガラを塗る。簡素で端正な数寄屋風の建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002275"},{"id":"00002282","register_sub_id":"101","register_pk":"103272","name":"西教寺正教蔵","kana":"さいきょうじせいきょうぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08125942,"lng":135.86677904,"geo_status":"db","era":"明治12","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0158","desc":"本堂の東側にある２階建の土蔵。切妻造・桟瓦葺で，西面には切妻造・起り屋根の庇を設け，蔵前とする。外壁は上部白漆喰塗，下部縦板張とし，蔵前は柱から軒裏まで漆喰で塗り込める。庇の虹梁絵様や誇張的な板蟇股などに，明治初期の意匠が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002282"},{"id":"00002277","register_sub_id":"101","register_pk":"103267","name":"西教寺内司課客殿","kana":"さいきょうじないしかきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081821,"lng":135.865891,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0153","desc":"書院の北東にある管長の執務室で，南に池を望む。南北棟で，屋根は寄棟造・桟瓦葺，軒を疎垂木・木舞打とし，側桁は舟肘木で受ける。内部は天井がやや高い床付の８畳間と６畳間からなるが，猿頬面取の竿縁天井など，細部には繊細な造形がみられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002277"},{"id":"00002280","register_sub_id":"101","register_pk":"103270","name":"西教寺内司課蔵","kana":"さいきょうじないしかくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081841,"lng":135.866028,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積26㎡","structure_material":"土蔵造2階建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0156","desc":"内司課は管長のための空間になっている。蔵は書院の北側，内司課庫裏の東側に南面して建つ。切妻造・平入，桟瓦葺で，南面中央に観音開扉を設け，ここに蔵前の切妻造の庇をつける。庇は軒裏まで塗籠め，外壁は腰を縦板張とする。小規模だが，丁寧なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002280"},{"id":"00002278","register_sub_id":"101","register_pk":"103268","name":"西教寺内司課庫裏","kana":"さいきょうじないしかくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.081829,"lng":135.865936,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0154","desc":"書院の北東にあり，管長の居住に用いられたもので，内司課客殿の東側に並立して建つ。南北棟の入母屋造・桟瓦葺で，妻は木連格子とする。南側に座敷を配し，北側に台所や風呂場を設ける。内向きのため規模は大きくないが，客殿と一連の造形を具備している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002278"},{"id":"00002279","register_sub_id":"101","register_pk":"103269","name":"西教寺内司課渡廊下","kana":"さいきょうじないしかわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.0817688,"lng":135.86586072,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0155","desc":"書院の北西隅から内司課客殿の南西隅に続く渡廊下。幅約３尺で，軸部は角柱・舟肘木で丸桁を受け，丸桁を虹梁で繋ぎ，虹梁上の蟇股・舟肘木で棟木をうける。軒は疎垂木・木舞打。蟇股や虹梁の形状が優美で，いずれの部材も面取するなど，丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002279"},{"id":"00002284","register_sub_id":"101","register_pk":"103274","name":"西教寺納骨堂","kana":"さいきょうじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08094324,"lng":135.86663086,"geo_status":"db","era":"大正6頃","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0160","desc":"入母屋造・桟瓦葺の本屋を高くして，周囲に庇を廻す。軒は本屋・庇とも一軒疎垂木・木舞打で軽快につくる。内部は外陣・内陣の構成になり，内陣奥に通し仏壇を設ける。本堂の東南に建ち，棟を直交させ複雑で動きのある外観で，景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002284"},{"id":"00002283","register_sub_id":"101","register_pk":"103273","name":"西教寺水屋","kana":"さいきょうじみずや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08083396,"lng":135.86640359,"geo_status":"db","era":"昭和19","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造、瓦葺、建築面積4.4㎡","structure_material":"木造","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0159","desc":"本堂南に建つ。長方形平面で，中央に細長い水盤を置く。軸部は角柱を建てて，斜材で補強し，三斗を組んで桁を受け，天井は格天井とする。屋根は入母屋造・本瓦葺，二軒繁垂木で深い軒をつくり，小規模な建築であるが，堂々とした外観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002283"},{"id":"00002276","register_sub_id":"101","register_pk":"103266","name":"西教寺浴室","kana":"さいきょうじよくしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08183142,"lng":135.86637496,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、鉄板葺、建築面積41㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2001.08.28(平成13.08.28)","register_no":"25 － 0152","desc":"書院の北東にあり，僧侶の浴室として使用されてきた。ＲＣ造，南北棟の切妻造・妻入で，屋根は銅板葺。平面は棟通りで左右にわかれ，前半が脱衣室，後半が浴槽になる。柱，長押，舟肘木さらに妻の破風や懸魚など，木造の形式をＲＣで忠実に再現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002276"},{"id":"00014046","register_sub_id":"101","register_pk":"508306","name":"沙沙貴神社旧源照殿（霜楓園）","kana":"ささきじんじゃきゅうげんしょうでん（そうふうえん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県近江八幡市安土町常楽寺字四ノ坪2","lat":35.13653611,"lng":136.135025,"geo_status":"db","era":"大正8年／昭和37年頃移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"25 - 0496","desc":"東廻廊外側に位置する祭儀控え室の座敷棟。入母屋造桟瓦葺。北から八畳と六畳、南に三畳と四畳半を東西に並べ、北東に矩折れに縁を廻す。八畳は書院座敷で、四畳半は北に床と西に床脇、三畳は南に丸形の下地窓とし茶室の設えとする。格調高い近代の座敷棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014046"},{"id":"00002637","register_sub_id":"101","register_pk":"103627","name":"地蔵院本堂","kana":"じぞういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市大沢町345","lat":35.136665,"lng":136.251358,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0188","desc":"町内唯一の真言宗寺院の本堂。桁行梁間各３間，向拝１間，入母屋造，桟瓦葺で，方柱上に平三斗組物，中備に蟇股を載せ，１軒繁垂木の軒を受ける。内部は内外陣に仕切り，内陣奥には丸柱を立て凸型に仏壇を構える。江戸末期の小規模密教本堂の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002637"},{"id":"00002396","register_sub_id":"101","register_pk":"103386","name":"實成坊門","kana":"じっせいぼうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080627,"lng":135.867538,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0165","desc":"實成坊は近世より続く西教寺の塔頭のひとつである。敷地南の門は１間１戸の薬医門で，軒が疎垂木，屋根が桟瓦葺。組物は簡素な絵様肘木であるが，妻の虹梁・大瓶束架構を見所とする。両側に続く穴太衆積の石垣と一体となって参道景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002396"},{"id":"00003106","register_sub_id":"101","register_pk":"104096","name":"浄華寺本堂","kana":"じょうけいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市下里町296","lat":35.13998272,"lng":136.25651183,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積131㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0202","desc":"仏堂と庫裏を兼ねた堂庫裏形式の浄土宗本堂。屋根は入母屋造，茅葺（現在鉄板仮覆）の四方に桟瓦葺の庇を付ける農家風の外観となる。間仕切や床，天井などに何回かの改造があるが，近世初期の小規模な道場建築のありさまをしのぶことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003106"},{"id":"00002638","register_sub_id":"101","register_pk":"103628","name":"昌善寺本堂","kana":"しょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市南菩提寺町680","lat":35.14188239,"lng":136.23157958,"geo_status":"db","era":"明治15","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積171㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0189","desc":"集落の南端にある浄土宗寺院の本堂。桁行５間，梁間７間，向拝１間，入母屋造，桟瓦葺で，前方外陣の奥，中央を内陣，その両脇を脇陣とし，内陣の奥に寄せて大型の須弥壇を構える。平面形式や内陣廻りの派手な彫刻・極彩色に明治期の新たな傾向が看取される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002638"},{"id":"00002641","register_sub_id":"101","register_pk":"103631","name":"白鬚神社社務所","kana":"しらひげじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県高島市鵜川215","lat":35.27465362,"lng":136.01131954,"geo_status":"db","era":"昭和7","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0192","desc":"比良山を神体山とする古社の社務所。田字型平面の座敷部の奥に貴賓室，前方に玄関・札所などを配する。入母屋造，妻入で唐破風造の式台を構え，一方に切妻屋根の突出部を付す正面の構えは中世の主殿を彷彿とさせ，古風な細部装飾と併せ巧みな意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002641"},{"id":"00002400","register_sub_id":"101","register_pk":"103390","name":"真盛園講堂（旧専門学寮講堂）","kana":"しんせいえんこうどう（きゅうせんもんがくりょうこうどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.08114128,"lng":135.868408,"geo_status":"db","era":"昭和12／平成10移築","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0169","desc":"大正９年に開設された真盛派の僧侶学校である専門学寮の講堂として建てられた。ほぼ方形の平面で，寄棟造・桟瓦葺の屋根を架け，４周に擬宝珠高欄を廻す。疎垂木の軒や舟肘木，細やかな部材構成など，伝統的な住宅の形式を近代の造形感覚で具現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002400"},{"id":"00000695","register_sub_id":"101","register_pk":"101685","name":"新善光寺山門","kana":"しんぜんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市林256","lat":35.02881281,"lng":136.02319522,"geo_status":"db","era":"明治35頃","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造楼門，瓦葺，建築面積70㎡","structure_material":"木造楼門","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0043","desc":"本堂の正面に建つ大規模な三間三戸楼門で，門扉はなく側面の板壁のみの極めて開放的な造りになる。虹梁型の内法貫及び繋梁で上部を固める。軒廻りは尾垂木付，縁腰組は拳鼻付の三手先詰組とし，二軒繁垂木で深い軒を支えた重厚な造りとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000695"},{"id":"00000694","register_sub_id":"101","register_pk":"101684","name":"新善光寺本堂","kana":"しんぜんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県栗東市林256","lat":35.02928435,"lng":136.02366676,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積308㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0042","desc":"鎌倉時代の創建と伝え，本尊は善光寺阿弥陀如来の分身を祀る古刹で，本堂は善光寺に倣って内々陣，内陣，外陣を一体的に造る撞木造とし，地下には「胎内巡り」を設ける。外陣は正側面の入母屋屋根に軒唐破風を付加するなど賑やかに飾る大建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000694"},{"id":"00004139","register_sub_id":"101","register_pk":"105129","name":"神明神社本殿","kana":"しんめいじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市南清水町174","lat":35.14254065,"lng":136.21604475,"geo_status":"db","era":"寛政2","year":1790,"year_source":"db","year_min":1790,"year_max":1790,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"25 － 0231","desc":"三間社春日造の社殿建築。身舎柱は欅材で間口３間奥行２間の一室とし，正側面に縁を巡らし，正面には１間の向唐破風を設ける。組物は出三斗とし，軒は二軒繁垂木，背面妻は豕扠首組，屋根は銅板葺である。町内唯一の三間社春日造の近世遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004139"},{"id":"00003246","register_sub_id":"101","register_pk":"104236","name":"杉尾神社本殿","kana":"すぎおじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町杉山73","lat":34.84730366,"lng":136.01698767,"geo_status":"db","era":"宝永4","year":1707,"year_source":"db","year_min":1707,"year_max":1707,"year_label":null,"structure":"木造平屋建、柿葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0206","desc":"一間社流造の社殿で，覆屋に収められている。棟札より宝永４年の建築であることが知られる。木柄が太く，細部も大ぶりな点に特徴があり，現状では彩色部分と白木の部材が混在している。滋賀県下に多数存在する一間社社殿の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003246"},{"id":"00006404","register_sub_id":"101","register_pk":"107387","name":"スミス記念堂（旧須美壽記念禮拜堂）","kana":"すみすきねんどう（きゅうすみすきねんれいはいどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県彦根市本町3-58","lat":35.27388952,"lng":136.24930917,"geo_status":"db","era":"昭和6／平成19移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"25 － 0254","desc":"入母屋造妻入桟瓦葺で、正面に唐破風造銅板葺の１間向拝を付けるもと教会礼拝堂。正面３間に桟唐戸をたて、側面前寄り３間は窓を設ける。和風を基調としながら、十字架や葡萄、鳩などをモチーフとした彫刻や金具を施す。昭和初期の和風教会堂として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006404"},{"id":"00002399","register_sub_id":"101","register_pk":"103389","name":"禅明坊門","kana":"ぜんめいぼうもん","category":"宗教","subcategory":"その他工作","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080395,"lng":135.868073,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0168","desc":"１間１戸高麗門の形式で，親柱を上部に延ばして直接棟木を受け，軒は疎垂木，屋根は桟瓦葺とする。親柱を結ぶ内法虹梁と木鼻に施した絵様や，親柱足元の八艘飾などが，意匠の見所となっている。参道の北側の東端に位置し，参道らしい連続性を保っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002399"},{"id":"00002397","register_sub_id":"101","register_pk":"103387","name":"禅林坊門","kana":"ぜんりんぼうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080544,"lng":135.867416,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0166","desc":"西教寺の塔頭は，本堂前より東の琵琶湖に向かって延びる参道南にある。１間１戸薬医門の形式で，軒は疎垂木，屋根は桟瓦葺，妻飾は蟇股とする。木鼻や蟇股などの絵様細部に江戸末期らしい造形がある。北にある實成坊と対になって，参道空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002397"},{"id":"00003105","register_sub_id":"101","register_pk":"104095","name":"宗林寺本堂","kana":"そうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市南花沢町588","lat":35.125118,"lng":136.258286,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積189㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0201","desc":"江戸時代末期に建てられた入母屋造，桟瓦葺の浄土真宗本堂。比較的小規模ながら，内外陣境の支輪付出組組物の構えや虹梁の彫刻など，細部は本格的。内陣の仏壇や余間後方の部屋に改造を受けているが，なお当初の形式を良く残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003105"},{"id":"00003247","register_sub_id":"101","register_pk":"104237","name":"高宮神社本殿","kana":"たかみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町多羅尾646","lat":34.813515,"lng":136.038162,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0207","desc":"一間社流造，檜皮葺の社殿。棟札より安政６年の新築で，近江蒲生郡八幡町の名工高木作右衛門が棟梁を努めたことが知られる。同種の社殿としてはやや大きく，身舎を内陣・下陣に分けるなど形式を整えている。中規模一間社の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003247"},{"id":"00012955","register_sub_id":"101","register_pk":"368035","name":"太郎坊宮阿賀神社一の鳥居","kana":"たろうぼうぐうあがじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町780-2","lat":35.11720278,"lng":136.18268889,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造、間口5.4m","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 438","desc":"八風街道沿いにある参道入口に南面して建つ。石造の明神鳥居で、足元径0・6メートルの内転び円柱に貫を通し、反りのある島木笠木を載せる。北に延びる参道の先に赤神山を臨み、神社の入口を象徴するとともに参道景観を彩る大鳥居として参拝者に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012955"},{"id":"00012947","register_sub_id":"101","register_pk":"368027","name":"太郎坊宮阿賀神社永安殿","kana":"たろうぼうぐうあがじんじゃえいあんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11801389,"lng":136.18184722,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、銅板葺、建築面積43㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 430","desc":"拝殿南側の崖下に東面して建つ神楽演奏所兼社務所。入母屋造銅板葺妻入の二階建で、参道石段に面する正面に唐破風玄関を付す。一階に大座敷、二階に2室を配し、二階の北西二面に掃出しの縁を廻して拝殿に接続する。近代に発展した境内の様相を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012947"},{"id":"00012952","register_sub_id":"101","register_pk":"368032","name":"太郎坊宮阿賀神社絵馬殿","kana":"たろうぼうぐうあがじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11775278,"lng":136.18209167,"geo_status":"db","era":"大正14年","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 435","desc":"境内中心部南方の境内最下部にあり、参道石段に東面して建つ。切妻造桟瓦葺、桁行3間梁間2間の1間毎に柱を立てる。組物は舟肘木、妻飾は叉首組、一軒疎垂木で化粧屋根裏とする。奈良県技師・岸熊吉の設計による、簡明かつ整然としたつくりの近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012952"},{"id":"00012946","register_sub_id":"101","register_pk":"368026","name":"太郎坊宮阿賀神社神楽殿","kana":"たろうぼうぐうあがじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11802778,"lng":136.18168889,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 429","desc":"拝殿背面に東面して建つ。入母屋造銅板葺妻入で、正側面に縁を廻す。正面は開放とし、側面2間に半蔀、背面3間の中央間に板扉を備える。内部は板敷、折上小組格天井の一室で、組物は平三斗、一軒扇垂木である。拝殿と一体で社頭景観の中核を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012946"},{"id":"00012949","register_sub_id":"101","register_pk":"368029","name":"太郎坊宮阿賀神社祭器庫","kana":"たろうぼうぐうあがじんじゃさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11809167,"lng":136.18213889,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 432","desc":"参道石段を挟んで長楽殿に対面して建つ。置屋根形式の切妻造妻入、土蔵造二階建で、西面に扉口を設けて吹放し下屋を付す。外壁は漆喰塗、腰縦板張で、鉢巻二段を廻し、西南二面に小窓を穿つ。立体的に構成された参道石段沿いの境内景観の添景となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012949"},{"id":"00012942","register_sub_id":"101","register_pk":"368022","name":"太郎坊宮阿賀神社参拝所","kana":"たろうぼうぐうあがじんじゃさんぱいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11805,"lng":136.18145,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 425","desc":"本殿前に東面して建つ。入母屋造銅板葺の渡殿を核として正面中央に切妻造の向拝を設け、背面に切妻造吹放しの幣殿を出して接続する本殿の側背面に下屋状の屋根を廻す。本殿と一体化した複雑な屋根を形成し、山腹に広がる境内景観の象徴的存在となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012942"},{"id":"00012944","register_sub_id":"101","register_pk":"368024","name":"太郎坊宮阿賀神社授与所","kana":"たろうぼうぐうあがじんじゃじゅよしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11809722,"lng":136.181525,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、銅板葺、建築面積2.9㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 427","desc":"参拝所の正面石段下の北脇に南面して建つ。入母屋造銅板葺の妻を正面として、背面を岩壁の窪みに入れ込む。正面間口は楣を通して硝子窓4枚を入れ、西側面に出入口を設ける。壁は簓子下見板張とする。岩峰中腹に形成された独特な社頭景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012944"},{"id":"00012954","register_sub_id":"101","register_pk":"368034","name":"太郎坊宮阿賀神社中門","kana":"たろうぼうぐうあがじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2251","lat":35.11752778,"lng":136.18240556,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造、面積8.6㎡","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 437","desc":"絵馬殿南方の参道石段下半部の踊場に建つ。総花崗石造、四方吹放しの長方形平面で、切妻造妻入、反りのある流し石板葺である。軸部は内転びの円柱を木鼻付の貫と梁桁でつなぎ、貫上中央に蟇股を置く。不動明王拝所と同じく、昭和初期の石工技術の高さを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012954"},{"id":"00012948","register_sub_id":"101","register_pk":"368028","name":"太郎坊宮阿賀神社長楽殿","kana":"たろうぼうぐうあがじんじゃちょうらくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11807222,"lng":136.18177778,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造及び鉄筋コンクリート造平屋地下一階建、瓦葺及び銅板葺、建築面積154㎡、階段棟付","structure_material":"木造及び鉄筋コンクリート造平屋地下一階建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 431","desc":"永安殿南側の崖下に東面して建つ集会施設。入母屋造桟瓦葺妻入の平屋建で、参道石段側の正面に唐破風玄関を設け、東北隅に永安殿へ渡る階段棟を附属する。内部は格天井の3室を並べ、地下に炊事場と浴室を設ける。近代に発展した境内景観の象徴的存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012948"},{"id":"00012950","register_sub_id":"101","register_pk":"368030","name":"太郎坊宮阿賀神社手水舎","kana":"たろうぼうぐうあがじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11809722,"lng":136.18195278,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造、銅板葺、面積5.0㎡","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 433","desc":"永安殿東側にある岩棚北端に南面して建つ。切妻造銅板葺、四方吹放しの長方形平面で、西北隅に手水石を据え、格天井を張る。軸部は内転びの角柱頂部を木鼻付の貫で固める。組物は舟肘木、中備蟇股で、細部を復古調の意匠とし、神域の入口を厳かに演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012950"},{"id":"00012951","register_sub_id":"101","register_pk":"368031","name":"太郎坊宮阿賀神社銅鳥居","kana":"たろうぼうぐうあがじんじゃどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和中","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11816389,"lng":136.18176389,"geo_status":"db","era":"昭和32年","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造、間口1.8m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 434","desc":"拝殿の北側にあり、本殿に通じる岩峰の裂け目の前に東面して建つ。木造で、円柱に貫を通し、反りのない島木笠木を重ねる八幡鳥居形式とし、全体を銅板で包む。神域の入口を明示するとともに古来の磐境信仰の中枢を象徴する構造物として存在感を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012951"},{"id":"00012945","register_sub_id":"101","register_pk":"368025","name":"太郎坊宮阿賀神社拝殿","kana":"たろうぼうぐうあがじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11807222,"lng":136.18177778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 428","desc":"境内中心部の岩峰下端に東面して建つ。桁行3間梁間3間、入母屋造銅板葺妻入で、四周に縁を廻す。四方吹放し舞殿形式で、格天井を張る。組物は三斗拳鼻付、中備は各面中央間に蟇股、一軒扇垂木。当社で希少な近世社殿で、伝統的な境内構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012945"},{"id":"00012943","register_sub_id":"101","register_pk":"368023","name":"太郎坊宮阿賀神社舞台","kana":"たろうぼうぐうあがじんじゃぶたい","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11801944,"lng":136.18155,"geo_status":"db","era":"明治13年／昭和23年改修","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造、面積31㎡","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 426","desc":"参拝所前面の岩棚南側に張出す露天の舞台。桁行4間梁間3間、懸造で、貫6段を通して軸部を固めて梁桁を組む。上面の床は鉄筋コンクリート造で、東西南三面に擬宝珠高欄を廻す。本殿前の広場を形成し、急峻な岩肌に立地する独特な社頭景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012943"},{"id":"00012953","register_sub_id":"101","register_pk":"368033","name":"太郎坊宮阿賀神社不動明王拝所","kana":"たろうぼうぐうあがじんじゃふどうみょうおうはいしょ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11772778,"lng":136.18185,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、面積4.9㎡","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 436","desc":"絵馬殿西側にある不動明王の祠の前に建つ。総花崗石造、方一間吹放しで、軸部は内転び角柱を貫と梁桁でつなぎ、束で棟木を受ける。屋根は東西棟の切妻造、反りのある流し石板葺である。大棟や鬼瓦等の細部も花崗石で精巧につくり、高度な石工技術をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012953"},{"id":"00012941","register_sub_id":"101","register_pk":"368021","name":"太郎坊宮阿賀神社本殿","kana":"たろうぼうぐうあがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市小脇町2247","lat":35.11805833,"lng":136.18138333,"geo_status":"db","era":"宝暦3年（1753）／大正13年改修","year":1753,"year_source":"db","year_min":1753,"year_max":1753,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"25 － 424","desc":"東近江市街西方の赤神山にある神社。本殿は岩峰南腹に東面して建つ一間社入母屋造銅板葺、正面千鳥破風、向拝軒唐破風付で、正側面に縁を廻す。二手先詰組に中備蟇股を加え、頭貫木鼻の霊獣や手挟の菊花彫刻、台輪木鼻の繰形など、要所に丁寧な装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012941"},{"id":"00002636","register_sub_id":"101","register_pk":"103626","name":"東方寺本堂","kana":"とうほうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市平松町471","lat":35.14502872,"lng":136.25004752,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"25 － 0187","desc":"町内唯一の天台宗寺院の本堂。桁行梁間各３間，向拝１間，入母屋造，桟瓦葺で，方柱上に平三斗組物を載せ側桁を受け１軒繁垂木の軒を支える。内部は畳敷，小組格天井で，奥１間通りに丸柱を立て凸型に仏壇を構える。明治期の小規模密教本堂の姿を良く留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002636"},{"id":"00002398","register_sub_id":"101","register_pk":"103388","name":"徳乗坊門","kana":"とくじょうぼうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県大津市坂本本町3210","lat":35.080517,"lng":135.867783,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2001.10.12(平成13.10.12)","register_no":"25 － 0167","desc":"形式は１間１戸の薬医門であるが，軒は疎垂木・木舞打で，起りのある桟瓦葺の屋根を架け，冠木を丸太状の材とするなど，数寄屋風の意匠が取り込まれており，近代和風の造形と思われる。参道の北側，實成坊と禅明坊の間に位置し，参道空間に欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002398"},{"id":"00003104","register_sub_id":"101","register_pk":"104094","name":"西福寺本堂","kana":"にしふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県東近江市平柳町1676","lat":35.14843,"lng":136.26506,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"25 － 0200","desc":"江戸時代末期に建てられた入母屋造，本瓦葺の浄土宗本堂。鬼瓦には慶応元年（１８６５）の銘がある。梁間を前後に分け，前半部を外陣，後半部を桁行に３分し，内陣と両脇陣をとる浄土宗仏堂の典型的な平面。各所にあしらった彫刻が時代を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003104"},{"id":"00003262","register_sub_id":"101","register_pk":"104252","name":"日本基督教団今津教会（旧今津基督教会館）","kana":"にほんきりすときょうだんいまづきょうかい（きゅういまづきりすときょうかいかん）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県高島市今津町今津1650-1","lat":35.402676,"lng":136.035049,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積130㎡、塔屋付","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0222","desc":"木造，平屋建，外壁モルタル塗，瓦葺（元スレート葺）で，ほぼ正方形の聖堂を中心に，北に講壇，南に玄関ホールを置き，４隅に事務室，図書室などを配す。正面に大きな妻面を見せ，頂部に塔屋をあげた明朗で印象的な外観をもつ。ヴォーリズ建築事務所の設計。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003262"},{"id":"00009323","register_sub_id":"101","register_pk":"194116","name":"日本基督教団近江金田教会礼拝堂","kana":"にほんきりすときょうだんおうみかねだきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"滋賀県","address":"滋賀県近江八幡市鷹飼町1575","lat":35.12446085,"lng":136.10215702,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造2階建、スレート葺、建築面積95㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"25 － 0321","desc":"木造二階建、建築面積九五平方メートル、切妻造スレート葺。南西に鐘楼を建て、南妻の切妻造玄関入口をアーチ形とする。一階は集会室、二階は単廊式の会堂でキングポスト・トラスを現す。外壁モルタル塗で、一階の引違窓、二階の上下窓とも簡素な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009323"},{"id":"00001077","register_sub_id":"101","register_pk":"102067","name":"日本基督教団堅田教会","kana":"にほんきりすときょうだんかたたきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田3-18-6","lat":35.11412573,"lng":135.91620256,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造２階建，鉄板葺一部スレート葺，建築面積178㎡","structure_material":"木造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"25 － 0109","desc":"大津市の北方，堅田地区に建つ教会で，ヴォーリズ建築事務所の設計になる。単廊式の会堂で，会堂部にはキングポストの簡潔な小屋組を顕わす。正面中央上部にチューダーアーチの４連窓を開け，右手にトンガリ屋根の角塔をあげて特徴的な外観を造りあげている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001077"},{"id":"00001078","register_sub_id":"101","register_pk":"132576","name":"日本基督教団堅田教会塀","kana":"にほんきりすときょうだんかたたきょうかいへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県大津市本堅田3-18-6","lat":35.11392899,"lng":135.91616977,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造，延長15.5m","structure_material":"煉瓦造","registered":"1999.02.17(平成11.02.17)","register_no":"25 － 0110","desc":"堅田の波止場に通じる街路に面する。赤煉瓦１枚厚，長手積みの塀で，高さは煉瓦１２段と程良い高さに押さえられおり，会堂玄関前に教会らしい開放的な空間を造りだしている。最上段は煉瓦の長手面を下にし，４５度振って笠石的扱いとしている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001078"},{"id":"00001714","register_sub_id":"101","register_pk":"102704","name":"日本キリスト教団水口教会門柱","kana":"にほんきりすときょうだんみなくちきょうかいもんちゅう","category":"宗教","subcategory":"その他工作物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県甲賀市水口町城東3-21","lat":34.97169893,"lng":136.16856876,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造、高さ1.5m","structure_material":"煉瓦造","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0134","desc":"礼拝堂玄関に対応した敷地南辺に位置する。煉瓦２枚半角で、みかけ煉瓦１９段に積み、最上部は煉瓦の長手面を下にして積んで納める。門柱の左右には、５段積程度の低い煉瓦塀が取り付き、柵などで開放的に囲っていたことがうかがわれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001714"},{"id":"00001713","register_sub_id":"101","register_pk":"102703","name":"日本キリスト教団水口教会礼拝堂","kana":"にほんきりすときょうだんみなくちきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県甲賀市水口町城東3-21","lat":34.971882,"lng":136.168594,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、スレート葺一部鉄板葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"25 － 0133","desc":"ヴォーリズ建築事務所設計になる簡素な教会堂建築。木造、平屋建で、南北棟を大棟としたラテン十字形の外郭をもつが、南妻面の東半に玄関を設け、東西方向の交差廊部を礼拝堂に充てている平面構成に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001713"},{"id":"00009499","register_sub_id":"101","register_pk":"194292","name":"橋本家住宅（旧正蔵坊）主屋","kana":"はしもとけじゅうたく（きゅうしょうぞうぼう）しゅおく","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県大津市小関町88","lat":35.00816188,"lng":135.85615139,"geo_status":"db","era":"正保元年／昭和前期・昭和後期改修","year":1644,"year_source":"db","year_min":1644,"year_max":1644,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"25 － 0323","desc":"敷地中央に建つ。木造平屋建、建築面積一二六平方メートル、切妻造及び入母屋造桟瓦葺。南東側の八畳主室に二間幅の大ドコと付書院を付し、庭園に臨む三面に縁を廻らす。側廻りは柱上に舟肘木を載せ、垂木を疎らに配る。園城寺別所の坊として希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009499"},{"id":"00003245","register_sub_id":"101","register_pk":"104235","name":"日雲神社本殿","kana":"ひくもじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町牧75","lat":34.90797811,"lng":136.08335662,"geo_status":"db","era":"元禄4","year":1691,"year_source":"db","year_min":1691,"year_max":1691,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0205","desc":"元禄４年の建築と伝える三間社流造，向拝１間の神社本殿。桁行３間梁間２間の身舎に１間幅の前室を設け，正側面に縁を廻らす。前室は前面中央間を引分戸とする他は斜格子嵌め殺しとする。近年金属板で仮葺されているが，当初の状況を良く伝える本殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003245"},{"id":"00005281","register_sub_id":"101","register_pk":"106269","name":"火頭古神社本殿","kana":"ひずこじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市土山町猪鼻163","lat":34.92073569,"lng":136.31424476,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"25 － 0237","desc":"桁行０．９ｍ，梁間０．７ｍ規模，二軒繁垂木，檜皮葺の一間社流造。身舎は円柱，向拝は角柱とし，組物は連三斗として中備に蟇股を置く。正側面に縁と高欄を廻し，正面中央に木階段を付す。檜の良材を用い，形式や工法に古式を残し，彫刻も質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005281"},{"id":"00000795","register_sub_id":"101","register_pk":"101785","name":"百済寺本坊喜見院書院","kana":"ひゃくさいじほんぼうきけんいんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県東近江市百済寺町323","lat":35.12686313,"lng":136.28891781,"geo_status":"db","era":"昭和15頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積200㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"25 － 0053","desc":"湖東三山のひとつ百済寺の本坊にあって，庭に面して建つ大型の入母屋造書院。平面は，仏間や書院の間などからなる２列６室の居室の２方に広縁を取り，四方に濡縁を張る。年代は新しいが，細部の造作とも伝統的な工法になる。設計・施工は大工の宮部太兵衛。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000795"},{"id":"00010830","register_sub_id":"101","register_pk":"201665","name":"日吉神社本殿","kana":"ひよしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県長浜市曽根町1097","lat":35.404755,"lng":136.253057,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積7.9㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0374","desc":"集落内の境内に西面して建ち、一間社切妻造、向拝一間、檜皮葺である。組物間を猿や霊獣の彫刻で埋める。正面小脇板や妻壁に配した植物や雲紋の彫刻、手挟や木鼻の透彫等、いずれも巧緻な施工で躍動感ある表現となる。湖北で活躍した大工宮部家の力量を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010830"},{"id":"00010831","register_sub_id":"101","register_pk":"201666","name":"日吉神社門及び玉垣","kana":"ひよしじんじゃもんおよびたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市曽根町1097","lat":35.404734,"lng":136.25299,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"門 木造、檜皮葺、間口1.8m 玉垣 木造、瓦葺、延長36m","structure_material":"門 木造","registered":"2015.11.17(平成27.11.17)","register_no":"25 ‐ 0375","desc":"本殿西正面の門と本殿を囲む玉垣。薬医門形式の門は、切妻造で正面に軒唐破風を付け、正面上部や妻壁に植物や雲紋の華やかな彫刻を飾る。玉垣は北に潜りを開き、繰形付の持送で腕木を受けて桟瓦を葺く。内法は竪連子を廻らせる。本殿に劣らぬ装飾性を備えた門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010831"},{"id":"00015315","register_sub_id":"101","register_pk":"532439","name":"宝厳寺弁才天堂","kana":"ほうごんじべんざいてんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"滋賀県","address":"滋賀県長浜市早崎町1664-3","lat":35.42145278,"lng":136.14328889,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積439㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"25 - 0522","desc":"竹生島にある真言宗寺院本堂。設計は乾兼松。桁行五間梁間五間、入母屋造檜皮葺の正面に千鳥破風を飾り四周裳階付き。前方に土間の礼堂、後方に内陣・脇陣を配す。内陣は柱を立ち登らせ組物は差肘木で小壁に飛天を描く。近代における復古的意匠の仏堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015315"},{"id":"00001777","register_sub_id":"101","register_pk":"102767","name":"宮部西薬師堂","kana":"みやべにしやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市宮部町1810、1811","lat":35.41946559,"lng":136.27449,"geo_status":"db","era":"天保10","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"25 － 0135","desc":"小規模な宝形造二重屋根の仏堂。平面は正方形で方２間の規模を持つ。初重は挿肘木，平行垂木，上重は出組，扇垂木とし，上下で外観に意匠的変化をつける。向拝組物間の彫物や手挟に見所を持つ。大工は棟札より隣町の西嶋繁右衛門であることが知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001777"},{"id":"00003244","register_sub_id":"101","register_pk":"104234","name":"妙感寺本堂（観音堂）","kana":"みょうかんじほんどう（かんのんどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"滋賀県","address":"滋賀県湖南市三雲1758","lat":34.97560738,"lng":136.09630228,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0204","desc":"木造３間四方，入母屋造本瓦葺の堂宇。東面して平入とする。昭和１２年の建築で，設計は当時京都帝国大学の講師であった藤原義一が当たった。内部は板敷とし，正側面三方に濡縁を廻らす。禅宗様を基調とする本堂で，中世の趣を伝える建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003244"},{"id":"00014624","register_sub_id":"101","register_pk":"515166","name":"明楽寺経蔵","kana":"みょうらくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.50493611,"lng":136.22655,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積51㎡","structure_material":"土蔵造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0518","desc":"本堂南に建つ土蔵造の経蔵。宝形造桟瓦葺で露盤宝珠を飾り、北面に切妻造銅板葺向拝を付す。切石積基壇に建ち、外壁は漆喰仕上で東西に火灯窓を開ける。内部は一室で虹梁形火打梁を架け、北半を土間、南半板敷とし、貼付紙の天井に飛天を描いて荘厳する経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014624"},{"id":"00014622","register_sub_id":"101","register_pk":"515164","name":"明楽寺庫裏","kana":"みょうらくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町937他","lat":35.50533333,"lng":136.2262,"geo_status":"db","era":"安永年間（1772-1781）","year":1776,"year_source":"estimated","year_min":1772,"year_max":1781,"year_label":"安永年間（1772-1781）","structure":"木造平屋建、瓦葺、建築面積278㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0516","desc":"本堂の北西に建つ庫裏。平屋建切妻造平入桟瓦葺で南面中央に式台玄関を設ける。内部は棟通りで南北二列に分け、南列は西に梁組を見せる吹抜の土間、東に平書院付の床を構えた三間続きの座敷とする。軸部は木太く、風格を備え、歴史的な伽藍を構成する庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014622"},{"id":"00014626","register_sub_id":"101","register_pk":"515168","name":"明楽寺山門","kana":"みょうらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.5051,"lng":136.22612778,"geo_status":"db","era":"文化4年（1807）","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造、瓦葺、間口5.1m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0520","desc":"本堂の西方で参道に開く一間一戸の四脚門。切妻造桟瓦葺で、本柱は円柱、袖柱は角柱とし、腰貫、飛貫、頭貫で固める。組物は支輪を備えた出組、軒は二軒繁垂木とする。飛貫と頭貫の木鼻を彫刻で飾った華やかな山門で、伽藍と宿場の町並みの歴史的景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014626"},{"id":"00014625","register_sub_id":"101","register_pk":"515167","name":"明楽寺鐘楼","kana":"みょうらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.50500833,"lng":136.22634167,"geo_status":"db","era":"天保8年（1837）","year":1837,"year_source":"db","year_min":1837,"year_max":1837,"year_label":null,"structure":"木造、瓦葺、面積14㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0519","desc":"本堂の南西に東面し、切石積基壇に建つ鐘楼。方一間の入母屋造桟瓦葺で、内転びの円柱を貫で固め、組物は尾垂木付の二手先、軒は二軒繁垂木とする。梵鐘を虹梁から吊り、天井は小組格天井を張る。小規模ながら欄間や木鼻などを彫刻で飾った丁寧な造りの鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014625"},{"id":"00014623","register_sub_id":"101","register_pk":"515165","name":"明楽寺太鼓楼","kana":"みょうらくじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.504975,"lng":136.22623611,"geo_status":"db","era":"文化4年（1807）","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造2階建、瓦葺、建築面積45㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0517","desc":"本堂の南西に北面する太鼓楼。二階建入母屋造妻入桟瓦葺、組物は出三斗、中備は蟇股、軒は一軒繁垂木。二階は北と南に火灯窓、東と西は格子構え、腰は袴腰形板張。内部は北西に階段を設け二階に太鼓を吊る。高く聳える望楼が歴史的な伽藍を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014623"},{"id":"00014621","register_sub_id":"101","register_pk":"515163","name":"明楽寺本堂","kana":"みょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県長浜市木之本町木之本字古町936","lat":35.50526389,"lng":136.22661111,"geo_status":"db","era":"安永年間（1772-1781）","year":1776,"year_source":"estimated","year_min":1772,"year_max":1781,"year_label":"安永年間（1772-1781）","structure":"木造平屋建、瓦葺、建築面積697㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"25 - 0515","desc":"木之本宿の中心に位置する真宗大谷派寺院の本堂。西面する入母屋造平入桟瓦葺で向拝を付す。間取は内外陣と左右余間とし、外陣周囲は板敷広縁に落縁を付す。外陣には円柱を立登らせ、虹梁形差物上に蟇股を配す。宿場の歴史的景観を担う大規模寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014621"},{"id":"00006570","register_sub_id":"101","register_pk":"107553","name":"八阪神社本殿","kana":"やさかじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町柞原321","lat":34.86350078,"lng":136.026695,"geo_status":"db","era":"貞享5","year":1688,"year_source":"db","year_min":1688,"year_max":1688,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積10㎡、覆屋付","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"25 － 0240","desc":"信楽川左岸の山裾に南面して建つ。正面柱間７．５尺規模の一間社流造で，屋根は檜皮葺。現在は覆屋に納める。浜床付で木階７級を設ける。妻飾りは虹梁大瓶束。正面は格子戸４枚の引違い，内陣は弊軸付板扉で限る。獏形木鼻や蟇股の彫刻で飾り，極彩色が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006570"},{"id":"00003248","register_sub_id":"101","register_pk":"104238","name":"二童子神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"滋賀県","address":"滋賀県甲賀市信楽町中野140","lat":34.85912608,"lng":136.02055673,"geo_status":"db","era":"元禄16","year":1703,"year_source":"db","year_min":1703,"year_max":1703,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"25 － 0208","desc":"一間社春日造の社殿。形式・棟札等から元禄１６年の建築であることが知られる。身舎は方１間で，ほぼ均等に内陣と下陣に分ける。屋根は檜皮葺とし，箱棟を置いている。滋賀県下でも数の少ない春日造本殿であり，近世本殿建築の好例といえる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003248"},{"id":"00004138","register_sub_id":"101","register_pk":"105128","name":"八幡神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"滋賀県","address":"滋賀県東近江市小田苅町954","lat":35.13378204,"lng":136.2205683,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、檜皮葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"25 － 0230","desc":"三間社流造の社殿。身舎は奥行２間の外陣と奥行１間の内陣からなり，格天井とする。正側面には縁を巡らし，背面柱筋には脇障子を設ける。屋根は銅板葺で，正面に角柱の向拝を設ける。全体構成に中世の様式の影響を残す，小規模社殿の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004138"},{"id":"00012959","register_sub_id":"101","register_pk":"368039","name":"阿倍王子神社旧本殿","kana":"あべおうじじんじゃきゅうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町160","lat":34.63089722,"lng":135.50900833,"geo_status":"db","era":"明治41年／昭和43年移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.2㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 767","desc":"市南部の熊野街道沿いにある神社で、旧本殿は境内南辺の切石積基壇上に東面して建つ。正面一間、側背面二間、流造銅板葺。庇は一段折れて縋破風とし、軒唐破風を付す。身舎組物は舟肘木。側面中柱は棟木まで延びあがる。簡素ながら特異なつくりの社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012959"},{"id":"00012960","register_sub_id":"101","register_pk":"368040","name":"阿倍王子神社葛之葉稲荷神社本殿（旧男山八幡神社本殿）","kana":"あべおうじじんじゃくずのはいなりじんじゃほんでん（きゅうおとこやまはちまんじんじゃほんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町160","lat":34.63109722,"lng":135.50927778,"geo_status":"db","era":"江戸後期／明治41年・昭和44年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 768","desc":"拝殿東側の覆屋内に南面して建つ。正面一間、側面二間、入母屋造檜皮葺、向拝軒唐破風付で、やや横長の平面とし、向拝の連三斗は肘木を内側に延ばして菖蒲桁下の出三斗とつなぐ。全体を赤色塗として要所に極彩色を施す。小社ながら華麗な意匠の社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012960"},{"id":"00012963","register_sub_id":"101","register_pk":"368043","name":"安倍晴明神社透塀","kana":"あべせいめいじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町144","lat":34.631725,"lng":135.50934167,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、銅板葺、延長25m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 771","desc":"拝殿の背面から延び、本殿の四周を結界する木造銅板葺の透塀。面取角柱を腰長押と内法長押で固め、腰上は菱形断面の板連子、腰は縦板張とする。屋根は腕木を出して桁を通し、一軒疎垂木とする。良材を用いた精巧なつくりで、本殿周辺の景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012963"},{"id":"00012962","register_sub_id":"101","register_pk":"368042","name":"安倍晴明神社拝殿及び幣殿","kana":"あべせいめいじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町144","lat":34.63174167,"lng":135.50923889,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 770","desc":"本殿前に西面して建つ。正面三間、側面三間、入母屋造銅板葺。三方に高欄付の縁を廻し、背面中央に奥行二間の幣殿を突出して本殿を臨む。内部は一室で左右奥に神饌所と祭器庫を設ける。本殿と調和した端正な復古的意匠で、落ち着いた社頭景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012962"},{"id":"00012961","register_sub_id":"101","register_pk":"368041","name":"安倍晴明神社本殿","kana":"あべせいめいじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町144","lat":34.63175,"lng":135.50931389,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"27 － 769","desc":"市南部の熊野街道沿いにある神社で、本殿は境内奥の切石積基壇上に西面して建つ。一間社流造銅板葺。大仏様木鼻や中世風蟇股を用いて細部を古式に飾る。身舎正面は柱筋内側に板扉を立てる。もと奈良県技師・吉田種次郎の設計による、技巧を凝らした近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012961"},{"id":"00010671","register_sub_id":"101","register_pk":"201245","name":"蟻通神社裏門","kana":"ありとおしじんじゃうらもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385812,"lng":135.313315,"geo_status":"db","era":"嘉永6年(1853)／昭和17年移築","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造、瓦葺、間口4.0m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0626","desc":"本殿北西側の参道口に構える四脚門で、切妻造本瓦葺である。表門とほぼ同規模同形式になり、同様に赤色塗とするが、棟柱の柱頭に雲紋の笈形を付さない点のみ異なる。大工の貝戸彦左衛門清重は当地の大工組の組頭を務めた。表門とともに神域を画す門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010671"},{"id":"00010669","register_sub_id":"101","register_pk":"201243","name":"蟻通神社絵馬殿","kana":"ありとおしじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385257,"lng":135.313414,"geo_status":"db","era":"文久元年(1861)／昭和17年移築","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0624","desc":"境内南東寄りに南北棟で建つ絵馬殿で、桁行四間梁間二間、入母屋造本瓦葺である。円柱を絵様虹梁で繋いで各間に大瓶束を立て、柱と大瓶束上に大斗舟肘木を組む。建ちの高い立面、透彫の虹梁木鼻や持送などに時代性を示すとともに、往時の信仰形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010669"},{"id":"00010670","register_sub_id":"101","register_pk":"201244","name":"蟻通神社表門","kana":"ありとおしじんじゃおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385239,"lng":135.313256,"geo_status":"db","era":"嘉永5年(1852)／昭和17年移築","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造、瓦葺、間口4.0m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0625","desc":"境内入口に南面して建つ赤塗の四脚門で、切妻造本瓦葺である。円柱を梁行のみ貫で固め、正背面柱は大斗舟肘木で桁を受ける。棟柱では桁高さの矩形梁を絵様肘木で受け、柱頭間に虹梁を渡す。また柱頭に雲紋の笈形を、大斗上に同種の拳鼻を付し、華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010670"},{"id":"00010673","register_sub_id":"101","register_pk":"201247","name":"蟻通神社北手水舎","kana":"ありとおしじんじゃきたてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385897,"lng":135.313451,"geo_status":"db","era":"江戸末期／昭和17年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積6.5㎡、手水鉢付","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0628","desc":"裏門北側に南北棟で建つ手水舎で、南寄りに手水鉢を据え、北を井戸とする。軸部は内転びの角柱を頭貫と台輪で固め、両妻は絵様虹梁上に笈形付の大瓶束を立てて飾る。頭貫を受ける大振りの持送や頭貫木鼻は絵馬殿同様に透彫の絵様を施す。装飾性豊かな手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010673"},{"id":"00010667","register_sub_id":"101","register_pk":"201241","name":"蟻通神社後門及び東西透塀","kana":"ありとおしじんじゃごうもんおよびとうざいすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385724,"lng":135.313465,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"後門 木造、銅板葺、間口2.4m 東透塀 木造、銅板葺、総延長24m 西透塀 木造、銅板葺、総延長24m","structure_material":"後門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0622","desc":"本殿背後に建つ後門と、東西に本殿を囲み拝殿背面にいたる透塀で、整層積の石垣上に建つ。後門は一間腕木門で両折桟唐戸を吊り、楣上に足の長い蟇股を配す。透塀は柱間に尖頭形の竪板を張詰め、上部目透しとする。透廊とともに社地移転時の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010667"},{"id":"00010666","register_sub_id":"101","register_pk":"201240","name":"蟻通神社透廊","kana":"ありとおしじんじゃすきろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385631,"lng":135.313426,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0621","desc":"幣殿に接続して石垣上に建つ桁行一一間の透廊で、中央間を広めて後方本殿側に拝所を張出す。東西両端を室とする他は吹放しで、切妻造銅板葺である。角柱上に大斗実肘木を乗せ、梁上に蟇股を配す以外は簡明な意匠である。社地移転時の境内の変容を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010666"},{"id":"00010674","register_sub_id":"101","register_pk":"201248","name":"蟻通神社太鼓橋","kana":"ありとおしじんじゃたいこばし","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385174,"lng":135.313176,"geo_status":"db","era":"江戸末期／昭和17年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造桁橋、橋長3.9m、幅員2.6m、袖高欄付","structure_material":"石造桁橋","registered":"2015.08.04(平成27.08.04)","register_no":"27－0629","desc":"表門手前の池に架かる石橋。橋長三・九メートル幅員二・六メートルの桁橋で、中央の橋脚にアーチ状の桁を架けて太鼓橋形式とする。橋面両側にアーチ状の石製高欄を組み、前後に袖高欄を設け、高欄の込栭を分銅形に作る。参道に趣を添える石橋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010674"},{"id":"00010665","register_sub_id":"101","register_pk":"201239","name":"蟻通神社拝殿及び幣殿","kana":"ありとおしじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385549,"lng":135.31339,"geo_status":"db","era":"江戸末期／明治40年改修・昭和17年移築改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0620","desc":"本殿正面に建ち、桁行一一間の横長平面になる入母屋造本瓦葺の拝殿。戦中の移築時に、正面中央の唐破風造向拝と背面の幣殿を増築した。側廻りは開口を多くして開放的とし、内部は天井を張らず、力感ある梁組を現しとする。市内で希少な横長形式の近世拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010665"},{"id":"00010664","register_sub_id":"101","register_pk":"201238","name":"蟻通神社本殿","kana":"ありとおしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.38568,"lng":135.313448,"geo_status":"db","era":"寛文9年(1669)／昭和17年移築・昭和25年改修","year":1669,"year_source":"db","year_min":1669,"year_max":1669,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0619","desc":"境内北寄りの透塀内に南面する。正面一間側面二間、隅木入春日造、軒唐破風付、銅板葺で、三方に腰高に縁高欄を廻らし、正面に浜床を設ける。身舎は組物出組で板支輪に波紋などを陽刻し、庇では二重虹梁に蟇股と大瓶束を置くなど、要所を彫刻で飾る本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010664"},{"id":"00010668","register_sub_id":"101","register_pk":"201242","name":"蟻通神社舞殿","kana":"ありとおしじんじゃまいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385437,"lng":135.313337,"geo_status":"db","era":"江戸前期／昭和17年移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0623","desc":"拝殿前方に建つ。五・八メートル四方の方一間、吹放し形式の舞殿で、入母屋造妻入り、銅板葺である。柱と頭貫を持送で固め、台輪上の組物は柱上、中備とも三斗で中備には拳鼻を付す。床高はやや低めとし、棹縁天井を張る。境内景観の中核をなす、大型の舞殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010668"},{"id":"00010672","register_sub_id":"101","register_pk":"201246","name":"蟻通神社南手水舎","kana":"ありとおしじんじゃみなみてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市長滝806他","lat":34.385122,"lng":135.313084,"geo_status":"db","era":"昭和15年／昭和17年移築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、瓦葺、面積7.4㎡、手水鉢付","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"27－0627","desc":"参道脇に南北棟で建つ、桁行二間で切妻造本瓦葺の手水舎。吹放し形式で、北側に大型で元禄七年銘の手水鉢を据え、南を井戸とする。軸部は柱を内転びに立てて貫で固め、柱上に大斗実肘木を組み、桁と梁を受ける。神社境内入口の景観形成に寄与する手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010672"},{"id":"00015334","register_sub_id":"101","register_pk":"532458","name":"石切劔箭神社絵馬殿","kana":"いしきりつるぎやじんじゃえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目736他","lat":34.681325,"lng":135.64626389,"geo_status":"db","era":"昭和35年","year":1960,"year_source":"db","year_min":1960,"year_max":1960,"year_label":null,"structure":"木造2階建、銅板葺、建築面積83㎡","structure_material":"木造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0945","desc":"境内入口に建ち、門を兼ねた絵馬殿。梁間四間と奥行深い三間一戸の楼門形式で、屋根銅板葺で、切妻造の四周に庇を付し棟上に剣と矢を飾る。下層中央間両脇に絵馬を並べ、随身像を安置。上層は格天井の一室で長押を廻らす。独創的な意匠とした楼門風の絵馬殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015334"},{"id":"00015333","register_sub_id":"101","register_pk":"532457","name":"石切劔箭神社透塀","kana":"いしきりつるぎやじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目691","lat":34.68217778,"lng":135.6462,"geo_status":"db","era":"昭和6年頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造、銅板葺、総延長26m","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0944","desc":"拝殿の背面から本殿の背面の柱筋に至り、矩折に本殿両脇を囲繞する銅板葺の透塀。切石積基壇に建ち、隅に角柱、中間に円柱を立て、地長押・腰長押・内法長押を打ち、腰は竪板張、上部は連子窓。腕木と垂木の鼻先に付した繰型が特徴的で、軒廻り賑やかな透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015333"},{"id":"00015332","register_sub_id":"101","register_pk":"532456","name":"石切劔箭神社拝殿及び幣殿","kana":"いしきりつるぎやじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目691","lat":34.68224167,"lng":135.64626389,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積130㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0943","desc":"本殿の前方、基壇上に建つ拝殿及び幣殿。設計は吉田種次郎。全体Ｔ字形平面で、拝殿入母屋造、幣殿両下造で銅板葺。正面に千鳥破風を据え、向唐破風造向拝を付す。組物に舟肘木や挿肘木、木鼻に拳鼻や大仏様風の繰形を用いるなど細部まで意匠を凝らした社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015332"},{"id":"00015331","register_sub_id":"101","register_pk":"532455","name":"石切劔箭神社本殿","kana":"いしきりつるぎやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府東大阪市東石切町一丁目691","lat":34.68229722,"lng":135.64625833,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"27 - 0942","desc":"生駒山西麓に位置する神社本殿。設計は吉田種次郎。高い基壇に建つ三間社流造銅板葺で、正面に千鳥・軒唐破風を付し、両妻面に亀甲紋の雨除を設ける。組物は大仏様風の木鼻を用いた特異な一手先とするなど、中世寺社建築の細部意匠を引用した近代の神社本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015331"},{"id":"00001393","register_sub_id":"101","register_pk":"102383","name":"大阪天満宮神楽所","kana":"おおさかてんまんぐうかぐらしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市北区天神橋2-1-8","lat":34.69598155,"lng":135.51294852,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"27 － 0077","desc":"弘化２年（1845）造替の本殿・拝殿の東に建つ南北棟，銅板葺入母屋屋根の単層建物で，拝殿とは二階廊で連絡する。柱上には舟肘木を置き，軒は二軒疎角垂木とし，周囲に高く縁を回し，擬宝珠高欄を付ける。西面は，格子蔀戸を釣るなど古式を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001393"},{"id":"00001394","register_sub_id":"101","register_pk":"102384","name":"大阪天満宮参集所","kana":"おおさかてんまんぐうさんしゅうじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市北区天神橋2-1-8","lat":34.696095,"lng":135.513077,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積231㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"27 － 0078","desc":"本殿と梅花殿の間に建つ東西棟，銅板葺入母屋屋根，木造単層の建物で，神楽所とは軒を一段落として変化をつけ，梅花殿とは廊下で繋がれる。身舎・庇構成をとり，身舎桁行を３分して計５室を設ける。通称「広間」で，現在は梅花殿の控室として利用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001394"},{"id":"00001392","register_sub_id":"101","register_pk":"102382","name":"大阪天満宮梅花殿","kana":"おおさかてんまんぐうばいかでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市北区天神橋2-1-8","lat":34.69607279,"lng":135.5133448,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積129㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"27 － 0076","desc":"「天満の天神さん」として知られる大阪天満宮の境内東端中央寄りに南面して建つ。木造単層，銅板葺入母屋屋根の客殿（現在は結婚式場）で，身舎・庇構成をとり，東端の部屋の天井を支輪付二重折上小組格天井とした格式高い造りとする点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001392"},{"id":"00011988","register_sub_id":"101","register_pk":"211159","name":"男神社旧拝殿及び幣殿（社務所）","kana":"おのじんじゃきゅうはいでんおよびへいでん（しゃむしょ）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府泉南市男里三丁目1065","lat":34.359304,"lng":135.257246,"geo_status":"db","era":"明治15年／明治36年改修、昭和15年頃移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"27-711","desc":"割拝殿として建築されたものを移築し社務所とする。桁行五間、梁間二間、切妻造、銅板葺で、正面に千鳥破風を付け、唐破風の玄関を張り出す。玄関は平三斗と太瓶束上の実肘木で軒桁を受ける凝った意匠を見せ、当地方の特色を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011988"},{"id":"00011989","register_sub_id":"101","register_pk":"211160","name":"男神社透塀","kana":"おのじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府泉南市男里三丁目1065","lat":34.35944239,"lng":135.25753876,"geo_status":"db","era":"明治15年頃／昭和前期改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造、瓦葺、総延長18m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"27-712","desc":"本殿と拝殿及び幣殿を画す。東に三間、西に折曲がり七間半とし、切妻造、本瓦葺。柱間は腰を羽目板、腰長押と内法長押間を透し連子窓とする。軒は一軒疎垂木で、妻面の拝みには梅鉢懸魚を吊る。丁寧な造作の透塀で境内景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011989"},{"id":"00011987","register_sub_id":"101","register_pk":"211158","name":"男神社拝殿及び幣殿","kana":"おのじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉南市男里三丁目1065","lat":34.359384,"lng":135.257636,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"27-710","desc":"市内北西部の金熊川右岸に位置する境内に東西棟で建つ。拝殿は桁行五間、梁間二間、入母屋造で、組物は舟肘木、妻飾は豕扠首とし、幣殿が続く中央間のみ虹梁を架け蟇股を置く。細部意匠は復古的で、建築家池田谷久吉の力量が発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011987"},{"id":"00015045","register_sub_id":"101","register_pk":null,"name":"加支多神社神饌所","kana":"かしたじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府泉佐野市鶴原1965","lat":34.42616944,"lng":135.34228056,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0916","desc":"本殿の西に位置し、基壇上に東面して建つ一間社流造鉄板葺。身舎は角柱とし、飛貫を通して鼻先を現し、組物は舟肘木で妻飾は大瓶束、軒は一軒で吹寄垂木とし、正面に桟唐戸を開く。全体的に装飾少ないながらも丁寧なつくりの小社で、境内の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015045"},{"id":"00015044","register_sub_id":"101","register_pk":"529322","name":"加支多神社拝殿及び幣殿","kana":"かしたじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府泉佐野市鶴原1965","lat":34.42608056,"lng":135.34224722,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0915","desc":"境内中央に南面して建つ入母屋造平入本瓦葺の拝殿。南に入母屋造妻入向拝を付し、北に両下造幣殿を接続する。拝殿正面は向拝両脇に格子窓を開け、楣と桁間の小壁に舟肘木と長押を装飾的に貼付ける。内部は一室で格天井張。重厚な本瓦葺屋根が境内景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015044"},{"id":"00015043","register_sub_id":"101","register_pk":null,"name":"加支多神社本殿","kana":"かしたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府泉佐野市鶴原1965","lat":34.42618889,"lng":135.34236389,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積6.4㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0914","desc":"見出川河口左岸、熊野街道沿いに位置する神社本殿。基壇上に南面して建つ一間社流造檜皮葺（銅板仮葺）で三方に刎高欄付縁を廻らす。庇柱は虹梁形頭貫を用いず三斗組で丸桁と海老虹梁を受ける。全体に簡素で整然とした意匠の本殿で境内の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015043"},{"id":"00010201","register_sub_id":"101","register_pk":"198034","name":"カトリック豊中教会司祭館","kana":"かとりっくとよなかきょうかいしさいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市本町6-196","lat":34.790037,"lng":135.466806,"geo_status":"db","era":"昭和14／昭和中期・平成11・平成15改修","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造2階建一部地階付、瓦葺、建築面積124㎡","structure_material":"木造2階建一部地階付","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0598","desc":"聖堂及びヨゼフ館の西側に南北棟で建つ。木造二階建、切妻造桟瓦葺で、東面中央に切妻屋根の玄関ポーチを構え、南壁面に煙突を立てる。丸太を使用した出桁造の軒廻りなどの細部意匠は聖堂と同様で、聖堂とともに静謐な敷地内空間を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010201"},{"id":"00010200","register_sub_id":"101","register_pk":"198033","name":"カトリック豊中教会聖堂及びヨゼフ館","kana":"かとりっくとよなかきょうかいせいどうおよびよぜふかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府豊中市本町6-196","lat":34.790341,"lng":135.46698,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋一部2階建、瓦葺一部鉄板葺、建築面積355㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0597","desc":"主体部である聖堂と、棟を直交して接続するヨゼフ館からなる。聖堂は屋根を入母屋造として鐘塔に刎高欄を廻らし、また三廊式平面の内部では、丸太柱、格天井、祭壇上の折上天井、組物付祭台を採用するなど、和風意匠を積極的に取入れる。木造和風教会の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010200"},{"id":"00012762","register_sub_id":"101","register_pk":"367665","name":"鴉宮稲荷社（旧本殿）","kana":"からすのみやいなりしゃ（きゅうほんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市此花区伝法二丁目1-1","lat":34.68708,"lng":135.45724194,"geo_status":"db","era":"天明元年（1781）／昭和5年頃・同42年頃移築","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"27 － 765","desc":"淀川下流部の南側にある境内東隅に建つ。高い切石積基壇上建つ南正面の一間社流造で、正側面に擬宝珠高欄付の切目縁を廻して脇障子を立てる。組物は三斗実肘木。中備の蟇股や妻飾の大瓶束笈形を躍動感のある彫刻で飾る。小社ながら豊かな細部意匠をもつ社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012762"},{"id":"00007083","register_sub_id":"101","register_pk":"108065","name":"鴉宮中門及び透塀","kana":"からすのみやちゅうもんおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市此花区伝法2-1-1","lat":34.68736089,"lng":135.4548771,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"門 木造、銅板葺、間口2.0m 塀 木造、スレート葺、延長30m","structure_material":"門 木造","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0458","desc":"拝殿後方の切石積基壇上に建ち、両側に延びる透塀により本殿を囲う。切妻造銅板葺の四脚門で、菱格子付の桟唐戸を開く。軒は一軒繁垂木で、屋根とともに、本殿と同様の直線的な構成とする。神明造本殿の正門に相応しい、端正なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007083"},{"id":"00007082","register_sub_id":"101","register_pk":"108064","name":"鴉宮拝殿","kana":"からすのみやはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市此花区伝法2-1-1","lat":34.68727362,"lng":135.45484376,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0457","desc":"境内の中央、本殿前に建ち、桁行７．３ｍ梁間５．５ｍ、切妻造銅板葺。組物は出組で、中備に彫刻付蟇股を配し、軒は二軒繁垂木。妻飾は、一手持出す三重虹梁形式で、下段を木鼻付の平三斗詰組とし、中段を雲龍彫刻で埋める。本殿と対照的に華やかな意匠の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007082"},{"id":"00007081","register_sub_id":"101","register_pk":"108063","name":"鴉宮本殿","kana":"からすのみやほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市此花区伝法2-1-1","lat":34.68741847,"lng":135.4548671,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.3㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"27 － 0456","desc":"河岸に位置する境内の奥に建つ。桁行２．８ｍ梁間２．３ｍ、神明造、銅板葺。低い亀腹上に建ち、柱は総円柱で、妻柱の外側に棟持柱を立て、軒は直線で構成し、棟に千木と勝男木を載せる。小規模ながら、昭和初期の神明造本殿として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007081"},{"id":"00007391","register_sub_id":"101","register_pk":"108373","name":"感田神社神楽殿","kana":"かんだじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447205,"lng":135.358948,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0512","desc":"境内地の東方に東西棟で建つ。桁行３間梁間２間半の木造平屋建で、北・西・南面に擬宝珠高欄付の切目縁をまわす。入母屋造桟瓦葺。内部は一室で、格天井を張る。東面は中央半間に神棚を造る。神事の際に西面中央柱を取り外し、広く開放とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007391"},{"id":"00007394","register_sub_id":"101","register_pk":"108376","name":"感田神社齋館","kana":"かんだじんじゃさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府貝塚市中1546-2","lat":34.447212,"lng":135.35910642,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0515","desc":"参集殿の東南に位置し、渡廊下で繋がる。東西棟の入母屋造桟瓦葺で、西面に落棟を付ける。八畳の座敷と三畳の前室を東西に配し、座敷は東面に北から物入と違棚、トコを並べ、南面に平書院をつくる。前室には丸形の下地窓を開ける。軽快な意匠感覚が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007394"},{"id":"00007393","register_sub_id":"101","register_pk":"108375","name":"感田神社参集殿","kana":"かんだじんじゃさんしゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市中1546-2他","lat":34.44735628,"lng":135.35893676,"geo_status":"db","era":"明治15／大正13移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0514","desc":"境内地の北辺に建つ、東西に細長い建物。屋根は本瓦葺で、東半部を入母屋造、西半部を切妻造とし、中央東寄りに入母屋造の式台を設ける。東端にはトコと違棚、平書院を構える十二畳半、その西に同規模の次の間を置き、縁をまわす。上質なつくりになる座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007393"},{"id":"00007392","register_sub_id":"101","register_pk":"108374","name":"感田神社神馬舎","kana":"かんだじんじゃしんめしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447048,"lng":135.358688,"geo_status":"db","era":"宝暦8","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0513","desc":"境内地の南辺、南門の東に建つ。桁行２．６ｍ梁間１．５ｍの木造平屋建。切妻造妻入桟瓦葺で、緩い起りをつける。方柱を建て、桁や梁を支持する。背面板壁で、他は腰竪格子とし、平側は上部に菱格子などを組む。木造神馬を安置し、伝統的な社頭景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007392"},{"id":"00007395","register_sub_id":"101","register_pk":"108377","name":"感田神社神門","kana":"かんだじんじゃしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447502,"lng":135.358459,"geo_status":"db","era":"安永9","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0516","desc":"南北の通りから少し東に入った位置に建つ。三間一戸二重門、入母屋造本瓦葺。初重は大斗肘木で、出桁造とし、一軒繁垂木。上重は平三斗で二軒扇垂木とする。初重両脇間には金剛柵と花頭窓を構え、上重には格狭間風に窓を開ける。独特な意匠構成になる神門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007395"},{"id":"00007396","register_sub_id":"101","register_pk":"108378","name":"感田神社土塀","kana":"かんだじんじゃどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.44759069,"lng":135.35819451,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長20m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0517","desc":"神門から通りまでの参道両脇と、神門南から三之社などの覆屋までの間に築かれる練塀。高さ２～２．５ｍ、折曲り総延長２０ｍを測る。屋根は切妻造瓦葺。白壁に仕上げるが、神門より内側は瓦と練り土が確認できる。神門とともに敷地正面に風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007396"},{"id":"00007386","register_sub_id":"101","register_pk":"108368","name":"感田神社末社一之社本殿","kana":"かんだじんじゃまっしゃいちのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.44733,"lng":135.358536,"geo_status":"db","era":"安永2／昭和50改修","year":1773,"year_source":"db","year_min":1773,"year_max":1773,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0507","desc":"境内地中央に東面して建つ。桁行４．８ｍ梁間５．８ｍの木造平屋建で、その内部を方２．９ｍに画し、後半に壇を設け、三間社風に神殿を造る。神殿は正面に擬宝珠高欄付の木階と縁を設け、円柱で出組とし、二軒繁垂木。屋根は軒唐破風付檜皮葺。末社社殿の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007386"},{"id":"00007389","register_sub_id":"101","register_pk":"108371","name":"感田神社末社五之社本殿","kana":"かんだじんじゃまっしゃごのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447392,"lng":135.358444,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.49㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0510","desc":"三之社本殿の西に位置する。小規模な一間社流造。三方に高欄付縁をまわし、正面に浜縁を付ける。身舎は円柱、大斗肘木、正面二軒繁垂木で、妻は虹梁大瓶束とする。屋根は葺足の粗い檜皮葺。向拝の彫刻が多少異なることを除けば、四之社本殿と同規模同形式。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007389"},{"id":"00007387","register_sub_id":"101","register_pk":"108369","name":"感田神社末社三之社本殿","kana":"かんだじんじゃまっしゃさんのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447388,"lng":135.358459,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0508","desc":"一之社の西北、三社を納める覆屋の中央に建つ。本瓦葺の一間社流造で、浜床・浜縁を付ける。柱は円柱で、三斗組とし、軒は一軒繁垂木。妻を虹梁大瓶束とする。身舎内部を前後に間仕切るが、中央に柱を建て、扉口を２ヶ所とする。丁寧なつくりになる社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007387"},{"id":"00007388","register_sub_id":"101","register_pk":"108370","name":"感田神社末社四之社本殿","kana":"かんだじんじゃまっしゃよんのしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.447365,"lng":135.358475,"geo_status":"db","era":"万延元","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.49㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0509","desc":"三之社本殿の東に位置する。小規模な一間社流造。三方に高欄付縁をまわし、正面に浜縁を付ける。身舎は円柱、大斗肘木、正面二軒繁垂木とし、妻は虹梁大瓶束。屋根は葺足の粗い檜皮葺。向拝は連三斗組で、中備に松などの彫物を飾る。時代相応の細部意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007388"},{"id":"00007390","register_sub_id":"101","register_pk":"108372","name":"感田神社神輿蔵","kana":"かんだじんじゃみこしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.4473,"lng":135.358505,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積21㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0511","desc":"一之社本殿の南側に東面して建つ。桁行４．９ｍ梁間４．２ｍの土蔵造平屋建。切妻造妻入本瓦葺。内部は一室で、中央の土間に神輿を置き、側・背面に低い板床を張る。外壁は腰板張とする白漆喰仕上げで、正面には銅板葺の唐破風を付け、印象的な意匠にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007390"},{"id":"00007397","register_sub_id":"101","register_pk":"108379","name":"感田神社南門","kana":"かんだじんじゃみなみもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府貝塚市中905","lat":34.44709,"lng":135.358658,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造、瓦葺、間口4.1m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"27 － 0518","desc":"境内地南辺のほぼ中央に建つ。間口４．１ｍと規模の大きい、一間一戸高麗門。屋根は切妻造本瓦葺。切石上に五平柱を建て、楣で固める。肘木と斗で支えられた男梁が深く軒桁を持ち出す。軒は一軒疎垂木。脇の土塀とともに、敷地南面の街路景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007397"},{"id":"00005297","register_sub_id":"101","register_pk":"106285","name":"願得寺客間","kana":"がんとくじきゃくま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.7426759,"lng":135.59635042,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0351","desc":"本堂と庫裏の間，玄関西に建つ。東西棟の切妻造，平屋建で，北に下屋を架け，桟瓦葺とする。平面は床付の６畳間を向かい合わせに配し，南に幅１間の広縁を設ける。控えの座敷だが，吟味した良材を多用し，洗練された床構えなど，近代の造形感覚が窺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005297"},{"id":"00005295","register_sub_id":"101","register_pk":"106283","name":"願得寺玄関","kana":"がんとくじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.74268228,"lng":135.59654842,"geo_status":"db","era":"宝暦2頃","year":1752,"year_source":"db","year_min":1752,"year_max":1752,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0349","desc":"南の本堂と北の庫裏の間に建つ。東を正面とし，式台付１０畳間の玄関と，その北の８畳の次の間からなり，西面に廊下が取り付く。玄関部は唐破風造，屋根は桟瓦葺である。本堂と庫裏を連結する機能を有し，玄関として格式のある外観を呈している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005295"},{"id":"00005296","register_sub_id":"101","register_pk":"106284","name":"願得寺書院","kana":"がんとくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.74260304,"lng":135.5961729,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0350","desc":"本堂の西に建つ。東西棟の入母屋造で，四周に下屋を廻し，桟瓦葺とする。建ちが高く重層に見えるが，平屋建で内部空間を高くつくる。平面は床・棚・付書院のある書院と次の間を幅１間の畳敷広縁が囲む形式である。外観は簡素だが，瀟洒なつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005296"},{"id":"00005298","register_sub_id":"101","register_pk":"106286","name":"願得寺太鼓楼","kana":"がんとくじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府門真市御堂町8-23","lat":34.74283762,"lng":135.59670452,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋一部2階建、瓦葺、建築面積79㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0352","desc":"境内の東辺北半にある。南北棟で桟瓦葺の長大な長屋形式で，切石積基壇上に建ち，南寄に門口を設ける。北端に載る楼は真壁造で東西両面に花頭窓を設け，入母屋造，本瓦葺屋根とする。街路沿いの景観を整えるとともに，楼が真宗寺院らしい風格を創出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005298"},{"id":"00007238","register_sub_id":"101","register_pk":"108220","name":"源聖寺庫裏","kana":"げんしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-3-1","lat":34.66396142,"lng":135.51135842,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0467","desc":"松屋町筋東側に占める境内地の通り寄りに南面して建つ。南面入母屋造北面切妻造の本瓦葺で、大棟南寄りに切妻造の煙出を付ける。正面中央東寄りに庇を掛け、戸口とする。方柱で、柱上に舟肘木を載せ、妻は虹梁大瓶束。簡明ながら重厚な庫裏外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007238"},{"id":"00007239","register_sub_id":"101","register_pk":"108221","name":"源聖寺山門","kana":"げんしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-3-1","lat":34.66380376,"lng":135.51125386,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0468","desc":"松屋町筋に西面する一間薬医門。間口３．２ｍで、潜り付の袖塀を両脇に付ける。男梁上に三斗組を置き、虹梁及び桁を高くし、鏡天井を張る。妻は虹梁蟇股、軒は二軒繁垂木で、屋根は切妻造本瓦葺とする。大型の薬医門で、蟇股や虹梁など彫りの深い絵様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007239"},{"id":"00003114","register_sub_id":"101","register_pk":"104104","name":"源正寺楼門","kana":"げんしょうじろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市阿倍野区阿倍野元町18-34","lat":34.629097,"lng":135.506973,"geo_status":"db","era":"明治22／大正12移築","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造楼門、瓦葺、建築面積13㎡","structure_material":"木造楼門","registered":"2003.01.31(平成15.01.31)","register_no":"27 － 0203","desc":"知恩院末で，鉄道敷設等により中央区上本町より現地に移築。初重袴腰を塗込める竜宮造の楼門で，上層は出組，二軒繁垂木，入母屋造，本瓦葺とする。蟇股や肘木の形式・絵様に近代らしい意匠が充溢するとともに，旧熊野街道に面し竜宮門として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003114"},{"id":"00015488","register_sub_id":"101","register_pk":"533503","name":"光聖寺山門","kana":"こうしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区生玉寺町3-4","lat":34.66150833,"lng":135.51445833,"geo_status":"db","era":"文政8年（1825）／昭和58年移築、令和6年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造、金属板（チタン）葺、間口2.5m、総延長10m、袖塀付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"27 - 0946","desc":"生玉寺町に位置する浄土宗寺院の山門。谷町筋に東面して建つ、一間一戸の薬医門で両脇に袖塀を延ばす。男梁鼻先に載せた大斗絵様肘木で軒桁を受け、軒は一軒繁垂木とする。妻飾は虹梁大瓶束笈形付。男梁、肘木、笈形などに精緻な彫刻を付し装飾華やかな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015488"},{"id":"00007242","register_sub_id":"101","register_pk":"108224","name":"光明寺庫裏","kana":"こうみょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-11","lat":34.662239,"lng":135.5114259,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0471","desc":"本堂の北側に玄関を介して繋がる。東西棟の切妻造本瓦葺で、大棟に煙出、妻面に下屋を設け、南面西寄りに庇を付け、出入口とする。壁は白漆喰仕上げ。玄関は入母屋造妻入桟瓦葺で、妻は木連格子。本堂と庫裏が並び建ち、重厚な境内景観を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007242"},{"id":"00007243","register_sub_id":"101","register_pk":"108225","name":"光明寺山門","kana":"こうみょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-11","lat":34.66207576,"lng":135.5111199,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造、瓦葺、間口3.2m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0472","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口３．２ｍで、潜戸付の袖塀を両脇に付ける。女梁を挿し肘木状に作り、男梁上に大斗肘木を組み、虹梁と軒桁を支持。妻は笈形付の虹梁大瓶束とし、軒は一軒繁垂木。鏡天井を張り、中備に龍の彫刻を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007243"},{"id":"00007241","register_sub_id":"101","register_pk":"108223","name":"光明寺本堂","kana":"こうみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-11","lat":34.662045,"lng":135.51144255,"geo_status":"db","era":"宝永3","year":1706,"year_source":"db","year_min":1706,"year_max":1706,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0470","desc":"松屋町筋の東に占める境内地の中央に位置する。入母屋造本瓦葺で、正面に一間向拝を付ける。五間堂で中央に双折両開桟唐戸をたてる。外陣及び内陣、脇陣からなる典型的な浄土宗本堂平面をもつ。建具ほかに改変が見られるものの、江戸中期の形態を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007241"},{"id":"00001118","register_sub_id":"101","register_pk":"102108","name":"金光教玉水教会会堂","kana":"こんこうきょうたまみずきょうかいかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市西区江戸堀1-16-9","lat":34.69004964,"lng":135.49559738,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部二階建，銅板葺，建築面積531㎡","structure_material":"木造平屋一部二階建","registered":"1999.06.07(平成11.06.07)","register_no":"27 － 0059","desc":"木造平屋建、一部２階建とする裳階付きの大型の和風建物。入母屋造の大屋根平側に２つの千鳥破風をつけ賑やかに飾る。細部の意匠は全体的に伝統的な手法に則り構成される。堂々とした外観は、風格がある。設計は池田谷(久吉)建築事務所で、北井工務店が施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001118"},{"id":"00011765","register_sub_id":"101","register_pk":"210781","name":"金剛寺天野川東岸旧子院築地塀","kana":"こんごうじあまのがわとうがんきゅうしいんついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天野町992他","lat":34.429323,"lng":135.529861,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土塀、瓦葺、総延長103m","structure_material":"土塀","registered":"2017.06.28(平成29.06.28)","register_no":"27-0701","desc":"天野川東岸の建物群を画す築地塀。川に面して建てられ、石垣基礎の上に、高さ〇・八メートルから一・三メートル程度の漆喰仕上の土壁を建て、上部に桟瓦を葺く。東岸にあった旧子院群の築地塀として設けられたもので、近世の境内状況を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011765"},{"id":"00011768","register_sub_id":"101","register_pk":"210784","name":"金剛寺大講堂","kana":"こんごうじだいこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市天野町992","lat":34.429346,"lng":135.530042,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積306㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0704","desc":"天野川の東岸、旧理趣院の敷地に建つ。寄棟造桟瓦葺の二重屋根、桁行一二間、梁間八間の規模で、正面中央には間口三間、切妻造の玄関を付す。小屋はトラス。天井が高く、縦長のガラス窓で明るい内部空間を実現する。近代の寺院における講堂の中でも大規模なもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011768"},{"id":"00011769","register_sub_id":"101","register_pk":"210785","name":"金剛寺大講堂食堂","kana":"こんごうじだいこうどうしょくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市天野町992","lat":34.429598,"lng":135.530031,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積347㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0705","desc":"大講堂の北に建つ。前面側に九尺幅の廊下を通し、その背後に食堂部、炊事室部、書庫二室が並ぶ不整形平面で、食堂前に玄関を付す。屋根は桟瓦葺。食堂のみ格天井とし、他は棹縁天井。壁は真壁で腰下見板張とする。講堂と一連で建てられた、近代寺院施設の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011769"},{"id":"00011770","register_sub_id":"101","register_pk":"210786","name":"金剛寺鎮守橋","kana":"こんごうじちんじゅばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市天野町","lat":34.428514,"lng":135.530187,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、銅板葺、全長6.4m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0706","desc":"天野川の境内入口付近にかかる木造橋。主伽藍と鎮守社を結ぶ。全長六・四メートル、幅三・〇メートルで、橋桁は僅かに反りを持つ。屋根は橋本体とは独立した柱で支持される切妻造銅板葺。本格的な構造を有する屋根を持つ橋で、寺院境内にふさわしい造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011770"},{"id":"00011760","register_sub_id":"101","register_pk":"210776","name":"金剛寺本坊奥殿","kana":"こんごうじほんぼうおくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府河内長野市天野町995","lat":34.429157,"lng":135.529596,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積284㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0696","desc":"桁行五間、梁間四間、入母屋造茅葺で、庇は桟瓦葺。一八畳間を中心に二列六間を配し、周囲には一間幅の畳縁を廻らす。南東隅には浴室などを収める附属屋が付く。御座の間を格天井とする以外は全て棹縁天井とする。大規模な御座所の遺例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011760"},{"id":"00011763","register_sub_id":"101","register_pk":"210779","name":"金剛寺本坊表門","kana":"こんごうじほんぼうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429729,"lng":135.529664,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"27-0699","desc":"子院群が統合された際に現位置に移築改修されたもの。北面する一間薬医門で、脇に築地塀が取り付く。切妻造本瓦葺で、五平の親柱に冠木を渡し、上下から男梁女梁で固める。軒は一軒繁垂木。全体に木柄が太く、大玄関と併せて本坊の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011763"},{"id":"00011758","register_sub_id":"101","register_pk":"210774","name":"金剛寺本坊客殿","kana":"こんごうじほんぼうきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429654,"lng":135.529505,"geo_status":"db","era":"江戸中期／平成3年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0694","desc":"中院の庫裏であったもの。桁行六間、梁間三間半、東面し、周囲には広縁を廻らす。屋根は入母屋造本瓦葺。平面は二列構成で、表側は八畳間三室を連ね、背面側は一間幅とする。天井は棹縁天井とし、部屋境は筬欄間とする。庭園に面し、境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011758"},{"id":"00011757","register_sub_id":"101","register_pk":"210773","name":"金剛寺本坊持仏堂","kana":"こんごうじほんぼうじぶつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.42881111,"lng":135.52938611,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0693","desc":"金剛寺の子院であった中院の持仏堂で、現在は金剛寺本坊の回遊式庭園の一端をなす。三間四方で東面し、背面に仏壇を張り出す。屋根は宝形造銅板葺。面取角柱に舟肘木をのせ、一軒疎垂木とする。内部は一室。近世期金剛寺の子院に建てられた、持仏堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011757"},{"id":"00011759","register_sub_id":"101","register_pk":"210775","name":"金剛寺本坊大玄関","kana":"こんごうじほんぼうだいげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429449,"lng":135.529641,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0695","desc":"旧子院群の統合に際し建てられた。入母屋造、本瓦葺の主体部に六畳・八畳・六畳を配し、その前面に檜皮葺の式台玄関を付す。玄関西脇には茶室を設ける。南・西には濡縁を廻らし、南縁は海老虹梁をかけ、化粧木舞裏とする。本坊正面の重厚な構えを作る建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011759"},{"id":"00011762","register_sub_id":"101","register_pk":"210778","name":"金剛寺本坊茶室","kana":"こんごうじほんぼうちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町996","lat":34.429566,"lng":135.529287,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0698","desc":"持仏堂の背後に建つ。入母屋造銅板葺で、四畳半茶室の北に水屋が付属する。茶室は、北東隅の二面に下地窓を設け、南面に貴人口、西面南端に躙口を配す。天井は、西寄りを掛込、他は棹縁天井とする。東端部を懸造状で造る、質の高い茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011762"},{"id":"00011761","register_sub_id":"101","register_pk":"210777","name":"金剛寺本坊渡廊下","kana":"こんごうじほんぼうわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府河内長野市天野町995","lat":34.429325,"lng":135.529659,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、檜皮葺一部茅葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0697","desc":"大玄関と奥殿をつなぐ渡廊下。一間幅の両下造檜皮葺で、中程に一間半四方、宝形造茅葺の四阿を設ける。軸部に丸太材や竹材を中心に用い、外板壁内土壁とする腰壁を配し、床は磚の四半敷。全体に草庵風の趣を見せ、庭園と併せて境内景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011761"},{"id":"00011764","register_sub_id":"101","register_pk":"210780","name":"金剛寺無量寿院・籠堂","kana":"こんごうじむりょうじゅいん・こもりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府河内長野市天野町1539","lat":34.429144,"lng":135.530092,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"27-0700","desc":"入母屋造桟瓦葺の主体部に向唐破風造の式台玄関が取り付く無量寿院部分と、北半の切妻造桟瓦葺、妻入の籠堂からなる。籠堂の妻面は二重虹梁大瓶束で古式とするが、その他はガラス建具を多用するなど近代的な意匠でまとめる。様々な時代性を備える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011764"},{"id":"00010193","register_sub_id":"101","register_pk":"198026","name":"西教寺大門及び築地塀","kana":"さいきょうじおおもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501228,"lng":135.438931,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"大門 木造、瓦葺、間口2.4m 築地塀 土塀、瓦葺、総延長12m","structure_material":"大門 木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0590","desc":"境内正面の薬医門形式の大門と左右に伸びる築地塀。大門は妻虹梁上の大瓶束に雲紋の笈形を付し、棟虹梁上の束の笈形には対の龍を象るなど、力強い造形をみせる。築地塀は壁面に定規筋二本をいれ、端部の貝形に絵様虹梁と蟇股を飾る。境内表構えに風格を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010193"},{"id":"00010191","register_sub_id":"101","register_pk":"198024","name":"西教寺上書院","kana":"さいきょうじかみしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-252","lat":34.501476,"lng":135.438568,"geo_status":"db","era":"明治中期／昭和期改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積57㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0588","desc":"本堂後方に建つ、二階建、寄棟造桟瓦葺の書院で、本堂から二階へ廊下がのびる。上下階とも八畳二室と縁からなるが、二階の奥室が格式が高く、上段の間として座敷飾りを備える。二階次の間には、トコに火灯窓を穿つ。貴人の接遇用に整えられた書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010191"},{"id":"00010199","register_sub_id":"101","register_pk":"198032","name":"西教寺北門","kana":"さいきょうじきたもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501311,"lng":135.438944,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.1m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0596","desc":"境内北辺東寄り、太鼓楼と経蔵の間に建つ一間薬医門で、間口二・一メートル、切妻造本瓦葺である。五平の本柱の頂部に冠木を渡し、矩形の梁を三筋架け、鼻先の桁で垂木を受ける。太鼓楼や経蔵、本堂の屋根とともに、境内北面の街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010199"},{"id":"00010196","register_sub_id":"101","register_pk":"198029","name":"西教寺経蔵","kana":"さいきょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501342,"lng":135.438896,"geo_status":"db","era":"明治24頃","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積6.1㎡","structure_material":"土蔵造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0593","desc":"本堂前庭の北寄りに建つ。正方形平面をもつ土蔵造平屋建の経蔵で、宝形造本瓦葺とし、宝珠を載せる。外部は漆喰塗で、板軒状の軒まで塗込め、柱や長押のほか舟肘木や蟇股などの細部も漆喰で表す。内部は素木で経棚を設える。堅実な左官仕上げになる経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010196"},{"id":"00010190","register_sub_id":"101","register_pk":"198023","name":"西教寺式台玄関及び書院","kana":"さいきょうじしきだいげんかんおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501278,"lng":135.438651,"geo_status":"db","era":"安政6","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積76㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0587","desc":"本堂左手に接続する入母屋造本瓦葺の建物で、正面に式台を構える。式台の後方を六畳の玄関とし、四畳を介して八畳と六畳からなる書院を配し、縁を廻らせる。式台は正面内法に筬欄間をたて、虹梁絵様や蟇股を波紋や雲紋として飾り、格天井を張り、風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010190"},{"id":"00010195","register_sub_id":"101","register_pk":"198028","name":"西教寺鐘楼","kana":"さいきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501178,"lng":135.438888,"geo_status":"db","era":"明治32頃","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造、瓦葺、面積5.5㎡","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0592","desc":"境内正面、東門と大門の間に位置する吹放し形式の鐘楼で、切妻造本瓦葺である。切石布積の高い基壇上に建ち、円柱を貫と台輪で固め、組物三斗で中備に彫刻化した蟇股をおき、妻虹梁上の大瓶束に華やかな笈形を付ける。建ちが高く境内の正面景観を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010195"},{"id":"00010197","register_sub_id":"101","register_pk":"198030","name":"西教寺太鼓楼","kana":"さいきょうじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501294,"lng":135.438972,"geo_status":"db","era":"昭和37","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"木造2階建、瓦葺、建築面積14㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0594","desc":"境内北東隅に建つ二階建の太鼓楼。木造モルタル塗、入母屋造本瓦葺で、一階西面を出入口とし、二階は四面に黒枠の火灯窓を穿ち、アクセントとする。外壁漆喰塗で二階に長押を表し、軒は板軒状に仕上げる。角地にあって真宗寺院の伽藍景観を特徴付ける太鼓楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010197"},{"id":"00010192","register_sub_id":"101","register_pk":"198025","name":"西教寺手水屋","kana":"さいきょうじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501219,"lng":135.438825,"geo_status":"db","era":"文化13頃","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造、瓦葺、面積4.6㎡","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0589","desc":"本堂南東側の前庭に建ち、切妻造本瓦葺である。角柱四本を内転びに建て、中央に手水鉢を置き、四方吹放しとする。柱上に舟肘木を輪薙込に組んで桁と妻虹梁を受け、虹梁上に間斗束を立て、棟通りには蟇股を飾る。小規模ながら建築的細部を丁寧に仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010192"},{"id":"00010198","register_sub_id":"101","register_pk":"198031","name":"西教寺東門","kana":"さいきょうじひがしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501099,"lng":135.438834,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0595","desc":"境内東辺南端、鐘楼の隣に構える門で、本堂脇の式台玄関への入口にあたる。一間薬医門、間口二・二メートル、切妻造本瓦葺で、左右に築地塀が接続する。本柱は五平材で、男梁を三筋架け、大斗実肘木で桁と梁を受ける。日常の使用に供される通用門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010198"},{"id":"00010189","register_sub_id":"101","register_pk":"198022","name":"西教寺本堂","kana":"さいきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.501373,"lng":135.438714,"geo_status":"db","era":"文化5／大正頃改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0586","desc":"間口一五メートルの真宗寺院本堂で、背面に茶室及び奥座敷を付属する。内陣と左右の余間を上段とし、須弥壇の背面に後門を開く。外陣は左右に長い一室で前面柱間が広く、内部柱を省く。内陣や内外陣境を彫刻や極彩色で華やかに荘厳し、時代的特色をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010189"},{"id":"00010194","register_sub_id":"101","register_pk":"198027","name":"西教寺門柱及び鉄柵","kana":"さいきょうじもんちゅうおよびてつさく","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府和泉市幸2-250","lat":34.50120195,"lng":135.43897031,"geo_status":"db","era":"明治31／昭和中期改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"門柱 石造、間口2.4m、鉄扉付 鉄柵 総延長6.3m","structure_material":"門柱 石造","registered":"2014.10.07(平成26.10.07)","register_no":"27 － 0591","desc":"大門正面に構える一対の門柱と鉄柵。門柱は花崗岩製で頂部を宝形に加工し、柱間に、上辺をアーチ状とした鉄製門扉を両開きに吊る。門柱と両端の石柱との間には鉄柵を設け、鏃を付けた長短二種の縦格子を交互に立てる。大門とともに、境内入口の結界を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010194"},{"id":"00005293","register_sub_id":"101","register_pk":"106281","name":"慈願寺表門及び築地塀","kana":"じがんじおもてもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62690212,"lng":135.59790209,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"表門 木造、瓦葺、間口3.7m、築地塀 土塀、瓦葺、延長12m","structure_material":"表門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0347","desc":"境内正面の東辺中央にある。表門は１間薬医門形式で，軒は二軒繁垂木とし，切妻造，本瓦葺屋根を架ける。腕木は端部を木鼻状につくり，大斗絵様肘木を受ける。表門の両側には，Ｌ字型平面で本瓦葺屋根の築地塀が延び，重厚な正面景観をかたちづくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005293"},{"id":"00005291","register_sub_id":"101","register_pk":"106279","name":"慈願寺経蔵","kana":"じがんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.6270069,"lng":135.59764576,"geo_status":"db","era":"明治9","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積32㎡","structure_material":"土蔵造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0345","desc":"本堂の北東にある。桁行４．８ｍの寄棟造，平入で，正面の東面に唐破風造の１間向拝を設け，屋根は本瓦葺とする。外壁は漆喰塗で軒裏まで塗籠め，腰を横板で覆う。向拝の虹梁絵様や中備蟇股などの細部には，江戸末期の造形が継承されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005291"},{"id":"00005292","register_sub_id":"101","register_pk":"106280","name":"慈願寺鐘楼","kana":"じがんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.6267833,"lng":135.59786214,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造、瓦葺、面積29㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0346","desc":"表門南方にあり，切石積基壇上に建つ。桁行１間，梁間１間，四方吹放し形式で，南北棟で切妻造，本瓦葺屋根を架ける。円柱を内転びに立て，三斗を組む。妻飾の虹梁大瓶束に棟方向の虹梁を組み込み，これに鐘を吊る。架構や細部が巧みで，丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005292"},{"id":"00005290","register_sub_id":"101","register_pk":"106278","name":"慈願寺太鼓楼","kana":"じがんじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62697769,"lng":135.59788738,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋一部2階建、瓦葺、建築面積38㎡","structure_material":"木造平屋一部2階建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0344","desc":"西を正面とし，南北棟の入母屋造で平屋建の北寄りに，入母屋造の２階を載せた形式で，軒は上下とも一軒，屋根は本瓦葺である。２階は真壁造で，各面とも中央間に花頭窓を設ける。境内東の入口，表門北側の築地塀沿いにあり，街路景観上，際だった存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005290"},{"id":"00005289","register_sub_id":"101","register_pk":"106277","name":"慈願寺手水屋","kana":"じがんじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62697052,"lng":135.59781614,"geo_status":"db","era":"寛文年間","year":1667,"year_source":"estimated","year_min":1661,"year_max":1673,"year_label":"寛文年間","structure":"木造、瓦葺、面積12㎡","structure_material":"木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0343","desc":"境内の東側入口にある。桁行１間，梁間１間，四方吹放し形式で，東西棟の切妻造，本瓦葺屋根を架ける。面取角柱を内転びに立てて虹梁型頭貫で固め，大斗肘木を載せ，妻は虹梁と笈形付の蓑束で飾る。虹梁や木鼻の絵様細部等から，寛文年間のものと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005289"},{"id":"00005288","register_sub_id":"101","register_pk":"106276","name":"慈願寺本堂","kana":"じがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.626896,"lng":135.597412,"geo_status":"db","era":"文化14","year":1817,"year_source":"db","year_min":1817,"year_max":1817,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積561㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0342","desc":"入母屋造，平入，向拝１間，本瓦葺で，東面して建つ。平面は真宗本堂らしく，外陣，矢来，内陣と続き，内陣左右に余間と飛檐の間を配し，外陣の三方には吹放しの広縁を廻す。桁行１９ｍと雄大な規模を有し，架構から組物及び細部まで，充実したつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005288"},{"id":"00005294","register_sub_id":"101","register_pk":"106282","name":"慈願寺脇門及び築地塀","kana":"じがんじわきもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府八尾市本町3-104","lat":34.62675538,"lng":135.5979393,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"脇門 木造、瓦葺、間口3.1m、築地塀 土塀、瓦葺、延長12m","structure_material":"脇門 木造","registered":"2006.03.02(平成18.03.02)","register_no":"27 － 0348","desc":"脇門は境内東南方に東面して建つ。１間棟門形式で，前後に控柱を立て，軒を二軒繁垂木とし，切妻造，本瓦葺屋根を架ける。本瓦葺屋根の築地塀は脇門から北に延び，表門南側の築地塀に接続する。表門などとともに，風格のある街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005294"},{"id":"00014651","register_sub_id":"101","register_pk":"515193","name":"地蔵寺庫裏","kana":"じぞうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40833333,"lng":135.58488889,"geo_status":"db","era":"昭和13年／同50年代改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0895","desc":"景勝地の真言宗寺院山門脇にある庫裏。切妻造平入桟瓦葺、妻壁に木瓜形窓を見せる。入母屋造式台玄関を構え、虹梁蟇股にホトトギスを彫る。内部は縁を巡らした六間取座敷と元土間の台所からなる。均整の取れた大屋根が奥行きある参道の境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014651"},{"id":"00014652","register_sub_id":"101","register_pk":"515194","name":"地蔵寺山門","kana":"じぞうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40823889,"lng":135.585125,"geo_status":"db","era":"明治35年／令和2年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造、瓦葺、間口2.2m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0896","desc":"真言宗寺院の表構えとなる一間一戸薬医門。石段を登った先を花崗岩切石敷とする。切妻造桟瓦葺、軒は疎垂木で裏板流板張。男梁に板蟇股を載せ、女梁は絵様繰形付で、八双金具付板扉を吊る。全体に端正な造りで、境内の落ち着きある歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014652"},{"id":"00014650","register_sub_id":"101","register_pk":"515192","name":"地蔵寺鍾馗堂","kana":"じぞうじしょうきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40834722,"lng":135.58454722,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0894","desc":"真言宗寺院本堂北側に接続する仏堂で、鍾馗印の藤澤友吉商店が寄進。入母屋造妻入桟瓦葺。正面濡縁付、脇間に火灯窓を構える。内部は三間四方格天井畳敷、奥に仏壇を設ける。亀腹はコンクリート造。境内に瓦葺屋根を連ねて景勝地の歴史的景観となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014650"},{"id":"00014649","register_sub_id":"101","register_pk":"515191","name":"地蔵寺本堂","kana":"じぞうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府河内長野市清水111-甲他","lat":34.40822222,"lng":135.58456944,"geo_status":"db","era":"享保6年（1721）／昭和3年改修","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0893","desc":"ホトトギスの名勝で知られる真言宗寺院の本堂。宝形造桟瓦葺、元は茅葺。一軒繁垂木、柱上に絵様肘木を置く。内部は円柱を立てた中央間を折上格天井の板敷とし、背面奥に須弥壇を置く。須弥壇前に天女の板絵を吊し、他に雲形の板も伝わり荘厳に特徴有る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014649"},{"id":"00014260","register_sub_id":"101","register_pk":"509650","name":"四天王寺阿弥陀堂","kana":"してんのうじあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65318889,"lng":135.51570833,"geo_status":"db","era":"延宝2年（1674）／昭和28年・昭和63年移築","year":1674,"year_source":"db","year_min":1674,"year_max":1674,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積135㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0851","desc":"寺域南西部に北面して建つ希少な寄棟造妻入の仏堂。本瓦葺、二軒繁垂木、出組、中備正面蟇股、側面間斗束、東西五間、南北六間と奥深く、化粧屋根裏と鏡天井の外陣・格天井の内陣・後陣からなる平面構成。三重県国束寺本堂を移築した紀州徳川家ゆかりの建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014260"},{"id":"00014259","register_sub_id":"101","register_pk":"509649","name":"四天王寺廻廊","kana":"してんのうじかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65378611,"lng":135.516825,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積1116㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0850","desc":"詳細な発掘調査により、鉄骨鉄筋コンクリート造で復元した単廊と門。単廊は位置・規模は創建から変わらず、一軒隅扇垂木、小屋組は虹梁に豕扠首とする。東・西重門は三間門切妻造で小壁に人字形割束を置く。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014259"},{"id":"00014257","register_sub_id":"101","register_pk":"509647","name":"四天王寺講堂","kana":"してんのうじこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65424722,"lng":135.51642778,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積317㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0848","desc":"金堂後方に位置する鉄骨鉄筋コンクリート造による復元講堂。一重、入母屋造錣葺。東西規模、丸太材による隅扇垂木、風鐸は発掘成果に基づく。金堂に比べて柱が細く、胴張弱いのは初唐様式を参考に差別化した。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014257"},{"id":"00014255","register_sub_id":"101","register_pk":"509645","name":"四天王寺五重塔","kana":"してんのうじごじゅうのとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65360278,"lng":135.516475,"geo_status":"db","era":"昭和34年／令和元年補強","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄骨鉄筋コンクリート造五重塔、瓦葺、建築面積56㎡","structure_material":"鉄骨鉄筋コンクリート造五重塔","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0846","desc":"伽藍中心に位置する鉄骨鉄筋コンクリート造の五重塔。塔高約三七メートル、外観は法隆寺五重塔に倣い飛鳥様式を基本に、より古い形態とするが、内部は六層でらせん階段を配する。発掘成果に基づき古代寺院の姿を復元した初例で、藤島亥治郎の設計による。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014255"},{"id":"00014256","register_sub_id":"101","register_pk":"509646","name":"四天王寺金堂","kana":"してんのうじこんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65387222,"lng":135.51645,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積231㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0847","desc":"詳細な発掘調査に基づき創建位置に鉄骨鉄筋コンクリート造で復元した金堂。二重、入母屋造錣葺。高さは法隆寺の塔と金堂の関係に倣い、外観は法隆寺金堂を基本とし、より大陸的で直線的な構成とした。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014256"},{"id":"00014262","register_sub_id":"101","register_pk":"509652","name":"四天王寺聖霊院唐門","kana":"してんのうじしょうりょういんからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65297778,"lng":135.51715,"geo_status":"db","era":"文化5年（1808）／明治30年頃・昭和27年移築・同54年頃改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.6㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0853","desc":"寺域南東部に南面して建つ四脚門。切妻造で軒唐破風付、銅板葺は元は檜皮葺で、二軒繁垂木とする。桟唐戸、礎盤、粽柱など禅宗様の意匠と、蟇股等の精巧な彫刻で格式高く飾る。徳川家康を合祀した用明殿の正門として建築、本坊御成門を経て、現在地に至る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014262"},{"id":"00014264","register_sub_id":"101","register_pk":"509654","name":"四天王寺青龍亭","kana":"してんのうじせいりゅうてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65589444,"lng":135.51808889,"geo_status":"db","era":"明治後期／平成15年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0855","desc":"四天王寺本坊の庭園内に建つ独立した茶室。木造平家建、屋根は銅板葺で元は杉皮葺。内部は台形と正三角形の二席と、これらを繋ぐ水屋からなる斬新な平面で、各部意匠は侘びた風情を醸す草庵風だが、一方で開口部が大きくて明るく近代的な茶室である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014264"},{"id":"00014258","register_sub_id":"101","register_pk":"509648","name":"四天王寺中門","kana":"してんのうじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65335833,"lng":135.51648056,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄骨鉄筋コンクリート造平屋建、瓦葺、建築面積86㎡","structure_material":"鉄骨鉄筋コンクリート造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0849","desc":"詳細な発掘調査に基づき、創建位置に鉄骨鉄筋コンクリート造で復元した中門。三間一戸八脚門、入母屋造錣葺。一軒隅扇垂木、雲斗など全体に意匠は飛鳥様式とする。上部構造は塔や南大門との関係から単層とした。発掘成果に基づき古代寺院の姿を復元した初例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014258"},{"id":"00014261","register_sub_id":"101","register_pk":"509651","name":"四天王寺納骨堂","kana":"してんのうじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65317222,"lng":135.51558056,"geo_status":"db","era":"江戸中期／昭和28年・昭和63年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0852","desc":"寺域南西部に北面して建つ方三間仏堂。宝形造桟瓦葺、一軒疎垂木、平三斗組、中備正面中央蟇股それ以外蓑束。角柱で上端に粽を付け、肘木は笹繰付。内部は格天井で、奥側三面に納骨壇、その中央に軒唐破風の宮殿を置く。三重県国束寺聖天堂を移築したもの。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014261"},{"id":"00014263","register_sub_id":"101","register_pk":"509653","name":"四天王寺本坊唐門","kana":"してんのうじほんぼうからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区四天王寺一丁目","lat":34.65486111,"lng":135.51708333,"geo_status":"db","era":"江戸後期／天保頃改修・明治30年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0854","desc":"寺域北東部の本坊の南西に建つ正門。向唐門本瓦葺で元檜皮葺、格天井とし、桟唐戸、礎盤、粽柱など禅宗様を基調とする。徳川歴代将軍の霊牌を祀る五智光院の正門として建築、虹梁上の霊廟守護の雲竜彫刻、扉の三つ葉葵紋透彫り、錺金具を施すなど格式高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014263"},{"id":"00007237","register_sub_id":"101","register_pk":"108219","name":"稱念寺山門","kana":"しょうねんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-5-1","lat":34.66506362,"lng":135.51133872,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0466","desc":"松屋町筋に西面して建つ一間薬医門。間口２．９ｍ幅に本柱を建て、女梁、冠木、男梁を架し、妻及び中備には蟇股を置く。一軒疎垂木で、屋根を切妻造本瓦葺とする。装飾を抑えるが、木鼻など細部に、江戸中期らしい意匠を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007237"},{"id":"00007247","register_sub_id":"101","register_pk":"108229","name":"稱名寺山門","kana":"しょうみょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町2-14","lat":34.659035,"lng":135.5108728,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0476","desc":"松屋町筋に西面する一間高麗門。間口２．８ｍで、腰海鼠壁とする袖塀を両脇に付ける。妻蟇股とし、軒は一軒繁垂木。切妻造本瓦葺で、棟には龍の飾り瓦、隅蓋瓦に波紋を飾る。小規模ながら、たちの高い高麗門で、薬医門が並ぶ下寺町において印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007247"},{"id":"00014634","register_sub_id":"101","register_pk":"515176","name":"真行寺本堂","kana":"しんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目39","lat":34.67075,"lng":135.56044167,"geo_status":"db","era":"天保3年（1832）／昭和33年・平成16年頃改修","year":1832,"year_source":"db","year_min":1832,"year_max":1832,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0878","desc":"旧深江村の集落北寄りにある真宗寺院の本堂。入母屋造平入本瓦葺、正面五間、向拝付、奥行の三間半を外陣及び脇間、框を入れて奥を一段高く内陣と左右余間とし、須弥壇背面に後門を開く。内外陣境を彫刻欄間と菱格子欄間で荘厳する。集落の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014634"},{"id":"00007244","register_sub_id":"101","register_pk":"108226","name":"心光寺山門","kana":"しんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-7","lat":34.66169,"lng":135.511047,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0473","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口２．７ｍ幅に本柱を建て、女梁と男梁、冠木を架し、男梁上に大斗を載せ、虹梁と軒桁を支持する。妻は虹梁大瓶束。大瓶束の上方には木鼻を四方に出す。男梁鼻先や虹梁絵様などの細部意匠は秀逸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007244"},{"id":"00003565","register_sub_id":"101","register_pk":"104555","name":"心光寺本堂","kana":"しんこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-3-68","lat":34.661678,"lng":135.51152,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積228㎡、ドーム付","structure_material":"鉄筋コンクリート造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"27 － 0258","desc":"市内を南北に貫通する松屋町筋東方の寺町に位置する。火災後の再建になる鉄筋コンクリート造寺院で，住職の設計と伝える。ドーム屋根，柱上の相輪風の飾り，パラペットの宝珠柱風手摺子，多弁アーチなどによりインド風の外観を造りだす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003565"},{"id":"00011353","register_sub_id":"101","register_pk":"209190","name":"真宗大谷派茨木別院鐘楼","kana":"しんしゅうおおたにはいばらきべついんしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府茨木市別院町3-31","lat":34.816896,"lng":135.574227,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積8.8㎡","structure_material":"木造","registered":"2016.11.29(平成28.11.29)","register_no":"27－0651","desc":"本堂南東側に位置し、花崗岩を精緻に積む基壇上に南北棟で建つ吹放ち形式の鐘楼で切妻造本瓦葺。軸部は石製礎盤に几帳面取角柱を立て、三斗を組む。妻飾は虹梁蟇股で、大梁端部が蟇股を貫いて波紋の木鼻となる独特な造形をもつ。街路からの景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011353"},{"id":"00011351","register_sub_id":"101","register_pk":"209188","name":"真宗大谷派茨木別院本堂","kana":"しんしゅうおおたにはいばらきべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府茨木市別院町3-31","lat":34.817042,"lng":135.573818,"geo_status":"db","era":"安永6","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積778㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"27－0649","desc":"市街地の境内に東面し、桁行三〇メートルを測る大堂。後門形式の平面など真宗寺院本堂の典型を示す一方、矢来内を外陣より一段高め、余間まわりを円柱とするなど高い寺格も表している。力感ある軸部、壮大な内部、優れた意匠に工匠の高い力量が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011351"},{"id":"00002060","register_sub_id":"101","register_pk":"103050","name":"少彦名神社拝殿","kana":"すくなひこなじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町2-1-8","lat":34.68875017,"lng":135.50598893,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0121","desc":"桁行３間，梁間２間，入母屋造，銅板葺で，正面に千鳥破風，軒唐破風を付ける。中央１間通りはもと土間で割拝殿形式であった。全体に簡素な造りだが正面は装飾的な構えとなり，虹梁上に太瓶束を立て菖蒲桁を受ける唐破風の構成など，巧みな処理が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002060"},{"id":"00002059","register_sub_id":"101","register_pk":"103049","name":"少彦名神社幣殿","kana":"すくなひこなじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町2-1-8","lat":34.68879141,"lng":135.50599845,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0120","desc":"正面一間，側面二間，両下造，銅板葺で，本殿正面に取り付く。角柱に虹梁形頭貫を通し台輪を載せ，絵様肘木及び中備の蟇股を置いて桁を受け，正面では笈形付太瓶束を立て棟木を支える。本殿と対照的に彫刻を多用した建物で，一体となって特徴ある構成を造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002059"},{"id":"00002058","register_sub_id":"101","register_pk":"103048","name":"少彦名神社本殿","kana":"すくなひこなじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市中央区道修町2-1-8","lat":34.68881993,"lng":135.50600083,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"27 － 0119","desc":"道修町は江戸時代以来，薬問屋が集中する地で，当社は薬の神である少彦名命を祀る。本殿は桁行一間，梁間二間，切妻造，銅板葺，平入りの小規模な社殿で，妻梁を虹梁形に造るほか装飾のない簡素な造りだが，全体の比例が良く，良材による質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002058"},{"id":"00012422","register_sub_id":"101","register_pk":"531746","name":"住吉大社角鳥居","kana":"すみよしたいしゃかくとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61248333,"lng":135.49255556,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口4.0m、高さ4.1m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-748","desc":"本宮域の幸寿門前に立つ。石造で、柱に大面取の角柱を用いるが、貫を通し、反りのある島木･笠木を重ねるなど明神鳥居の形式とする。重心の低いどっしりとした造形で境内の他の鳥居と一線を画する。同社を代表する鳥居として古くから参拝者に親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012422"},{"id":"00012405","register_sub_id":"101","register_pk":"531729","name":"住吉大社北絵馬殿","kana":"すみよしたいしゃきたえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61265,"lng":135.4919,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-731","desc":"神池にかけられた反橋手前の表参道北側に建つ。桁行三間梁間一間、東西棟の切妻造本瓦葺で、規模･形式とも南絵馬殿と寸分違わない。用途上の使い分けもなく二棟一対で絵馬殿として機能する。反橋と調和し、同社を象徴する社頭景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012405"},{"id":"00012421","register_sub_id":"101","register_pk":"531745","name":"住吉大社北大鳥居","kana":"すみよしたいしゃきたおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61333333,"lng":135.49225833,"geo_status":"db","era":"江戸前期／明治前期移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口5.7m、高さ6.5m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-747","desc":"境内側面の北からの参道入口に立つ。石造で、西鳥居と同じ形式の明神鳥居であるが、規模は一回り小さくつくる。東と南の大鳥居とは同規模で、四基一対で四至を結界する。境内の四方を固める主要な入口の一つとして、広大な境内の北面の構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012421"},{"id":"00012414","register_sub_id":"101","register_pk":"531738","name":"住吉大社北瑞籬門","kana":"すみよしたいしゃきたみずがきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61256389,"lng":135.49364722,"geo_status":"db","era":"江戸後期／昭和38年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、銅板葺、間口4.4m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-740","desc":"本宮域の背面北端にある切妻造銅板葺の四脚門。規模･形式とも南端籬門と寸分違わず、本宮域の背後を固める左右一対の門としてつくられる。南端籬門と同じく、第一殿の脇に建ち、境内中心部の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012414"},{"id":"00012424","register_sub_id":"101","register_pk":"531748","name":"住吉大社北脇参道角鳥居","kana":"すみよしたいしゃきたわきさんどうかくとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61328889,"lng":135.4917,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造、間口4.6m、高さ5.0m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-750","desc":"北脇参道の入口に立つ。柱を大面取の角柱とした石造の明神鳥居で、幸寿門前の角鳥居の形式に準ずるが、均整のとれた造形と均質な仕上が時代感覚を伝える。南脇参道角鳥居と左右一対で中央の西大鳥居の脇を固める、同社の境内正面の構成に不可欠な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012424"},{"id":"00012411","register_sub_id":"101","register_pk":"531735","name":"住吉大社幸寿門","kana":"すみよしたいしゃこうじゅもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61246111,"lng":135.49263333,"geo_status":"db","era":"江戸前期／昭和45年移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、銅板葺、間口4.6m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-737","desc":"本宮域の正面中央にある切妻造銅板葺の四脚門。組物は実肘木付の三斗、妻飾は虹梁蟇股、破風に梅鉢懸魚を吊る。門扉の上は冠木と棟木の間に虹梁を入れ、その下に蟇股、上に大瓶束を備えた独特の構成とするなど、本宮域の表構えとしての格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012411"},{"id":"00012412","register_sub_id":"101","register_pk":"531736","name":"住吉大社幸福門","kana":"すみよしたいしゃこうふくもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61223889,"lng":135.4926,"geo_status":"db","era":"江戸前期／昭和45年移築","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、銅板葺、間口4.5m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-738","desc":"本宮域の正面脇にある切妻造銅板葺の四脚門。幸寿門と同じ規模･形式であるが、組物を大斗肘木とし、冠木と棟木の間は中備の蓑束のみとするなど全体に抑制の効いた造形とする。幸寿門と同じく、境内における江戸前期の建築形式を伝える貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012412"},{"id":"00012409","register_sub_id":"101","register_pk":"531733","name":"住吉大社斎館","kana":"すみよしたいしゃさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61201944,"lng":135.4934,"geo_status":"db","era":"文政11年(1828)／大正4年移築","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積164㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-735","desc":"神館背面に建つ。桁行七間梁間五間半、入母屋造本瓦葺で、上段の間を中心として前三室、後二室に座敷を配し、正面から側面に縁を廻す。組物は舟肘木、妻飾は木連格子で梅鉢懸魚を吊る。規模が大きく、境内中心部の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012409"},{"id":"00012406","register_sub_id":"101","register_pk":"531730","name":"住吉大社五月殿","kana":"すみよしたいしゃさつきでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61171111,"lng":135.4925,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-732","desc":"神館域正面脇の御田北側にあって御田植神事に用いられる。桁行三間梁間二間、東西棟の切妻造本瓦葺、吹放ち形式で、境内で唯一壇上積基壇に建つ。飾気の少ない素木造に太い面取角柱や虹梁を用いて豪放に仕上げる。御田と一体で伝統ある景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012406"},{"id":"00005757","register_sub_id":"101","register_pk":"106745","name":"住吉大社神館","kana":"すみよしたいしゃしんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区住吉2-9-89","lat":34.611938,"lng":135.493149,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積301㎡","structure_material":"木造平屋建","registered":"2006.10.18(平成18.10.18)","register_no":"27 － 0381","desc":"大正天皇の即位記念として建設。本宮の東方に位置する。南面する大床を備えた８畳の「玉座」の間を中心に複雑な屋根を架け，西面に唐破風造の玄関車寄を突き出す。各面に破風を見せる屋根構成と優美な深い軒線の意匠に特徴がある。設計は大阪府技師の池田實。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005757"},{"id":"00012415","register_sub_id":"101","register_pk":"531739","name":"住吉大社神館西門","kana":"すみよしたいしゃしんかんにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61191944,"lng":135.4927,"geo_status":"db","era":"文政11年（1828）／明治中期移築","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造、瓦葺、間口4.5m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-741","desc":"神館域の正面中央にある切妻造本瓦葺の四脚門。組物は実肘木付の三斗、妻飾は虹梁蟇股、冠木と棟木の間に虹梁を入れて蟇股と大瓶束を備える。素木造だが幸寿門に共通する形式で、虹梁や蟇股等の絵様も流麗で気品があり、神館域の表構えとしての格式を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012415"},{"id":"00012407","register_sub_id":"101","register_pk":"531731","name":"住吉大社神馬舎","kana":"すみよしたいしゃしんめしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61306944,"lng":135.4921,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-733","desc":"表参道に並行する北脇参道の西脇に建つ。桁行二間梁間三間、切妻造本瓦葺妻入で、北面に下屋を設けて屋根を葺下ろす。内部は主体部を土間の馬房、下屋を床張の馬丁部屋とする。現在も厩舎に用いられている、境内をかたちづくる伝統的な構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012407"},{"id":"00012418","register_sub_id":"101","register_pk":"531742","name":"住吉大社摂社大海神社北小門","kana":"すみよしたいしゃせっしゃたいかいじんじゃきたしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61413056,"lng":135.4937,"geo_status":"db","era":"江戸後期／明治前期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-744","desc":"摂社大海神社の正面北脇を区切る瑞垣に開く。切妻造本瓦葺の棟門で、親柱を円柱、控柱を角柱とし、南小門と同じ規模･形式であるが、冠木と棟木の間に横桟を入れるなど細部に違いがある。小規模ながら南小門と一対になって、大海神社の社頭景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012418"},{"id":"00012417","register_sub_id":"101","register_pk":"531741","name":"住吉大社摂社大海神社南小門","kana":"すみよしたいしゃせっしゃたいかいじんじゃみなみしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.613675,"lng":135.493575,"geo_status":"db","era":"江戸後期／明治14年頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-743","desc":"摂社大海神社の正面南脇を区切る瑞垣に開く。切妻造本瓦葺の棟門で、親柱を円柱として角柱の控柱を前後に備える。棟木は冠木上に立てた束で受け、屋根には反りを付けて梅鉢懸魚を吊る。小規模ながら北小門と一対になって、大海神社の社頭景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012417"},{"id":"00012394","register_sub_id":"101","register_pk":"531718","name":"住吉大社摂社船玉神社本殿","kana":"すみよしたいしゃせっしゃふなたまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61210833,"lng":135.49260556,"geo_status":"db","era":"明治前期／昭和45年移築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、檜皮葺、建築面積7.5㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-720","desc":"神館域の正面脇に建つ。正面側面とも一間、切妻造檜皮葺妻入で、妻飾の豕扠首や本宮本殿と同形式の懸魚、内外陣に分かれる平面など住吉造に準じた形式とする。規模が大きく、鰹木と千木を載せた屋根が古式を強調し、境内中心部の復古的景観を演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012394"},{"id":"00012425","register_sub_id":"101","register_pk":"531749","name":"住吉大社摂社若宮八幡宮鳥居","kana":"すみよしたいしゃせっしゃわかみやはちまんぐうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61216111,"lng":135.4939,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造、間口2.0m、高さ2.3m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-751","desc":"本宮域の後方、南中門の脇にある摂社若宮八幡宮前に立つ。柱に角柱を用い、貫を柱内で納め、反りのない島木･笠木を重ねる独特の形式とする。数多くの鳥居を有する境内にあって、類例少ない形式で希少である。建築年代が明らかな鳥居としても貴重な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012425"},{"id":"00012419","register_sub_id":"101","register_pk":"531743","name":"住吉大社西大鳥居","kana":"すみよしたいしゃにしおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61258056,"lng":135.4916,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口6.1m、高さ6.4m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-745","desc":"境内正面の表参道入口に立つ。石造で、内転びの丸柱に貫を通し、反りのある島木･笠木を重ねた明神鳥居形式であるが、木割が太く安定感のある造形が古式を伝える。同社最大の大鳥居として参拝者に親しまれるとともに森厳な境内正面の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012419"},{"id":"00012396","register_sub_id":"101","register_pk":"531720","name":"住吉大社末社侍者社拝所・神饌所","kana":"すみよしたいしゃまっしゃおもとしゃはいしょ・しんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61215,"lng":135.4932,"geo_status":"db","era":"文政5年(1822)／昭和5年改修","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-722","desc":"境内中心部の本宮域と神館域の境に建つ。桁行六間梁間三間、切妻造銅板葺妻入で、前三間を神饌所、後三間を拝所とし、拝所最奥に本殿を安置する。拝所の左右には扉を開き、本宮域と神館域を結び付ける。同社の独特な境内の構成の核となる社殿の一つである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012396"},{"id":"00012395","register_sub_id":"101","register_pk":"531719","name":"住吉大社末社侍者社本殿","kana":"すみよしたいしゃまっしゃおもとしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61215556,"lng":135.49324167,"geo_status":"db","era":"文政5年(1822)","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-721","desc":"侍者社拝所･神饌所にある境内唯一の屋内安置の本殿。正面側面とも一間、正面入母屋造、背面切妻造、檜皮葺妻入で、脇障子を立て高欄付の縁と木階七級を設ける。組物は舟肘木、妻飾は木連格子で本宮本殿と同形式の懸魚を吊る。細部は金物で豊かに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012395"},{"id":"00012401","register_sub_id":"101","register_pk":"531725","name":"住吉大社末社貴船社本殿","kana":"すみよしたいしゃまっしゃきぶねしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61208056,"lng":135.4943,"geo_status":"db","era":"江戸後期／昭和中期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-727","desc":"本宮域の背後に立聞社と並んで建つ。正面側面とも一間、切妻造本瓦葺妻入で、外陣正面に袖壁を付し、内外陣境は長押がなく虹梁に板扉を嵌込む。立聞社と同じ規模･形式であるが細部に違いがある。住吉造に倣った本殿形式の多彩な細部意匠の展開を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012401"},{"id":"00012403","register_sub_id":"101","register_pk":"531727","name":"住吉大社末社五社本殿","kana":"すみよしたいしゃまっしゃごしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61312778,"lng":135.49455,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-729","desc":"神苑の奥に建つ末社群の一つ。本瓦葺の五間社流造で、正面に縁と木階五級を設ける。妻は豕扠首で本宮本殿と同形式の懸魚を吊る。身舎各間は外陣を開放し、境に板扉を備える。境内後方を構成する末社群の景観にあって変化のある存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012403"},{"id":"00012402","register_sub_id":"101","register_pk":"531726","name":"住吉大社末社后土社本殿","kana":"すみよしたいしゃまっしゃごどしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61313611,"lng":135.49475556,"geo_status":"db","era":"江戸後期／昭和中期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-728","desc":"境内後方の神苑の奥に建つ末社群の一つ。正面側面とも一間、切妻造桟瓦葺妻入で、妻の豕扠首や反りのある屋根、土台建で見世棚風につくる外陣など、住吉造に準じた末社共通の形式を有する。立聞社や貴船社と同じく、住吉造系の本殿形式の多様性を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012402"},{"id":"00012400","register_sub_id":"101","register_pk":"531724","name":"住吉大社末社立聞社本殿","kana":"すみよしたいしゃまっしゃたちききしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61208889,"lng":135.4942,"geo_status":"db","era":"文政11年(1828)／昭和27年移築","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-726","desc":"本宮域の背後に貴船社と並んで建つ。正面側面とも一間、切妻造本瓦葺妻入で、柱は直接梁を受け、妻飾は豕扠首で梅鉢懸魚を吊る。面取角柱を土台建にして床を高く張り、外陣を見世棚造風にしながら、全体的には住吉造に倣った形式を有している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012400"},{"id":"00012399","register_sub_id":"101","register_pk":"531723","name":"住吉大社末社龍社本殿","kana":"すみよしたいしゃまっしゃたつしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61211944,"lng":135.4923,"geo_status":"db","era":"江戸後期／昭和4年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積6.7㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-725","desc":"神館域前方の神池のほとりに建つ。正面側面とも一間、切妻造本瓦葺妻入で、平面は内外陣に分かれ、外陣を開放し、境に板扉を構える。内陣は床を張らず、中央に井戸がある。水神と関わりの深い同社の信仰を端的に示す社殿で、形式も住吉造に準じている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012399"},{"id":"00012398","register_sub_id":"101","register_pk":"531722","name":"住吉大社末社楠珺社拝殿","kana":"すみよしたいしゃまっしゃなんくんしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61230556,"lng":135.49438889,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-724","desc":"楠珺社本殿の前面に建つ。切妻造平入の前面に入母屋造妻入を接続したＴ字形屋根をかけ、正面に向唐破風の向拝を付け、背面に祭壇を突出する。内部は土間の参拝空間とし、祭壇を床張とする。参拝の多様化に応じた大規模社殿で、信仰空間の新局面を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012398"},{"id":"00012397","register_sub_id":"101","register_pk":"531721","name":"住吉大社末社楠珺社本殿","kana":"すみよしたいしゃまっしゃなんくんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61225278,"lng":135.49437778,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.8㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-723","desc":"本宮域の背面にある神木の洞に差し込まれるように建つ。正面一間、切妻造銅板葺妻入で、屋根には反りを付け蕪懸魚を吊る。平面は内外陣に分かれ、外陣を開放し、境に板扉を構える。朱塗に飾金具を多用するなど小規模ながら装飾豊かな社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012397"},{"id":"00012404","register_sub_id":"101","register_pk":"531728","name":"住吉大社南絵馬殿","kana":"すみよしたいしゃみなみえまでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61245,"lng":135.4919,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.05.10(平成30.05.10)","register_no":"27-730","desc":"神池にかけられた反橋手前の表参道南側に建つ。桁行三間梁間一間、東西棟の切妻造本瓦葺、吹放ち形式で、太い大面取角柱や切石敷風にしたモルタル土間など、復古的な意匠でまとめられている。反橋と調和し、同社を象徴する社頭景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012404"},{"id":"00012420","register_sub_id":"101","register_pk":"531744","name":"住吉大社南大鳥居","kana":"すみよしたいしゃみなみおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61116667,"lng":135.49196389,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、間口5.7m、高さ6.4m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-746","desc":"境内側面の南からの参道入口に立つ。石造で、西鳥居と同じ形式の明神鳥居であるが、規模は一回り小さくつくる。東と北の大鳥居とは同規模で、四基一対で四至を結界する。境内の四方を固める主要な入口の一つとして、広大な境内の南面の構えの核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012420"},{"id":"00012416","register_sub_id":"101","register_pk":"531740","name":"住吉大社南中門","kana":"すみよしたいしゃみなみちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61214722,"lng":135.49375833,"geo_status":"db","era":"江戸後期／昭和38年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口5.3m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-742","desc":"南門から石舞台と続く神館域裏の参道上に建つ。切妻造本瓦葺の四脚門で、組物を三斗、妻飾を虹梁蟇股とするなど旧規を踏襲するが、虹梁や蟇股等の絵様は動的で量感に富み、時代感覚を現している。同社最大の門で、境内南辺の歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012416"},{"id":"00012408","register_sub_id":"101","register_pk":"531732","name":"住吉大社南手水舎","kana":"すみよしたいしゃみなみてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.612,"lng":135.49233889,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積8.5㎡、手水鉢付","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-734","desc":"表参道に並行する南脇参道の終点に建つ。桁行一間梁間一間、東西棟の入母屋造本瓦葺、吹放ち形式で、中央に水盤を据える。柱は几帳面取、組物は出組、軒は二軒扇垂木で格天井を張る。小規模ながら華麗なつくりで、伝統的な境内構成に彩りを添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012408"},{"id":"00012413","register_sub_id":"101","register_pk":"531737","name":"住吉大社南瑞籬門","kana":"すみよしたいしゃみなみみずがきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61221944,"lng":135.4936,"geo_status":"db","era":"江戸後期／昭和38年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、銅板葺、間口4.4m","structure_material":"木造","registered":"2018.05.10(平成30.05.10)","register_no":"27-739","desc":"本宮域の背面南端にある切妻造銅板葺の四脚門。組物を大斗肘木、妻飾を虹梁蟇股とするなど旧規を踏襲するが、虹梁や木鼻等の絵様は控えめな形状ながら極太で力強く、時代感覚を現している。第一殿の脇に建ち、境内中心部の歴史的景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012413"},{"id":"00012423","register_sub_id":"101","register_pk":"531747","name":"住吉大社南脇参道角鳥居","kana":"すみよしたいしゃみなみわきさんどうかくとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区住吉二丁目9-89","lat":34.61201944,"lng":135.4913,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造、間口4.6m、高さ5.1m","structure_material":"石造","registered":"2018.05.10(平成30.05.10)","register_no":"27-749","desc":"南脇参道の入口に立つ。幸寿門前の角鳥居の形式を踏襲する石造の明神鳥居で、規模･形式とも寸分違わず北脇参道角鳥居と同じである。北脇参道角鳥居と左右一対で中央の西大鳥居の脇を固める、同社の境内正面の構成に不可欠な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012423"},{"id":"00014503","register_sub_id":"101","register_pk":"513917","name":"聖贖主教会（博愛社礼拝堂）","kana":"せいあがないぬしきょうかい（はくあいしゃれいはいどう）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市淀川区十三元今里三丁目63-4他","lat":34.7218,"lng":135.47608056,"geo_status":"db","era":"昭和11年／同62年・平成26年改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積265㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"27 - 0874","desc":"ヴォーリズ建築事務所設計のロマネスク調の鉄筋コンクリート造教会。外観は正面バラ窓、鐘楼塔屋とタレットが特徴的。当初は一階は社会福祉のために使用し、二階以上の教会と区切っていた。アウトフレームにより礼拝堂は意匠平明で落ち着いた空間とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014503"},{"id":"00002951","register_sub_id":"101","register_pk":"103941","name":"清学院庫裏","kana":"せいがくいんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区北旅龍町西1丁3-13","lat":34.59111447,"lng":135.482819,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積75㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0189","desc":"不動堂の南面と東面に接続した鍵形平面の住居建築で，不動堂側面にあたる南面に式台玄関を設け，奥に八畳間２室を配し，玄関南側を土間とする。切妻造で，不動堂南面から延びた部分は，つし２階で虫籠窓を設けた町家の外観とし，市街地の寺院の特色が伺える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002951"},{"id":"00002950","register_sub_id":"101","register_pk":"103940","name":"清学院不動堂","kana":"せいがくいんふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区北旅龍町西1丁3-13","lat":34.59118088,"lng":135.48277639,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0188","desc":"桁行・梁間とも２間半の小仏堂で，通りに西面して建つ。切妻造・本瓦葺，平入，軸部は角柱とし，内部は８畳間で後方半間に通仏壇を構え，中央に軒唐破風付きの宮殿形厨子を置く。虹梁や木鼻の細部様式から江戸末期と考えられる。類例の少ない修験道場の建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002950"},{"id":"00002952","register_sub_id":"101","register_pk":"103942","name":"清学院門","kana":"せいがくいんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府堺市堺区北旅龍町西1丁3-13","lat":34.59113794,"lng":135.48274525,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口1.7m、左右塀付","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"27 － 0190","desc":"元禄２年（１６８９）の堺大絵図に「山伏清学院」とあり，江戸時代を通じての修験道場で，建物は江戸末期のものと考えられる。門は１間１戸の薬医門で，垂木に反りがある軽快な意匠とする。庫裏玄関前の前庭を囲うように建ち，市街地の街路景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002952"},{"id":"00009340","register_sub_id":"101","register_pk":"194133","name":"善龍寺山門","kana":"ぜんりゅうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町2-1-17","lat":34.66111004,"lng":135.51157243,"geo_status":"db","era":"文化7年／昭和前期移築","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2012.08.13(平成24.08.13)","register_no":"27 － 0549","desc":"境内南面、天王寺七坂の一つ口縄坂沿いに建つ。間口二・七メートルの薬医門形式で、切妻造本瓦葺とし、左右に潜付袖塀を付す。架構は冠木上に架けた男梁に三斗をおいて妻虹梁を受け、妻飾には雲紋彫刻化した蟇股を飾る。良材を用い、意匠も優れた山門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009340"},{"id":"00007246","register_sub_id":"101","register_pk":"108228","name":"大光寺山門","kana":"だいこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町2-6","lat":34.660118,"lng":135.51098052,"geo_status":"db","era":"寛延2","year":1749,"year_source":"db","year_min":1749,"year_max":1749,"year_label":null,"structure":"木造、瓦葺、間口2.8m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0475","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口２．８ｍで、潜戸付の袖塀を両脇に付ける。女梁を挿し肘木状に作り、男梁上、大斗肘木を介し、虹梁と軒桁を支持する。軒は一軒繁垂木。妻と中備は笈形付の虹梁大瓶束で、妻と中備の笈形の意匠を違える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007246"},{"id":"00002799","register_sub_id":"101","register_pk":"103789","name":"大光寺太子館","kana":"だいこうじたいしかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府吹田市岸部中5-10-10","lat":34.780518,"lng":135.539185,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積83㎡","structure_material":"木造2階建","registered":"2002.06.25(平成14.06.25)","register_no":"27 － 0179","desc":"真宗寺院にある聖徳太子を祀る木造２階建の仏堂。地元の工匠の手になると考えられるが，１階を大壁で縦長窓の洋風意匠，２階を真壁で柱頭に舟肘木を置き軒を反らせる和風意匠とする新機軸で，洋風意匠の在郷への浸透を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002799"},{"id":"00013612","register_sub_id":"101","register_pk":"504983","name":"建水分神社摂社南木神社築地塀","kana":"たけみくまりじんじゃせっしゃなぎじんじゃついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.45996944,"lng":135.63146111,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"鉄筋コンクリート造、瓦葺、総延長41m","structure_material":"鉄筋コンクリート造","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0816","desc":"拝殿の背後の東西から延びて本殿の側背面を囲う鉄筋コンクリート造桟瓦葺の塀。側面塀の後方は地形なりに登り、段上の背面塀に接続する。全体を漆喰で塗込め、基壇、柱、頭繋ぎなどを現し、妻の破風なども丁寧につくる。本殿周りの静謐な空間を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013612"},{"id":"00013611","register_sub_id":"101","register_pk":"504965","name":"建水分神社摂社南木神社拝殿及び幣殿","kana":"たけみくまりじんじゃせっしゃなぎじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.46009444,"lng":135.63143056,"geo_status":"db","era":"昭和15年／平成16年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0815","desc":"本殿前に北面して建つ。正面五間側面二間、切妻造銅板葺、正面三間向拝付。向拝中央間は屋根を切欠いて一段高く向唐破風屋根を付す。四周に縁を廻し、背面両端に一間四方の室が突出し中央に唐破風屋根の幣殿が接続する。特異な形式ながら端正な意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013611"},{"id":"00013610","register_sub_id":"101","register_pk":"504964","name":"建水分神社摂社南木神社本殿","kana":"たけみくまりじんじゃせっしゃなぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.46,"lng":135.63145,"geo_status":"db","era":"昭和13年／平成16年・同29年改修","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0814","desc":"建水分神社境内にある楠木正成を祀る摂社。本殿は境内中段南側に北面して建つ。一間社春日造銅板葺で、正側面に腰高く縁を廻して脇障子を建て、縁の両端に至る幅広の木階を付して浜縁を設ける。楠公顕彰の機運が高まる中再興された、端正なつくりの近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013610"},{"id":"00013613","register_sub_id":"101","register_pk":"504984","name":"建水分神社宝庫","kana":"たけみくまりじんじゃほうこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字水分1060","lat":34.46061111,"lng":135.63159722,"geo_status":"db","era":"大正9年頃","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積40㎡","structure_material":"土蔵造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0817","desc":"境内下段の参道沿いに西面して建つ。木造平屋建、切妻造妻入桟瓦葺で、正面に切妻屋根の玄関を付す。外壁は漆喰で軒先まで塗込めて軒下に鉢巻を廻し、側面に窓を四連開いて腰を竪板張とする。内部は一室で中央に陳列棚を設ける。参道入口の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013613"},{"id":"00015063","register_sub_id":"101","register_pk":"529341","name":"千早神社小宮（旧本殿）","kana":"ちはやじんじゃこみや（きゅうほんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41618611,"lng":135.65287778,"geo_status":"db","era":"明治7年／昭和56年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0934","desc":"社務所の北に建ち、参道に南面する一間社流造銅板葺の旧本殿。三方に縁を廻らし、脇障子を建て、組物は大斗肘木、軒は一軒繁垂木、妻飾は豕扠首。肘木や虹梁に絵様を入れ、庇の中備に菊と波の彫刻を付す。小規模ながら装飾豊富な社殿で、境内の旧景を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015063"},{"id":"00015062","register_sub_id":"101","register_pk":"529340","name":"千早神社社務所","kana":"ちはやじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41607778,"lng":135.65278611,"geo_status":"db","era":"昭和7年／昭和50年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0933","desc":"参道に北面する社務所。平屋建銅板葺で、式台棟、授与所棟、主体部のそれぞれ切妻屋根を正面にみせる。内部南西は続き間座敷で南東に床を構え、南西に縁を廻らす。軒薄く簡明ながれも螻羽が深い切妻屋根を前方に突出して強調した力強い外観が特徴的な社務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015062"},{"id":"00015061","register_sub_id":"101","register_pk":"529339","name":"千早神社手水舎","kana":"ちはやじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41612222,"lng":135.65299167,"geo_status":"db","era":"昭和3年／昭和50年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、面積1.6㎡","structure_material":"木造","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0932","desc":"本殿の北西、参道に南面する切妻造平入銅板葺の手水舎。主柱を棟木まで延ばし、前後に低い控柱を立てて貫で固める。二段の腕木で軒桁を支え、主柱間に楣を入れ欄間は横連子。中央に自然石組の手水鉢を置く。簡明ながら存在感を示す手水舎で境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015061"},{"id":"00015059","register_sub_id":"101","register_pk":"529337","name":"千早神社拝殿及び渡廊","kana":"ちはやじんじゃはいでんおよびわたろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41585,"lng":135.65330556,"geo_status":"db","era":"昭和3年／昭和50年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0930","desc":"本殿正面に建つ拝殿及び渡廊。桁行三間梁間二間切妻造銅板葺で上段の本殿に向け渡廊を設ける。側廻りは背面中央に御扉を建てる他は全て吹放ちとし、流麗な意匠の錺金具を付した御扉のみが背景の森から浮かび上がる。大江新太郎の設計による斬新な形式の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015059"},{"id":"00015058","register_sub_id":"101","register_pk":null,"name":"千早神社本殿","kana":"ちはやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.4158,"lng":135.65339722,"geo_status":"db","era":"昭和3年／昭和50年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0929","desc":"史跡千早城跡二の丸に位置する神社本殿。設計は大江新太郎。境内南東端に西面して建つ桁行三間梁間二間切妻造妻入銅板葺で棟に千木と堅魚木を置く。内部は内・外陣とし外陣前面に縁を付し、扉などに流麗な意匠の錺金具を飾る。全体に木柄細く端正な姿の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015058"},{"id":"00015060","register_sub_id":"101","register_pk":"529338","name":"千早神社末社","kana":"ちはやじんじゃまっしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府南河内郡千早赤阪村大字千早1228","lat":34.41596111,"lng":135.65329167,"geo_status":"db","era":"昭和７年／昭和50年改修","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.5㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"27 - 0931","desc":"本殿の北西に位置し、基壇上に南面して建つ桁行三間梁間一間切妻造平入銅板葺。螻羽を深くつくり、大棟に長い樋棟を載せる。柱は円柱で腰長押、内法長押で固め、南面各間には錺金具を付した扉戸を開ける。妻に飾る縦長の懸魚や桁隠など本殿意匠に通じる末社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015060"},{"id":"00007245","register_sub_id":"101","register_pk":"108227","name":"超心寺山門","kana":"ちょうしんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-15-1","lat":34.66088193,"lng":135.510986,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0474","desc":"松屋町筋に西面する一間薬医門で、切妻造本瓦葺とする。間口３．１ｍで、袖塀を両脇に付ける。女梁を挿し肘木状に作り、男梁上、大斗肘木を介して、虹梁と軒桁を支持。妻や中備は流水や雲紋風に彫られた蟇股とする。軒は一軒繁垂木。たちの高い薬医門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007245"},{"id":"00014271","register_sub_id":"101","register_pk":"509661","name":"伴林氏神社手水舎","kana":"ともばやしのうじのじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57528056,"lng":135.61114722,"geo_status":"db","era":"昭和16年／同58年・平成8年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0862","desc":"境内南の大鳥居外側西に位置する手水舎で、靖国神社手水舎を移築したもの。入母屋造銅板葺、二軒吹寄垂木、四隅に三本一組で円柱を立て、内法長押上に連子の欄間を嵌める。近代らしい洗練された意匠の大規模な手水舎で、靖国神社の遺構としても貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014271"},{"id":"00014269","register_sub_id":"101","register_pk":"509659","name":"伴林氏神社拝殿及び幣殿","kana":"ともばやしのうじのじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57566667,"lng":135.61122778,"geo_status":"db","era":"昭和16年／同58年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積219㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0860","desc":"式内社の本殿南に南面して建つ近代の大型拝殿。入母屋造平入銅板葺、三間の向拝に千鳥破風を載せる。正面五間、側面四間、奥に幣殿が突出し、翼廊を介し東に祭器所、西に神饌所を配す。台湾檜素木造、格天井御影石敷の広い土間で、近代らしい堂々とした造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014269"},{"id":"00014268","register_sub_id":"101","register_pk":"509658","name":"伴林氏神社本殿","kana":"ともばやしのうじのじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57578889,"lng":135.61123889,"geo_status":"db","era":"昭和15年／同36年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0859","desc":"市野山古墳の西にある式内社本殿で大伴氏の祖神を祀る。正面三間春日造で向拝に切妻破風を載せる。二軒繁垂木、大棟に堅魚木、千木が鬼板外側に付く。木階廻りを幣殿に繋ぎ屋内とする。西の靖国神社として整備された台湾檜素木造の格式ある近代大型本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014268"},{"id":"00014270","register_sub_id":"101","register_pk":"509660","name":"伴林氏神社棟門及び透塀","kana":"ともばやしのうじのじんじゃむねもんおよびすかしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.57585833,"lng":135.61123333,"geo_status":"db","era":"昭和15年／同58年改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"棟門 木造、銅板葺、間口2.1m 透塀 木造、銅板葺、総延長55m","structure_material":"棟門 木造","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0861","desc":"本殿の北、東、西方を囲む透塀と棟門。基壇の葛石上に建ち本殿を囲む神域を形成する。透塀は銅板葺で、地覆と内法貫間に大和打の板を嵌める。北面中央を切り上げて開く棟門は、切妻造平入銅板葺で、中備に蟇股を掲げる。境内社殿群を構成して景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014270"},{"id":"00014272","register_sub_id":"101","register_pk":"509662","name":"伴林氏神社若宮八幡宮社殿(旧澤田尋常小学校奉安殿)","kana":"ともばやしのうじのじんじゃわかみやはちまんぐうしゃでん（きゅうさわだじんじょうしょうがっこうほうあんでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府藤井寺市林三丁目400","lat":34.575875,"lng":135.61099722,"geo_status":"db","era":"昭和15年／同48年・平成15年移築","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.7㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"27 - 0863","desc":"伴林氏神社本殿の西に建つ社殿で元は奉安殿。木造で一間社神明造、銅板葺で千木、堅魚木、鞭掛を備える。素木造で木柄太く、棟持柱は転びなく直立する。高欄付き榑縁を廻し、木階を設け擬宝珠付親柱を構える。木造奉安殿の希少な遺構で神明造による好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014272"},{"id":"00000065","register_sub_id":"101","register_pk":"101055","name":"日本基督教団大阪教会","kana":"にほんきりすときょうだんおおさかきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市西区江戸堀1-23-17","lat":34.68944487,"lng":135.49346393,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"鉄骨造・煉瓦造・コンクリート造3階建塔屋付、銅板葺、建築面積674㎡","structure_material":"鉄骨造・煉瓦造・コンクリート造3階建塔屋付","registered":"1996.12.20(平成8.12.20)","register_no":"27 － 0005","desc":"ヴォーリズ設計の鉄骨・煉瓦・コンクリート混合造の教会堂で，背後に塔屋が建つ。ロマネスク様式を基調とする意匠で構成され，数少ない大正期の赤煉瓦建物として親しまれている。正面妻壁のバラ窓や，玄関上部の半円形の飾り窓で構成される外観に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000065"},{"id":"00004997","register_sub_id":"101","register_pk":"105987","name":"日本基督教団大阪住吉教会","kana":"にほんきりすときょうだんおおさかすみよしきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市住吉区東粉浜2-21-3","lat":34.61896342,"lng":135.49250079,"geo_status":"db","era":"大正8／昭和6増改造","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、スレート葺、建築面積180㎡、塔付","structure_material":"木造2階建","registered":"2005.11.10(平成17.11.10)","register_no":"27 － 0329","desc":"南海本線と阪堺線に挟まれた一画に所在。大正８年建設の切妻造，下見板張，上げ下げ窓の礼拝堂及び牧師館の前面に寄棟造，モルタル塗の木造２階建を増築し，正面右寄りに塔を上げる。改造はあるが，玄関脇の丸窓や礼拝堂祭壇などが昭和初期意匠の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004997"},{"id":"00007890","register_sub_id":"101","register_pk":"108870","name":"日本基督教団島之内教会","kana":"にほんきりすときょうだんしまのうちきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市中央区東心斎橋1-38","lat":34.67215586,"lng":135.50499712,"geo_status":"db","era":"昭和3／昭和中期改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリートブロック造3階建、建築面積384㎡","structure_material":"鉄筋コンクリートブロック造3階建","registered":"2009.11.02(平成21.11.02)","register_no":"27-0535","desc":"大阪市内の繁華街に建つ。３階建、陸屋根。正面に大階段を構え、６本の角柱を並べる玄関を造り、化粧ブロックを使用し、正面性を打ち出す。設計者が開発した「中村式鉄筋コンクリートブロック構造」による建築で、近代における建築構造の発展過程を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007890"},{"id":"00010663","register_sub_id":"101","register_pk":"201237","name":"日本基督教団天満教会","kana":"にほんきりすときょうだんてんまきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市北区天神西町20-1","lat":34.694683,"lng":135.510832,"geo_status":"db","era":"昭和4年／昭和34年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造4階建、建築面積362㎡","structure_material":"鉄筋コンクリート造4階建","registered":"2015.08.04(平成27.08.04)","register_no":"27－0618","desc":"天満宮近傍に位置する中村式鉄筋コンクリート造四階建。正面は略対称形で、階段室前面を矩形意匠で構成する。内部一階を集会室とし、二・三階分の礼拝堂に架ける楕円アーチの梁に連続アーチを刳抜く。構造及び意匠に昭和初期の建築思潮の一端を示す教会堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010663"},{"id":"00015490","register_sub_id":"101","register_pk":"533505","name":"日本基督教団南大阪教会塔","kana":"にほんきりすときょうだんみなみおおさかきょうかい とう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市阿倍野区阪南町一丁目30-2","lat":34.63559722,"lng":135.51580556,"geo_status":"db","era":"昭和3年／昭和56年改修","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積11㎡、塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2025.08.06(令和7.08.06)","register_no":"27 - 0948","desc":"阿倍野に位置する教会の塔。設計は村野藤吾。鉄筋コンクリート造３階建で外壁モルタル塗仕上。方形平面で南面中央部の迫出に円と十字を組合わせた帯状透彫を付し、頂部に十字架を立てる。村野の処女作の一部で、鉄筋コンクリート造形への志向を示す貴重な塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015490"},{"id":"00001629","register_sub_id":"101","register_pk":"102619","name":"日本フリーメソジスト教団大阪日本橋キリスト教会","kana":"にほんふりーめそじすときょうだんおおさかにっぽんばしきりすときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府大阪市中央区日本橋1-20-4","lat":34.66582493,"lng":135.50581234,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積342㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0090","desc":"堺筋の南の起点，日本橋一丁目の南西角近くに東面して建つ。玄関部の尖頭アーチの入口，３階の５連の尖頭アーチ窓などゴシックスタイルを基調とするが，堺筋沿いの街路景観に溶け込むように正面ファサードを概ね平板につくっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001629"},{"id":"00000545","register_sub_id":"101","register_pk":"101535","name":"念仏寺本堂","kana":"ねんぶつじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区上本町4-2-41","lat":34.67074114,"lng":135.52046351,"geo_status":"db","era":"天保13","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建，瓦葺，152㎡","structure_material":"木造平屋建","registered":"1998.04.21(平成10.04.21)","register_no":"27 － 0034","desc":"大阪の繁華街に立地する中規模の浄土宗本堂。平面は，内外陣・余間等規格に則って配置する標準的な作品である。細部彫刻等は時代相応の構成になる。旧城下の寺町の北限を示す遺構であり，入母屋造の大屋根を見せる外観は，整った境内とも広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000545"},{"id":"00014636","register_sub_id":"101","register_pk":"515178","name":"法明寺庫裏","kana":"ほうみょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66985833,"lng":135.56052778,"geo_status":"db","era":"寛政9年（1797）／昭和中期・同61年改修","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造2階建、瓦葺、建築面積258㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0880","desc":"旧深江村の集落西寄りに所在する浄土宗寺院の庫裏。入母屋造平入桟瓦葺のつし二階建、正背面に下屋を設け、入母屋造式台玄関を構える。内部は九間取座敷に広い土間と板間を並べ、竹の節欄間を備えるなど古風な面を持つ。本堂と並んで歴史的な境内景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014636"},{"id":"00014637","register_sub_id":"101","register_pk":"515179","name":"法明寺鐘楼","kana":"ほうみょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66965556,"lng":135.56013611,"geo_status":"db","era":"正徳3年（1713）／大正元年・平成26年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0881","desc":"旧深江村の西寄りにある浄土宗寺院の鐘楼。境内南西に位置する。切妻造本瓦葺、一軒半繁垂木、虹梁蟇股と絵様肘木を備え、角柱几帳面取下端粽付。基壇は切込み矧ぎ石積で、北面に切込み階段を備える。軸組太く絵様繰形整う建築年代明らかな鐘楼として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014637"},{"id":"00014635","register_sub_id":"101","register_pk":"515177","name":"法明寺本堂","kana":"ほうみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66987222,"lng":135.56030278,"geo_status":"db","era":"元禄7年（1694）／大正元年・昭和38年改修","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0879","desc":"旧深江村の集落西寄りに所在する浄土宗寺院の本堂。元は錣屋根、火災後に寄棟造とした平入本瓦葺。一軒半繁垂木で反りは伸びやか。中央間を広くとった正面五間向拝付。内陣柱は太い円柱で、脇仏壇含む内陣は平面凸型で一段高く近世浄土宗本堂の特徴を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014635"},{"id":"00014638","register_sub_id":"101","register_pk":"515180","name":"法明寺薬医門","kana":"ほうみょうじやくいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府大阪市東成区深江南三丁目20他","lat":34.66957778,"lng":135.56024444,"geo_status":"db","era":"寛政7年（1795）／大正元年・平成14年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2023.08.07(令和5.08.07)","register_no":"27 - 0882","desc":"旧深江村の浄土宗寺院の表門。奈良街道から参道を引き込んで境内南面に開く、入母屋造平入本瓦葺の薬医門。格天井で、梁は三通り架け、控柱に水引虹梁を架ける。小規模ながら絵様繰形整う建築年代明らかな門で、集落及び街道沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014638"},{"id":"00007240","register_sub_id":"101","register_pk":"108222","name":"萬福寺山門","kana":"まんぷくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府大阪市天王寺区下寺町1-9","lat":34.662891,"lng":135.51118804,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.9m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0469","desc":"松屋町筋に西面する一間薬医門。間口２．９ｍ幅に本柱を建て、男梁と女梁間に大斗肘木を入れ、妻には蟇股を置く。二軒半繁垂木で、切妻造本瓦葺。地垂木や男梁、女梁の鼻先に絵様を施し、華やかな印象を与える。蟇股には植物紋様を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007240"},{"id":"00011158","register_sub_id":"101","register_pk":"205265","name":"水無瀬神宮神庫","kana":"みなせじんぐうしんこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.884849,"lng":135.672689,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積24㎡","structure_material":"土蔵造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0644","desc":"境内南西隅に北面して建つ。桁行二間半梁間二間、土蔵造二階建、寄棟造桟瓦葺で、正面中央の戸口に下屋を設け、漆喰塗の扉を開く。切石積基礎上に建ち、正面に石階四級を設け、外壁漆喰塗として水切一段を廻らせる。近代に再編された境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011158"},{"id":"00011160","register_sub_id":"101","register_pk":"205267","name":"水無瀬神宮神門及び築地塀","kana":"みなせじんぐうしんもんおよびついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.885065,"lng":135.672618,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"神門 木造、瓦葺、間口2.8m 築地塀 瓦葺、総延長5.0m、北方潜戸付","structure_material":"神門 木造","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0646","desc":"参道の突当りに構える門と築地塀。神門は一間薬医門、切妻造本瓦葺で、女梁に斗を置いて男梁を支持し、男梁上に長い撥束を立て、斗と実肘木で棟木を受ける。築地塀も本瓦葺で土壁に定規線五筋を引き、北塀に潜りを開く。離宮跡地の由緒に相応しい格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011160"},{"id":"00011159","register_sub_id":"101","register_pk":"205266","name":"水無瀬神宮手水舎","kana":"みなせじんぐうちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.885127,"lng":135.672706,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、面積5.5㎡、手水鉢付","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0645","desc":"境内正面の神門北東に南北棟で建ち、桁行長を三・〇メートルとのばした方一間平面で、入母屋造桟瓦葺とし、石製の手水鉢と井戸枠を置く。角柱に内法長押を廻らして舟肘木を置き、格天井を組み、妻飾は木蓮格子に梅鉢懸魚を吊る。本格的な形式をもつ手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011159"},{"id":"00011157","register_sub_id":"101","register_pk":"205264","name":"水無瀬神宮拝殿及び幣殿","kana":"みなせじんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.88487,"lng":135.673076,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0643","desc":"拝殿は桁行四間の入母屋造の正面に三間向拝を付け、北側に庇状の張出しと神饌所、背面に桁行二間の幣殿を設ける。土間式で基壇周囲に高欄を廻らせる。小屋を虹梁豕扠首、組物舟肘木として古風とし、伸びやかな曲線の蟇股を飾るなど設計者角南隆の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011157"},{"id":"00011156","register_sub_id":"101","register_pk":"205263","name":"水無瀬神宮本殿","kana":"みなせじんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府三島郡島本町広瀬三丁目10-24","lat":34.88485,"lng":135.673278,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"27 - 0642","desc":"境内南東奥に西面して建つ。桁行三間梁間二間で、四方に縁を廻らして脇障子をたて、前面に浜床を設ける。柱上に舟肘木を置き、二軒繁垂木とする。内部は内外陣に二分し、外陣は折上小組格天井を張り、正側面に板唐戸を開く。簡素な意匠に格調を備えた社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011156"},{"id":"00001724","register_sub_id":"101","register_pk":"102714","name":"御幸森天神宮透塀","kana":"みゆきもりてんじんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66043439,"lng":135.53456943,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造、銅板葺、延長32m","structure_material":"木造","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0096","desc":"拝殿背後から延びて幣殿及び本殿を巡る塀。高さ約１ｍの切石積に建ち、折れ曲がり延長１７間で、挿肘木を用い銅板葺の屋根を架ける。各間に連子窓を設け腰板壁とする。柱・垂木などは本殿、拝殿などと同様な大面取りとして意匠を統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001724"},{"id":"00001723","register_sub_id":"101","register_pk":"102713","name":"御幸森天神宮拝殿","kana":"みゆきもりてんじんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66030735,"lng":135.53456172,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0095","desc":"亀腹基壇上に建つ入母屋造平入り拝殿で、正面に緩やかな曲線からなる唐破風造の向拝を備える。内部は１室で背面左右の庇を「のりと座」及び「祭器庫」とする。本殿、幣殿と一連の建築であり、昭和初期における鎌倉復古様式神社建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001723"},{"id":"00001722","register_sub_id":"101","register_pk":"102712","name":"御幸森天神宮幣殿","kana":"みゆきもりてんじんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66035252,"lng":135.53456814,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0094","desc":"本殿・拝殿間を繋ぐ桁行２間、両流造の幣殿。側面に菱格子窓を構え腰板壁とする。内部は木舞下地の化粧屋根裏とし、上下２段の虹梁を渡した架構に特色がある。本殿・拝殿同様な良質の檜を用い、素木の端正な美しさをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001722"},{"id":"00001721","register_sub_id":"101","register_pk":"102711","name":"御幸森天神宮本殿","kana":"みゆきもりてんじんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"大阪府","address":"大阪府大阪市生野区桃谷3-10-5","lat":34.66038576,"lng":135.53456814,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2000.04.28(平成12.04.28)","register_no":"27 － 0093","desc":"三間社流造で屋根正面に千鳥破風と軒唐破風を付ける組物は身舎を軒支輪付の出組、庇を三斗組とする。身舎庇ともに実肘木に大仏様の繰形を施し、蟇股や木鼻の形態も古式である。透塀越しに望めるように床を高めている。設計は奈良の吉田種次郎と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001721"},{"id":"00013609","register_sub_id":"101","register_pk":"504963","name":"薬樹山延命寺宝物館","kana":"やくじゅさんえんめいじほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"大阪府","address":"大阪府河内長野市神ガ丘492","lat":34.42606389,"lng":135.59399167,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積85㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"27 － 0813","desc":"市街南東にある真言宗寺院の宝物館で境内南の高台に建つ。木造二階建寄棟造桟瓦葺で、四周に下屋を廻し正面に切妻玄関を付す。外壁は漆喰塗で軒は扇垂木。内部は中央を区画して像を安置し四周の回廊壁際に陳列棚を設ける。城郭の櫓を思わせる重厚なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013609"},{"id":"00004272","register_sub_id":"101","register_pk":"105262","name":"吉野薬師堂","kana":"よしのやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府豊能郡能勢町吉野110","lat":34.98641427,"lng":135.47596879,"geo_status":"db","era":"天文24","year":1555,"year_source":"db","year_min":1555,"year_max":1555,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積73㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"27 － 0299","desc":"集落ほぼ中央に南面して建つ。方３間，寄棟造，茅葺（鉄板仮葺）で，側柱は大面取り角柱，仏壇前面両脇は太い円柱とし，内部は前方梁間２間を広間，奥は中央を仏壇，両脇を小間に仕切る。中世の部材を残すとともに，集落の歴史景観上欠くことのできない建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004272"},{"id":"00001834","register_sub_id":"101","register_pk":"102824","name":"瀧安寺鳳凰閣","kana":"りゅうあんじほうおうかく","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"大正","pref":"大阪府","address":"大阪府箕面市箕面公園内","lat":34.84269624,"lng":135.47198017,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦一部銅板葺、建築面積130㎡、塔屋付","structure_material":"木造平屋建","registered":"2000.09.26(平成12.09.26)","register_no":"27 － 0099","desc":"切妻造・桟瓦葺，平屋建で，その北端に宝形造の楼閣をあげた形態で，平等院鳳凰堂翼廊の気分が表現されている。設計は武田五一，施工は高橋組。箕面山の中腹に位置し，石垣を高く築いた敷地に建ち，箕面川の渓流とともに優れた景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001834"},{"id":"00012222","register_sub_id":"101","register_pk":"353022","name":"若山神社本殿","kana":"わかやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府三島郡島本町大字広瀬1497","lat":34.891384,"lng":135.654335,"geo_status":"db","era":"文化4年(1807)／大正11年改修","year":1807,"year_source":"db","year_min":1807,"year_max":1807,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"27-717","desc":"平野部を見下ろす景勝地に東面して建つ。三間社流造で、中央柱間を広くとる。身舎は円柱で、軒は二軒繁垂木、屋根はかつては檜皮葺だったと伝える。向唐破風造の向拝には、近代らしい装飾意匠の彫刻を施しており、特徴的な形式の神社本殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012222"},{"id":"00007274","register_sub_id":"101","register_pk":"108256","name":"上善寺経蔵","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41341065,"lng":135.31650863,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、面積28㎡","structure_material":"土蔵造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0503","desc":"本堂の西方に東面して建つ。宝形造本瓦葺、正面４．９ｍ奥行５．０ｍ規模で、正面に一間向拝を付ける。土蔵造で白漆喰仕上げとし、正面中央の出入口に両開格子戸と、漆喰仕上げの引分戸をたてる。内部は低い板床を張り、天井は棹縁天井、漆喰壁で柱や貫を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007274"},{"id":"00007272","register_sub_id":"101","register_pk":"108254","name":"上善寺本堂","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41353884,"lng":135.31697886,"geo_status":"db","era":"天和3／宝暦5改修","year":1683,"year_source":"db","year_min":1683,"year_max":1683,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積380㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0501","desc":"境内のほぼ中央に西面して建つ。入母屋造本瓦葺の七間堂で、正面に一間向拝を付ける。内・外陣からなる典型的な浄土宗平面に、正面に広縁、両側面入側一間半に各３室を設ける特徴的な平面になる。正面各間には両開双折桟唐戸をたてる。大規模な浄土宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007272"},{"id":"00007273","register_sub_id":"101","register_pk":"108255","name":"上善寺庫裏","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41358338,"lng":135.31664475,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0502","desc":"本堂の西北に南面して建つ。南北棟の切妻造妻入本瓦葺で、正面１４ｍ奥行１６ｍと規模の大きな庫裏である。東側面には桁行５．６ｍ梁間９．０ｍの切妻屋根を張り出し、その南面に式台を付ける。棟に煙出を載せ、妻正面には虹梁や束、貫からなる架構を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007273"},{"id":"00007275","register_sub_id":"101","register_pk":"108257","name":"上善寺鐘楼","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.413242,"lng":135.31694,"geo_status":"db","era":"寛政9","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造、瓦葺、面積16㎡","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0504","desc":"本堂の南方に位置する南北棟の吹放ち鐘楼で、屋根は切妻造本瓦葺。桁行３．９ｍ梁間３．６ｍ、切石積基壇上に四方転びに円柱を建て、貫や台輪で固める。三斗組で、妻は虹梁大瓶束、軒は二軒繁垂木。笈形や木鼻、中備などに貘や獅子ほかの良質な彫物が配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007275"},{"id":"00007276","register_sub_id":"101","register_pk":"108258","name":"上善寺表門","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.413349,"lng":135.316544,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0505","desc":"本堂の正面、通りに西面して建つ。切妻造本瓦葺の四脚門で、間口３．５ｍに及ぶ。本柱は円柱で、その前後に方柱を建てる。組物は三斗組で、妻は虹梁大瓶束。軒は二軒繁垂木。中央に両開桟唐戸をたてる。組物間や扉上部等が植物紋様や動物の彫刻で充たされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007276"},{"id":"00007277","register_sub_id":"101","register_pk":"108259","name":"上善寺裏門","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大阪府","address":"大阪府泉佐野市栄町4695-1","lat":34.41359473,"lng":135.316483,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.5m、両脇袖塀付","structure_material":"木造","registered":"2008.07.08(平成20.07.08)","register_no":"27 － 0506","desc":"庫裏の西、孝子越街道に北面する。切妻造本瓦葺の一間薬医門。間口２．５ｍで、両脇に袖塀を設け、東袖塀に潜りを開ける。本柱は五平柱で、控柱は面取方柱。一軒半繁垂木。妻と冠木中備に板蟇股を置く。旧佐野町場の町並みに建つ、重厚な門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007277"},{"id":"00006242","register_sub_id":"101","register_pk":"107226","name":"斑鳩寺聖徳殿後殿","kana":"いかるがでらしょうとくでんこうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県揖保郡太子町鵤709","lat":34.8369963,"lng":134.5751897,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積212㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0282","desc":"３層の屋根を重ねた八角円堂の外観で，中殿取合い部の南北に入母屋造翼部を突出。上層は三手先に扇垂木，中間の庇は平三斗に疎垂木，下層は出組に繁垂木と変化を付ける。内部は中殿に面して唐破風を飾り，中央に厨子を納める。伊藤平左衛門設計の近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006242"},{"id":"00006241","register_sub_id":"101","register_pk":"107225","name":"斑鳩寺聖徳殿中殿","kana":"いかるがでらしょうとくでんなかでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県揖保郡太子町鵤709","lat":34.83700696,"lng":134.57532689,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0281","desc":"聖徳殿は境内南寄りに東面して建つ。中殿は前殿と後殿を繋ぐ両下造の本瓦葺。梁間４間の身舎が二重折上格天井の内陣で，両側面の裳階は廊下とする。両妻の柱は前殿と後殿の柱を兼用し，内部空間は実質桁行５間規模となる。伊藤平左衛門設計の近代仏堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006241"},{"id":"00015207","register_sub_id":"101","register_pk":"530631","name":"雲松寺玄関及び庫裏","kana":"うんしょうじげんかんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市河間町19","lat":34.84463611,"lng":134.69969167,"geo_status":"db","era":"昭和5年頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積285㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0822","desc":"本堂の東に南面して建つ玄関及び庫裏。入母屋造の東西棟の玄関棟に南北棟の庫裏が接続し全体にＬ字の平面。玄関は正面に唐破風屋根の式台を付し、庫裏は南西を土間、北に２列６室を配す。北・西庭を望む座敷は室境に雁・松・竹・梅の襖絵を建てる瀟洒な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015207"},{"id":"00015208","register_sub_id":"101","register_pk":"530632","name":"雲松寺山王堂","kana":"うんしょうじさんのうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県姫路市河間町19他","lat":34.84441944,"lng":134.69973889,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0823","desc":"本堂南東に位置し山王権現を祀る小堂。南面して建つ桁行三間、梁間三間半、入母屋造本瓦葺で一間向拝を付す。組物は舟肘木、軒は一軒疎垂木、妻飾は虹梁大瓶束。内部は内・外陣とし内陣背面中央の仏壇上に宮殿を配す。正面にガラス戸を建てた近代らしい仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015208"},{"id":"00015209","register_sub_id":"101","register_pk":"530633","name":"雲松寺山門及び袖塀","kana":"うんしょうじさんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市河間町17","lat":34.84431111,"lng":134.69975833,"geo_status":"db","era":"江戸中期／大正4年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"山門 木造2階建、瓦葺、建築面積12㎡ 袖塀 土塀、総延長21m","structure_material":"山門 木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0824","desc":"境内入口に東面して建つ一間一戸入母屋造本瓦葺の鐘楼門と南北に続く土塀。山門下層は四隅に角柱と円柱を一対で立てる特異な形式。上層は円柱を立て組物は尾垂木付二手先、軒は二軒繫垂木、腰組付縁に高欄を付す。凝ったつくりの山門で境内の表構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015209"},{"id":"00015206","register_sub_id":"101","register_pk":"530630","name":"雲松寺本堂","kana":"うんしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市河間町19","lat":34.84458611,"lng":134.69943889,"geo_status":"db","era":"宝暦元年(1751)／江戸後期・大正14年改修","year":1751,"year_source":"db","year_min":1751,"year_max":1751,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積242㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"28 - 0821","desc":"姫路城北方にある黄檗宗寺院の本堂。基壇上に建つ入母屋造本瓦葺の四周に裳階を付し、大棟に宝珠を飾る。身舎組物は平三斗で一軒扇垂木、妻飾は二重虹梁蟇股。六間取後列中央の内陣は格天井で須弥壇を配す。播磨地方の黄檗宗寺院の代表的な建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015206"},{"id":"00010327","register_sub_id":"101","register_pk":"199100","name":"慧日寺裏門","kana":"えにちじうらもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077584,"lng":135.069003,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、銅板葺、間口2.3m、左右袖塀及び潜戸付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"28-0606","desc":"庫裏の東正面に建つ、間口二・三メートルの一間薬医門。軒は一軒疎垂木の木舞打ち、切妻造銅板葺である。五平の本柱上に冠木、控柱間に絵様木鼻付頭貫を渡し、前後に三筋の梁をかける。全体に簡素なつくりであるが、江戸中期復興の境内北側の構えを伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010327"},{"id":"00010325","register_sub_id":"101","register_pk":"199098","name":"慧日寺経蔵","kana":"えにちじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077693,"lng":135.069541,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積39㎡、経庫付","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0604","desc":"方丈の東正面に、西面して建つ。置き屋根式の切妻造桟瓦葺、平入の土蔵造で、正面入口には持送りで入母屋造の庇を設ける。内部は南北に二分して南側四・九メートル四方を吹抜けとし、奥に須弥壇を構え、扇垂木の軒をもつ宮殿風経庫を置く、類例の少ない経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010325"},{"id":"00010324","register_sub_id":"101","register_pk":"199097","name":"慧日寺庫裏","kana":"えにちじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077916,"lng":135.069148,"geo_status":"db","era":"江戸後期／大正13年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積373㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0603","desc":"桁行二三メートル梁間一五メートル、東西棟の入母屋造茅葺、妻入りで、方丈の北に建つ。正面となる東側を土間とし、居室部は棟通りを境に南北二列に分け、背面側は八畳三室を配し、南西隅の書院には座敷飾を設ける。方丈とともに境内空間の核を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010324"},{"id":"00010326","register_sub_id":"101","register_pk":"199099","name":"慧日寺鐘楼","kana":"えにちじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077785,"lng":135.069383,"geo_status":"db","era":"慶応3年（1867）","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造2階建、檜皮葺、建築面積5.9㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0605","desc":"方丈の南、低い乱石積基壇に東西棟で建つ袴腰付の方一間形式で、入母屋造檜皮葺である。梁を現しとして銅鐘を吊り、その上で化粧隅木尻を組み、化粧屋根裏とする。軒は二軒繁垂木である。二手先詰組とした縁腰組も充実し、たちが高く存在感のある鐘楼である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010326"},{"id":"00010323","register_sub_id":"101","register_pk":"199096","name":"慧日寺方丈","kana":"えにちじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県丹波市山南町太田127-1","lat":35.077654,"lng":135.069077,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積349㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"28-0602","desc":"丘陵を背にして東に開く境内奥中央に東面して建つ。入母屋造茅葺で、六間取の正側面に広縁を廻らした平面とし、軸部は角柱で直接桁を受ける。南東の仏殿とは橋状の矩折れ渡廊下で繋ぎ、北の庫裏とは式台玄関付廊下で連絡する。地域景観の核となる茅葺の方丈。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010323"},{"id":"00011165","register_sub_id":"101","register_pk":"205272","name":"大土神社蔵","kana":"おおつちじんじゃくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.73514,"lng":135.231277,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積11㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0648","desc":"幣殿及び拝殿の西側に建つ、神事道具等を収めるための蔵。土蔵造平屋建で、拝殿側妻面に扉口を開き、背面上部に換気のための丸穴を設ける以外は全面壁とする。内壁は真壁漆喰塗、外壁はモルタル塗。境内景観を構成する小規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011165"},{"id":"00011166","register_sub_id":"101","register_pk":"205273","name":"大土神社鳥居","kana":"おおつちじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.734477,"lng":135.231439,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、高さ5.2m、間口4.1m","structure_material":"石造","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0649","desc":"南北に細長い敷地の南端にあって境内を画する。間口四・一メートル、高さ五・二メートルの石造明神鳥居で、六甲花崗岩を用いた粗面仕上げとする。比較的大規模な鳥居である。水車利用を意図して開発され菜種や綿実の絞油生産で栄えた地域の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011166"},{"id":"00011162","register_sub_id":"101","register_pk":"205269","name":"大土神社拝殿及び幣殿","kana":"おおつちじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.735135,"lng":135.231364,"geo_status":"db","era":"昭和4頃／昭和60頃改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0645","desc":"正面三間奥行二間の拝殿と奥行四間の幣殿からなる。拝殿は桟瓦葺、幣殿は向唐破風の鉄板葺とする。拝殿は舟肘木に疎垂木で簡明な意匠とする。内部はいずれも一室で、床は板張り。天井は幅の広い格天井を張るなど、簡素な中にも質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011162"},{"id":"00011161","register_sub_id":"101","register_pk":"205268","name":"大土神社本殿","kana":"おおつちじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市灘区鶴甲三丁目159他","lat":34.735215,"lng":135.231359,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"28 - 0644","desc":"六甲川に沿った細長い南北敷地の北寄りに建つ。一間社流造で、内陣は三室に区画し、正側面に縁を廻し高欄を付け、正面には浜床・浜縁を設ける。正面は格子戸四枚引違で、軸部組物は檜材を用いる。江戸末期の新田開発の歴史を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011161"},{"id":"00006168","register_sub_id":"101","register_pk":"107152","name":"尾上神社随身門","kana":"おのえじんじゃずいしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.74353042,"lng":134.82443495,"geo_status":"db","era":"江戸後期／大正期・平成7改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0269","desc":"木造，三間一戸八脚門，入母屋造，銅板葺。角柱を長押で固め，虹梁形の飛貫上に蟇股を載せる。軒は一軒半繁垂木。正面中央間に両開戸を吊り，両脇間は板壁で囲い，両脇間後室に随身像を向き合わせに安置する。境内入口に建ち，神社正面の重厚な構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006168"},{"id":"00006167","register_sub_id":"101","register_pk":"107151","name":"尾上神社拝殿","kana":"おのえじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.743721,"lng":134.824097,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積64㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0268","desc":"社殿の最前に建つ。木造，桁行５間，梁間４間で，背面に太鼓橋及び神饌所が附属し，入母屋造，正面千鳥破風及び軒唐破風付，本瓦葺とする。破風妻飾は木連格子。屋根には鯱や鬼瓦等の役物瓦を多用し，社殿正面を飾るなど，重厚かつ華やかな外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006167"},{"id":"00006166","register_sub_id":"101","register_pk":"107150","name":"尾上神社幣殿","kana":"おのえじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.743748,"lng":134.82402,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0267","desc":"本殿前面に付設して建つ。木造平屋建，桁行３間，梁間３間，入母屋造，本瓦葺とし，正面に千鳥破風を付け，背面に入母屋屋根を付ける。妻飾は正面以外を木連格子として拝殿と意匠を合わせる。本殿側に祝詞座を設け，規模が大きく，屋根のつくりも特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006166"},{"id":"00006165","register_sub_id":"101","register_pk":"107149","name":"尾上神社本殿","kana":"おのえじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市尾上町長田518","lat":34.743813,"lng":134.823929,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2007.05.15(平成19.05.15)","register_no":"28 － 0266","desc":"加古川河口近くに所在する神社。境内入口正面に社殿が建ち，本殿はその最奥に位置する。木造，三間社流造，銅板葺。庇側面を板壁とし，前面を幣殿の祝詞座に接続する。妻は二手先の組物で，妻飾を二重虹梁大瓶束の形式とし，本格的な神社本殿のつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006165"},{"id":"00010855","register_sub_id":"101","register_pk":"201690","name":"温泉寺薬師堂","kana":"おんせんじやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字薬師畷985-2","lat":35.62563767,"lng":134.80299803,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0625","desc":"温泉街奥寄りに位置する下段境内の中心仏堂。正面三間側面四間、一間向拝付。内部を前後に二分して内陣奥に須弥壇を置き、近世密教系仏堂の一類型を示す。内外の要所を彫刻で飾り、特に向拝は、虹梁上の龍、柱上に並置した籠彫の手挟など、いずれも秀逸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010855"},{"id":"00010865","register_sub_id":"101","register_pk":"201700","name":"春日神社本殿","kana":"かすがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県篠山市本郷字口ノ坪141-1","lat":35.158842,"lng":135.264396,"geo_status":"db","era":"弘化3","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"木造平屋建、こけら葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0635","desc":"山間の境内上段に西面する覆屋内に建つ。三間社流造、軒唐破風付で、庇は中柱を省き一間とする。三方に縁を廻らし、妻は出組で二重虹梁の妻飾を受ける。彫刻は中井清次郎正用の作になり、向拝廻りの龍や鳳凰の濃密かつ躍動的な彫刻に彫物師中井家の作風を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010865"},{"id":"00001137","register_sub_id":"101","register_pk":"102127","name":"光明寺本堂","kana":"こうみょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加東市光明寺433","lat":34.94854619,"lng":134.94726723,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積331㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0053","desc":"安政６年焼失した本堂を武田五一の設計により大正１４年に再興したもの。銅板葺入母屋造の五間堂で、四周に縁を回し、正面に３間の向拝をのばす。内部は１間幅の外陣、２間幅の内陣、２間幅の宮殿とで構成される。鎌倉時代の建築様式に倣ったとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001137"},{"id":"00009522","register_sub_id":"101","register_pk":"194315","name":"極樂寺仁王門","kana":"ごくらくじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町八千代区中野間字門上213-3","lat":35.00732252,"lng":134.9006885,"geo_status":"db","era":"享保13年","year":1728,"year_source":"db","year_min":1728,"year_max":1728,"year_label":null,"structure":"木造二階建、瓦葺、建築面積21㎡","structure_material":"木造二階建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0561","desc":"山裾の境内東端に建ち、三間一戸楼門、入母屋造本瓦葺である。下層柱筋の組物は三斗上に舟肘木をおいて天井桁を受け、また皿斗付大斗や肘木鼻の繰形などに大仏様の細部を取入れる。さらに棟通りの虹梁上に瓶を模した大瓶束をおくなど、独特な形態をもつ楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009522"},{"id":"00010856","register_sub_id":"101","register_pk":"201691","name":"極楽寺本堂","kana":"ごくらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字寺ノ谷800-3","lat":35.623908,"lng":134.805226,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2015.11.17(平成27.11.17)","register_no":"28 ‐ 0626","desc":"城崎温泉奥寄りの境内に南面する方丈型本堂。六間取の三方に広縁と落縁を廻らし、正面にガラス戸を建て、両端間に火灯窓を開ける。仏間と室中を折上格天井とし、室中両側に竹の節欄間を設け、上間下間とも奥室に床を備える。伝統的平面に近代的要素を備える本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010856"},{"id":"00014882","register_sub_id":"101","register_pk":"519142","name":"西正寺本堂","kana":"さいしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県尼崎市上坂部三丁目85","lat":34.74803611,"lng":135.42933611,"geo_status":"db","era":"享保7年(1722)／江戸後期増築","year":1722,"year_source":"db","year_min":1722,"year_max":1722,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"28 - 0796","desc":"ＪＲ塚口駅南東にある浄土真宗本願寺派の寺院本堂。桁行７間梁間７間入母屋造本瓦葺で正面に１間向拝を付す。外陣正側面に縁を廻し、奥に内陣と両脇に余間をとる中規模真宗本堂の典型。角柱を１間毎に配するなど古式。集落の中心寺院として歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014882"},{"id":"00002966","register_sub_id":"101","register_pk":"103956","name":"志方八幡神社社務所蔵","kana":"しかたはちまんじんじゃしゃむしょくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市志方町志方町301-2","lat":34.823872,"lng":134.829025,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積18㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0104","desc":"社務所主屋北西部の北方に建つ。桁行２間半，梁間２間規模の２階建土蔵で，屋根は南北棟，切妻造，桟瓦葺，置屋根形式とし，東面の南寄りに庇を付けた出入口を設ける。土壁をあらわした簡素な外観は社務所主屋背後の裏庭空間の点景をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002966"},{"id":"00002965","register_sub_id":"101","register_pk":"103955","name":"志方八幡神社社務所主屋","kana":"しかたはちまんじんじゃしゃむしょしゅおく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市志方町志方町301-2","lat":34.823776,"lng":134.829178,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺一部瓦葺、建築面積337㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0103","desc":"志方町中心部の宮山頂部近くに南面して建つ。桁行８間，梁間４間の入母屋造，茅葺身舎の南面・西面に本瓦葺の庇を廻した四方蓋風民家の外観と，方丈風の六間取の西方下手に土間及び納屋等を配置し，北東に矩折れに４室を張り出した平面に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002965"},{"id":"00002967","register_sub_id":"101","register_pk":"103957","name":"志方八幡神社社務所門","kana":"しかたはちまんじんじゃしゃむしょもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県加古川市志方町志方町301-2","lat":34.82325,"lng":134.829147,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口1.8m","structure_material":"木造","registered":"2002.08.21(平成14.08.21)","register_no":"28 － 0105","desc":"社務所主屋式台玄関の南方に位置し，社務所敷地の南辺のほぼ中央に建つ。東西棟，切妻造，桟瓦葺，１間１戸の薬医門で，農家風の主屋に対応した簡素なつくりとする。間口１間規模と小規模ではあるが，石段の上に建ち神社景観のアイストップともなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002967"},{"id":"00001136","register_sub_id":"101","register_pk":"102126","name":"慈眼寺持宝院大師堂","kana":"じげんじじほういんたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市社1369","lat":34.91889128,"lng":134.96512145,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積145㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0052","desc":"武田五一設計による木造寺院建築。施工は小西瀧次郎。亀甲積基壇に建つ正面３間、側面５間、正方形平面の堂で、本瓦葺宝形屋根を架ける。異様に長い１間向拝が特徴的で、武田五一の伝統的建築に対する独自な解釈がよく表明されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001136"},{"id":"00006568","register_sub_id":"101","register_pk":"107551","name":"常楽寺山門","kana":"じょうらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.79485151,"lng":134.829376,"geo_status":"db","era":"明和7","year":1770,"year_source":"db","year_min":1770,"year_max":1770,"year_label":null,"structure":"木造、瓦葺、間口3.8m","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0279","desc":"境内の南辺西寄りに建つ間口１２尺の四脚門で，切妻造，本瓦葺とする。妻飾りは虹梁に笈形付大瓶束で，大瓶束に差した桁行の虹梁が特徴。組物は出三斗に実肘木とし，軒は二軒繁垂木である。扉は冠木と唐居敷に軸を納める古式で，八双，四葉の金物もよく遺る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006568"},{"id":"00006569","register_sub_id":"101","register_pk":"107552","name":"常楽寺鐘楼","kana":"じょうらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.79484009,"lng":134.82927317,"geo_status":"db","era":"宝暦4","year":1754,"year_source":"db","year_min":1754,"year_max":1754,"year_label":null,"structure":"木造、瓦葺、面積8.4㎡","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0280","desc":"境内の南方，山門の西に位置する。石積の基壇上に建つ桁行９．５尺，梁間９尺規模の東西棟で，切妻造，本瓦葺とする。柱は四方転びで頭貫を虹梁につくる。組物は出三斗，中備は蟇股，妻飾りは虹梁に蟇股。一軒疎垂木の化粧軒裏とし，棟木下の虹梁に梵鐘を吊る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006569"},{"id":"00006600","register_sub_id":"101","register_pk":"107583","name":"常楽寺本堂","kana":"じょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.795162,"lng":134.829346,"geo_status":"db","era":"元禄5／享保7増築","year":1692,"year_source":"db","year_min":1692,"year_max":1692,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積374㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0277","desc":"本堂は境内西寄りに南面して建つ。桁行１９ｍ，梁間１７ｍ，入母屋造，本瓦葺で向拝が付く。前面を広縁とし，凸形内陣と両脇間，外陣からなる浄土宗本堂である。内陣格天井の花鳥画が鮮やか。増築の本玄関は本堂の東に続く東西棟で，唐破風の式台を南面させる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006600"},{"id":"00006567","register_sub_id":"101","register_pk":"107550","name":"常楽寺薬師堂","kana":"じょうらくじやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市東神吉町神吉1413","lat":34.794941,"lng":134.829178,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"28 － 0278","desc":"本堂南に東面して建つ。方２間規模の宝形造，銅板葺で，向拝が付く。石階４級を設け，東，南，北に縁が付く。組物は出三斗で中備は蟇股，一軒疎垂木とする。正面は中央と北間を嵌殺し格子戸とし，南間を開戸とする。内部は板床で，奥の段に厨子を安置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006567"},{"id":"00012593","register_sub_id":"101","register_pk":"367887","name":"真宗大谷派姫路船場別院本徳寺行在所","kana":"しんしゅうおおたにはひめじせんばべついんほんとくじあんざいしょ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市地内町1-1","lat":34.833889,"lng":134.682938,"geo_status":"geocoded","era":"江戸末期／明治18年・昭和8年改修、平成23年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"28 － 0698","desc":"明治天皇の行在所となった御殿で、境内西辺に南面して建つ。桁行六間梁間五間半、入母屋造桟瓦葺で、四周に銅板葺下屋を廻す。内部の中心をなす玉座の間は付書院に天袋と違棚を配した奇抜な座敷飾をもつ。端正な意匠と造作で整えられた寺院附属の住宅建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012593"},{"id":"00008156","register_sub_id":"101","register_pk":"132597","name":"大信寺本堂","kana":"だいしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加西市北条町北条字江ノ木1256","lat":34.93483435,"lng":134.83083663,"geo_status":"db","era":"弘化2年（1845）／平成4年改修","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積219㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"28 － 0454","desc":"南面して建つ三間堂で、入母屋造銅板葺とし、正面に一間向拝を付ける。側柱が方柱、内部が円柱。組物は出三斗で、中備に成の高い皿斗付出三斗を飾る。外陣及び内陣、脇陣からなる標準的な浄土宗本堂で、室境を簡略化するなど幕末らしい内部構成を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008156"},{"id":"00012773","register_sub_id":"101","register_pk":"367676","name":"多田神社宝物殿","kana":"ただじんじゃほうもつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県川西市多田院多田所町1","lat":34.86099389,"lng":135.40307694,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造一部木造平屋建、銅板葺、建築面積138㎡","structure_material":"鉄筋コンクリート造一部木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"28 － 708","desc":"猪名川中流の北岸にある境内前方の参道東脇に建つ。切妻造銅板葺の平屋建で、主体部は鉄筋コンクリート造、屋根と切妻造妻入の向拝は木造とする。内部は一室で内装を木造とし、格天井を張る。大正以降戦前に建築された不燃構造・和風意匠の神社宝物殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012773"},{"id":"00014655","register_sub_id":"101","register_pk":"515197","name":"徳壽院本堂","kana":"とくじゅいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区宮内字小松原195他","lat":34.79628889,"lng":134.590925,"geo_status":"db","era":"江戸中期／明治33年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"28 - 0792","desc":"魚吹八幡神社の東隣にある真言宗寺院の本堂。境内北辺西寄りに南面し、切石積基壇上に建つ正面一間、側背面二間の宝形造本瓦葺で縁を付す。組物出組に支輪を備え、軒は二軒扇垂木。内部北辺に仏壇を配して格天井を張る。小規模ながら軒廻りなど充実した造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014655"},{"id":"00014656","register_sub_id":"101","register_pk":"515198","name":"徳壽院薬師堂","kana":"とくじゅいんやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県姫路市網干区宮内字小松原195他","lat":34.79628889,"lng":134.59085278,"geo_status":"db","era":"江戸中期／大正4年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2023.08.07(令和5.08.07)","register_no":"28 - 0793","desc":"魚吹八幡神社の東隣にある真言宗寺院の仏堂。境内北西隅に南面し、方三間の入母屋造平入本瓦葺で南に向拝を付す。軒廻りは柱頭から腕木を出した出桁造で、一軒疎垂木とし珍しい。内部は北に仏壇を設け、床は畳敷で竿縁天井を張る。簡素ながらも丁寧な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014656"},{"id":"00007091","register_sub_id":"101","register_pk":"108073","name":"泊神社本殿","kana":"とまりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764275,"lng":134.824326,"geo_status":"db","era":"承応2","year":1653,"year_source":"db","year_min":1653,"year_max":1653,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.0㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0347","desc":"南面する入母屋造妻入銅板葺で、正面に軒唐破風付の向拝を付ける特徴的な外観となる。１間社で、背面は中央に柱を建て２間とし、正・側３方に榑縁をまわす。身舎は円柱で、柱上は出組。向拝は三斗組で、中備に蟇股を置く。時代相応の良質な意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007091"},{"id":"00002663","register_sub_id":"101","register_pk":"103653","name":"長田神社天照社","kana":"ながたじんじゃあまてらすしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67158623,"lng":135.1469122,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0082","desc":"透塀の内，本殿東方に位置し，切石３段積の基壇上に建つ。一間社流造で，桁行２尺７寸，梁間２尺２寸，向拝梁間１尺８寸規模，屋根は銅板葺，軒は一軒繁垂木とする。本殿の意匠に対応して，柱は円柱で四周に縁高欄を廻し，向拝の柱は角柱として浜床を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002663"},{"id":"00002666","register_sub_id":"101","register_pk":"103656","name":"長田神社出雲大社","kana":"ながたじんじゃいずもたいしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67146475,"lng":135.14662289,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0085","desc":"焼失を免れた末社のひとつで，西楽所の西方に東面して建つ。玉垣内の石積基壇上に載った一間社流造で，桁行２尺４寸，梁間３尺３寸規模とし，月読社と同様，軒は二軒繁垂木，三方に高欄付縁を廻し，棟を千木と勝男木で飾る。拝殿等に合わせ木部を丹塗とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002666"},{"id":"00002671","register_sub_id":"101","register_pk":"103661","name":"長田神社廻廊及び脇門","kana":"ながたじんじゃかいろうおよびわきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.6711873,"lng":135.14720031,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積60㎡、脇門付","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0090","desc":"神門の西側４間分，神符授与所の東側，脇門を挟んで左右４間分づつを廻廊とする。梁間８尺，両下造，銅板葺で，北側は吹放ち，南面は腰羽目板嵌，上部連子窓とし，脇門には桟唐戸を建込む。神門などともに石垣上に建ち，内外苑を隔てる一文字状の結界をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002671"},{"id":"00002672","register_sub_id":"101","register_pk":"103662","name":"長田神社神楽殿","kana":"ながたじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67133872,"lng":135.14725708,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0091","desc":"脇門を潜った右手前方，拝殿の東南方に西面して建つ。桁行２１尺梁間１２尺，入母屋造，銅板葺で，前後に桁行９尺，梁間４尺５寸と６尺の突出部を設け十字形平面とする。軒は一軒疎垂木とし，四周に縁高欄を廻す。神社社殿構成に欠くことのできない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002672"},{"id":"00002670","register_sub_id":"101","register_pk":"103660","name":"長田神社神符授与所及び附属屋","kana":"ながたじんじゃしんふじゅよじょおよびふぞくや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67118053,"lng":135.1470848,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0089","desc":"神門東端に桁行６尺，梁間８尺，東西棟，両下造の附属屋が取り付き，その東に南北棟，入母屋造，桁行１８尺，梁間１２尺の神符授与所を内苑側に張り出す。北側は三方にガラス障子を建込み，南面は附属屋とも廻廊と同様の腰羽目板嵌，上部連子窓の意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002670"},{"id":"00002669","register_sub_id":"101","register_pk":"103659","name":"長田神社神門","kana":"ながたじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67116409,"lng":135.14700075,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、間口7.1m","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0088","desc":"拝殿の南方，拝殿の棟とは方向をやや振って建つ。境内再編に伴う新設の施設で，切妻造，銅板葺，３間３戸の八脚門形式を採る。本柱は円柱，控柱は角柱，軒は二軒疎垂木とし，丹塗のうえ要所を錺金具で飾る。昭和初期内務省系神社建築の造形的特色をもつ作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002669"},{"id":"00002662","register_sub_id":"101","register_pk":"103652","name":"長田神社透塀及び門","kana":"ながたじんじゃすきべいおよびもん","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67165612,"lng":135.14680245,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0081","desc":"東西楽所から発して本殿を囲うように建つ。塀は東西面各８間，北面１０間の切妻造，銅板葺，控え柱建で，腰羽目板張り，上部透し連子窓とする。東西楽所寄りの２箇所に潜りを設けるほか，北面中央に切妻造，銅板葺，柱間７尺５寸，棟門形式の裏門を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002662"},{"id":"00002665","register_sub_id":"101","register_pk":"103655","name":"長田神社月読社","kana":"ながたじんじゃつくよみしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.671494,"lng":135.147171,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0084","desc":"焼失を免れた末社のひとつで，拝殿の東方に西面して建つ。一間社流造，銅板葺で，桁行２尺４寸，梁間２尺３寸，向拝梁間１尺９寸規模，軒は二軒繁垂木とし，三方に高欄付縁を廻す。もと素木建であったが，玉垣内の新設石積基壇上に移築され，丹塗を施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002665"},{"id":"00002661","register_sub_id":"101","register_pk":"103651","name":"長田神社西楽所","kana":"ながたじんじゃにしがくじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67146627,"lng":135.14677447,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0080","desc":"拝殿の背面１間通りの西端に位置し，拝殿よりやや低い石積基壇の上に建つ。桁行２間，梁間２間規模の東西棟，銅板葺，入母屋造とし，西・南面に連子窓，東面に入口を開ける。東楽所と同様なつくりになり，社殿構成に拡がりと奥行きをもたせる役割を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002661"},{"id":"00002659","register_sub_id":"101","register_pk":"103649","name":"長田神社拝殿","kana":"ながたじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67139874,"lng":135.14690657,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積143㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0078","desc":"幣殿の前面に建つ。幣殿とは平面的に一体のつくりで，桁行５間，梁間５間，銅板葺の入母屋造とする。正面１間通りは吹放ちの向拝とし縋破風をつけて納めるなど創意が見られるほか，正面中央の軒唐破風，飛貫頭貫間の蟇股など社殿中最も装飾的につくられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002659"},{"id":"00002660","register_sub_id":"101","register_pk":"103650","name":"長田神社東楽所","kana":"ながたじんじゃひがしがくじょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67150982,"lng":135.14697797,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0079","desc":"拝殿の背面１間通りの東端に位置し，拝殿よりやや低い石積基壇の上に建つ。桁行２間，梁間２間規模の東西棟，銅板葺，入母屋造とし，東・南面に連子窓，西面に入口を開ける。組物は舟肘木，軒は一軒疎垂木で簡素であるが本殿幣殿拝殿の社殿構成の一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002660"},{"id":"00002667","register_sub_id":"101","register_pk":"103657","name":"長田神社蛭子社","kana":"ながたじんじゃひるこしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67138985,"lng":135.14664363,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積0.79㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0086","desc":"焼失を免れた末社のひとつで，拝殿の西方に東面して建つ。出雲大社とは並列し，ほぼ同様の仕様であるが，桁行２尺３寸，梁間２尺１寸１分，向拝梁間１尺５寸９分，棟高１０尺９寸４分とやや小ぶり。もと素木建であったが，移築に際し丹塗仕上げとされた。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002667"},{"id":"00002658","register_sub_id":"101","register_pk":"103648","name":"長田神社幣殿","kana":"ながたじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67148973,"lng":135.14688133,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0077","desc":"本殿と拝殿を繋ぐ位置に建つ。東西棟の本殿とは棟を直交させた切妻造で，桁行２間（１３尺５寸）梁間１間（１４尺４寸）の規模とする。柱は角柱，組物は出三斗で中備に蟇股を入れ，軒は二軒疎垂木とするなど本殿とは異なる仕様とし桁行柱間には蔀戸を立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002658"},{"id":"00002657","register_sub_id":"101","register_pk":"103647","name":"長田神社本殿","kana":"ながたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67156657,"lng":135.14685498,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0076","desc":"大正１３年１月焼失の再建社殿。三間社流造で，切石積基壇上の亀腹上に建ち，柱は円柱で四方に跳高欄付切目縁を廻らす。組物は平三斗，軒は二軒繁垂木，妻飾は豕叉首とし，棟を千木と勝男木で飾る。木部は丹塗を施し要所に錺金具を打つ。設計は香川定太郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002657"},{"id":"00002668","register_sub_id":"101","register_pk":"103658","name":"長田神社松尾社","kana":"ながたじんじゃまつおしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.671444,"lng":135.147186,"geo_status":"db","era":"江戸後期／昭和3移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積0.81㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0087","desc":"焼失を免れた末社のひとつで，火災前は覆舎内に在った。拝殿向拝部の東方，月読社の南方に位置し，桁行２尺３寸，梁間２尺１寸と対向する蛭子社と同規模，同仕様であるが，石積基壇上に亀腹を築き，その上に一間社流造を載せている点は透塀内の末社に似る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002668"},{"id":"00009519","register_sub_id":"101","register_pk":"194312","name":"西宮神社嘉永橋","kana":"にしのみやじんじゃかえいばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73525384,"lng":135.33442382,"geo_status":"db","era":"嘉永元年","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"石造桁橋、橋長6.0m、幅員1.8m、袖高欄付","structure_material":"石造桁橋","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0558","desc":"神池の西側中央に架かり、松尾神社の参道上に位置する。石造、橋長六・〇メートル、幅員一・八メートルの通行用の桁橋で、六甲山産の花崗岩（御影石）が用いられる。敷石の上には石製の欄干を備える。境内に残る最も古い橋で、神社の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009519"},{"id":"00009518","register_sub_id":"101","register_pk":"194311","name":"西宮神社瑞寶橋","kana":"にしのみやじんじゃすいほうばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73545371,"lng":135.33460228,"geo_status":"db","era":"明治40年／大正11年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"石造桁橋、橋長5.5m、幅員2.5m、袖高欄付","structure_material":"石造桁橋","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0557","desc":"社殿前につくられた神池に架かり、拝殿正面に位置する。石造、橋長五・五メートル幅員二・五メートルの祭礼用の太鼓橋で、六甲山産の花崗岩（御影石）が用いられる。円弧状の桁石の上を十七等分して敷石を割り付け、青銅製の欄干を備えた丁寧な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009518"},{"id":"00015344","register_sub_id":"101","register_pk":"532468","name":"西宮神社手水舎","kana":"にしのみやじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73535833,"lng":135.33507778,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、面積13㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0836","desc":"境内中央部、参道東脇に設けた手水舎。切妻造銅板葺で、四隅の石製台座上に円柱と八角柱を束ねて立て、頭貫で固め、大斗肘木で桁と虹梁を受ける。中備は中世風の復古的な蟇股。内部に手水鉢を据え四方を吹放つ。真反の軒は優美で意匠に凝った堂々たる手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015344"},{"id":"00015345","register_sub_id":"101","register_pk":"532469","name":"西宮神社銅鐘舎（旧燈籠覆屋）","kana":"にしのみやじんじゃどうしょうしゃ（きゅうとうろうおおいや）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73545833,"lng":135.33483056,"geo_status":"db","era":"明治37年","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、銅板葺、面積3.2㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0837","desc":"境内中央部、参道の西脇に位置する旧燈籠陳列用の覆屋。方一間の起付き切妻造銅板葺。壇上積風石製台座に土台を置き、角柱を立て内法長押を廻し、外側絵様付の舟肘木で梁と桁を受ける。四面に菱格子を建て、上部は筬欄間とする。繊細かつ丁寧なつくりの覆屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015345"},{"id":"00015342","register_sub_id":"101","register_pk":"532466","name":"西宮神社西翼殿","kana":"にしのみやじんじゃにしよくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73586111,"lng":135.33448611,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0834","desc":"本殿の西に位置する祭祀用の社殿。方一間切妻造銅板葺で、亀腹上に角柱を立て長押で固め、組物は舟肘木。内部は一室の板敷で上部は化粧屋根裏とし、南・東面に刎高欄付榑縁を廻す。本殿復興に伴い新たに建立した社殿で東翼殿と一対で左右対称の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015342"},{"id":"00015343","register_sub_id":"101","register_pk":"532467","name":"西宮神社拝殿","kana":"にしのみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73570833,"lng":135.33460556,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積215㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0835","desc":"本殿正面に位置する鉄筋コンクリート造の拝殿。入母屋造平入銅板葺で南面に千鳥破風を据え軒唐破風付向拝を付し、北面も軒唐破風を突出する。両脇から北方に翼廊を延ばして斎庭を囲う回廊を形成し、内外で塗装色を塗り分ける。屋根の構成優美で華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015343"},{"id":"00015341","register_sub_id":"101","register_pk":"532465","name":"西宮神社東翼殿","kana":"にしのみやじんじゃひがしよくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73584722,"lng":135.33474722,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0833","desc":"本殿の東に位置し、斎庭に南面する祭祀用の社殿。亀腹基壇に建つ方一間、切妻造銅板葺。角柱を長押で固め、組物は舟肘木。内部は一室の板敷で上部は化粧屋根裏とし、南・西面に刎高欄付榑縁を廻す。本殿の復興に伴い新たに建立した社殿で、斎庭の一角を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015341"},{"id":"00015340","register_sub_id":"101","register_pk":"532464","name":"西宮神社本殿","kana":"にしのみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"兵庫県","address":"兵庫県西宮市社家町11","lat":34.73590278,"lng":135.33462222,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"28 - 0832","desc":"全国えびす社総本社の本殿。身舎の前に庇を付した春日造を相の間で三棟並列に連結した大規模な社殿。屋根は銅板葺。組物は大斗絵様肘木で、庇を一連で葺き降ろし、庇両端に隅木を入れる。戦災焼失した旧国宝本殿を戦後に復興した我が国唯一の三連春日造社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015340"},{"id":"00001446","register_sub_id":"101","register_pk":"102436","name":"フロインドリーブ本店（旧ユニオン教会）","kana":"ふろいんどりーぶほんてん（きゅうゆにおんきょうかい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市中央区生田町4-6-15","lat":34.70079804,"lng":135.19514413,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"鉄筋コンクリート造3階建、スレート葺、建築面積463㎡、塔屋付き","structure_material":"鉄筋コンクリート造3階建","registered":"1999.11.18(平成11.11.18)","register_no":"28 － 0061","desc":"ヴォーリズ建築事務所の設計になる教会建築。正面中央の玄関上部に鍾塔を建ち上げ，左手にゴシック式の礼拝堂棟，右手にハーフティンバー・スタイルの牧師館棟を配し，礼拝堂棟の妻面，角塔，牧師館棟の屋根面との構成で街路沿いファサードの均衡をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001446"},{"id":"00011992","register_sub_id":"101","register_pk":"211164","name":"本住寺本堂","kana":"ほんじゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字長崎493-3","lat":35.627563,"lng":134.812214,"geo_status":"db","era":"昭和6年／平成11年増築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積159㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"28-674","desc":"城崎温泉街山寄りの境内に南面する本堂。背面中央間に須弥壇、右脇間に開祖の壇、左脇間に位牌堂をそれぞれ張出す。堂内は全て格天井で内陣は折上格天井で荘厳し、来迎柱にも獅子鼻・獏鼻を飾る。向拝の蟇股の龍の彫刻は播州飾磨彫の松本一門の作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011992"},{"id":"00003130","register_sub_id":"101","register_pk":"104120","name":"本徳寺中宗堂","kana":"ほんとくじちゅうそうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"兵庫県","address":"兵庫県姫路市亀山324","lat":34.809879,"lng":134.677216,"geo_status":"db","era":"明治31","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"28 － 0116","desc":"入母屋造平入の前室と，重層宝形造の後室を複合させた堂宇。前室には向拝１間を備え，全体を本瓦葺とする。江戸末期に焼失した前身堂を再建したもの。九世伊藤平左衛門の作。現存例の少ない中宗堂のひとつで，内陣と外陣を備える本格的複合仏堂の好例である。&nbsp;","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003130"},{"id":"00009521","register_sub_id":"101","register_pk":"194314","name":"楊柳寺仁王門","kana":"ようりゅうじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町八千代区大和字前田776-1","lat":35.00179503,"lng":134.87491299,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造二階建、瓦葺、建築面積20㎡","structure_material":"木造二階建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0560","desc":"境内下段の入口に南面して構える、三間一戸楼門、入母屋造本瓦葺。軸部は貫で固め、上層の組物は二手先、軒は二軒繁垂木である。皿斗付大斗や挿肘木の使用、通肘木鼻の繰形などに、大仏様の影響が認められる。古刹の正門に相応しい、均整のとれた楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009521"},{"id":"00009520","register_sub_id":"101","register_pk":"194313","name":"楊柳寺本堂","kana":"ようりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県多可郡多可町八千代区大和字東谷774","lat":35.00350943,"lng":134.87697003,"geo_status":"db","era":"寛延4年／昭和22年改修","year":1751,"year_source":"db","year_min":1751,"year_max":1751,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積190㎡","structure_material":"木造平屋建","registered":"2013.03.29(平成25.03.29)","register_no":"28 － 0559","desc":"境内上段に建つ。桁行五間梁間四間半、向拝一間、入母屋造銅板葺である。梁間二間分の外陣は虹梁四筋を架けて格天井を張り、桁行三間梁間二間の内陣に大型の厨子を安置する。後陣と右脇陣は半間幅の下屋とする。山中に建つ本格的なつくりの天台宗寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009520"},{"id":"00011991","register_sub_id":"101","register_pk":"211163","name":"蓮成寺本堂","kana":"れんじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"兵庫県","address":"兵庫県豊岡市城崎町湯島字御所452","lat":35.625867,"lng":134.807,"geo_status":"db","era":"昭和11年／昭和57年頃改修、平成19年増築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"28-673","desc":"城崎温泉山寄りの境内に南面する真宗寺院本堂。昭和八年建立の大本教但州別院鶴鳴殿を移築し向拝と下屋を付したもので、小屋組はキングポストトラスである。西側に一列室を設けたため、向拝が中心よりずれ、西端に花頭窓を穿ち特徴ある外観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011991"},{"id":"00002664","register_sub_id":"101","register_pk":"103654","name":"長田神社八幡社","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県神戸市長田区長田町3-1-1","lat":34.67155547,"lng":135.14677378,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"28 － 0083","desc":"透塀の内，本殿西方に位置する。天照社と同様，切石３段積の基壇上に建つ一間社流造で，桁行２尺７寸，梁間２尺２寸，向拝梁間１尺８寸規模，屋根は銅板葺，軒は一軒繁垂木，木部を丹塗とする。天照社とともに，透塀内の聖なる空間を構成する主要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002664"},{"id":"00007097","register_sub_id":"101","register_pk":"108079","name":"泊神社能舞台","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.76390437,"lng":134.82407643,"geo_status":"db","era":"江戸後期／平成19改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0353","desc":"神楽殿の南に位置する。北面して建つ切妻造妻入の能舞台で、西側面に脇座、背面に後座を設け、橋掛が続く。桁行４．９ｍ梁間４．９ｍのほぼ方形で、後座は梁間２．１ｍとする。床は拭板敷で、天井は化粧屋根裏天井で、豪快な梁組を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007097"},{"id":"00007098","register_sub_id":"101","register_pk":"108080","name":"泊神社太鼓倉","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.76396127,"lng":134.82390345,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0354","desc":"神楽殿の西南、随身門の西に位置する。桁行６．４ｍ梁間３．８ｍ規模の木造平屋建。屋根は桟瓦葺で、北面を入母屋造、南面を切妻造とする。北妻面に大きく扉口を設け、他３方は土壁とし、内部は漆喰仕上げ、外は焼板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007098"},{"id":"00007096","register_sub_id":"101","register_pk":"108078","name":"泊神社末社種子神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.76415445,"lng":134.82402194,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積0.25㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0352","desc":"住吉神社本殿の南に東面して建つ。正面０．４５ｍ奥行０．５５ｍの１間社流見世棚造で、住吉神社本殿とほぼ同規模、同形式であり、絵様も似ており、一連で建立されたとみられる。本殿の西方から北にかけて、多くの小祠が建ち並び、豊かな境内景観を創り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007096"},{"id":"00007092","register_sub_id":"101","register_pk":"108074","name":"泊神社神楽殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764179,"lng":134.824234,"geo_status":"db","era":"承応2／昭和63改修","year":1653,"year_source":"db","year_min":1653,"year_max":1653,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0348","desc":"本殿の前方に位置する。入母屋造本瓦葺で、桁行３間梁間３間に四周に高欄付切目縁をまわしたが、背面は室内に改造された。面取方柱で、柱上に舟肘木を置き、軒は一軒疎垂木。正面は引違戸、側面は連子窓とする。本殿と一連で建てられた、近世初頭の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007092"},{"id":"00007093","register_sub_id":"101","register_pk":"108075","name":"泊神社幣殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764221,"lng":134.824295,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0349","desc":"本殿の正面、神楽殿後方に繋がる社殿。梁間は神楽殿と同寸で、桁行は３間。屋根は桟瓦葺で、中央２間は北面が切妻造、南面が両下造、両側面半間を下屋とする。正・背面開放で、側面には窓を開ける。内部は畳敷の１室で、天井は化粧屋根裏とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007093"},{"id":"00007095","register_sub_id":"101","register_pk":"108077","name":"泊神社末社住吉神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764275,"lng":134.824112,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積0.24㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0351","desc":"本殿の西南に東面して建つ。正面０．４５ｍ奥行０．５５ｍ規模の１間社流見世棚造。土台上に身舎柱と向拝柱を建て、身舎は正面を両開戸、側・背面を板壁とし、身舎と向拝間を２段の棚状に造る。向拝は三斗組とし、身舎は大斗肘木とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007095"},{"id":"00007094","register_sub_id":"101","register_pk":"108076","name":"泊神社末社熊野神社本殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"兵庫県","address":"兵庫県加古川市加古川町木村658","lat":34.764408,"lng":134.824265,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、鉄板葺、建築面積0.32㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"28 － 0350","desc":"本殿の北に南面して建つ小祠。正面０．４４ｍ規模の１間社。切妻造鉄板葺であるが、流造の前流を切り縮めたとみられる。身舎は正・側面１間とし、身舎背面柱から向拝柱に直接、虹梁を架ける。組物を平三斗、妻を大瓶束とする。丁寧なつくりになる小祠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007094"},{"id":"00001135","register_sub_id":"101","register_pk":"102125","name":"清水寺客殿","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97233186,"lng":135.0814389,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積90㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0051","desc":"本坊と大講堂との間に位置し、本坊大広殿より渡廊下で連絡される東西棟の建物。３室構成で、南東西の３面に縁側、北面に廊下を設け、東端北側に便所・浴室を張りだす。本坊の大屋根と著しい対照をなす低平な入母屋屋根が建物の性格を表している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001135"},{"id":"00001134","register_sub_id":"101","register_pk":"102124","name":"清水寺本坊","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97237522,"lng":135.08110782,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積694㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0050","desc":"大講堂へ向かう参道沿いの北側擁壁上の平地西寄りに建ち、東面に大講堂に向けて唐破風の玄関車寄を構える。主体部は南側に大広殿・客僧室を、北側に執事室・居間・台所などの内向き諸室を配し大きな切妻屋根で覆い、南西端に方丈室を張り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001134"},{"id":"00001132","register_sub_id":"101","register_pk":"102122","name":"清水寺大講堂","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.9724974,"lng":135.08184881,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積424㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0048","desc":"根本中堂の南方、石段下に南面して建つ。本瓦葺宝形屋根の７間堂で、石積基壇に建ち、組物は出組、軒は二軒繁垂木とし、北面を除く３面に高欄付きの縁を回す。「平安時代後期の建築物にあらはれたる意匠を多分に加味」したとされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001132"},{"id":"00001133","register_sub_id":"101","register_pk":"102123","name":"清水寺鐘楼","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97274571,"lng":135.08154138,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積57㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0049","desc":"大講堂から根本中堂へ登る石段中途の踊場西方に東面して建つ。本瓦葺入母屋造、下部を袴腰とする伝統的形式に則った鐘楼で、組物は二手先、軒は二軒半繁垂木とし、武田五一意匠、高岡市老子製作所出吹の梵鐘を吊す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001133"},{"id":"00001131","register_sub_id":"101","register_pk":"102121","name":"清水寺根本中堂","kana":null,"category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"兵庫県","address":"兵庫県加東市平木1194","lat":34.97317533,"lng":135.08190793,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積235㎡","structure_material":"木造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"28 － 0047","desc":"大正２年焼失した堂塔伽藍坊舎を武田五一の全山再建計画に基づき伊藤平左衛門の施工により復興したもの。根本中堂は、焼失前の中堂に倣ったと思われる本瓦葺入母屋屋根の五間堂で、四面に縁を回し、正面に軒唐破風付きの３間向拝を設ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001131"},{"id":"00015067","register_sub_id":"101","register_pk":"529345","name":"育成幼稚園園舎兼日本聖公会櫻井聖保羅教会礼拝堂","kana":"いくせいようちえんえんしゃけんにっぽんせいこうかいさくらいせいぱうろきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県桜井市大字桜井70","lat":34.51305833,"lng":135.85022222,"geo_status":"db","era":"昭和5年／昭和55年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積157㎡","structure_material":"木造2階建","registered":"2024.08.15(令和6.08.15)","register_no":"29 - 0362","desc":"ＪＲ桜井駅南東にある園舎兼礼拝堂。木造二階建切妻造桟瓦葺で外壁は下見板張、腰は一部モルタル洗出仕上で、上部に矩形と尖塔アーチ窓を開く。一階は園舎、二階は東西に長い単廊の礼拝堂とし、小屋組はシザートラス。地域が親しむ切妻屋根の園舎兼礼拝堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015067"},{"id":"00002074","register_sub_id":"101","register_pk":"103064","name":"菊水楼表門","kana":"きくすいろうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.682003,"lng":135.834152,"geo_status":"db","era":"江戸期／明治期移築","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造薬医門、瓦葺、間口2.4m","structure_material":"木造薬医門","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0032","desc":"春日大社一の鳥居に突き当たる三条通に面した南側に建つ。圓成寺塔頭の門を明治時代に現在地に移築したと伝える。本瓦葺の薬医門は伝承が首肯されるような風格をもつ建築で，歴史ある料理旅館の表構えに格式を添えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002074"},{"id":"00002075","register_sub_id":"101","register_pk":"103065","name":"菊水楼庭門","kana":"きくすいろうにわもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県奈良市高畑町1130","lat":34.68188966,"lng":135.83429635,"geo_status":"db","era":"江戸期／明治期移築","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"木造薬医門、瓦葺、間口1.9m","structure_material":"木造薬医門","registered":"2000.12.04(平成12.12.04)","register_no":"29 － 0033","desc":"本館玄関廻りから旧本館北側の庭を画する塀に設けた門で，本館の玄関脇に建つ。表門同様，圓成寺塔頭の門を明治時代現在地に移築したと伝え，同じ薬医門形式ながらこちらはやや規模が小さく，桟瓦葺とされている。歴史ある料理旅館の構成要素として相応しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002075"},{"id":"00013311","register_sub_id":"101","register_pk":"366300","name":"旧慈門院表門（陶原家住宅表門）","kana":"きゅうじもんいんおもてもん（すはらけじゅうたくおもてもん）","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46527778,"lng":135.86288611,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0293","desc":"敷地南辺の石垣上に建つ長屋門。入母屋造桟瓦葺で、中央西寄りに扉を開き、門扉前まで石階段を設ける。門の西を作業場、東を物置とし、東から北へ濡縁を廻らす。扉回りはケヤキの良材を用い、内法に虹梁を架け中備を蟇股とするなど敷地正面を印象付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013311"},{"id":"00013308","register_sub_id":"101","register_pk":"366297","name":"旧慈門院客殿及び庫裏（陶原家住宅主屋）","kana":"きゅうじもんいんきゃくでんおよびくり（すはらけじゅうたくおもや）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46538056,"lng":135.86291111,"geo_status":"db","era":"江戸中期／江戸末期改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0290","desc":"旧妙楽寺子院の客殿及び庫裏。切妻造桟瓦葺の東西棟で、西の庫裏を落棟とし四周に下屋を廻す。客殿は東に畳廊下及び３列６室を配し、上手に床付の座敷を置く。庫裏は玄関北の茶の間と西の台所からなる。襖絵も良く残り、近世の妙楽寺子院の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013308"},{"id":"00013310","register_sub_id":"101","register_pk":"366299","name":"旧慈門院小座敷及び土蔵（陶原家住宅小座敷及び土蔵）","kana":"きゅうじもんいんこざしきおよびどぞう（すはらけじゅうたくこざしきおよびどぞう）","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46549167,"lng":135.86283333,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造２階建、瓦葺、建築面積44㎡","structure_material":"木造２階建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0292","desc":"客殿及び庫裏の北西に建つ。東を入母屋造の小座敷、西を切妻造置屋根の土蔵とする。小座敷は６畳で北に床、棚、押入を備え、南から東へ濡縁を廻し、土蔵側は半間幅の蔵前廊下である。土蔵は二階建で外壁は腰を焼板の竪羽目板張とするほかは漆喰塗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013310"},{"id":"00013309","register_sub_id":"101","register_pk":"366298","name":"旧慈門院持仏堂（陶原家住宅持仏堂）","kana":"きゅうじもんいんじぶつどう（すはらけじゅうたくじぶつどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46549167,"lng":135.86300278,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0291","desc":"客殿の北方に建つ持仏堂。梁間二間、桁行三間の規模で東を正面とし、北面を除く三方に濡縁を廻らす。屋根は入母屋造桟瓦葺妻入。内部は畳敷の一室で、中央北寄りに厨子、西、北面に仏壇を据える。天井中央を折上げ護摩用の煙抜きを設ける。丁寧な造作の小堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013309"},{"id":"00013312","register_sub_id":"101","register_pk":"366301","name":"旧慈門院塀重門（陶原家住宅塀重門）","kana":"きゅうじもんいんへいじゅうもん（すはらけじゅうたくへいじゅうもん）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰316","lat":34.46531667,"lng":135.86292222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、檜皮葺、間口1.7m、左右袖塀付","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0294","desc":"表門北面と客殿の間に建つ腕木門で、前庭と東の主庭を画す。屋根は勾配が緩やかな切妻造檜皮葺である。礎盤に円柱を立て、腕木は西正面を拳鼻とし、東は控柱で受ける。扉は花格子入の桟唐戸で、蟇股は麒麟の彫刻で飾るなど、主庭からの景色を華やかに整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013312"},{"id":"00013306","register_sub_id":"101","register_pk":"366295","name":"旧真法院表門（西宮家住宅表門）","kana":"きゅうしんぽういんおもてもん（にしみやけじゅうたくおもてもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰336","lat":34.46486111,"lng":135.85923333,"geo_status":"db","era":"嘉永2年(1849)／昭和60年頃改修","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造、瓦葺、間口2.4m、左右袖塀付","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0288","desc":"敷地南面に開く棟門。礎盤上円柱の上に冠木を載せ、女梁、男梁を組み、男梁上の舟肘木で軒桁を受ける。冠木上には板蟇股を載せ棟木を受け、妻飾は大瓶束笈形付とする。背面は舟肘木下に控柱を立てる。木柄が太く、一軒疎垂木の深い軒は力感ある外観を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013306"},{"id":"00013305","register_sub_id":"101","register_pk":"366294","name":"旧真法院客殿及び庫裏（西宮家住宅主屋）","kana":"きゅうしんぽういんきゃくでんおよびくり（にしみやけじゅうたくおもや）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰336","lat":34.46495,"lng":135.85936667,"geo_status":"db","era":"嘉永3年(1850)","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積311㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0287","desc":"旧妙楽寺子院が神仏分離後、社家住宅となったもの。客殿は三列九室を配し、周囲に鞘の間や縁を廻らし大規模で、南西に唐破風玄関、南東に庫裏を付す。北に床付の座敷を据え、その南は内拝所だが旧仏間で、本尊厨子は小屋裏に据えている。子院建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013305"},{"id":"00013307","register_sub_id":"101","register_pk":"366296","name":"旧真法院塀重門（西宮家住宅塀重門）","kana":"きゅうしんぽういんへいじゅうもん（にしみやけじゅうたくへいじゅうもん）","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県桜井市大字多武峰336","lat":34.46486111,"lng":135.85923333,"geo_status":"db","era":"嘉永3年(1850)／昭和60年頃改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造、檜皮葺（銅板仮葺）、間口2.0m","structure_material":"木造","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0289","desc":"客殿南妻の玄関から西に延びる土塀に開く腕木門で、前庭と北の主庭を画す。柱は角柱で、北背面に支柱を添え、柱間中央に蟇股を据え棟木を受ける。桟唐戸を木製藁座で釣込む。銅板葺だが檜皮葺の軒付を残し、一軒疎垂木とともに軽快な印象で前庭の景観を成す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013307"},{"id":"00005023","register_sub_id":"101","register_pk":"106013","name":"浄教寺掲示板舎","kana":"じょうきょうじけいじばんしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市上三条町","lat":34.68204176,"lng":135.82517849,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、銅板葺、間口1.1m","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0090","desc":"山門前方西側に三条通りに面して建つ。柱間１間，切妻造，銅板葺で，切石基壇の上に建つ。柱背面に鉄棒の控えが付き，柱正面で木鼻状の受木が掲示板額縁を受ける。基壇葛石上に木柵を巡らせる。細部も丁寧なつくりで，三条通りの歴史的景観の構成要素になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005023"},{"id":"00005022","register_sub_id":"101","register_pk":"106012","name":"浄教寺山門","kana":"じょうきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市上三条町","lat":34.68209107,"lng":135.82522831,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2005.11.10(平成17.11.10)","register_no":"29 － 0089","desc":"三条通りに南面して建つ。１間１戸の薬医門で，屋根は切妻造，本瓦葺，軒は二軒繁垂木とし，主柱は唐居敷に円柱を建てる。蟇股・木鼻・桟唐戸綿板等の各所に動植物・渦・雲等の彫刻を施す。均整のとれたつくりで，三条通りの歴史的景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005022"},{"id":"00014507","register_sub_id":"101","register_pk":"513921","name":"浄楽寺本堂","kana":"じょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市中町279","lat":34.52668056,"lng":135.81088056,"geo_status":"db","era":"明治20年","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0338","desc":"耳成山北方の農村集落中央に所在する浄土真宗寺院の本堂。入母屋造平入本瓦葺、向拝を付し、正面側三方に縁を巡らす外陣、左右余間を配す内陣からなる後門形式平面。多武峰妙楽寺輪蔵の部材を購入して建て、礎盤等は転用が明らか。神仏分離の時代を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014507"},{"id":"00014508","register_sub_id":"101","register_pk":"513922","name":"浄楽寺門","kana":"じょうらくじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"奈良県","address":"奈良県橿原市中町279","lat":34.52666111,"lng":135.81106944,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"29 - 0339","desc":"境内東辺の通りに開く浄土真宗寺院の薬医門で、位置を本堂軸線から少し南にずらす。本瓦葺、一軒疎垂木、五平の本柱間に冠木を架け女梁で支持する男梁で控え柱と繋ぐ。木鼻や蟇股の絵様は伝統的で質実な造形。集落中央に位置し本堂と共に歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014508"},{"id":"00016583","register_sub_id":"101","register_pk":"574945","name":"善行寺客殿","kana":"ぜんぎょうじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"明治中期／平成11年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺一部銅板葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0377","desc":"本堂の東に南面して建つ貴賓用の客殿。入母屋造妻入本瓦葺で銅板葺の軒唐破風を付し、式台を構える。内部は南北３室からなり、北端室は上段に構えて格天井を張り、床・違棚・付書院を備える。式台や上段など寺格を示し、本堂と並び建ち境内景観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016583"},{"id":"00016589","register_sub_id":"101","register_pk":"574951","name":"善行寺山門","kana":"ぜんぎょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"寛政10年（1798）","year":1798,"year_source":"db","year_min":1798,"year_max":1798,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0383","desc":"境内南辺西寄りに位置し、通りより引き込み建つ一間一戸薬医門。東脇に潜戸を設け、東・西正面に袖塀を付す。屋根本瓦葺で軒は二軒繁垂木、妻飾は虹梁大瓶束笈形付。ケヤキの良材を用い、腕木や梁先端に流麗な絵様を付し、蟇股や笈形を彫刻で飾る華やかな門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016589"},{"id":"00016586","register_sub_id":"101","register_pk":"574948","name":"善行寺集会場","kana":"ぜんぎょうじしゅうかいじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0380","desc":"境内南辺の中央に建つ集会場。北面して建つ入母屋造妻入桟瓦葺で、外壁は漆喰塗で腰はモルタル塗とする。正面にガラス戸を建て、内部は板敷の１室で棹縁天井を張り、集会室とする。簡素なつくりながら太鼓楼に並び建ち、境内の歴史的景観を形成する集会場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016586"},{"id":"00016590","register_sub_id":"101","register_pk":"574952","name":"善行寺小門","kana":"ぜんぎょうじしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和4年／平成10年改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、瓦葺、間口2.1m、袖塀付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0384","desc":"境内南面の東寄りに建つ一間一戸の薬医門。切妻造本瓦葺で、西側と東側前方に桟瓦葺袖塀を付す。主柱と控柱を貫で固め、軒は一軒疎垂木とし、板張天井で、門口に両開の板扉を吊る。小規模ながら本瓦葺屋根の重厚な外観で、通りの歴史的な景観に寄与する小門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016590"},{"id":"00016585","register_sub_id":"101","register_pk":"574947","name":"善行寺鐘楼","kana":"ぜんぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"天保10年（1839）／昭和13年改修","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造、瓦葺、面積7.7㎡","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0379","desc":"境内南西隅に位置する鐘楼。切石積基壇に建つ入母屋造本瓦葺、円柱を四方転びに立て、腰貫、内法貫、虹梁形頭貫で固めて台輪を廻らし、組物は出組、軒は二軒繁垂木とする。内部は石敷の土間で小組格天井を張り、梵鐘を吊る。蟇股や獅子鼻など彫刻優秀な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016585"},{"id":"00016587","register_sub_id":"101","register_pk":"574949","name":"善行寺太鼓楼","kana":"ぜんぎょうじたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和30年","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造2階建、瓦葺、建築面積34㎡","structure_material":"木造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0381","desc":"集会所の西に位置する太鼓楼。入母屋造の棟中央に方一間入母屋造の二階を載せ、全体本瓦葺。二階外壁は漆喰塗で軒まで塗込め、四面に火灯窓を開ける。二階内部は一室の畳敷で、棹縁天井を張り、上部中央に太鼓を吊る。城郭風の外観が真宗寺院の象徴的な存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016587"},{"id":"00016588","register_sub_id":"101","register_pk":"574950","name":"善行寺手水舎","kana":"ぜんぎょうじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、面積3.8㎡、井戸及び手水鉢付","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0382","desc":"本堂の南に位置する手水舎。切妻造桟瓦葺の南北棟で、成の高い礎石上に角柱を四方転びに立て、梁と桁を架け、各間に内法貫を入れて固める。軒は一軒疎垂木で化粧屋根裏とする。内部は南に井戸、北に手水鉢を配す。簡素ながらも境内景観に欠かせない手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016588"},{"id":"00016593","register_sub_id":"101","register_pk":"574955","name":"善行寺西面北塀","kana":"ぜんぎょうじにしめんきたべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、瓦葺、延長14m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0387","desc":"本堂と宝蔵の間に建ち、境内西面の北側部分を画す塀。木造、延長１４メートル。自然石積基礎で土台上に半間毎に柱を立て内側に控柱を付す。腕木で軒を支え、屋根桟瓦葺。外壁は漆喰塗で腰はモルタル塗とする。簡素ながらも寺院境内の歴史的景観をつくる塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016593"},{"id":"00016592","register_sub_id":"101","register_pk":"574954","name":"善行寺西面南塀","kana":"ぜんぎょうじにしめんみなみべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"コンクリートブロック造、瓦葺、延長12m","structure_material":"コンクリートブロック造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0386","desc":"敷地南面西塀から宝蔵の間に建ち、境内西面南半を画す塀。延長12メートル、自然石基礎としたコンクリートブロック造の塀で屋根桟瓦葺。外壁は外を黄土色モルタル塗で５筋の定規筋を付し、内を漆喰塗仕上とする。重厚な外観で寺院境内の表構えをつくる塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016592"},{"id":"00016584","register_sub_id":"101","register_pk":"574946","name":"善行寺宝蔵","kana":"ぜんぎょうじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"明治9年","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積17㎡","structure_material":"土蔵造2階建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0378","desc":"境内西辺の南寄りに位置する宝蔵。東面して石積基礎に建つ、土蔵造２階建宝形造桟瓦葺で頂部に露盤宝珠を飾り、正面銅板葺庇に軒唐破風を付す。外壁は漆喰塗で、腰は海鼠壁とする。内部は各階板敷とし、二階は棹縁天井を張る。重厚な外観で寺観を整える宝蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016584"},{"id":"00016582","register_sub_id":"101","register_pk":"574944","name":"善行寺本堂","kana":"ぜんぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"安政7年（1860）／昭和12年改修","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積432㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0376","desc":"藤原宮跡の南西に位置する浄土真宗寺院の本堂。境内北西に南面して建つ、入母屋造本瓦葺で正面に一間向拝を付す。典型的な真宗寺院本堂の平面形式で、外陣は円柱を立て、差物を縦横に架けて固め、内陣廻りは彫刻や彩色で荘厳を極めた江戸末期の大規模な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016582"},{"id":"00016591","register_sub_id":"101","register_pk":"574953","name":"善行寺南面西塀","kana":"ぜんぎょうじみなみめんにしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"奈良県","address":"奈良県橿原市飛騨町59","lat":34.49575583,"lng":135.80298694,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造、瓦葺、延長5.6m","structure_material":"木造","registered":"2026.02.10(令和8.02.10)","register_no":"29 - 0385","desc":"山門袖塀の西側に続き、境内南辺の西端部を画す塀。延長５・６メートル、切石積基礎に半間毎に柱を立て、腕木で軒を支える。外は本瓦葺、壁は漆喰塗で腰は竪板張、内は桟瓦葺、壁はモルタル塗仕上とする。通りに面して真宗寺院の歴史的景観を形成する塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016591"},{"id":"00008159","register_sub_id":"101","register_pk":"132600","name":"當麻寺松室院客殿","kana":"たいまでらまつむろいんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1263-11","lat":34.51551375,"lng":135.69612641,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積208㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"29 － 0188","desc":"中之坊の東に建ち、桁行１８ｍ梁間１２ｍ、木造平屋建、入母屋造桟瓦葺で、玄関の屋根を切り上げる。内部は仏間や客間の周囲に縁をめぐらす。数寄屋建築に造詣のあった川上邦基と古代建築に精通した大岡實の設計になり、軽快さと雄大さを併せもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008159"},{"id":"00006042","register_sub_id":"101","register_pk":"107027","name":"中宮寺表御殿","kana":"ちゅうぐうじおもてごもん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県生駒郡斑鳩町法隆寺北1-1-2","lat":34.61483097,"lng":135.73945756,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"29 － 0114","desc":"敷地の中央に位置し，本堂の北側に西面して建つ。桁行６間，梁間４間半，木造平屋建，入母屋造，本瓦葺。南東隅に御上段の間を設け格天井とし，北東隅に御座の間等計６室を配する。貼付壁や襖絵等上質で，細部意匠等，書院建築の遺構として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006042"},{"id":"00013304","register_sub_id":"101","register_pk":"366293","name":"登彌神社社務所","kana":"とみじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66097222,"lng":135.76597778,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積138㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0286","desc":"境内南東に西面して建つ。南北棟の入母屋造桟瓦葺で、正面中央に向唐破風屋根の式台玄関を付し、背面南側に切妻造の角屋を突出する。内部は諸室を続間に配し、北室を床を構えた供進使室とする。装飾を抑えた端正なつくりで、境内景観を格式高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013304"},{"id":"00013302","register_sub_id":"101","register_pk":"366291","name":"登彌神社神饌所","kana":"とみじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66116667,"lng":135.76563611,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0284","desc":"本殿南西の中段に東面して建つ。桁行三間、梁間二間、切妻造桟瓦葺で、南面東間の戸口に檜皮葺の庇を付す。外壁は漆喰塗で、側背面の腰を竪板張とする。内部北側の板間西面に神饌棚を設ける。全体的に均整の取れたつくりで、本殿廻りの境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013302"},{"id":"00013303","register_sub_id":"101","register_pk":"366292","name":"登彌神社手水舎","kana":"とみじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66096944,"lng":135.76566111,"geo_status":"db","era":"昭和14年","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.6㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0285","desc":"境内南西に南北棟で建つ。切妻造本瓦葺、吹放し形式の長方形平面で、中ほどに手水鉢を据える。角柱を内転びに立て、正面を内法貫、側背面を内法貫と腰貫で固める。簡素ながら堅実なつくりで、境内景観の一画を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013303"},{"id":"00013301","register_sub_id":"101","register_pk":"366290","name":"登彌神社拝殿","kana":"とみじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66106389,"lng":135.76578056,"geo_status":"db","era":"寛政11年（1799）頃／昭和14年改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0283","desc":"本殿正面の石段下に建ち、旧神楽殿を改修したとされる拝殿。桁行三間、梁間二間、入母屋造桟瓦葺で、柱間装置を設けず開放的につくる。内部は板敷で化粧屋根裏とし、四周の切目縁に高欄を設ける。簡素ながらも堅実なつくりで、本殿前の礼拝空間を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013301"},{"id":"00013300","register_sub_id":"101","register_pk":"366289","name":"登彌神社本殿","kana":"とみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県奈良市石木町648-1","lat":34.66123889,"lng":135.76582778,"geo_status":"db","era":"文政7年（1824）","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"29 － 0282","desc":"市西部の丘上にある神社。本殿は境内最奥上段に南面して建つ。一間社春日造檜皮葺の二棟を、背面通りの壁面と板床で連結した特異な形式。それぞれ正側面に縁を廻して浜縁を設け、軸部は弁柄塗を基調に柱金襴巻や組物などを極彩色で彩る華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013300"},{"id":"00014195","register_sub_id":"101","register_pk":"508825","name":"中之坊稲荷社","kana":"なかのぼういなりしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県葛城市當麻元當麻方1263-11","lat":34.51569722,"lng":135.69525,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"29-0331","desc":"當麻寺中之坊の境内北西隅に建つ鎮守社。一間社入母屋造平入檜皮葺、二軒繁垂木で、正面に千鳥破風を付け向拝を唐破風とする。組物は二手先で、肘木に笹繰を取り隅尾垂木を入れ向拝虹梁木鼻を波形に造り、軸部全体に彩色を施すなど、小品ながら装飾性に富む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014195"},{"id":"00008023","register_sub_id":"101","register_pk":"128854","name":"本善寺御成御殿","kana":"ほんぜんじおなりごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39271656,"lng":135.85901738,"geo_status":"db","era":"明和9","year":1772,"year_source":"db","year_min":1772,"year_max":1772,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0157","desc":"客殿の南に接続し、桁行９．０ｍ梁間８．０ｍ、北切妻造及び南入母屋造、桟瓦葺である。トコと違棚、付書院を備えた八畳の主室と四畳の前室からなり、西・南に広縁、周囲に落縁を巡らす。良材を用い、丁寧に造られる。客殿と一体で上質な接客空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008023"},{"id":"00008022","register_sub_id":"101","register_pk":"128853","name":"本善寺客殿","kana":"ほんぜんじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39282003,"lng":135.85895403,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積227㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0156","desc":"本堂西にあって、玄関と御成御殿の間に建つ。桁行１６ｍ梁間１３ｍ、北入母屋造及び南切妻造、桟瓦葺。東西二列になり、東側は南端を上段の間とする対面所で広縁を付設する。西側は三室を並べ南室にトコ飾りを備える。対面等に用いられた大型の客殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008022"},{"id":"00008018","register_sub_id":"101","register_pk":"128849","name":"本善寺経蔵","kana":"ほんぜんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.3934556,"lng":135.85950092,"geo_status":"db","era":"寛政4","year":1792,"year_source":"db","year_min":1792,"year_max":1792,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡、輪蔵付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0152","desc":"境内東北角の野面石積基壇に建つ。桁行三間梁間三間、宝形造、西面軒唐破風付、本瓦葺である。西面中央に桟唐戸をたて、両脇間及び側面中央間に花頭窓を付ける。内部は一室で、棹縁天井を張り、八角輪蔵を納める。落ち着いた外観になる経蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008018"},{"id":"00008024","register_sub_id":"101","register_pk":"128855","name":"本善寺庫裏","kana":"ほんぜんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39287915,"lng":135.85871754,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積249㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0158","desc":"客殿の北西隅に接続して建つ。桁行１８ｍ梁間１３ｍ、入母屋造本瓦葺で、棟上に入母屋屋根の煙出を上げ、北面の東寄りに式台玄関を構える。西半部を広い土間、東を床上とし、畳敷の居室や板間を配する。地方における中核寺院の伽藍を構成する重要な要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008024"},{"id":"00008021","register_sub_id":"101","register_pk":"128852","name":"本善寺玄関","kana":"ほんぜんじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39294672,"lng":135.8589477,"geo_status":"db","era":"安政7","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積86㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0155","desc":"客殿の北正面に構える玄関で、桁行６．６ｍ梁間４．５ｍ、切妻造、正面唐破風造、檜皮葺とし、東側に下屋を張り出す。特異な屋根形状とともに、内法には波に麒麟や飛龍の透彫欄間を入れ、虹梁上に力士像を置くなど、間口が広く華やかな正面構えをもつ式台玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008021"},{"id":"00008025","register_sub_id":"101","register_pk":"128856","name":"本善寺山門","kana":"ほんぜんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39327612,"lng":135.85923909,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.5m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"29-0159","desc":"境内北面東寄りの石段上に建ち、左右に築地塀を矩折れに延ばす。一間薬医門、切妻造本瓦葺。女梁両端に大振りの絵様繰形を造り出して男梁を支持し、両妻と冠木中央に板蟇股を置いて棟木を受ける。古刹の境内入口に相応しい、木太く重厚な構えの山門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008025"},{"id":"00008019","register_sub_id":"101","register_pk":"128850","name":"本善寺鐘楼","kana":"ほんぜんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39336692,"lng":135.85928977,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、面積9.2㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0153","desc":"境内東寄り、山門東側の切石積基壇上に建つ、桁行一間梁間一間の吹放ち鐘楼。石製礎盤上に四本柱を内転びに建て、虹梁や貫で固め、柱間中央に大瓶束を入れ、組物は出組、中備を簑束、二軒半繁垂木とする。重厚な入母屋造本瓦葺とし、境内入口の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008019"},{"id":"00008020","register_sub_id":"101","register_pk":"128851","name":"本善寺茶所","kana":"ほんぜんじちゃじょ","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39322333,"lng":135.85911029,"geo_status":"db","era":"寛政10","year":1798,"year_source":"db","year_min":1798,"year_max":1798,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積55㎡、太鼓楼付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0154","desc":"本堂の北東、山門の西側に建つ。桁行７．９ｍ梁間７．０ｍ、入母屋造本瓦葺で、棟上に入母屋屋根の太鼓楼を載せる。内部は前半部を吹放ちの土間と広縁とし、竈を築く。門徒接遇のための茶所で、屋根に太鼓楼を置き、浄土真宗特有の伽藍景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008020"},{"id":"00008015","register_sub_id":"101","register_pk":"128846","name":"本善寺本堂","kana":"ほんぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.3929974,"lng":135.85916096,"geo_status":"db","era":"江戸中期／文化6・明治33改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積448㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0149","desc":"吉野川南岸に迫る山麓に占める境内の中央に建つ。桁行１８ｍ梁間１７ｍ、入母屋造本瓦葺で、正面に一間向拝を付ける。外陣と、内陣及び余間、鞘の間、後方の後堂からなり、外陣三方に広縁を巡らす。真宗の吉野地方における中核寺院に相応しい風格を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008015"},{"id":"00008016","register_sub_id":"101","register_pk":"128847","name":"本善寺蓮如堂","kana":"ほんぜんじれんにょどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39319588,"lng":135.85954526,"geo_status":"db","era":"延享4","year":1747,"year_source":"db","year_min":1747,"year_max":1747,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.2㎡、繋廊付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0150","desc":"境内東寄りの山裾に建ち、桁行一間梁間一間、宝形造、正面向拝一間、軒唐破風付、銅板葺である。三方に高欄付切目縁を巡らして脇障子を建て、側面に花頭窓を付け、正面桟唐戸は彫刻で飾る。小規模ながら、開祖を祀る仏堂らしく華やかな意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008016"},{"id":"00008017","register_sub_id":"101","register_pk":"128848","name":"本善寺蓮如堂拝堂","kana":"ほんぜんじれんにょどうはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"奈良県","address":"奈良県吉野郡吉野町大字飯貝567","lat":34.39329935,"lng":135.85946925,"geo_status":"db","era":"延享5","year":1748,"year_source":"db","year_min":1748,"year_max":1748,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"29-0151","desc":"蓮如堂の前面に繋廊を介して建ち、桁行三間梁間二間、入母屋造本瓦葺である。内部は拭板張の一室で格天井を張り、周囲に切目縁をまわす。建具は正面に桟唐戸をたて、他を蔀とし、小壁を漆喰仕上げ、軒は一軒疎垂木。軽快な堂で、柱上の絵様肘木が特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008017"},{"id":"00008050","register_sub_id":"101","register_pk":"128881","name":"吉野神宮表鳥居","kana":"よしのじんぐうおもてとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"奈良県","address":"奈良県吉野郡吉野町大字吉野山3226","lat":34.38733148,"lng":135.84532564,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"石造、間口5.5m、高さ5.9m","structure_material":"石造","registered":"2010.01.15(平成22.01.15)","register_no":"29-0184","desc":"境内の北東、表参道正面に位置し、県道に北面する。石造の明神鳥居で、幅５．５ｍ高さ５．９ｍ。内転びに円柱を建て、貫と嶋木で固め、笠木を載せる。大鳥居と比べ、内転びが大きく、柱間と高さの比例もやや低く、重厚で安定感のある姿をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008050"},{"id":"00015500","register_sub_id":"101","register_pk":"533515","name":"興国寺開山堂","kana":"こうこくじかいさんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97746389,"lng":135.12491944,"geo_status":"db","era":"文政6年（1823）頃","year":1823,"year_source":"db","year_min":1823,"year_max":1823,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0408","desc":"伽藍北方の高台に位置する開山堂。宝形造本瓦葺の三間堂で周囲に縁を廻らす。組物は出組で軒支輪を備え軒は二軒繁垂木。内部は一室で北に仏壇を構え格天井を張る。仏壇下方には開祖法燈国師の墓である宝篋印塔を安置。小規模ながらも総ヒノキ造の上質な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015500"},{"id":"00015499","register_sub_id":"101","register_pk":"533514","name":"興国寺坐禅堂","kana":"こうこくじざぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97731111,"lng":135.12508333,"geo_status":"db","era":"江戸後期／江戸末期増築、昭和59年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0407","desc":"法堂の北に南面して建つ仏堂。入母屋造本瓦葺東西棟の前堂に南北棟の後堂が接続し、全体Ｔ字形の平面。内部は前堂から後堂まで一連の四半敷土間とし、前堂両端間に畳敷の単、後堂北面両端間に仏壇と位牌壇を設ける。伽藍軸線上に建ち、寺院景観の中核を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015499"},{"id":"00015502","register_sub_id":"101","register_pk":"533517","name":"興国寺大門","kana":"こうこくじだいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97526944,"lng":135.12623333,"geo_status":"db","era":"昭和13年／平成9年移築","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0410","desc":"伽藍南端の参道入口に南面して建つ四脚門。切妻造本瓦葺で、円柱の主柱と控柱を腰貫と頭貫で固め、柱頂に三斗を組んで妻虹梁を受け、丸桁を支持する。軒は二軒繁垂木。頭貫木鼻は牡丹の篭彫とするなど華やか。建ちが高い総ケヤキ造の門で古刹の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015502"},{"id":"00015498","register_sub_id":"101","register_pk":"533513","name":"興国寺法堂","kana":"こうこくじはっとう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97715278,"lng":135.12525278,"geo_status":"db","era":"寛政9年（1797）","year":1797,"year_source":"db","year_min":1797,"year_max":1797,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積194㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0406","desc":"由良町の山間に位置する臨済宗寺院の法堂。境内中心部に南面して建つ方五間二重入母屋造本瓦葺で正面に軒唐破風を付し、千鳥破風を飾る。内部は四半敷の土間とし、身舎背面側に須弥壇を設け、上部には広大な鏡天井を張り、龍を描く。大規模で雄大な禅宗仏殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015498"},{"id":"00015501","register_sub_id":"101","register_pk":"533516","name":"興国寺方丈","kana":"こうこくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県日高郡由良町大字門前字三光坪801-7","lat":33.97728333,"lng":135.12558889,"geo_status":"db","era":"元禄11年（1698）／天保9年（1838）増築","year":1698,"year_source":"db","year_min":1698,"year_max":1698,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0409","desc":"法堂の東側に西面して建つ方丈。寄棟造本瓦葺の南北棟で、西面南寄りに向唐破風造の玄関を突出する。平面は3列6室で三方に広縁を廻らし、西半は室中、北東に床、違棚、付書院を備えた座敷を配す。側通りには１間毎に柱を立てるなど古式を残す大規模な方丈。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015501"},{"id":"00016424","register_sub_id":"101","register_pk":"536491","name":"高山寺本堂","kana":"こうざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県田辺市稲成町393","lat":33.74045,"lng":135.37888333,"geo_status":"db","era":"昭和43年／平成26年改修","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄筋コンクリート造平屋建地階付、瓦葺、建築面積247㎡","structure_material":"鉄筋コンクリート造平屋建地階付","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0411","desc":"会津川沿いの高台にある真言宗寺院本堂。設計は大岡實。鉄筋コンクリート造入母屋造本瓦葺の五間堂形式で基壇に組高欄を廻らす。平面は内陣と外陣境に畳敷の中の間を配す。太い木割、柱や桁の隅延び、軒反りの曲線など、古代建築に精通した大岡實らしい仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016424"},{"id":"00010335","register_sub_id":"101","register_pk":"199108","name":"興山寺本堂","kana":"こうざんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県紀の川市桃山町最上字東垣内561","lat":34.231283,"lng":135.347973,"geo_status":"db","era":"明治22年","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"30-0201","desc":"宝形造本瓦葺の三間堂で背面の庇一間を取込み、正面に向拝を付ける。柱上端を虹梁で固めて長押との間に彫刻化した蟇股を挟み、籠彫の木鼻を付す。組物は出組詰組で獅子の拳鼻を飾る。内部は一室で二重折上小組格天井を張る。豊かな彫刻で荘厳された近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010335"},{"id":"00014923","register_sub_id":"101","register_pk":"519183","name":"興禅寺庫裏","kana":"こうぜんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県西牟婁郡上富田町市ノ瀬字中ノ岡1043他","lat":33.70942778,"lng":135.46888611,"geo_status":"db","era":"天保2年(1831)／昭和後期改修","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積307㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0358","desc":"富田川南岸の高台に位置する臨済宗寺院の庫裏。北西を正面とする切妻片入母屋造妻入本瓦葺で棟上に煙出を設ける。正面妻は連子窓を開け、海老虹梁を架ける。三列に部屋を並べ、西に土間玄関、南東に二間続きの座敷、北東に台所。軸部木太く規模雄大な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014923"},{"id":"00015225","register_sub_id":"101","register_pk":"530649","name":"光臺院経蔵","kana":"こうだいいんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山649","lat":34.21686667,"lng":135.58474167,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0386","desc":"参道の西方に位置する校倉造の経蔵。切石積の基壇上に東面して建つ宝形造本瓦形銅板葺。礎石に円柱の床束を立て、井桁に組んだ台輪に校木を積んで丸桁を載せ、軒は一軒半繁垂木とする。内部は一室の板敷で猿頬天井張。同高に校木を積み上げる端正な姿の経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015225"},{"id":"00015224","register_sub_id":"101","register_pk":"530648","name":"光臺院多宝塔","kana":"こうだいいんたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山649","lat":34.21758889,"lng":135.58452778,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積6.0㎡","structure_material":"木造多宝塔","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0385","desc":"高野山五之室谷に位置する真言宗別格本山寺院の多宝塔。庭園内の築山上に建ち、下層は四方に擬宝珠高欄付縁を廻らし、組物は出組。上層は四手先とし軒は上下とも二軒扇垂木。屋根と亀腹は銅板葺。蟇股に菊花紋を掲げ、精緻なつくりで、名刹に相応しい多宝塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015224"},{"id":"00013174","register_sub_id":"101","register_pk":"368403","name":"神野阿弥陀堂","kana":"こうのあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷字東堂之前1049","lat":34.34918889,"lng":135.49143333,"geo_status":"db","era":"貞享3年（1686）／平成4年改修","year":1686,"year_source":"db","year_min":1686,"year_max":1686,"year_label":null,"structure":"木造平屋建、茅葺（金属板仮葺）、建築面積109㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"30 － 0277","desc":"葛城山間の集落北側に南面して建つ仏堂。寄棟造平入茅葺金属板仮葺の三間堂で、四周に切目縁を廻し庇柱を立てる。身舎柱はケヤキ円柱で、虹梁形頭貫を架け、組物は大斗肘木とする。側柱はクリの大面取り角柱に舟肘木である。紀北地域の村堂の事例として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013174"},{"id":"00000803","register_sub_id":"101","register_pk":"101793","name":"高野山霊宝館玄関・北廊・中廊","kana":"こうやさんれいほうかんげんかん・きたろう・なかろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21138903,"lng":135.58113912,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積147㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0013","desc":"霊宝館の受付部で，中廊により紫雲殿と，北廊により放光閣と結ばれる。玄関は，正面３間の単層入母屋造，北廊・中廊は単層の吹放廊で，丸柱間に蔀戸風の腰羽目を付ける。基壇上に建つ紫雲殿と放光閣の寄り付き部の棟を上げ，流動感を生みだしているのが特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000803"},{"id":"00000802","register_sub_id":"101","register_pk":"101792","name":"高野山霊宝館紫雲殿","kana":"こうやさんれいほうかんしうんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21119172,"lng":135.58113181,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積226㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0012","desc":"高野山開創１１００年記念として計画された宝物館で，当初は右翼を含む日の字形の配置計画であった｡設計は大江新太郎と奥本吾市｡当地の厳しい気候条件を考慮して，宝蔵を除き木造漆喰塗とする。紫雲殿は正面奥に位置する単層切妻造の建物で正殿にあたる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000802"},{"id":"00000804","register_sub_id":"101","register_pk":"101794","name":"高野山霊宝館放光閣","kana":"こうやさんれいほうかんほうこうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21138903,"lng":135.58086141,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，銅板葺，建築面積126㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0014","desc":"下層５間×５間，上層３間×３間の重層宝形造りで，下層は大斗・舟肘木，上層は出組の詰組とし，隅に尾垂木を付ける。西面後部を裳階付とし，内部に阿弥陀如来を納める。紫雲殿と同様，内部床はコルク張り，高窓の外側に鉄製の縦型ブラインドを設置する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000804"},{"id":"00000806","register_sub_id":"101","register_pk":"101796","name":"高野山霊宝館宝蔵","kana":"こうやさんれいほうかんほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21100902,"lng":135.58089065,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積96㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0016","desc":"この棟のみ鉄筋コンクリート造とする。桁行３６尺，梁間２４尺，建坪２４坪，寄棟屋根の収蔵庫で，校倉造の形式を有する。校倉形式の鉄筋コンクリート造建築としては最初のもので，大江新太郎設計になる明治神宮宝物殿（大正１０年）の習作と考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000806"},{"id":"00000805","register_sub_id":"101","register_pk":"101795","name":"高野山霊宝館南廊及西廊","kana":"こうやさんれいほうかんみなみろうおよびにしろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町高野山306","lat":34.21119172,"lng":135.58091257,"geo_status":"db","era":"大正9","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建，鉄板葺，建築面積203㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"30 － 0015","desc":"紫雲殿の西面に発し，南西隅で矩折れ放光閣の南面に接続する梁間２１尺の廊で，南西隅に宝形の隅櫓を載せてヴォリュームのバランスをとっている点に特徴がある。南廊は古文書及び美術工芸品の，隅櫓部は大師関係品の，西廊は仏像彫刻の展示室に充てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000805"},{"id":"00015361","register_sub_id":"101","register_pk":"532485","name":"金剛峯寺阿字観堂","kana":"こんごうぶじあじかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和後","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.21420833,"lng":135.58303611,"geo_status":"db","era":"昭和42年","year":1967,"year_source":"db","year_min":1967,"year_max":1967,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0393","desc":"応接室の北西に位置し、阿字観をおこなう道場。石庭に南面する桁行七間梁間三間切妻造平入銅板葺で周囲に縁を廻らす。中央の広間に来迎壁を設けて阿字を掲げ、左右に六畳大の子房を四室設ける。法隆寺西室などの僧房建築を参考に案出した高野山唯一の阿字観堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015361"},{"id":"00015359","register_sub_id":"101","register_pk":"532483","name":"金剛峯寺応接室（旧貴賓館附属浴室）","kana":"こんごうぶじおうせつしつ（きゅうきひんかんふぞくよくしつ）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.21408333,"lng":135.58312222,"geo_status":"db","era":"昭和8年／昭和32年頃移築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0391","desc":"奥殿の北東に位置し、旧貴賓館の浴室を曳家改修した応接室。切妻造銅板葺で四周に縁を廻し西と東に庇を付す。柱頭で軒桁を受け、軒は一軒疎垂木。妻飾は豕扠首。内部は一室の板敷で竿縁天井を張り東に床を構え石庭を望む。奥殿に続き庭園景観をつくる応接室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015359"},{"id":"00015357","register_sub_id":"101","register_pk":"532481","name":"金剛峯寺奥殿(旧貴賓館）","kana":"こんごうぶじおくでん（きゅうきひんかん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山132","lat":34.21397222,"lng":135.58291944,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積330㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0389","desc":"高野山に位置する真言宗総本山寺院の貴賓用の客殿。石庭に南面して建つ入母屋造平入銅板葺で正面に切妻造玄関を付す。二列八室の周囲に擬宝珠高欄付縁を廻らし、玄関は絨毯敷で貴賓室に用い、南西に床構え付座敷を配す。正面の大蟇股が目を惹く優雅な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015357"},{"id":"00015365","register_sub_id":"101","register_pk":"532489","name":"金剛峯寺奧殿塀","kana":"こんごうぶじおくでんへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷137","lat":34.21374444,"lng":135.58275833,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、銅板葺、延長81m","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0397","desc":"勅使門の東西に延びる延長81メートルの塀。土台上に角柱を立て、腰長押と内法長押を廻らし、北側に控柱を立て２段の貫で繋ぐ。大仏様風の繰型付き腕木で出桁を支え、軒は一軒疎垂木とし屋根銅板葺。外壁は真壁造で漆喰塗仕上。長大な塀が境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015365"},{"id":"00015360","register_sub_id":"101","register_pk":"532484","name":"金剛峯寺奥殿渡廊下","kana":"こんごうぶじおくでんわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷137","lat":34.214,"lng":135.58310278,"geo_status":"db","era":"昭和8年／昭和32年頃増築","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0392","desc":"奥殿、別殿及び応接室を接続する平面Ｔ字形の渡廊下。両下造銅板葺で角柱上の舟肘木で桁を支え、虹梁を架け大斗肘木で棟木を支持。軒は一軒疎垂木。柱間は吹放ちとし高欄と飛貫を入れ、板敷床で化粧軒裏を現す。軽快なつくりで周囲の建物と調和した渡廊下。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015360"},{"id":"00015496","register_sub_id":"101","register_pk":"533511","name":"金剛峯寺浄水所","kana":"こんごうぶじじょうすいじょ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷152-1","lat":34.21313333,"lng":135.5813,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積34㎡","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0404","desc":"壇上伽藍へ至る蛇腹路の南側に位置し、北面して建つ浄水所。桁行三間梁間一間、鉄筋コンクリート造切妻造瓦棒銅瓦葺で、四方を吹放つ。内部中央には水盤を据え、上部は化粧屋根裏天井を現す。内外は全て白色塗装とし、簡明ながら大規模で存在感を示す手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015496"},{"id":"00015495","register_sub_id":"101","register_pk":"533510","name":"金剛峯寺鐘楼","kana":"こんごうぶじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷152-1","lat":34.21293889,"lng":135.58003333,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積30㎡","structure_material":"鉄筋コンクリート造","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0403","desc":"壇上伽藍の金堂南東に位置する鐘楼。基壇上に北面して建つ、鉄筋コンクリート造入母屋造瓦棒銅瓦葺。柱を隅に寄せた方三間で四方を吹放ち、台輪上に出組を詰組に配し、軒は二軒繁垂木。細部は金堂などに通じる復古調の意匠とし、軒出が深く堂々たる姿の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015495"},{"id":"00015362","register_sub_id":"101","register_pk":"532486","name":"金剛峯寺新書院","kana":"こんごうぶじしんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.214125,"lng":135.58270278,"geo_status":"db","era":"大正前期／昭和32年移築","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、銅板葺、建築面積168㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0394","desc":"奥殿の北西に廊下で接続する貴賓用の離座敷。入母屋造銅板葺の南北棟で周囲に下屋を廻らし、北西に浴室を附属する。内部は三室からなり、北室は１８畳の主座敷で、床、違棚、付書院を備える。全体に良材を豊富に用い、障壁画や細部意匠に優れた華やかな座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015362"},{"id":"00015363","register_sub_id":"101","register_pk":"532487","name":"金剛峯寺真松庵","kana":"こんごうぶじしんしょうあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷136","lat":34.21413889,"lng":135.582575,"geo_status":"db","era":"昭和39年","year":1964,"year_source":"db","year_min":1964,"year_max":1964,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0395","desc":"新書院の西に接続する貴賓用の茶室。八畳広間席の南東に六畳の待合棟、南西に４畳半茶室を付す。広間席の天井は疎らに組んだ格天井とし、天井板の板目を市松状に配する凝ったつくり。いずれも軒高を抑えた銅板葺屋根で、柱を面皮付とした上質なつくりの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015363"},{"id":"00015364","register_sub_id":"101","register_pk":"532488","name":"金剛峯寺勅使門","kana":"こんごうぶじちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字本中院谷137","lat":34.21372778,"lng":135.58284444,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造、檜皮葺、間口3.5m","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0396","desc":"奥殿正面に開く、一間一戸檜皮葺の平唐門。円柱の主柱と大面取角柱の控柱を腰貫、飛貫、男梁で繋ぎ、軒は一軒疎垂木とし、棟木を蟇股と垂木で受ける特徴的なつくり。門口に繊細な連子の板扉を開け、欄間に寺紋を飾る。螻羽深く、全体に優美で上質な勅使門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015364"},{"id":"00015358","register_sub_id":"101","register_pk":"532482","name":"金剛峯寺別殿（旧客殿）","kana":"こんごうぶじべつでん（きゅうきゃくでん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山132","lat":34.21388056,"lng":135.58321944,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積363㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"31 - 0390","desc":"奥殿の東に位置する僧侶・信徒用の客殿。石庭に西面して建つ入母屋造銅板葺で柱上に組物なく直接軒桁を受け、軒は一軒疎垂木。二列八室の周囲に刎高欄付縁を廻らし、南西を床構え付座敷とする。内向きの控え目な意匠としつつ寺格に応じた大規模で上質な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015358"},{"id":"00015494","register_sub_id":"101","register_pk":"533509","name":"金剛峯寺六角経蔵","kana":"こんごうぶじろっかくきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山152-1","lat":34.21281667,"lng":135.57895833,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"鉄筋コンクリート造二階建、銅板葺、建築面積21㎡","structure_material":"鉄筋コンクリート造二階建","registered":"2025.08.06(令和7.08.06)","register_no":"30 - 0402","desc":"金剛峯寺壇上伽藍の金堂南西に位置する経蔵。基壇上に東面して建つ鉄筋コンクリート造、二重、六角円堂で宝形造銅板葺。初重は壁式構造に木造で校倉風、二重はラーメン構造に木造で組物・軒廻りを付加するなど、躯体の表層に木造で伝統的意匠を実現した経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015494"},{"id":"00016426","register_sub_id":"101","register_pk":"536493","name":"西南院経蔵","kana":"さいなんいんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山249","lat":34.21218333,"lng":135.57477222,"geo_status":"db","era":"享和3年（1803）／昭和後期改修","year":1803,"year_source":"db","year_min":1803,"year_max":1803,"year_label":null,"structure":"土蔵造2階建、銅板葺、建築面積31㎡","structure_material":"土蔵造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0413","desc":"境内南端の高台に北面して建つ経蔵。土蔵造二階建、入母屋造銅板葺の置屋根形式で、一階正面に唐破風造銅板葺の前室を付す。外壁は大壁で、床下は柱のみを塗込め、高床風の外観とする。前室正面に大振りの板蟇股を飾り、組物などに彩色を施した華やかな経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016426"},{"id":"00016427","register_sub_id":"101","register_pk":"536494","name":"西南院山門","kana":"さいなんいんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和後","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字西院谷249","lat":34.21286389,"lng":135.57527778,"geo_status":"db","era":"昭和45年頃","year":1970,"year_source":"db","year_min":1970,"year_max":1970,"year_label":null,"structure":"木造、銅板葺、間口4.5m、左右袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0414","desc":"境内東寄りに北面して建ち、表門となる四脚門。切妻造銅板葺で左右に切妻造銅板葺の袖塀を付す。門は主柱を円柱、控柱を角柱とし、軒は垂木に強い反りを付した二軒繁垂木、妻飾は虹梁蟇股。全体に均整とれた姿で、中備の蟇股など復古的な意匠でまとめた山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016427"},{"id":"00016425","register_sub_id":"101","register_pk":"536492","name":"西南院本堂","kana":"さいなんいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山249","lat":34.21240556,"lng":135.57508889,"geo_status":"db","era":"明治34年頃／昭和中期改修","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0412","desc":"高野山の西院谷に位置する真言宗寺院の本堂。境内南東部に北面して建つ入母屋造檜皮葺で、正面東寄りに向唐破風造向拝を付す。内部は内陣を並列する特徴的な平面で東に金剛界大日如来、西に不動明王を安置。明治３年焼失後の再建になる近代の大規模な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016425"},{"id":"00014911","register_sub_id":"101","register_pk":"519171","name":"志磨神社神門及び袖塀","kana":"しまじんじゃしんもんおよびそでへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市中之島677","lat":34.23996667,"lng":135.18076389,"geo_status":"db","era":"昭和19年","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"神門 木造、瓦葺、間口2.7m、袖塀 木造、瓦葺、総延長16m","structure_material":"神門 木造","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0346","desc":"境内南端、参道正面に建つ一間一戸の四脚門。柱は面取角柱とし、本柱を繋ぐ冠木上に巻斗を並べて棟木を支える。控柱は頭貫で繋ぎ、大斗肘木を載せる。軒は一軒疎垂木。袖塀は連子格子で腰板壁とする。整った意匠をもつ神門で袖塀とともに境内の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014911"},{"id":"00014910","register_sub_id":"101","register_pk":"519170","name":"志磨神社手水舎","kana":"しまじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市中之島677","lat":34.24003889,"lng":135.18081389,"geo_status":"db","era":"昭和19年","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積5.8㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0345","desc":"参道脇に西面する手水舎。方一間切妻造桟瓦葺。四隅に面取角柱を内転びに立て飛貫で固め、木鼻は大仏様風。組物を介さず柱頭に直接梁桁を架け柱間は貫上に蟇股を載せる。妻飾は豕扠首。簡素ながら洗練された意匠をもつ手水舎で、境内の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014910"},{"id":"00014909","register_sub_id":"101","register_pk":"519169","name":"志磨神社拝殿","kana":"しまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県和歌山市中之島677","lat":34.24023056,"lng":135.18088889,"geo_status":"db","era":"昭和19年／昭和42年改修","year":1944,"year_source":"db","year_min":1944,"year_max":1944,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"30 - 0344","desc":"和歌山城北東に位置する式内社。本殿の南側に建つ桁行五間梁間三間、入母屋造平入銅板葺で正面に三間の軒唐破風向拝を付し、背面に両下造の祝詞殿、北西に切妻造の神饌所を附属。内部は格天井とし正側面に切目縁を廻す。蟇股や虹梁絵様など整った意匠の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014909"},{"id":"00015219","register_sub_id":"101","register_pk":"530643","name":"淨願寺庫裏","kana":"じょうがんじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分字廣田823-1他","lat":34.26444722,"lng":135.34344722,"geo_status":"db","era":"江戸後期／平成29年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積245㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0380","desc":"本堂の西に位置する庫裏。東面して建つ入母屋造平入桟瓦葺で、正面南寄りに唐破風造の式台玄関を付す。内部は南に土間、北に8室を配し、北西に角座敷を延ばして上段の間とし、西面に床を構え、前面に上段を設ける。大振りな式台玄関が目を惹く大規模な庫裏。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015219"},{"id":"00015223","register_sub_id":"101","register_pk":"530647","name":"淨願寺山門","kana":"じょうがんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26428333,"lng":135.343675,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口3.2m、袖塀付","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0384","desc":"境内南辺東寄りに位置し、通りに南面する山門。一間一戸切妻造平入本瓦葺の薬医門で両脇に袖塀を付し、正面側に中古の控柱を立てる。男梁上の平三斗で妻虹梁を受け、笈形付大瓶束で棟木を支持。軒は二軒繁垂木。虹梁や肘木など絵様彫刻で飾った華やかな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015223"},{"id":"00015221","register_sub_id":"101","register_pk":"530645","name":"淨願寺鐘楼","kana":"じょうがんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26429722,"lng":135.343575,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積9.0㎡","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0382","desc":"本堂の南西に位置する鐘楼。切石積基壇上に建つ方一間切妻造本瓦葺。礎盤上に角柱を四方転びに立て、腰貫、飛貫、虹梁形頭貫で固め、組物は大斗肘木、妻飾は虹梁大瓶束笈形付、軒は二軒疎垂木。虹梁・蟇股・懸魚を彫刻で飾り、総ケヤキ造とした上質な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015221"},{"id":"00015222","register_sub_id":"101","register_pk":"530646","name":"淨願寺手水舎","kana":"じょうがんじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26437222,"lng":135.34363889,"geo_status":"db","era":"江戸後期／昭和54年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積5.2㎡","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0383","desc":"本堂の南に位置する手水舎。入母屋造の本瓦葺南北棟で、角柱を四方転びに立て、虹梁形頭貫で固め、組物は大斗肘木の詰組、軒は二軒吹寄垂木とする。柱間を吹放し、土間中央西寄りに水盤を据え格天井を張る。小規模ながら降棟を付すなど重厚な屋根の手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015222"},{"id":"00015220","register_sub_id":"101","register_pk":"530644","name":"淨願寺宝蔵","kana":"じょうがんじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26431389,"lng":135.34374722,"geo_status":"db","era":"大正2年／昭和54年移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0381","desc":"本堂の南東、参道に西面して建つ宝蔵。方一間宝形造本瓦葺で露盤宝珠を飾る。外壁は漆喰塗仕上で腰は下見板張。正面は戸口に両開戸を吊り、本瓦葺庇を付す。内部は一室の板敷で三方に棚を備え、上部は束立の和小屋を現す。小規模ながら寺観を整える宝蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015220"},{"id":"00015218","register_sub_id":"101","register_pk":"530642","name":"淨願寺本堂","kana":"じょうがんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県紀の川市東国分812他","lat":34.26451667,"lng":135.343675,"geo_status":"db","era":"天明4年(1784)／明治前期増築、昭和54年改修","year":1784,"year_source":"db","year_min":1784,"year_max":1784,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積233㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0379","desc":"紀の川中流域の集落中心部に位置する浄土真宗寺院の本堂。境内北東隅に南面して建つ入母屋造平入本瓦葺で一間向拝を付す。内部は内・外陣、左右両余間からなり、正面吹放ちの広縁付。大虹梁や欄間など彫刻で荘厳し、本瓦葺の大屋根が集落景観の核をなす本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015218"},{"id":"00015367","register_sub_id":"101","register_pk":"532491","name":"常喜院客殿","kana":"じょうきいんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷365","lat":34.21298889,"lng":135.58300556,"geo_status":"db","era":"明治前期／昭和41年増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、銅板葺、建築面積361㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0399","desc":"本堂の東方に南面して建つ客殿。入母屋造平入銅板葺で正面東寄りに入母屋造玄関を突出。玄関を入った正面８畳間を挟んで、東に庫裏、西に客殿を接続し、客殿に持仏間、上段の間を配する。高野山における近世以来の平面的な特徴を備えた近代の大規模な客殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015367"},{"id":"00015369","register_sub_id":"101","register_pk":"532493","name":"常喜院山門","kana":"じょうきいんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷364","lat":34.21284167,"lng":135.58315833,"geo_status":"db","era":"昭和30年頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造、銅板葺、間口3.5m、袖塀付","structure_material":"木造","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0401","desc":"境内東辺に東面して建つ正門。切妻造銅板葺の四脚門で両脇に袖塀を付す。主柱は円柱、控柱は角柱、組物出三斗、軒は反りのある二軒疎垂木。妻飾は虹梁に束立で蟇股風笈形を付す。頭貫木鼻や蟇股などを復古的な細部意匠とし、ヒノキの良材を用いた上質な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015369"},{"id":"00015368","register_sub_id":"101","register_pk":"532492","name":"常喜院拝殿","kana":"じょうきいんはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷364","lat":34.21297778,"lng":135.58255,"geo_status":"db","era":"明治43年頃／令和6年改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積268㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0400","desc":"日露戦争戦没者慰霊塔の拝殿で境内中央部に南面して建つ。入母屋造銅板葺で正背面に軒唐破風を付す。内部は3列6室に部屋を並べ、西列北は折上小組格天井の上段の間とし、上段に付書院と帳台構を備える豪壮なつくり。大振りな軒唐破風など外観華やかな拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015368"},{"id":"00015366","register_sub_id":"101","register_pk":"532490","name":"常喜院本堂（旧最勝院本堂）","kana":"じょうきいんほんどう（きゅうさいしょういんほんどう）","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字南谷364","lat":34.21285833,"lng":135.58224722,"geo_status":"db","era":"江戸末期／昭和41年増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、銅板葺、建築面積324㎡","structure_material":"土蔵造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"30 - 0398","desc":"高野山の南谷にある真言宗寺院の本堂。境内西側に東面して建つ宝形造銅板葺主体部の北に入母屋造の護摩堂棟を延ばし、西に切妻造の増築棟を付す複雑な屋根構成。正面の外壁は桁下まで塗込め漆喰塗仕上とし、中央に掛子塗扉を開く。重厚な外観が特徴的な本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015366"},{"id":"00011785","register_sub_id":"101","register_pk":"210801","name":"正住寺離れ座敷","kana":"しょうじゅうじはなれざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"和歌山県","address":"和歌山県和歌山市東長町二丁目17他","lat":34.228235,"lng":135.163822,"geo_status":"db","era":"大正9年／平成25年移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0223","desc":"山門から本堂へと続く参道の北側に建つ。寄棟造桟瓦葺の平屋建で、座敷一〇畳、次の間七畳半の正面側及び背面側に内縁を設け、南西隅に入母屋造の玄関が取り付く。座敷廻りを杉や檜を用いて端正にまとめるなど、質の高い意匠を備える離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011785"},{"id":"00011787","register_sub_id":"101","register_pk":"210803","name":"稱念寺山門","kana":"しょうねんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市加太1346","lat":34.274809,"lng":135.07432,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.9m、左右潜戸付","structure_material":"木造","registered":"2017.06.28(平成29.06.28)","register_no":"30-0225","desc":"境内の西面に建つ四脚門。切妻造本瓦葺で、両脇には小屋根を付けた潜戸が付く。門柱は円柱とし、冠木上に中備蟇股として虹梁を支える。控柱は几帳面取角柱で、門柱との間は腰貫、腰長押、頭貫で繋ぐ。小規模ながら総欅造とするなど質の高い門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011787"},{"id":"00011786","register_sub_id":"101","register_pk":"210802","name":"稱念寺本堂","kana":"しょうねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県和歌山市加太1346","lat":34.274945,"lng":135.074465,"geo_status":"db","era":"寛政7年（1795）／明治40年移築","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積343㎡","structure_material":"木造平屋建","registered":"2017.06.28(平成29.06.28)","register_no":"30-0224","desc":"加太の街中にある西山浄土宗寺院の本堂。入母屋造本瓦葺の七間堂で、和歌山城下にあった真光寺より移築したもの。三間規模の向拝を設け、南東には式台玄関が付く。身舎柱は円柱、庇柱は面取角柱。内陣柱は漆塗金襴巻、小壁に彫刻欄間をはめるなど荘厳な造り。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011786"},{"id":"00006043","register_sub_id":"101","register_pk":"107028","name":"定福寺庫裏","kana":"じょうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市賢堂285","lat":34.308819,"lng":135.612625,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2006.11.29(平成18.11.29)","register_no":"30 － 0102","desc":"敷地南西に位置し，本堂南西に南面して建つ。南東隅に拝殿を付ける。桁行６間半，梁間５間半の規模で，木造平屋建，入母屋造，桟瓦葺とする。東半を土間，西半を床上部とし，南西隅に座敷を設け続き間座敷とする。床構えに古い形式を留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006043"},{"id":"00010040","register_sub_id":"101","register_pk":"196187","name":"東光寺山門","kana":"とうこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡北山村大字竹原字下モ地296","lat":33.96415242,"lng":135.97346193,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"30 － 0191","desc":"本堂の東正面に建つ四脚門形式の山門で、棟柱を若干正面側にずらし、薬医門に似た構成とする。切妻造桟瓦葺。柱上には組物を設けず、棟通りは冠木上に棟束三本を立てて斗と実肘木で棟木を受け、妻では棟束に大振りの笈形を付す。伽藍正面の景観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010040"},{"id":"00010039","register_sub_id":"101","register_pk":"196186","name":"東光寺本堂","kana":"とうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡北山村大字竹原296","lat":33.96423314,"lng":135.97332362,"geo_status":"db","era":"弘化4","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"30 － 0190","desc":"桁行九間半梁間六間、切妻造平入で、東面して建つ。方丈型本堂と庫裏を組み合わせた形式で、本堂部は五室、庫裏部は四室からなり、簡素な外観ながら、ケヤキを用いた内陣を中心とした上質な堂内をもつ。両妻にはガンギと呼ばれる板張を設け、地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010039"},{"id":"00005658","register_sub_id":"101","register_pk":"106646","name":"日本基督教団紀南教会","kana":"にほんきりすときょうだんきなんきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県東牟婁郡那智勝浦町大字下里930-1","lat":33.57937575,"lng":135.92185449,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋一部2階建、銅板葺、建築面積84㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"30 － 0100","desc":"西村伊作設計の教会堂建築。間口６．４ｍ，奥行１１．７ｍ規模の単廊式教会堂で，正面中央の玄関ポーチを高く造り，急傾斜屋根を架けるのが特徴。玄関ポーチ外壁のみドイツ壁風に仕上げる。内部東面にアルコーブを設けて講壇とし，独特なトラス小屋を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005658"},{"id":"00004603","register_sub_id":"101","register_pk":"105593","name":"日本聖公会橋本基督教会旧礼拝堂","kana":"にほんせいこうかいはしもときりすときょうかいきゅうれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県橋本市古佐田1-244","lat":34.31691634,"lng":135.61255152,"geo_status":"db","era":"明治初期／明治33移築改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"30 － 0069","desc":"もと奈良県吉野にあった明治初期建築の民家。平屋建，切妻造，桟瓦葺で，平面は４間取になる。床上４室が牧師の執務と居住の用に供せられ，移築時に床を張った土間が礼拝堂になる。伝統的な民家の形式を保持しつつ，教会堂に転換された数少ない事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004603"},{"id":"00016719","register_sub_id":"101","register_pk":"579203","name":"宝城院客殿及び庫裏","kana":"ほうじょういんきゃくでんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山156","lat":34.215064,"lng":135.579567,"geo_status":"db","era":"江戸後期／昭和40年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、鉄板葺及び銅板葺、建築面積480㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0429","desc":"境内北寄りに位置する客殿及び庫裏。大規模な客殿の西に、庫裏を配して全体鉄板葺とし、南面西寄りに入母屋造銅板葺の式台玄関を付す。客殿の上段の間は大床を構えて障壁画を飾り、帳台構えを備えるなど格式高い構成とする。高野山における寺院客殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016719"},{"id":"00016720","register_sub_id":"101","register_pk":"579204","name":"宝城院山門","kana":"ほうじょういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字谷上156","lat":34.214814,"lng":135.579422,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、銅板葺、間口3.4m","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0430","desc":"参道正面に建つ正門。切妻造銅板葺、一間一戸の四脚門。主柱は円柱、控柱は角柱とし、組物は出三斗、軒は二軒疎垂木とする。妻の虹梁上の大瓶束は蕾形とした独特な形状で、冠木中央の束に唐獅子と牡丹の笈形を付す。彫刻優秀で、寺観を整える華やかな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016720"},{"id":"00016718","register_sub_id":"101","register_pk":"579202","name":"宝城院本堂及び護摩堂","kana":"ほうじょういんほんどうおよびごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山156","lat":34.214904,"lng":135.579695,"geo_status":"db","era":"江戸後期／昭和40年頃増築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"30 - 0428","desc":"壇上伽藍の北の高台に位置する真言宗寺院の本堂及び護摩堂。本堂は西面して建つ入母屋造平入で一間向拝を付し、背面に増築の内陣を突出。北に接続する護摩堂は切妻造で本堂と一連で瓦型銅板葺とし、正面に縁を廻らす。両堂の内陣が並列する高野山らしい仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016718"},{"id":"00015214","register_sub_id":"101","register_pk":"530638","name":"法然寺本堂","kana":"ほうねんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"和歌山県","address":"和歌山県海南市沖野々字城山553-1","lat":34.16112222,"lng":135.27710278,"geo_status":"db","era":"明治9年／平成29年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積280㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0375","desc":"貴志川西岸の高台に位置する浄土宗寺院本堂。境内中央に南面する入母屋造本瓦葺の五間堂で、正面を吹放ちの広縁とし、一間向拝を付す。組物は大斗肘木、軒は二軒疎垂木、妻飾は虹梁大瓶束。内・外陣境の虹梁上に、躍動的な龍の彫刻を横溢させた華やかな本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015214"},{"id":"00014404","register_sub_id":"101","register_pk":"511393","name":"堀越癪観音庫裏","kana":"ほりこししゃくかんのんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡かつらぎ町大字東谷字向井1360","lat":34.340125,"lng":135.5,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"30 - 0329","desc":"和泉と高野山を往来する七越峠近くに所在する葛城修験行所の一つで、本堂西隣に位置する庫裏。入母屋造茅葺、西側に竈を置く土間、東側を六間取鍵座敷として縁を廻らす農家風の建物。床差し天井、おだち組の小屋など古式を示す。修験の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014404"},{"id":"00013876","register_sub_id":"101","register_pk":"507834","name":"槇尾山明神社摂社弁財天社本殿","kana":"まきおやまみょうじんしゃせっしゃべんざいてんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字九度山字東山新開619-14","lat":34.28826667,"lng":135.56758056,"geo_status":"db","era":"明和2年(1765)／平成17年改修","year":1765,"year_source":"db","year_min":1765,"year_max":1765,"year_label":null,"structure":"木造平屋建、銅板葺、5.8㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0313","desc":"本殿の北に建つ一間社春日造銅板葺。正側面に縁を廻し脇障子を建て浜床を設ける。組物は三斗で背面妻飾は豕扠首。身舎と庇は海老虹梁で繋ぐ。本殿よりやや小規模だが形式は同様で、木柄の太さや肘木の面取に古式を示す。本殿と共に産土社の遺風を伝える社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013876"},{"id":"00013875","register_sub_id":"101","register_pk":"507833","name":"槇尾山明神社本殿","kana":"まきおやまみょうじんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡九度山町大字九度山字東山新開619-14","lat":34.28831944,"lng":135.56761111,"geo_status":"db","era":"明和2年(1765)／平成17年改修","year":1765,"year_source":"db","year_min":1765,"year_max":1765,"year_label":null,"structure":"木造平屋建、銅板葺、8.0㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0312","desc":"槙尾山の西斜面に西面して建つ。一間社春日造銅板葺。正側面に縁を廻し脇障子を建て浜床を設ける。組物は三斗で背面妻飾は豕扠首。身舎と庇は海老虹梁で繋ぐ。正面に板唐戸を建て、内部は引違障子で前後に区画。間口二メートルを超える大型の春日造社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013875"},{"id":"00015226","register_sub_id":"101","register_pk":"530650","name":"密厳院苅萱堂","kana":"みつごんいんかるかやどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山478","lat":34.21250556,"lng":135.59298889,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、檜皮葺及び銅板葺、建築面積423㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"30 - 0387","desc":"金剛峯寺の東方に所在する仏堂。北面して建つ入母屋造檜皮葺東西棟の南に入母屋造銅板葺の南北棟を接続。内部は西に引導地蔵の内陣、東に親子地蔵の内陣を配し、両内陣を結ぶ南側通路は苅萱親子の悲話の絵解き場。街路沿いに建ち地域の歴史的な景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015226"},{"id":"00016600","register_sub_id":"101","register_pk":"574962","name":"養源寺大黒堂","kana":"ようげんじだいこくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1465-1","lat":34.02998889,"lng":135.17308056,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積86㎡、左右渡り廊下及び連絡廊附属","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0425","desc":"本堂と妙見堂と廊下で接続し、出世大黒天を安置する仏堂。東面する入母屋造平入本瓦葺で1間向拝を付す。内陣は畳敷、外陣は拭板張でいずれも格天井。内陣中央西寄りに須弥壇を構え天井を折上げる。向拝の木鼻や手挟など精緻な彫刻で飾り外観華やかな仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016600"},{"id":"00016599","register_sub_id":"101","register_pk":"574961","name":"養源寺本堂","kana":"ようげんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県有田郡広川町大字広1465-1","lat":34.02998889,"lng":135.17308056,"geo_status":"db","era":"正徳3年（1713）／昭和7年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"30 - 0424","desc":"市街地の中心部に位置する日蓮宗寺院本堂。境内中央に東面して建つ、寄棟造平入本瓦葺で向拝一間を付し、北東に入母屋造の玄関を接続。組物は舟肘木、軒は一軒疎垂木。内陣は格天井張で来迎柱や組物を彩色で荘厳する。棟に鯱瓦を載せ古刹の風格を示す本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016599"},{"id":"00012973","register_sub_id":"101","register_pk":"368114","name":"利生護国寺山門","kana":"りしょうごこくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県橋本市隅田町下兵庫字山副732","lat":34.32420833,"lng":135.63354722,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2019.09.10(令和1.09.10)","register_no":"30 － 260","desc":"境内の南辺、本堂正面に開く１間１戸の四脚門。切妻造本瓦葺、板桟戸両開き。門柱は円柱、控柱は面取角柱とし、控柱と門柱は頭貫、腰貫、腰長押でつなぐ。控柱上に実肘木付の連三斗を備える。軒は一軒疎垂木。建ちが高く、古刹にふさわしい門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012973"},{"id":"00013878","register_sub_id":"101","register_pk":"507836","name":"楞厳寺石段及び石垣","kana":"りょうごんじいしだんおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡那智勝浦町大字大野字安之坂1422","lat":33.67346944,"lng":135.84467222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石段 石造、総延長15m、石垣 石造、総延長51m","structure_material":"石段 石造","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0315","desc":"石垣は高台の境内擁壁を兼ね、本堂前庭を囲んで東と南に入口を開ける。流紋岩を野面に積み、前庭から上部は切石積とする。総延長五四メートル。東面の入口から南に曲がる石段が取付き、東に二四段、南に二〇段を数える。山間部にある寺院境内の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013878"},{"id":"00013877","register_sub_id":"101","register_pk":"507835","name":"楞厳寺本堂","kana":"りょうごんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県東牟婁郡那智勝浦町大字大野字安之坂1422","lat":33.673525,"lng":135.84461667,"geo_status":"db","era":"安政4年(1857)／明治後期改修","year":1857,"year_source":"db","year_min":1857,"year_max":1857,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積199㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"30 － 0314","desc":"桁行九間梁間五間半入母屋造桟瓦葺。東面し、広縁を東南面に廻す。方丈形式で、前列は天井棹縁を通して欄間を開放とする等三室を一体的に扱う。後列は内陣両脇に脇間。長押付の貫を一木で造りだすなど堅牢なつくり。向拝や組物も無く質実な外観を有する本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013877"},{"id":"00016429","register_sub_id":"101","register_pk":"536496","name":"蓮華定院客殿及び庫裏","kana":"れんげじょういんきゃくでんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山700","lat":34.21808889,"lng":135.5816,"geo_status":"db","era":"江戸末期／昭和50年頃増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、檜皮葺及び金属板葺、建築面積487㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0416","desc":"本堂の北東に南面して建つ客殿及び庫裏。入母屋造平入檜皮葺で、正面の東寄りに入母屋造の玄関を突出する。内部は東の庫裏、西の客殿からなり、客殿の正面に一間幅の広縁及び濡縁を付して、高欄を廻らす。高野山内における江戸時代の典型的な客殿建築の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016429"},{"id":"00016430","register_sub_id":"101","register_pk":"536497","name":"蓮華定院山門","kana":"れんげじょういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字一心院谷700","lat":34.21791667,"lng":135.58158889,"geo_status":"db","era":"万延元年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造、檜皮葺、間口3.6m、東袖塀付","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0417","desc":"境内南東端に南面して建つ四脚門。切妻造檜皮葺で箱棟に鬼板を飾り、東側に潜戸付袖塀を付す。主柱は円柱、控柱は角柱で三斗を組み、軒は二軒疎垂木。獅子鼻や獏鼻、腰貫上部の牡丹唐草の透欄間など精緻な彫刻を付し、要所の錺金具とともに装飾豊富な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016430"},{"id":"00016431","register_sub_id":"101","register_pk":"536498","name":"蓮華定院塀","kana":"れんげじょういんへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山字一心院谷700","lat":34.21789444,"lng":135.58147222,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、檜皮葺、延長40m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0418","desc":"山門の西側に続く折曲延長40メートルの檜皮葺の塀。柱を一間毎に立て、壁は真壁とし、腰は外を海鼠壁で上部に水切を付す。内は竪板張とする。中央東寄りに通用口を開け、片引板戸を建てる。通りに面して海鼠壁が連なり、重厚な外観が歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016431"},{"id":"00016428","register_sub_id":"101","register_pk":"536495","name":"蓮華定院本堂及び護摩堂","kana":"れんげじょういんほんどうおよびごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"和歌山県","address":"和歌山県伊都郡高野町大字高野山700","lat":34.21808889,"lng":135.58129444,"geo_status":"db","era":"万延元年（1860）／昭和48年増築","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"土蔵造一部木造平屋建、檜皮葺一部金属板葺、建築面積242㎡","structure_material":"土蔵造一部木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"30 - 0415","desc":"一心院谷の東北側に位置する真言宗寺院の仏堂。境内南西端に東面して建つ、入母屋造平入檜皮葺の本堂の北に棟を切下げ護摩堂を接続し、本堂正面に一間向拝を付す。天保14年大火後の再建で、外壁は漆喰塗仕上の大壁で堅牢につくり、独特な外観を呈する仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016428"},{"id":"00007762","register_sub_id":"101","register_pk":"108743","name":"網野神社石鳥居","kana":"あみのじんじゃいしとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68305085,"lng":135.0270127,"geo_status":"db","era":"明治14／大正後期移築・昭和4改修","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"石造、高さ5.5m、幅4.4m","structure_material":"石造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0341","desc":"境内南辺の中央に位置し、本殿への参道が北へ延びる。石造の明神鳥居。高さ５．５ｍ、幅４．４ｍ。低い亀腹上に、直径０．４６ｍの円柱を内転びに建て、貫で固め、反り増しのある笠木と島木を置く。伝統的な比例を踏襲し、安定した姿を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007762"},{"id":"00007760","register_sub_id":"101","register_pk":"108741","name":"網野神社境内社蠶織神社本殿","kana":"あみのじんじゃけいだいしゃこおりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68344082,"lng":135.02749305,"geo_status":"db","era":"天明2／大正13・昭和38改修","year":1782,"year_source":"db","year_min":1782,"year_max":1782,"year_label":null,"structure":"木造、檜皮葺、建築面積7.6㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0339","desc":"境内の東寄りに西面して建つ。檜皮葺の一間社流造、三方に組高欄付切目縁をまわす。柱は円柱で、本支輪付出組とし、桁と妻虹梁を持ち出す。二軒繁垂木で、妻は笈形付虹梁大瓶束。正面に双折両開桟唐戸を吊る。向拝や身舎中備、脇障子など要所に彫物を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007760"},{"id":"00007758","register_sub_id":"101","register_pk":"108739","name":"網野神社神饌所","kana":"あみのじんじゃしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68388964,"lng":135.02699645,"geo_status":"db","era":"昭和前期／平成20改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、金属板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0337","desc":"拝殿北面の西端に建つ。桁行二間梁間二間、南北棟の切妻造金属板葺。面取方柱を長押で固め、柱上に舟肘木を置く。一軒疎垂木で、妻は虹梁蟇股。正面に妻戸、東面に蔀などを装置し、横板壁で、上部に横連子や竪連子窓を開ける。緩い勾配の優美な屋根になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007758"},{"id":"00007759","register_sub_id":"101","register_pk":"108740","name":"網野神社透塀","kana":"あみのじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68397644,"lng":135.02711914,"geo_status":"db","era":"昭和前期／平成20改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、金属板葺、延長30m","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0338","desc":"拝殿後方から本殿を囲んで建つ。延長３０ｍ。方柱を長押等で固め、腕木が軒桁を支持。一軒疎垂木で切妻造金属板葺。腰を横板壁とし、上部に菱格子を嵌め、東西各１ヵ所に両開戸を構える。本殿背面は切石積上に屋根のない瑞垣とする。本殿まわりを厳粛に結界する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007759"},{"id":"00007761","register_sub_id":"101","register_pk":"108742","name":"網野神社手水舎","kana":"あみのじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68312954,"lng":135.02695919,"geo_status":"db","era":"昭和18／平成4改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造、銅板葺、面積6.1㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"26-0340","desc":"境内の南寄り、参道の脇に位置する。桁行一間梁間一間で周囲を吹き放つ。南北棟の切妻造銅板葺。大きく面を取る方柱を切石礎石上に建て、内法貫で固める。柱上に舟肘木を置き、桁や梁を支持。一軒疎垂木の化粧屋根裏天井。妻に蟇股を置く。軸太な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007761"},{"id":"00007756","register_sub_id":"101","register_pk":"108737","name":"網野神社拝殿","kana":"あみのじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68376981,"lng":135.02709765,"geo_status":"db","era":"昭和4／平成20改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0335","desc":"本殿の南方に建つ。桁行三間梁間二間で四周に高欄付切目縁をまわす。入母屋造金属板葺、正面に千鳥破風と唐破風を付ける。側まわりに蔀を装置。内部は拭板敷で、折上小組格天井を張る。柱間の中央に大きく広がる蟇股を置き、左右対称の唐草模様で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007756"},{"id":"00007755","register_sub_id":"101","register_pk":"108736","name":"網野神社本殿","kana":"あみのじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68391481,"lng":135.02711412,"geo_status":"db","era":"大正11／平成20改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0334","desc":"境内中央に位置する。一間社流造金属板葺で、二重基壇上に建つ。円柱で三斗組。組高欄付縁を三方にめぐらし、脇障子を構える。身舎正面は吹寄せ格子の板戸四枚引違をたて、他を板壁とする。蟇股や木鼻、絵様など古建築に精通した設計者ならではの意匠である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007755"},{"id":"00007757","register_sub_id":"101","register_pk":"108738","name":"網野神社渡廊","kana":"あみのじんじゃわたろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京丹後市網野町網野789-1他","lat":35.68385041,"lng":135.02710746,"geo_status":"db","era":"昭和4頃／平成20改修","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"26-0336","desc":"本殿と拝殿の間に建つ。桁行二間梁間一間、南北棟の切妻造妻入金属板葺。面取方柱で、舟肘木を置き、軒は一軒疎垂木。両側面に蔀戸を装置。拭板敷で、化粧屋根裏天井。梁行に虹梁を架し、蟇股を飾る。薄い舟肘木や垂木の反りなど繊細な意匠感覚が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007757"},{"id":"00003265","register_sub_id":"101","register_pk":"104255","name":"安楽寺山門","kana":"あんらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市左京区鹿ケ谷御所ノ段町21","lat":35.02135008,"lng":135.7962735,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、茅葺、間口2.2m、袖塀付","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0148","desc":"寺地南西隅の緩い石段を上がったところに西面して建つ。八角円柱の本柱と面皮の控柱を立て，丸太の桁を回し，小丸太の垂木を扇に配して軒を構成し，屋根を寄棟造，茅葺とする。数寄屋風の造りで特徴ある彫物を付すなど景観構成上欠かせない意匠を凝らした門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003265"},{"id":"00003264","register_sub_id":"101","register_pk":"104254","name":"安楽寺書院（客殿）","kana":"あんらくじしょいん（きゃくでん）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区鹿ケ谷御所ノ段町21","lat":35.02158643,"lng":135.79673938,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0147","desc":"本堂の東に位置し，渡廊下で連絡する。桁行約１３．７ｍ，梁間約７ｍ，切妻造，桟瓦葺で，南に下屋を付す。南北に３室を並べ（もとは１５畳２室），東西及び南に縁を回す。奥の主室には床・違棚を備え，丸太や色土壁を用いて，簡素だが数寄屋風の座敷に造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003264"},{"id":"00003263","register_sub_id":"101","register_pk":"104253","name":"安楽寺本堂","kana":"あんらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区鹿ケ谷御所ノ段町21","lat":35.02161306,"lng":135.79655807,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"26 － 0146","desc":"本堂は境内北寄りに南面して建つ。一重，宝形造，本瓦葺，裳階付の前堂の背後に，後設の切妻造，桟瓦葺の正堂を張り出す。前堂は方１間格天井の身舎周囲に化粧屋根裏の庇を回した形式で，正堂は鏡天井で須弥壇を構える。江戸後期浄土宗本堂の展開を示す遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003263"},{"id":"00013595","register_sub_id":"101","register_pk":"504958","name":"出雲大神宮石鳥居","kana":"いずもだいじんぐういしとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05880833,"lng":135.57827222,"geo_status":"db","era":"享保3年(1718)","year":1718,"year_source":"db","year_min":1718,"year_max":1718,"year_label":null,"structure":"石造、間口4.8m","structure_material":"石造","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0623","desc":"参道屈曲部北側の低い石段上に建つ、花崗岩製の明神鳥居。直径五七センチメートルの円柱を間口四・八メートルに立て、貫で固め、島木、笠木を渡す。島木と笠木は両者全長を一材から造り出す。氏子の寄進により建立された、良材による堅実な作りの石鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013595"},{"id":"00013597","register_sub_id":"101","register_pk":"504960","name":"出雲大神宮上之社本殿","kana":"いずもだいじんぐうかみのやしろほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05949167,"lng":135.57920278,"geo_status":"db","era":"文化10年(1813)","year":1813,"year_source":"db","year_min":1813,"year_max":1813,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0625","desc":"本殿東方の山中に建つ一間社流造、前室及び向拝付、鉄板葺。三方に縁高欄を廻らし身舎の棟通に脇障子をたて正面に木階を付す。前室の庇部は正面に格子、側面に連子窓を建てた外陣とし、身舎は内陣と内々陣に画す。本殿の独自形式に倣いつつ縮小した境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013597"},{"id":"00013593","register_sub_id":"101","register_pk":"504956","name":"出雲大神宮祭器庫","kana":"いずもだいじんぐうさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05881667,"lng":135.578575,"geo_status":"db","era":"明治18年／大正7年移築","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0621","desc":"参道東方の一段高い場所に南北棟で建ち、土蔵造二階建、寄棟造鉄板葺。西面中央を戸口として土戸両開きとし、下屋を設ける。二階の両妻に小窓を穿ち、庇の持送に彫刻を施す。外壁漆喰塗で腰を海鼠壁、軒に蛇腹を廻らす。素木造主体の境内に趣を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013593"},{"id":"00013592","register_sub_id":"101","register_pk":"504955","name":"出雲大神宮社務所","kana":"いずもだいじんぐうしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05891667,"lng":135.57813333,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積182㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0620","desc":"拝殿前方の参道西方に建つ。東西棟の入母屋造の北側に折曲がりに角屋を張出し、西側にも張出しをもつ桟瓦葺建物で変化ある外観とする。平面は座敷列を雁行配置して高欄付縁を廻らし、舞良戸をたて、小壁の蟇股に菊花紋をあしらう。重厚で気品を備えた社務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013592"},{"id":"00013590","register_sub_id":"101","register_pk":"504953","name":"出雲大神宮神饌所","kana":"いずもだいじんぐうしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05928611,"lng":135.57815,"geo_status":"db","era":"明治41年","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0618","desc":"中門西方に南北棟で建ち、桁行一〇メートル、入母屋造鉄板葺。角柱に舟肘木を載せ、東正面中央間の出入口に板唐戸を開き、欄間に吹寄菱格子を入れる。内部は三室で南室は床棚付の座敷、北室は板敷の神饌所で井戸をもつ。神官控所を備えた端正な意匠の神饌所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013590"},{"id":"00013596","register_sub_id":"101","register_pk":"504959","name":"出雲大神宮制札","kana":"いずもだいじんぐうせいさつ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05878333,"lng":135.57821111,"geo_status":"db","era":"明治6年","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造、銅板葺、間口0.9m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0624","desc":"石鳥居の手前西側に東西棟で建つ。花崗岩切石積の基壇上に角柱二本を間口〇・九メートルに立てて貫で固める。柱上部の腕木で桁を受け、わずかに反りを持たせた垂木を疎らに配り、切妻造、段葺状の銅板葺とする。境内の近代再興最初期の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013596"},{"id":"00013598","register_sub_id":"101","register_pk":"504961","name":"出雲大神宮摂社黒太夫社","kana":"いずもだいじんぐうせっしゃくろだゆうしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳南所44","lat":35.05981944,"lng":135.57673056,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.3㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0626","desc":"境内から約一〇〇メートル西方に所在する境外社。南面する一間社流造、鉄板葺で、三方に刎高欄付の縁を廻らせ、背面柱筋に脇障子をたて、庇に浜縁を張る。軸部や組物等の大面取、蟇股や手挟など細部に古典意匠の習熟が看取される。戦前の復古調社殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013598"},{"id":"00013591","register_sub_id":"101","register_pk":"504954","name":"出雲大神宮奏楽舎","kana":"いずもだいじんぐうそうがくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05923333,"lng":135.57860556,"geo_status":"db","era":"明治14年／明治41年移築","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0619","desc":"中門東方の一段高い石垣上に東西棟で建ち、入母屋造鉄板葺である。内部は床と床脇を備えた一室で、南面と西面に高欄付の切目縁を廻らし、軒は一軒疎垂木。はじめ神饌所として建てられ、現神饌所新築の際に移築された。境内の変遷経過を伝える意匠簡明な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013591"},{"id":"00013594","register_sub_id":"101","register_pk":"504957","name":"出雲大神宮手水舎","kana":"いずもだいじんぐうてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05888056,"lng":135.57837222,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造、瓦葺、面積6.2㎡","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0622","desc":"参道の東側に社務所と相対して南北棟で建つ。桁行一間梁間一間、長方形平面の吹放し形式で、起り付きの切妻造桟瓦葺。礎盤上に四本柱を内転びに立て、西面に虹梁形内法貫を渡し、他の三面は貫で固め、柱天に舟肘木を組む。境内入口の景観に寄与する手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013594"},{"id":"00013589","register_sub_id":"101","register_pk":"504952","name":"出雲大神宮拝殿","kana":"いずもだいじんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05915833,"lng":135.57835278,"geo_status":"db","era":"明治11年","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0617","desc":"中門前方に建つ南北棟、桁行三間梁間三間、入母屋造檜皮葺、四方吹放し形式の拝殿。亀腹上に円柱を立て、周囲に刎高欄付の縁を廻らし、内部は全面小組格天井張、軒は二軒繁垂木として軽やかな軒反りをもたせる。境内中枢を占め、格式と優美さを備えた拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013589"},{"id":"00013588","register_sub_id":"101","register_pk":"504951","name":"出雲大神宮本殿廻廊及び透塀","kana":"いずもだいじんぐうほんでんかいろうおよびすきべい","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05926667,"lng":135.57849167,"geo_status":"db","era":"廻廊 昭和10年、透塀 明治26年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"廻廊 木造平屋建、檜皮葺、建築面積37㎡ 透塀 木造、鉄板葺、総延長41m","structure_material":"廻廊 木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0616","desc":"中門の東西にのびる廻廊と、その両端から北に廻る透塀。廻廊は桁行四間で外側は角柱に長押を廻らし、各間に連子窓を入れる。内側は吹放しで梁行に虹梁を架ける。透塀も廻廊と同様の立面として調和を図る。本殿の神域を囲繞する落着いた佇まいの廻廊と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013588"},{"id":"00013587","register_sub_id":"101","register_pk":"504950","name":"出雲大神宮本殿中門及び祝詞舎","kana":"いずもだいじんぐうほんでんちゅうもんおよびのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府亀岡市千歳町千歳出雲無番地","lat":35.05927778,"lng":135.57836389,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"26 － 0615","desc":"拝殿背後に建つ中門の背面に祝詞舎を接続し、拝殿、祝詞舎後方の本殿とともに主要社殿の中軸をなす。中門は四脚門、祝詞舎は中門の背面柱を共有した桁行二間の吹放し形式で、本殿側に軒唐破風を付け、総檜皮葺。和様を基調とし復古的細部を用いた礼拝施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013587"},{"id":"00012184","register_sub_id":"101","register_pk":"352984","name":"今宮神社疫神社本殿","kana":"いまみやじんじゃえきじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.046017,"lng":135.741844,"geo_status":"db","era":"明治41年頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-532","desc":"本殿の西側に並び建ち、桁行三間梁間二間、入母屋造、向拝一間、銅板葺。正側面に刎高欄付の切目縁を廻らして脇障子をたて、外陣に板唐戸と蔀をたてる。蟇股などに、中世社寺の細部の近代的表現による優美な意匠が用いられる。亀岡の特質を示す良質な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012184"},{"id":"00012185","register_sub_id":"101","register_pk":"352985","name":"今宮神社疫神社渡廊・門・廻廊","kana":"いまみやじんじゃえきじんじゃわたろう・もん・かいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04592,"lng":135.741825,"geo_status":"db","era":"明治41年頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-533","desc":"疫神社本殿前に切妻造妻入の渡廊を建てて前面に平唐門を開き、その左右に廻廊をのばす。渡廊は桁行の横架材に反りをもたせて廊全体を強く反らせる。廻廊は前面柱間に吹寄菱欄間を入れる。渡廊、門とも蟇股や門の透彫欄間など亀岡らしい繊細優美な意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012185"},{"id":"00012189","register_sub_id":"101","register_pk":"352989","name":"今宮神社絵馬舎","kana":"いまみやじんじゃえましゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045268,"lng":135.741831,"geo_status":"db","era":"寛政12年(1800)","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-537","desc":"境内南西隅に南北棟で建ち、周囲を吹放す形式で、桁行六間梁間二間、入母屋造桟瓦葺である。基壇上に建ち、太めの角柱を貫で固め、舟肘木で桁を受け、軒は一軒疎垂木、妻飾は虹梁大瓶束とする。内外に多数の絵馬を掲げ、当社の庶民信仰の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012189"},{"id":"00012213","register_sub_id":"101","register_pk":"353013","name":"今宮神社御旅所鏡の間","kana":"いまみやじんじゃおたびしょかがみのま","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039286,"lng":135.748912,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-561","desc":"境内西端に南北棟で建ち、能舞台の橋掛に接続する。桁行一〇・一メートル梁間三・九メートル、入母屋造桟瓦葺。外壁は真壁で中塗仕上とし、東面の橋掛取付部に覗き窓を設ける。内部は広間など三室からなる。能舞台と一体の施設として御旅所の構成要素となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012213"},{"id":"00012210","register_sub_id":"101","register_pk":"353010","name":"今宮神社御旅所権殿社","kana":"いまみやじんじゃおたびしょごんでんしゃ","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039286,"lng":135.749246,"geo_status":"db","era":"寛政7年(1795)","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積8.9㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-558","desc":"境内北東寄りに南面し、前面に神輿奉安殿を建てる。三間社入母屋造、一間向拝付で、正側面に切目縁を廻らす。組物は三斗で中備蟇股とする。旧洛中の最北に位置し、今宮祭の際に神輿から祭神が遷座する重要な役割を担う社殿で、細部意匠はよく整っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012210"},{"id":"00012211","register_sub_id":"101","register_pk":null,"name":"今宮神社御旅所神輿奉安殿","kana":"いまみやじんじゃおたびしょしんよほうあんでん","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039202,"lng":135.749236,"geo_status":"db","era":"昭和20年","year":1945,"year_source":"db","year_min":1945,"year_max":1945,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積90㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-559","desc":"殿社前面に建ち、桁行一〇・五メートル梁間八・六メートル、入母屋造鉄板葺。各面三間で小壁の下方を吹放ちとする。正背面中央間を広め、楣を高く納めて神輿の出入りの便を図る。内部は格天井で、小屋はトラス組。御旅所の中核をなす規模の大きな奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012211"},{"id":"00012212","register_sub_id":"101","register_pk":"353012","name":"今宮神社御旅所能舞台","kana":"いまみやじんじゃおたびしょのうぶたい","category":"宗教","subcategory":"建築物","type_guess":"御旅所・行在所","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市上京区大宮頭今宮御旅所前西入若宮横町136","lat":35.039198,"lng":135.749092,"geo_status":"db","era":"寛政7年(1795)","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-560","desc":"神輿奉安殿の西隣に南面する。桁行梁間とも五・九メートル、入母屋造妻入で、背面に後座を設けて鏡板に松と竹を描き、東面軒下の切目縁を謡座とする。後座西端と鏡の間の間に橋掛を渡す。舞台背面に虹梁を架け、小組格天井を張る。近世能舞台の古例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012212"},{"id":"00012186","register_sub_id":"101","register_pk":"352986","name":"今宮神社神楽殿","kana":"いまみやじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045977,"lng":135.742235,"geo_status":"db","era":"天保10年(1839)／明治後期改修","year":1839,"year_source":"db","year_min":1839,"year_max":1839,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-534","desc":"本殿東側に南北棟で建ち、渡廊で本殿とつなぐ。桁行六・九メートル梁間三・九メートルの神楽所の北室を神殿とし、全体を入母屋造銅板葺とする。神楽所は開放的なつくりで柱上に舟肘木をおき、南室に格天井を張り、切目縁を廻らす。繊細な意匠の神楽殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012186"},{"id":"00012202","register_sub_id":"101","register_pk":"353002","name":"今宮神社祭器庫","kana":"いまみやじんじゃさいきこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045998,"lng":135.742393,"geo_status":"db","era":"江戸後期／大正後期移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-550","desc":"境内北東隅に南北棟で建ち、桁行三間梁間三間、切妻造桟瓦葺。正面中央の柱間をやや広め、中間を竪連子とする桟唐戸を両開きとする。外壁は真壁造で見せ貫とし、妻壁は梁上に大振りの蟇股を置き、虹梁と豕扠首を組む。境内後方の歴史的景観に寄与する祭器庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012202"},{"id":"00012194","register_sub_id":"101","register_pk":"352994","name":"今宮神社地主社拝所・透塀","kana":"いまみやじんじゃじしゅしゃはいしょ・すきべい","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045583,"lng":135.741681,"geo_status":"db","era":"天保13年(1842)","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"拝所 木造平屋建、銅板葺、建築面積6.0㎡ 透塀 木造、総延長6.0m","structure_material":"拝所 木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-542","desc":"地主社本殿正面に建つ拝所と左右の透塀。拝所は桁行二間梁間一間、切妻造妻入で、桁行中央の柱間を結界として吹寄菱格子の扉を両開とする。透塀は拝所桁行中央柱と同じ切石積基礎に建ち、各間に格子をたて目板瓦を葺く。独特の礼拝空間を創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012194"},{"id":"00012193","register_sub_id":"101","register_pk":"352993","name":"今宮神社地主社本殿","kana":"いまみやじんじゃじしゅしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045596,"lng":135.741681,"geo_status":"db","era":"天保13年(1842)","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.7㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-541","desc":"境内西側、若宮社裏の微高地に南面し、二間社流造、銅板葺。周囲に刎高欄付の縁を廻らし、隅行の三手先腰組で支持する。庇は総桁行を一間とし向拝柱に虹梁形頭貫を渡し、蟇股二個をおき、身舎柱と海老虹梁で繋ぐ。間口二間の身舎、縁腰組に独自性を示す社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012193"},{"id":"00012203","register_sub_id":"101","register_pk":"353003","name":"今宮神社神輿庫","kana":"いまみやじんじゃしんよこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045417,"lng":135.742554,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、建築面積80㎡","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-551","desc":"東門の北側に南北棟で建つ。桁行一二・一メートル梁間六・六メートル、土蔵造、寄棟造桟瓦葺で、軒蛇腹を廻らす。西正面は神輿の出入りのため広い柱間で三区画し、黒色の大きな鉄扉を開き、庇を通す。内部は一室で床張とする。重厚な外観をもつ大型の神輿庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012203"},{"id":"00012199","register_sub_id":"101","register_pk":"352999","name":"今宮神社大将軍社本殿・拝所","kana":"いまみやじんじゃたいしょうぐんしゃほんでん・はいしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04558,"lng":135.741763,"geo_status":"db","era":"元禄8年(1695)頃","year":1695,"year_source":"db","year_min":1695,"year_max":1695,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-547","desc":"境内西寄り、八幡社と日吉社の間に東面して建つ。一間社流見世棚造の本殿の前面に、方一間、切妻造妻入の拝所を接続し、拝所背面に設けた棚と本殿の間に木階三級を付けるという独特な形式をもつ。拝所は吹放ち形式で、柱上部の繰型付の持送りも特徴的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012199"},{"id":"00012196","register_sub_id":"101","register_pk":"352996","name":"今宮神社月読社拝所・透塀","kana":"いまみやじんじゃつくよみしゃはいしょ・すきべい","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04540894,"lng":135.74160218,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"拝所 木造平屋建、瓦葺、建築面積2.8㎡ 透塀 木造、瓦葺、総延長5.8m","structure_material":"拝所 木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-544","desc":"月読社本殿正面の切石積基壇に建つ拝所と左右の透塀。拝所は方一間、切妻造妻入で背面柱筋に格子を入れて結界とする。角柱上の舟肘木で虹梁と桁を受け、両妻に豕扠首を組む。透塀は目板瓦葺で柱間に木柵を設ける。境内中心から隔された静かな佇まいの社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012196"},{"id":"00012195","register_sub_id":"101","register_pk":"352995","name":"今宮神社月読社本殿","kana":"いまみやじんじゃつくよみしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045393,"lng":135.741543,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-543","desc":"境内西方の石段上に東面して建ち、一間社流造、銅板葺である。正側面に刎高欄付切目縁を廻らして脇障子をたて、庇に浜床と浜縁を設ける。身舎、庇とも柱上に舟肘木をおく。庇柱は柱天より下方に虹梁を架けて蟇股を置く特異な形式をもつ。簡明な意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012195"},{"id":"00012204","register_sub_id":"101","register_pk":"353004","name":"今宮神社手水舎","kana":"いまみやじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045215,"lng":135.742336,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造、瓦葺、面積5.9㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"26-552","desc":"楼門の北東に位置して北向きに建ち、東参道参詣者の便を図る。方一間、入母屋造で、角柱を貫で固めて各面に格子をたてる。内法貫上に二個、頭貫上に一個の蟇股を置き、いずれも実肘木を一体化して繰型を施す異形の中備とする。華やかな細部意匠をもつ手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012204"},{"id":"00012188","register_sub_id":"101","register_pk":"352988","name":"今宮神社拝殿","kana":"いまみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045708,"lng":135.742059,"geo_status":"db","era":"元禄7年(1694)／弘化3年(1846)改修","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-536","desc":"幣殿正面に東西棟で建つ。桁行三間梁間三間、入母屋造銅板葺で、桁行中央間を約二間分と広め、周囲に刎高欄付切目縁を廻らす。柱上に舟肘木をおき格天井を張り、軒は二軒疎垂木で妻飾を木連格子とする。境内軸の中枢をなす比較的規模の大きな舞殿形式の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012188"},{"id":"00012198","register_sub_id":"101","register_pk":"352998","name":"今宮神社八幡社","kana":"いまみやじんじゃはちまんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04559,"lng":135.741763,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-546","desc":"境内西寄り、八社の南側に東面して建ち、一間社流造、銅板葺。正側面に刎高欄付切目縁を廻らし、脇障子をたてる。身舎は付柱と板唐戸で前後に二分し、前寄りを吹放す。庇組物の桁行肘木は内方も伸ばして虹梁形頭貫上の斗で受ける。手の込んだ造作の境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012198"},{"id":"00012197","register_sub_id":"101","register_pk":"352997","name":"今宮神社八社","kana":"いまみやじんじゃはっしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045644,"lng":135.741765,"geo_status":"db","era":"元禄7年(1694)頃","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.5㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-545","desc":"若宮社の北側に並ぶ小社群の北端に建つ。八間社流見世棚造、桟瓦葺で、各間に八幡神等を祀り、庇は一間おきに柱を省く。身舎は円柱、庇は角柱として舟肘木をおき、庇の梁行を虹梁で繋ぐ。元禄再興期に末社を合祀して建立されたとされ、境内再編履歴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012197"},{"id":"00012209","register_sub_id":"101","register_pk":"353009","name":"今宮神社東門南北築地塀","kana":"いまみやじんじゃひがしもんなんぼくついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045141,"lng":135.742597,"geo_status":"db","era":"明治14年","year":1881,"year_source":"db","year_min":1881,"year_max":1881,"year_label":null,"structure":"土塀、瓦葺、延長27m","structure_material":"土塀","registered":"2018.03.27(平成30.03.27)","register_no":"26-557","desc":"東門の南北に折曲がりにのびる土塀で、切妻造本瓦葺である。切石積基礎に布石を伏せて須柱を立て、桁上の出し梁で軒桁を受け、一軒繁垂木の軒を受ける。壁は中塗仕上げで定規筋五本を現す。妻には蟇股を置くなど上質なつくりで、門前の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012209"},{"id":"00012200","register_sub_id":"101","register_pk":"353000","name":"今宮神社日吉社","kana":"いまみやじんじゃひよししゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045568,"lng":135.741762,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.6㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-548","desc":"若宮社北側の小社群の南端に東面して建つ。一間社流見世棚造、銅板葺。身舎内部を前後に二分して室境に板唐戸を開き、前室前面に格子をたてる。身舎は円柱に舟肘木をおき、庇は角柱上の連三斗で桁を受け、中備蟇股とする。境内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012200"},{"id":"00012183","register_sub_id":"101","register_pk":"352983","name":"今宮神社幣殿・拝所・廻廊","kana":"いまみやじんじゃへいでん・はいしょ・かいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045916,"lng":135.742044,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-531","desc":"本殿前に切妻造妻入の幣殿を建てて前面に向唐破風造の拝所を構え、幣殿左右に廻廊をのばす。いずれも円柱で、幣殿は柱を絵様虹梁で繋ぎ大斗実肘木を載せ、廻廊は舟肘木で桁を受け、前面柱間に吹寄菱欄間を入れる。拝所妻壁は透彫の雲紋等で装飾性を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012183"},{"id":"00012182","register_sub_id":"101","register_pk":"352982","name":"今宮神社本殿","kana":"いまみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.046014,"lng":135.742039,"geo_status":"db","era":"明治35年","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-530","desc":"境内北端に疫神社本殿と並び建つ。桁行三間梁間二間、切妻造、向拝一間、銅板葺。四周に榑縁を廻らし脇障子をたて、外陣に板唐戸と蔀をたてる。向拝の間口と奥行、けらばを広めて屋根をのびやかに張出す。伝統形式を保守しつつ優美な外観をもつ近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012182"},{"id":"00012187","register_sub_id":"101","register_pk":"352987","name":"今宮神社本殿築地塀","kana":"いまみやじんじゃほんでんついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.046087,"lng":135.741719,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土塀、瓦葺、延長65m","structure_material":"土塀","registered":"2018.03.27(平成30.03.27)","register_no":"26-535","desc":"本殿と疫神社本殿の北背面と東西両面に折曲がりに廻らされた土塀で、延長六五・四メートルを測る。北面中央に埋門を設け、切妻造桟瓦葺及び本瓦葺である。石積基礎上に建ち、内側は一間毎に須柱を立て、定規筋五本を現す。本殿域に格式を添える上質な土塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012187"},{"id":"00012201","register_sub_id":"101","register_pk":"353001","name":"今宮神社宗像社","kana":"いまみやじんじゃむなかたしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045174,"lng":135.742424,"geo_status":"db","era":"元禄7年(1694)頃","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-549","desc":"境内南東隅に東面し、鯰を陰刻した切石積基壇に建ち、一間社流造、銅板葺である。身舎前半を吹放ち、正側面に縁を廻らし脇障子をたて庇に浜床を付ける。身舎は円柱に舟肘木、庇は角柱に三斗を組み、両者を海老虹梁で繋ぐ。小社ながら多様な造作が施される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012201"},{"id":"00012205","register_sub_id":"101","register_pk":"353005","name":"今宮神社楼門","kana":"いまみやじんじゃろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045134,"lng":135.742185,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造2階建、銅板葺、建築面積47㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"26-553","desc":"境内南正面の中ほどに建つ。三間一戸楼門、入母屋造銅板葺。下層は腰組を三手先とし、脚を伸ばした華麗な蟇股を配し、上層は尾垂木付三手先を組み、間斗束をおく。柱間の逓減、階高の調整により安定感のある姿形をもち、細部には近代社寺建築の特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012205"},{"id":"00012207","register_sub_id":"101","register_pk":"353007","name":"今宮神社楼門西廻廊","kana":"いまみやじんじゃろうもんにしかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045118,"lng":135.742069,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-555","desc":"楼門の西にやや間をあけて東西棟で建つ。桁行三間梁間一間、切妻造本瓦葺である。正背面に連子窓、両妻に板唐戸をたて、中備の間斗束に舟肘木を載せる。隅柱を延ばし、二軒の軒や妻の破風に強い反りをもたせる。中世以前の意匠、技法を援用した良質な廻廊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012207"},{"id":"00012206","register_sub_id":"101","register_pk":"353006","name":"今宮神社楼門東廻廊","kana":"いまみやじんじゃろうもんひがしかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04514,"lng":135.742334,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-554","desc":"楼門の東にやや間をあけて東西棟で建つ。桁行三間梁間一間、切妻造本瓦葺である。正背面に連子窓、両妻に板唐戸をたて、中備の間斗束に舟肘木を載せる。妻飾は虹梁上に蟇股、大斗、出三斗を組み、細部彫刻に中世以前の意匠を援用した良質な廻廊。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012206"},{"id":"00012191","register_sub_id":"101","register_pk":"352991","name":"今宮神社若宮社拝殿","kana":"いまみやじんじゃわかみやしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045491,"lng":135.741928,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.8㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-539","desc":"本殿の東正面に南北棟で建つ。方一間、入母屋造銅板葺で周囲に切目縁を廻らす。四本柱に長押を廻らせ、柱上に舟肘木をおき格天井を張り、軒は小舞付の一軒疎垂木で、妻飾は木連格子である。本社拝殿同様に舞殿形式の拝殿で元禄再興期の境内の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012191"},{"id":"00012190","register_sub_id":"101","register_pk":"352990","name":"今宮神社若宮社本殿","kana":"いまみやじんじゃわかみやしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.045486,"lng":135.741816,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-538","desc":"境内中ほどの西寄りに東面する三間社。春日造屋根を左右に並べ、棟をエ字形に繋ぐ独特な屋根形式をもつ。正側面に榑縁を廻らせて脇障子をたて、身舎正面各間に板唐戸をたてる。庇は総桁行を一間とし虹梁形の桁で軒を受ける。特異な形式と優美な意匠の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012190"},{"id":"00012192","register_sub_id":"101","register_pk":"352992","name":"今宮神社若宮社門・透塀","kana":"いまみやじんじゃわかみやしゃもん・すきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区紫野今宮町21","lat":35.04545175,"lng":135.74181863,"geo_status":"db","era":"元禄7年(1694)","year":1694,"year_source":"db","year_min":1694,"year_max":1694,"year_label":null,"structure":"門 木造、瓦葺、間口1.8m 透塀 木造、瓦葺、総延長26m","structure_material":"門 木造","registered":"2018.03.27(平成30.03.27)","register_no":"26-540","desc":"本殿正面に開く門と、その両側から本殿を囲繞する透塀で切石積基礎に建つ。門は腕木門、切妻造で、猿頭付の段葺の屋根を目板瓦葺とする。透塀は柱に長押を廻らし、吹寄菱格子をいれ、腰を土壁、屋根は目板瓦葺とする。若宮の神域を画す丁寧なつくりの門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012192"},{"id":"00010002","register_sub_id":"101","register_pk":"196149","name":"宇良神社拝殿及び中殿","kana":"うらじんじゃはいでんおよびちゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府与謝郡伊根町字本庄浜191","lat":35.72889127,"lng":135.25783768,"geo_status":"db","era":"明治17／昭和中期改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積93㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0458","desc":"本殿正面に建ち、後方に中殿を張出す。広い柱間による桁行三間梁間二間の規模で、周囲を開放して高欄を廻らす。割拝殿形式をとり、側廻りを出組詰組とし、琵琶板の波紋や動植物、正面中央間の雲龍など要所を優秀な彫刻で飾る。明治期における中井権次の力作。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010002"},{"id":"00010001","register_sub_id":"101","register_pk":"196148","name":"宇良神社本殿","kana":"うらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府与謝郡伊根町字本庄浜191","lat":35.72878867,"lng":135.25781989,"geo_status":"db","era":"明治17","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、茅葺、建築面積26㎡、井戸屋形付","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0457","desc":"境内奥に北面する建ちの高い茅葺本殿で、棟に千木と堅魚木を戴く。桁行三間梁間二間で周囲に縁を廻らし、正面中央に板唐戸を両折に吊る。主体部は直線的かつ簡素な意匠とし、縁の北東隅に取付く井戸屋形のみ彫刻を施す。丹後地方に分布する神明造系本殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010001"},{"id":"00009996","register_sub_id":"101","register_pk":"196143","name":"大本みろく殿","kana":"おおもとみろくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府綾部市本宮町本宮下1","lat":35.2960669,"lng":135.26127307,"geo_status":"db","era":"昭和28／昭和60改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"鉄骨造及び木造平屋建一部地階付、銅板葺、建築面積1950㎡","structure_material":"鉄骨造及び木造平屋建一部地階付","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0452","desc":"桁行五〇メートルを超す大建築で、入母屋造妻入とし裳階を廻らす。西面に間口一〇メートルの入母屋玄関を構え、背面に張出す大神殿周りも入母屋屋根を重層させる。主構造は鉄骨造だが木材で化粧して木造に見せ、広大な広間に格天井を張る。壮大な規模の神殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009996"},{"id":"00016678","register_sub_id":"101","register_pk":"579162","name":"海眼寺観音堂","kana":"かいげんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府福知山市字寺38","lat":35.30491,"lng":135.122015,"geo_status":"db","era":"明治10年／昭和10年移築、令和6年改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0743","desc":"市街地北方の臨済宗寺院の観音堂。入母屋造妻入桟瓦葺で三方に縁を廻らし、正面向拝は虹梁形頭貫上に獅子と牡丹の彫刻を飾る。軸部は円柱、台輪上に外部三斗、内部出組を詰組に配す。内部格天井は中央の鏡天井に龍を描く。小規模ながら丁寧なつくりの仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016678"},{"id":"00016679","register_sub_id":"101","register_pk":"579163","name":"海眼寺山門","kana":"かいげんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府福知山市字寺38","lat":35.305193,"lng":135.12206,"geo_status":"db","era":"嘉永6年（1853）","year":1853,"year_source":"db","year_min":1853,"year_max":1853,"year_label":null,"structure":"木造2階建、瓦葺、建築面積6.0㎡","structure_material":"木造2階建","registered":"2026.07.09(令和8.07.09)","register_no":"26 - 0744","desc":"通りに北面して建つ鐘楼門。切妻造桟瓦葺、一間一戸の楼門。下層は角柱、正面に虹梁形頭貫を架け、上層は円柱、台輪に大斗肘木を載せ、軒は一軒繁垂木。桁行三間の中央間に火灯窓を開け、高欄付縁を廻らす。木鼻や絵様など時代相を示し、境内の正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016679"},{"id":"00015477","register_sub_id":"101","register_pk":"533492","name":"興正寺阿弥陀堂","kana":"こうしょうじあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.99014167,"lng":135.75211111,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積399㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0692","desc":"御影堂の北隣に東面して建つ阿弥陀堂。二重、入母屋造本瓦葺で正面に三間向拝を付す。各層は禅宗様の尾垂木付き三手先斗栱で丸桁を受け、軒は下層を二軒繁垂木、上層を二軒扇垂木とする。全体に禅宗様を基調とし、御影堂とともに両堂形式で復興した近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015477"},{"id":"00015483","register_sub_id":"101","register_pk":"533498","name":"興正寺阿弥陀堂門","kana":"こうしょうじあみだどうもん","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.99016389,"lng":135.75271389,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、間口4.5m、袖塀付","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0698","desc":"阿弥陀堂の正面、堀川通りに東面して建つ四脚門。切妻造本瓦葺で両脇に袖塀を付す。総ケヤキ造で、柱上に三斗を組み、虹梁上の蟇股で棟木を支持し、軒は二軒繁垂木とする。本柱上部の正面側に施した龍など要所を精巧な彫刻で飾り、風格ある表構えをつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015483"},{"id":"00015479","register_sub_id":"101","register_pk":"533494","name":"興正寺経蔵","kana":"こうしょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.9903,"lng":135.75262222,"geo_status":"db","era":"嘉永元年（1848）","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積43㎡、輪蔵付","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0694","desc":"境内北東部に位置し、高欄付基壇上に南面して建つ経蔵。正面三間、側面四間、宝形造本瓦葺で正面に軒唐破風を飾り、唐破風造向拝を付す。下層外壁は漆喰塗で向拝まで塗込め、頂部に漆喰彫刻を廻らし内部土間中央に輪蔵を配す。楼造風の独特な意匠を持つ経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015479"},{"id":"00015476","register_sub_id":"101","register_pk":"533491","name":"興正寺御影堂","kana":"こうしょうじごえいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.98975,"lng":135.75211667,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1，123㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0691","desc":"七条堀川の北西に位置する浄土真宗興正寺派の本山寺院の御影堂。境内中央に東面して建つ入母屋造本瓦葺で正面に3間向拝を付す。内陣及び余間の柱や壁面は金箔押、組物及び欄間は極彩色とし、荘厳を極める。明治35年大火後に復興した、大規模な近代の仏殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015476"},{"id":"00015482","register_sub_id":"101","register_pk":"533497","name":"興正寺三門","kana":"こうしょうじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98981111,"lng":135.75271389,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建、瓦葺、建築面積50㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0697","desc":"御影堂の正面、堀川通りに東面して建つ入母屋造本瓦葺、三間三戸の楼門。柱は円柱で組物は三手先、隅は四手先、軒は二軒扇垂木。腰組を付し高欄付縁を廻らす。一階中央間の両脇羽目板を精緻な牡丹唐草彫刻で埋尽くし、本山寺院の正面を飾る軒反り雄大な三門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015482"},{"id":"00015480","register_sub_id":"101","register_pk":"533495","name":"興正寺鐘楼","kana":"こうしょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98951389,"lng":135.75267778,"geo_status":"db","era":"安永3年（1774）","year":1774,"year_source":"db","year_min":1774,"year_max":1774,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0695","desc":"境内南東部に位置する鐘楼。基壇上に北面して建つ桁行3間、梁間２間、入母屋造本瓦葺で腰組を廻らし四周に袴腰を付す。組物は三手先で隅のみ四手先、軒は二軒扇垂木で禅宗様、中備は蟇股や蓑束の和様とする折衷様式。明治大火を免れた境内最古の貴重な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015480"},{"id":"00015478","register_sub_id":"101","register_pk":"533493","name":"興正寺高廊下","kana":"こうしょうじたかろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69","lat":34.98997222,"lng":135.75213889,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0693","desc":"御影堂と阿弥陀堂の間を繋ぐ唐破風造本瓦葺の渡廊下。軸部は几帳面取の角柱を頭貫で固め、大斗肘木上に桁を通し、梁中央の笈形付き大瓶束で棟木を受ける。床には長尺の板を張り天井は輪垂木の化粧軒裏天井。細部意匠も優れた廊下で本山寺院の格式を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015478"},{"id":"00015481","register_sub_id":"101","register_pk":"533496","name":"興正寺手水屋形","kana":"こうしょうじちょうずやがた","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98988611,"lng":135.75239722,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、瓦葺、面積7.8㎡、手水鉢付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0696","desc":"御影堂の北東に建つ手水屋形。入母屋造本瓦葺の東西棟で、四方転びの柱を頭貫で固め、台輪上に三斗を組み、軒は二軒繁垂木。中備は龍の彫刻付蟇股。内部は石敷床の中央に手水鉢を配し、上部は格天井を張る。小規模ながら良質なつくりで境内を構成する手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015481"},{"id":"00015484","register_sub_id":"101","register_pk":"533499","name":"興正寺東面北側築地塀","kana":"こうしょうじとうめんきたがわついじへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.99028333,"lng":135.75273333,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長24m","structure_material":"土塀","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0699","desc":"境内北方の東面を画し、阿弥陀堂門の両脇に延びる本瓦葺の塀。切石積基礎に一間毎に立てた柱を桁で繋ぎ、梁先で軒桁を支持する。軒は二軒繁垂木。外側は漆喰塗仕上とし、定規筋五本を付す。阿弥陀堂門に連なり、堀川通沿いに重厚な境内景観をつくる築地塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015484"},{"id":"00015485","register_sub_id":"101","register_pk":"533500","name":"興正寺東面南側築地塀","kana":"こうしょうじとうめんみなみがわついじへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市下京区醒ケ井通北小路下る花園町69他","lat":34.98963056,"lng":135.75276389,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土塀、瓦葺、延長45m","structure_material":"土塀","registered":"2025.08.06(令和7.08.06)","register_no":"26 - 0700","desc":"三門の南袖塀から矩折れして南へ延びる本瓦葺の塀。切石積基礎上に一間毎に柱を立てて桁で繋ぎ、梁先で軒桁を支持する。軒は二軒疎垂木。外側は漆喰塗仕上とし、定規筋五本を付す。境内東面を画す一連の築地塀で、堀川通沿いに風格ある寺院の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015485"},{"id":"00010641","register_sub_id":"101","register_pk":"201215","name":"金戒光明寺大方丈","kana":"こんかいこうみょうじおおほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019655,"lng":135.788019,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積581㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0474","desc":"御影堂の東北方に南面して建ち、桁行一三間梁間一一間で、入母屋造桟瓦葺屋根を架ける。六室からなる方丈形式で、正面に広縁、両側と背面に畳縁、外周に切目縁を廻す。各部の比例が優れた上質かつ雄大な書院造で、蟻壁の横連子や天井等の細部も精緻である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010641"},{"id":"00010643","register_sub_id":"101","register_pk":"201217","name":"金戒光明寺唐門","kana":"こんかいこうみょうじからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019397,"lng":135.787997,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、銅板葺、面積7.3㎡","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0476","desc":"大方丈の南正面、上面四半敷とした切石積基壇に建つ。四脚門形式で、丸柱と面取角柱を長押と頭貫で固め、屋根は向唐破風造の銅板葺、軒は二軒疎垂木で木舞打とする。扉と壁にある繊細な吹寄菱欄間、濃密な絵様繰形細部など、昭和初期の造形が凝縮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010643"},{"id":"00010642","register_sub_id":"101","register_pk":"201216","name":"金戒光明寺玄関","kana":"こんかいこうみょうじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019534,"lng":135.788212,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0475","desc":"大方丈東側にあり、寺務所と接続する。南北棟の入母屋造桟瓦葺の妻入で、正面中央に唐破風造銅板葺の車寄を設ける。六室からなる縦長の平面で、背面に幅広廊下を配する。板敷の応接室と書院造の座敷の対比、和風意匠に加味された洋風細部など、見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010642"},{"id":"00010644","register_sub_id":"101","register_pk":"201218","name":"金戒光明寺築地塀","kana":"こんかいこうみょうじついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019405,"lng":135.787959,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"土塀、瓦葺、総延長57m","structure_material":"土塀","registered":"2015.08.04(平成27.08.04)","register_no":"26－0477","desc":"唐門から矩折れで延び、西側は大方丈南西隅に、東側は玄関の南西隅にそれぞれ至り、大方丈の南庭を区画する。切石積基壇に建ち、壁面に定規線五本を入れ、一間毎に太い柱を立てて腕木で桁を出し、本瓦葺屋根を受ける。格調高い境内空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010644"},{"id":"00010640","register_sub_id":"101","register_pk":"201214","name":"金戒光明寺御影堂","kana":"こんかいこうみょうじみえいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区黒谷町121","lat":35.019555,"lng":135.787555,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積706㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0473","desc":"桁行七間梁間七間、正面に三間向拝を設け、雄大な入母屋造本瓦葺の屋根を架け、ほぼ南面して建つ。横長の外陣と縦長の内陣及び両脇陣からなる平面で、和様が基調の軸部に、尾垂木付二手先組物をあげ、洗練された細部をもち、本山格に相応しい堂姿を呈する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010640"},{"id":"00010000","register_sub_id":"101","register_pk":"196147","name":"雙栗神社石鳥居","kana":"さぐりじんじゃいしとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.87562901,"lng":135.75464,"geo_status":"db","era":"元禄15","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"石造、高さ6.5m、幅5.5m","structure_material":"石造","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0456","desc":"境内西端に位置する。花崗岩を用いた石造明神鳥居で、柱間五・五メートル、高さ六・五メートルを測る大型の石鳥居である。近辺の中小社の遺構としては古例であり、規模においては最大級である。古社の入口を荘厳するのにふさわしい雄大さを持ち合わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010000"},{"id":"00009999","register_sub_id":"101","register_pk":"196146","name":"雙栗神社玉垣","kana":"さぐりじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.87624068,"lng":135.75748668,"geo_status":"db","era":"江戸後期／昭和36改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、総延長44m","structure_material":"木造","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0455","desc":"本殿門両側から、本殿左右に矩折れにのび、東方は南面三間東面八間、西方は南面三間西面八間を数える。南面と東西面の前方五間は角連子の透塀、後方六間は尖頭形の板を並べた透塀とし、二種の形式を併用させて変化をつける。本殿廻りの神域を画す玉垣。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009999"},{"id":"00009997","register_sub_id":"101","register_pk":"196144","name":"雙栗神社拝殿","kana":"さぐりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.8760703,"lng":135.75756561,"geo_status":"db","era":"天明5","year":1785,"year_source":"db","year_min":1785,"year_max":1785,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0453","desc":"桁行三間梁間二間で中央間を馬道とし、左右に広い板間を設ける。天井が高く、開放的な印象を与える。組物は舟肘木で、中央間の楣上部に蟇股をおき、軒は一軒疎垂木とする。割拝殿形式でありながら、板間の外回り三方を壁にしており、類例の少ない形式である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009997"},{"id":"00009998","register_sub_id":"101","register_pk":"196145","name":"雙栗神社本殿門","kana":"さぐりじんじゃほんでんもん","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町佐山双栗55","lat":34.87616544,"lng":135.75756837,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、間口2.4m","structure_material":"木造平屋建","registered":"2014.04.25(平成26.04.25)","register_no":"26 － 0454","desc":"本殿と拝殿の中間に建つ。正面一間側面一間、切妻造妻入の一戸門で、左右に玉垣を廻らせる。柱は頂部粽付で、前列は几帳面取、後列は小面取とし、前面柱間に両開の格子戸を吊る。組物は出三斗で、虹梁や木鼻には極彩色を施し、多彩な装飾を華麗に施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009998"},{"id":"00011155","register_sub_id":"101","register_pk":"205262","name":"慈済院表門","kana":"じさいいんおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.015943,"lng":135.675516,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造、瓦葺、間口2.8m、東方潜戸付","structure_material":"木造","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0506","desc":"玄関廊式台のほぼ正面、天龍寺の総門から本山庫裏に至る参道に面して建つ。一間薬医門、切妻造本瓦葺で、本柱頂部を繋ぐ冠木を男梁と女梁で挟み、男梁上の板蟇股で棟木を受ける。軒は二軒疎垂木である。天龍寺最古級の表門であり塔頭の表構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011155"},{"id":"00011152","register_sub_id":"101","register_pk":"205259","name":"慈済院庫裏","kana":"じさいいんくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.016232,"lng":135.67557,"geo_status":"db","era":"寛政11","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積101㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0503","desc":"本堂東側に玄関廊を介して建つ。切妻造妻入の正面は、舟肘木で受ける妻梁上の中央に蟇股と虹梁大瓶束を組み、両脇に海老虹梁を飾る定型的な構成を見せ、絵様なども時代性をよく示す。平面はほぼ正方形で、東半を占める土間は大黒柱を中心に豪壮な梁組を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011152"},{"id":"00011153","register_sub_id":"101","register_pk":"205260","name":"慈済院玄関廊","kana":"じさいいんげんかんろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.016208,"lng":135.675472,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0504","desc":"本堂と庫裏の間を繋ぐ両下造の建物。東半に玄関の間をおいて入母屋造の式台玄関を構え、西半の一〇畳では虹梁を三筋架けて板蟇股で化粧屋根を支持する特異な構成をもつ。玄関と廊下の機能を兼備する一方で本堂と庫裏を繋ぐ開放的な大廊下形式の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011153"},{"id":"00011154","register_sub_id":"101","register_pk":"205261","name":"慈済院書院","kana":"じさいいんしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.016416,"lng":135.675423,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積61㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0505","desc":"本堂北側に建ち、庭に面する北西面に切目縁を廻らせる。内部は八畳二室からなる書院を原型に、南西面に廻らせた広縁を取り込んで広い座敷としており、北東に床を備える。面皮柱など数寄屋意匠を摂取し、天龍寺で近世に遡る唯一の書院遺構として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011154"},{"id":"00011151","register_sub_id":"101","register_pk":"205258","name":"慈済院本堂","kana":"じさいいんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市右京区嵯峨天龍寺芒ノ馬場町66","lat":35.01623,"lng":135.675322,"geo_status":"db","era":"文化13","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積238㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"26 - 0502","desc":"天龍寺の旧三門の北に位置する塔頭の本堂。南面する六間取の方丈形式で、室中を含む前三室は境に竹の節を設け、三室通しの棹縁天井を張る。四面広縁や上間後室の西側に床と付書院を設ける形式などに、禅宗塔頭寺院本堂としての特色を示し、意匠も洗練される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011151"},{"id":"00006548","register_sub_id":"101","register_pk":"107531","name":"実相院客殿","kana":"じっそういんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市左京区岩倉上蔵町312","lat":35.079117,"lng":135.781509,"geo_status":"db","era":"享保6","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積362㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0264","desc":"承秋門院御所の一部を移築，間取を変更したものと伝える。複雑な平面に入母屋造，桟瓦葺の屋根を架け，車寄の軒は唐破風につくる。造作は丁寧で，上段の間から続く滝の間と波の間は能舞台にも用い，床を拭板張とし，意匠及び造作に優れたつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006548"},{"id":"00006549","register_sub_id":"101","register_pk":"107532","name":"実相院門","kana":"じっそういんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市左京区岩倉上蔵町312","lat":35.07898055,"lng":135.7818851,"geo_status":"db","era":"享保6","year":1721,"year_source":"db","year_min":1721,"year_max":1721,"year_label":null,"structure":"木造、瓦葺、間口5.1m、左右袖塀付","structure_material":"木造","registered":"2007.07.31(平成19.07.31)","register_no":"26 － 0265","desc":"客殿とともに承秋門院御所から移築したものと伝える。境内の表門として東面して建つ間口１７尺規模の四脚門である。蟇股上の斗と実肘木で棟木を受ける。二軒疎垂木，木舞下地の化粧小屋で軽快なつくり。屋根は本瓦葺である。両脇に本瓦葺の築地塀が取り付く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006549"},{"id":"00011982","register_sub_id":"101","register_pk":"211117","name":"上善寺観音堂","kana":"じょうぜんじかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.038254,"lng":135.763365,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-528","desc":"境内南東隅に西面して建つ。正面三間、側面三間、宝形造本瓦葺で一間向拝を付ける。側廻りは格子や舞良戸をたて、飛貫を虹梁形とする。内部は一室だが、後寄りに立てる円柱に虹梁を渡して結界とし、奥に仏壇を設ける。六地蔵の一所としての由緒を伝える仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011982"},{"id":"00011983","register_sub_id":"101","register_pk":"211118","name":"上善寺山門","kana":"じょうぜんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.038113,"lng":135.763194,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積7.5㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-529","desc":"境内南端に南面して構える、間口三・六メートルの一間薬医門、切妻造本瓦葺である。太い五平の本柱に冠木を渡して梁を四筋架け、本柱位置は梁下に女梁を組み、梁上に蟇股を載せ、内寄りの梁には蓑束を立てて実肘木と拳鼻を付す。重厚で装飾も豊かな山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011983"},{"id":"00011981","register_sub_id":"101","register_pk":"211116","name":"上善寺書院","kana":"じょうぜんじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.0387,"lng":135.763102,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積170㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-527","desc":"本堂の北東方に渡り廊下を介して建つ、寄棟造、桟瓦葺。平面は六間取の方丈形式で周囲に廊下を廻らす。中列後室を広い内陣として格天井を張り、上手となる西列は後室に座敷飾を備える。各室に長押を廻らし、室境に筬欄間を入れるなど、端正な意匠の書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011981"},{"id":"00011980","register_sub_id":"101","register_pk":"211115","name":"上善寺本堂","kana":"じょうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区鞍馬口通寺町東入北側上善寺門前町482","lat":35.038466,"lng":135.762971,"geo_status":"db","era":"文化9年(1812)","year":1812,"year_source":"db","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"26-526","desc":"境内中央に南面し、桁行五間、梁間六間、入母屋造本瓦葺で三間向拝を付け、縁を廻らす。内部は内陣と脇陣、外陣による浄土宗本堂の標準平面をもつ。側廻りは角柱に舟肘木をのせ、内陣周囲は円柱に三斗を組む。須弥壇廻りの意匠充実し、内部架構も見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011980"},{"id":"00014187","register_sub_id":"101","register_pk":"508817","name":"青蓮院青龍殿（旧大日本武徳会京都支部武徳殿）","kana":"しょうれんいんせいりゅうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市山科区厨子奥花鳥町28他","lat":35.00225556,"lng":135.78741667,"geo_status":"db","era":"大正2年／平成26年移築","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積537㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"26-0646","desc":"武道施設を東山の山上へ移築、護摩堂の外陣としたもの。中央の道場板間の上は高く吹き抜いて高窓を設け、切妻屋根の正背面に千鳥破風を飾る。道場周囲の観覧席は裳階下で、正面入口上は軒唐破風とする。移築時の改造も最小限で、保存良好な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014187"},{"id":"00013749","register_sub_id":"101","register_pk":"505305","name":"神光院客殿","kana":"じんこういんきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06032778,"lng":135.74362222,"geo_status":"db","era":"文政9年(1826)","year":1826,"year_source":"db","year_min":1826,"year_max":1826,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積188㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 629","desc":"本堂東方に南面して建ち渡廊下で繋ぐ。桟瓦葺で、南面中央に入母屋造の式台玄関が突出する。平面は三行三列の九室の周囲に縁を廻らせ、上手となる西列は最奥を上段として床と棚を備え、中列奥に院主の間、下手東列に仏間等を配する。上質なつくりの接客施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013749"},{"id":"00013751","register_sub_id":"101","register_pk":"505309","name":"神光院山門","kana":"じんこういんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.05998611,"lng":135.74366944,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 631","desc":"境内南辺中央に東西棟で建つ。一間薬医門、切妻造本瓦葺。五平の太い本柱頂部に女梁を組み、厚めの冠木を渡し、男梁上に撥形の束を立てて棟木を受ける。軒は一軒で木小舞打の疎垂木とし、破風拝みに梅鉢懸魚を飾る。意匠質実ながら風格を備えた古刹の正門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013751"},{"id":"00013748","register_sub_id":"101","register_pk":"505303","name":"神光院中興堂","kana":"じんこういんちゅうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06055278,"lng":135.74324444,"geo_status":"db","era":"大正6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積121㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 628","desc":"本堂北西側に南面して建つ。正面三間奥行四間、宝形造の主体部正面に入母屋造屋根を付け、さらに張出して唐破風の向拝を構える等複雑な外観を呈す。主体部は畳敷の外陣と両脇陣の後方を板間の内陣とする。円形垂木の軒や屋根構成に創意が認められる近代仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013748"},{"id":"00013747","register_sub_id":"101","register_pk":"505301","name":"神光院本堂","kana":"じんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06035556,"lng":135.74335278,"geo_status":"db","era":"文政12年(1829)","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 627","desc":"境内の中程に南面する。桁行三間梁間四間、入母屋造銅板葺で正面に向拝を付す。角柱を立て組物は平三斗。内部は前一間を外陣、後三間を内陣として桁行一杯の仏壇を作る。内外陣境に結界は設けず正面全面に半蔀を建てる。江戸後期の中規模本堂の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013747"},{"id":"00013750","register_sub_id":"101","register_pk":"505307","name":"神光院蓮月庵","kana":"じんこういんれんげつあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市北区西賀茂神光院町120","lat":35.06001667,"lng":135.74345,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"26 － 630","desc":"本堂前方、山門脇に南北棟で建つ。大田垣蓮月の寓居。切妻造桟瓦葺で南に下屋を張出し東・北面の土間入口に庇を廻らせる。内部は北東隅を土間、西側の三畳に不動明王を祀る。南半は玄関や台所を配す。煤竹詰打の天井や円窓など、数寄屋意匠を加味した小庵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013750"},{"id":"00000448","register_sub_id":"101","register_pk":"101438","name":"大覚寺心経殿","kana":"だいかくじしんきょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区嵯峨大沢町4-1","lat":35.02864224,"lng":135.67860758,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"鉄筋コンクリート造平屋建，銅板葺，建築面積31㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"26 － 0012","desc":"奉納された般若心経の写経を納めるための建物。木造の八角円堂を鉄筋コンクリートで模したもので，軒や縁の意匠等に素材の特性がいかされている。設計は昭和初期を代表する住宅建築家藤井厚二。藤井の住宅以外の珍しい作品として価値がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000448"},{"id":"00008504","register_sub_id":"101","register_pk":"134900","name":"大聖寺表門","kana":"だいしょうじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03067893,"lng":135.7591623,"geo_status":"db","era":"江戸後期／大正11年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、間口3.5m","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0356","desc":"境内の東南角に位置する。間口三・五メートルと大型の一間一戸薬医門、切妻造本瓦葺。男梁を三通りに架け、本柱に女梁を挿し、斗を介して男梁を受ける。中備は妻が蟇股、中央が大瓶束。一軒疎垂木。尼門跡筆頭格の寺格にふさわしい堂々とした構えになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008504"},{"id":"00008503","register_sub_id":"101","register_pk":"134899","name":"大聖寺玄関","kana":"だいしょうじげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03102702,"lng":135.75905567,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0355","desc":"宮御殿東に位置する。桁行一五メートル梁間五・三メートル、入母屋造桟瓦葺。東面に唐破風造銅板葺の大きな車寄せを突出。南から応接室、玄関、内玄関、納戸を並べ、背面に廊下を通す。伝統的な和風建築ながら、自動車等の利便を配慮するなど近代性を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008503"},{"id":"00008501","register_sub_id":"101","register_pk":"134897","name":"大聖寺残月亭","kana":"だいしょうじざんげつてい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.0310195,"lng":135.75853176,"geo_status":"db","era":"昭和13年","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積75㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0353","desc":"宮御殿の西、渡り廊下を介して続く。Ｌ字型の入母屋造で、東と南に妻を見せる。トコや棚を構える四畳半台目の茶室を中央に、その南にトコと付書院を並べる六畳間、東に位牌の間や水屋を配する。質の良い材料で、丁寧に施工された近代茶室の佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008501"},{"id":"00008505","register_sub_id":"101","register_pk":"134901","name":"大聖寺高塀","kana":"だいしょうじたかへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03081507,"lng":135.75908264,"geo_status":"db","era":"昭和17年頃","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造、瓦葺、延長36m","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0357","desc":"表門から玄関への通路と境内前庭を区切る高塀。玄関東南隅から南へ三六メートル延び、南面築地塀に至り、途中に通用口を二ヶ所穿つ。礎石上、土台を置き、方柱をたて、腕木を出し、軒桁を支持し、塀瓦を葺く。壁は漆喰仕上げ。簡素ながら厳粛な雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008505"},{"id":"00008506","register_sub_id":"101","register_pk":"134902","name":"大聖寺東面築地","kana":"だいしょうじとうめんついじ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03097939,"lng":135.75923867,"geo_status":"db","era":"大正11年頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"土塀、瓦葺、延長59m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0358","desc":"境内東辺、烏丸通沿いに位置する築地塀で、表門から北側に折れ曲がり五九メートル延びる。北寄りに通用門を設ける。本瓦を葺き、通り側に白線五線を入れる。通用門は正・背面に瓦庇を架け、引違い戸と片開戸の潜りを設ける。賑やかな烏丸通に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008506"},{"id":"00008507","register_sub_id":"101","register_pk":"134903","name":"大聖寺南面築地","kana":"だいしょうじなんめんついじ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03063042,"lng":135.75891529,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土塀、瓦葺、延長66m","structure_material":"土塀","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0359","desc":"境内南辺、小路沿いに設けられた築地塀。表門から西側隣地境まで延び、総延長六六メートルを測る。本瓦葺とし、小路側には白線五線を入れる。西寄りに間口一・八メートルの門口を穿ち、両開戸をたて、不浄の門とする。重厚な構えで、近世尼門跡の風格を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008507"},{"id":"00008499","register_sub_id":"101","register_pk":"134895","name":"大聖寺本堂","kana":"だいしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03078888,"lng":135.75900805,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積134㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0351","desc":"境内東南寄りに西面して建つ。入母屋造桟瓦葺。六間取方丈形式、正面に広縁、正・側面に高欄付切目縁を巡らす。方柱で舟肘木とし、一軒疎垂木、妻木連格子。後列南室を貴人の間とし、花鳥を描く大トコを構える。伝統的な形式のなか、品格のある設えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008499"},{"id":"00008500","register_sub_id":"101","register_pk":"134896","name":"大聖寺宮御殿","kana":"だいしょうじみやごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03094931,"lng":135.75873481,"geo_status":"db","era":"江戸後期／文政8年（1825）頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積322㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0352","desc":"境内中央に南面して建つ。入母屋造の西棟と東に続く切妻造の東棟からなる。東棟は前後列各四室からなり、数寄屋風意匠になる。西棟はトコや違棚を構える主室ほか四室を田の字型に配し、周囲に畳縁を設ける。近世における尼門跡寺院の御殿の形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008500"},{"id":"00008502","register_sub_id":"101","register_pk":"134898","name":"大聖寺渡り廊下","kana":"だいしょうじわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市上京区烏丸通上立売下る御所八幡町109-1","lat":35.03090419,"lng":135.75900554,"geo_status":"db","era":"昭和17年","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"26 － 0354","desc":"本堂と玄関を繋ぐ。桁行一二メートル梁間三・八メートル、両下造桟瓦葺。複廊になり、東側は内向きの通路で板張、西側は畳敷、両端部近くに襖や杉戸をたてて間仕切る。天井はいずれも棹縁天井。中間に防火壁を設けるなど近代的な要素も見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008502"},{"id":"00007068","register_sub_id":"101","register_pk":"108050","name":"建勲神社大鳥居","kana":"たけいさおじんじゃおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03850662,"lng":135.74462352,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造、高さ7.2m、幅5.5m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0290","desc":"船岡山山麓、船岡東通に東面して建つ。木造の明神鳥居で、幅５．５ｍ高さ７．２ｍに及ぶ。礎石上に円柱を建て、貫と嶋木、笠木で固める。材は台湾阿里山産の檜で、素木のままとする。大規模で、笠木も大きく反り、神域の荘厳な結界を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007068"},{"id":"00007066","register_sub_id":"101","register_pk":"108048","name":"建勲神社貴賓館","kana":"たけいさおじんじゃきひんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.038555,"lng":135.744156,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0288","desc":"拝殿の東方に位置する。南北棟の入母屋造桟瓦葺で、緩やかな起りになる切妻造桟瓦葺の車寄を西面して付ける。桁行３間半梁間４間半で、南・東・西３方に跳高欄付切目縁をまわす。洛北から東山を望む、瀟洒な近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007066"},{"id":"00007064","register_sub_id":"101","register_pk":"108046","name":"建勲神社祭器庫","kana":"たけいさおじんじゃさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.0387239,"lng":135.743774,"geo_status":"db","era":"明治13／昭和4移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積32㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0286","desc":"拝殿の東北方に位置する。南面する土蔵造２階建で、入母屋造本瓦葺の置屋根とする。地盤高の関係で２階に出入口を設け、１間庇を付ける。外壁は漆喰仕上げ。庇は桟瓦葺で、柱型を表し、塗り込める。側・背面に庇付窓を設け、外観を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007064"},{"id":"00007067","register_sub_id":"101","register_pk":"108049","name":"建勲神社社務所","kana":"たけいさおじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.038662,"lng":135.744003,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積77㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0289","desc":"貴賓館の西北に南面して建ち、廊下などを介して繋がる。入母屋造桟瓦葺で、玄関正面にこけら葺庇を付ける。中央東寄りの玄関土間を挟んで、東に旧宿直室、西に事務室、その西に旧宮司室を設ける。内法が高く、その上に小振りな屋根が載り、軽快な外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007067"},{"id":"00007063","register_sub_id":"101","register_pk":"108045","name":"建勲神社神饌所","kana":"たけいさおじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03855338,"lng":135.7432219,"geo_status":"db","era":"明治17／明治43移築","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積52㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0285","desc":"本殿透塀の南方に、東西棟で本殿に正面を向ける。桁行５間梁間３間規模の入母屋造檜皮葺。内部は桁行に３室に分け、東に土間と台所、中央に板間、西に８畳間を配する。天井はいずれも棹縁天井。入口土間に両開妻戸、縁に面して舞良戸をたてる。神饌所の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007063"},{"id":"00007062","register_sub_id":"101","register_pk":"108044","name":"建勲神社透塀","kana":"たけいさおじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03869716,"lng":135.74312943,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、延長55m","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0284","desc":"本殿四周を囲む塀で、正面で祝詞舎両脇に付く。切石布基礎上に土台を載せ、方柱をたて、腰長押や内法長押で固め、腕木で桁を支持する。軒は疎垂木で、屋根桟瓦葺。柱間は腰板壁で菱格子、小壁にたすきを入れる。本殿まわりの空間を画し、森厳な雰囲気をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007062"},{"id":"00007065","register_sub_id":"101","register_pk":"108047","name":"建勲神社手水舎","kana":"たけいさおじんじゃちょうずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03854628,"lng":135.74369966,"geo_status":"db","era":"明治13／大正11移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造、檜皮葺、面積4.2㎡","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0287","desc":"拝殿の東南方に所在する。桁行１間梁間１間、東西棟の切妻造檜皮葺で、緩い勾配とする。礎石上に方柱をたて、内法貫で固め、舟肘木を介し、虹梁や桁を支持。豕叉首を組み、軒は一軒疎垂木。周囲に菱格子欄間を置く。化粧屋根裏天井で、中央に石製水盤を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007065"},{"id":"00007060","register_sub_id":"101","register_pk":"108042","name":"建勲神社祝詞舎","kana":"たけいさおじんじゃのりとしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03865396,"lng":135.74337735,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積7.1㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0282","desc":"本殿の前方に位置する。桁行１間梁間１間で、前寄り柱筋に両開戸をたてる。切妻造妻入檜皮葺。円柱で、柱上に舟肘木を置き、内法貫や虹梁、桁で固める。梁行中備に蟇股を置き、妻は豕叉首。緩い起り屋根に、一軒疎垂木とし、穏やかな表情を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007060"},{"id":"00007059","register_sub_id":"101","register_pk":"108041","name":"建勲神社拝殿","kana":"たけいさおじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03863734,"lng":135.74346929,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0281","desc":"本殿の東方に位置する吹放ちの拝殿。桁行２間梁間３間で、四周に切目縁をまわす。入母屋造妻入檜皮葺で、妻を木連格子とする。面取方柱で、柱上に舟肘木を置き、軒は二軒疎垂木。拭板敷で、折上小組格天井を張る。軒反の大きい優美な外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007059"},{"id":"00007058","register_sub_id":"101","register_pk":"108040","name":"建勲神社本殿","kana":"たけいさおじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03868652,"lng":135.7431831,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.1㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0280","desc":"船岡山山頂に東面して建つ１間社流造の本殿。四周に組高欄付縁をまわし、正面に木階、浜床、浜縁を付ける。身舎は円柱、向拝は面取方柱。組物は舟肘木で、妻は豕叉首。二軒繁垂木とし、打越垂木を疎垂木とする。簡明な意匠になる近代本殿の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007058"},{"id":"00007061","register_sub_id":"101","register_pk":"108043","name":"建勲神社渡廊","kana":"たけいさおじんじゃわたろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市北区紫野北舟岡町49","lat":35.03867,"lng":135.74328521,"geo_status":"db","era":"明治13／明治43移築","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"26 － 0283","desc":"本殿と祝詞舎を繋ぐ。桁行２間梁間１間で、切妻造妻入銅板葺。方柱上に舟肘木を載せ、梁及び桁を架し、梁中央に撥束を立て、舟肘木を介して棟木を支持する。床は中央通りを石敷とし、天井は一軒疎垂木の化粧屋根裏とする。簡易な構造で、軽快な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007061"},{"id":"00012216","register_sub_id":"101","register_pk":"353016","name":"玉田神社一の鳥居","kana":"たまたじんじゃいちのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町中島向野12-2","lat":34.894776,"lng":135.736631,"geo_status":"db","era":"文化年間（1804-1817）","year":1810,"year_source":"estimated","year_min":1804,"year_max":1817,"year_label":"文化年間（1804-1817）","structure":"石造、間口3.7m、高さ4.3m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"26-564","desc":"境内の北西方に建つ石造明神鳥居。間口三・七メートル、高さ四・三メートル。内転びの柱に貫を通し、その中央には額束を立て、柱上に一体で造られた島木と笠木を載せる。笠木は端部において反りをもつ。地域の歴史的景観を良好に形成する鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012216"},{"id":"00012217","register_sub_id":"101","register_pk":"353017","name":"玉田神社二の鳥居","kana":"たまたじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町森宮西地内","lat":34.892336,"lng":135.737257,"geo_status":"db","era":"享保年間（1716-1735）／文化年間（1804-1817）移築","year":1726,"year_source":"estimated","year_min":1716,"year_max":1735,"year_label":"享保年間（1716-1735）","structure":"石造、間口3.4m、高さ4.1m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"26-565","desc":"境内の南面を東西に走る祭礼道の入口に建つ石造明神鳥居。間口三・四メートル、高さ四・一メートルで、一の鳥居と同形式であるが、規模が小さく柱径が太いため、安定感のある造形をみせており、時代の古さが感じられる。地域の歴史を今に伝える鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012217"},{"id":"00012214","register_sub_id":"101","register_pk":"353014","name":"玉田神社本殿","kana":"たまたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町森宮東1","lat":34.8932,"lng":135.739256,"geo_status":"db","era":"寛永元年(1624)／文化2年(1805)改修","year":1624,"year_source":"db","year_min":1624,"year_max":1624,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-562","desc":"田園地帯の台地に境内を構える。本殿は南面し、寛永元年の八間社を文化二年に縮小し四間社流造、向拝一間とした。柱や桁など軸部に寛永材が残り、実肘木に江戸初期の特徴を示す。蟇股や手挟、脇障子の彫刻は文化材で花鳥、唐獅子など華やかな細部意匠で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012214"},{"id":"00012215","register_sub_id":"101","register_pk":"353015","name":"玉田神社末社市杵社","kana":"たまたじんじゃまっしゃいちきしゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府久世郡久御山町森宮東1","lat":34.893102,"lng":135.739367,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"26-563","desc":"本殿の南東の覆屋内に西面して建つ。一間社流造、こけら葺で、正側面に縁を廻らして脇障子をたて、正面に木階五級、浜床、浜縁を設ける。組物は三斗、中備は蟇股で側面板壁と共に彩色の痕跡をよく残る。妻飾は虹梁豕叉首組で、小社ながら整った意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012215"},{"id":"00008143","register_sub_id":"101","register_pk":"132584","name":"自玉手祭来酒解神社本殿","kana":"たまてよりまつりきたるさかとけじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字天王山3-1","lat":34.90168074,"lng":135.67869656,"geo_status":"db","era":"文政3年（1820）","year":1820,"year_source":"db","year_min":1820,"year_max":1820,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"26 － 0344","desc":"天王山山頂東側の平坦部に鎮座する大型社殿。五間社流造、檜皮葺で、銅板仮葺とする。身舎は四周に縁をめぐらし、脇障子を建てる。庇部分は身舎より一段低く、三方に菱格子戸をたてて前室とする。欄間や蟇股の彫刻は、枠面から横溢させて雄壮に彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008143"},{"id":"00014049","register_sub_id":"101","register_pk":"508309","name":"知恩院阿弥陀堂","kana":"ちおいんあみだどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区新橋通大和大路東入三丁目林下町442","lat":35.005175,"lng":135.78263333,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0641","desc":"中心伽藍の南西、御影堂の西に東面して建つ仏堂。入母屋造本瓦葺で裳階に向拝三間がつく。内陣の南北が脇間で東を外陣とする。須弥壇はやや低く像高のある阿弥陀如来坐像を納める。設計木子清敬、棟梁市田重郎兵衛。近世の伝統を引く近代仏堂の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014049"},{"id":"00014050","register_sub_id":"101","register_pk":"508310","name":"知恩院阿弥陀堂渡廊下","kana":"ちおいんあみだどうわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区新橋通大和大路東入三丁目林下町442","lat":35.00533333,"lng":135.78279722,"geo_status":"db","era":"明治43年／昭和40年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0642","desc":"国宝御影堂の西縁から西へ延び、南へ折れて阿弥陀堂北縁に取付く。本瓦葺の屋根は照り起りで両端を唐破風に造る。柱間は吹放ち、御影堂縁に合わせて高く床を張り、東から四間目は境内通路のため更に床を切り上げる。壮大な堂宇の間を繋ぐ荘重な渡廊下である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014050"},{"id":"00014051","register_sub_id":"101","register_pk":"508311","name":"知恩院納骨堂","kana":"ちおいんのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市東山区新橋通大和大路東入三丁目林下町442","lat":35.00455,"lng":135.78404167,"geo_status":"db","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"26 - 0643","desc":"御影堂南東の高台に建つ方一間の裳階付である。屋根は宝形造の本瓦葺とする。壇上積基壇に建ち、四手先で軽快な軒を受ける。内部は四半瓦敷で、螺鈿細工の須弥壇を据え、内部彩色は紙上に施す。設計は阪谷良之進。古典理解に基づく造形は近代仏堂の佳品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014051"},{"id":"00014863","register_sub_id":"101","register_pk":"519123","name":"東福寺恩賜門","kana":"とうふくじおんしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.976825,"lng":135.77408056,"geo_status":"db","era":"明治42年","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造、檜皮葺、間口3.9m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0663","desc":"昭憲皇太后恩賜による一間一戸檜皮葺の唐門。設計は亀岡末吉。礎盤に円柱を立て貫で固めて三斗を組み、軒は一軒繁垂木。中備は蟇股とし、虹梁上に大瓶束を置き、大斗肘木で棟木を支持。菊紋付扉を吊り、欄間、蟇股、虹梁上など繊細な透彫で飾る華麗な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014863"},{"id":"00014864","register_sub_id":"101","register_pk":"519124","name":"東福寺唐門","kana":"とうふくじからもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97699444,"lng":135.77379167,"geo_status":"db","era":"明治23年／明治42年頃増築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造、瓦葺、間口4.2m、歩廊付","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0664","desc":"方丈の西に開く一間一戸本瓦葺の唐門。方丈との間に落棟で唐破風屋根の歩廊が取付く。門は礎石上に円柱を立て三斗を組み、中備は蟇股を模した龍の彫刻で飾り、梁上に笈形付大瓶束を配す。門口に桟唐戸を開く。全体に装飾少なく簡素ながら整った意匠の唐門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014864"},{"id":"00014862","register_sub_id":"101","register_pk":"519122","name":"東福寺庫裏","kana":"とうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97672778,"lng":135.77441389,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積559㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0662","desc":"方丈南東に位置する切妻造桟瓦葺。西に唐破風造銅板葺の式台玄関、南に起り付き切妻造桟瓦葺の脇玄関を付す。内部は方形の平面中央に、式台玄関、脇玄関及び北東の座敷に至る板敷床の中廊下を通す。大規模な切妻造屋根の庫裏が伽藍中枢の雄大な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014862"},{"id":"00014869","register_sub_id":"101","register_pk":"519129","name":"東福寺通霄門","kana":"とうふくじつうしょうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97665,"lng":135.77364167,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造及び木造、瓦葺、間口4.6m","structure_material":"鉄筋コンクリート造及び木造","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0669","desc":"通天橋と本堂の間の南寄りに開く切妻造本瓦葺の門。四隅の角柱と頭貫を鉄筋コンクリート造とし、頭貫から上部を木造とする混構造。組物は三斗を組み、虹梁上の大瓶束に蟇股風の笈形を付す。軒は一軒繁垂木。南歩廊と一体となり、雄大な伽藍景観をつくる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014869"},{"id":"00014866","register_sub_id":"101","register_pk":"519126","name":"東福寺通天橋","kana":"とうふくじつうてんきょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97729167,"lng":135.77366944,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造及び木造平屋建、瓦葺、建築面積99㎡","structure_material":"鉄筋コンクリート造及び木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0666","desc":"稲荷山から流れる三ノ川に架かる橋。鉄筋コンクリート造橋脚を懸造状に構築し、上部を木造切妻造本瓦葺の歩廊とする。西面中央を突出させて、西方の景色を望む視点場とし、飛貫上には優美な蟇股を飾る。木柄の細い列柱が、谷を渡る歩廊の軽快さを演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014866"},{"id":"00014867","register_sub_id":"101","register_pk":"519127","name":"東福寺通天橋北歩廊","kana":"とうふくじつうてんきょうきたほろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97763333,"lng":135.77369722,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積176㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0667","desc":"通天橋とその北東高台にある塔頭常楽庵を結ぶ登廊。梁間一間切妻造本瓦葺及び桟瓦葺で、北東に向かって２箇所で折曲がり、地形に沿って屋根に傾斜をつける。柱頂部に直接梁を架けた簡明な構造で、傾斜を軽快に登る列柱が、境内に立体感ある景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014867"},{"id":"00014868","register_sub_id":"101","register_pk":"519128","name":"東福寺通天橋南歩廊","kana":"とうふくじつうてんきょうみなみほろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97689167,"lng":135.77365833,"geo_status":"db","era":"明治44年／昭和38年改修","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0668","desc":"通天橋と本堂を結び、直線状に延びる歩廊。梁間一間の切妻造本瓦葺で、通霄門を挟んで本堂基壇に接続し、西面北寄りで唐門まで突出する。腰貫を通した円柱上に直接梁を架け、束で棟木を支えた簡明な構造。長大な歩廊の列柱が、壮大な伽藍の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014868"},{"id":"00014861","register_sub_id":"101","register_pk":"519121","name":"東福寺通天台","kana":"とうふくじつうてんだい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97721389,"lng":135.77395,"geo_status":"db","era":"昭和36年頃","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0661","desc":"方丈の北西に位置し、通天橋を眺める展望台。桁行３間梁間１間、平屋建切妻造桟瓦葺。土台に立てた円柱の頂部に直接梁を架け、貫で軸部を固める。床は板敷とし、上部は化粧屋根裏、柱間は吹放ち、腰に高欄を嵌める。小規模ながら方丈北西の姿を印象付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014861"},{"id":"00014860","register_sub_id":"101","register_pk":"519120","name":"東福寺方丈","kana":"とうふくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97704167,"lng":135.77410833,"geo_status":"db","era":"明治23年／明治43年頃増築","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積624㎡、廊下付","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0660","desc":"本堂の北に位置する桁行16間梁間９間入母屋造本瓦葺。六間取りで南と東に吹放ちの広縁、西に入側縁を付し、四周に高欄付濡縁を廻らし、南西に廊下附属。室中は桁行7間梁間4間半と広大で、北西は床を備えた御所の間。規模雄大で上質な明治期屈指の方丈。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014860"},{"id":"00014865","register_sub_id":"101","register_pk":"519125","name":"東福寺方丈築地塀","kana":"とうふくじほうじょうついじべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97683611,"lng":135.77385556,"geo_status":"db","era":"明治42年頃","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"土塀、瓦葺、総延長78m","structure_material":"土塀","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0665","desc":"方丈の西と南を囲い、西面の唐門と南面の恩賜門に取り付く、折れ曲がり総延長78メートルの築地塀。切石積基礎に柱を一間毎に立て、本瓦葺とする。外壁は鼠色漆喰塗で五条の定規筋を白漆喰塗、内壁は白漆喰塗とする。方丈の外周を廻り、伽藍景観を整える塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014865"},{"id":"00014859","register_sub_id":"101","register_pk":"519119","name":"東福寺本堂","kana":"とうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市東山区本町十五丁目778","lat":34.97633889,"lng":135.77380556,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積809㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"26 - 0659","desc":"東山に位置する臨済宗東福寺派大本山寺院の本堂。壇上積基壇に建つ桁行五間梁間三間、一重入母屋造本瓦葺裳階付。組物は本屋三手先、裳階出組、軒はいずれも二軒扇垂木。内部四半敷土間は天井高く張り、北寄り中央に須弥壇を配す。規模壮大な近代屈指の仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014859"},{"id":"00001397","register_sub_id":"101","register_pk":"102387","name":"日本聖公会京都聖三一教会","kana":"にほんせいこうかいきょうとせいさんいちきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区聚楽廻中町45-1","lat":35.017673,"lng":135.740875,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、瓦葺、建築面積182㎡","structure_material":"木造2階建","registered":"1999.10.14(平成11.10.14)","register_no":"26 － 0049","desc":"階下を幼稚園，階上を礼拝堂に充てる。基礎を煉瓦，階下を縦板貼りとした和風真壁造的なハーフティンバースタイルの教会建築で，礼拝堂は幾何学的曲線を用いた軽快なトラス小屋組を持つ。設計はバーガミニー。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001397"},{"id":"00009039","register_sub_id":"101","register_pk":"162399","name":"仁和寺大玄関","kana":"にんなじおおげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02852919,"lng":135.71317256,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺一部檜皮葺、建築面積127㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0381","desc":"御殿群南端に東面して建つ。桁行12メートル梁間7.0メートル、入母屋造桟瓦葺で、東正面に間口6.0メートル近い大きな唐破風造檜皮葺の車寄を構える。細部では蟇股や大瓶束の笈形に秀麗な彫刻を施すなど、威厳と華やかさを備えた大型の玄関である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009039"},{"id":"00009041","register_sub_id":"101","register_pk":"162401","name":"仁和寺黒書院","kana":"にんなじくろしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.0290146,"lng":135.7128909,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0383","desc":"宸殿西側に南面して並び建ち、桁行15.5メートル梁間11.7メートル、入母屋造桟瓦葺で、宸殿と白書院の双方と、檜皮葺屋根の渡廊下で繋ぐ。平面は方丈型六間取で、西奥室に座敷飾を備える。周囲に舞良戸を建て、内向きの書院らしく落着いた外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009041"},{"id":"00009044","register_sub_id":"101","register_pk":"162404","name":"仁和寺皇族門","kana":"にんなじこうぞくもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.0285981,"lng":135.71337332,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、檜皮葺、間口2.7m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0386","desc":"大玄関から東にのびる塀の中間に構える門で、四脚平唐門、檜皮葺である。本柱は円柱、控え柱は角柱で、男梁上の蟇股と舟肘木で棟木を受け、軒は大疎垂木とし、桟唐戸の上に透彫欄間を入れる。御殿群の前庭と内庭を仕切る、木割の細い、繊細な姿の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009044"},{"id":"00009040","register_sub_id":"101","register_pk":"162400","name":"仁和寺白書院","kana":"にんなじしろしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02878388,"lng":135.71306769,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0382","desc":"宸殿と大玄関の間に東面して建ち、桁行一15.8メートル梁間12.5メートル、入母屋造桟瓦葺である。表と裏に三室ずつ配る六室構成で、正面広縁を吹放しとする。表側の室境は竹の節欄間とし座敷にトコと棚を設える。旧宸殿としての格調を備える書院である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009040"},{"id":"00009038","register_sub_id":"101","register_pk":"162398","name":"仁和寺宸殿","kana":"にんなじしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02898164,"lng":135.71317855,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積257㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0380","desc":"境内南西の御殿群中央に建つ。桁行19.7メートル梁間11.8メートル、入母屋造檜皮葺である。寝殿造の外観、書院造の内部構成を組み合わせ、東側に中門廊風の突出を設ける。内外とも門跡寺院に相応しい優雅な意匠で、亀岡末吉の代表作のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009038"},{"id":"00009043","register_sub_id":"101","register_pk":"162403","name":"仁和寺勅使門","kana":"にんなじちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02871496,"lng":135.71354112,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、檜皮葺、間口5.2m、左右袖塀付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0385","desc":"白書院正面に東面して建ち、四脚門、前後唐破風造側面入母屋、檜皮葺である。本願寺唐門を模した形式をもち、壁面や桟唐戸などを、花菱や鳳凰、唐草などを図案化した流麗な透彫りで埋め尽くす。亀岡末吉の意匠感覚が発揮された見応えのある大型の門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009043"},{"id":"00009045","register_sub_id":"101","register_pk":"162405","name":"仁和寺霊宝館","kana":"にんなじれいほうかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.0292693,"lng":135.71435914,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積376㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0387","desc":"境内のほぼ中央に建ち、鉄筋コンクリート造二階建、建築面積376平方メートル、桟瓦葺である。平面はロの字形で、南面中央に切妻造のポーチを突出させる。外壁は校倉造を模した構成で、垂木や虹梁も現すなど、コンクリートによる和風表現の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009045"},{"id":"00009042","register_sub_id":"101","register_pk":"162402","name":"仁和寺霊明殿","kana":"にんなじれいめいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市右京区御室大内33-1","lat":35.02928728,"lng":135.71301375,"geo_status":"db","era":"明治44年","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積53㎡、渡り廊下付","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"26 － 0384","desc":"黒書院の北側に渡り廊下を介して南面して建ち、方三間、宝形造、一間向拝付、檜皮葺である。内部は一室で三間幅の仏壇を設け、折上小組格天井を張る。平安後期頃の様式を意識した構成としつつ、蟇股には亀岡末吉の得意とした唐草を図案化した彫刻を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009042"},{"id":"00015320","register_sub_id":"101","register_pk":"532444","name":"乃木神社記念館","kana":"のぎじんじゃきねんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93298611,"lng":135.77643333,"geo_status":"db","era":"大正5年頃／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石造平屋建、茅葺（鉄板仮葺）、建築面積82㎡","structure_material":"石造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0681","desc":"境内北東に位置し、乃木希典が満州で司令部に用いた家屋を再現したと伝わる記念館。西面して建つ石造切妻造平入茅葺（鉄板仮葺）で、戸口や窓廻りを煉瓦積、正面外壁を漆喰塗仕上。中央に玄関ホール、北と南に部屋を配す。境内に独特な存在感を示す記念館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015320"},{"id":"00015322","register_sub_id":"101","register_pk":"532446","name":"乃木神社神門及び袖塀","kana":"のぎじんじゃしんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93308333,"lng":135.77592222,"geo_status":"db","era":"大正5年／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"神門 木造、銅板葺、間口5.5m 袖塀 木造、瓦葺、総延長27m","structure_material":"神門 木造","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0683","desc":"境内北西の入口に建つ四脚門と両脇の塀。設計は設樂貞雄。神門は入母屋造平入銅板葺。組物は実肘木付平三斗、軒は二軒繁垂木とし、門口に板扉を開く。塀は本瓦葺で外壁漆喰塗とし、腰は簓子下見板張。軒反り強く雄大な門で、塀とともに境内の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015322"},{"id":"00015319","register_sub_id":"101","register_pk":"532443","name":"乃木神社拝殿","kana":"のぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93248889,"lng":135.776425,"geo_status":"db","era":"大正5年／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0680","desc":"本殿の北に位置する拝殿。設計は設樂貞雄。桁行3間梁間2間入母屋造平入銅板葺。組物は舟肘木、軒は二軒疎垂木。内部は一室の板敷で格天井を張る。正背面中央間の板扉以外は蔀戸で四周に刎高欄付縁を廻らす開放的なつくり。本殿とともに境内景観の要をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015319"},{"id":"00015321","register_sub_id":"101","register_pk":"532445","name":"乃木神社宝物館","kana":"のぎじんじゃほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93316944,"lng":135.77638889,"geo_status":"db","era":"大正5年頃","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0682","desc":"境内北東に位置する乃木夫妻の遺品展示施設。基壇上に西面して建つ、土蔵造２階建切妻造平入本瓦葺。外壁は漆喰塗仕上で、一階は海鼠壁仕上。二階には乃木夫妻の祠を配し、二重虹梁上に撥束を立てるなど特徴的な小屋組。外観重厚で境内景観を構成する宝物館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015321"},{"id":"00015318","register_sub_id":"101","register_pk":"532442","name":"乃木神社本殿","kana":"のぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府京都市伏見区桃山町板倉周防37-1他","lat":34.93225556,"lng":135.77648889,"geo_status":"db","era":"大正5年／昭和中期改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2025.03.13(令和7.03.13)","register_no":"26 - 0679","desc":"桃山御陵の南に位置し、乃木希典と妻を祀る神社の本殿。設計は設樂貞雄。境内南辺に北面して建つ桁行三間梁間三間、入母屋造妻入銅板葺で一間向拝付き。三方に縁を廻らし、脇障子を建てる。向拝中備は蟇股上に二つの斗を配す。基壇上に建つ堂々たる姿の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015318"},{"id":"00002929","register_sub_id":"101","register_pk":"103919","name":"平安神宮内廻廊","kana":"へいあんじんぐううちかいろう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.01665983,"lng":135.78271494,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積88㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0119","desc":"昭和１５年の一連の造営時に建てられた。西側と東側に分かれ，内拝殿と北東及び北西歩廊をつなぎ，大極殿背後の空間を区画している。基壇上にあって，１間幅の外側を連子窓を設けた壁とし，内側は円柱を建て，屋根は緩やかな反りをもたせている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002929"},{"id":"00002939","register_sub_id":"101","register_pk":"103929","name":"平安神宮大鳥居","kana":"へいあんじんぐうおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎成勝寺町・岡崎円勝寺町","lat":35.01255205,"lng":135.78268762,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"鉄筋コンクリート造一部鉄骨造、高さ24m、幅18m","structure_material":"鉄筋コンクリート造一部鉄骨造","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0129","desc":"昭和天皇大礼を記念して建てられた。設計は京都府技師の阪谷良之進。構造は鉄筋コンクリート及び鉄骨造、形式は明神鳥居で、幅18ｍ、高24ｍになり、当時国内最大であった。柱が太いプロポーションが特徴で、洛東岡崎のシンボルとして広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002939"},{"id":"00002932","register_sub_id":"101","register_pk":"103922","name":"平安神宮額殿","kana":"へいあんじんぐうがくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01581375,"lng":135.78189755,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0122","desc":"南内庭西側に位置する。規模，構造形式は神楽殿と同一とするが，内部は四半敷の総土間とする。東，南，北の３面は中央に板唐戸，両脇に蔀戸を立て，西面で廻廊に接続する。参拝者の休憩や講演などを目的とした建物で，境内景観上欠くことができない。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002932"},{"id":"00002931","register_sub_id":"101","register_pk":"103921","name":"平安神宮神楽殿","kana":"へいあんじんぐうかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01582604,"lng":135.78300004,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積272㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0121","desc":"南内庭東側に位置し，東外廻廊と東側で接続する。基壇を設けて桁行８間，梁間４間の丸柱を建て，南，西，北の３面１間通りを吹き放しとする。屋根は入母屋造，本瓦葺。神楽の奉奏とともに結婚式等を行う場として建てられたもので，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002931"},{"id":"00002936","register_sub_id":"101","register_pk":"103926","name":"平安神宮斎館","kana":"へいあんじんぐうさいかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.015709,"lng":135.783279,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積448㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0126","desc":"東外廻廊の外側に位置する。木造平屋建，瓦葺一部銅板葺，建築面積４４８㎡。廻廊内の丹塗の建物群とは趣を異にするが，床・棚を備え折上小組格天井とする旧供進使室など内外ともに質が高く，唐破風造の玄関を備えるなど，近代和風建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002936"},{"id":"00002935","register_sub_id":"101","register_pk":"103925","name":"平安神宮神門翼廊","kana":"へいあんじんぐうしんもんよくろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01542679,"lng":135.78277227,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積300㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0125","desc":"神門（応天門）両脇から東西に延び，それぞれ梁間２間，桁行４間の南北棟につながる。神門脇には扉口を開き，１間おいて両外側は畳敷きの室内とする。木部は破風板等も含めて丹塗とし，屋根は本瓦葺。境内の正面側景観を形つくる要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002935"},{"id":"00002926","register_sub_id":"101","register_pk":"103916","name":"平安神宮透塀及び後門","kana":"へいあんじんぐうすきべいおよびこうもん","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.017067,"lng":135.78244,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造透塀、銅板葺、折曲り延長90m、及び棟門、間口3.0m","structure_material":"木造透塀","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0116","desc":"昭和１５年，孝明天皇合祀時に行われた一連の造営の一つ。これらの設計は内務省神社局技師であった角南隆と谷重雄である。一間棟門の後門を中心に左右に透塀を延ばし，当初は総延長で１１４ｍに達していた。本殿の背後を区切る建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002926"},{"id":"00002938","register_sub_id":"101","register_pk":"103928","name":"平安神宮西祭器庫","kana":"へいあんじんぐうにしさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01569852,"lng":135.78132441,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0128","desc":"東祭器庫の西側に並ぶ。東祭器庫に倣って造られたもので，ほぼ同様の規模，形式，意匠を持つが，外壁腰部など細部意匠が異なる。内部は二階建とし，小屋はトラス組になる。軒部は漆喰で塗り上げており，腰部は海鼠壁風の目地を切るなど特徴的な土蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002938"},{"id":"00002928","register_sub_id":"101","register_pk":"103918","name":"平安神宮西神庫","kana":"へいあんじんぐうにしじんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.01700573,"lng":135.78221652,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造校倉、銅板葺、建築面積13㎡","structure_material":"木造校倉","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0118","desc":"東神庫と対をなす神庫。本殿の背後，透塀内の西北隅に位置し，形式・規模・意匠ともに東神庫と厳密な対称型をなす。正面には両開き板扉を設け，軒は一軒疎垂木である。比較的小規模ではあるが，校倉建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002928"},{"id":"00002934","register_sub_id":"101","register_pk":"103924","name":"平安神宮西門及び西外廻廊","kana":"へいあんじんぐうにしもんおよびにしかいろう","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01535155,"lng":135.78175344,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0124","desc":"昭和１５年の一連の造営時に建設されたもの。南歩廊から神門翼廊までを矩折れに結び，中程には章善門とも称する西門を開く。東門・東外廻廊と完全な対称型をなし，両者で龍尾壇下の南内庭を区画する。広大な境内空間の街路側に位置し，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002934"},{"id":"00002937","register_sub_id":"101","register_pk":"103927","name":"平安神宮東祭器庫","kana":"へいあんじんぐうひがしさいきこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01571752,"lng":135.78146434,"geo_status":"db","era":"明治40／昭和15移築","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0127","desc":"西外廻廊の西に位置する土蔵造２階建の祭器庫。正面入口には切妻造瓦葺の屋根をかけ，寄棟造の小屋はトラスを組む。外壁は腰部を板張りとする特徴的な外観である。昭和１５年の一連の造営時に，旧位置から移築されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002937"},{"id":"00002927","register_sub_id":"101","register_pk":"103917","name":"平安神宮東神庫","kana":"へいあんじんぐうひがしじんこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎入江町121","lat":35.01701841,"lng":135.78265727,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造校倉、銅板葺、建築面積13㎡","structure_material":"木造校倉","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0117","desc":"本殿の背後，透塀内の東北隅に位置し，１２尺（約３．６ｍ）四方の妻入正方形平面を持つ。屋根は切妻造，銅板葺で，正面には縁を設け，その左側に石階及び木階を備える。その殆どが丹塗の境内にあって，白木の外観が特徴的な校倉である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002927"},{"id":"00002933","register_sub_id":"101","register_pk":"103923","name":"平安神宮東門及び東外廻廊","kana":"へいあんじんぐうひがしもんおよびひがしそとかいろう","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.01540213,"lng":135.78317174,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0123","desc":"南歩廊から神門翼廊までを矩折れに結び，南内庭の東側を区切る。中程には宣政門とも称する東門を開く。門は切妻造，本瓦葺，二軒半繁垂木の切妻造。廻廊は単廊式で本瓦葺，総延長約５０ｍに達する。丹塗と緑の連子窓の組合せが，境内景観を特徴付けている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002933"},{"id":"00002930","register_sub_id":"101","register_pk":"103920","name":"平安神宮南歩廊","kana":"へいあんじんぐうみなみほろう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府京都市左京区岡崎西天王町97","lat":35.0162031,"lng":135.78316988,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積288㎡","structure_material":"木造平屋建","registered":"2002.08.21(平成14.08.21)","register_no":"26 － 0120","desc":"Ｌ字型平面で蒼龍楼と東外廻廊，白虎楼と西外廻廊を結ぶ歩廊。２間幅で，中央を連子窓を設けた壁で区切る。二軒の丸垂木で，屋根は本瓦葺。左右とも東西棟部中央に扉口を開く。形式・規模ともに本殿廻りの塀とは明確に区別され，境内景観を形作っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002930"},{"id":"00009783","register_sub_id":"101","register_pk":"195612","name":"本能寺表門","kana":"ほんのうじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市中京区寺町通御池下る下本能寺前町522-1","lat":35.01037836,"lng":135.76732415,"geo_status":"db","era":"明治4／明治12移築","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造、瓦葺、間口4.9m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0428","desc":"寺町通に西面して建つ大型の薬医門で、左右に袖塀を付ける。男梁を四本架け、両端二本に蟇股、中央二本に大瓶束を載せて棟木を受ける。軒は二軒疎垂木で、垂木上面に木小舞を並べる。ケヤキの良材を使い、細部意匠や施工も上質で、気品を備えた表門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009783"},{"id":"00009782","register_sub_id":"101","register_pk":"195611","name":"本能寺信長公御廟所拝殿","kana":"ほんのうじのぶながこうごびょうしょはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区寺町通御池下る下本能寺前町522-1他","lat":35.01012851,"lng":135.76853768,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0427","desc":"本堂の南東に位置する信長公廟所を拝するための建物。三間四方で、各面とも中央間を開放し、両脇間に腰板壁を張る。内法長押を廻らして柱上に舟肘木をのせ、小壁は漆喰仕上げで内部に格天井を張る。大仏様風の木鼻を用いるなど、復古的な要素を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009782"},{"id":"00009781","register_sub_id":"101","register_pk":"195610","name":"本能寺本堂","kana":"ほんのうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府京都市中京区寺町通御池下る下本能寺前町522-1他","lat":35.01032482,"lng":135.76830568,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積590㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0426","desc":"寺町通に向けて境内を開く。本堂は七間四方で、内陣を五間四間と広くとるなど日蓮宗系寺院本堂の標準的平面を示す。広い内陣を確保するため、側柱を立て登らせ、トラスを併用して大スパンを実現する。細部は古典に忠実で、天沼俊一の設計として初期の大型仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009781"},{"id":"00010656","register_sub_id":"101","register_pk":"201230","name":"向日神社客殿","kana":"むこうじんじゃきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市向日町南山82-1","lat":34.943787,"lng":135.697433,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0489","desc":"境内の南寄りに東面して建つ。Ｔ字形平面で屋根を入母屋造とする主体部の東正面に切妻の車寄を付ける。玄関の西奥に座敷を並べて奥の八畳に床と平書院を備え、南に廊下を通す。車寄に筬欄間を廻らし、格天井を張るなど、端正な意匠で気品のある近代和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010656"},{"id":"00010657","register_sub_id":"101","register_pk":"201231","name":"向日神社手水舎","kana":"むこうじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944221,"lng":135.697882,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積4.0㎡、手水鉢・井戸付","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0490","desc":"境内の東寄り、参道北方に南面して建つ。桁行を正面一間背面二間、梁間を一間とし、東面と北面のみを腰貫で固めて使用の便を図る。全体に簡素な意匠としながら、正面の虹梁形飛貫や蟇股を雲紋化した彫刻として華やかに飾り、境内の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010657"},{"id":"00010645","register_sub_id":"101","register_pk":"201219","name":"向日神社幣拝殿及び本殿覆屋","kana":"むこうじんじゃへいはいでんおよびほんでんおおいや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944179,"lng":135.697169,"geo_status":"db","era":"天保13年（1842）","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積277㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0478","desc":"三間社流造の本殿を納める覆屋は方五間で、流造のような形態とし、幣殿で入母屋造の拝殿と繋ぐ。桁行五間の拝殿は柱間が広く大規模で、正面に千鳥破風と向唐破風造の向拝を付す。本殿覆屋は比較的簡素だが、拝殿向拝廻りの雲龍等の彫刻は特に濃密で目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010645"},{"id":"00010650","register_sub_id":"101","register_pk":"201224","name":"向日神社末社春日神社本殿","kana":"むこうじんじゃまっしゃかすがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944295,"lng":135.697012,"geo_status":"db","era":"江戸後期／明治11年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、こけら葺、建築面積0.55㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0483","desc":"本殿北方、祖霊社西方の覆屋内に南面して建つ。近村にあった社を明治期に合祀したもの。小規模な一間社流造で、正面に軒唐破風を付ける。身舎及び庇の組物の肘木に繰形を付け、軒唐破風妻飾などに雲紋の彫刻を付けるなど、細部まで手の込んだ装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010650"},{"id":"00010655","register_sub_id":"101","register_pk":"201229","name":"向日神社末社勝山稲荷神社拝殿","kana":"むこうじんじゃまっしゃかつやまいなりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944398,"lng":135.698075,"geo_status":"db","era":"昭和前期／昭和42年頃移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0488","desc":"稲荷神社本殿の南正面に南面して建つ。間口三間の入母屋造に向拝一間を付ける。側面を二間とし、中央の柱に脇障子を設けて前方に縁を廻す。隅柱に大仏様木鼻を付し、向拝では虹梁絵様を袖切のみとし、蟇股を鎌倉時代風の意匠とするなど、復古的要素を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010655"},{"id":"00010654","register_sub_id":"101","register_pk":"201228","name":"向日神社末社勝山稲荷神社本殿","kana":"むこうじんじゃまっしゃかつやまいなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944437,"lng":135.698077,"geo_status":"db","era":"大正期／昭和42年頃移築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、銅板葺、建築面積3.3㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0487","desc":"境内の東寄り、参道北方に南面して建つ、正面一間背面二間の流造社殿。流造の通例と異なり身舎柱を角柱とし、柱上に舟肘木を置く。三方に刎高欄付の縁を廻し、正面に木階を設ける。庇は絵様付水引虹梁を架け、三斗を組み、装飾を加える。近代神社建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010654"},{"id":"00010649","register_sub_id":"101","register_pk":"201223","name":"向日神社末社五社神社本殿","kana":"むこうじんじゃまっしゃごしゃじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944248,"lng":135.697346,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0482","desc":"祖霊社の東方に南面して建つ。桁行三間梁間一間、切妻造で、正面中央間のみ広めて虹梁を架ける。正面は腰下を板壁、内法を菱格子、上部土壁とする。内部は背面寄りに片流屋根の内陣を設けて五室に間仕切り、板唐戸を吊り、繁垂木とする。独特な形式の境内社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010649"},{"id":"00010651","register_sub_id":"101","register_pk":"201225","name":"向日神社末社御霊神社本殿","kana":"むこうじんじゃまっしゃごりょうじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町南山82-1","lat":34.944048,"lng":135.69738,"geo_status":"db","era":"江戸中期／明治10年移築","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、こけら葺、建築面積2.3㎡、覆屋付","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0484","desc":"拝殿南方に北面して建ち、正面に虹梁をもつ覆屋を架ける。一間社流見世棚造で、見世棚左右に板壁を張る。屋根はこけら葺で、木製の箱棟と鬼板を飾る。組物は柱上の舟肘木のみの簡素な形式とする。見世棚造としては比較的規模が大きく、境内の景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010651"},{"id":"00010647","register_sub_id":"101","register_pk":"201221","name":"向日神社末社祖霊社本殿","kana":"むこうじんじゃまっしゃそれいしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944334,"lng":135.697155,"geo_status":"db","era":"元禄元年（1688）","year":1688,"year_source":"db","year_min":1688,"year_max":1688,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0480","desc":"拝殿北方に渡廊を介し、東面して建つ。もとは祈祷所として建立されたもので、桁行二間半梁間二間、入母屋造妻入である。組物を持たず簡素な意匠とし、外壁の白壁が目立つ瀟洒な建物で、内部の改修はあるものの、天保期の境内整備以前に遡る遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010647"},{"id":"00010648","register_sub_id":"101","register_pk":"201222","name":"向日神社末社祖霊社渡廊","kana":"むこうじんじゃまっしゃそれいしゃわたろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.94427,"lng":135.69716,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0481","desc":"本社拝殿と祖霊社本殿を南北に繋ぐ、長さ約一〇メートルの渡廊。南寄り約三メートルを落棟にし、北寄りは間柱を入れて柱上に舟肘木を据え、梁行の各柱間に虹梁を架けて蟇股で棟木を受ける。軸部はやや木太いが、太鼓状の床桁や反りのある垂木が軽快さを創る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010648"},{"id":"00010652","register_sub_id":"101","register_pk":"201226","name":"向日神社末社天満宮社本殿","kana":"むこうじんじゃまっしゃてんまんぐうしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944324,"lng":135.697769,"geo_status":"db","era":"天保4年（1833）","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"26－0485","desc":"境内の東寄り、参道北方に南面して建つ。切妻造の本体前面に切妻造妻入の向拝を併設する独特の構えとなる。後端間後寄りの内陣は腰高の床張として三室に仕切り、幣軸構の板唐戸を吊る。前面に刎高欄付の縁と木階を設け、こけら葺の屋根を架けて内殿風とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010652"},{"id":"00010653","register_sub_id":"101","register_pk":"201227","name":"向日神社末社天満宮社瑞垣","kana":"むこうじんじゃまっしゃてんまんぐうしゃみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944345,"lng":135.697768,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、総延長17m","structure_material":"木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0486","desc":"天満宮社本殿向拝の側面に取り付き、矩折れに後方へ延びる。基壇上の土台に立てる柱で直接棟木を受ける。腰下を竪板壁、内法は襷格子を入れ、瓦葺の屋根とする。挿肘木の腕木には大仏様の木鼻を付けるなど、簡素ながら装飾を持ち、社叢景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010653"},{"id":"00010646","register_sub_id":"101","register_pk":"201220","name":"向日神社南門・北門及び瑞垣","kana":"むこうじんじゃみなみもん・きたもんおよびみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府向日市向日町北山65","lat":34.944146,"lng":135.696969,"geo_status":"db","era":"天保13年（1842）","year":1842,"year_source":"db","year_min":1842,"year_max":1842,"year_label":null,"structure":"南門及び北門 木造、瓦葺、間口2.0m 瑞垣 木造、瓦葺、総延長52m","structure_material":"南門及び北門 木造","registered":"2015.08.04(平成27.08.04)","register_no":"26－0479","desc":"拝殿に接続して本殿覆屋の三方に瑞垣を廻らし、南北に門口を開く。瑞垣は瓦葺で腰下を竪板張、上部を菱格子とし、内側に石製の添柱を付す。南門と北門はいずれも棟門で絵様付の腕木を二段重ねる。華やかな植物紋の透彫を嵌めた桟唐戸を吊り、境内を荘厳する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010646"},{"id":"00014400","register_sub_id":"101","register_pk":"511389","name":"明覺寺山門","kana":"めいかくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99116944,"lng":135.75681389,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造、瓦葺、間口2.6m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0650","desc":"新町通に面する山門。五平の本柱と控柱を貫２段で繋いだ薬医門で、切妻造桟瓦葺。両妻は梁上においた板蟇股が棟木を受ける。軒は１軒疎垂木で破風拝みに懸魚を付ける。間口２・６メートルで、要所に金具を打つ板戸両開を吊る。市中の寺院の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014400"},{"id":"00014398","register_sub_id":"101","register_pk":"511387","name":"明覺寺茶室杏梁庵","kana":"めいかくじちゃしつきょうりょうあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99116944,"lng":135.75711389,"geo_status":"db","era":"大正9年／昭和初期移築","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0648","desc":"本堂の奥に位置。観月橋にあった本願寺門主の別邸三夜荘からの移築と伝わる四畳半の茶室と、隣接する四畳水屋からなる。切妻造桟瓦葺で南に土庇を付す。茶室は半間床で網代天井は北半間を一段落とす。南に躙口、西に貴人口を開ける。大谷光瑞ゆかりの茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014398"},{"id":"00014399","register_sub_id":"101","register_pk":"511388","name":"明覺寺土蔵","kana":"めいかくじどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99108611,"lng":135.75710278,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積14㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0649","desc":"本堂奥、茶室南脇に位置する。土蔵造２階建、切妻造本瓦葺。腰は竪板張、上部は漆喰塗で鉢巻まで塗込める。西に庇を付し、掛子塗の土戸両開の戸口を設け、内部は１・２階とも１室。小屋は和小屋で両妻の梁が中引梁を受ける。敷地南東の茶室露地の背景を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014399"},{"id":"00014397","register_sub_id":"101","register_pk":"511386","name":"明覺寺本堂","kana":"めいかくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"京都府","address":"京都府京都市下京区新町通正面下る平野町781他","lat":34.99114722,"lng":135.75699722,"geo_status":"db","era":"明治30年頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積146㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"26 - 0647","desc":"東本願寺の西に位置。桁行５間梁間７間切妻造桟瓦葺で入母屋造玄関を付す。１２畳２室の外陣と両脇に余間を配す内陣からなる変則的な平面。内陣に須弥壇を置く。左余間は襖絵を建込んだ上段の間で、次の間には杉戸絵を飾る。小規模だが格調高い設え持つ本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014397"},{"id":"00009794","register_sub_id":"101","register_pk":"195623","name":"離宮八幡宮高天宮神社","kana":"りきゅうはちまんぐうこうてんぐうじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89179554,"lng":135.67945754,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積4.7㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0439","desc":"境内西方に東面して建つ。三間社流造、銅板葺で、縁を廻らし、浜床を設け、妻を豕扠首とする。向拝中備は、拝殿同様に古式な蟇股を翻案した独自の意匠の蟇股を飾る。全体的に装飾を控え、復古的に簡素な意匠を見せることで格調のある趣きとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009794"},{"id":"00009797","register_sub_id":"101","register_pk":"195626","name":"離宮八幡宮透塀","kana":"りきゅうはちまんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89190833,"lng":135.67951037,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、延長38m、潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0442","desc":"本殿の側背面にコ字形に配された透塀で、側面六間、背面八間とし、前端は拝殿釣殿端部に取付く。基壇上に建ち、腰までを羽目板、腰長押と内法長押で軸を固め、菱格子をはめる。軒は疎垂木で、屋根は銅板葺とする。簡素な意匠ながら、格調高い結界装置である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009797"},{"id":"00009795","register_sub_id":"101","register_pk":"195624","name":"離宮八幡宮中門","kana":"りきゅうはちまんぐうちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89167419,"lng":135.6795789,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、銅板葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0440","desc":"拝殿正面に位置し、本殿、拝殿、中門を一直線に並べる。四脚門形式で左右に矩折に袖塀を付属する。本柱、控柱とも角柱で、両開の桟唐戸を吊る。軒は二軒で優美な反りをもたせる。妻に板蟇股を配し、正面蟇股には東福寺月下門の意匠を引用し、外観を引き立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009795"},{"id":"00009796","register_sub_id":"101","register_pk":"195625","name":"離宮八幡宮手水所","kana":"りきゅうはちまんぐうてみずしょ","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89155283,"lng":135.67953035,"geo_status":"db","era":"昭和3頃","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造、瓦葺、面積3.1㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0441","desc":"中門の南西に南北棟で建つ。切妻造桟瓦葺で、二本の丸柱の前後に控柱をたて、柱上に渡した男梁で桁を受け、屋根を支える。両妻には板蟇股をおいて棟木を受ける。懸魚や蟇股の意匠は境内の他の建物と共通し、復古的な意匠を持つ。洗練された境内景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009796"},{"id":"00009793","register_sub_id":"101","register_pk":"195622","name":"離宮八幡宮拝殿","kana":"りきゅうはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89176556,"lng":135.67954749,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0438","desc":"桁行三間梁間二間、入母屋造の主体部正面に唐破風造の向拝を付け、両側面後寄りに桁行二間の翼廊、背面中央に幣殿を設ける。柱上に舟肘木をおき、軒は二軒疎垂木とする。主体部は折上格天井を張り、ほかは化粧屋根裏である。木割が太く、復古的な設計法を採る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009793"},{"id":"00009792","register_sub_id":"101","register_pk":"195621","name":"離宮八幡宮本殿","kana":"りきゅうはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"京都府","address":"京都府乙訓郡大山崎町字大山崎小字西谷21-1","lat":34.89187121,"lng":135.67951608,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"26 － 0437","desc":"西国街道に面して境内を構える。本殿は、三間社流造、銅板葺で、三方に縁を廻らし、背面柱筋に脇障子をたてる。身舎は内外陣に二分し、内陣前面に板唐戸三所を開き、外陣正面を吹き放つ。蟇股や木鼻の細部を含め、全体を中世風の復古的な意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009792"},{"id":"00013136","register_sub_id":"101","register_pk":"368381","name":"蓮乗寺山門","kana":"れんじょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27935,"lng":135.512575,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.3m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0593","desc":"敷地南辺中央東寄りに南面して建つ。切妻造桟瓦葺の薬医門で、親柱に五平材を用いた正面側は簡素なつくりとする一方で、側面の梁上には大振りの絵様付蟇股を置き、控柱を絵様、木鼻付の虹梁状の飛貫を抜き通して蟇股で桁を支える。境内の表構を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013136"},{"id":"00013135","register_sub_id":"101","register_pk":"368380","name":"蓮乗寺鐘楼","kana":"れんじょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27933611,"lng":135.51262778,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積5.2㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0592","desc":"境内南東に北面して建つ。切妻造桟瓦葺、軒は一軒疎垂木とし、妻に懸魚を飾る。礎石の上に角柱を内転びで立て、二段に通した貫で固めて四周に腰板を張る。棟木下に湾曲した鐘釣梁を渡し、梵鐘を吊る。簡素ながら山門と並び立ち、境内の表構を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013135"},{"id":"00013134","register_sub_id":"101","register_pk":"368379","name":"蓮乗寺番神堂","kana":"れんじょうじばんじんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27938333,"lng":135.51246389,"geo_status":"db","era":"文政11年（1828）","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0591","desc":"境内南西に北面して建つ。入母屋造桟瓦葺、正側面に縁を廻し、正面一間向拝付。内部は外陣は棹縁天井の床畳敷で、内陣は側面化粧軒裏、中央一段高く棹縁天井とし、床板敷。内陣中央に来迎壁と須弥壇を置き、背後に五連の神棚を並べ、番神信仰の有様を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013134"},{"id":"00013133","register_sub_id":"101","register_pk":"368378","name":"蓮乗寺本堂","kana":"れんじょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"京都府","address":"京都府南丹市美山町大野庵ノ谷13","lat":35.27956667,"lng":135.51255833,"geo_status":"db","era":"寛政11年（1799）／昭和30年代・平成28年改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、茅葺（銅板仮葺）、建築面積249㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"26 － 0590","desc":"美山町西部にある日蓮宗寺院。敷地中央に南面して建つ入母屋造の本堂は、内部西を仏堂、東を庫裏とし、正面中央東寄に式台玄関を設ける。仏堂は六間取の方丈形式で、正面と西側に縁を廻す。奥側中央の仏間奥には位牌堂が突出する。境内景観の中核を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013133"},{"id":"00014409","register_sub_id":"101","register_pk":"511398","name":"天日名鳥命神社幣拝殿","kana":"あめのひなどりのみことじんじゃへいはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市大畑874","lat":35.48755278,"lng":134.11855278,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積28㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"31 - 0282","desc":"丘上の式内社の幣拝殿。入母屋造妻入桟瓦葺、正面に入母屋造起り破風の向拝を設け、妻飾懸魚を重ねる。向拝に格天井、縁を三方に廻し、内部一室、背面に切妻造の幣殿を張り出す。原寸図が遺る懸魚は本殿彫刻に比べて伝統的な意匠で、境内の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014409"},{"id":"00014408","register_sub_id":"101","register_pk":"511397","name":"天日名鳥命神社本殿","kana":"あめのひなどりのみことじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市大畑874","lat":35.48753611,"lng":134.11848333,"geo_status":"db","era":"大正2年","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"31 - 0281","desc":"鹿野城下から鳥取城下への道沿い丘上に所在する式内社。一間社流造銅板葺の床が高い本殿で、四方に縁を廻す。亀腹は石造。全体に装飾は抑制的だが、蟇股等彫刻意匠に近代的な華やかさがある。正面扉に神紋を付す。設計書を備え近代の社殿造営の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014408"},{"id":"00014927","register_sub_id":"101","register_pk":"519187","name":"宇倍神社神門","kana":"うべじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48080833,"lng":134.26900833,"geo_status":"db","era":"大正4年／昭和前期改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造、檜皮葺、間口3.0m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0286","desc":"拝殿の東に位置する切妻造檜皮葺の門。円柱の本柱と角柱の控柱を腰貫、内法貫で固め、組物は舟肘木、中備には菊紋の上半部を呈す彫刻を配す。豕扠首で棟木を支え、軒は一軒繁垂木。かつて紙幣の図柄となった門で優美な起り屋根が宇部神社の景観を特徴づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014927"},{"id":"00014926","register_sub_id":"101","register_pk":"519186","name":"宇倍神社透塀","kana":"うべじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48096111,"lng":134.2687,"geo_status":"db","era":"大正11年／昭和前期・同48年改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、銅板葺、延長61m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0285","desc":"幣殿両脇から後方に延びて本殿を囲う透塀。切石積基壇に土台を置いて柱を１間毎に立て、軒桁は腕木で支持し屋根銅板葺とする。各柱間には連子窓を入れ、腰は縦板目板張とし、正面両脇に出入口を設ける。本殿と一体となって境内の歴史的な景観をつくる透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014926"},{"id":"00014925","register_sub_id":"101","register_pk":"519185","name":"宇倍神社拝殿","kana":"うべじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48086667,"lng":134.26889722,"geo_status":"db","era":"明治17年／平成11年改修","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0284","desc":"本殿の東方に位置する拝殿は入母屋造妻入檜皮葺。正面に木階を付し、四周に高欄付縁を廻らす。組物は舟肘木とし、軒は二軒繁垂木、妻飾は木連格子。内部は一室の拭板敷で、格天井を張る。破風板など錺金具で荘厳する以外は全体に装飾抑えた端正な意匠の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014925"},{"id":"00014924","register_sub_id":"101","register_pk":"519184","name":"宇倍神社本殿","kana":"うべじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市国府町宮ノ下651","lat":35.48093056,"lng":134.26875833,"geo_status":"db","era":"明治31年／明治41年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0283","desc":"稲葉山南西麓に位置する因幡国一宮の本殿。東面する切妻造平入檜皮葺で正面1間背面3間、側面２間、向拝1間付。組物は舟肘木、妻飾は豕扠首、軒は二軒繁垂木。四周に縁と高欄が廻り、向拝に浜縁を付す。全体に装飾抑えつつも扉に菊紋を付して荘厳した本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014924"},{"id":"00002812","register_sub_id":"101","register_pk":"103802","name":"大神山神社石の大鳥居","kana":"おおがみやまじんじゃいしのおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡大山町大山","lat":35.38987297,"lng":133.536041,"geo_status":"db","era":"嘉永7","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"石造、高さ8.5m、幅12m","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"31 － 0055","desc":"高さ８．５ｍ，柱の直径約２尺の石造明神鳥居である。柱には建立時の願主や，施主及び修理世話人などの名が刻まれている。山陽方面から大山寺への参道入口にあたる大山横手道にあり，規模も雄大で，「石の大鳥居」として広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002812"},{"id":"00014930","register_sub_id":"101","register_pk":"519190","name":"加知彌神社随神門","kana":"かちみじんじゃずいしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町寺内155-1","lat":35.47848611,"lng":134.05256667,"geo_status":"db","era":"文政13年(1830)／昭和中期改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、銅板葺、建築面積15㎡","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0289","desc":"境内入口に東面して建つ桁行三間梁間二間切妻造平入銅板葺の随神門。棟通りを東に寄せた変則的な八脚門形式の平面で、中央間は土間で化粧屋根裏、両脇間の西間は床と天井を張り随神を安置、東間は吹放ちの土間で天井を張り随神の礼拝場とした特徴的なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014930"},{"id":"00014929","register_sub_id":"101","register_pk":"519189","name":"加知彌神社拝殿","kana":"かちみじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市鹿野町寺内155-1","lat":35.47849722,"lng":134.05209167,"geo_status":"db","era":"大正10年／昭和中期改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0288","desc":"本殿東に東面する桁行三間梁間三間、入母屋造銅板葺の拝殿。四周に縁と高欄を巡らし、正面に柱間の広い唐破風造の向拝を付す。内部は一室の拭板敷で格天井を張る。全体に装飾少なく簡素なつくりとし、大振りな唐破風の向拝など、本殿の形式と呼応する拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014929"},{"id":"00014928","register_sub_id":"101","register_pk":"519188","name":"加知彌神社本殿","kana":"かちみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市鹿野町寺内155-1","lat":35.47850278,"lng":134.05186667,"geo_status":"db","era":"文政13年(1830)／昭和38年改修","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積49㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0287","desc":"鹿野城跡北方に位置する式内社の本殿。境内中央に東面する桁行三間梁間三間、切妻造妻入銅板葺。内外陣の前方一間を吹放ち、さらに正面に広い柱間で唐破風造の一間向拝を付す。向拝廻りの彫刻以外は全体に装飾を抑えつつも、大規模で独特な存在感を示す本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014928"},{"id":"00013177","register_sub_id":"101","register_pk":"368306","name":"賀茂神社本殿","kana":"かもじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県倉吉市葵町584","lat":35.42909167,"lng":133.82903889,"geo_status":"db","era":"江戸末期／平成15年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"31 － 0269","desc":"倉吉市街地南方の丘陵上に西面して建つ産土社。正面一間、背面二間、側面二間、入母屋造妻入、銅板葺で、四方に高欄付の縁を廻し、向拝一間を設ける。虹梁上部の龍、木鼻の獏、獅子、正面嵌板の獅子、牡丹など、各所を精緻な彫刻で華やかに飾る優美な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013177"},{"id":"00012627","register_sub_id":"101","register_pk":"367921","name":"蚊屋島神社神楽殿","kana":"かやしまじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年増築","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積63㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0261","desc":"拝殿前方にあり、参道に東面して建つ。東側四間半の入母屋造の舞台と控間が当初、西側二間の切妻造の入口兼倉庫が後補である。舞台は12畳半敷で参道側と本殿側の二面に高欄付の縁を廻し、格天井を張る。随神門や宝庫と同じく近代的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012627"},{"id":"00012626","register_sub_id":"101","register_pk":"367920","name":"蚊屋島神社神饌所及び渡廊","kana":"かやしまじんじゃしんせんしょおよびわたろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0260","desc":"拝殿東面と渡廊で接続し、南面して建つ。桁行三間梁間二間、切妻造妻入、内部は前方が土間、後方が畳敷で床を高く張り、西面に戸口を設ける。渡廊は桁行四間梁間一間で、全体に優美な弧を描く。機能的な整備が図られた神社の近代化の一端を示す社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012626"},{"id":"00012631","register_sub_id":"101","register_pk":"367925","name":"蚊屋島神社随神門","kana":"かやしまじんじゃずいしんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年・平成17年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0265","desc":"境内正面の参道上に南面して建つ、三間一戸の八脚門。切妻造で、妻飾は虹梁大瓶束、破風に蕪懸魚を吊る。幅広の中央間は開放とし、両脇間は門口側を格子、三方を板壁として随神像を安置する。奥行狭く間口の広い外観で、境内正面の景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012631"},{"id":"00012630","register_sub_id":"101","register_pk":"367924","name":"蚊屋島神社天神社","kana":"かやしまじんじゃてんじんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治元年頃／昭和51年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.4㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0264","desc":"境内後方にあり、本殿東側に南面して建つ。三間社流見世棚造で、虹梁大瓶束の妻飾や若葉の透彫木鼻をもつ向拝の虹梁型頭貫など細部装飾を含め、規模･形式とも豊受社と寸分違わない。豊受社と対置され、伝統的な境内空間を構成する、端正な意匠の境内社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012630"},{"id":"00012629","register_sub_id":"101","register_pk":"367923","name":"蚊屋島神社豊受社","kana":"かやしまじんじゃとようけしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治元年頃／昭和51年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.4㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0263","desc":"境内後方にあり、本殿西側に南面して建つ。三間社流見世棚造で、前後とも一軒疎垂木、妻飾は虹梁大瓶束、破風拝みに蕪懸魚を飾る。身舎と向拝は海老虹梁でつなぎ、向拝両端の柱を虹梁型頭貫で結ぶ。伝統的な境内空間を構成する、端正な意匠の境内社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012629"},{"id":"00012625","register_sub_id":"101","register_pk":"367919","name":"蚊屋島神社幣殿及び拝殿","kana":"かやしまじんじゃへいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"天保4年（1833）／明治元年・同33年改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積73㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0259","desc":"本殿正面に接続し、南面して建つ。拝殿は桁行五間梁間二間の入母屋造で、正面に入母屋造軒唐破風付の向拝、背面に両下造の幣殿を出す。内部は畳敷、格天井で、幣殿の床を一段上げ、本殿前に木階五級を設ける。装飾豊かな正面で、社頭景観を華やかに整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012625"},{"id":"00012628","register_sub_id":"101","register_pk":"367922","name":"蚊屋島神社宝庫（仮殿）","kana":"かやしまじんじゃほうこ（かりでん）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治33年／昭和51年・平成17年改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積29㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0262","desc":"拝殿前方にあり、参道に西面して建つ。桁行三間梁間二間、切妻造妻入で、側背面を板壁とし、正面に切妻造の吹放し向拝を付す。軒は一軒疎垂木。内部は10畳敷で後方に祭壇を設ける。装飾の少ない外観で随神門や神楽殿と同じく近代的な表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012628"},{"id":"00012624","register_sub_id":"101","register_pk":"367918","name":"蚊屋島神社本殿","kana":"かやしまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県西伯郡日吉津村大字日吉津354","lat":35.437454,"lng":133.379944,"geo_status":"geocoded","era":"明治元年／平成17年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0258","desc":"箕蚊屋平野中央部に鎮座する、蚊屋庄29ヵ村の産土社。本殿は正面三間側面三間の切妻造妻入で、正面側柱を角柱とする。内部は外陣、内陣、内々陣に分け、外陣の床と天井を一段下げ、正面中央間を幣殿に開放する。外観を大社造風にする独特な形式の大型本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012624"},{"id":"00009826","register_sub_id":"101","register_pk":"195655","name":"興禅寺本堂","kana":"こうぜんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市栗谷町10","lat":35.50444504,"lng":134.24126461,"geo_status":"db","era":"文化11／明治期・大正期増築","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"31 － 0183","desc":"入母屋造平入の主体部の前面に入母屋造妻入の向拝を建て、間を両下造の御拝ノ間で繋ぐという複雑な屋根形態をもち、赤色瓦を葺く。主体部は手前より次ノ間、高間、霊壇とし、最奥の霊壇は折上格天井に花鳥などを彩画する華やかな意匠で、藩主霊屋の由緒を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009826"},{"id":"00012010","register_sub_id":"101","register_pk":"210951","name":"山王日吉神社本殿","kana":"さんのうひえじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市布勢字村土居1","lat":35.50435,"lng":134.176273,"geo_status":"db","era":"嘉永3年（1850）／昭和55年改修","year":1850,"year_source":"db","year_min":1850,"year_max":1850,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-229","desc":"正面一間、側背面二間流造、銅板葺、四周に切目縁を廻らす。棟札から嘉永三年の建築、棟梁木原傳兵衛であることが判る。向拝の蟇股に池田家家紋、正面の引違戸には池田家家紋と徳川家家紋が並ぶ。「布勢の山王さん」として地域に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012010"},{"id":"00007112","register_sub_id":"101","register_pk":"108094","name":"常忍寺本堂","kana":"じょうにんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市行徳3-977","lat":35.50243969,"lng":134.22166286,"geo_status":"db","era":"文政元／天保9改修・平成10移築","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"31 － 0113","desc":"南面する５間堂で、入母屋造瓦葺に１間向拝を付ける。正面の柱は円柱で、柱上粽付で三斗を組む。内部は正面１間通りを外陣とし、その奥４間を内陣、両脇を余間とし、内陣中央後寄りに須弥壇を構える。典型的な日蓮宗本堂形式になり、細部様式に時代を反映する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007112"},{"id":"00014932","register_sub_id":"101","register_pk":"519192","name":"杉谷神社拝殿及び幣殿","kana":"すぎたにじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市気高町日光1035","lat":35.51332778,"lng":134.069575,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0291","desc":"境内中央に西面して建つ拝殿及び幣殿。拝殿は入母屋造妻入桟瓦葺の東西棟で、正面に一間の向拝を設け、切目縁を付す。内部は一室の畳敷とし、竿縁天井を高く張る。本殿に向かう背面上段に切妻造桟瓦葺の弊殿を張出す。本殿と一体的に境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014932"},{"id":"00014931","register_sub_id":"101","register_pk":"519191","name":"杉谷神社本殿","kana":"すぎたにじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市気高町日光1035","lat":35.51332778,"lng":134.06966944,"geo_status":"db","era":"大正4年／昭和25年改修","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"31 - 0290","desc":"干拓地の旧日光池の東方、丘上にある神社本殿。西面する一間社流造銅板葺、四周に高欄付縁を廻し正面の木階下に浜縁を付す。組物は皿斗付大斗で三斗を組み、妻飾は虹梁大瓶束。全体に装飾少なく簡素にまとめる。設計書も備え近代の社殿造営の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014931"},{"id":"00015084","register_sub_id":"101","register_pk":"529362","name":"大樹寺開山堂","kana":"だいじゅじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41240278,"lng":134.329425,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0293","desc":"本堂背面と渡廊で接続する開山堂。一段高い石積上に西面して建つ入母屋造平入桟瓦葺。内部は一室で格天井を張り、東側に円柱を立て虹梁を渡し須弥壇を設ける。周囲の位牌棚は柱を省略し垂壁を廻らした軽快なつくり。本堂の背後に建ち伽藍の歴史的景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015084"},{"id":"00015086","register_sub_id":"101","register_pk":"529364","name":"大樹寺鐘楼","kana":"だいじゅじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41209722,"lng":134.32913889,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積9.9㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0295","desc":"本堂南西に位置する鐘楼。基壇上に東面して建つ入母屋造銅板葺。礎盤上に円柱を内転びに立て正面に中央上方が湾曲する腰貫を用いる。円柱に三斗を組み、軒は二軒繁垂木、中備は蟇股。内部は格天井張。戦時供出した梵鐘再鋳記念の鐘楼で伽藍景観の一翼を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015086"},{"id":"00015085","register_sub_id":"101","register_pk":"529363","name":"大樹寺僧堂","kana":"だいじゅじそうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41250278,"lng":134.32936389,"geo_status":"db","era":"昭和30年／平成23年改修","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積166㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0294","desc":"本堂の北東に位置する僧堂。西面して建つ入母屋造平入桟瓦葺。内部は一室の土間で竿縁天井を張り、入側に土間の廊下を廻らす。中央には文殊菩薩像を配し、修行用の単を東西に三列設える。往時は中国地方唯一の専門僧堂であったという由緒を伝える大型の僧堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015085"},{"id":"00015083","register_sub_id":"101","register_pk":"529361","name":"大樹寺本堂","kana":"だいじゅじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡八頭町福地408","lat":35.41229167,"lng":134.32927778,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積256㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"31 - 0292","desc":"市場城跡東方の山腹にある曹洞宗寺院本堂。境内中央に西面する入母屋造平入桟瓦葺。正面向拝は垂木を湾曲させ、中備、手挟は彫刻豊か。内部は前面を外陣、中央を大間、後方を内陣とし、大間は折上格天井。棟が高い大規模本堂の姿が地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015083"},{"id":"00012020","register_sub_id":"101","register_pk":"210961","name":"大山寺鐘楼","kana":"だいせんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県西伯郡大山町大山字中門院谷9","lat":35.390816,"lng":133.534796,"geo_status":"db","era":"昭和25年","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造、銅板葺、面積11㎡","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"31-239","desc":"本堂西側に北面して並び建つ。桁行一間梁間一間、一重切妻造銅板葺。基壇上に柱を内転びに立て、腰貫、飛貫、頭貫で固める。柱上部に大斗を載せ、十字に組んだ絵様肘木で桁、虹梁を受ける。本堂同様に中世の様式を基調としながら近代的な特徴を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012020"},{"id":"00012019","register_sub_id":"101","register_pk":"210960","name":"大山寺本堂","kana":"だいせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"鳥取県","address":"鳥取県西伯郡大山町大山字中門院谷9","lat":35.390999,"lng":133.534841,"geo_status":"db","era":"昭和26年／昭和60年改修","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"31-238","desc":"木造、正面五間側面六間、宝形造銅板葺、向拝三間正面唐破風付。内部は外陣、内陣、脇陣、後陣からなり、後陣の前より須弥壇を構え内々陣とする。中世寺院の構成を継承しつつ、意匠性豊かな彫刻を用いるなど近代的な要素が加わり、近代寺院建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012019"},{"id":"00010338","register_sub_id":"101","register_pk":"199111","name":"立川稲荷神社中門","kana":"たちかわいなりじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市立川町4-218-2","lat":35.492832,"lng":134.247986,"geo_status":"db","era":"大正10年／昭和8年・平成25年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、金属板葺、間口2.4m","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0194","desc":"本殿と幣殿の間の石段上に建つ。方一間、切妻造妻入りで、屋根に緩く起りをつける。礎盤上に立つ円柱上に舟肘木を組んで落とし込み、桁を受ける。妻飾は豕扠首とし、正面柱間に上半を竪格子とした桟唐戸を吊る。近代に各地で建てられた神社中門の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010338"},{"id":"00010337","register_sub_id":"101","register_pk":"199110","name":"立川稲荷神社拝殿及び幣殿","kana":"たちかわいなりじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市立川町4-68","lat":35.492779,"lng":134.247905,"geo_status":"db","era":"寛保元年（1741）／大正7年改修","year":1741,"year_source":"db","year_min":1741,"year_max":1741,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積68㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0193","desc":"間口三間奥行三間、入母屋造妻入り、桟瓦葺として縁を廻らし、背面に幣殿を張出す。内部は一室で幣殿を上段とし、格天井を張る。妻飾を木連格子とし、正面に構える唐破風造の向拝に、蟇股を二個重ねて彫刻木鼻を付すなど、正面構えの装飾密度を高めた拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010337"},{"id":"00010336","register_sub_id":"101","register_pk":"199109","name":"立川稲荷神社本殿","kana":"たちかわいなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市立川町4-218-2","lat":35.492883,"lng":134.248054,"geo_status":"db","era":"大正10年／昭和8年・平成25年改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0192","desc":"正面一間背面二間、切妻造金属板葺で四周に縁高欄を廻らし、正面の向拝に浜床を設ける。柱上に舟肘木を落とし込み、軒は二軒繁垂木、妻飾は豕扠首とする。正面と両側面前間に桟唐戸を開き、他は板壁とする。建ちが高く、装飾を抑えた簡明な意匠になる本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010336"},{"id":"00008327","register_sub_id":"101","register_pk":"133969","name":"転法輪寺本堂","kana":"てんぽうりんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県東伯郡琴浦町大字別宮字中屋敷472他","lat":35.42534307,"lng":133.65869337,"geo_status":"db","era":"延享3年(1746)／文政5年(1822)・明治4年・昭和29年改修","year":1746,"year_source":"db","year_min":1746,"year_max":1746,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積113㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"31 － 0163","desc":"山麓に占める境内後方に位置する。桁行五間梁間三間の入母屋造妻入桟瓦葺で、軒支柱を建てる。前二間を外陣、奥を内陣とする。内陣は三方に縁をまわし、床を高く張り、背面に接して壇を構え、中央に本尊、脇に脇士等を安置する。村落に所在する近世仏堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008327"},{"id":"00012618","register_sub_id":"101","register_pk":"367912","name":"長田神社祈祷殿","kana":"ながたじんじゃきとうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目103","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和34年／平成19年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0252","desc":"神門前方に社務所と並び、西面して建つ。桁行7･9メートル梁間4･9メートル、切妻造銅板葺妻入で、正面に唐破風状の向拝を設け、背面に神棚を突出する。内部は畳敷で、奥5畳の床を一段高くして内陣とする。門前景観における近代化の様相を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012618"},{"id":"00012616","register_sub_id":"101","register_pk":"367910","name":"長田神社神饌所（仮殿）","kana":"ながたじんじゃしんせんじょ（かりでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"大正4年／大正13年移築","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0250","desc":"本殿北側に南面して建つ。桁行二間半梁間一間半の入母屋造鉄板葺で、正面東寄りに玄関、東側面に納屋を下屋で設ける。内部は玄関に面して三畳間を設け、北面全面を押入とする。西半は土間とし、西側面に勝手口を開く。近代的な境内の構成を伝える社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012616"},{"id":"00012617","register_sub_id":"101","register_pk":"367911","name":"長田神社神門","kana":"ながたじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造、銅板葺、間口3.3m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0251","desc":"境内正面の参道上に西面して建つ銅板葺の薬医門。間口三・三メートルで、扉を設けず、本柱を丸柱とする独特の構成で、木太い軸部に一軒小舞打で軒の出の大きい屋根をかける。装飾は少ないが、総檜造の簡潔かつ豪放な表門で、境内正面の景観を厳かに引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012617"},{"id":"00012615","register_sub_id":"101","register_pk":"367909","name":"長田神社透塀","kana":"ながたじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造、銅板葺、延長41m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0249","desc":"本殿の四周を結界する木造銅板葺の透塀。基壇は三段の切石積、腰は縦板張目板打、腰長押と内法長押を廻し、腰上は菱形断面の板連子とする。屋根は腕木を出して桁を通し、深い軒をつくる。檜の良材を用いた精巧なつくりで、本殿周辺の景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012615"},{"id":"00012614","register_sub_id":"101","register_pk":"367908","name":"長田神社中門","kana":"ながたじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造、銅板葺、間口2.4m","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0248","desc":"本殿を囲む透塀の正面中央に建つ切妻造銅板葺妻入の門。間口二・四メートル、礎盤上の4本の丸柱を貫と長押で固め、中備蟇股、舟肘木で梁桁を受け、格天井を張る。妻飾は豕叉首、軒は一軒で起り屋根とする。明治時代の「制限図式」の影響がみられる神社建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012614"},{"id":"00012619","register_sub_id":"101","register_pk":"367913","name":"長田神社手水舎","kana":"ながたじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目121","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、瓦葺、面積7.0㎡","structure_material":"木造","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0253","desc":"神門前方の参道を挟んで祈祷殿と対面する位置に建つ。桁行2･9メートル梁間2･4メートル、四方吹放しの切妻造桟瓦葺で、礎石上の几帳面取角柱を内法虹梁で固め、柱上の舟肘木と波形蟇股で軒桁を受ける。祈祷殿と同じく門前の歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012619"},{"id":"00012613","register_sub_id":"101","register_pk":"367907","name":"長田神社幣拝殿","kana":"ながたじんじゃへいはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"江戸後期／大正13年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、金属板葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0247","desc":"本殿正面に西面して建つ。桁行三間梁間二間、入母屋造平入の拝殿背面に、桁行二間梁間一間、入母屋造の幣殿を出し、周囲に縁を廻す。拝殿は12畳、幣殿は6畳で床を一段高く張る。柱を角柱とし、装飾を控えた簡明なつくりで森厳な社頭景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012613"},{"id":"00012612","register_sub_id":"101","register_pk":"367906","name":"長田神社本殿","kana":"ながたじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市東町一丁目101","lat":35.505241,"lng":134.240631,"geo_status":"geocoded","era":"江戸後期／大正13年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"31 － 0246","desc":"鳥取城南隣に鎮座し、本殿は境内奥に西面して建つ。正面千鳥破風付の入母屋造、正面一間、側面二間背面二間の四周に高欄付の縁を廻し、軒唐破風付の向拝を設ける。軒廻りは隅のみ出組の二軒繁垂木。向拝の打越垂木を緩やかに起らすなど優美な造形をもつ社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012612"},{"id":"00008165","register_sub_id":"101","register_pk":"132606","name":"南菀寺山門","kana":"なんえんじさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県東伯郡三朝町大字三朝字下平205-3","lat":35.41175731,"lng":133.89470497,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積9.5㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"31 － 0162","desc":"市街地から庫裏に至る石段の途中に建ち、桁行一間梁間一間、楼門、入母屋造桟瓦葺である。下階を漆喰塗で厚く覆って通路をアーチ状につくり、上階は四面とも竪格子とし、軒は二軒繁垂木で、棟に鵄尾を上げる。いわゆる竜宮造の形式で、特異な伽藍景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008165"},{"id":"00010341","register_sub_id":"101","register_pk":"199114","name":"摩尼寺山門","kana":"まにじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市覚寺624","lat":35.52965822,"lng":134.26331192,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造、瓦葺、間口2.9m、左右袖塀及び潜り戸付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0197","desc":"本堂正面に建つ一間一戸薬医門。五平の本柱と控柱上に各々冠木を渡し、皿斗付の三斗で木鼻付の梁を受け、波紋彫刻の笈形付大瓶束で棟木を受ける。屋根は切妻造桟瓦葺で棟端に鯱を載せ、破風拝みに三花懸魚を吊る。随所に立体的な彫刻を施し境内の表構えを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010341"},{"id":"00010340","register_sub_id":"101","register_pk":"199113","name":"摩尼寺鐘楼","kana":"まにじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県鳥取市覚寺624","lat":35.529561,"lng":134.263356,"geo_status":"db","era":"明治25年","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、瓦葺、面積16㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"31-0196","desc":"山門の東に建つ方一間の吹放ち形式の鐘楼で、入母屋造桟瓦葺である。几帳面取角柱を石礎盤上に内転びで立て、足固貫、内法貫、木鼻付頭貫及び台輪で固め三斗実肘木で梁を受け、中備は蟇股とする。中央に梁を渡し梵鐘を吊る。山門とともに表構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010340"},{"id":"00010339","register_sub_id":"101","register_pk":"199112","name":"摩尼寺本堂","kana":"まにじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"鳥取県","address":"鳥取県鳥取市覚寺624","lat":35.529763,"lng":134.263466,"geo_status":"db","era":"万延元年（1860）","year":1860,"year_source":"db","year_min":1860,"year_max":1860,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"31-0195","desc":"南面し、桁行三間梁間四間、入母屋造桟瓦葺で正面に千鳥破風を飾り、軒唐破風付の一間向拝を付す。正面一間を外陣とし、堂内後寄りに仏壇を据えて内陣を広くとる。向拝や内外陣境、仏壇廻りは龍や鳥獣、雲や波形の彫刻で高密度に飾り、時代的特徴を良く示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010339"},{"id":"00005494","register_sub_id":"101","register_pk":"106482","name":"向山神社籠堂","kana":"むこうやまじんじゃこもりどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29114092,"lng":134.24891859,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0099","desc":"本殿の西側にある。南を正面とする切妻造，妻入で，土台を廻して角柱を立てて貫で緊結し，竪板壁とする。南面の出入口は引込戸を設け，内側を踏込土間とする。内部は天井を張らず，板敷で囲炉裏を設ける。素朴な形式であるが，神社信仰の一端を物語る施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005494"},{"id":"00005493","register_sub_id":"101","register_pk":"106481","name":"向山神社拝殿及び覆殿","kana":"むこうやまじんじゃはいでんおよびおおいどの","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29109145,"lng":134.24899614,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、鉄板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0098","desc":"本殿前面にある拝殿は，切妻造，妻入，正面と背面に格子戸，中敷居を入れた両側面に板戸を配し，組物や装飾のない簡素な形式である。覆殿は，吹放しの軸部を一段高く組んで，棟を拝殿と直交させる。集落を見渡す高台にあって，存在感のある形態を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005493"},{"id":"00005492","register_sub_id":"101","register_pk":"106480","name":"向山神社本殿","kana":"むこうやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"鳥取県","address":"鳥取県八頭郡智頭町大字市瀬","lat":35.29113252,"lng":134.24899614,"geo_status":"db","era":"明治6","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3㎡","structure_material":"木造平屋建","registered":"2006.03.27(平成18.03.27)","register_no":"31 － 0097","desc":"ほぼ南面して建つ一間社流造。石造亀腹上に廻した土台上に軸部を組み，組物は三斗，中備蟇股とする。虹梁や手挟などの絵様装飾が豊かで，獅子鼻は立体的な造形である。軒は正面が二軒繁垂木，銅板葺である。近世以来の伝統的な形式と造形をよく継承している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005492"},{"id":"00011553","register_sub_id":"101","register_pk":"210389","name":"医光寺中門","kana":"いこうじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"島根県","address":"島根県益田市染羽町ロ195-1","lat":34.67986111,"lng":131.86549694,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口4.6m","structure_material":"木造","registered":"2017.05.02(平成29.05.02)","register_no":"32-0180","desc":"医光寺は市街地の東部に位置する臨済宗寺院。中門は四脚門で、切妻造、桟瓦葺とする。本柱は丸柱、控柱は角柱とし、頭貫で固め、出組組物で軒を支える。頭貫に亀甲紋を地紋彫りし、虹梁や木鼻など随所を彫刻で華やかに飾り、境内景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011553"},{"id":"00010888","register_sub_id":"101","register_pk":"201723","name":"出雲大社宇迦橋大鳥居","kana":"いずもおおやしろうがばしおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県出雲市大社町杵築南1387-5他","lat":35.39158,"lng":132.687275,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"鉄筋コンクリート造、高さ23m、幅14m","structure_material":"鉄筋コンクリート造","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0175","desc":"高さ二三メートル、基部柱間一四メートル、柱径一・八メートルを測る巨大な鉄筋コンクリート造の明神鳥居で、宇迦橋北詰に道路を跨いで建つ。旧大社駅から出雲大社に向かう神門通りに建てられた鳥居で、近代に整備された参道景観を象徴的に演出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010888"},{"id":"00010887","register_sub_id":"101","register_pk":"201722","name":"出雲大社彰古館","kana":"いずもおおやしろしょうこかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県出雲市大社町杵築東195","lat":35.402534,"lng":132.684991,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、銅板葺、建築面積165㎡","structure_material":"木造2階建","registered":"2015.11.17(平成27.11.17)","register_no":"32 ‐ 0174","desc":"本殿の北西方にある宝物館。亀甲積基壇に建つ木造二階建、入母屋造銅板葺で、正面中央に一間切妻造の玄関を設け、二階は桁行梁間とも側廻り一間を逓減し、縁高欄を廻して安定した外観をつくる。良質のスギ材を用い、施工も丁寧で、境内空間と調和している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010887"},{"id":"00009665","register_sub_id":"101","register_pk":"194661","name":"櫛代賀姫神社本殿","kana":"くししろかひめじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"島根県","address":"島根県益田市久城町963-1他","lat":34.70126748,"lng":131.84003628,"geo_status":"db","era":"明和2","year":1765,"year_source":"db","year_min":1765,"year_max":1765,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"32 － 0167","desc":"拝殿後方に建つ三間社流造銅板葺で、庇部床高を本屋より一段下げて縁高欄を廻らし、庇の側面に格子をたてて前室風につくる。妻飾は豕扠首で軒は一軒繁垂木とする。当地方の神社本殿の特徴を示すとともに、細部に天正期の古材を残し、遺風を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009665"},{"id":"00000086","register_sub_id":"101","register_pk":"101076","name":"津和野カトリック教会","kana":"つわのかとりっくきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町大字後田ロ66-7","lat":34.46746341,"lng":131.77412759,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積131㎡","structure_material":"木造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"32 － 0005","desc":"この教会は，長崎浦上のキリシタン信徒の殉教地として知られる津和野にビリオン神父によって創設されたもので，現在の建物は昭和４年の再建である。木造平屋建の単塔式のゴシック様式になり，簡潔な図柄のスデンドグラスのある教会として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000086"},{"id":"00008364","register_sub_id":"101","register_pk":"134006","name":"津和野カトリック教会神父館","kana":"つわのかとりっくきょうかいしんぷかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"島根県","address":"島根県鹿足郡津和野町後田字殿町ロ66-7","lat":34.46731759,"lng":131.77415663,"geo_status":"db","era":"昭和6年","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造2階建、スレート葺、建築面積69㎡","structure_material":"木造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"32 － 0156","desc":"和風庭園に西面して建つ。桁行１３ｍ梁間５．４ｍの木造２階建。寄棟造スレート葺とし、外壁は２階を下見板張、１階を腰板張、上部を板壁ペンキ塗装とする。内部は１階に事務室や応接室、食堂、２階に居室三室などを配する。地方における教会施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008364"},{"id":"00014293","register_sub_id":"101","register_pk":"509683","name":"美保神社拝殿","kana":"みほじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県松江市美保関町美保関608","lat":35.56231944,"lng":133.30629167,"geo_status":"db","era":"大正13年／平成10年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、杮葺、建築面積203㎡","structure_material":"木造平屋建","registered":"2022.06.29(令和4.06.29)","register_no":"32 - 0216","desc":"美保関に位置する式内社の拝殿。桁行六間、梁間三間、切妻造妻入杮葺で、正面の下屋中央に切妻の破風を付す。内部は石敷で柱が林立し、柱間装置は四面開放で、天井を張らずに整然とした小屋組をみせる。いわゆる美保造の雄大な本殿に相応しい広壮な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014293"},{"id":"00000083","register_sub_id":"101","register_pk":"101073","name":"横田相愛教会（旧救世軍会館）","kana":"よこたそうあいきょうかい（きゅうきゅうせいぐんかいかん）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"島根県","address":"島根県仁多郡奥出雲町横田924","lat":35.17981391,"lng":133.0906053,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造2階建塔屋付、亜鉛メッキ銅板葺、建築面積155㎡","structure_material":"木造2階建塔屋付","registered":"1996.12.20(平成8.12.20)","register_no":"32 － 0002","desc":"桁行１１間，梁間７間の規模の木造２階建の教会で，正面に出入り口を兼ねた４階建ての塔屋が取り付く。地元の求道者岡崎喜一郎が私財を投じて建築にあたったという。外壁を下見板張りとし，特徴的な窓枠を備えた素朴な洋風の教会である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000083"},{"id":"00012988","register_sub_id":"101","register_pk":"368067","name":"大浦神社鳥居","kana":"おおうらじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市寄島町7756-1","lat":34.48113611,"lng":133.58216111,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造、間口4.5m","structure_material":"石造","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 329","desc":"境内東方に延びる参道入口に建つ花崗石製明神鳥居。柱間4・5メートル高さ6・5メートル、足元径0・6メートルの円柱を頂部で柱1本分の内転びで立て、貫で固め、反りのある島木笠木を載せる。均整の取れた外観で参道景観の核をなし、参拝者に親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012988"},{"id":"00012987","register_sub_id":"101","register_pk":"368066","name":"大浦神社祝詞殿、幣殿及び拝殿","kana":"おおうらじんじゃのりとでん、へいでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市寄島町7756-1","lat":34.48166111,"lng":133.58136667,"geo_status":"db","era":"昭和2年頃／平成21年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積151㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 328","desc":"本殿前に東面して建つ。入母屋造銅板葺の拝殿と祝詞殿を前後に並べ、両下造の幣殿でつなぐ権現造風の外観で、拝殿正面に千鳥破風と大振りの向唐破風向拝を付す。全体に簡明ながら端正なつくりで、向拝を霊獣の彫刻で飾るなど、厳かな社頭景観を演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012987"},{"id":"00012986","register_sub_id":"101","register_pk":"368065","name":"大浦神社本殿","kana":"おおうらじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市寄島町7756-1","lat":34.48180278,"lng":133.58121111,"geo_status":"db","era":"昭和2年／平成27年改修","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積33㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 327","desc":"市南部の寄島町中心部にある神社。本殿は境内後方の高い基壇上に東面して建つ。桁行三間梁間三間、入母屋造銅板葺、正面千鳥破風、向拝一間軒唐破風付。組物は尾垂木付二手先とし、蟇股や木鼻に精巧な彫刻を施すなど、端正な意匠でまとめた近代の大型本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012986"},{"id":"00015234","register_sub_id":"101","register_pk":"530658","name":"大元宗忠神社御札所（旧神札殿）","kana":"おおもとむねただじんじゃおふだしょ（きゅうみまもりどの）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.645175,"lng":133.90185278,"geo_status":"db","era":"明治18年／昭和52年・平成3年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、銅板葺、建築面積48㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0376","desc":"拝殿の南東に位置する入母屋造銅板葺東西棟の御札所。組物は木鼻付大斗肘木で軒は一軒繁垂木とする。かつて木階を付した北正面に庇を架け、身舎周囲に刎高欄付の切目縁を廻す。内部は１室で御札所とする。社務所と一対で左右対称の境内景観をつくる御札所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015234"},{"id":"00015237","register_sub_id":"101","register_pk":"530661","name":"大元宗忠神社教祖記念館（旧布教所兼主屋）","kana":"おおもとむねただじんじゃきょうそきねんかん（きゅうふきょうしょけんおもや）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-102","lat":34.64498611,"lng":133.90212222,"geo_status":"db","era":"嘉永元年(1848)／明治15年移築、平成16年改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積274㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0379","desc":"境内南東に位置するかつての布教所兼主屋。入母屋造茅葺で周囲に本瓦葺の下屋を廻し、南面に大玄関を突出する。西側に神壇と旧祖霊社を配し、六室に区切る三六畳半の教場が中央を占める。北西に教祖宗忠が晩年居住した御居間を残し、黒住教の記念碑的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015237"},{"id":"00015233","register_sub_id":"101","register_pk":"530657","name":"大元宗忠神社社務所（旧神饌殿）","kana":"おおもとむねただじんじゃしゃむしょ（きゅうみけどの）","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64555,"lng":133.90185833,"geo_status":"db","era":"明治18年／昭和52年・平成元年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、銅板葺、建築面積46㎡","structure_material":"木造2階建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0375","desc":"拝殿の北東に位置する、入母屋造銅板葺東西棟の社務所。組物は木鼻付大斗肘木で、軒は一軒繁垂木とする。かつて木階を付した南正面に庇を付し、身舎周囲には刎高欄付の切目縁を廻す。内部は一室で宮司室。御札所と一対で左右対称の境内景観をつくる社務所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015233"},{"id":"00015239","register_sub_id":"101","register_pk":"530663","name":"大元宗忠神社長屋門","kana":"おおもとむねただじんじゃながやもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-103","lat":34.64484722,"lng":133.90233611,"geo_status":"db","era":"江戸末期／昭和55年頃・平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積58㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0381","desc":"教祖記念館の南東、通りに東面して建つ長屋門。北面切妻造、南面入母屋造、本瓦葺で、南・西面に下屋を廻らす。中央南寄りに板扉の門口を構えて石敷土間とし、北脇に潜戸を設ける。外壁は腰高の焼杉板張。旧布教所兼主屋の正門となる堅実なつくりの長屋門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015239"},{"id":"00015232","register_sub_id":"101","register_pk":"530656","name":"大元宗忠神社拝殿","kana":"おおもとむねただじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64536389,"lng":133.90172778,"geo_status":"db","era":"明治18年／昭和52年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積262㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0374","desc":"本殿の東に建つ比翼入母屋造銅板葺の大規模拝殿。正面に千鳥破風、唐破風造の向拝を付す。内部は御神前の両脇に幣殿を配し、東は長大な虹梁で柱を省いた広大な教場とし、御神前へと床高を高める。向拝廻りを豊富に装飾し、華やかかつ独特の外観を備えた拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015232"},{"id":"00015235","register_sub_id":"101","register_pk":"530659","name":"大元宗忠神社拝殿北回廊","kana":"おおもとむねただじんじゃはいでんきたかいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64548889,"lng":133.90176111,"geo_status":"db","era":"明治18年／昭和52年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0377","desc":"拝殿と社務所を接続する回廊。平面矩折の両下造銅板葺の渡廊下で北面に武道館への渡廊下が接続。柱を胴差で繋ぎ、床を高く張り、腰と内法上部は竪板張。床は拭板敷、天井は竿縁天井。南回廊と対をなし、拝殿、御札所、社務所とともに社殿の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015235"},{"id":"00015236","register_sub_id":"101","register_pk":"530660","name":"大元宗忠神社拝殿南回廊","kana":"おおもとむねただじんじゃはいでんみなみかいろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64521111,"lng":133.90176667,"geo_status":"db","era":"明治18年／昭和52年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0378","desc":"拝殿と御札所を接続する回廊。平面矩折とする両下造銅板葺の渡廊下で、柱を胴差で繋ぎ、床を高く張り、腰と内法上部は竪板張、床は拭板敷、天井は竿縁天井。隅部の床下は物置とする。北回廊と対をなし、拝殿、御札所、社務所とともに社殿の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015236"},{"id":"00015238","register_sub_id":"101","register_pk":"530662","name":"大元宗忠神社武道館（旧大教会所）","kana":"おおもとむねただじんじゃぶどうかん（きゅうだいきょうかいしょ）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64579444,"lng":133.90159444,"geo_status":"db","era":"明治32年／大正2年増築、昭和51年・平成16年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積616㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0380","desc":"本殿の北方に東面して建つかつての布教の中心道場。入母屋造妻入桟瓦葺の周囲に下屋を廻し、正面に入母屋造玄関を付す。内部中央は一室の広大な板敷で、西面を上段とし、奥に旧神壇を張出す。木造トラスを用いて二〇〇畳に及ぶ無柱空間を実現した大規模道場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015238"},{"id":"00015231","register_sub_id":"101","register_pk":"530655","name":"大元宗忠神社本殿","kana":"おおもとむねただじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64536667,"lng":133.90143056,"geo_status":"db","era":"明治18年／昭和39年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0373","desc":"ＪＲ大元駅西方、黒住教発祥地に教祖大元宗忠を祀った神社本殿。基壇上に建つ入母屋造銅板葺社殿で、正面に千鳥破風を据え、三間の向拝に軒唐破風を付し、床高の高い身舎周囲に縁を廻す。伝統的な彫刻や錺金具で荘厳し、細部まで丁寧なつくりの上質な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015231"},{"id":"00015240","register_sub_id":"101","register_pk":"530664","name":"大元宗忠神社門及び瑞垣","kana":"おおもとむねただじんじゃもんおよびみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区上中野一丁目3-101","lat":34.64537222,"lng":133.90152778,"geo_status":"db","era":"明治18年／昭和39年改修","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"門 木造、銅板葺、間口2.2m 瑞垣 木造、銅板葺、総延長62m","structure_material":"門 木造","registered":"2024.12.03(令和6.12.03)","register_no":"33 - 0382","desc":"本殿正面に開く門及び周囲を廻る瑞垣。門は銅板葺の平唐門で、礎盤上に円柱を立て、桟唐戸を開く。冠木上中央に浪に兎の彫刻を飾る。塀は切妻造銅板葺で、精緻に積んだ切石積の基壇上に建ち、柱間に菱格子と襷桟の欄間を嵌める。本殿を区画する上質な門と塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015240"},{"id":"00012029","register_sub_id":"101","register_pk":"210970","name":"木山神社拝殿","kana":"きやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.016837,"lng":133.722298,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-282","desc":"大正八年に現在の奥宮の場所で建てられ、昭和三七年に現在の里宮に移築されたもの。設計は江川三郎八。入母屋造銅板葺で小屋組をトラスとし、唐破風造の三間向拝が取り付く。吹寄垂木の多用、たすき状の意匠など、江川の作品に特徴的な要素を多く見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012029"},{"id":"00012030","register_sub_id":"101","register_pk":"210971","name":"木山神社渡廊下","kana":"きやまじんじゃわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.016714,"lng":133.722329,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積13㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-283","desc":"拝殿の南面東端部と社務所を結ぶ渡廊下。両下造銅板葺で、床に緩やかな起りを付け、高欄を配する。桁行方向各柱間には虹梁をかけ、妻部分にも湾曲の大きい虹梁をかけて、随所を彫刻で飾る。軒の垂木を吹寄せとするなど、拝殿と共通する意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012030"},{"id":"00012236","register_sub_id":"101","register_pk":"353036","name":"弘泉寺山門","kana":"こうせんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市下津井田之浦二丁目843","lat":34.437726,"lng":133.804996,"geo_status":"db","era":"文政12年(1829）","year":1829,"year_source":"db","year_min":1829,"year_max":1829,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"33-295","desc":"境内東寄りに建つ山門。塩飽大工の手になるもので、本瓦葺の薬医門。両脇にも門口を設けて、二軒繁垂木とする重厚な門であり、頭貫は全長に渡って波を模しているなど、随所に彫刻を彫る装飾豊かな点が特徴。地域及び大工の特色をよく表出した門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012236"},{"id":"00012235","register_sub_id":"101","register_pk":"353035","name":"弘泉寺本堂","kana":"こうせんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市下津井田之浦二丁目843","lat":34.437734,"lng":133.804735,"geo_status":"db","era":"文政10年(1827)／昭和51年改修","year":1827,"year_source":"db","year_min":1827,"year_max":1827,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積123㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"33-294","desc":"塩飽大工の手になるもので、東面して建つ。桁行三間、梁間四間、向拝一間、入母屋造桟瓦葺で、石垣基壇上に青木石の亀腹基礎を設けている。良材を用いた手堅い造りで、蟇股など細部意匠は波形や動植物の洗練された意匠で飾り、地域の歴史的景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012235"},{"id":"00012639","register_sub_id":"101","register_pk":"367933","name":"金光教教学研究所客殿","kana":"こんこうきょうきょうがくけんきゅうしょきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷1441-3他","lat":34.529953,"lng":133.629623,"geo_status":"geocoded","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積349㎡","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0304","desc":"金光町市街南部の丘上にある迎賓施設で、客殿は敷地中央に西面して建つ。平屋建、南北棟の入母屋造銅板葺で四周に下屋を廻す。内部は中廊下を矩折れに通して椅子坐式の座敷4室を設ける。近代の設計手法と伝統木造技術が高度に調和した昭和期和風建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012639"},{"id":"00012640","register_sub_id":"101","register_pk":"367934","name":"金光教教学研究所客殿付属舎","kana":"こんこうきょうきょうがくけんきゅうしょきゃくでんふぞくしゃ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷1441-3他","lat":34.529953,"lng":133.629623,"geo_status":"geocoded","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積131㎡、渡廊下付","structure_material":"木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0305","desc":"客殿前方北寄りに南面して建つ。平屋建、入母屋造銅板葺で、正面に入母屋造の玄関を突出する。南東隅から東と南に渡廊下を延ばして、客殿、洋館と接続する。内部は前半に玄関や控室、後半に厨房や浴室等を設ける。客殿と一体をなす上質なつくりの和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012640"},{"id":"00012641","register_sub_id":"101","register_pk":"367935","name":"金光教教学研究所洋館","kana":"こんこうきょうきょうがくけんきゅうしょようかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県浅口市金光町大谷1441-3他","lat":34.529953,"lng":133.629623,"geo_status":"geocoded","era":"昭和5年","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、スレート葺、建築面積208㎡、渡廊下付","structure_material":"木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"33 － 0306","desc":"客殿前方南側に西面して建つ。木造二階建、寄棟造で西南隅に塔屋を設け、正面に玄関ポーチを付す。外壁は人造石洗出し仕上、半円窓やメダイヨンで要所を飾る。一階に応接間等各室、二階に大広間を設ける。客殿と相対し、格調高い和洋館併設の表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012641"},{"id":"00012984","register_sub_id":"101","register_pk":null,"name":"西大寺石門","kana":"さいだいじいしもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65323333,"lng":134.03787778,"geo_status":"db","era":"文政2年(1819)","year":1819,"year_source":"db","year_min":1819,"year_max":1819,"year_label":null,"structure":"石造及び木造2階建、瓦葺、建築面積31㎡","structure_material":"石造及び木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 325","desc":"境内南面中央に建つ入母屋造本瓦葺の竜宮造楼門。下層は石造で、四隅に石柱を立てて上部にアーチ状の石梁を渡す。上層は木造で各間に花頭窓を開く。組物はなく一軒扇垂木で、外壁を軒裏まで漆喰で塗込める。下層石造の豪壮な竜宮造で、国内最大規模を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012984"},{"id":"00012982","register_sub_id":"101","register_pk":null,"name":"西大寺経蔵（輪蔵）","kana":"さいだいじきょうぞう（りんぞう）","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65346111,"lng":134.03743056,"geo_status":"db","era":"嘉永7年（1854)／大正期移築","year":1854,"year_source":"db","year_min":1854,"year_max":1854,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 323","desc":"境内西南辺に東面して建つ。六角形平面の本瓦葺で、正面の扉口に片流れの向拝を付す。軒は出桁造で、外壁は軒裏まで漆喰で塗込める。内部中央の八角輪蔵は総欅造で、尾垂木付三手先詰組や軒扇垂木など禅宗様とする。輪蔵を備えた六角経蔵の貴重な遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012982"},{"id":"00012981","register_sub_id":"101","register_pk":null,"name":"西大寺高祖堂","kana":"さいだいじこうそどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65376389,"lng":134.03757778,"geo_status":"db","era":"安永9年(1780)頃","year":1780,"year_source":"db","year_min":1780,"year_max":1780,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 322","desc":"吉井川下流西岸にある真言宗寺院。高祖堂は境内西北隅に南面して建つ。方三間、宝形造本瓦葺で、正側面に高欄付縁を廻す。内部は畳敷の一室で、奥に須弥壇を置き、二重折上小組格天井を張る。組物は出組、中備は蟇股。装飾を控えた格式の高いつくりをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012981"},{"id":"00011555","register_sub_id":"101","register_pk":"210490","name":"西大寺牛玉所殿奥殿","kana":"さいだいじごおしょでんおくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65431111,"lng":134.03838611,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"33-0277","desc":"本殿・釣殿及び拝殿の奥に南面して建つ。一間社、宝形造、本瓦葺で、本殿背後の石垣上の高い位置にあり、一時期本殿とされていた。軒は二軒繁垂木で、一間四方の小ぶりな社殿であるが、三方に縁を廻らし、脇障子を設け、向拝周り、組物等に濃密な意匠を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011555"},{"id":"00011554","register_sub_id":"101","register_pk":"210489","name":"西大寺牛玉所殿本殿・釣殿及び拝殿","kana":"さいだいじごおしょでんほんでん・つりどのおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65408694,"lng":134.038325,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"33-0276","desc":"邑久大工の作になる複合社殿で、拝殿、本殿とも入母屋造本瓦葺。本殿上には楼閣を設ける。拝殿は三手先、本殿は二手先で、本殿は二軒で地を並行垂木、飛檐を扇垂木とする珍しい形式。本殿天井は未完であり、楼閣を支える複雑な小屋組を見せている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011554"},{"id":"00012985","register_sub_id":"101","register_pk":null,"name":"西大寺鐘楼門","kana":"さいだいじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65386389,"lng":134.03781667,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積10㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 326","desc":"境内を南北に区切る土塀中央に建つ入母屋造本瓦葺の一間楼門。下層は正背面に虹梁を渡し、親柱筋に板扉を備える。上層は正背三間として中央間を開放し、梵鐘を吊る。組物は出組、中備は間斗束、縁腰組は出三斗。江戸中期の境内の建築形式を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012985"},{"id":"00012983","register_sub_id":"101","register_pk":null,"name":"西大寺仁王門","kana":"さいだいじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市東区西大寺中三丁目1225","lat":34.65359444,"lng":134.03750556,"geo_status":"db","era":"元文5年（1740）頃","year":1740,"year_source":"db","year_min":1740,"year_max":1740,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"33 － 324","desc":"境内西面北寄りに建つ。入母屋造本瓦葺の三間一戸楼門で、正面両脇間の金剛柵後方に仁王像を安置する。上層は尾垂木付三手先、中備蟇股とし、縁腰組は四手先で四周琵琶板に十二支を彫刻する。精緻な大工技術を駆使した禅宗様で、規模雄大な楼門の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012983"},{"id":"00013183","register_sub_id":"101","register_pk":"368407","name":"実際寺客殿","kana":"じっさいじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58624444,"lng":133.73464167,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（金属板仮葺）、建築面積103㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0331","desc":"本堂の北東に建つ。庫裏の接客部が残ったものとみられ、桁行５間、梁間４間での三方廊下に縁を廻らす。入母屋造茅葺金属板仮葺で、三方に本瓦葺の下屋を廻す。内部は南列は西から８畳と１２畳、北列は座敷７畳、板間、８畳で、座敷には床と付書院を備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013183"},{"id":"00013186","register_sub_id":"101","register_pk":"368410","name":"実際寺山門","kana":"じっさいじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58608611,"lng":133.73482222,"geo_status":"db","era":"明治17年","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0334","desc":"境内南東に南面して建ち、切妻造本瓦葺の薬医門で袖塀として本瓦葺の土塀が付く。本柱は五平で、冠木を載せ、女梁、男梁と組み、出三斗組で桁と梁を支持する。妻は虹梁蟇股で、棟木下に拳鼻を付し、軒は一軒疎垂木である。江戸後期に遡る重厚な山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013186"},{"id":"00013184","register_sub_id":"101","register_pk":"368408","name":"実際寺鐘楼","kana":"じっさいじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58605556,"lng":133.73464722,"geo_status":"db","era":"明治12年／大正15年移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、瓦葺、面積3.8㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0332","desc":"本堂の南東に建つ。方一間の鐘楼で屋根は入母屋造本瓦葺で、近世部材を再用した鐘楼である。四方転びの角柱を腰貫、飛貫、頭貫で固め、腰貫は撞木を吊る東側を一段下げる。組物は柱上で枠肘木の三斗組とし、軒は一軒疎垂木である。妻は菱格子とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013184"},{"id":"00013187","register_sub_id":"101","register_pk":"368411","name":"実際寺外塀及び石垣","kana":"じっさいじそとべいおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58634444,"lng":133.73483611,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"外塀 木造、瓦葺、延長61m 石垣 石造、延長71m","structure_material":"外塀 木造","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0335","desc":"敷地東辺から北辺に廻る。外塀は腕木付桟瓦屋根の土塀が納屋北東角から北に延び北東角隅で西へ折れ、北辺では一段低い瓦葺築地塀となる。石垣の東面は乱積で、納屋基礎部と北辺は谷積となる。境内の外周を整える施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013187"},{"id":"00013185","register_sub_id":"101","register_pk":"368409","name":"実際寺納屋","kana":"じっさいじなや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58613333,"lng":133.73488333,"geo_status":"db","era":"明治17年頃","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造2階建、瓦葺、建築面積46㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0333","desc":"境内の東辺南寄りに西面して建つ。桁行５間、梁間２間の南北棟で、南側を入母屋造、北側を切妻造とし西面の下屋とも本瓦葺とする。外壁は大壁漆喰塗で、外廻りは焼板竪板張とする。１階は土間の３室、２階は板間の二室に仕切る。境内導入部の景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013185"},{"id":"00013182","register_sub_id":"101","register_pk":"368406","name":"実際寺本堂","kana":"じっさいじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市中島字村内北町516","lat":34.58613889,"lng":133.73456944,"geo_status":"db","era":"慶安2年（1649）／明治前期・昭和59年改修","year":1649,"year_source":"db","year_min":1649,"year_max":1649,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"33 － 0330","desc":"境内西に東面して建つ小規模な真言宗寺院の本堂。正面３間、側面２間で、正面と南側面に切目縁を廻らし、柱は全て角柱で面取が大きく、縁外に軒支柱を建て、身舎柱筋大斗上の海老虹梁で縁桁と繋ぐ。木鼻や実肘木の渦も江戸前期らしい特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013182"},{"id":"00012032","register_sub_id":"101","register_pk":"210973","name":"善覚稲荷神社拝殿","kana":"ぜんかくいなりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.016978,"lng":133.722436,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-285","desc":"本社拝殿の右方に並んで建つ。妻入の入母屋造銅板葺で、背面右方に神饌所、本殿との間に釣殿が附属する。江川三郎八の設計になり、吹寄垂木、特徴あるトラス架構、格天井など、その特徴をよく示す他、正面側基礎石を洋風意匠とするなど特徴ある意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012032"},{"id":"00012031","register_sub_id":"101","register_pk":"210972","name":"善覚稲荷神社本殿","kana":"ぜんかくいなりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県真庭市木山字金谷平1265-1","lat":35.017,"lng":133.72234,"geo_status":"db","era":"大正8年／昭和37年移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"33-284","desc":"桁行四･〇メートル、梁間三・二メートル、切妻造銅板葺、平入で、四周に縁を廻らす。壁を二重に張り、柱は外側を円柱、内側を角柱とし、天井は格天井。設計は江川三郎八で、垂木を吹寄とするなど、境内の他の建物と共通する要素でまとめる、特色ある社殿建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012031"},{"id":"00004183","register_sub_id":"101","register_pk":"105173","name":"天仲院本堂","kana":"てんちゅういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野251","lat":34.68128272,"lng":133.72922579,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積200㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"33 － 0090","desc":"田園地帯に南面して建つ。桁行約１４ｍ，入母屋造，本瓦葺で，側廻りには角柱を立て，舟肘木で軒を受ける。平面は正面広縁付，座敷を西北隅に配した６間取で，いわゆる方丈形式とする。棟札から建築年代が明らかで，地方における江戸後期の臨済宗本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004183"},{"id":"00008764","register_sub_id":"101","register_pk":"149485","name":"洞松寺開山堂及び位牌堂","kana":"とうしょうじかいざんどうおよびいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59030389,"lng":133.62003585,"geo_status":"db","era":"享保年間（1716-1735）／江戸末期・明治前期・昭和後期改修","year":1726,"year_source":"estimated","year_min":1716,"year_max":1735,"year_label":"享保年間（1716-1735）","structure":"木造平屋建、鉄板葺一部瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0241","desc":"本堂の内陣後方に位牌堂を介して開山堂を建てる。開山堂は6.8ｍ四方で、宝形造鉄板葺とし、後方に壇を設けて開山を祀る。また位牌堂は桁行3.8ｍ梁間5.1ｍ、両下造瓦葺で、両側に位牌壇を設置。本堂建立後に開山堂や位牌堂が整備された経過を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008764"},{"id":"00008767","register_sub_id":"101","register_pk":"149488","name":"洞松寺庫裏","kana":"とうしょうじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59042017,"lng":133.61956045,"geo_status":"db","era":"宝暦2年(1752)／天保14年(1843)増築・平成9年改修","year":1752,"year_source":"converted","year_min":1752,"year_max":1752,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積296㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0244","desc":"方丈北側に接続し、桁行28ｍ梁間12ｍ、入母屋造及び切妻造桟瓦葺で、北端の浴司を落棟とする。中央の広い土間正面に桟唐戸を開き、典座寮等を配す。地方禅院における庫裏の好例であり、相対して建つ禅堂とともに、禅院の伽藍構成をよくとどめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008767"},{"id":"00008769","register_sub_id":"101","register_pk":"149490","name":"洞松寺書院月泉院","kana":"とうしょうじしょいんげっせんいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59078484,"lng":133.61973231,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積70㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0246","desc":"禅堂北側の一郭に、南面して建つ。桁行11ｍ梁間7.5ｍ、入母屋造本瓦葺で妻壁を菱格子とし、周囲に桟瓦葺の下屋をめぐらす。内部は客間と仏間のほか、茶室、台所などからなり、造作にも良材を用いる。風格を備えた、住職の居住施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008769"},{"id":"00008768","register_sub_id":"101","register_pk":"149489","name":"洞松寺鐘楼","kana":"とうしょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59050589,"lng":133.61994201,"geo_status":"db","era":"天保9年（1838）","year":1838,"year_source":"converted","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造2階建、瓦葺、建築面積18㎡","structure_material":"木造2階建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0245","desc":"本堂と接賓を繋ぐ位置に建つ。桁行5.3ｍ梁間4/0ｍ、両下造桟瓦葺の下層に、正方形平面で入母屋造本瓦葺の上層を、棟を直交させて載せる。上層は壁に花頭窓を開けて縁高欄をめぐらし、頭貫には渦紋を表して妻壁を菱格子とするなど、華やかな意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008768"},{"id":"00008765","register_sub_id":"101","register_pk":"149486","name":"洞松寺禅堂及び接賓","kana":"とうしょうじぜんどうおよびせっぴん","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59065616,"lng":133.61988194,"geo_status":"db","era":"天保9年（1838）","year":1838,"year_source":"converted","year_min":1838,"year_max":1838,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積251㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0242","desc":"本堂東側に鐘楼を介して建ち、南北に長い平面をもつ。桁行27ｍ梁間10ｍ、入母屋造本瓦葺で、中央を露地で仕切り、北半を禅堂として内部に単を配し、南半は禅僧の宿所である接賓とする。江戸末期における曹洞宗寺院の禅堂形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008765"},{"id":"00008771","register_sub_id":"101","register_pk":"149492","name":"洞松寺二ノ門","kana":"とうしょうじにのもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3774-1","lat":34.59295231,"lng":133.6194785,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口3.0m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0248","desc":"山門から250ｍ北方の参道に建ち、桁行3.0ｍ梁間2.7ｍ、切妻造本瓦葺である。正・背面は方柱を虹梁で繋ぎ、側面は腰下を開放とし、上部は柱筋外側を壁として内側を浅い仏壇とする。また軒先まで漆喰で塗り込めるなど、特異な形式で風格のある表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008771"},{"id":"00008766","register_sub_id":"101","register_pk":"149487","name":"洞松寺方丈及び書院","kana":"とうしょうじほうじょうおよびしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59028337,"lng":133.61974172,"geo_status":"db","era":"宝暦3年(1753)／天保6年(1835)増築・昭和54年頃改修","year":1753,"year_source":"converted","year_min":1753,"year_max":1753,"year_label":null,"structure":"木造平屋建、瓦葺一部鉄板葺、建築面積220㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0243","desc":"境内南西に建ち、方丈が庫裏に、書院が本堂に接続し、南北14ｍ東西16ｍ、入母屋造桟瓦葺である。方丈は南側にトコを備えた座敷や茶室を配し、北側を20畳の広間とする。書院は正面に式台を構え、奥室に大トコをもつ。丁寧なつくりの接客施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008766"},{"id":"00008763","register_sub_id":"101","register_pk":"149484","name":"洞松寺本堂","kana":"とうしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.5903861,"lng":133.61989142,"geo_status":"db","era":"元禄10年(1697)／天明5年(1785)・昭和54年改修","year":1697,"year_source":"converted","year_min":1697,"year_max":1697,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積290㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0240","desc":"境内奥に北面して建ち、桁行19ｍ梁間15ｍ、入母屋造、本瓦葺及び桟瓦葺である。六間取方丈形式で、前方二間通りと西側面に広縁をとる。内陣と大間に折上天井を張り、両室境は太い円柱で二手先を受け、花頭枠を渡すなど、意匠を凝らした曹洞宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008763"},{"id":"00008770","register_sub_id":"101","register_pk":"149491","name":"洞松寺門及び土塀","kana":"とうしょうじもんおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県小田郡矢掛町横谷字舟木谷3796","lat":34.59069635,"lng":133.6193841,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"門 木造、間口1.3m 土塀 総延長75m","structure_material":"門 木造","registered":"2011.07.25(平成23.07.25)","register_no":"33 － 0247","desc":"月泉院西面に開く門と、その左右に矩折れに伸びて月泉院を囲む土塀、及び山門両側に築かれた土塀からなる。門は、1間棟門、切妻造桟瓦葺で、舞良戸を両開に吊る。土塀は総延長75ｍ、壁は漆喰で仕上げる。端正な意匠の土塀が境内景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008770"},{"id":"00013889","register_sub_id":"101","register_pk":"507847","name":"中山神社拝殿","kana":"なかやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市一宮695-2","lat":35.100175,"lng":133.99463889,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積80㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"33 － 0347","desc":"本殿が重文の神社拝殿。入母屋造檜皮葺平入で正面に唐破風向拝を付す。設計は江川三郎八。正面中央を両折板唐戸とし他は格子戸引違を建て廻らす。特異なプロポーションの扱いや、吹寄垂木や格天井、直線的な舟肘木の使用等、随所に江川の作風が看取される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013889"},{"id":"00013890","register_sub_id":"101","register_pk":"507848","name":"中山神社幣殿","kana":"なかやまじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県津山市一宮695-2","lat":35.10021944,"lng":133.99458889,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"33 － 0348","desc":"拝殿同様江川三郎八の設計。桁行一間梁間一間で、桁行は実長三間分の柱間を成の高い頭貫で支える。組物は大斗肘木で屋根は切妻造檜皮葺。柱間は全て開放とし高欄を付す。特異な吹寄垂木の船底天井は江川設計の木山神社幣殿と類似する等、その作風をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013890"},{"id":"00007586","register_sub_id":"101","register_pk":"108568","name":"日本基督教団倉敷教会教会堂","kana":"にほんきりすときょうだんくらしききょうかいきょうかいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県倉敷市鶴形1-679-1","lat":34.600658,"lng":133.77107207,"geo_status":"db","era":"大正12","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造一部コンクリート造3階建塔屋付、スレート葺、建築面積267㎡、スロープ付","structure_material":"木造一部コンクリート造3階建塔屋付","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0203","desc":"通りの西側に建つ。東西棟の切妻造スレート葺で、東南隅に塔屋を付設。１階を木骨ＲＣ造の石貼とし、長いスロープが２階礼拝堂前のテラスへと続く。礼拝堂は単廊式で側面に４ヶ所の尖頭アーチ窓を開ける。石造風の重厚さと上部の軽快さが独特の調和を生み出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007586"},{"id":"00007688","register_sub_id":"101","register_pk":"108670","name":"寶福寺秋葉宮石垣及び玉垣","kana":"ほうふくじあきばぐういしがきおよびたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.69163335,"lng":133.73334753,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石垣 石造、総延長37m、玉垣 石造、総延長40m、石段及び石門付","structure_material":"石垣 石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0227","desc":"秋葉宮境内の南端を画し、境内地を造成。拝殿の南方に長い石段を設け、その両側に石垣を築く。石垣は総延長３７ｍ、高さ３．０ｍで、石段側を切石積、隅を算木積、他を野石乱積とし、上部に石製の玉垣を置く。石段は大きく３分され、途中に石門を構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007688"},{"id":"00007686","register_sub_id":"101","register_pk":"108668","name":"寶福寺秋葉宮五社明神宮","kana":"ほうふくじあきばぐうごしゃみょうじんぐう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.6919216,"lng":133.73316198,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"石祠5基及び基壇からなる、石造、建築面積2.1㎡","structure_material":"石祠5基及び基壇からなる","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0225","desc":"本殿の後方、東西に長く石積基壇を造り、その上に同じ規模形式の石祠５基を並べる。石祠は正面０．６２ｍ側面０．６８ｍ規模。石製基礎石上、側・背面に石板、正面には板扉をたて、緩やかな軒反りをもつ入母屋造屋根を載せる。秋葉宮境内に落ち着きを与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007686"},{"id":"00007687","register_sub_id":"101","register_pk":"108669","name":"寶福寺秋葉宮手水舎","kana":"ほうふくじあきばぐうてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.69173628,"lng":133.73318609,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"石造及び木造、鉄板葺、間口1.2m、水盤付","structure_material":"石造及び木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0226","desc":"拝殿の南西に建つ。南北棟の切妻造鉄板葺。間口１．２ｍに石製方柱を建て、頂部に腕木を架し、その上に束を建て、棟木や軒桁を渡し、垂木を疎らに配る。柱間に長方形の水盤を置く。水盤は切石上に置かれ、底面を花頭形に切り込む。簡易な構造の手水舎の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007687"},{"id":"00007685","register_sub_id":"101","register_pk":"108667","name":"寶福寺秋葉宮拝殿及び渡殿","kana":"ほうふくじあきばぐうはいでんおよびわたりでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.69180349,"lng":133.73321721,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積86㎡、前後石垣及び石段付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0224","desc":"本殿の正面に位置する。拝殿は桁行五間梁間二間、入母屋造本瓦葺で、千鳥破風と軒唐破風付一間向拝を付ける。内部は畳敷で、棹縁天井。渡殿は拝殿背面中央間から突出して設けられ、儀式の間と祭壇の間を前後に設ける。礼拝の場として整備された形態になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007685"},{"id":"00007684","register_sub_id":"101","register_pk":"108666","name":"寶福寺秋葉宮本殿","kana":"ほうふくじあきばぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野2068-4","lat":34.691898,"lng":133.73317009,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積6.1㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0223","desc":"山内北西の小高い位置に南面して建つ。桁行一間梁間一間、入母屋造本瓦葺で、正面に一間向拝を付け、周囲に組高欄付縁をまわす。円柱で二手先詰組とし、二軒繁垂木。小規模ながら、均整の取れた外観で、向拝木鼻や隅尾垂木を雲龍の丸彫とするなど、装飾を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007684"},{"id":"00007681","register_sub_id":"101","register_pk":"108663","name":"寶福寺開山堂","kana":"ほうふくじかいざんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1973-1","lat":34.69043411,"lng":133.73449119,"geo_status":"db","era":"江戸中期／江戸後期増築・昭和35改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積40㎡、土塀付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0220","desc":"仏殿南方の一段高い敷地に北面して建つ。方三間規模の宝形造桟瓦葺で、背面に壇を付設する。堂内は瓦敷、棹縁天井の一室とし、背面に接して中央に須弥壇、両脇に祖師壇を構える。須弥壇上部は粽付円柱で、禅宗様三手先詰組とし、桟唐戸をたてる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007681"},{"id":"00007683","register_sub_id":"101","register_pk":"108665","name":"寶福寺開山堂石垣及び土塀","kana":"ほうふくじかいざんどういしがきおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1973-1他","lat":34.69064459,"lng":133.73438721,"geo_status":"db","era":"文化3","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"石垣 石造、総延長24m、塀 土塀、瓦葺、総延長19m、石段付","structure_material":"石垣 石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0222","desc":"開山堂敷地の北側に設けられる。表門正面に石段を築き、その両脇から矩折れに東西に延びる。石垣は総延長２４ｍ高さ１．６ｍで割石乱積とし、隅を算木積とする。土塀は総延長１９ｍ高さ１．７ｍの築地塀で中塗仕上げとする。開山堂の格式ある佇まいを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007683"},{"id":"00007682","register_sub_id":"101","register_pk":"108664","name":"寶福寺開山堂表門","kana":"ほうふくじかいざんどうおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1973-1","lat":34.69061298,"lng":133.7344843,"geo_status":"db","era":"文化3／昭和中期改修","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造、瓦葺、間口2.1m、左右袖塀付","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0221","desc":"開山堂の正面に建つ四脚門。切妻造本瓦葺で、両側面に袖塀を設け、西に潜りを穿つ。円柱で、三斗組。妻は虹梁大瓶束とし、一軒疎垂木。本柱と控柱は腰長押や頭貫、台輪で固め、長押上に菱文様を彫った板壁を嵌める。扉は桟唐戸両開。手堅い意匠になる四脚門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007682"},{"id":"00007673","register_sub_id":"101","register_pk":"108655","name":"寶福寺経蔵","kana":"ほうふくじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69100641,"lng":133.73393856,"geo_status":"db","era":"宝暦14／明治16改修","year":1764,"year_source":"db","year_min":1764,"year_max":1764,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積17㎡","structure_material":"土蔵造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0212","desc":"仏殿の西北、一段高い位置に東面して建つ。宝形造本瓦葺で、唐破風造一間向拝を付ける。方二間規模の土蔵造で、切石積基礎上に建ち、白漆喰仕上げとする。軒は出桁造とし、側面に花頭形の窓を穿つ。内部は板張の一室。向拝の蟇股など、仏寺らしい意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007673"},{"id":"00007589","register_sub_id":"101","register_pk":"108571","name":"寶福寺庫裏","kana":"ほうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69138132,"lng":133.73435996,"geo_status":"db","era":"江戸中期／明治16・昭和60頃改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積432㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0206","desc":"玄関及び食堂の東に南面して建つ。桁行２６ｍ梁間１２ｍ規模の木造２階建。切妻造妻入本瓦葺で、正面は柱や梁、貫などを現し、中央の入口に起りのある小屋根を出す。入口土間奥に広間、両脇に知客寮や典座などを配する。近世禅院における庫裏の形態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007589"},{"id":"00007588","register_sub_id":"101","register_pk":"108570","name":"寶福寺玄関及び食堂","kana":"ほうふくじげんかんおよびじきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69132368,"lng":133.734192,"geo_status":"db","era":"江戸後期／明治中期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0205","desc":"方丈の東に南面して建つ。桁行１４ｍ梁間８．２ｍ規模。屋根は南面を軒唐破風付の入母屋造とし、本瓦葺。正面に式台を構え、その奥を玄関とし、両脇に副司寮と殿司寮、さらに廊下を介して奥に食堂を配する。山陽における臨済宗の拠点寺院の格式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007588"},{"id":"00007678","register_sub_id":"101","register_pk":"108660","name":"寶福寺山門","kana":"ほうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69096168,"lng":133.73472136,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口4.4m","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0217","desc":"仏殿の前方に東面して建つ一間一戸楼門。入母屋造桟瓦葺。上層は桁行三間梁間二間で、横板壁とし、正面中央間に両開板戸をたてる。木鼻付出組で、二軒繁垂木とする。下層は出三斗で格天井を張り、両開桟唐戸を吊る。簡明な意匠で、禅林の正面を厳かに画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007678"},{"id":"00007679","register_sub_id":"101","register_pk":"108661","name":"寶福寺山門石垣及び土塀","kana":"ほうふくじさんもんいしがきおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.6909336,"lng":133.73474763,"geo_status":"db","era":"江戸後期／昭和前期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石垣 石造、総延長52m、塀 土塀、瓦葺、総延長40m、石段付","structure_material":"石垣 石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0218","desc":"境内の東方、山門正面に石段を設け、その南北に石垣で一段高い敷地を形成し、上部に土塀を造る。北側延長２９ｍ南側延長２３ｍ、高さ２．５ｍ規模の、安山岩の切石亀甲積。土塀は総延長４０ｍで白漆喰仕上げ、瓦葺とする。山門とともに伽藍正面の構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007679"},{"id":"00007675","register_sub_id":"101","register_pk":"108657","name":"寶福寺書院","kana":"ほうふくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.6915683,"lng":133.73403319,"geo_status":"db","era":"明治中期／昭和33改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、瓦葺、建築面積72㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0214","desc":"方丈の北背面から渡廊下を介して繋がる。東西棟の入母屋造桟瓦葺で、瓦葺下屋庇を付ける。西に四畳半、東に六畳を配し、北に一間幅の畳敷、南から西面に榑縁をまわす。四畳半には西面にトコと付書院を並べ、落掛を自然木とし、趣のある居室とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007675"},{"id":"00007674","register_sub_id":"101","register_pk":"108656","name":"寶福寺鐘楼","kana":"ほうふくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69118726,"lng":133.7344464,"geo_status":"db","era":"文政元","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造、瓦葺、面積7.8㎡","structure_material":"木造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0213","desc":"方丈の東南方に位置する方一間吹放ちの鐘楼。切石積基礎上に建ち、屋根は南北棟の入母屋造本瓦葺。四方転びの方柱で、腰貫や内法貫、頭貫、台輪で固め、三斗組とする。中備に蟇股を置き、軒は一軒疎垂木。妻を小さく、勾配を緩くして、穏やかな佇まいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007674"},{"id":"00007672","register_sub_id":"101","register_pk":"108654","name":"寶福寺千尺井","kana":"ほうふくじせんじゃくせい","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69074358,"lng":133.73407,"geo_status":"db","era":"江戸前期","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"石造、面積2.4㎡","structure_material":"石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0211","desc":"仏殿の西南に位置する。東西１．５ｍ南北１．６ｍ規模で、０．１５ｍ厚の花崗岩切石を枠石とし、４枚を相欠にして井桁に組む。井戸孔内は丸石積。仏殿での行事などに使われる井戸で、境内で最も古いと伝わる。規模が大きいながら、枠石を薄くし品よく仕上げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007672"},{"id":"00007676","register_sub_id":"101","register_pk":"108658","name":"寶福寺禅堂","kana":"ほうふくじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.691444,"lng":133.73373279,"geo_status":"db","era":"文化11／明治39・昭和40頃改修","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡、井戸付","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0215","desc":"方丈西北に南面して建ち、北に井戸を付設。桁行１１ｍ梁間８．１ｍ、入母屋造妻入桟瓦葺で、正面に向拝を付ける。正面は中央に引違腰障子戸をたて、両脇間に花頭窓を穿つ。内部は左右に単を設け、中央２間幅を四半瓦敷とし、厨子を置く。禅堂の形態をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007676"},{"id":"00007592","register_sub_id":"101","register_pk":"108574","name":"寶福寺典座井戸","kana":"ほうふくじてんぞいど","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69129719,"lng":133.7344187,"geo_status":"db","era":"文化11","year":1814,"year_source":"db","year_min":1814,"year_max":1814,"year_label":null,"structure":"石造、面積1.5㎡、上屋付","structure_material":"石造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0209","desc":"庫裏典座の南方に位置する。厚さ１３㎝の花崗岩切石を井桁に組み枠石とする。方１．２ｍ高さ０．４９ｍ。その周囲に桁行２．１ｍ梁間１．８ｍ規模、切妻造本瓦葺の上屋を設ける。東・北面を開放し、他面に腰壁を設ける。近世禅院における庫裏に関連施設の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007592"},{"id":"00007680","register_sub_id":"101","register_pk":"108662","name":"寶福寺獨木橋","kana":"ほうふくじどくぼっきょ","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.690987,"lng":133.735016,"geo_status":"db","era":"文政11","year":1828,"year_source":"db","year_min":1828,"year_max":1828,"year_label":null,"structure":"石造、橋長2.9m","structure_material":"石造","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0219","desc":"山門石段の東方に位置する。長さ２．９ｍ幅３．６ｍの石造桁橋。上面をアーチ状に造る石桁３本を架し、長さ１．９ｍの板石を２列に並べ、欄干石を置き、親柱石を建てる。材は花崗岩。穏やかな反りをもつ石橋で、欄干に鎬を付けるなど丁寧なつくりになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007680"},{"id":"00007591","register_sub_id":"101","register_pk":"108573","name":"寶福寺中井戸","kana":"ほうふくじなかいど","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.691452,"lng":133.734146,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"石造、面積1.2㎡、上屋付","structure_material":"石造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0208","desc":"食堂北側の濡縁に接する。厚さ１７㎝の花崗岩切石を井桁に組み枠石とする。方１．１ｍ高さ０．４２ｍ。食堂などで使われる。井戸の周囲に桁行１．７ｍ梁間１．１ｍ規模、切妻造桟瓦葺の上屋を設ける。四隅に方柱を建て、貫等で固め、梁に釣瓶を下げる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007591"},{"id":"00007671","register_sub_id":"101","register_pk":"108653","name":"寶福寺仏殿","kana":"ほうふくじぶつでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69087723,"lng":133.7342507,"geo_status":"db","era":"享保20／文政4・明治16改修","year":1735,"year_source":"db","year_min":1735,"year_max":1735,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0210","desc":"山内南寄りに東面して建つ。桁行５間梁間５間で、一重もこし付風に造る。入母屋造本瓦葺、妻虹梁大瓶束で、正・側面は中央間を桟唐戸、両脇間を円窓とする。壁白漆喰仕上げで、上部に弓形欄間を設ける。身舎は出組詰組で、二軒扇垂木。江戸中期禅宗仏殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007671"},{"id":"00007587","register_sub_id":"101","register_pk":"108569","name":"寶福寺方丈","kana":"ほうふくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69133874,"lng":133.73392498,"geo_status":"db","era":"江戸末期／昭和中期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積486㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0204","desc":"境内地の北寄りに南面して建ち、背面に東司を付ける。入母屋造本瓦葺で、妻面は出組など組物で四重に梁を重ねる。桁行２４ｍ梁間１８ｍ規模。六間取を基本に正側面に広縁をまわし、裏方丈や茶頭寮などを付設する。地方における大規模な方丈建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007587"},{"id":"00007677","register_sub_id":"101","register_pk":"108659","name":"寶福寺方丈土塀","kana":"ほうふくじほうじょうどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.69113314,"lng":133.73376354,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土塀、瓦葺、延長65m","structure_material":"土塀","registered":"2009.04.28(平成21.04.28)","register_no":"33 － 0216","desc":"方丈前庭の南辺西寄りから西辺を画し、さらに禅堂前方で西に延びる総延長６５ｍの土塀。基礎を石垣状につくり、敷地の高低差を調整する。白漆喰仕上げで、方丈前が高さ１．４ｍで桟瓦葺、禅堂前と西辺土塀は高さ１．５ｍで、照り起りのある伏間瓦で葺く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007677"},{"id":"00007590","register_sub_id":"101","register_pk":"108572","name":"寶福寺宝蔵","kana":"ほうふくじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県総社市井尻野1968-1","lat":34.691635,"lng":133.73418406,"geo_status":"db","era":"寛政5","year":1793,"year_source":"db","year_min":1793,"year_max":1793,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0207","desc":"庫裏の後方に東西棟で建つ。桁行７．９ｍ梁間４．９ｍの土蔵造２階建、切妻造桟瓦葺。外壁は漆喰壁、腰を海鼠壁とし、四隅では海鼠壁を鉢巻まで立ち上げ、妻上部や平側の窓下端などに海鼠壁と水切り瓦をまわす。極めて丁寧に造られ、意匠的に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007590"},{"id":"00007570","register_sub_id":"101","register_pk":"108552","name":"妙教寺朝日天王社","kana":"みょうきょうじあさひてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.7103136,"lng":133.834,"geo_status":"db","era":"明治42／昭和54移築","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.8㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0187","desc":"本殿の西北に南面して建つ一間社。千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝を設ける。支輪付四手先で二、三手目にも通肘木を架し、隅方向に尾垂木を付ける。二軒繁垂木。絵様などの彫りは太く、象や唐獅子、雲など彫刻は独特の雰囲気をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007570"},{"id":"00007569","register_sub_id":"101","register_pk":"108551","name":"妙教寺荒熊天王社","kana":"みょうきょうじあらくまてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710262,"lng":133.834061,"geo_status":"db","era":"大正8／昭和54移築","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積2.1㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0186","desc":"本殿の後方に位置する一間社。千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝を設ける。切目縁を四周にまわし、腰組は出組。龍彫刻の尾垂木付三手先斗栱で、各所を彫物で飾り、扉も装飾的な格子戸とする。末社群中で最も装飾的な社殿のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007569"},{"id":"00007567","register_sub_id":"101","register_pk":"108549","name":"妙教寺縁引天王社","kana":"みょうきょうじえんびきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71011273,"lng":133.834183,"geo_status":"db","era":"明治21／昭和54移築","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0184","desc":"妙正天王社に北隣に位置する一間社流造檜皮葺。切石基礎上に石造亀腹を造り、土台を置く。身舍は円柱で、切目長押や内法長押、頭貫、台輪で固め、三斗組、一軒繁垂木とする。明治期に遡る末社のひとつ。小規模で、彫物装飾がなく、簡明な社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007567"},{"id":"00007573","register_sub_id":"101","register_pk":"108555","name":"妙教寺大乗天王社","kana":"みょうきょうじおおのりてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710251,"lng":133.833817,"geo_status":"db","era":"大正6／昭和54移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0190","desc":"羽弥御崎天王社の南に位置する一間社流造檜皮葺。正側面に擬宝珠高欄付切目縁をまわす。縁及び浜縁に縁束を建てず、二手先の挿肘木で持ち出す。身舍は円柱で、三斗組とし、向拝は几帳面取方柱で皿斗付三斗組。同時期の妙正天王社と同じ規模・形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007573"},{"id":"00007558","register_sub_id":"101","register_pk":"108540","name":"妙教寺御水舎","kana":"みょうきょうじおみずや","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.708652,"lng":133.833191,"geo_status":"db","era":"昭和29／昭和54・平成18移築","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造平屋建、瓦葺、面積12㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0175","desc":"本堂の西方に南北棟で建つ。桁行４．８ｍ梁間２．５ｍ、切妻造桟瓦葺、吹放ちとし、中央に水盤を置く。柱は方柱で脇柱を建て、柱上に三斗を組む。中備に蟇股を入れ、軒は一軒疎垂木。妻は豕叉首組とする。絵様や木鼻などに近代的な意匠をよく表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007558"},{"id":"00007574","register_sub_id":"101","register_pk":"108556","name":"妙教寺御厩舎","kana":"みょうきょうじおんきゅうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71023173,"lng":133.83377747,"geo_status":"db","era":"昭和前期／昭和54移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積5.2㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0191","desc":"大乗天王社の南に東面して建つ。桁行２．９ｍ梁間１．８ｍの切妻造妻入本瓦葺。土台上に方柱を建て、柱上に舟肘木を置く。一軒疎垂木。正面に両開戸を設け、壁を腰板張の漆喰壁とし、前寄りに窓を開ける。内部は土間床で神馬像を安置。小規模な神厩舎の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007574"},{"id":"00007555","register_sub_id":"101","register_pk":"108537","name":"妙教寺寒松軒","kana":"みょうきょうじかんしょうけん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70911796,"lng":133.8333851,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積77㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0172","desc":"庫裏の北に接し、西側は庭に面する。桁行８．９ｍ梁間９．０ｍの木造２階建、入母屋造桟瓦葺。１階は田の字型に４室を配し、主室にはトコを構える。１階はガラス戸をたて開放的にし、２階は白漆喰で塗り込め、格狭間風の窓を開ける。前面の庭園を意識した建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007555"},{"id":"00007554","register_sub_id":"101","register_pk":"108536","name":"妙教寺客殿及び庫裏","kana":"みょうきょうじきゃくでんおよびくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70896755,"lng":133.83345093,"geo_status":"db","era":"大正5／平成18改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積562㎡、渡廊下付","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0171","desc":"本堂の西北に位置する。東西棟入母屋造の客殿の東端に、南北棟切妻造の庫裏が付く。庫裏正面は柱や梁、蟇股などの架構を現し、その西方に唐破風造の大玄関を構える。屋根は本瓦葺。客殿は田の字型に４室を配し、座敷飾りを備える。重厚で風格ある構えをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007554"},{"id":"00007563","register_sub_id":"101","register_pk":"108545","name":"妙教寺五社天王社","kana":"みょうきょうじごしゃてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70999927,"lng":133.83403427,"geo_status":"db","era":"明治29／昭和54移築","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0180","desc":"霊応殿を中心にして七十七末社が配されるが、その中で唯一の五間社。本殿東側の南端に位置する。流造檜皮葺、高い切石積基壇上に建つ。出組を詰組とし、組物間に蟇股を入れる。妻は虹梁大瓶束で外に持ち出す。効果的に彫刻を用い、落ち着きのある意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007563"},{"id":"00007564","register_sub_id":"101","register_pk":"108546","name":"妙教寺三光天王社","kana":"みょうきょうじさんこうてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710049,"lng":133.834106,"geo_status":"db","era":"昭和2／昭和54移築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0181","desc":"本殿東側末社群の中央に建つ。正面一間側背面二間、千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝。身舎を出組、腰組を四手先とし、通肘木上に斗を並べる。水引虹梁や繋虹梁を龍彫刻とする他、中備や方立、脇障子、腰板など華やかな彫物装飾で充たす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007564"},{"id":"00007559","register_sub_id":"101","register_pk":"108541","name":"妙教寺山門","kana":"みょうきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70881448,"lng":133.83318444,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0176","desc":"本堂の正面西方に、西面して建つ。規模の大きな一間一戸薬医門、切妻造本瓦葺。本柱上に冠木を架し、男梁を渡し、三斗を組み、軒桁や妻虹梁大瓶束を持ち上げる。軒は二軒半繁垂木。彫物は良質で蟇股や笈形などに限定的に用いられ、構造的に見応えがある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007559"},{"id":"00007583","register_sub_id":"101","register_pk":"108565","name":"妙教寺鐘楼","kana":"みょうきょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70958456,"lng":133.83327472,"geo_status":"db","era":"文久2／昭和33・昭和54移築","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造、瓦葺、面積9.3㎡","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0200","desc":"霊応殿社殿群の西南方に位置する。亀甲積基壇上に建つ、桁行３．０ｍ梁間３．０ｍの四方吹放ちの鐘楼。入母屋造本瓦葺。方柱を腰貫と内法貫、頭貫、台輪で固め、三斗組とし、中備に蟇股を置く。標準的な方一間鐘楼で、大棟棟瓦や鯱など飾瓦が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007583"},{"id":"00007575","register_sub_id":"101","register_pk":"108557","name":"妙教寺末廣天王社","kana":"みょうきょうじすえひろてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71015927,"lng":133.83371,"geo_status":"db","era":"明治12／昭和54移築","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.65㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0192","desc":"経王殿の西側に東面して建つ。小規模な一間社で、流造檜皮葺。切石積基壇上に土台を置き、柱を建てる。身舍は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。板支輪付出組とし、妻を一段持ち出す。彫刻装飾は限定的であり、質実な意匠にまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007575"},{"id":"00007584","register_sub_id":"101","register_pk":"108566","name":"妙教寺清正公堂","kana":"みょうきょうじせいしょうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.707542,"lng":133.83501992,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.5㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0201","desc":"本堂や霊応殿などから離れた、境内の東南端に所在する。小高い位置に南面して建つ一間社で、入母屋造銅板葺。正面に一間向拝を付ける。龍彫刻とする尾垂木付三手先詰組で、縁及び浜縁の腰組を四手先斗栱とするなど、軒や縁まわりが斗栱で賑やかに飾られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007584"},{"id":"00007556","register_sub_id":"101","register_pk":"108538","name":"妙教寺太鼓楼及び渡廊下","kana":"みょうきょうじたいころうおよびわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.709145,"lng":133.833282,"geo_status":"db","era":"明治後期／大正前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"太鼓楼 木造2階建、瓦葺、建築面積6㎡、渡廊下 木造、瓦葺、面積58㎡","structure_material":"太鼓楼 木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0173","desc":"客殿北面西端から北に延びる廊下で、北端に階段室を兼ねる太鼓楼を設ける。太鼓楼は建ちの高い方２．４ｍの建築で、宝形造本瓦葺。渡り廊下は切妻造桟瓦葺で、途中に寄棟造の方３．３ｍ板敷を設ける。客殿北の庭を画し、庭園景観を構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007556"},{"id":"00007585","register_sub_id":"101","register_pk":"108567","name":"妙教寺仁王門","kana":"みょうきょうじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和中","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.708729,"lng":133.832916,"geo_status":"db","era":"昭和32","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄筋コンクリート造、面積97㎡","structure_material":"鉄筋コンクリート造","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0202","desc":"参道正面に建つ。花崗岩切石貼のＲＣ造。中央に方４．２ｍ、四隅に方３．９ｍの矩形平面を張り出す独特の構成になり、各々にドーム状の屋根を載せ、相輪を立てる。中央棟をアーチ形に開け通路とし、他には仁王像等を安置。伝統的な社頭景観において異彩を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007585"},{"id":"00007571","register_sub_id":"101","register_pk":"108553","name":"妙教寺信受・照両天王社","kana":"みょうきょうじのぶ・あきりょうてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71028867,"lng":133.83387267,"geo_status":"db","era":"昭和6／昭和54移築","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.62㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0188","desc":"本殿の西側に東面する小規模な一間社で、切石積基壇上に建つ。千鳥破風付入母屋造檜皮葺で、出組を詰組とし、二軒繁垂木。正面の一間向拝に大きく軒唐破風を付け、水引虹梁を龍、兎毛通を鳳凰の彫物として装飾するが、建物規模に対してやや大振りな印象である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007571"},{"id":"00007572","register_sub_id":"101","register_pk":"108554","name":"妙教寺羽弥御崎天王社","kana":"みょうきょうじはやみさきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710266,"lng":133.833847,"geo_status":"db","era":"大正10／昭和54移築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0189","desc":"信受・照両天王社の南に位置し、末社群中で最も規模の大きい一間社。千鳥破風付入母屋造檜皮葺で、軒唐破風付一間向拝を設ける。龍と雲の二重尾垂木を付ける三手先詰組で、向拝ほかを多くの彫刻で充たす。装飾的、様式的に密度が濃い社殿建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007572"},{"id":"00007568","register_sub_id":"101","register_pk":"108550","name":"妙教寺日車天王社","kana":"みょうきょうじひぐるまてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710209,"lng":133.83412633,"geo_status":"db","era":"明治41／昭和54移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積2.0㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0185","desc":"本殿東北に建つ一間社。千鳥破風付入母屋造檜皮葺で、正面に軒唐破風付一間向拝を設ける。尾垂木を龍彫刻とする二手先詰組で、組物間にも彫物を飾る。繋虹梁を龍の丸彫、水引虹梁の絵様を浮彫とする向拝まわりや、唐獅子の脇障子など、豊かな彫物装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007568"},{"id":"00007576","register_sub_id":"101","register_pk":"108558","name":"妙教寺秀義天王社","kana":"みょうきょうじひでよしてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710136,"lng":133.833679,"geo_status":"db","era":"明治3／昭和54移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積0.47㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0193","desc":"末廣天王社の南に位置する。一間社流造檜皮葺。切石基壇上に石造の亀腹を置き、土台建とする。身舍は円柱で、支輪付出組とし、中備に彫物を入れる。妻は虹梁大瓶束で、前に持ち出す。要所に彫物装飾を配しており、小規模ながら丁寧に造り込まれた社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007576"},{"id":"00007557","register_sub_id":"101","register_pk":"108539","name":"妙教寺宝光閣","kana":"みょうきょうじほうこうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70917176,"lng":133.83319648,"geo_status":"db","era":"明治42／昭和54改修","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋地下1階建、瓦葺及び銅板葺、建築面積97㎡","structure_material":"木造平屋地下1階建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0174","desc":"太鼓楼の西南に建つ。入母屋造で軒先銅板葺の桟瓦葺とし、千鳥破風を付ける。舟肘木で一軒疎垂木。腰板張の白漆喰壁で、南面に花頭窓を開ける。後方は道に張り出し、煉瓦造の基礎を高く建ち上げ、アーチを設ける。高い煉瓦積基礎と伝統的木造が独特の外観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007557"},{"id":"00007553","register_sub_id":"101","register_pk":"108535","name":"妙教寺本堂","kana":"みょうきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70869389,"lng":133.83356298,"geo_status":"db","era":"明治15／平成18移築","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積202㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0170","desc":"境内地の東南に西面して建つ、入母屋造本瓦葺の二重仏堂。正面三間側面六間で、背面に一間通りの位牌堂を付設し、正側面に縁をまわす。内部は凹型外陣とその奥の内陣からなり、背面に接して須弥壇を構える。禅宗仏殿の形態を受け継ぐ日蓮宗仏堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007553"},{"id":"00007566","register_sub_id":"101","register_pk":"108548","name":"妙教寺妙正天王社","kana":"みょうきょうじよしまさてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71009507,"lng":133.834152,"geo_status":"db","era":"大正6／昭和54移築","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0183","desc":"夜守天王社の北に位置する一間社流造檜皮葺。正側面に擬宝珠高欄付切目縁をまわす。正面に浜床と浜縁を付け、身舎円柱を切目長押と内法長押、頭貫、台輪で固めるなど、境内の多くの末社と共通する構造形式になる。三斗組、一軒繁垂木。装飾的要素を抑えた社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007566"},{"id":"00007565","register_sub_id":"101","register_pk":"108547","name":"妙教寺夜守天王社","kana":"みょうきょうじよもりてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71006692,"lng":133.83412931,"geo_status":"db","era":"昭和前期／昭和54移築","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0182","desc":"三光天王社の北に建つ一間社。入母屋造妻入檜皮葺で、一間向拝を付ける。浜床と浜縁を付け、身舍は四周に組高欄付縁をまわす。身舍は円柱で、切目長押や内法長押、頭貫、台輪で固め、出組を詰組とする。二軒繁垂木。向拝木鼻は複雑な絵様を彫り残す籠彫とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007565"},{"id":"00007560","register_sub_id":"101","register_pk":"108542","name":"妙教寺霊応殿経王殿","kana":"みょうきょうじれいおうでんきょうおうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.710079,"lng":133.833832,"geo_status":"db","era":"明治30／昭和54移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積59㎡、渡廊下及び小部屋付","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0177","desc":"境内の東北奥に位置する。本殿正面に建つ切妻造妻入檜皮葺で、正面は落棟で拝殿と繋ぎ、背面に唐破風造の突出部を付ける。内部は畳敷で、折上小組格天井を張り、正側面に高欄付切目縁をまわす。円柱で支輪付出組、二軒繁垂木。細部まで丁寧な仕上げになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007560"},{"id":"00007562","register_sub_id":"101","register_pk":"108544","name":"妙教寺霊応殿前殿","kana":"みょうきょうじれいおうでんぜんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.709953,"lng":133.8336854,"geo_status":"db","era":"明治19／昭和54移築","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0179","desc":"拝殿正面に繋がる桁行四間梁間一間の細長い建物。唐破風造妻入檜皮葺。方柱で、大斗肘木とし、中備に蟇股形の彫刻を飾る。梁行に虹梁を架け、菊水などを彫る笈形付大瓶束を置く。石敷で、化粧屋根裏天井。経王殿や拝殿と一体となり、荘厳な礼拝空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007562"},{"id":"00007561","register_sub_id":"101","register_pk":"108543","name":"妙教寺霊応殿拝殿","kana":"みょうきょうじれいおうでんはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.71000893,"lng":133.83375287,"geo_status":"db","era":"明治19／昭和54移築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0178","desc":"経王殿の正面に建つ。入母屋造檜皮葺。桁行三間梁間三間で、周囲を吹き放つ。正背面中央間を広くとり、虹梁を架す。布基礎石をまわし、その上に礎盤を置き円柱を建てる。平三斗で、二軒繁垂木。内部は格天井で、基礎天端にあわせて低い板床を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007561"},{"id":"00007577","register_sub_id":"101","register_pk":"108559","name":"妙教寺六社天王社一富天王社","kana":"みょうきょうじろくしゃてんのうしゃいちとみてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.7094665,"lng":133.83353811,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0194","desc":"霊応殿の社殿群から少し離れた南方の位置に、六社天王社と総称される６棟の末社群が配され、その北端に西面して建つ。一間社流造檜皮葺。組物は三斗組で、中備を略す。軒は繁垂木で、正面のみ二軒とする。妻は虹梁豕叉首組。抑制の利いた落ち着いた意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007577"},{"id":"00007580","register_sub_id":"101","register_pk":"108562","name":"妙教寺六社天王社白糸天王社","kana":"みょうきょうじろくしゃてんのうしゃしらいとてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70939425,"lng":133.83351836,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0197","desc":"大元鬼天王社の南に位置する。一間社流造檜皮葺。切石基壇上に石造亀腹を置き、土台建とする。身舎は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。三斗組で、妻は虹梁豕叉首組。一富天王社や夜守天王社と細部の特徴も含めて同じ規模・形式になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007580"},{"id":"00007579","register_sub_id":"101","register_pk":"108561","name":"妙教寺六社天王社大元鬼天王社","kana":"みょうきょうじろくしゃてんのうしゃだいげんきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70941914,"lng":133.83352515,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0196","desc":"夜守天王社の南に位置する。切石基壇上に石造亀腹を置き、土台建とする一間社流造檜皮葺。身舍は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。柱上三斗組。妻を梁上に束立とし、正背面とも一軒繁垂木、浜縁を挿肘木で支持し、繋虹梁がなく手挟とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007579"},{"id":"00007582","register_sub_id":"101","register_pk":"108564","name":"妙教寺六社天王社福崎天王社","kana":"みょうきょうじろくしゃてんのうしゃふくさきてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70935702,"lng":133.83350549,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0199","desc":"六社天王社のうち最も南に建つ一間社流造檜皮葺。切石基壇上に石造亀腹を置き、土台建。正面も一軒とし、向拝に手挟を用いるなど、大元鬼天王社に近い仕様になる。明治中期に建立された、ほぼ同じ規模・形式の社殿６棟が整然と並び建ち、厳粛な空間をつくり出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007582"},{"id":"00007581","register_sub_id":"101","register_pk":"108563","name":"妙教寺六社天王社福恵天王社","kana":"みょうきょうじろくしゃてんのうしゃふくよしてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70937791,"lng":133.83351249,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋建、檜皮葺、建築面積1.3㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0198","desc":"白糸天王社の南に建つ一間社流造檜皮葺。切石基壇上に石造亀腹を置き、土台建。円柱を切目長押や内法長押、頭貫、薄い台輪で固め、三斗組とする。妻は虹梁上に束立で、正面のみ二軒繁垂木とし、繋虹梁を略し、手挟とする。手挟や虹梁には若葉風絵様を用いる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007581"},{"id":"00007578","register_sub_id":"101","register_pk":"108560","name":"妙教寺六社天王社夜守天王社","kana":"みょうきょうじろくしゃてんのうしゃよもりてんのうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県岡山市北区高松稲荷字宮谷712他","lat":34.70944283,"lng":133.83353111,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積1.4㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"33 － 0195","desc":"一富天王社の南に位置する。一間社流造檜皮葺。切石基壇上に石造の亀腹を置き、土台建とする。身舍は円柱で、切目長押や内法長押、頭貫、薄い台輪で固める。柱上三斗組、正面のみ二軒繁垂木で、妻は虹梁豕叉首組。縁を二手先の挿肘木、浜縁を持送りで支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007578"},{"id":"00015089","register_sub_id":"101","register_pk":"529367","name":"由加神社大鳥居","kana":"ゆがじんじゃおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"岡山県","address":"岡山県倉敷市児島由加字瑜伽2852","lat":34.50561389,"lng":133.85106111,"geo_status":"db","era":"明治27年","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"炻器製、間口3.2m","structure_material":"炻器製","registered":"2024.08.15(令和6.08.15)","register_no":"33 - 0369","desc":"境内南西に位置し、西面して建つ大鳥居。柱間約三・二メートル、高さ約四・七メートル。備前焼の部材を組み上げた春日鳥居で、柱と貫の交差部や島木と笠木の一部などに一体焼成部材を用いる。高度な技術で製作した大規模備前焼作品で地域の象徴的存在の鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015089"},{"id":"00015088","register_sub_id":"101","register_pk":"529366","name":"由加神社三宝荒神社本殿","kana":"ゆがじんじゃさんぽうこうじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市児島由加字瑜伽2852","lat":34.50608333,"lng":133.85105,"geo_status":"db","era":"江戸後期／平成9年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"33 - 0368","desc":"本殿東隣に南面して建つ方一間、正面入母屋造、背面切妻造、妻入銅板葺。正面に１間向拝を付し、三方に擬宝珠高欄付の縁を廻す。身舎組物は連三斗とし、軒は二軒繁垂木、中備は蟇股。板状の頭貫木鼻など古式なつくりの本殿で、境内の歴史的な景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015088"},{"id":"00015087","register_sub_id":"101","register_pk":"529365","name":"由加神社拝殿及び幣殿","kana":"ゆがじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県倉敷市児島由加字瑜伽2852","lat":34.50591667,"lng":133.85102778,"geo_status":"db","era":"安永6年（1777）／天保9年（1838）改修","year":1777,"year_source":"db","year_min":1777,"year_max":1777,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積142㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"33 - 0367","desc":"倉敷市街南東の瑜加山に位置する神社の拝殿及び幣殿。拝殿は南面して建つ入母屋造平入で正面に３間向拝を設け千鳥破風を付し、前方に向唐破風造向拝を突出する。背面は切妻造銅板葺の幣殿を延ばす。錺金具や彫刻など装飾濃密な向拝を付し独特な形式の社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015087"},{"id":"00006576","register_sub_id":"101","register_pk":"107559","name":"龍乗院石段及び石垣","kana":"りゅうじょういんいしだんおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"岡山県","address":"岡山県玉野市東田井地1326","lat":34.55650145,"lng":133.99594039,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石段 石造8段、幅9.0m、石垣 石造、総延長37m","structure_material":"石段 石造8段","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0158","desc":"鐘楼門下に幅約９ｍの石段８段が積まれ，その西側に石垣が設置され，寺域を画している。石垣の総延長は３７ｍで，高さを２．６ｍとする。石材加工や積み方はほぼ４区画に分けられ，積まれた時期が異なる。高台に築かれた寺院固有の景観を創り出している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006576"},{"id":"00006575","register_sub_id":"101","register_pk":"107558","name":"龍乗院鐘楼門","kana":"りゅうじょういんしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"岡山県","address":"岡山県玉野市東田井地1326","lat":34.55648,"lng":133.996109,"geo_status":"db","era":"大正11","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造及び鉄筋コンクリート造楼門、瓦葺、建築面積10㎡、左右袖塀付","structure_material":"木造及び鉄筋コンクリート造楼門","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0157","desc":"高台に位置する境内の石段上方に建つ。２層で，下層はＲＣ造とし，仕上げは腰部を花崗岩貼，その上を白色小口タイル貼のモダンな意匠とする。上層は伝統的な木造で，桁行２間，梁間１間半，入母屋造，本瓦葺とする。当地で類例を見ない混合構造の構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006575"},{"id":"00006307","register_sub_id":"101","register_pk":"107290","name":"龍乗院本堂","kana":"りゅうじょういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"岡山県","address":"岡山県玉野市東田井地1326","lat":34.5566894,"lng":133.99597837,"geo_status":"db","era":"文政2／昭和57改修","year":1819,"year_source":"db","year_min":1819,"year_max":1819,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積214㎡","structure_material":"木造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"33 － 0156","desc":"寺山の麓の高台に位置する。桁行１３．６ｍ，梁間１２．２ｍ，木造平屋建，入母屋造，本瓦葺とする。６間取の方丈形式の平面をもち，東南に間口２間幅の式台玄関を付け，屋根を向唐破風造とする。妻飾り彫刻には狛犬，虎を用いるなど江戸後期らしい意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006307"},{"id":"00000097","register_sub_id":"101","register_pk":"101087","name":"厳島神社宝物館","kana":"いつくしまじんじゃほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県廿日市市宮島町118","lat":34.29477556,"lng":132.31862898,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積570㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"1996.12.20(平成8.12.20)","register_no":"34 － 0005","desc":"鉄骨鉄筋コンクリート造で，大江新太郎の設計で清水組の施工と伝える。近代的な平面をもちながら伝統的な木造建築の形態や意匠を持つ建物を，近代的な材料で造っている点に特徴がある。当時の大江新太郎の作風をよく示した建物のひとつである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000097"},{"id":"00003598","register_sub_id":"101","register_pk":"104588","name":"耕三寺銀龍閣","kana":"こうさんじぎんりゅうかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30397476,"lng":133.0909089,"geo_status":"db","era":"昭和18","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0056","desc":"境内南東方の庭園池泉に張り出して建つ。八畳大の板間の三方に縁を廻らし，東側に床と小室を設ける。屋根は宝形造の銅板葺。板間は鏡天井として龍の絵を描き，軸部はすべて銀色とする。板間の障子に花頭窓を設ける点も特徴的で，特異な意匠の建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003598"},{"id":"00003589","register_sub_id":"101","register_pk":"104579","name":"耕三寺鼓楼","kana":"こうさんじころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30447393,"lng":133.08989324,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0047","desc":"羅漢堂西側背面に建ち，鐘楼と対をなす。鐘楼と同規模同形式で，細部装飾に至るまでほぼ完全に同一である。１階は四半敷の土間とし，上層に高欄を設けない縁を出し，二手先の組物に二軒繁垂木，入母屋造，本瓦葺とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003589"},{"id":"00003585","register_sub_id":"101","register_pk":"104575","name":"耕三寺山門","kana":"こうさんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30492321,"lng":133.09015693,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄造、間口4.5m、左右袖塀付","structure_material":"鉄造","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0043","desc":"境内の北端にあって，伽藍中心軸上に位置する。柱四本を建て，中央に両開，両脇に片開の扉を吊り，両袖は瓦葺とする。柱，扉ともに鉄製で，白色を基調に随所に丹色を配し，扉には様々な絵柄の装飾を施す。街路に面して境内のランドマークとなる建造物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003585"},{"id":"00003593","register_sub_id":"101","register_pk":"104583","name":"耕三寺至心殿","kana":"こうさんじししんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.303974,"lng":133.089951,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0051","desc":"伽藍最上段西側に建ち，信楽殿と対をなす。法界寺阿弥陀堂を模したと伝えられ，５間四方の身舎に吹き放しの裳階を設け，屋根は宝形造銅板葺。組物は平三斗で，裳階の正面中央部のみ一段高く屋根を設ける。内部は１室とし，各種用途として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003593"},{"id":"00003588","register_sub_id":"101","register_pk":"104578","name":"耕三寺鐘楼","kana":"こうさんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30452873,"lng":133.09048083,"geo_status":"db","era":"昭和15","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0046","desc":"羅漢堂東側背面に建ち，鼓楼と同じ規模形式を持つ。桁行３間，梁間２間，入母屋造，本瓦葺で，白漆喰塗の袴腰を備える。新薬師寺鐘楼を模したもので，上部に高欄を持たない縁を張り出す。上層内部は中央部を吹き抜けとし，両側に床を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003588"},{"id":"00003594","register_sub_id":"101","register_pk":"104584","name":"耕三寺信楽殿","kana":"こうさんじしんぎょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30402628,"lng":133.09055142,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0052","desc":"伽藍最上段の東側に建つ。至心殿とは対をなし，同規模同形式とするが，平面などに若干の違いがある。身舎柱は円柱，裳階柱は角柱で，講堂として用いられる身舎内部は１室とし，天井は折上小組格天井。四周外壁は蔀戸を見せるが，内側には壁が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003594"},{"id":"00003592","register_sub_id":"101","register_pk":"104582","name":"耕三寺僧宝蔵","kana":"こうさんじそうほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.304272,"lng":133.090485,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0050","desc":"伽藍中段東側に建ち，同型同規模の法宝蔵と五重塔をはさんで対をなす。四天王寺金堂を参照しつつ大きく外観を変え，身舎は円柱に二手先，裳階は角柱に平三斗とし，内部は折上格天井の大空間とする。昭和前期における大規模木造寺院建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003592"},{"id":"00003596","register_sub_id":"101","register_pk":"104586","name":"耕三寺多宝塔","kana":"こうさんじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30377986,"lng":133.08987097,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積25㎡","structure_material":"木造多宝塔","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0054","desc":"本堂西方に建つ。石山寺多宝塔を模しており，下層は方３間の周囲に縁を廻らし，上層は円形平面で四手先組物で二軒繁垂木の軒を支え，屋根は上層下層とも銅板葺とする。比較的原作に忠実であり，組物等に彩色を施した外観は壮麗である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003596"},{"id":"00003586","register_sub_id":"101","register_pk":"104576","name":"耕三寺中門","kana":"こうさんじちゅうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.3048091,"lng":133.09014972,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造、瓦葺、建築面積46㎡","structure_material":"木造","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0044","desc":"四間二戸の二重門で，入母屋造，本瓦葺。法隆寺の西院伽藍の中門を原型とするが，梁間は二間とし，各部比例も異なる。組物等の装飾はおおむね原型を踏襲しているが，飾金具，彩色などを多用して壮麗な外観としている。中心伽藍の北方を画す建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003586"},{"id":"00003597","register_sub_id":"101","register_pk":"104587","name":"耕三寺八角円堂","kana":"こうさんじはっかくえんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30384166,"lng":133.09066872,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積71㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0055","desc":"本堂を挟んで多宝塔と対置される。正八角形平面を持ち，屋根は宝形造，本瓦葺。法隆寺東院夢殿を模しているが，規模を縮小している。柱は八角柱で，組物は隅部出三斗，中備は平三斗，内部は板敷で，中央を鏡天井，周囲を格天井とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003597"},{"id":"00003590","register_sub_id":"101","register_pk":"104580","name":"耕三寺仏宝蔵","kana":"こうさんじぶっぽうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.304546,"lng":133.09082952,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0048","desc":"一連の伽藍からはやや東寄りに建つ，桁行５間，梁間２間，平入，入母屋造，本瓦葺の宝蔵。内部は板敷で一室とする。耕三寺の建築の中では比較的簡素で，新薬師寺本堂を模したとされるが，規模，各柱間に長押，連子窓を設ける外観など大きく異なる点が多い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003590"},{"id":"00003591","register_sub_id":"101","register_pk":"104581","name":"耕三寺法宝蔵","kana":"こうさんじほうほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.304237,"lng":133.089951,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0049","desc":"伽藍中段に建つ宝物館で，僧宝蔵と対をなす。桁行４間，梁間３間の身舎四周に裳階を廻らす。屋根は入母屋造，本瓦の錣葺とする。四天王寺金堂を模したといわれるが，法宝蔵は妻入であり，屋根勾配，各部比例なども大きく異なる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003591"},{"id":"00003595","register_sub_id":"101","register_pk":"104585","name":"耕三寺本堂","kana":"こうさんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.30375935,"lng":133.09028052,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積271㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0053","desc":"中堂，左右翼廊，尾廊からなる堂宇。いずれも本瓦葺とし，軸部，壁面，建具に至るまで極彩色を施し，飾金具を用いる。平等院鳳凰堂を模しているが，細部においては異なる点も多く，内部外部とも壮麗さを増しており，耕三寺の中核建築として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003595"},{"id":"00003587","register_sub_id":"101","register_pk":"104577","name":"耕三寺羅漢堂","kana":"こうさんじらかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県尾道市瀬戸田町瀬戸田553-2","lat":34.3048338,"lng":133.09048393,"geo_status":"db","era":"昭和14","year":1939,"year_source":"db","year_min":1939,"year_max":1939,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積346㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"34 － 0045","desc":"中門の両側に続く回廊状の建築で，内部に羅漢像を安置する。左右とも桁行１７間，梁間１間の規模で，本瓦葺，切妻造とする。外側壁面を連子窓，内側を板扉とし，内部は板敷。小屋は虹梁，扠首組に化粧屋根裏とする。中心伽藍の中では最も初期の建築である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003587"},{"id":"00013340","register_sub_id":"101","register_pk":"366329","name":"榊󠄀森神社拝殿","kana":"さかきもりじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県安芸郡熊野町新宮八丁目601-2","lat":34.37038889,"lng":132.61719167,"geo_status":"db","era":"明治16年頃","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0282","desc":"本殿の南に渡殿及び幣殿を介し、南面して建つ。木造平屋建、正面入母屋造桟瓦葺で、背面の渡殿及び幣殿と一体に屋根を葺く。内部は一室で、出三斗に丸太梁を桁行に掛け現しとし、その上に天井を張る。入母屋造妻入の屋根は境内空間の象徴的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013340"},{"id":"00013339","register_sub_id":"101","register_pk":"366328","name":"榊󠄀森神社本殿","kana":"さかきもりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸郡熊野町新宮八丁目601-2","lat":34.37049444,"lng":132.61726111,"geo_status":"db","era":"江戸末期／明治16年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0281","desc":"町の北部に位置し、石段を登った境内地の北西に南面して建つ。三間社流造銅板葺で、背面を除く三方に高欄付の縁を廻す。組物は出組で、中備を蟇股とする。妻飾りは二重虹梁蟇股で、棟木を大瓶束で受ける。庇の間の海老虹梁や欄間、板支輪などを彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013339"},{"id":"00013335","register_sub_id":"101","register_pk":"366324","name":"榊山八幡神社護国神社本殿","kana":"さかきやまはちまんじんじゃごこくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31794444,"lng":132.81141389,"geo_status":"db","era":"昭和28年頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0277","desc":"拝殿前方の参道に東面して建つ、村内戦没者を祀る小社。正面一間、側面二間、流造銅板葺で、正側面に縁を廻して脇障子を建て、浜縁を設ける。身舎は粽付円柱で、台輪を廻して三斗を組み、正面桟唐戸や蟇股を菊花紋の彫刻で飾る。参道沿いの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013335"},{"id":"00013333","register_sub_id":"101","register_pk":"366322","name":"榊山八幡神社神門及び塀","kana":"さかきやまはちまんじんじゃしんもんおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.3184,"lng":132.81142778,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"神門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長78m","structure_material":"神門 木造","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0275","desc":"本殿の四周を囲繞する切妻造本瓦葺の神門と桟瓦葺の塀。神門は一間腕木門で、本柱後方に控柱を立て、上部を格子とした両開桟唐戸を吊る。塀は真壁漆喰塗で、腰上に竪格子を嵌める。簡素ながら上質なつくりで、森厳な本殿周りの景観を格調高く整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013333"},{"id":"00013336","register_sub_id":"101","register_pk":"366325","name":"榊山八幡神社随身門","kana":"さかきやまはちまんじんじゃずいじんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31762222,"lng":132.81154444,"geo_status":"db","era":"天明2年(1782)頃／昭和10年代改修","year":1782,"year_source":"db","year_min":1782,"year_max":1782,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0278","desc":"参道の中段に南面して建つ。三間一戸八脚門、入母屋造銅板葺で、組物は出三斗で二軒半繁垂木とする。広く取った中央間は門扉を設けず吹放ち、両脇間後方を格子戸と板壁で区画して随身像と狛犬を祀る。境内唯一の近世建築で、参道景観に風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013336"},{"id":"00013332","register_sub_id":"101","register_pk":"366321","name":"榊山八幡神社拝殿及び幣殿","kana":"さかきやまはちまんじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31833889,"lng":132.81144167,"geo_status":"db","era":"明治40年／昭和58年改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0274","desc":"本殿正面石段下に南面して建つ。入母屋造銅板葺、軒唐破風付一間向拝付で背面に幣殿を張出す。拝殿は平三斗組、二軒繁垂木、中備は彫刻蟇股とし、正面一間通りを吹放し、四周に縁を廻す。幣殿は舟肘木、一軒繁垂木と簡素につくる。社頭景観を重厚に演出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013332"},{"id":"00013331","register_sub_id":"101","register_pk":"366320","name":"榊山八幡神社本殿","kana":"さかきやまはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31849167,"lng":132.81144167,"geo_status":"db","era":"明治40年／昭和前期改修","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0273","desc":"海を臨む丘上にある神社。本殿は境内北奥の上段に南面して建つ。方三間、入母屋造銅板葺、正面千鳥破風、軒唐破風付一間向拝付。四周に縁を廻して浜縁を設ける。組物は出組、二軒繁垂木とし、板支輪や木鼻、蟇股などを彫刻で飾る。重厚なつくりの本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013331"},{"id":"00013334","register_sub_id":"101","register_pk":"366323","name":"榊山八幡神社松尾神社本殿","kana":"さかきやまはちまんじんじゃまつおじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市安芸津町三津字榊山5513","lat":34.31862778,"lng":132.81150278,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.5㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"34 － 0276","desc":"酒造関係者により京都の松尾大社より勧請され、本殿北東に南面して建つ小社。一間社流造銅板葺で、正側面に縁を廻して脇障子を建て、浜縁を設ける。身舎は粽付円柱で、台輪を廻して三斗を組み、海老虹梁で庇と繋ぐ。地域の酒造業繁栄の歴史を物語る社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013334"},{"id":"00008777","register_sub_id":"101","register_pk":"149498","name":"照林坊御成の間","kana":"しょうりんぼうおなりのま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80890542,"lng":132.84714642,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"converted","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積117㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0118","desc":"客殿の東南に廊下を介して続く。入母屋造桟瓦葺で、周囲に下屋をまわす。東西に3室を並べ、周囲に縁をまわし、南背面に浴室や便所を付設する。東端を主室とし、トコやトコ脇、付書院を構える。各室に棹縁天井を張り、砂壁として、落ち着きのある設えをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008777"},{"id":"00008781","register_sub_id":"101","register_pk":"149502","name":"照林坊鐘撞堂","kana":"しょうりんぼうかねつきどう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80918661,"lng":132.84763899,"geo_status":"db","era":"江戸中期／延享元年(1744)・平成6年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、面積16㎡","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0122","desc":"本堂の東南に位置する。切石積基壇に建つ桁行1間梁間1間の吹放ち鐘楼。入母屋造桟瓦葺。礎盤に粽付円柱を内転びにたて、貫や台輪で固め、尾垂木付二手先斗栱を組む。柱間中央にも斗栱を置き、その間に蟇股を飾る。二軒繁垂木。近世建立になる良質な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008781"},{"id":"00008776","register_sub_id":"101","register_pk":"149497","name":"照林坊客殿","kana":"しょうりんぼうきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80903913,"lng":132.84700878,"geo_status":"db","era":"昭和9年／昭和61年改修","year":1934,"year_source":"converted","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積196㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0117","desc":"本堂の西南に位置する。入母屋造妻入本瓦葺、正面に唐破風造玄関を付け、周囲に下屋をまわす。内部は対面所と、座敷飾りを備える座敷に2分され、対面所は大トコを構える17畳半で、側面に鞘の間、前方に玄関の間を付ける。近代における真宗対面所の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008776"},{"id":"00008780","register_sub_id":"101","register_pk":"149501","name":"照林坊経蔵","kana":"しょうりんぼうきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.8094786,"lng":132.84752396,"geo_status":"db","era":"江戸中期／宝暦2年(1752)・明治45年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造平屋建、瓦葺、建築面積20㎡","structure_material":"土蔵造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0121","desc":"本堂の東北に南面して建つ。方3.8ｍの土蔵造、宝形造桟瓦葺で、1間向拝を付ける。鉢巻上に台輪を置き、出三斗組とし、中備に蟇股を飾る。軒は一軒繁垂木。内部は1室の板敷で、格天井を張る。見応えのある組物や蟇股、彫物などが各所に配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008780"},{"id":"00008778","register_sub_id":"101","register_pk":"149499","name":"照林坊庫裏","kana":"しょうりんぼうくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80917677,"lng":132.84682395,"geo_status":"db","era":"享和元年(1801)","year":1801,"year_source":"converted","year_min":1801,"year_max":1801,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積315㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0119","desc":"本堂の後方に位置する。切妻造妻入桟瓦葺で、北・東面に下屋を付ける。桁行22ｍ梁間14ｍの大規模な庫裏で、正面寄りに土間を設け、東を大戸口、西を勝手口とする。居室部は梁行を3分して東列に畳敷を並べ、南奥に御内仏がある。近世の本格的な庫裏建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008778"},{"id":"00008782","register_sub_id":"101","register_pk":"149503","name":"照林坊山門","kana":"しょうりんぼうさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80929869,"lng":132.84779826,"geo_status":"db","era":"寛文5年(1665)／昭和中期改修","year":1665,"year_source":"converted","year_min":1665,"year_max":1665,"year_label":null,"structure":"木造、銅板葺、間口3.3m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0123","desc":"本堂の前方に位置する。間口3.3ｍの四脚門。切妻造銅板葺で、正・背面に軒唐破風を付ける。組物は支輪付の出組で、正・背面は詰組に配する。二軒繁垂木。妻虹梁大瓶束。格天井を張り、両開板戸をたてる。繰形は複雑で、絵様も繊細で手が込んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008782"},{"id":"00008775","register_sub_id":"101","register_pk":"149496","name":"照林坊本堂","kana":"しょうりんぼうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80931048,"lng":132.8472644,"geo_status":"db","era":"嘉永5年(1852)／明治期・昭和33年改修","year":1852,"year_source":"converted","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積629㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0116","desc":"境内の中央に東面して建つ。外陣と内陣、余間からなり、正面に広縁を設け、周囲の縁先に庇柱をたて、背面に後堂を設ける大規模な真宗本堂。入母屋造本瓦葺で、正面に向拝を付設。矢来内がなく、また当初は正面縁を側面前方へまわすなど、特徴的な平面となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008775"},{"id":"00008779","register_sub_id":"101","register_pk":"149500","name":"照林坊渡り廊下","kana":"しょうりんぼうわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"広島県","address":"広島県三次市三次町1280","lat":34.80923183,"lng":132.84702058,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"34 － 0120","desc":"本堂と庫裏を繋ぐ東西棟の廊下。桁行21ｍ梁間2.9ｍ、両下造桟瓦葺。高く床を張り、化粧屋根裏天井、側柱筋には高欄を付ける。花頭窓を穿つ漆喰壁で南北に間仕切り、複廊とする。床下も中央筋に壁を設け、仕切る。寺格の高さを窺わせる建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008779"},{"id":"00013190","register_sub_id":"101","register_pk":"368414","name":"専教寺山門","kana":"せんきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"広島県","address":"広島県安芸高田市高宮町船木字東福田1506-1","lat":34.77431389,"lng":132.75169444,"geo_status":"db","era":"大正3年","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造、瓦葺、間口3.9m、左右袖塀付","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"34 － 0263","desc":"本堂の正面に西面して建つ。切妻造桟瓦葺の四脚門で、親柱は円柱、控柱は角柱で絵様付の虹梁を渡す。軒は二軒繁垂木、妻飾は笈形付大瓶束で破風に蕪懸魚を吊る。虹梁は菊水、木鼻は唐獅子や象、獏、大瓶束は邪鬼等多彩な彫刻で飾る。境内の表構えを形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013190"},{"id":"00013189","register_sub_id":"101","register_pk":"368413","name":"専教寺納骨堂","kana":"せんきょうじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和中","pref":"広島県","address":"広島県安芸高田市高宮町船木字東福田1506-1","lat":34.77453333,"lng":132.75171667,"geo_status":"db","era":"昭和中期","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"34 － 0262","desc":"境内北端に南面して建つ。正面三間側面二間、宝形造桟瓦葺で、正面中央に両折桟唐戸と両脇に花頭窓を設け、彫刻欄間を嵌める。内部は畳敷の一室で、奥に仏像を安置する。柱頭は虹梁形頭貫と木鼻、台輪、尾垂木付一手先の組物で飾る。均整のとれた外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013189"},{"id":"00013188","register_sub_id":"101","register_pk":"368412","name":"専教寺本堂","kana":"せんきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市高宮町船木字東福田1506-1","lat":34.77434167,"lng":132.75198611,"geo_status":"db","era":"寛政6年（1794）／大正2年・平成6年改修","year":1794,"year_source":"db","year_min":1794,"year_max":1794,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積408㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"34 － 0261","desc":"安芸高田市北東部にある真宗本堂。外陣正面柱間七間と大規模で、内部を円柱、側廻りを角柱とし、広い畳敷の外陣、装飾的な内外陣境、内陣背後の後門等真宗本堂の典型的な平面である。向拝廻りの彫刻、外縁の格天井等随所を豪華に飾る江戸後期真宗本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013188"},{"id":"00010350","register_sub_id":"101","register_pk":"199123","name":"南禅坊山門","kana":"なんぜんぼうさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市鞆町後地字草谷甲1339","lat":34.384163,"lng":133.379296,"geo_status":"db","era":"江戸中期／文化7年(1810)改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積5.1㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0142","desc":"境内東方に開く。一間一戸四脚門の上部に方一間で入母屋造本瓦葺の上層を増築し、鐘楼を吊る。木部には全体に弁柄が塗られ、上層正背面に火灯窓、両側面に円窓を穿ち、軒先には強い反りをみせ、異国情緒を漂わせる。朝鮮通信使寄港地である鞆の浦の情景を彩る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010350"},{"id":"00010349","register_sub_id":"101","register_pk":"199122","name":"南禅坊本堂","kana":"なんぜんぼうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県福山市鞆町後地字草谷甲1339","lat":34.384272,"lng":133.379041,"geo_status":"db","era":"江戸末期／昭和40年・平成7年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積315㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0141","desc":"鞆町西側の寺院群内に構える境内に東面する。桁行一六メートル梁間一七メートル、入母屋造本瓦葺で一間向拝を付す。内部を内陣、余間、外陣に区分し、前面に吹放ちの広縁、三方に落縁を廻す典型的な真宗本堂平面で、要所に時代相応の発達した装飾を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010349"},{"id":"00010352","register_sub_id":"101","register_pk":"199125","name":"福泉坊庫裏","kana":"ふくせんぼうくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.663143,"lng":132.707991,"geo_status":"db","era":"江戸末期／平成25年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積209㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0144","desc":"本堂から渡廊下を介して接続して建つ。北端を土間として南側に座敷などの居室を二列並べる平面で、南列中央間は仏間とする。西列の一部では側柱を一間毎に立て、また仏壇部分は旧規は浅い押床としていた点など古様を示し、当地の真宗寺院庫裏の一例となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010352"},{"id":"00010354","register_sub_id":"101","register_pk":"199127","name":"福泉坊山門","kana":"ふくせんぼうさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.663278,"lng":132.707598,"geo_status":"db","era":"文政13年(1830)／平成16年移築","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造、瓦葺、間口2.4m","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"34-0146","desc":"本堂正面の西方に建つ。間口二・四メートルの一間薬医門で、切妻造桟瓦葺とする。男梁上に三斗を並べて桁と虹梁を受け、軒は二軒繁垂木である。棟通り虹梁上を雲龍彫刻で埋め、虹梁や男梁鼻の絵様繰形を江戸末期らしい華やかなものとして境内正面を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010354"},{"id":"00010353","register_sub_id":"101","register_pk":"199126","name":"福泉坊鐘楼","kana":"ふくせんぼうしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.663103,"lng":132.707634,"geo_status":"db","era":"昭和29年","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"木造、瓦葺、面積9.4㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"34-0145","desc":"境内西方に本堂と隣接して建つ一間四方の吹放ち鐘楼で、入母屋造桟瓦葺である。切石積基壇上に石製礎盤を置き、丸柱を四方転びに立てて腰貫と頭貫、台輪で固め、尾垂木付の出組を詰組とする。細部絵様や組物の充実した鐘楼で、真宗寺院伽藍を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010353"},{"id":"00010351","register_sub_id":"101","register_pk":"199124","name":"福泉坊本堂","kana":"ふくせんぼうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和中","pref":"広島県","address":"広島県安芸高田市吉田町吉田字下川東1334-1","lat":34.662989,"lng":132.707805,"geo_status":"db","era":"昭和23年／平成25年改修","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積404㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"34-0143","desc":"郡山旧城下の境内奥に建ち、桁行一九メートル梁間二一メートル、入母屋造桟瓦葺である。外陣は矢来と柱を省いた広闊な一室とし、内外陣境では七間分の欄間を跨ぐ一対の龍を彫り、外陣組物には斜栱を用いる等、当地で名工と謳われた西谷庄一の力量を示す本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010351"},{"id":"00008572","register_sub_id":"101","register_pk":"134968","name":"佛通寺多宝塔","kana":"ぶっつうじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三原市高坂町許山30-1","lat":34.45459221,"lng":133.02681857,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積18㎡","structure_material":"木造多宝塔","registered":"2011.01.26(平成23.01.26)","register_no":"34 － 0105","desc":"境内の高台に建ち、間口、奥行とも四・三メートル、三間多宝塔、銅板葺で、縁高欄をめぐらす。軸部は和様を基調とし、組物は下層出組、上層四手先とする。蟇股等の細部に流麗な彫刻を施し、軒まわり部材に反りをもたせるなど整った塔姿をもつ近代の多宝塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008572"},{"id":"00014949","register_sub_id":"101","register_pk":"519209","name":"明覚寺山門","kana":"みょうかくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"広島県","address":"広島県三次市吉舎町吉舎字七日市462","lat":34.715525,"lng":132.99096111,"geo_status":"db","era":"明治2年","year":1869,"year_source":"db","year_min":1869,"year_max":1869,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0309","desc":"境内東面中央に開く、切妻造桟瓦葺の四脚門。主柱を円柱、控柱を角柱とし、主柱間の冠木の上方に前後の控柱を繋ぐ頭貫を通した特異な形式。台輪上には拳鼻付平三斗を詰組に配し、軒は一軒繁垂木。門口には板戸を吊る。組物賑やかな山門で通りの景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014949"},{"id":"00014948","register_sub_id":"101","register_pk":"519208","name":"明覚寺鐘堂","kana":"みょうかくじしょうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"広島県","address":"広島県三次市吉舎町吉舎字七日市462","lat":34.71543333,"lng":132.99094444,"geo_status":"db","era":"明治25年／昭和中期改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造、瓦葺、面積6.8㎡","structure_material":"木造","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0308","desc":"本堂の東南に位置する鐘堂。基壇上に建つ一間四方入母屋造桟瓦葺の南北棟。礎石に円柱を四方内転びに立てて腰貫、頭貫で固めて、三斗を組み、中備は蟇股、軒は一軒繁垂木。内部は竿縁天井を張って梵鐘を吊る。通りに面して建ち、地域の歴史的景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014948"},{"id":"00014947","register_sub_id":"101","register_pk":"519207","name":"明覚寺本堂","kana":"みょうかくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県三次市吉舎町吉舎字七日市462","lat":34.71554444,"lng":132.99071389,"geo_status":"db","era":"昭和3年／令和2年移築","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積284㎡","structure_material":"木造平屋建","registered":"2024.03.06(令和6.03.06)","register_no":"34 - 0307","desc":"石見銀山街道の吉舎宿にある真宗寺院の本堂。東京の両国にあった慈光院本堂を移築したもの。境内に東面して建つ入母屋造桟瓦葺の七間堂で間口の広い向拝を付す。外陣は土間をコの字に廻らした斬新な平面で、小屋組にトラスを用いる。良質な近代和風の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014947"},{"id":"00006713","register_sub_id":"101","register_pk":"107696","name":"明眼寺本堂","kana":"みょうげんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"広島県","address":"広島県東広島市福富町下竹仁字土井沖488-3","lat":34.526657,"lng":132.742767,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積299㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"34 － 0084","desc":"桁行７間梁間９間半、入母屋造桟瓦葺の浄土真宗本堂で、右手奥に８畳２室の座敷を張り出す。正面は吹放ちの広縁とし、正・側面には擬宝珠高欄付の切目縁を廻し、１間向拝を付ける。工匠は安芸高田の西谷庄一で、斜栱に尾垂木を加えるなど独特な組物とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006713"},{"id":"00012648","register_sub_id":"101","register_pk":"367942","name":"赤間神宮水天門及び回廊","kana":"あかまじんぐうすいてんもんおよびかいろう","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"山口県","address":"山口県下関市阿弥陀寺町5-2","lat":33.958561,"lng":130.948288,"geo_status":"geocoded","era":"昭和32年／平成2年増築","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"水天門 鉄筋コンクリート造及び木造2階建、銅板葺、建築面積77㎡ 回廊 木造、銅板葺、建築面積25㎡","structure_material":"水天門 鉄筋コンクリート造及び木造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"35 － 0098","desc":"壇ノ浦を望む境内正面の石垣上に南面して建つ竜宮造の楼門。入母屋造銅板葺に鴟尾を飾り、東西に回廊を延ばす。鉄筋コンクリート造で上層軸部や組物等を木造とし、腰組に人字形割束を配する。特異な形式と鮮やかな色調で、関門海峡のシンボルとなる大型の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012648"},{"id":"00014204","register_sub_id":"101","register_pk":"508834","name":"川崎観音堂山門","kana":"かわさきかんのんどうさんもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県周南市川崎二丁目511-1","lat":34.07375556,"lng":131.77957778,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"石造及び木造二階建、瓦葺、建築面積11㎡","structure_material":"石造及び木造二階建","registered":"2022.02.17(令和4.02.17)","register_no":"35-0106","desc":"山陽道富田にある周防国三十三観音霊場札所の本堂高台下にある竜宮門風の鐘楼門。下層石造、上層木造の二階建入母屋造桟瓦葺平入、二階は角柱に舟肘木で桁を受け、全面に花頭窓を配し、内部は格天井とする。石段や高台上の境内と共に歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014204"},{"id":"00014203","register_sub_id":"101","register_pk":"508833","name":"川崎観音堂本堂","kana":"かわさきかんのんどうほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県周南市川崎二丁目511-1","lat":34.07397778,"lng":131.77978889,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"35-0105","desc":"山陽道富田を見渡す高台にある、周防国三十三観音霊場札所の仏堂。入母屋造桟瓦葺平入、妻飾り虹梁大瓶束、軒は出組に隅扇垂木、正面向拝は各所に繰形や彫刻を施す。内部は折上げ格天井、奥に壇を設ける。禅宗様の装飾を丁寧に施す小堂で地域の崇敬を集める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014203"},{"id":"00014205","register_sub_id":"101","register_pk":"508835","name":"川崎観音堂門柱","kana":"かわさきかんのんどうもんちゅう","category":"宗教","subcategory":"その他工作物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県周南市川崎二丁目511-1","lat":34.07390833,"lng":131.77974722,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石造、間口2.9m","structure_material":"石造","registered":"2022.02.17(令和4.02.17)","register_no":"35-0107","desc":"山陽道富田にある周防国三十三観音霊場札所の高台を登る石段の先で、本堂正面に位置する石造門柱一対。高さ約二・六メートル、御影石製角柱、江戸切り仕上。柱頭は丸みを帯びた造出しで繰形を施す。後設の照明も意匠に配慮する。高台の境内のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014205"},{"id":"00001534","register_sub_id":"101","register_pk":"102524","name":"錦雲閣","kana":"きんうんかく","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県岩国市横山2-8内","lat":34.17119276,"lng":132.17627621,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造2階建、瓦葺、建築面積123㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"35 － 0034","desc":"旧岩国藩主吉川家の歴代を祀る吉香神社の絵馬堂。桁行６間梁行４間，身舎５間×３間の入母屋造，桟瓦葺，楼閣風建築で，吉香公園内に偉容を誇る。階下は土間敷で，外周は入口を除き腰を板壁として内側に腰掛縁を設ける。階上は板敷で高欄付切目縁を廻す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001534"},{"id":"00004299","register_sub_id":"101","register_pk":"105289","name":"功山寺総門","kana":"こうざんじそうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市長府川端1-2-3","lat":33.9956811,"lng":130.98330455,"geo_status":"db","era":"室町時代","year":1454,"year_source":"estimated","year_min":1333,"year_max":1572,"year_label":"室町時代","structure":"木造、瓦葺、間口4.4m","structure_material":"木造","registered":"2004.07.23(平成16.07.23)","register_no":"35 － 0044","desc":"本柱を棟木際まで延ばす禅宗様の四脚門で，国宝仏殿のある伽藍東側正面にある。円形柱座をもつ礎石に円柱を立て，貫で固め，桁行方向の頭貫位置には舟肘木と軒桁を柱頭に入れ，垂木を受ける。軒廻りは大幅に改変されたが，軸部は室町中期の形式を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004299"},{"id":"00009830","register_sub_id":"101","register_pk":"195659","name":"護國寺清正公堂","kana":"ごこくじせいしょうこうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市上田中町2-15-7","lat":33.9635885,"lng":130.94145496,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0074","desc":"本堂南に東面する小堂で、入母屋造桟瓦葺の外陣奥に切妻造の内陣を突出する。外陣に濡縁を廻らせ正面に切妻向拝を設ける。内外陣境は床を上げて結界を設け、最奥の須弥壇は五区分して中央に加藤清正像を祀る。外部は和様で、須弥壇廻りには禅宗様を取入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009830"},{"id":"00009831","register_sub_id":"101","register_pk":"195660","name":"護國寺納骨堂","kana":"ごこくじのうこつどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県下関市上田中町2-15-7他","lat":33.96352949,"lng":130.94151301,"geo_status":"db","era":"大正10／昭和6頃改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積8.4㎡、銅製記念塔付","structure_material":"鉄筋コンクリート造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0075","desc":"境内の南寄りに位置する方二・九メートルの鉄筋コンクリート造で、昭和初期に現在の規模に拡張した。陸屋根で、上部に方円二段の台座上に円筒形の銅製記念塔を載せ、総高五・六メートルとする。外壁は化粧目地入モルタル塗とし、隅柱や背面戸口の額縁を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009831"},{"id":"00003312","register_sub_id":"101","register_pk":"104302","name":"護國寺本堂","kana":"ごこくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市上田中町2-11-10","lat":33.963699,"lng":130.941452,"geo_status":"db","era":"昭和4","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積160㎡","structure_material":"木造平屋建","registered":"2003.03.18(平成15.03.18)","register_no":"35 － 0042","desc":"市街の山裾に東面して建つ日蓮宗の本堂建築。精巧な石積基壇を築き，入母屋造，妻入で，奥行きのある平面とする。比較的細い柱や長押・貫で，平明な外壁をつくり，腰を簓子下見板張とする。正面玄関に設けた唐破風庇が特徴的で，地域景観の核になっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003312"},{"id":"00009832","register_sub_id":"101","register_pk":"195661","name":"護國寺門柱","kana":"ごこくじもんちゅう","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県下関市上田中町2-15-7","lat":33.96361753,"lng":130.94153205,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"石造門柱2基、間口2.8m","structure_material":"石造門柱2基","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0076","desc":"参道の石段を上り詰めた境内の東正面に開く門で、石製の門柱一対からなる。門柱間二・八メートルで高さ二・七メートルとする。御影石の角柱を瘤出し仕上として各面周囲に平滑面をとり、両柱とも背面に刻銘をもつ。頂部の、丸みを帯びた造り出しが印象的な門柱。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009832"},{"id":"00009381","register_sub_id":"101","register_pk":"194174","name":"春風楼","kana":"しゅんぷうろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山口県","address":"山口県防府市松崎町69-1","lat":34.06305731,"lng":131.57341644,"geo_status":"db","era":"明治6年／昭和59年・平成17年改修","year":1873,"year_source":"db","year_min":1873,"year_max":1873,"year_label":null,"structure":"木造2階建、瓦葺、建築面積212㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"35 － 0071","desc":"防府天満宮境内の西南隅に北面して建つ。一七・五メートル四方、二階建、入母屋造桟瓦葺のもと参籠所で、四周に縁を廻らし正面に石階を付す。建設が頓挫した五重塔の部材を引継ぎ、床下廻りに塔初層の組物を使用する。楼閣風で独特な形式になる神社建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009381"},{"id":"00013761","register_sub_id":"101","register_pk":"505321","name":"瑞松庵山門","kana":"ずいしょうあんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県宇部市大字船木字瑞松庵1581","lat":34.04029722,"lng":131.21268889,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、茅葺、間口3.1m、左右袖塀付","structure_material":"木造","registered":"2021.02.26(令和3.02.26)","register_no":"35 － 103","desc":"入母屋造茅葺の一間楼門。左右に袖塀を付属する。下層は角柱の本柱前後に控柱を立て、三段の貫で繋ぐ。柱間は開放。上層は円柱を立て、桁行三間梁間三間で、四面とも中央間を開放とし、縁に禅宗様高欄を廻らす。小振りながら古刹の表構えの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013761"},{"id":"00012046","register_sub_id":"101","register_pk":"210987","name":"住吉神社唐門及び透塀","kana":"すみよしじんじゃからもんおよびすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市一の宮住吉一丁目1162-2","lat":33.999668,"lng":130.956557,"geo_status":"db","era":"明治34年頃／明治42年増改築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"唐門 木造、檜皮葺、間口2.5m 透塀 木造、こけら葺、総延長79m","structure_material":"唐門 木造","registered":"2017.10.27(平成29.10.27)","register_no":"35-97","desc":"本殿と拝殿の間に建つ檜皮葺の向唐門と左右にのびるこけら葺の透塀。門の本柱は円柱として三斗を組み、虹梁を架ける。控柱は角柱に舟肘木を乗せ、細部には復古的意匠を用いる。透塀は中間に菱格子を組み、上下に吹寄せの襷を付す。繊細な造作の門塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012046"},{"id":"00012045","register_sub_id":"101","register_pk":"210986","name":"住吉神社楼門","kana":"すみよしじんじゃろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"山口県","address":"山口県下関市一の宮住吉一丁目1162-4","lat":33.999417,"lng":130.956575,"geo_status":"db","era":"明治34年","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、檜皮葺、建築面積41㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"35-96","desc":"石段上の境内前面に構える三間一戸楼門で、入母屋造檜皮葺。正面に付す奥行一間の庇は当地方から九州に類例が散見される。上層の建ちを抑え、木割が大きく均整のとれた立面などに室町期の前身楼門への指向を示しつつ、細部には明治期らしい華やかさを備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012045"},{"id":"00007135","register_sub_id":"101","register_pk":"108117","name":"大乗寺山門","kana":"だいじょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市長府金屋町17","lat":34.00324852,"lng":130.99053698,"geo_status":"db","era":"江戸末期／平成19移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積35㎡","structure_material":"木造","registered":"2008.04.18(平成20.04.18)","register_no":"35 － 0060","desc":"旧山陽道に東面して建つ。間口３．６ｍ、１間１戸、切妻造本瓦葺の四脚門で、柱は粽付円柱、組物は出組、軒は二軒繁垂木。両脇に間口１．７ｍ、切妻造本瓦葺、棟門形式の脇門を従える。商工業の町、金屋の玄関口に相応しい規模、構成、意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007135"},{"id":"00007136","register_sub_id":"101","register_pk":"108118","name":"大乗寺鐘楼","kana":"だいじょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"山口県","address":"山口県下関市長府金屋町17","lat":34.00347778,"lng":130.99065588,"geo_status":"db","era":"安政5／平成19移築","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"35 － 0061","desc":"山門の北方に位置する。南北棟、入母屋造本瓦葺、桁行１間梁間１間の袴腰付鐘楼で、柱は粽付円柱、組物は出組、軒は二軒繁垂木とし、四周に跳高欄をまわす。寺所蔵の建地割図から「安政五年九月 笹井要蔵」が判明。山門とともに旧山陽道の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007136"},{"id":"00009837","register_sub_id":"101","register_pk":"195666","name":"遠石八幡宮祭器庫","kana":"といしはちまんぐうさいきこ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03986732,"lng":131.82324979,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0081","desc":"拝殿の右奥に建つ切妻造平屋建。角柱で腰長押と内法長押を打つ。組物は舟肘木、妻飾は豕扠首で、軒は一軒繁垂木とする。壁は腰上を横板張、腰下を竪板張とし、外側面は透塀に合わせた連子窓形の板壁、内側はガラス入格子引違窓とする。神饌所と形式を揃える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009837"},{"id":"00009838","register_sub_id":"101","register_pk":"195667","name":"遠石八幡宮神饌所","kana":"といしはちまんぐうしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03986732,"lng":131.82302375,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0082","desc":"拝殿の左奥に建つ切妻造平屋建。角柱で腰長押と内法長押を打つ。組物は舟肘木、妻飾は豕扠首で、軒は一軒繁垂木。壁は腰上を横板張、腰下を竪板張とし、外側面は連子窓形の板壁、内側はガラス入格子引違窓とする。祭器庫とともに左右対称の伽藍景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009838"},{"id":"00009840","register_sub_id":"101","register_pk":"195669","name":"遠石八幡宮神門及び袖塀","kana":"といしはちまんぐうしんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408","lat":34.03940035,"lng":131.82308323,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"神門 木造、銅板葺、間口4.2m 袖塀 木造、銅板葺、総延長12m、潜戸付","structure_material":"神門 木造","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0084","desc":"拝殿の正面に建つ四脚門。本柱は円柱で、冠木より上部では虹梁と組んで大瓶束風に見せ、笈形を付す。控柱は角柱で組物は大斗肘木。軒は一軒で、門扉は桟唐戸両開とする。左右袖塀は各三間で中央を脇門とし、脇間に連子窓をたてる。厳格な雰囲気を醸す表門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009840"},{"id":"00009839","register_sub_id":"101","register_pk":"195668","name":"遠石八幡宮透塀","kana":"といしはちまんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408","lat":34.0399857,"lng":131.82315581,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造、銅板葺、総延長58m、潜戸付","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0083","desc":"拝殿翼部両端から本殿背後を囲む透塀で、祭器庫と神饌所の妻に取り付く。拝殿翼部寄りに引違戸、本殿背面に両開戸の戸口を設ける。角柱を腰長押と内法長押で固め、腕木で出桁を受け、軒は一軒とする。腰は竪板張で、連子窓には横長六角形断面の連子子を並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009839"},{"id":"00009841","register_sub_id":"101","register_pk":"195670","name":"遠石八幡宮手水舎","kana":"といしはちまんぐうてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.0392671,"lng":131.82299995,"geo_status":"db","era":"昭和16／昭和30頃改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造、銅板葺、面積3.1㎡","structure_material":"木造","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0085","desc":"神門前方の参道左手に位置する。石製手水鉢の両側に石製基礎を築き、四脚門形式の柱配置とする。本柱、控柱とも角柱で、本柱を棟までのばし、大斗肘木で棟木を受ける。控柱上部を女梁と男梁で繋いで桁を持ち出し、切妻屋根をかける。端正な意匠の手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009841"},{"id":"00009836","register_sub_id":"101","register_pk":"195665","name":"遠石八幡宮拝殿","kana":"といしはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03978701,"lng":131.82313082,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0080","desc":"楼門の左右に翼部をのばし、正背面に構える向拝屋根の拝み部を両翼の棟に重ねる。組物は上層三手先、向拝大斗肘木、翼部舟肘木。軒は上層と向拝が二軒、翼部が一軒である。床は幣殿前半と同高の擬石敷とする。当地方の伝統的な社殿形式を継承した楼拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009836"},{"id":"00009835","register_sub_id":"101","register_pk":"195664","name":"遠石八幡宮幣殿","kana":"といしはちまんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03987029,"lng":131.82314569,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積44㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0079","desc":"本殿前面に取付き、桁行四間で後方を床張、前方を擬石敷とし、境に木階二級を設ける。屋根は後方切妻造、前方両下造の段違いで、角柱に舟肘木を載せ、一軒繁垂木とする。側面の半蔀上戸は二つ折りで磨ガラスを用いる。内部架構は虹梁大瓶束笈形付。近代的な幣殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009835"},{"id":"00009834","register_sub_id":"101","register_pk":"195663","name":"遠石八幡宮本殿","kana":"といしはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県周南市遠石2-1408他","lat":34.03994168,"lng":131.82315164,"geo_status":"db","era":"昭和15／昭和30頃改修","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積39㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"35 － 0078","desc":"三間社流造で庇の側面を前室風に囲み、側背面に縁高欄を廻らせ木階七級を設ける。身舎は円柱に平三斗を、庇は角柱に舟肘木を載せ、身舎側面に板唐戸を、庇に引戸をたてる。妻飾は虹梁大瓶束で華やかな笈形を付し、軒は二軒繁垂木である。上質な近代の神社本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009834"},{"id":"00015250","register_sub_id":"101","register_pk":"530674","name":"長尾八幡宮神饌所","kana":"ながおはちまんぐうしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89419722,"lng":132.26782778,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0127","desc":"中殿南側に位置する神饌所。基壇上に建つ入母屋造妻入桟瓦葺で、東に庇を付して戸口とし、北面に渡廊下を接続。内部は東に玄関土間、西に２室配し、西室は床構付き座敷で、床脇に窓を設けた近代らしい意匠。北側の控所と一対で境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015250"},{"id":"00015252","register_sub_id":"101","register_pk":"530676","name":"長尾八幡宮透塀","kana":"ながおはちまんぐうすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89425,"lng":132.26775,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造、銅板葺、総延長25m","structure_material":"木造","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0129","desc":"本殿の南北両脇に延び、本殿域を区画する透塀。切石積基壇上に建つ、切妻造銅板葺で、北・南の端部を西へ一間延ばす。軒は腕木で支持し、柱間に菱格子、欄間に吹寄の襷桟を建て、腰に横板を嵌める。軽快なつくりで、本殿周囲の歴史的な景観に寄与する透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015252"},{"id":"00015248","register_sub_id":"101","register_pk":"530672","name":"長尾八幡宮中殿及び幣殿","kana":"ながおはちまんぐうちゅうでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89432222,"lng":132.26782778,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積83㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0125","desc":"本殿と拝殿の間に位置する中殿及び幣殿。切石積基壇上に建つ両下造銅板葺東西棟で中殿の北・南面に下屋を付し、西に幣殿を延ばす。中殿中央は一室の畳敷で北・南に各２室を配し、東の幣殿は床を一段高く張る。天井は竿縁天井。境内景観に欠かせない社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015248"},{"id":"00015253","register_sub_id":"101","register_pk":"530677","name":"長尾八幡宮手水舎","kana":"ながおはちまんぐうちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南2649","lat":33.89432222,"lng":132.26896389,"geo_status":"db","era":"大正4年頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、面積6.4㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0130","desc":"境内中央、参道の北に建つ切妻造桟瓦葺の手水舎。礎石上に柱を四方転びに立て、虹梁形頭貫で固める。台輪上に大斗肘木を組み、軒は一軒疎垂木。両妻拝に蕪懸魚を付す。内部中央に水盤据え、化粧軒裏を現す。装飾少なく、簡素ながらも境内景観をつくる手水舎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015253"},{"id":"00015255","register_sub_id":"101","register_pk":"530679","name":"長尾八幡宮鳥居","kana":"ながおはちまんぐうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字宮崎11432-1他","lat":33.89348611,"lng":132.269875,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"石造、間口5.7m、高さ6.9m","structure_material":"石造","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0132","desc":"境内南東の参道入口に建つ石造の明神鳥居。柱間5・7メートル、高さ6・9メートル、内転びの円柱に貫を通し、頂部に反りのある島木と笠木を載せ、正面貫上に社名を刻んだ石製の扁額を掲げる。境内の入口に象徴的に建ち、参道の歴史的な景観を形成する鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015255"},{"id":"00015249","register_sub_id":"101","register_pk":"530673","name":"長尾八幡宮拝殿","kana":"ながおはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89431389,"lng":132.26796667,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0126","desc":"本殿の東に位置する拝殿。基壇上に東面して建つ入母屋造平入銅板葺で正面に千鳥破風を飾り、唐破風造向拝を付し、三方に高欄付縁を廻らす。組物は出組、軒は二軒繁垂木。内部は一室の畳敷で格天井。向拝に籠彫や丸彫彫刻を集中して飾り、外観華やかな拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015249"},{"id":"00015251","register_sub_id":"101","register_pk":"530675","name":"長尾八幡宮控所","kana":"ながおはちまんぐうひかえしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89442778,"lng":132.26784722,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0128","desc":"中殿の北側に位置する控所。基壇上に建つ入母屋造妻入桟瓦葺で、東の戸口に庇を付す。内部は東に玄関土間、西に２室配し、西室は床構付き座敷で床脇に違棚を備える。南面の高欄付縁から渡廊下で中殿に接続する。神饌所と一対で境内の歴史的な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015251"},{"id":"00015247","register_sub_id":"101","register_pk":"530671","name":"長尾八幡宮本殿","kana":"ながおはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南11431-2","lat":33.89432222,"lng":132.26769722,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0124","desc":"周防大島の神南山中腹に位置する神社本殿。基壇上に東面して建つ、三間社流造檜皮葺で、正面に千鳥破風を飾り、切妻造向拝を付す。組物は尾垂木付三手先で通肘木上に斗を並べ、妻飾は二重虹梁大瓶束。軒廻り賑やかで秀逸な彫刻で飾った地元大工による本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015247"},{"id":"00015254","register_sub_id":"101","register_pk":"530678","name":"長尾八幡宮御幸橋","kana":"ながおはちまんぐうみゆきばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"山口県","address":"山口県大島郡周防大島町大字西安下庄字神南2649","lat":33.89428611,"lng":132.26866389,"geo_status":"db","era":"昭和12年","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"鉄筋コンクリート造及び石造、橋長4.3m、幅員4.3m、橋台付","structure_material":"鉄筋コンクリート造及び石造","registered":"2024.12.03(令和6.12.03)","register_no":"35 - 0131","desc":"境内中央に広がる池に架かる橋。橋長四・三メートル、幅員四・三メートルで、緩やかに反る鉄筋コンクリート造の床版両端に石製高欄を組み、高欄狭間に木瓜状に彫出す石版を嵌める。防火用貯水池建設の一環で架橋し、境内整備の歴史を物語る太鼓橋形式の橋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015254"},{"id":"00003918","register_sub_id":"101","register_pk":"104908","name":"日本基督教団下関丸山教会（旧日本メソヂスト下関教会）会堂","kana":"にほんきりすときょうだんしものせきまるやまきょうかい（きゅうにほんめそぢすとしものせききょうかい）かいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市丸山町4-1-8","lat":33.956921,"lng":130.932526,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積143㎡、塔屋付","structure_material":"木造平屋一部2階建","registered":"2004.02.17(平成16.02.17)","register_no":"35 － 0043","desc":"関門海峡を一望する高台に建つ。木造，平屋一部２階建で，主室の礼拝堂はキングポストトラス風の小屋組を現した質実な内部構成になる。正面に大きな妻面を見せ，向かって右手に塔屋を付したスパニッシュスタイルの外観は，白壁・赤瓦が印象的な対比をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003918"},{"id":"00007593","register_sub_id":"101","register_pk":"108575","name":"防府天満宮本殿・幣殿・拝殿","kana":"ほうふてんまんぐうほんでん・へいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"山口県","address":"山口県防府市松崎町69","lat":34.0633519,"lng":131.57416276,"geo_status":"db","era":"昭和33","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積211㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"35 － 0067","desc":"入母屋造の本殿と拝殿を両下造の幣殿が繋ぐ複合社殿で、南面する。周囲に組高欄付切目縁をまわし、柱は円柱で、大斗肘木を載せ、二軒繁垂木とする。本殿は桁行三間で、内部を１室とし、正背面中央に両開板戸をたてる。繊細優美な意匠になり、近代社殿建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007593"},{"id":"00013891","register_sub_id":"101","register_pk":"507849","name":"妙鑑寺位牌堂","kana":"みょうかんじいはいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"山口県","address":"山口県山口市大内矢田南八丁目53","lat":34.15191667,"lng":131.51554167,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積88㎡","structure_material":"煉瓦造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"35 － 0104","desc":"桁行一七メートル梁間五メートル煉瓦造平屋建で、屋根は寄棟造赤色桟瓦葺。中央に塔屋が載る。イギリス積を化粧で現し四隅に柱形を付ける。内部は一室で、位牌棚と通路で構成され、天窓からの光が静謐な空間をつくる。煉瓦造の躯体が境内に異彩を放つ位牌堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013891"},{"id":"00006114","register_sub_id":"101","register_pk":"107098","name":"めぐみ幼稚園第一園舎（旧下関バプテスト教会）","kana":"めぐみようちえんだいいちえんしゃ（きゅうしものせきばぷてすときょうかい）","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"山口県","address":"山口県下関市上田中町2-13-26","lat":33.96476634,"lng":130.94102334,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積200㎡、地下室付","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"35 － 0055","desc":"傾斜地に建ち，正面東側に半地下を設けた３廊式教会堂。南側廊部の東端に尖頭屋根を戴く鐘塔を配し玄関とする。外壁は，半地下部を擬石仕上げ，上部をモルタル吹き付けとし，鐘塔に尖頭やチューダーアーチの開口をとる。ヴォーリズ建築事務所設計の教会建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006114"},{"id":"00014089","register_sub_id":"101","register_pk":"508349","name":"有宮神社本殿","kana":"ありみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市西祖谷山村徳善82","lat":33.87796667,"lng":133.77072222,"geo_status":"db","era":"明治41年／昭和41年・平成2年・同15年改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積2.2㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"36 - 0215","desc":"大歩危峡右岸の山中、旧街道沿いの尾根上に位置する。一間社流造銅板葺、柱を長押で固め台輪を載せ組物は二手先。正側面に高欄付切目縁を廻し、脇障子を隅行に建てる。脇障子や木鼻、正側面及び庇の虹梁形頭貫の蟇股等、各所を彫刻で飾った、華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014089"},{"id":"00007805","register_sub_id":"101","register_pk":"108786","name":"安楽寺山門","kana":"あんらくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.05224191,"lng":134.0617321,"geo_status":"db","era":"宝暦6／昭和11改修","year":1756,"year_source":"db","year_min":1756,"year_max":1756,"year_label":null,"structure":"木造、瓦葺、面積41㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"36-0077","desc":"本堂の南方に建つ、三間三戸二階二重門。入母屋造本瓦葺。上重二軒扇垂木、下重二軒繁垂木。上重が本格的な禅宗様三手先詰組であるのに対し、下重は斗を使わず、肘木や直材を組み合わせる奇抜な組物を用いる。扉上部の中備には奇矯な表情の鬼面を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007805"},{"id":"00007803","register_sub_id":"101","register_pk":"108784","name":"安楽寺書院","kana":"あんらくじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.05282482,"lng":134.06183332,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積94㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"36-0075","desc":"本堂の北東に東西棟で建つ。入母屋造本瓦葺で、桟瓦葺の下屋庇をまわす。東西に十畳と十二畳半の二室を配し、東・南・西に縁、背面に榑縁を付け、各室にトコやトコ脇、付書院を構え、室境に彫刻欄間を飾る。軽快ながら安定感のある外観をもつ良質な書院座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007803"},{"id":"00007804","register_sub_id":"101","register_pk":"108785","name":"安楽寺鐘楼","kana":"あんらくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.0523763,"lng":134.06200959,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造、瓦葺、面積21㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"36-0076","desc":"本堂の東南に位置する。切石積の高い基壇上に建つ方一間吹放ち鐘楼。入母屋造本瓦葺で棟に鯱を飾り、撞木を吊る西側に軒唐破風を付ける。湾曲した方柱を四方転びに建て、三斗組で中備に蟇股を置く。二軒扇垂木とし、内部に格天井を張る。風格のある鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007804"},{"id":"00007807","register_sub_id":"101","register_pk":"108788","name":"安楽寺方丈","kana":"あんらくじほうじょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町引野字寺ノ西北8他","lat":34.1183368,"lng":134.3885059,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺一部瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"36-0079","desc":"東面する本堂の東北に南面して建つ。屋根は周囲を本瓦葺とする入母屋造茅葺。方柱で、大斗肘木を置き、中備は束で笈形風に彫物を飾る。一軒半繁垂木。内部は田字型に四室を配し、周囲に広縁をまわす。上段の間は藩主の座所と伝える。穏やかな外観になる座敷。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007807"},{"id":"00007802","register_sub_id":"101","register_pk":"108783","name":"安楽寺本堂","kana":"あんらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県美馬市美馬町字宮西11","lat":34.05261364,"lng":134.06173036,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積517㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"36-0074","desc":"境内地西寄りに南面して建つ。入母屋造本瓦葺の七間堂、周囲に庇柱を建て、正面に三間向拝を付ける。内部は外陣と矢来の間、内陣等からなる典型的な浄土真宗本堂の形式をもつ。向拝や内外陣境の欄間などに多くの彫物が施される。近代の大規模な真宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007802"},{"id":"00011216","register_sub_id":"101","register_pk":"205323","name":"今宮神社神門及び瑞垣","kana":"いまみやじんじゃしんもんおよびみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻316-1","lat":34.02765187,"lng":133.88044942,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"神門 木造、銅板葺、間口2.7m 瑞垣 木造、鉄板葺、延長48m","structure_material":"神門 木造","registered":"2016.08.01(平成28.08.01)","register_no":"36 - 0132","desc":"本殿と拝殿の間に神門を開け、神門に続いて本殿を囲繞する瑞垣を廻らす。神門は切妻造妻入の一間一戸門で、前面柱筋に上部を菱格子とする桟唐戸を吊る。瑞垣は切石積基壇上に木造で建て、上部を、正面側で菱格子、側背面では縦格子として正面を飾り立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011216"},{"id":"00011215","register_sub_id":"101","register_pk":"205322","name":"今宮神社拝殿","kana":"いまみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻316-1","lat":34.027685,"lng":133.880399,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"36 - 0131","desc":"本殿の正面に建つ方一間入母屋造妻入の建物で、柱間を吹き放して床を張る。天井は格天井、妻には木連格子を嵌める。舞殿とも称され、神楽殿のような使い方も想定されていたとみられる。本殿同様、装飾を抑えた簡明な外観とする。近代の社頭景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011215"},{"id":"00011214","register_sub_id":"101","register_pk":"205321","name":"今宮神社本殿","kana":"いまみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県三好市井川町辻316-1","lat":34.027603,"lng":133.880532,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"36 - 0130","desc":"伊予街道の旧道から石段を上がった傾斜地に境内を構える。一間社流造の小規模社殿。舟肘木で桁を受け、妻は豕扠首とし、破風に懸魚を付けるほかは装飾要素を抑えた簡素な外観を持つ。設計は徳島県立工業学校の福永嘉吉。煙草産業での繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011214"},{"id":"00011573","register_sub_id":"101","register_pk":"210393","name":"浦山堂","kana":"うらやまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字浦山412-1","lat":34.02298389,"lng":134.05840111,"geo_status":"db","era":"嘉永元年（1848）／昭和43年改修","year":1848,"year_source":"db","year_min":1848,"year_max":1848,"year_label":null,"structure":"木造平屋建、スレート葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0162","desc":"端四国八十八箇所霊場の第三七番札所。宝形造桟瓦葺の三間堂で、背面寄り中央に一間幅の仏間を設け、四方吹放ちで、四方に縁を廻らし、天井は棹を疎らに配する棹縁天井とする。軒は疎垂木。仏間廻り、側柱上に組物・彫刻を施し、比較的装飾豊かである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011573"},{"id":"00011565","register_sub_id":"101","register_pk":"210498","name":"大泉堂","kana":"おおいずみどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字岡335","lat":34.02769194,"lng":134.07019806,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、瓦葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0154","desc":"端四国八十八箇所霊場の第一三番札所。宝形造本瓦葺の三間堂で、桁行四・〇メートル、梁間三・九メートルの規模の三方吹放ち。中央奥に仏間を張出し、天井は棹縁天井とする。縁を設けない簡易な作りながら、本瓦をもちいるなど重厚な雰囲気を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011565"},{"id":"00010356","register_sub_id":"101","register_pk":"199128","name":"大日孁神社拝殿","kana":"おおひるめじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市山城町光兼字光兼558","lat":33.932177,"lng":133.722551,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"36-0118","desc":"本殿前の一段低い位置の石積基壇上に建つ。桁行三間梁間二間、入母屋造で、内部は畳敷で三室に分かれ、欄間に瓢箪や竹の透彫を嵌める。背面張出しに内拝殿と物入を設ける。木鼻も含めた向拝虹梁彫刻に巻付く龍を表す技法などに、本殿と共通の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010356"},{"id":"00010355","register_sub_id":"101","register_pk":"199273","name":"大日孁神社本殿","kana":"おおひるめじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市山城町光兼字光兼558","lat":33.932152,"lng":133.722641,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"36-0117","desc":"境内奥の石垣に建つ流造本殿。尾垂木付三手先で軒や妻を大きく迫出し、腰組を出組で受け、脇障子を隅行に振る。随所を龍や動植物の彫刻で飾り、特に頭貫木鼻は籠彫の中に人物を彫出し、破風は龍を巻付けた立体的な造形とするなど、高い彫刻技法に見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010355"},{"id":"00011570","register_sub_id":"101","register_pk":"210391","name":"皆瀬堂","kana":"かいぜどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字皆瀬190","lat":34.01323111,"lng":134.07697,"geo_status":"db","era":"文化13年（1816）","year":1816,"year_source":"db","year_min":1816,"year_max":1816,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0159","desc":"端四国八十八箇所霊場の第三四番札所。宝形造桟瓦葺の三間堂で、北面中央に二間幅の仏間を設け、南・東の二面を吹放ちとして縁を設け、天井は棹縁天井とする。仏間廻りに彫刻を施すほかは全体に簡易な作りとし、地域の信仰の有り様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011570"},{"id":"00007594","register_sub_id":"101","register_pk":"108576","name":"願勝寺山門","kana":"がんしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県美馬市美馬町字願勝寺8","lat":34.05162,"lng":134.06015,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造、瓦葺、間口3.6m","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"36 － 0073","desc":"東面する三間一戸八脚門。入母屋造本瓦葺。礎盤上に円柱を建て、出三斗で中備に彫物を置く。柱上部に台輪状の部材を上下２段に設け、その間に笈形付大瓶束や、蓮弁状に上下を作る束などを配する。中央間を花頭形に開け植物文様を飾る。独創的な意匠になる山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007594"},{"id":"00011569","register_sub_id":"101","register_pk":"210501","name":"吉良堂","kana":"きらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字吉良346-3","lat":33.99413,"lng":134.07243611,"geo_status":"db","era":"文化7年（1810）／平成17年改修","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積35㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0158","desc":"端四国八十八箇所霊場の第三〇番札所。寄棟造茅葺（鉄板仮葺）の三間堂で、背面側を三間幅の仏間とし、三方吹放ちの三方に縁を廻らす。正面中央間には虹梁をかけ、天井は棹縁天井とする。背面中央間を円柱とし、随所に彫刻を施し木鼻を付ける。比較的大型の堂宇。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011569"},{"id":"00010691","register_sub_id":"101","register_pk":"201265","name":"西圓寺本堂","kana":"さいえんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県吉野川市鴨島町麻植塚365","lat":34.071657,"lng":134.375937,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積222㎡","structure_material":"木造平屋建","registered":"2015.08.04(平成27.08.04)","register_no":"36－0127","desc":"洋行した当時の住職が椅子式仏堂への指向を提唱し、外観にも洋風意匠を取り入れた。内陣部は和風の入母屋造平入とするが、外陣部分は正面入母屋の妻を半切妻形式とし、正面に車寄を付ける。壁は洋風の横板張で壁面に上下窓を配する。独創的な形式の真宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010691"},{"id":"00007409","register_sub_id":"101","register_pk":"108391","name":"西教寺経蔵","kana":"さいきょうじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県美馬市美馬町字宮西13-1","lat":34.052773,"lng":134.06132391,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積47㎡","structure_material":"土蔵造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"36 － 0071","desc":"本堂の南に東面して建つ。正面に千鳥破風を付ける入母屋造本瓦葺で、唐破風造の前室を設ける。桁行７．１ｍ梁間５．３ｍの土蔵造平屋建で、切石積基礎上を漆喰仕上げとする。前室正面は方柱で柱上に皿斗付三斗を組み、虹梁絵様や笈形などに独特の意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007409"},{"id":"00007410","register_sub_id":"101","register_pk":"108392","name":"西教寺山門","kana":"さいきょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字宮西13-1","lat":34.052994,"lng":134.061752,"geo_status":"db","era":"天保14","year":1843,"year_source":"db","year_min":1843,"year_max":1843,"year_label":null,"structure":"木造、瓦葺、間口3.1m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"36 － 0072","desc":"本堂の前方に建つ、南北棟の三間薬医門。中央に両開桟唐戸を吊り、北間に潜りを設ける。切妻造本瓦葺。本柱上に冠木、男梁を架し、三斗を組み、軒桁や妻の虹梁大瓶束を支える。軒は二軒で、飛檐を雲彫刻の板軒とする特徴的な意匠を見せる。重厚で風格ある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007410"},{"id":"00007408","register_sub_id":"101","register_pk":"108390","name":"西教寺本堂","kana":"さいきょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬市美馬町字宮西13-1","lat":34.05298448,"lng":134.06132513,"geo_status":"db","era":"安政5","year":1858,"year_source":"db","year_min":1858,"year_max":1858,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積240㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"36 － 0070","desc":"境内西寄りに東面して建つ。桁行１４ｍ梁間１６ｍ規模で、入母屋造本瓦葺とし、正面に一間向拝、背面に縋破風を付ける。浄土真宗本堂の標準的な平面構成になるが、正面広縁を外陣と一体的に扱う。三斗組を重ねる妻飾りや、向拝の龍虎の彫刻など見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007408"},{"id":"00008589","register_sub_id":"101","register_pk":"134985","name":"地蔵寺経蔵","kana":"じぞうじきょうぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13738786,"lng":134.43179753,"geo_status":"db","era":"文化7年（1810）","year":1810,"year_source":"db","year_min":1810,"year_max":1810,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積31㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0092","desc":"本堂の北方に南面して建つ。桁行五・九メートル梁間四・九メートル、寄棟造本瓦葺。切石積基礎上に建つ土蔵で、外壁を漆喰仕上げとし、側面に花頭形の格子窓を穿つ。堂内は板敷で、壁板張、鏡天井を張り、中央に八角の輪蔵を置く。丁寧なつくりの小規模経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008589"},{"id":"00008590","register_sub_id":"101","register_pk":"134986","name":"地蔵寺五百羅漢堂","kana":"じぞうじごひゃくらかんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13830368,"lng":134.4314071,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積674㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0093","desc":"本堂など主要伽藍の北方高台に位置する。釈迦堂を中心に大師堂と弥勒堂を対面してコ字形に配し、この間を回廊が繋ぐ。建築面積六七四平方メートル。本瓦葺とし、回廊には背面に接して壇を設けて、羅漢像を安置する。庶民の信仰を集める大規模な境内仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008590"},{"id":"00008588","register_sub_id":"101","register_pk":"134984","name":"地蔵寺大師堂","kana":"じぞうじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.1368286,"lng":134.43230904,"geo_status":"db","era":"正徳年間（1711-1716）／江戸末期改修","year":1714,"year_source":"estimated","year_min":1711,"year_max":1716,"year_label":"正徳年間（1711-1716）","structure":"木造平屋建、瓦葺、建築面積96㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0091","desc":"本堂の東方に対面して建つ。桁行三間梁間三間、入母屋造本瓦葺で、正面中央に唐破風造の一間向拝を付設。方柱で平三斗とし、彫刻欄間を飾る。二軒繁垂木。内部は後方一間通りを柱列や小壁で間仕切り、厨子を安置する。鏡天井に天女を描くなど、装飾性が強い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008588"},{"id":"00008587","register_sub_id":"101","register_pk":"134983","name":"地蔵寺不動堂","kana":"じぞうじふどうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13694606,"lng":134.43171117,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積59㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0090","desc":"本堂の北側に接して建つ。桁行三間梁間三間で、正面に一間向拝、背面に仏壇を付設する。切妻造本瓦葺。内部は一室で、板敷とし、棹縁天井を張り、中央に護摩壇を置く。方柱で、大斗肘木を置き、一軒繁垂木。二重虹梁大瓶束の妻面に飾られる彫刻が親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008587"},{"id":"00008586","register_sub_id":"101","register_pk":"134982","name":"地蔵寺本堂","kana":"じぞうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県板野郡板野町羅漢字林東5","lat":34.13685303,"lng":134.43175505,"geo_status":"db","era":"正徳年間(1711-1716）","year":1714,"year_source":"estimated","year_min":1711,"year_max":1716,"year_label":"正徳年間(1711-1716）","structure":"木造平屋建、瓦葺、建築面積82㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0089","desc":"境内地の西南に東面して建つ。桁行三間梁間三間で、正面に一間向拝を付け、背面半間通りを取り込む。入母屋造本瓦葺。正面一間通りを外陣、その奥を内陣とし、後方中央に須弥壇を構える。柱は方柱で、隅に絵様肘木を置く。近世に遡る四国札所本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008586"},{"id":"00008784","register_sub_id":"101","register_pk":"149505","name":"常楽寺大師堂","kana":"じょうらくじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町延命606","lat":34.05035061,"lng":134.4759288,"geo_status":"db","era":"文化9年(1812)／平成15年改修","year":1812,"year_source":"converted","year_min":1812,"year_max":1812,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"36 － 0099","desc":"本堂の東北に南面して建つ。宝形造本瓦葺の3間堂。正面に1間向拝を付ける。方柱、木鼻付平三斗、中備蟇股、二軒繁垂木。正面の小壁に彫物を飾る。内部は正面1間通りを外陣、奥を内陣とする。江戸後期に遡る本堂と大師堂が残り、近世四国札所の景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008784"},{"id":"00008783","register_sub_id":"101","register_pk":"149504","name":"常楽寺本堂","kana":"じょうらくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町延命606","lat":34.0503593,"lng":134.475666,"geo_status":"db","era":"江戸後期／弘化2年(1845)・昭和63年改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"36 － 0098","desc":"辰ヶ山の中腹に東面して建つ。入母屋造本瓦葺の3間堂。正面に1間向拝を付ける。方柱で、平三斗、中備蟇股、二軒繁垂木。内部は正面1間通りを外陣、その奥を内陣とし、中央に須弥壇を構え、厨子を置く。外陣鏡天井に龍が描かれる。近世四国札所本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008783"},{"id":"00011566","register_sub_id":"101","register_pk":"210554","name":"白村堂","kana":"しらむらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字白村194","lat":34.03096611,"lng":134.07422,"geo_status":"db","era":"天保11年（1840）","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造平屋建、茅葺（鉄板仮葺）、建築面積29㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0155","desc":"端四国八十八箇所霊場の第一四番札所。入母屋造茅葺（鉄板仮葺）の三間堂で、四方吹放ちの四方に縁を廻らす。軒は繁垂木とする。中央奥の柱筋より前に仏間を配し、天井は棹縁天井とする。虹梁を配して木鼻を付けるなど、比較的装飾豊かである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011566"},{"id":"00014210","register_sub_id":"101","register_pk":"508840","name":"千光院本堂","kana":"せんこういんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"徳島県","address":"徳島県阿波市土成町吉田字山の神22-3","lat":34.12463611,"lng":134.35234167,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺一部鉄板葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2022.02.17(令和4.02.17)","register_no":"36-0216","desc":"宮川内谷川の扇頂部に位置する真言宗寺院の本堂。桁行３間梁間４間、切妻造本瓦葺平入の正面に向拝、両側面に下屋、背後に突出部を付す。内部は広い外陣１室で棹縁天井を張る。奥に内陣、内々陣を張出す。イベントにも利用し、当地の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014210"},{"id":"00014087","register_sub_id":"101","register_pk":"508347","name":"蔵珠院茶室","kana":"ぞうしゅいんちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町芝原字宮ノ本3","lat":34.09281944,"lng":134.46276389,"geo_status":"db","era":"江戸末期／平成26年移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積81㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"36 - 0213","desc":"吉野川右岸の平野に位置する寺院の茶室。本堂西側に建ち、茶室二室と水屋、控室からなる寄棟及び切妻造の棟と、上の間の切妻造棟が棟方向を違えて接続する。部屋ごとに趣を変え、いずれも多様な銘木をふんだんに用い、細部まで意匠を凝らした上質な数寄屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014087"},{"id":"00014088","register_sub_id":"101","register_pk":"508348","name":"蔵珠院まい込み泉","kana":"ぞうしゅいんまいこみいずみ","category":"宗教","subcategory":"その他工作物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県徳島市国府町芝原字宮ノ本3","lat":34.09251111,"lng":134.46304722,"geo_status":"db","era":"江戸末期／昭和50年頃・令和2年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、直径6m、深さ4.3m","structure_material":"石造","registered":"2021.10.14(令和3.10.14)","register_no":"36 - 0214","desc":"吉野川右岸の平野に位置する寺院の通路付井戸。本堂前方に位置し、上部径約六メートル、深さ約三メートルの擂鉢状の掘込みに螺旋状の通路を設け、底部に径約〇・八メートルの井筒を埋める。壁面は結晶片岩の板状割石を積む。地元に親しまれる類例稀な井戸。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014088"},{"id":"00008593","register_sub_id":"101","register_pk":"134989","name":"大山寺回廊","kana":"たいさんじかいろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15936287,"lng":134.39961426,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積45㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0096","desc":"本堂と大師堂を繋ぐ南北棟の廊下。桁行四間梁間三間、切妻造桟瓦葺。梁行に三分し、中央通りを正面に腰壁や格子戸、背面に板壁をたてて間仕切り、壇を設け、三十三観音を安置。正面一間通りを拜所とし、棹縁天井を張る。回廊を信仰の場とした特殊な堂宇である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008593"},{"id":"00008594","register_sub_id":"101","register_pk":"134990","name":"大山寺鐘楼門","kana":"たいさんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15921534,"lng":134.40011394,"geo_status":"db","era":"江戸末期／昭和60年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、銅板葺、建築面積22㎡","structure_material":"木造2階建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0097","desc":"本堂の前方、石段を降りた位置に東面して建つ。入母屋造の三間一戸楼門で、下層は正面に虹梁を架け間柱を省略する。上層は円柱で、出三斗組、二軒扇垂木。周囲に連子をたてるなど開放的な扱いとし、擬宝珠高欄付縁を張る。大柄で落ち着きのある鐘楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008594"},{"id":"00008592","register_sub_id":"101","register_pk":"134988","name":"大山寺大師堂","kana":"たいさんじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15945329,"lng":134.39962615,"geo_status":"db","era":"文久3年（1863）／昭和60年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0095","desc":"本堂の北方に東面して建つ。正面三間側面二間で、背面に須弥壇を付設し、正・側面に縁をまわす。宝形造で正面に一間向拝を設ける。堂内は板敷、棹縁天井の一室。方柱で、出三斗組とし、軒は一軒の吹寄垂木とする。江戸末期に建立された標準的な弘法大師堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008592"},{"id":"00008591","register_sub_id":"101","register_pk":"134987","name":"大山寺本堂","kana":"たいさんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県板野郡上板町神宅字大山4","lat":34.15927584,"lng":134.39960919,"geo_status":"db","era":"江戸中期／寛政8年（1796）移築・昭和27年・昭和60年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造平屋建、銅板葺、建築面積155㎡","structure_material":"木造平屋建","registered":"2011.01.26(平成23.01.26)","register_no":"36 － 0094","desc":"大山の中腹に伽藍を構える。東面して建つ三間仏堂で、正・側面に縁柱をたてる。入母屋造とし、正面に一間向拝を付設。正面一間通りを外陣、奥を内陣とし、後方に須弥壇や脇壇を置く。木鼻や手挟を龍や貘、植物の彫刻として飾るなど近世らしい装飾をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008591"},{"id":"00009669","register_sub_id":"101","register_pk":"194665","name":"太龍寺護摩堂","kana":"たいりゅうじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88244899,"lng":134.52213588,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積111㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0109","desc":"境内東方に南面して建ち、本坊西に接続する。正面三間側面四間、入母屋造銅板葺で、正面向拝一間付、南東面に縁を廻す。前一間を外陣、奥三間は中央間の内陣及び厨子と脇間からなる。粽付円柱を立て、側廻りは台輪上に出組詰組とし、向拝廻りの彫刻密度を高める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009669"},{"id":"00009674","register_sub_id":"101","register_pk":"194670","name":"太龍寺鐘楼門","kana":"たいりゅうじしょうろうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88213728,"lng":134.52126737,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造、銅板葺、間口5.3m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0114","desc":"本坊から本堂に上る石段途中に東面して建つ。三間一戸楼門、入母屋造銅板葺。下層は貫で固め、台輪上に出組とし、門扉を持たない。梵鐘を吊る上層は周囲竪板壁とし、正背面中央間に花頭窓を開く。組物出三斗、軒は二軒扇垂木とし、彫刻は時代的特色を表す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009674"},{"id":"00009667","register_sub_id":"101","register_pk":"194663","name":"太龍寺大師堂","kana":"たいりゅうじたいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88166377,"lng":134.51997295,"geo_status":"db","era":"明治10","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積108㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0107","desc":"境内北西方、御影堂の前に東面する。方三間正面向拝一間付で四方に縁を廻す。入母屋造銅板葺、千鳥破風及び軒唐破風付。御影堂を礼拝するための堂で、奥二間を内陣、前一間を外陣とする。虹梁や欄間など随所に瑞獣や波紋などの彫刻を充溢させ装飾的につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009667"},{"id":"00009670","register_sub_id":"101","register_pk":"194666","name":"太龍寺多宝塔","kana":"たいりゅうじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88159239,"lng":134.520337,"geo_status":"db","era":"文久元","year":1861,"year_source":"db","year_min":1861,"year_max":1861,"year_label":null,"structure":"木造多宝塔、銅板葺、建築面積40㎡","structure_material":"木造多宝塔","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0110","desc":"本堂北側の高台に建つ。下層は方三間の周囲に縁を廻らし、組物出組、二軒繁垂木とし、上層は円形平面、四手先組物で二軒扇垂木の軒を支え、上下層とも銅板葺とする。四天柱内を折上格天井とし虚空蔵菩薩を安置する。安定感ある塔姿で、伽藍景観を引立てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009670"},{"id":"00009673","register_sub_id":"101","register_pk":"194669","name":"太龍寺仁王門","kana":"たいりゅうじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88360303,"lng":134.52383719,"geo_status":"db","era":"文化3","year":1806,"year_source":"db","year_min":1806,"year_max":1806,"year_label":null,"structure":"木造、銅板葺、間口7.7m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0113","desc":"境内東端に東面して建ち、三間一戸八脚門、入母屋造銅板葺で、両脇間後方に仁王像を安置する。円柱を頭貫と腰貫で固め、台輪上に出三斗を据え、軒は二軒繁垂木とする。中央間には絵様虹梁を架け装飾性を高める。山上伽藍の入口を画すに相応しい意匠を持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009673"},{"id":"00009666","register_sub_id":"101","register_pk":"194662","name":"太龍寺本堂","kana":"たいりゅうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88140679,"lng":134.52039411,"geo_status":"db","era":"嘉永5","year":1852,"year_source":"db","year_min":1852,"year_max":1852,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積180㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0106","desc":"境内の西方に南面して建つ。五間堂規模で正面のみ柱間を広くとり三間とする。入母屋造銅板葺、四方に縁を廻し、正面向拝一間付。内部三間四方を内陣とし、前一間を広い外陣とする。要所を彫刻化した蟇股などで飾り、全体に木太く、当地域の札所の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009666"},{"id":"00009672","register_sub_id":"101","register_pk":"194668","name":"太龍寺本坊","kana":"たいりゅうじほんぼう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88246089,"lng":134.5217623,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積944㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0112","desc":"東半の方丈と西半の庫裏からなり、いずれも入母屋造銅板葺で、間を唐破風屋根の式台玄関で繋ぐ。方丈は九間取の中央を持仏堂とし、前面に入側を配し、欄間には手の込んだ彫刻欄間を入れる。簡素な外観になる大型の本坊で、落ち着いた境内空間を実現している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009672"},{"id":"00009668","register_sub_id":"101","register_pk":"194664","name":"太龍寺御影堂","kana":"たいりゅうじみえいどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88165663,"lng":134.51980163,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0108","desc":"境内北西方、大師堂の西方に東面する。正面三間側面二間、宝形造銅板葺で、正側面に縁を廻す。円柱を立て出三斗組、二軒扇垂木とする。堂内は前後二分して内外陣とし、漆塗の厨子を安置する。大師堂とあわせて境内景観に欠かせない堂で、厳粛な雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009668"},{"id":"00009671","register_sub_id":"101","register_pk":"194667","name":"太龍寺六角経蔵","kana":"たいりゅうじろっかくきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県阿南市加茂町竜山1他","lat":33.88231812,"lng":134.52226675,"geo_status":"db","era":"安政3","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡、輪蔵付","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"36 － 0111","desc":"境内東方に西面して建つ。六角円堂、銅板葺。各隅に五角柱を立て、外壁は腰高に竪板張とし背面三方に棚を張出す。内部の八角輪蔵は禅宗様でまとめられ、二軒扇垂木で極彩色を施し、随所に錺金具を散らす。幕末の華やかな意匠で荘厳された内部空間が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009671"},{"id":"00011571","register_sub_id":"101","register_pk":"210502","name":"竹屋敷堂","kana":"たけやしきどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字竹屋敷64","lat":34.01571806,"lng":134.06646389,"geo_status":"db","era":"大正元年","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0160","desc":"端四国八十八箇所霊場の第三五番札所。宝形造桟瓦葺の三間堂で、背面中央を一間幅の仏間とし、三方吹放ちの四方に縁を廻らす。天井は棹縁天井とする。仏間周りに組物・彫刻を施し、正面中央間に虹梁をかける他は、柱間を貫と長押で固める簡素な造りである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011571"},{"id":"00014960","register_sub_id":"101","register_pk":"519220","name":"立江寺多宝塔","kana":"たつえじたほうとう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"high","period":"大正","pref":"徳島県","address":"徳島県小松島市立江町字若松13","lat":33.96752222,"lng":134.60603611,"geo_status":"db","era":"大正12年","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造多宝塔、銅板葺及び瓦葺、建築面積31㎡","structure_material":"木造多宝塔","registered":"2024.03.06(令和6.03.06)","register_no":"36 - 0228","desc":"四国霊場十九番札所の境内南方に建つ多宝塔。下層は本瓦葺で方三間の周囲に縁を廻らし組物出組、二軒繁垂木。上層は円形平面で本瓦型銅板葺。四手先組物で軒は二軒扇垂木。内部の四天柱内は折上格天井。板支輪や腰組蟇股の彫刻などが装飾的な近代の多宝塔。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014960"},{"id":"00012822","register_sub_id":"101","register_pk":"367725","name":"椿八幡神社本殿","kana":"つばきはちまんじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県阿南市椿町浜1-1","lat":33.92174167,"lng":134.65957194,"geo_status":"db","era":"安政3年(1856)頃","year":1856,"year_source":"db","year_min":1856,"year_max":1856,"year_label":null,"structure":"木造平屋建、檜皮葺(金属板仮葺)、建築面積4.7㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"36 － 191","desc":"市南東部の椿町中心部の境内奥に北面して建つ。一間社流造檜皮葺（鉄板仮葺）で、四周縁を腰組で支持する。組物は柱上の斜め方向にも手先を出す尾垂木付二手先の詰組、妻飾は二重虹梁。組物間や扉回りを彫刻で密に飾る。複雑な構造と豊かな装飾をもつ社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012822"},{"id":"00012990","register_sub_id":"101","register_pk":"368069","name":"釣井薬師堂","kana":"つるいやくしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県三好市東祖谷釣井107","lat":33.86614722,"lng":133.86609722,"geo_status":"db","era":"文久2年（1862）／昭和33年・平成11年改修","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"36 － 195","desc":"祖谷川上流の釣井集落にある三間堂。宝形造銅板葺で、出桁造の一軒疎垂木、四周に切目縁を廻す。内部は板敷の一室で、東正面と両側面東端1間を吹放しとし、西面に張出しの仏壇を設け、各間に桟唐戸を吊る。祖谷渓の歴史的な集落景観の構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012990"},{"id":"00009222","register_sub_id":"101","register_pk":"164775","name":"東福寺本堂","kana":"とうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字木屋341","lat":34.00313675,"lng":134.077586,"geo_status":"db","era":"天保4年(1833)／昭和40年改修","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積374㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"境内中央に東面する。桁行26.2メートル梁間13.1メートル、寄棟造本瓦葺で、周囲に下屋を廻らし、正面に唐破風造銅板葺の玄関を構える。東面に広縁を通しその奥を8間取とし、後列南第2間を内陣とする。北寄りはもと庫裏。風格ある外観の真言宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009222"},{"id":"00011568","register_sub_id":"101","register_pk":"210500","name":"長瀬堂","kana":"ながせどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字長瀬196","lat":33.99952,"lng":134.08573,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積26㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0157","desc":"端四国八十八箇所霊場の第二八番札所。宝形造桟瓦葺の三間堂で、背面側に仏間を突出させる。四方吹放ちの四周に縁を廻らし、正面中央間は縁を切りこんで木階を設ける。天井は棹縁天井とする。仏間廻りには彫刻を施すが、全体に簡素な意匠でまとめている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011568"},{"id":"00009066","register_sub_id":"101","register_pk":"162426","name":"箸蔵寺高灯籠","kana":"はしくらじたかとうろう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.04395506,"lng":133.84186927,"geo_status":"db","era":"明治17年","year":1884,"year_source":"db","year_min":1884,"year_max":1884,"year_label":null,"structure":"木造二重灯籠、瓦葺、建築面積15㎡","structure_material":"木造二重灯籠","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0101","desc":"吉野川を俯瞰する丘上に建つ。木造二重灯籠、袴腰付、宝形造桟瓦葺で、北面の出入口に唐破風屋根をかける。下重組物は出組で軒を扇垂木、上重は絵様肘木と二軒繁垂木とする。上層は方一間で、柱や天井を漆喰塗込めとし、四面に花頭窓を開く。特異な形式の木造灯籠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009066"},{"id":"00009068","register_sub_id":"101","register_pk":"162428","name":"箸蔵寺中門","kana":"はしくらじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.04751013,"lng":133.84092402,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、間口3.6m、左右袖塀付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0103","desc":"方丈前に東西棟で建つ。切妻造桟瓦葺の一間薬医門で、両脇に袖塀を付ける。五平の本柱を冠木や虹梁形の楣で固め、男梁を四通りに架す。男梁上に大斗肘木を置き、梁や桁を支持。一軒疎垂木で、妻虹梁大瓶束、全面に格天井を張る。規模が大きく威厳ある構え。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009068"},{"id":"00009067","register_sub_id":"101","register_pk":"162427","name":"箸蔵寺手水舎","kana":"はしくらじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.03623358,"lng":133.88784012,"geo_status":"db","era":"明治29年","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"木造、瓦葺、面積6.4㎡、手水鉢付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0102","desc":"本殿東南に位置する。方一間で四方を吹放しとし、軒は二軒繁垂木、屋根は南北棟の入母屋造桟瓦葺である。礎盤上に立てた角柱を頭貫と台輪で固め、組物は出組詰組とする。琵琶板に植物紋様を飾り、手水鉢の四隅を邪鬼で支えるなど、装飾性に富む手水舎である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009067"},{"id":"00009069","register_sub_id":"101","register_pk":"162429","name":"箸蔵寺仁王門","kana":"はしくらじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"徳島県","address":"徳島県三好市池田町州津蔵谷1006他","lat":34.04461903,"lng":133.84202532,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造二階建、瓦葺、建築面積56㎡","structure_material":"木造二階建","registered":"2011.10.28(平成23.10.28)","register_no":"36 － 0104","desc":"山の中腹に位置し、南面する。三間一戸二重門、入母屋造桟瓦葺。上・下重とも出組詰組、二軒繁垂木。上重は桁行三間梁間二間、正面中央に両開桟唐戸、両脇間に花頭窓を穿つ。内部は一室で、側・背面に接して壇を構える。近代における禅宗様二重門の優品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009069"},{"id":"00011567","register_sub_id":"101","register_pk":"210499","name":"日浦堂","kana":"ひうらどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字日浦72","lat":33.99015306,"lng":134.08206,"geo_status":"db","era":"天明8年（1788）／平成24年改修","year":1788,"year_source":"db","year_min":1788,"year_max":1788,"year_label":null,"structure":"木造平屋建、鋼板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0156","desc":"端四国八十八箇所霊場の第二六番札所。寄棟造鉄板葺の三間堂で、背面側を三間幅の仏間とし、三方吹放ちの四方に縁を廻らし、正面中央間には向拝一間を設ける。天井は棹縁天井とする。仏間、向拝等に彫刻を施す。仏間の規模が大きく、比較的装飾豊かである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011567"},{"id":"00011572","register_sub_id":"101","register_pk":"210392","name":"引地堂","kana":"ひきちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字引地167","lat":34.02010389,"lng":134.063335,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0161","desc":"端四国八十八箇所霊場の第三六番札所。寄棟造桟瓦葺で、梁間二間桁行二間半。背面中央に一間幅の仏間を設け、四方吹放ちの三方に縁を廻らし、天井は棹縁天井とする。仏間廻り以外は簡素な造りとするが、正面一間を葺下ろして向拝とする点が特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011572"},{"id":"00011564","register_sub_id":"101","register_pk":"210553","name":"別所堂","kana":"べっしょどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県美馬郡つるぎ町貞光字別所25-1","lat":34.02349389,"lng":134.06430611,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2017.05.02(平成29.05.02)","register_no":"36-0153","desc":"端四国八十八箇所霊場の第一一番札所。宝形造の三間堂で、三方吹放ち。中央奥に幅広の仏間を張出し、三方に縁を廻らす。天井は棹縁天井とする。現在は桟瓦葺であるが、第二次大戦前は茅葺であったと伝える。地域信仰の有り様を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011564"},{"id":"00004638","register_sub_id":"101","register_pk":"105628","name":"萬福寺蔵","kana":"まんぷくじくら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.82283623,"lng":134.47601424,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積23㎡","structure_material":"土蔵造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0052","desc":"境内東方にあり，構造手法から江戸末期と推定される。土蔵造２階建，南北棟の切妻造，桟瓦葺の置屋根式とし，西面に庇付の戸口を設ける。外壁は丁寧な漆喰塗で，腰を押縁下見板張とし，頂部には蛇腹を廻し，妻面の拝みには珍しい松の鰭を付けた懸魚を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004638"},{"id":"00004637","register_sub_id":"101","register_pk":"105627","name":"萬福寺鐘楼","kana":"まんぷくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.82285455,"lng":134.47550286,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積8.7㎡","structure_material":"木造","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0051","desc":"本堂西南にある。方１間の吹放し鐘楼で，二軒繁垂木，入母屋造，本瓦葺である。軸部は角柱を内転びに建て，腰貫・内法貫・頭貫・台輪で結び，三斗を組み，中備蟇股を配する。蟇股や木鼻は独特な形状で地方色があるが，絵様細部は１８世紀中期の特徴を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004637"},{"id":"00004639","register_sub_id":"101","register_pk":"105629","name":"萬福寺鎮守堂","kana":"まんぷくじちんじゅどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.8231147,"lng":134.47555578,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積1.0㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0053","desc":"本堂西に南面してあり，棟札から年代が判明する。乱石積基壇上に建つ１間社見世棚造，板軒，鉄板葺である。身舎は円柱で台輪上に大斗肘木を組み，庇は角柱を虹梁型頭貫で結び，連三斗と中備蟇股をあげる。全体は簡素なつくりだが，境内構成に欠かせない要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004639"},{"id":"00004636","register_sub_id":"101","register_pk":"105626","name":"萬福寺本堂","kana":"まんぷくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県那賀郡那賀町延野字寺前20","lat":33.82295528,"lng":134.47570332,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、茅葺（鉄板仮葺）一部瓦葺、建築面積181㎡","structure_material":"木造平屋建","registered":"2005.02.09(平成17.02.09)","register_no":"36 － 0050","desc":"東西に長い境内に南面して建ち，東の庫裏との間に玄関を設ける。方丈形式の６間取平面で，南と西に広縁を設け，柱は角柱，側廻りは舟肘木とする。屋根は寄棟造，もと茅葺で，４周に本瓦葺の下屋を廻す。いわゆる四方蓋民家風の外観に地域性が現れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004636"},{"id":"00007806","register_sub_id":"101","register_pk":"108787","name":"蓮光寺山門","kana":"れんこうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"徳島県","address":"徳島県名西郡石井町石井字重松531-1","lat":34.07180924,"lng":134.43204164,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積6.3㎡","structure_material":"木造","registered":"2009.08.07(平成21.08.07)","register_no":"36-0078","desc":"境内地の南辺中央に建つ。一間一戸楼門で、上部に鐘を吊る。入母屋造本瓦葺。間口２．６ｍに方柱を建て、前寄りに扉口を設ける。上層は円柱で、三斗組、中備蟇股、二軒繁垂木。縁を腕木で支持し、逆蓮の擬宝珠高欄を付ける。端正な外観をもつ小規模の鐘楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007806"},{"id":"00008197","register_sub_id":"101","register_pk":"132638","name":"宇夫階神社齋殿","kana":"うぶしなじんじゃさいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30794352,"lng":133.82085222,"geo_status":"db","era":"文政元年（1818）／昭和6年改修","year":1818,"year_source":"db","year_min":1818,"year_max":1818,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0365","desc":"境内中段の南寄りに位置する。桁行９．０ｍ梁間１１ｍの木造平屋建、入母屋造桟瓦葺。田の字型に四室を配し、縁をまわす。西北の部屋にトコや棚、平書院を構え、室境には繊細な欄間を飾るなど良質な書院建築。神仏分離により廃された神宮寺の名残を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008197"},{"id":"00008196","register_sub_id":"101","register_pk":"132637","name":"宇夫階神社雑庫","kana":"うぶしなじんじゃざっこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30805643,"lng":133.82077832,"geo_status":"db","era":"明治中期／昭和9年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積27㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0364","desc":"本殿の東南、一段低い位置に建つ。桁行５．０ｍ梁間４．８ｍの２階建土蔵。切妻造本瓦葺で妻入とし、緩い起りの切妻造桟瓦葺の屋根を正面に付ける。腰は目地切をしたモルタル仕上げで、上部は白漆喰仕上げ。小屋組はトラス組。社頭景観を構成する一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008196"},{"id":"00008198","register_sub_id":"101","register_pk":"132639","name":"宇夫階神社社務所","kana":"うぶしなじんじゃしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30793531,"lng":133.82099797,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積162㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0366","desc":"齋殿の東に接続する。入母屋造本瓦葺で、庇を設け、齋殿寄りに入母屋造本瓦葺の式台玄関を付ける。内部は中廊下式で正面側に応接室や事務関係、奥に座敷や居間を配し、西端に土間を設ける。座敷にはトコやトコ脇、平書院を構える。近代的な社務所の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008198"},{"id":"00008194","register_sub_id":"101","register_pk":"132635","name":"宇夫階神社神饌殿","kana":"うぶしなじんじゃしんせんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30811596,"lng":133.82062231,"geo_status":"db","era":"昭和16年","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0362","desc":"拝殿の南隣に東西棟で建つ。桁行三間梁間三間、入母屋造妻入銅板葺。壇正積基壇上に建ち、方柱で舟肘木を置き、一軒疎垂木。正面中央に両開板戸をたて、側面前一間、背面中央一間に格子窓を開け、他は腰板張とする漆喰仕上げの真壁で、平明な外観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008194"},{"id":"00008193","register_sub_id":"101","register_pk":"132634","name":"宇夫階神社忠魂社本殿","kana":"うぶしなじんじゃちゅうこんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30812007,"lng":133.82039033,"geo_status":"db","era":"昭和10年","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.8㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0361","desc":"本殿の西南に位置し、東面する。高い亀甲積基壇上に建つ入母屋造銅板葺の浜縁付一間社。正側面に高欄付の切目縁をまわし、正面に木階を付ける。出組詰組、二軒繁垂木とするなど、塩竃神社本殿に比べて規模が小さいものの、同様の構造形式とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008193"},{"id":"00004438","register_sub_id":"101","register_pk":"105428","name":"宇夫階神社本殿（旧多賀宮御正殿）","kana":"うぶしなじんじゃほんでん（きゅうたかのみやごせいでん）","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"香川県","address":"香川県綾歌郡宇多津町1644","lat":34.30824493,"lng":133.82045804,"geo_status":"db","era":"昭和28／昭和51移築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"37 － 0229","desc":"昭和２８年の式年遷宮で造営された豊受大神宮の多賀宮御正殿。次の式年遷宮に際し解体，頒賜された。桁行３間，梁間２間，切妻造の茅葺型銅板葺屋根を架ける。縁を廻さず，棟持柱，堅魚木，千木をもつ正式の神明造で，掘立て柱の伝統的工法をよく残している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004438"},{"id":"00008192","register_sub_id":"101","register_pk":"132633","name":"宇夫階神社末社金刀比羅宮拝殿及び幣殿","kana":"うぶしなじんじゃまっしゃことひらぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30867228,"lng":133.82066952,"geo_status":"db","era":"明治7年","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0360","desc":"塩竈神社本殿の西北に南面して建つ。桁行三間梁間二間、入母屋造本瓦葺で、正面に向拝一間、背面に幣殿を付設する。内部は拭板敷で、棹縁天井を張り、正面に縁を付ける。向拝のみ三斗組とし、中備に波紋彫刻を置く。身舎は組物などを省略し簡明な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008192"},{"id":"00008191","register_sub_id":"101","register_pk":"132632","name":"宇夫階神社末社塩竈神社拝殿及び幣殿","kana":"うぶしなじんじゃまっしゃしおがまじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30835615,"lng":133.82080501,"geo_status":"db","era":"昭和9年／昭和60年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積67㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0359","desc":"塩竈神社本殿の正面に位置する。桁行三間梁間二間の入母屋造銅板葺で、正面に軒唐破風付一間向拝を付設。背面に桁行三間梁間三間切妻造の幣殿を突出する。正面中央に双折桟唐戸、両脇に蔀戸を装置する。安定感のある外観で、向拝の龍や鳳凰の彫刻は出色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008191"},{"id":"00008190","register_sub_id":"101","register_pk":"132631","name":"宇夫階神社末社塩竈神社本殿","kana":"うぶしなじんじゃまっしゃしおがまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30842389,"lng":133.82077011,"geo_status":"db","era":"昭和9年／昭和60年改修","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0358","desc":"小丘に占める境内の最上段、本殿の北方に位置し、高い亀甲積基壇上に建つ。桁行一間梁間一間、入母屋造、向拝一間、銅板葺の社殿で、正面に千鳥破風と軒唐破風を付ける。本支輪付の出組詰組とし、要所に彫物を飾る。二軒繁垂木。瀟洒ながら本格的な仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008190"},{"id":"00008195","register_sub_id":"101","register_pk":"132636","name":"宇夫階神社神輿蔵","kana":"うぶしなじんじゃみこしぐら","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県綾歌郡宇多津町字西町1644-1他","lat":34.30790247,"lng":133.82042113,"geo_status":"db","era":"昭和9年頃","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積52㎡","structure_material":"土蔵造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0363","desc":"本殿の南方に位置し北面する。桁行９．６ｍ梁間４．８ｍの土蔵造、切妻造本瓦葺。石積基壇上に建ち、腰を黒色のモルタル仕上げ、上部を白漆喰仕上げとする。腰内部は二室に間仕切り、それぞれに緩い起りの切妻造銅板葺の庇を付けて、硬質な外観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008195"},{"id":"00000103","register_sub_id":"101","register_pk":"101093","name":"金刀比羅宮宝物館","kana":"こんぴらぐうほうもつかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県仲多度郡琴平町892-1","lat":34.18455385,"lng":133.81316693,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"石造2階建、瓦葺、建築面積165㎡","structure_material":"石造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"37 － 0004","desc":"石造，２階建の宝物館で，文部省技師久留正道の設計である。入母屋造，本瓦葺の屋根や唐破風造の玄関等をもつ一方，アーチ窓や石組による目地等を用いる。日本人建築家が，伝統的な建築に本格的な洋風の意匠を持ち込んだ初期の事例として注目できる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000103"},{"id":"00012247","register_sub_id":"101","register_pk":"353047","name":"讃留霊王神社玉垣","kana":"さるれおじんじゃたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県丸亀市飯山町下法軍寺1459","lat":34.24734,"lng":133.849979,"geo_status":"db","era":"江戸末期／明治後期増設","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長20m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"37-429","desc":"神社の御神体である円墳、讃留霊王古墳の墳頂部を方形に画す玉垣。花崗岩製、総延長二〇メートルで、正面に当たる東側を開いて幣殿との間を通路状に結ぶ。特徴的な構成をとる神社を象徴するとともに、地域の歴史的景観を形成する玉垣である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012247"},{"id":"00012248","register_sub_id":"101","register_pk":"353048","name":"讃留霊王神社鳥居","kana":"さるれおじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県丸亀市飯山町下法軍寺1459","lat":34.247417,"lng":133.850315,"geo_status":"db","era":"文政13年(1830)","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"石造、間口2.2m、高さ2.9m","structure_material":"石造","registered":"2018.03.27(平成30.03.27)","register_no":"37-430","desc":"境内東端部の入口から拝殿・幣殿へと上がる階段の中ほどに建つ石造明神鳥居。間口二・二メートルで、柱をやや内転びで立て、島木と反りの強い笠木で結ぶ。柱に「文政十三年」と彫られており年代も明らかで、境内の歴史的景観を今に伝える鳥居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012248"},{"id":"00012246","register_sub_id":"101","register_pk":"353046","name":"讃留霊王神社幣殿","kana":"さるれおじんじゃへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市飯山町下法軍寺1459","lat":34.247359,"lng":133.850063,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、檜皮葺（銅板仮葺）、建築面積6.0㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"37-428","desc":"丸亀市南方平野部の小高い丘陵上に位置する。入母屋造平入、檜皮葺の一間社で、円柱上に二手先を組み、軒は二軒扇垂木とし、四方に縁を廻らす。背面側の讃留霊王古墳を御神体とし、正面だけでなく背面側にも桟唐戸を設ける点が特徴である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012246"},{"id":"00014414","register_sub_id":"101","register_pk":"511403","name":"三所神社幣拝殿","kana":"さんしょじんじゃへいはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市本島町生ノ浜字浦内635","lat":34.38158333,"lng":133.76031111,"geo_status":"db","era":"明治30年","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積38㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0465","desc":"塩飽諸島本島の生ノ浜浦に所在する神社の拝殿及び弊殿。正面三間側面二間、入母屋造本瓦葺、正面に千鳥破風、唐破風向拝を重ねる。背面に弊殿を張り出し、本殿と接続する。水引虹梁、蟇股、手挟、向拝の彫刻に技量を示す。塩飽大工活動末期の社殿として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014414"},{"id":"00014413","register_sub_id":"101","register_pk":"511402","name":"三所神社本殿","kana":"さんしょじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県丸亀市本島町生ノ浜字浦内635","lat":34.38160556,"lng":133.76038333,"geo_status":"db","era":"天保元年（1830）","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.2㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"37 - 0464","desc":"塩飽諸島本島の生ノ浜浦に所在する神社本殿。一間社流造、本瓦葺で二重切石基壇、亀腹上に建つ。正側面に高欄付切目縁を廻らし、身舎両袖に脇障子を建てる。板支輪の彫刻、手挟や木鼻の丸彫彫刻等、いずれも巧緻で躍動感があり塩飽大工の力量が示される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014413"},{"id":"00002442","register_sub_id":"101","register_pk":"103432","name":"清水観音堂","kana":"しみずかんのんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県小豆郡土庄町豊島唐櫃字東伏1261-3","lat":34.48555743,"lng":134.08544038,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、瓦葺、建築面積27㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0058","desc":"共同用水場南側の階段上にある桟瓦葺，切妻造の観音堂。桁行と梁間は約４ｍで，前方に向拝を張り出す。後方に仏壇，その右側に附属屋を設ける。簡素な建物であるが，当地域での水と信仰との結びつきを物語り，水利施設と一体の独特の空間を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002442"},{"id":"00002443","register_sub_id":"101","register_pk":"103433","name":"清水神社社殿","kana":"しみずじんじゃしゃでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県小豆郡土庄町豊島唐櫃字東状1261-2","lat":34.48574733,"lng":134.08531107,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積15㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"37 － 0059","desc":"共同用水場西方の階段上段にある，本瓦葺，前方入母屋造の社殿。石造基礎の上に，梁間４ｍ，桁行３ｍ，外装杉板張の建家が立ち上がり，後方に板石を積んだ約１ｍ幅の祭壇を張り出す。小屋梁の墨書により，大正２年造と知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002443"},{"id":"00012833","register_sub_id":"101","register_pk":"367736","name":"正蓮寺大玄関及び小玄関","kana":"しょうれんじおおげんかんおよびしょうげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"弘化2年（1845）／昭和28年頃・平成27年改修","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 440","desc":"本堂の東側に接続し、西に入母屋造妻入の大玄関、東に両下造の小玄関を配し、東面を庫裏に接続する。大玄関は式台を構えて奧に三室を並べ、最奧を座敷とする。小玄関は渡廊下を兼ね、後方に控室を設ける。本堂、庫裏と並び建ち、境内の景観を重厚に整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012833"},{"id":"00012835","register_sub_id":"101","register_pk":"367738","name":"正蓮寺経蔵","kana":"しょうれんじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"明治12年／平成4年・同10年頃改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積26㎡","structure_material":"土蔵造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 442","desc":"境内前方の山門東脇に北面して建つ。六角形平面の本瓦葺で、切妻造起り屋根の向拝を付す。外壁は柱形を表した大壁造で、正面に扉口、西面に花頭窓を設け、向拝は動物の具象的な彫刻で賑やかに飾る。参道を挟んで鐘楼と並び建ち、境内の表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012835"},{"id":"00012836","register_sub_id":"101","register_pk":"367739","name":"正蓮寺山門","kana":"しょうれんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 443","desc":"境内南面の西寄りに建つ。切妻造本瓦葺の薬医門で、親柱は大断面の五平材を用い、控柱も木太い角柱に絵様付の虹梁を渡すなど量感あるつくりとする。軒は二軒半繁垂木、妻飾は笈形付大瓶束で蕪懸魚を吊る。境内の江戸中期の建築形式を伝える貴重な建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012836"},{"id":"00012834","register_sub_id":"101","register_pk":"367737","name":"正蓮寺鐘楼","kana":"しょうれんじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、面積8.9㎡","structure_material":"木造","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 441","desc":"境内前方の山門西脇に東面して建つ。入母屋造本瓦葺の吹放し鐘楼で、布積基壇に反りのある角柱を内転びで立て、三段に通した貫で固める。組物は二重尾垂木付三手先の詰組、軒は二軒扇垂木である。均整のとれた禅宗様建築で、境内の表構えを引き締めている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012834"},{"id":"00012832","register_sub_id":"101","register_pk":"367735","name":"正蓮寺本堂","kana":"しょうれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県坂出市加茂町字井出東1048他","lat":34.31171778,"lng":133.91462389,"geo_status":"db","era":"文政8年（1825）／平成4年・同28年改修","year":1825,"year_source":"db","year_min":1825,"year_max":1825,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積332㎡","structure_material":"木造平屋建","registered":"2019.03.29(平成31.03.29)","register_no":"37 － 439","desc":"市西部の五色台西麓にある真宗寺院。本堂は南正面の入母屋造本瓦葺、向拝一間付。内部を円柱、側廻りを角柱とし、向拝は木鼻に龍や獏を彫刻し、虹梁には波に鯉の躍動的な文様をあしらうなど装飾豊かに仕上げる。讃岐地方の江戸後期真宗本堂の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012832"},{"id":"00007928","register_sub_id":"101","register_pk":"108908","name":"善通寺釈迦堂","kana":"ぜんつうじしゃかどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22634176,"lng":133.77679782,"geo_status":"db","era":"延宝年間／天保2移築・昭和45年改修","year":1677,"year_source":"estimated","year_min":1673,"year_max":1681,"year_label":"延宝年間","structure":"木造平屋建、瓦葺、建築面積152㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0328","desc":"金堂の南東に位置する。桁行五間梁間六間、入母屋造、向拝一間軒唐破風付、本瓦葺。堂内は中央背面に接して仏壇を構え、前方に板敷を設けて内陣とし、三方に外陣をめぐらす。四周に縁を付け、方柱で舟肘木、引違い舞良戸をたてるなど、住宅風仏堂の特徴をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007928"},{"id":"00007931","register_sub_id":"101","register_pk":"108911","name":"善通寺鐘楼","kana":"ぜんつうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22596521,"lng":133.77629781,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積23㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0331","desc":"金堂の南西に建つ鐘楼で、桁行三間梁間二間、袴腰付、入母屋造本瓦葺である。挿肘木と虹梁上の三斗で擬宝珠高欄付縁を支持し、上層は組物を平三斗組として扇垂木で総反りの軒を受ける。もと鐘楼門であった痕跡をとどめる鐘楼で、境内景観を引き立てている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007931"},{"id":"00008178","register_sub_id":"101","register_pk":"132619","name":"善通寺誕生院閻魔堂及び渡廊下","kana":"ぜんつうじたんじょういんえんまどうおよびわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22564022,"lng":133.77432037,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0346","desc":"護摩堂と東の親鸞堂を繋ぐ渡廊下。桁行五間梁間一間、切妻造桟瓦葺。中央三間は南面を開放、北面は屋根を葺き降ろして奥行一間の閻魔堂を造り、蔀戸を吊る。両端一間は北面が真壁造で連子窓を開け、南面は腰壁。基本的に廻廊と同じ意匠で、統一感をもたせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008178"},{"id":"00008171","register_sub_id":"101","register_pk":"132612","name":"善通寺誕生院奥殿","kana":"ぜんつうじたんじょういんおくでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22497607,"lng":133.77393569,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積98㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0339","desc":"誕生院伽藍の中央に東面して建ち、釣屋を介して御影堂に続く。方三間、宝形造本瓦葺。四周に縁をまわし、円柱で、平三斗組とし、中央間に蟇股を飾る。正面中央間は唐破風屋根を付け、厨子風に造り、彫刻や彩色で飾る。繊細優美な姿で、厳粛な雰囲気を醸し出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008171"},{"id":"00008186","register_sub_id":"101","register_pk":"132627","name":"善通寺誕生院極楽堀石積","kana":"ぜんつうじたんじょういんごくらくほりいしづみ","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22565782,"lng":133.77477393,"geo_status":"db","era":"明治22年","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"石造、延長193m、柵付","structure_material":"石造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0354","desc":"誕生院境内の東端に、深さ１．３ｍ、幅６．５ｍ、南北９０ｍに及ぶ極楽堀が掘られる。四周に切石を積み上げて擁壁を造り、延長１９３ｍを測る。通り側に構える石柵は、布石上に方形の柵子を建て、六本おきに太くし、その間に笠石を載せる。堅固な構えを造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008186"},{"id":"00008175","register_sub_id":"101","register_pk":"132616","name":"善通寺誕生院護摩堂","kana":"ぜんつうじたんじょういんごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.2255646,"lng":133.77424475,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0343","desc":"聖霊殿の東北に南面して建つ。正面三間側面三間で、内・外陣からなり、周囲に縁をまわす。宝形造銅板葺の二重屋根とし、正面に向拝一間を付ける。円柱、平三斗組で、中備に間斗束を置く。軒は二軒疎垂木。木鼻や蟇股、肘木などに復古的な細部意匠を採用する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008175"},{"id":"00008177","register_sub_id":"101","register_pk":"132618","name":"善通寺誕生院護摩堂廻廊","kana":"ぜんつうじたんじょういんごまどうかいろう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22546268,"lng":133.77400802,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積56㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0345","desc":"聖霊殿から地蔵堂の側・背面を通り、護摩堂に至る廊下。切妻造銅板葺、地蔵堂側を開放、北・西面は真壁造で連子窓を設け、出入口を一ヶ所開ける。方柱で、舟肘木を置き、梁間に虹梁を渡し、蟇股で棟木を支持。土間床で化粧屋根裏天井とし、閑静な空間を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008177"},{"id":"00008176","register_sub_id":"101","register_pk":"132617","name":"善通寺誕生院地蔵堂","kana":"ぜんつうじたんじょういんじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22552844,"lng":133.77407378,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積6.6㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0344","desc":"護摩堂の西に位置し、南面する。両脇間が狭い方三間仏堂。宝形造銅板葺で正面に軒唐破風を付ける。周囲に葛石をまわし、切石礎石上に方柱を建て、舟肘木を置く。一軒疎垂木。土間で、格天井を張り、中央に石造地蔵を安置する。勾配の緩い、穏やかな外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008176"},{"id":"00008174","register_sub_id":"101","register_pk":"132615","name":"善通寺誕生院聖霊殿","kana":"ぜんつうじたんじょういんしょうりょうでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22535089,"lng":133.77406392,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、銅板葺及び檜皮葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0342","desc":"御影堂の北に並び立ち、桁行三間の渡廊下で繋がる。宝形造銅板葺で、四周に檜皮葺の裳階をまわし、正面の中央間を切り上げ、銅板葺とする。正面三間側面四間とし、内・外陣に分け、小組格天井を張る。方柱で舟肘木、緩やかな一軒疎垂木を配る端正な仏堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008174"},{"id":"00008179","register_sub_id":"101","register_pk":"132620","name":"善通寺誕生院宸殿","kana":"ぜんつうじたんじょういんしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22460454,"lng":133.77441243,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積215㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0347","desc":"御影堂の南方に建つ東西棟の入母屋造桟瓦葺。桁行２０ｍ梁間１１ｍで、組高欄付の切目縁を三方にまわす。南北各四室からなる八間取で、北面に畳廊下を付設する。南面西端間が上段の間で、トコや棚を構え、二重折上小組格天井とする。規模が大きく、風格がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008179"},{"id":"00008180","register_sub_id":"101","register_pk":"132621","name":"善通寺誕生院大玄関及び小玄関","kana":"ぜんつうじたんじょういんだいげんかんおよびしょうげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22470976,"lng":133.77458669,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積201㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0348","desc":"宸殿の東に取り付き、北側に大玄関、南に小玄関を配する。大玄関は入母屋造妻入瓦葺で、正面に軒唐破風を付ける。式台を設け、天井は二重折上小組格天井とする。小玄関は入母屋造で、格天井として、両脇間に花頭窓を開ける。宸殿正面に格調ある構えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008180"},{"id":"00008185","register_sub_id":"101","register_pk":"132626","name":"善通寺誕生院太鼓塀","kana":"ぜんつうじたんじょういんたいこべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22526541,"lng":133.77494178,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、延長61m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0353","desc":"勅使門の南北に延び、北は番所に、南は通用口に至る。折曲り総延長６１ｍに及ぶ。極楽堀に接する場所は護岸石積上に、その他は切石基礎上に建ち、勅使門の袖部分では高さ２．７ｍ、他は２．３ｍを測る。本瓦葺とし、五線の定規筋を入れ、格式が窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008185"},{"id":"00008189","register_sub_id":"101","register_pk":"132630","name":"善通寺誕生院勅使橋","kana":"ぜんつうじたんじょういんちょくしばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22518321,"lng":133.77505685,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"石造桁橋、橋長6.5m、幅員3.6m、脚柱付","structure_material":"石造桁橋","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0357","desc":"勅使門の東、極楽堀に架かる。石造桁橋で、中央に橋脚を建てる。橋長６．５ｍ、幅員３．６ｍ。緩やかに起る太鼓橋で、擬宝珠高欄を付ける。擬宝珠柱は両側に各八本ずつ建て、柱身に対して宝珠が大きく、斗束も分銅形にするなど、装飾的な要素が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008189"},{"id":"00008184","register_sub_id":"101","register_pk":"132625","name":"善通寺誕生院勅使門","kana":"ぜんつうじたんじょういんちょくしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22515033,"lng":133.77496151,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、銅板葺、間口3.0m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0352","desc":"仁王門の南方、大玄関の東北に位置する四脚門。前後唐破風造側面切妻造の銅板葺。本柱を円柱、控柱を几帳面取方柱とし、三斗組で、正・背面中備に蟇股を置く。周囲に葛石をまわし、土間床とし、全面に格天井を張る。緩やかな屋根勾配で、優雅な外観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008184"},{"id":"00008182","register_sub_id":"101","register_pk":"132623","name":"善通寺誕生院仁王門","kana":"ぜんつうじたんじょういんにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.2253476,"lng":133.77474451,"geo_status":"db","era":"明治22年／昭和50年修理","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0350","desc":"御影堂の東に位置する三間一戸八脚門。入母屋造本瓦葺とし、棟に鯱を飾る。大斗肘木。二軒繁垂木で鏡天井を張り、床は石敷。両脇間には石積基礎を設け、正面側に金剛柵を付け、金剛力士像を安置し、背面には大草鞋を飾る。規模が大きく、力強い外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008182"},{"id":"00008188","register_sub_id":"101","register_pk":"132629","name":"善通寺誕生院二十日橋","kana":"ぜんつうじたんじょういんはつかばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22543309,"lng":133.7748826,"geo_status":"db","era":"昭和17年／昭和後期移設","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"石造桁橋、橋長6.8m、幅員5.4m、脚柱付","structure_material":"石造桁橋","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0356","desc":"仁王門の東、極楽堀に架かる。明治以前は毎月二十日のみ橋の通行が許されたと伝え、その由来でこの名がある。石造桁橋で、中央に橋脚を建てる。橋長６．８ｍ、幅員５．４ｍ。緩やかな太鼓橋で、擬宝珠高欄を付け、岸上では外に開く。伝統的な石橋の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008188"},{"id":"00008183","register_sub_id":"101","register_pk":"132624","name":"善通寺誕生院番所","kana":"ぜんつうじたんじょういんばんしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22529828,"lng":133.77477081,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積9.3㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0351","desc":"仁王門の南に南北棟で建つ。桁行４．０ｍ梁間２．３ｍの木造平屋建。緩い起りを付ける入母屋造で本瓦を葺く。仁王門寄りの東面半間と北面に銅板葺庇付の出格子窓を付ける。腰に下見板を張り、真壁造。内部は一室で、畳敷とする。誕生院伽藍の正面を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008183"},{"id":"00008187","register_sub_id":"101","register_pk":"132628","name":"善通寺誕生院弁天社","kana":"ぜんつうじたんじょういんべんてんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22551857,"lng":133.77482999,"geo_status":"db","era":"慶応3年(1867)","year":1867,"year_source":"db","year_min":1867,"year_max":1867,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積0.9㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0355","desc":"極楽堀のなか、二十日橋の北側に西面して建つ。石造の基礎組上に建つ一間社流造、本瓦葺。小規模な社殿で、側・背面板壁とし、正面に両開桟唐戸をたてる。縁を張らず、正面に木階を付ける。三斗組で、向拝の中備や木鼻に彫刻を飾る。堀に建つ特徴的な景観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008187"},{"id":"00008172","register_sub_id":"101","register_pk":"132613","name":"善通寺誕生院御影堂","kana":"ぜんつうじたんじょういんみえどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"昭和前","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22513974,"lng":133.77424548,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積554㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0340","desc":"奥殿の前に建つ。前寄りで十字形に入母屋屋根が交叉し、正面に三間向拝を付ける。前方は桁行七間梁間四間で外陣とし、その奥に桁行六間梁間五間の内陣を付設、周囲に縁をまわす。組物は平三斗。内部は内・外陣とも格天井を張り、平明で広い礼拝空間を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008172"},{"id":"00008173","register_sub_id":"101","register_pk":"132614","name":"善通寺誕生院御影堂前廻廊","kana":"ぜんつうじたんじょういんみえどうまえかいろう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22526212,"lng":133.7745571,"geo_status":"db","era":"大正4年","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0341","desc":"御影堂前に位置する、東西棟の本瓦葺建物。桁行九間梁間一間で吹き放ち、妻を唐破風造とする。礎石上に几帳面取方柱を建て、柱上に三斗を組み、虹梁形頭貫で固め、大瓶束が棟木を支持する。梁間中備の龍彫刻や、柱の貘鼻、獅子鼻が重畳し、御影堂の参道を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008173"},{"id":"00008181","register_sub_id":"101","register_pk":"132622","name":"善通寺誕生院南土蔵","kana":"ぜんつうじたんじょういんみなみどぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市善通寺町3-615他","lat":34.22421,"lng":133.77408693,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"37 － 0349","desc":"伽藍の南西隅に位置する。南北棟の切妻造桟瓦葺の置屋根。高く切石を積み上げて基礎とし、壁は白漆喰仕上げ。北面に両開戸を装置し、東・西面に窓を穿つ。内部は板敷で、壁を板張とする。１階は引違い戸をたて南一間を間仕切る。装飾的要素を廃した簡明な土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008181"},{"id":"00007929","register_sub_id":"101","register_pk":"108909","name":"善通寺天神社","kana":"ぜんつうじてんじんしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22655164,"lng":133.77642538,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積2.4㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0329","desc":"金堂の北東に祀られた小規模な一間社流見世棚造。切石積基壇上に建ち、土台上に方柱を建てて、舟肘木を置き、桁を受け、一軒繁垂木、本瓦を葺く。外壁は横板張とする。周囲を石柵で囲い、正面に石鳥居を建てて、寺院境内社としての風致を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007929"},{"id":"00007933","register_sub_id":"101","register_pk":"108913","name":"善通寺中門","kana":"ぜんつうじなかもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22584175,"lng":133.77571962,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積27㎡、袴腰付","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0333","desc":"境内の西辺中央、釈迦堂の正面に建つ。一間一戸楼門、入母屋造本瓦葺である。下層では左右に袴腰状の板壁を設け、虹梁には雲龍や鶴を彫る。上層は桁行三間梁間二間とし、吹き放つ。軒は総反りで垂木を扇に配り、優美な意匠とする。特異な外観をもつ門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007933"},{"id":"00007932","register_sub_id":"101","register_pk":"108912","name":"善通寺南大門","kana":"ぜんつうじみなみだいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22565863,"lng":133.77670728,"geo_status":"db","era":"明治41頃","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造、瓦葺、間口7.6m、左右袖塀付","structure_material":"木造","registered":"2009.11.02(平成21.11.02)","register_no":"37-0332","desc":"境内の南辺中央、金堂の正面に建ち、間口７．６ｍの門の左右に矩折れに延ばした袖塀に潜りを開く。高麗門形式の平唐門で、前後に軒唐破風を付け、本瓦を葺く。建ちが高く、左右の螻羽の出も深く、役物瓦の意匠も見応えがあり、古刹の正門に相応しい風格を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007932"},{"id":"00007930","register_sub_id":"101","register_pk":"108910","name":"善通寺龍王社","kana":"ぜんつうじりゅうおうしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県善通寺市善通寺町3-622","lat":34.22651871,"lng":133.77560851,"geo_status":"db","era":"文化5／文久元改修","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積3.0㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"37-0330","desc":"境内北西にある池の小島に所在。規模の小さな一間社流造、本瓦葺である。野面積基壇上に土台を設け、方柱を建て三斗を組む。一軒疎垂木で、妻は虹梁大瓶束。妻の中備を雲紋彫刻、向拝の中備を波頭紋とするなど、雨乞祈願のための社らしい意匠をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007930"},{"id":"00002691","register_sub_id":"101","register_pk":"103681","name":"乃木神社鳥居","kana":"のぎじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22559606,"lng":133.78057178,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"石造、高さ3m、幅3m","structure_material":"石造","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0089","desc":"手水舎の北東方，四国学院大学方面から入る参道のほぼ中央，参道が社務所前でクランク状になる手前側に建つ。柱径５５ｃｍの御影石を用いた石造鳥居で，柱間５ｍほどの規模。神明造の本殿に対応して，直線材を用い貫が柱内に納まる神明鳥居の形式を採る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002691"},{"id":"00002688","register_sub_id":"101","register_pk":"103678","name":"乃木神社拝殿","kana":"のぎじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22535661,"lng":133.77995231,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0086","desc":"本殿と同様に切石積基壇の上に建ち，正面５間の中央３間を入口とし，西面本殿側に幣殿を，北西方に祭器庫を突出させる。屋根は銅板葺で，棟を千木と勝男木で飾り，正面屋根に千鳥破風をつくっているが，全体的に神明造風の簡潔な直線的造形で統一されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002688"},{"id":"00002687","register_sub_id":"101","register_pk":"103677","name":"乃木神社本殿","kana":"のぎじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22530614,"lng":133.77984631,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0085","desc":"もと歩兵第４３連隊跡地の北側に位置し，切石積基壇上の亀腹の上に東面して建つ。棟持柱を持つ三間社神明造の本殿で，柱は円柱，屋根は銅板葺とする。木部は全体に素木で，正面に桁行梁間とも１間の両下造向拝を設け，正面階及び本殿四周に高欄を廻らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002687"},{"id":"00010366","register_sub_id":"101","register_pk":"199138","name":"萩原寺大門及び番所","kana":"はぎわらじおおもんおよびばんしょ","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2742-1","lat":34.070929,"lng":133.687356,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"大門 木造、瓦葺、間口3.3m、左右袖塀及び潜戸付 番所 木造平屋建、瓦葺、建築面積18㎡","structure_material":"大門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0406","desc":"境内西側本坊の客殿正面に位置する。大門は切妻造本瓦葺の四脚門で左右に袖塀を続けて潜戸を開く。ケヤキ造で妻飾の笈型や絵様など要所に濃密な彫刻を施し、時代的特色をよく表す。北方には桁行三間梁間二間の番所を付設する。本坊入口の厳格な雰囲気を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010366"},{"id":"00010363","register_sub_id":"101","register_pk":"199135","name":"萩原寺客殿","kana":"はぎわらじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2742-1","lat":34.070828,"lng":133.687047,"geo_status":"db","era":"宝暦14年（1764）頃","year":1764,"year_source":"db","year_min":1764,"year_max":1764,"year_label":null,"structure":"木造平屋建、茅葺一部瓦葺、建築面積241㎡、門付","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0403","desc":"境内西側本坊の中心に東面して建つ大型客殿で、北端に唐破風屋根の式台を構えて御成門を従え、南側は西列に三室、東列に二室を配し、南西隅に上段の間を配する。屋根は茅葺の四方に瓦葺屋根を廻らす、当地で四方蓋と呼ぶ形式をもち、地方的特色を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010363"},{"id":"00010362","register_sub_id":"101","register_pk":"199134","name":"萩原寺護摩堂","kana":"はぎわらじごまどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.071205,"lng":133.687839,"geo_status":"db","era":"江戸前期／享保10年（1725）・昭和10年頃・昭和58年改修","year":1638,"year_source":"estimated","year_min":1615,"year_max":1661,"year_label":"江戸前期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0402","desc":"境内中央の山麓部に南面して建つ。方三間で宝形造の外陣の背面に切妻造の内陣を張出し、正面に一間向拝を付す。外陣は面取の大きい角柱に舟肘木を載せ、軒をせがい造として深くとる。内陣床下には石積みの護摩壇が設けられ、古来よりの信仰形態を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010362"},{"id":"00010364","register_sub_id":"101","register_pk":"199136","name":"萩原寺鐘楼","kana":"はぎわらじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.070863,"lng":133.688344,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0404","desc":"本堂へ登る石段の参道脇に建つ吹放ち形式の鐘楼で、入母屋造本瓦葺である。面取角柱を四方転びに立て、貫で繋ぐ。頭貫木鼻に獅子彫刻を飾り、頭貫上に台輪を廻して三斗を組み、中備に龍や波紋に彫刻化した蟇股を飾る。境内景観に寄与する端正な意匠の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010364"},{"id":"00010365","register_sub_id":"101","register_pk":"199137","name":"萩原寺手水舎","kana":"はぎわらじてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.070914,"lng":133.688457,"geo_status":"db","era":"昭和11年頃","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造、瓦葺、面積5.0㎡、手水鉢付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0405","desc":"本堂南方に東西棟で建つ切妻造本瓦葺の手水舎。石製礎盤上に角柱を四方転びに立て、頭貫と台輪を廻らして固める。四隅に皿斗付大斗の三斗を組み、桁と梁を受け、中備蟇股とする。軒は反りのある垂木を疎に配る。ケヤキの良材を使い、堅実な意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010365"},{"id":"00010361","register_sub_id":"101","register_pk":"199133","name":"萩原寺本堂","kana":"はぎわらじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2737-1","lat":34.07112,"lng":133.688428,"geo_status":"db","era":"享保8年（1723）／宝暦4年（1754）・昭和10年改修","year":1723,"year_source":"db","year_min":1723,"year_max":1723,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積207㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0401","desc":"境内東丘陵上に南面し、桁行五間梁間六間、正面三間向拝付、本瓦葺。内部は前後に二分し、内外陣とも三間梁を架けて無柱の室とする。粽付円柱に台輪を廻して三斗詰組とし、桟唐戸をたてるなど禅宗様を積極的に取入れており、近世密教系寺院仏堂の一様相を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010361"},{"id":"00010367","register_sub_id":"101","register_pk":"199139","name":"萩原寺南門及び土塀","kana":"はぎわらじみなみもんおよびどべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県観音寺市大野原町萩原字寺上2742-1","lat":34.07075267,"lng":133.68742303,"geo_status":"db","era":"江戸末期／昭和53年・平成3年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"南門 木造、瓦葺、間口2.6m 土塀 土塀、瓦葺、総延長89m","structure_material":"南門 木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0407","desc":"境内本坊部分の東辺を画する土塀と、大門の南方にあけられた南門からなる。南門は一間薬医門の形式で、本柱、控柱とも丸太材を使用して野趣にあふれた景観を形成する。土塀は総延長八九メートルに及ぶ長大なもので、本坊の表構えに緊張感と格調を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010367"},{"id":"00013198","register_sub_id":"101","register_pk":"368422","name":"本堯寺松平頼該霊廟","kana":"ほんぎょうじまつだいらよりかねれいびょう","category":"宗教","subcategory":"建築物","type_guess":"塔","type_guess_confidence":"low","period":"明治","pref":"香川県","address":"香川県高松市西山崎町850-1","lat":34.275675,"lng":133.990425,"geo_status":"db","era":"明治元年／明治42年改修","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡、無縫塔付","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"37 － 0444","desc":"高松藩松平家一門の頼該を祀る霊廟建築。無縫塔の墓石に一間四方で本瓦葺の宝形屋根をかけて奥殿と称し、四畳の寄棟造の拝殿とを二畳の相の間で繋ぐ。奥殿のみ丸柱に扇垂木として意匠を変える。複合社殿形式の武家廟所の遺例として希少である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013198"},{"id":"00009845","register_sub_id":"101","register_pk":"195674","name":"宮處八幡宮注連柱","kana":"みやどころはちまんぐうしめばしら","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30581477,"lng":134.11365662,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"石造、間口5.3m、脇柱付","structure_material":"石造","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0396","desc":"境内下段の石段上に建つ。見付〇・六メートル見込〇・五メートル、高さ四・二メートルの花崗石製の本柱一対を間口五・三メートルに立て、各々の両側に脇柱を立てて石貫で繋ぐ。本柱間には注連縄を張る。端正な意匠の注連柱で、境内入口の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009845"},{"id":"00009843","register_sub_id":"101","register_pk":"195672","name":"宮處八幡宮拝殿及び幣殿","kana":"みやどころはちまんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30610387,"lng":134.1138208,"geo_status":"db","era":"拝殿 明治11 幣殿 明治33","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積131㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0394","desc":"拝殿は桁行五間梁間二間、入母屋造本瓦葺で、正面に唐破風造の大振りな向拝を張出し、背面に両下造の幣殿を付属する。拝殿は外周に格子や舞良戸をたて、内部一室で格天井を張る。幣殿は二段階に床を高め、奥に本殿に昇段する階を備える。風格ある構えの拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009843"},{"id":"00009842","register_sub_id":"101","register_pk":"195671","name":"宮處八幡宮本殿","kana":"みやどころはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30616812,"lng":134.1138672,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、檜皮葺及び銅板葺、建築面積31㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0393","desc":"高い石積基壇上に建ち、正面一間側面二間、入母屋造、正面向拝付、軒唐破風及び千鳥破風付、檜皮葺である。側背面に廻らした縁に五手先、正面の浜床に三手先の腰組を組み、軒は二軒で側背面を扇垂木とする。複雑な構成の細部を丁寧にまとめた見応えある近代社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009842"},{"id":"00009844","register_sub_id":"101","register_pk":"195673","name":"宮處八幡宮末社護国神社本殿","kana":"みやどころはちまんぐうまっしゃごこくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県高松市前田西町字岡崎512","lat":34.30606461,"lng":134.11363877,"geo_status":"db","era":"昭和11／昭和22移築","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"37 － 0395","desc":"拝殿手前の参道の西側に祀られる。一間社流造、銅板葺で、正面に千鳥破風を飾る。四手先の腰組で縁を受け、花樹を透彫した脇障子を隅行に振り、意匠を強調する。また妻飾の大瓶束には花頭枠状の笈形を付す。小規模ながら手の込んだ造作になる境内社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009844"},{"id":"00014532","register_sub_id":"101","register_pk":"513946","name":"妙法寺山門（勅使門）","kana":"みょうほうじさんもん（ちょくしもん）","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県丸亀市富屋町9","lat":34.2898,"lng":133.795225,"geo_status":"db","era":"明治18年","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"木造、瓦葺、間口3.1m、袖塀付","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"37 - 0485","desc":"丸亀城北側の城下町に所在する天台宗寺院の四脚門。本堂正面の伽藍東面に開く。切妻造本瓦葺で多種の役瓦で飾る。一軒繁垂木で柱梁とも木柄太く重厚。門扉は欅一枚板に襷桟と寺紋付。主柱頭貫彫刻の波兎は見所で、虹梁や木鼻含めて塩飽大工による仕事は優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014532"},{"id":"00010374","register_sub_id":"101","register_pk":"199146","name":"本山寺冠木門","kana":"もとやまじかぶきもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.13959756,"lng":133.69448894,"geo_status":"db","era":"明治43年","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"石造、間口4.4m、左右脇柱付","structure_material":"石造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0414","desc":"間口四・四メートルの石造冠木門で、両側に潜門を付属し、本堂東辺の入口を雄大に構成している。本柱は大面取の五平で、上細りの形状とし、冠木上部に帯を回して木瓜形を表し、頂部には唐破風造の屋根を載せるなど、丁寧に加工した花崗岩を精緻に組んでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010374"},{"id":"00010369","register_sub_id":"101","register_pk":"199141","name":"本山寺十王堂","kana":"もとやまじじゅうおうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139669,"lng":133.693576,"geo_status":"db","era":"宝暦9年（1759）／平成5年改修","year":1759,"year_source":"db","year_min":1759,"year_max":1759,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積148㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0409","desc":"本堂の南西に東面し大師堂と対する。桁行五間梁間三間、寄棟造、三間向拝付の本瓦葺で、前一間を外陣、後方を内陣とし、背面の廊下と護摩堂が増築である。面取角柱を貫と長押で固めた軸部、大斗絵様肘木の組物は簡素であるが、向拝は架構や細部が充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010369"},{"id":"00010372","register_sub_id":"101","register_pk":"199144","name":"本山寺鐘楼","kana":"もとやまじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139223,"lng":133.693905,"geo_status":"db","era":"江戸中期","year":1661,"year_source":"db","year_min":1661,"year_max":1661,"year_label":null,"structure":"木造、瓦葺、面積13㎡","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"37-0412","desc":"境内南東部に位置し、乱石積基壇に建つ方一間吹放し形式の鐘楼。軒支輪付の二軒繁垂木とし、南北棟で入母屋造の本瓦葺をあげる。内転びに立てた粽付面取角柱を貫と台輪で固め、実肘木拳鼻付の出組を詰組にするなど、境内に相応しい充実した形式である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010372"},{"id":"00010368","register_sub_id":"101","register_pk":"199140","name":"本山寺大師堂","kana":"もとやまじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139378,"lng":133.694095,"geo_status":"db","era":"寛政7年（1795）／明治16年改修","year":1795,"year_source":"db","year_min":1795,"year_max":1795,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0408","desc":"本堂南東に西面して建つ。方三間の入母屋造、一間向拝付で本瓦葺とする。前二間の外陣と後一間の内陣は格天井で、向拝と背面張出しが増築である。側まわりは面取角柱であるが、出組に中備平三斗、軒支輪付の本格的な形式で、境内復興整備の実像を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010368"},{"id":"00010370","register_sub_id":"101","register_pk":"199142","name":"本山寺大日堂","kana":"もとやまじだいにちどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139835,"lng":133.69398,"geo_status":"db","era":"江戸中期","year":1661,"year_source":"db","year_min":1661,"year_max":1661,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0410","desc":"本堂西脇の基壇に南面して建つ。方三間、宝形造本瓦葺で、内部は後一間に仏壇を構えた一室とし棹縁天井を張る。太い円柱や実肘木付三斗は風食などから室町期の材と判断されるが、長押や天井等が木細く、一八世紀中期に古材を利用して整備されたと考えられる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010370"},{"id":"00010373","register_sub_id":"101","register_pk":"199145","name":"本山寺大門","kana":"もとやまじだいもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字新田1760-1","lat":34.139244,"lng":133.694063,"geo_status":"db","era":"江戸後期／大正3年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積24㎡","structure_material":"木造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0413","desc":"大師堂南脇の八脚門。南北棟で入母屋造の本瓦葺、軒は二軒繁垂木とする。石製礎盤に円柱を立てて貫と虹梁、台輪で固め、組物は実肘木拳鼻付三斗、中備は正面各間と背面中央間が蟇股、ほかは撥束である。整った構造細部で、境内東面南方の構えをかたちづくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010373"},{"id":"00010371","register_sub_id":"101","register_pk":"199143","name":"本山寺宝蔵","kana":"もとやまじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県三豊市豊中町本山甲字屋敷内1359-31","lat":34.13974,"lng":133.694552,"geo_status":"db","era":"天保4年（1833）","year":1833,"year_source":"db","year_min":1833,"year_max":1833,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"37-0411","desc":"本堂北の本坊東南に西面して建つ。土蔵造二階建、腰を海鼠壁とし、宝形造本瓦葺とする。西面に庇付出入口を設け、内壁は竪板張、一階は根太天井、二階は棹縁天井を張る。内外とも丁寧な造作になるが、正方形の平面や二階南面に設けた二連花頭窓は独特である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010371"},{"id":"00002690","register_sub_id":"101","register_pk":"103680","name":"乃木神社手水舎","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"香川県","address":"香川県善通寺市文京町4-4-5","lat":34.22548386,"lng":133.78058118,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積8.3㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"37 － 0088","desc":"社務所の東南方，参道の鳥居をくぐりぬけた直ぐの左手に建つ。東西棟，銅板葺，切妻造，平入の手水舎で，四面吹放ちとする。柱は転びをつけず，２本宛の控柱を添えて貫，束，桁，梁などにより構成主義的な軸部を造作しているところに特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002690"},{"id":"00003143","register_sub_id":"101","register_pk":"104133","name":"金両藤井家住宅正門（旧八幡寺山門）","kana":null,"category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"香川県","address":"香川県小豆郡小豆島町苗羽字内浜甲842-1","lat":34.47645842,"lng":134.31826872,"geo_status":"db","era":"江戸後期／大正7頃移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"37 － 0136","desc":"主屋玄関の東南方に位置し，土蔵の西南隅部につながる。間口９ｍ規模で，玄関に通じる大門，勘定場に対応する脇門，大門の西方の木戸門から構成される。大門は本瓦葺の１間１戸の薬医門で，廃寺となった八幡寺の山門を移築したものと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003143"},{"id":"00002696","register_sub_id":"101","register_pk":"103686","name":"石土神社の高灯籠（式年祭記念燈）","kana":"いしづちじんしゃのたかとうろう（しきねんさいきねんとう）","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"愛媛県","address":"愛媛県西条市小松町妙口甲727-2","lat":33.87892359,"lng":133.07905476,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造、高さ9.5m","structure_material":"鉄筋コンクリート造","registered":"2002.02.14(平成14.02.14)","register_no":"38 － 0023","desc":"町北西部の山際にある，式年祭を記念して造られた灯籠。末広がりの約９．５ｍ高，下部直径約１．５ｍのＲＣ造構造物で，頂部にコンクリートでかたどった宝珠・笠・四面開放の火袋等を頂く。巡礼登山道の途中にあり，地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002696"},{"id":"00013764","register_sub_id":"101","register_pk":"505325","name":"西条栄光教会牧師館","kana":"さいじょうえいこうきょうかいぼくしかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県西条市明屋敷字旧陣屋内236-3","lat":33.92094444,"lng":133.17948333,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階建、瓦葺、建築面積79㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 152","desc":"礼拝堂の南に渡廊下で接続する。二階建切妻造桟瓦葺。下部を杉板張、上部を真壁造とする。玄関周囲に食堂や居間などを配し、玄関は吹抜の階段室を兼ね、二階は集会室、寝室などである。内外とも漆喰に木部を現し格子や障子を用いるなど和風意匠で統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013764"},{"id":"00013763","register_sub_id":"101","register_pk":"505323","name":"西条栄光教会礼拝堂","kana":"さいじょうえいこうきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"愛媛県","address":"愛媛県西条市明屋敷字旧陣屋内236-3","lat":33.92114722,"lng":133.17943889,"geo_status":"db","era":"昭和26年","year":1951,"year_source":"db","year_min":1951,"year_max":1951,"year_label":null,"structure":"木造2階一部平屋建、瓦葺一部鉄板葺、建築面積197㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"38 － 151","desc":"西条藩の陣屋跡に位置。桁行二〇メートル梁間九メートル、切妻造桟瓦葺で両脇に下屋を設ける。南面中央に鐘塔を掲げ、妻の一部をやや前方に張出して十字架を付す。内部は一室の礼拝堂で奥に祭壇を設ける。白色の壁と縦長窓の連続が印象的なモダンな礼拝堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013763"},{"id":"00007598","register_sub_id":"101","register_pk":"108580","name":"浄光寺地蔵堂","kana":"じょうこうじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県越智郡上島町岩城855","lat":34.24715893,"lng":133.15039108,"geo_status":"db","era":"天保2","year":1831,"year_source":"db","year_min":1831,"year_max":1831,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"38 － 0088","desc":"本堂の東に南面して建つ小規模な仏堂。入母屋造本瓦葺。面取方柱が、直接に桁を受ける。一軒疎垂木。正面中央と側面前間に建具をたて、他を漆喰壁とし、正面から側面前寄りに切目縁をまわす。内部は広い１室。軒が全体にわたって反り、軽快な外観とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007598"},{"id":"00007597","register_sub_id":"101","register_pk":"108579","name":"浄光寺本堂","kana":"じょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県越智郡上島町岩城855","lat":34.247128,"lng":133.150269,"geo_status":"db","era":"宝暦2／文政8改修","year":1752,"year_source":"db","year_min":1752,"year_max":1752,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積95㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"38 － 0087","desc":"南面して建つ三間堂。宝形造本瓦葺で、正面に一間向拝、背面に下屋を付ける。面取方柱で、木鼻付大斗絵様肘木とし、中備に蓑束を飾る。一軒繁垂木。内部は前寄り二間通りを外陣、その奥を内陣とし、中央後寄りに須弥壇を置く。小規模な浄土宗本堂の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007597"},{"id":"00005205","register_sub_id":"101","register_pk":"106195","name":"福田寺山門","kana":"ふくでんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市上吾川878","lat":33.74559314,"lng":132.7156639,"geo_status":"db","era":"文政5","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0069","desc":"切妻造，本瓦葺の四脚門で，本堂南に東面して建つ。総欅の素木造で，軸部は親柱が円柱，控柱が角柱，組物は実肘木付三斗，中備が蟇股，妻飾は虹梁大瓶束で，軒は二軒繁垂木である。虹梁や木鼻の渦文，笈形の波濤文，持送り彫物など，装飾細部も充実している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005205"},{"id":"00005204","register_sub_id":"101","register_pk":"106194","name":"福田寺通玄庵","kana":"ふくでんじつうげんあん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市上吾川878","lat":33.74571052,"lng":132.71556331,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、茅葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0068","desc":"本堂南西に南面して建つ。寄棟造，茅葺の四周に瓦葺の下屋を廻した，いわゆる四方蓋造の外観を呈する。南東隅に玄関，その北にダイドコ，西側に田の字形で４室を配し，北西の仏間の天井に龍を描く。隠居した僧侶の住居である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005204"},{"id":"00005203","register_sub_id":"101","register_pk":"106193","name":"福田寺本堂","kana":"ふくでんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県伊予市上吾川878","lat":33.74592838,"lng":132.7157949,"geo_status":"db","era":"天明元","year":1781,"year_source":"db","year_min":1781,"year_max":1781,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積124㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"38 － 0067","desc":"南北に細長い境内に南面して建つ。入母屋造，本瓦葺で，妻飾は狐格子とする。基本的には６間取平面になり，正面に広縁を設ける。組物や彫物を用いないが，内陣仏壇の構えや，室中と両脇間の境に設けた竹の節欄間など，方丈形式のつくりになっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005203"},{"id":"00003156","register_sub_id":"101","register_pk":"104146","name":"ふるさと旅行村極楽堂","kana":"ふるさとりょこうむらごくらくどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県上浮穴郡久万高原町下畑野川乙488","lat":33.67318641,"lng":132.93736021,"geo_status":"db","era":"明治31／昭和52移築","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積36㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"38 － 0033","desc":"三間四方の平面に宝形造の屋根を載せる堂宇で，四方に濡縁を巡らす。正面は２間幅の扉口を開き，他は横板壁とする。内部は格天井に郷土の植物画を描く。地元組中の集会所的施設でもあり、当初四国遍路の道筋にあったことから仮眠の宿としても利用された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003156"},{"id":"00015516","register_sub_id":"101","register_pk":"533531","name":"明専寺石垣","kana":"みょうせんじいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"愛媛県","address":"愛媛県今治市大西町脇甲1277","lat":34.05773333,"lng":132.91892778,"geo_status":"db","era":"天保9年（1838）／安政4年（1857）増築","year":1838,"year_source":"db","year_min":1838,"year_max":1838,"year_label":null,"structure":"石造、総延長83m","structure_material":"石造","registered":"2025.08.06(令和7.08.06)","register_no":"38 - 0200","desc":"境内東面の市道に沿った石垣。総延長八三メートル、最大高さ約二・五メートル、中央石段を挟み北側は弓杖島の花崗岩、南側は寺周囲から集めた様々な石を用い、いずれも村中寄進で築造した。大小の石を精緻に積んだ長大な石垣で、地域の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015516"},{"id":"00015515","register_sub_id":"101","register_pk":"533530","name":"明専寺鐘楼門","kana":"みょうせんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県今治市大西町脇甲1277","lat":34.0579,"lng":132.91891389,"geo_status":"db","era":"天保11年（1840）","year":1840,"year_source":"db","year_min":1840,"year_max":1840,"year_label":null,"structure":"木造2階建、瓦葺、建築面積8.3㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"38 - 0199","desc":"市街西方の丘陵地に位置する浄土真宗寺院の鐘楼門。一間一戸二重門で入母屋造本瓦葺。下層は桁先を延ばして軒桁を支持。上層組物は出組、軒は二軒繁垂木。側廻りは連子窓で正背面中央間を開放とし内部に梵鐘を吊る。彫刻は幕末の時代相応で境内入口を飾る門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015515"},{"id":"00006327","register_sub_id":"101","register_pk":"107310","name":"明石寺石垣及び塀","kana":"めいせきじいしがきおよびへい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36909985,"lng":132.51928004,"geo_status":"db","era":"昭和5・昭和19","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石垣 石造、総延長73m、石段付 塀 石造、総延長63m","structure_material":"石垣 石造","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0083","desc":"本堂のある最上段の敷地を形成する。石垣は高さ３．８ｍ、石段付。積み方は打込矧ぎの乱積で、出隅部は算木積で反りを付ける。石垣上の塀は鉄筋コンクリート造で擬宝珠高欄状に造り、柱間の花頭窓風に透かした意匠が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006327"},{"id":"00006328","register_sub_id":"101","register_pk":"107311","name":"明石寺石段及び石垣","kana":"めいせきじいしだんおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"大正","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.3685981,"lng":132.5194425,"geo_status":"db","era":"大正5・大正期／昭和初期増設","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"石段 石造43段、幅3.7m、石垣 石造、総延長65m","structure_material":"石段 石造43段","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0084","desc":"石段は幅３．６ｍ、踊場を設けた４３段から成り、仁王門の前に至る。御影石の切石を用い、階段曲線部は３石を継ぎ、直線部は１石で１段とする。石垣は境内中段の平地を造成。野面石を用いた乱積で、西側の一部は矢羽積。傾斜地を利用した境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006328"},{"id":"00006326","register_sub_id":"101","register_pk":"107309","name":"明石寺客殿","kana":"めいせきじきゃくでん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.368847,"lng":132.519409,"geo_status":"db","era":"大正期／昭和42頃改造","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積157㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0080","desc":"仁王門の南東、北面して建つ。桁行８間、梁間５間、入母屋造、桟瓦葺で、正面西端に唐破風造の式台を付ける。内部は大床付の４８畳や式台の間、事務所ほかを設け、南側東端に茶室に付設。質実な意匠で、落ち着いた外観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006326"},{"id":"00006323","register_sub_id":"101","register_pk":"107306","name":"明石寺地蔵堂","kana":"めいせきじじぞうどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36904578,"lng":132.51929978,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積16㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0078","desc":"境内中段の平地に位置し、南面して建つ。桁行３間、梁間３間、入母屋造、桟瓦葺で正面に向拝を設ける。組物は二手先、軒は二軒繁垂木、妻飾は虹梁大瓶束とする。龍や兎、鶴などの彫刻が向拝や身舎の細部にわたり施され、彫物師の意気込みが伝わる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006323"},{"id":"00006322","register_sub_id":"101","register_pk":"107305","name":"明石寺鐘楼堂","kana":"めいせきじしょうろうどう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36917067,"lng":132.51918722,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積9.2㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0081","desc":"本堂の南東に位置し、基壇上に建つ。桁行１間、梁間１間、四方吹放ち鐘楼で、入母屋造、桟瓦葺とする。円柱は内転びに建て、三斗組で、中備にも平三斗を置き、二軒繁垂木とする。装飾を抑えた意匠とするが、軒の出が深く、入母屋屋根の反りが美しい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006322"},{"id":"00006321","register_sub_id":"101","register_pk":"107304","name":"明石寺大師堂","kana":"めいせきじだいしどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36931322,"lng":132.51915722,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0077","desc":"本堂の東に並んで南面して建つ。方３間宝形造、桟瓦葺。組物は出三斗、軒は二軒繁垂木。向拝の獅子彫刻とした木鼻や、身舎の雲形に彫り込まれた支輪板など装飾的である。また向拝部分の飛檐垂木をＳ字状の反転曲線とし、向拝軒勾配を調整する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006321"},{"id":"00006325","register_sub_id":"101","register_pk":"107308","name":"明石寺手水舎","kana":"めいせきじちょうずや","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36880111,"lng":132.51910011,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造、瓦葺、面積5.5㎡","structure_material":"木造","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0082","desc":"仁王門の南西に位置する。切妻造、銅板葺。方柱４本を内転びに建て、中央に手水鉢を置き、四方吹放ちとする。三斗組で、軒は二軒繁垂木とし、妻飾は虹梁大瓶束で笈形を付ける。小規模ながら、建築的細部を丁寧に仕上げた佳品である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006325"},{"id":"00006324","register_sub_id":"101","register_pk":"107307","name":"明石寺仁王門","kana":"めいせきじにおうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36888844,"lng":132.51907667,"geo_status":"db","era":"明治34頃","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積37㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0079","desc":"本堂の前方、境内中段の平地に位置し、南面して建つ。３間１戸八脚門で、入母屋造、桟瓦葺とする。出組で二軒繁垂木。正面は頭貫を全て虹梁形とし、欄間や支輪板に雲紋を彫り込み、大棟は両端に鯱を配し、側板は波や龍に型取るなど、意匠、技術ともに優秀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006324"},{"id":"00006320","register_sub_id":"101","register_pk":"107303","name":"明石寺本堂","kana":"めいせきじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"愛媛県","address":"愛媛県西予市宇和町明石205他","lat":33.36922656,"lng":132.51898711,"geo_status":"db","era":"明治23頃","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積104㎡","structure_material":"木造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"38 － 0076","desc":"山の斜面に位置する境内最上段に、南面して建つ。桁行５間、梁間５間、入母屋造、桟瓦葺、向拝付。四方に切目縁を廻し、組物は平三斗、軒は二軒繁垂木。唐破風屋根を大屋根の下で突き出す重厚な外観と、向拝の随所に施された彫刻が目を引く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006320"},{"id":"00011585","register_sub_id":"101","register_pk":"210514","name":"大川上美良布神社神庫","kana":"おおかわかみびらふじんじゃしんこ","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県香美市香北町韮生野大宮243-1","lat":33.65006389,"lng":133.78387389,"geo_status":"db","era":"天保12年（1841）／昭和61年改修","year":1841,"year_source":"db","year_min":1841,"year_max":1841,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積19㎡","structure_material":"土蔵造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"39-0293","desc":"桁行三間梁間二間、庇付の二階建土蔵。切妻造平入、置屋根形式。二段に水切瓦を廻し、腰壁は四面で異なる土佐漆喰の鏝仕上げとする。随所に彫刻を嵌め込んで飾り、北妻の雲形の窓上部は天邪鬼が唐破風状の庇を支え、鬼と雲の鏝絵で飾り特徴ある外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011585"},{"id":"00004063","register_sub_id":"101","register_pk":"105053","name":"桑瀬神社本殿","kana":"くわぜじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県吾川郡いの町桑瀬","lat":33.78396614,"lng":133.30784897,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、板葺、建築面積6.2㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0131","desc":"礫滝横の峻険な山肌を切り開いた６坪程の社地に建つ。ほぼ南面する鞘殿に収まる切妻造，板葺，平入の一間社で，背面と正面の前後に錣屋根を架け，正面左右柱上部や蟇股などに龍，獏，鳳凰などの彩色彫刻を施す。古くから地区住民により守られてきた神社。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004063"},{"id":"00003170","register_sub_id":"101","register_pk":"104160","name":"正覚寺石垣","kana":"しょうがくじいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1718-1","lat":33.42408626,"lng":134.02196069,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造、延長31m","structure_material":"石造","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0074","desc":"境内地の南辺に位置し，中央東寄りに門を開く。「イシグロ」と呼ばれる台風時等海からの強風避けの石垣で，２０～３０ｃｍ程の比較的大きな玉石で高さ１．５ｍ厚１ｍの外塀を築造し，類例の少ない昭和初期寺院境内景観をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003170"},{"id":"00003169","register_sub_id":"101","register_pk":"104159","name":"正覚寺本堂","kana":"しょうがくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"昭和前","pref":"高知県","address":"高知県安芸郡奈半利町乙1718-1","lat":33.42422979,"lng":134.02215441,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2003.01.31(平成15.01.31)","register_no":"39 － 0073","desc":"国道から南に入った境内地の西辺近くに東面して建つ。桁行４間梁間４間規模，向拝付きの宝形造本堂で右瓦が使用されている。奥に新本堂が増築された以降も外陣的な役割を果たしており，四国三十三観音霊場第九番札所として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003169"},{"id":"00006342","register_sub_id":"101","register_pk":"107325","name":"乗光寺書院","kana":"じょうこうじしょいん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1877-3","lat":33.43903328,"lng":133.98210717,"geo_status":"db","era":"大正末期／昭和中期改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造平屋建、瓦葺、建築面積41㎡","structure_material":"木造平屋建","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0231","desc":"敷地の中央に南北棟で建つ木造平屋建である。屋根は寄棟造桟瓦葺で、軒先を金属板葺とする。内部はトコと棚を構える数寄屋風の６畳座敷と次の間４畳からなり、東西に榑縁をつける。小規模ながら落ち着いた佇まいの建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006342"},{"id":"00006343","register_sub_id":"101","register_pk":"107326","name":"乗光寺門","kana":"じょうこうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県安芸郡安田町大字安田1877-3","lat":33.43910301,"lng":133.98204095,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"鉄筋コンクリート造、間口3.0m、脇門付","structure_material":"鉄筋コンクリート造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0232","desc":"敷地の西辺、北寄りに開く門で南に脇門がつく。主門は間口３．０ｍ、高さ３．０ｍのコンクリート造の方柱で、柱頭下部に歯飾りを施す。上部に鉄製の欠円アーチを渡して門灯を掲げる。脇門門柱は幅０．９ｍで主門と同じ意匠になる。近代における寺院表門の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006343"},{"id":"00009678","register_sub_id":"101","register_pk":"194674","name":"定福寺庫裏","kana":"じょうふくじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県長岡郡大豊町粟生字寺ノナル158-3","lat":33.79274912,"lng":133.76955788,"geo_status":"db","era":"江戸末期／明治18移築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積241㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0276","desc":"本堂より一段低い位置に南面し、入母屋造銅板葺で背面に持仏堂を張出す。主体部は前後二列に一〇室を並べ、西寄りに入母屋造の玄関、西端列にトコを備えた表間を配し、南西面に縁を廻らせる。東側の旧土間に大黒柱を残すなど、当地の大型民家の名残を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009678"},{"id":"00009677","register_sub_id":"101","register_pk":"194673","name":"定福寺本堂","kana":"じょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県長岡郡大豊町粟生字粟生山159-3","lat":33.79304655,"lng":133.7692081,"geo_status":"db","era":"安永8","year":1779,"year_source":"db","year_min":1779,"year_max":1779,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"39 － 0275","desc":"山中に所在する境内の奥に南面する。桁行五間梁間五間、入母屋造銅板葺、正面向拝付。中央の方三間を格天井張の内陣とし、正面一間通を外陣、両側に脇陣、背面を後陣とする。各面の一部に桟唐戸を吊る他は横板張とし、閉鎖的な構えになる真言宗寺院本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009677"},{"id":"00004066","register_sub_id":"101","register_pk":"105056","name":"善法寺本堂","kana":"ぜんぽうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県吾川郡仁淀川町土居甲1023","lat":33.60947583,"lng":133.17431586,"geo_status":"db","era":"明治初期／明治32頃改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"木造平屋建、瓦葺、建築面積122㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"39 － 0134","desc":"土居川と安居川の合流地近くの河岸上に位置する。池川郷庄屋宅の客殿を本堂に充てたと伝える。桁行５間梁間５間規模，入母屋造，桟瓦葺で，屋根の各面には左瓦を使用する。大きな入母屋の妻は対岸から見ることができ，地区の格好のランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004066"},{"id":"00003736","register_sub_id":"101","register_pk":"104726","name":"長法寺本堂","kana":"ちょうほうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町1894","lat":33.42868306,"lng":134.01001914,"geo_status":"db","era":"文政5","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積149㎡","structure_material":"木造平屋建","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0093","desc":"桁行５間半梁行６間規模を有し，正面に１間の向拝を延ばす。屋根は入母屋造，桟瓦葺，軒は一軒疎垂木，組物平三斗，中備蟇股で，正面１間通りと両側面半間分を入側とし，桁行４間半梁行２間半分を外陣に充てる。安芸地方における江戸後期真宗寺院本堂の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003736"},{"id":"00003737","register_sub_id":"101","register_pk":"104727","name":"長法寺門","kana":"ちょうほうじもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸郡田野町1894","lat":33.42843903,"lng":134.01010504,"geo_status":"db","era":"慶応2","year":1866,"year_source":"db","year_min":1866,"year_max":1866,"year_label":null,"structure":"木造、瓦葺、間口2.8m、袖塀付","structure_material":"木造","registered":"2003.12.01(平成15.12.01)","register_no":"39 － 0094","desc":"本堂の南方に東西棟で建つ。切妻造，桟瓦葺，間口１間半規模の１間薬医門で，本柱に五平材を用い，棟を蟇股で受けている点に特徴がある。間口の割にややたちが高く感じられるが，両袖に１間長の瓦葺板塀を従えて安定感ある姿形をつくりだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003737"},{"id":"00004189","register_sub_id":"101","register_pk":"105179","name":"仁井田神社鞘殿","kana":"にいだじんじゃさやでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"大正","pref":"高知県","address":"高知県高知市土佐山桑尾字大潰78番イ","lat":33.63657099,"lng":133.52047508,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0154","desc":"拝殿奥にある本殿を保護する施設。桁行４．５ｍ，梁間５．６ｍ，切妻造，平入で，銅板葺の屋根はもと茅葺である。側廻りは角柱を立て，柱間は貫と角材を格子状に組んで厳重に囲う。質素なつくりであるが，拝殿と釣り合った規模を有し，社頭景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004189"},{"id":"00004188","register_sub_id":"101","register_pk":"105178","name":"仁井田神社拝殿","kana":"にいだじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高知市土佐山桑尾字大潰78番イ","lat":33.63654824,"lng":133.52049545,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積57㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0153","desc":"桁行９．８ｍ，梁間５．８ｍ，入母屋造，妻入で，桟瓦葺屋根は左瓦を用いる。側廻りに角柱を立てて桁を受け，柱間に中敷居を入れて格子を建て込み，軒の出桁は渦紋付の持送板で受ける。簡素な形式であるが，社頭景観の構成上，欠かせない存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004188"},{"id":"00004187","register_sub_id":"101","register_pk":"105177","name":"仁井田神社本殿","kana":"にいだじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高知市土佐山桑尾字大潰78番イ","lat":33.63657665,"lng":133.52046918,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、板葺、建築面積3.6㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0152","desc":"覆屋内にある桁行１．４ｍの１間社流造で，正側面に高欄付の切目縁を廻し，正面には浜縁をつける。身舎は円柱上に台輪を廻し，拳鼻付の出組を詰組にする。庇の龍，脇障子の松だけでなく中備に花鳥や山など，多彩な彫物を要所に配して，華やかな構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004187"},{"id":"00004186","register_sub_id":"101","register_pk":"105176","name":"春宮神社拝殿","kana":"はるみやじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"高知県","address":"高知県高知市土佐山桑尾字横平629番イ","lat":33.63742148,"lng":133.50860572,"geo_status":"db","era":"明治11","year":1878,"year_source":"db","year_min":1878,"year_max":1878,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0151","desc":"入母屋造，桟瓦葺，妻入，正面１間向拝付で，長方形平面は後半中央に本殿を安置し，前半を拝殿とする。軸部は角柱を立て，前半のみ大斗・舟肘木で丸桁をうける。小壁に配した龍や，波涛に兎・平目・鯉など躍動感のある彫物が，当時の造形の傾向を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004186"},{"id":"00004185","register_sub_id":"101","register_pk":"105175","name":"春宮神社本殿","kana":"はるみやじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"高知県","address":"高知県高知市土佐山桑尾字横平629番イ","lat":33.63743942,"lng":133.5085551,"geo_status":"db","era":"文政7","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"木造平屋建、板葺、建築面積3.9㎡","structure_material":"木造平屋建","registered":"2004.06.09(平成16.06.09)","register_no":"39 － 0150","desc":"江戸前期の創建と伝える神社。覆屋を兼ねた拝殿奥にある１間社春日造で，建築年代は銘札より判明する。身舎は木製土台上に円柱を立てて三斗を組み，屋根はこけら葺，軒は吹寄垂木とする。彩色がほとんどない素木造で，装飾も庇の象鼻や蟇股程度と簡明な意匠。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004185"},{"id":"00006725","register_sub_id":"101","register_pk":"107708","name":"安田八幡宮玉垣","kana":"やすだはちまんぐうたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"高知県","address":"高知県安芸郡安田町大字安田2170","lat":33.43812681,"lng":133.98061727,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"石造、延長19m","structure_material":"石造","registered":"2007.12.05(平成19.12.05)","register_no":"39 － 0235","desc":"神社参道の両脇に設けられた石造玉垣。間口４．６ｍ、長さ１６ｍ、高さ０．６ｍで、親柱を９間に立て、各間小柱５本で笠石を受ける。上手の石段部分は長さ３．０ｍで、両端に親柱、中間に中柱を置き、小石柱５本で笠石を受ける。参道景観を整える施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006725"},{"id":"00016455","register_sub_id":"101","register_pk":"536522","name":"宇美八幡宮神門","kana":"うみはちまんぐうしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県糟屋郡宇美町宇美一丁目4104-1","lat":33.57023333,"lng":130.50861667,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"木造、銅板葺、間口7.9m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0258","desc":"東西に延びる参道中央部に位置する八脚門。基壇上に西面して建つ切妻造銅板葺で、円柱の主柱で棟木を支え、角柱の控柱と飛貫、頭貫で固める。柱間は全て吹放ち、上部は化粧軒裏を現す。軒反り優美で、参道を見通す開放的なつくりが境内の軸線を強調する神門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016455"},{"id":"00016454","register_sub_id":"101","register_pk":"536521","name":"宇美八幡宮拝殿及び幣殿","kana":"うみはちまんぐうはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糟屋郡宇美町宇美一丁目4104","lat":33.57035833,"lng":130.50881667,"geo_status":"db","era":"明治19年／明治32年・昭和33年増築","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積100㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0257","desc":"本殿の前面に位置する拝殿及び弊殿。拝殿は西面して建つ切妻造妻入銅板葺で、正面に増築の軒唐破風付きの入母屋造向拝を設け、周囲に庇を廻らす。後方に両下造銅板葺の幣殿を接続する。増築による変化ある屋根構成が優美で、境内中核部の景観を形成する社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016454"},{"id":"00016453","register_sub_id":"101","register_pk":"536520","name":"宇美八幡宮本殿","kana":"うみはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県糟屋郡宇美町宇美一丁目4104","lat":33.57043611,"lng":130.50898056,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造平屋建、檜皮葺、建築面積62㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0256","desc":"市街地の中心部に位置する神社の本殿。境内東側に西面して建つ桁行五間梁間三間、入母屋造檜皮葺で一間向拝を付し、周囲に刎高欄付縁を廻らし脇障子を建てる。組物は出組、軒は二軒繁垂木。向拝の獅子鼻、籠彫の手挟など精緻な彫刻で飾った華麗な大規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016453"},{"id":"00014978","register_sub_id":"101","register_pk":"519238","name":"観世音寺宝蔵","kana":"かんぜおんじほうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県太宰府市観世音寺五丁目51-3","lat":33.51493611,"lng":130.52227222,"geo_status":"db","era":"昭和34年／昭和36年・平成21年改修","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、瓦葺、建築面積340㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"40 - 0224","desc":"大宰府政庁跡に近い観世音寺境内に建つ文化財収蔵展示施設。防湿・防熱効果を高めるためピロティと二重壁を採用した鉄筋コンクリート造建築。梁にハンチを付けず、二軒風の深い軒を舟肘木で支え、腰壁は精緻な瓦積で仕上げる。端正かつ優美な戦後の和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014978"},{"id":"00013466","register_sub_id":"101","register_pk":"368562","name":"教圓寺鐘楼","kana":"きょうえんじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県豊前市大字宇島215","lat":33.62244444,"lng":131.14098611,"geo_status":"db","era":"文久3年(1863)／昭和55年改修","year":1863,"year_source":"db","year_min":1863,"year_max":1863,"year_label":null,"structure":"木造3階建、瓦葺、建築面積41㎡","structure_material":"木造3階建","registered":"2020.08.17(令和2.08.17)","register_no":"40 － 0173","desc":"周防灘に面する宇島に位置し、旧中津街道沿いの境内南西隅に建つ。正面三間、側面二間、三階建袴腰付、宝形造桟瓦葺。二層の組物は出組で二軒繁垂木、四周に連子窓あるいは火頭窓を入れ、縁を出三斗で支え、内部に梵鐘を吊る。類稀な三層の鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013466"},{"id":"00015105","register_sub_id":"101","register_pk":"529383","name":"興国寺山門及び袖塀","kana":"こうこくじさんもんおよびそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県田川郡福智町上野1892","lat":33.72020833,"lng":130.78722222,"geo_status":"db","era":"大正13年","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"山門 木造、銅板葺、間口3.3m 袖塀 木造、銅板葺、総延長7.5m、潜戸付","structure_material":"山門 木造","registered":"2024.08.15(令和6.08.15)","register_no":"40 - 0227","desc":"境内入口に南面して建つ一間一戸入母屋造銅板葺の二重門。両脇に銅板葺袖塀を付す。下層主柱は円柱、控柱は角柱、組物は三斗の詰組で、内部は格天井張。上層は円柱に大斗肘木を組む。軒はいずれも緩やかに反らせた二軒扇垂木とし、精緻で斬新なつくりの山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015105"},{"id":"00015104","register_sub_id":"101","register_pk":"529382","name":"興国寺本堂","kana":"こうこくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県田川郡福智町上野1892","lat":33.72051944,"lng":130.78728611,"geo_status":"db","era":"大正8年／令和4年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積297㎡","structure_material":"木造平屋建","registered":"2024.08.15(令和6.08.15)","register_no":"40 - 0226","desc":"福智山南西麓に位置する曹洞宗寺院の本堂。境内北側に南面して建つ入母屋造平入桟瓦葺。入側一間の広縁を取込んだ六間取の方丈形式で、正面に三間向拝を付す。内部中央の大間は折上格天井張。正面中央には二重に虹梁形差物を渡し、力士彫刻の束で飾った本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015104"},{"id":"00013201","register_sub_id":"101","register_pk":"368425","name":"小烏神社神饌所","kana":"こがらすじんじゃしんせんしょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57984444,"lng":130.39153889,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0168","desc":"拝殿脇に渡廊下を介して接続する。桁行三間、梁間二間、切妻造桟瓦葺、内部は入口回りを土間、その他を板敷の一室とする。西角に物入を作り、南西面に板戸の出入口を設ける。妻は二重虹梁で、虹梁端部に鯖の尾を付す等、小規模ながら凝ったつくりとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013201"},{"id":"00013203","register_sub_id":"101","register_pk":"368427","name":"小烏神社手水舎","kana":"こがらすじんじゃてみずしゃ","category":"宗教","subcategory":"建築物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57969722,"lng":130.39175278,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、銅板葺、面積6.7㎡","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0170","desc":"拝殿に通じる参道脇に位置する。桁行一間、梁間一間、切妻造銅板葺、角柱四本を内転びに立て、中央に昭和四年銘の手水鉢を置き、四方を吹放しとする。柱上に舟肘木を置き桁と虹梁を受け、虹梁上に板蟇股をおいて棟木を受ける。本殿などと意匠を統一する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013203"},{"id":"00013202","register_sub_id":"101","register_pk":"368426","name":"小烏神社天満宮","kana":"こがらすじんじゃてんまんぐう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57979722,"lng":130.39128611,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積3.4㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0169","desc":"本殿の西、境内の隅に位置する。一間社流造、銅板葺、浜床を付ける。柱は円柱で、三斗組とし、軒は二軒繁垂木。妻を虹梁大瓶束とする。向拝と身舎は海老虹梁で繋ぎ、三方に切目縁を設け、身舎両袖を脇障子で仕切る。檜の良材を用いた造作の丁寧な小社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013202"},{"id":"00013200","register_sub_id":"101","register_pk":"368424","name":"小烏神社拝殿及び渡殿","kana":"こがらすじんじゃはいでんおよびわたりでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57979167,"lng":130.39151389,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0167","desc":"本殿正面に接続し、南面して建つ。拝殿は入母屋造銅板葺平入、渡殿は銅板葺とする。拝殿は身舎・向拝ともに二軒、軸部を吹放ち開放として、四周に縁を廻す。床は板張り、天井は格天井とし、向拝蟇股を藤の彫刻で飾る。簡素な中にも質の高い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013200"},{"id":"00013205","register_sub_id":"101","register_pk":"368429","name":"小烏神社奉献塔","kana":"こがらすじんじゃほうけんとう","category":"宗教","subcategory":"その他工作物","type_guess":"塔","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57976667,"lng":130.39130278,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"石造、高さ6.0m","structure_material":"石造","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0172","desc":"拝殿脇に立つ高さ６メートルの石塔。二段積の台座の上に立ち、塔上は笠木付の柱頭を飾り、頂部に銅製の八咫烏を載せる。正面となる南に「奉献」の浮彫り、背面に昭和四年の銘と寄進者の名を刻み、境内景観に寄与する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013205"},{"id":"00013199","register_sub_id":"101","register_pk":"368423","name":"小烏神社本殿","kana":"こがらすじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57983056,"lng":130.39141389,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積20㎡","structure_material":"木造平屋建","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0166","desc":"天神近郊住宅地の丘陵にある神社。本殿は境内後方の高台に建つ。三間社流造銅板葺で、四方に高欄付切目縁を廻し、向拝廻りに浜床を広くとる。妻飾は虹梁に豕扠首、組物は身舎四隅及び向拝を出三斗とする。全体に装飾を抑えた、端正な意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013199"},{"id":"00013204","register_sub_id":"101","register_pk":"368428","name":"小烏神社瑞垣","kana":"こがらすじんじゃみずがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区警固三丁目194","lat":33.57984444,"lng":130.39138056,"geo_status":"db","era":"昭和4年","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造、金属板葺、延長33m","structure_material":"木造","registered":"2019.12.05(令和1.12.05)","register_no":"40 － 0171","desc":"渡殿に接続し、本殿を中心に一辺三〇尺の透塀で囲む。角柱を地、腰、内法の各長押で固め、腕木で出桁を受け、疎垂木、鉄板葺とする。腰長押、内法長押間に連子窓を嵌める。簡素ながら装飾をもち、本殿の配置に沿った計画的な平面構成をとる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013204"},{"id":"00014430","register_sub_id":"101","register_pk":"511419","name":"篠山神社透塀","kana":"ささやまじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.32893611,"lng":130.50783889,"geo_status":"db","era":"明治12年／昭和5年頃改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、銅板葺及び瓦葺、延長88m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0203","desc":"中門左右に延びて本殿を取り囲む透塀。東西一三間、南北一七間規模で、石積は江戸切仕上げ切石乱積みで築き、腰長押下は襷桟打、内法長押の間に竪格子を嵌め込み、出桁造、疎垂木とする塀を立ち上げる。本殿まわりの神域を画し、森厳な社殿空間を作り出す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014430"},{"id":"00014429","register_sub_id":"101","register_pk":"511418","name":"篠山神社中門","kana":"ささやまじんじゃちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.328775,"lng":130.5079,"geo_status":"db","era":"明治12年／昭和5年頃改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造、銅板葺、間口2.7m","structure_material":"木造","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0202","desc":"本殿と拝殿のほぼ中間に位置する。一間平唐門、銅板葺、高さ約一メートルの石垣上に建つ。冠木上の蟇股に有馬家家紋の左三つ巴、控柱の虹梁形頭貫上に雲文をあしらい、懸魚の六葉は同家家紋の竜胆車でかたどる。丁寧なつくりで、建物の由緒を装飾に織り込む。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014429"},{"id":"00014428","register_sub_id":"101","register_pk":"511417","name":"篠山神社拝殿","kana":"ささやまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.32862778,"lng":130.50783611,"geo_status":"db","era":"明治12年／昭和5年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積87㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0201","desc":"本殿から約四〇メートル南に位置する。桁行五間、梁間三間、入母屋造平入、銅板葺で、基壇は切石二段で築く。正面に三間幅の広い向拝を付け、内部は折上げ格天井とし、四周に刎高欄付切目縁をまわす。正面桟唐戸、背面引分戸の他は蔀を吊る開放的な大型拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014428"},{"id":"00014427","register_sub_id":"101","register_pk":"511416","name":"篠山神社本殿","kana":"ささやまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県久留米市篠山町字六丁目444","lat":33.32893333,"lng":130.50792778,"geo_status":"db","era":"明治12年／昭和5年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積43㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0200","desc":"筑後川に面する久留米城址の本丸跡に南面して建つ。三間社、入母屋造妻入、三間向拝付、銅板葺で、有馬家藩主五柱を祀る。中備蟇股で、出組、二軒繁垂木が深い軒を持ち出す。大屋根に向拝を取り込み、特異ながらも端正かつ堂々たる構えの近代大型社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014427"},{"id":"00014549","register_sub_id":"101","register_pk":"513963","name":"浄福寺山門","kana":"じょうふくじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県大川市大字小保字上町市場40-1","lat":33.20472222,"lng":130.3725,"geo_status":"db","era":"明治5年頃","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"木造、瓦葺、間口2.8m","structure_material":"木造","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0213","desc":"木工で知られる歴史的町並みの通りに開く浄土真宗寺院の山門。切妻造桟瓦葺の薬医門で、軒は半繁垂木で天井を張る。八双金具等で飾った板扉を建て、西脇間に潜り戸、両側面の男梁先に支柱を入れて袖壁を設ける。五平の本柱等木柄太く質実で、格式を窺わせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014549"},{"id":"00008602","register_sub_id":"101","register_pk":"134998","name":"浄福寺鐘楼","kana":"じょうふくじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県福岡市南区桧原6-897-7","lat":33.53186744,"lng":130.38529128,"geo_status":"db","era":"江戸後期／明治中期・昭和50年移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、面積8.4㎡","structure_material":"木造","registered":"2011.01.26(平成23.01.26)","register_no":"40 － 0066","desc":"方一間で、四周吹放ちとする。礎盤上に円柱を内転びにたて、腰貫や長押、台輪で固め、尾垂木付二手先を詰組とし、一軒扇垂木を配る。妻木連格子の入母屋造本瓦葺。中央を鏡天井とする化粧屋根裏天井で、彫刻欄間や地紋彫を飾る。秀逸な意匠になる吹放ち鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008602"},{"id":"00014548","register_sub_id":"101","register_pk":"513962","name":"浄福寺離れ座敷","kana":"じょうふくじはなれざしき","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県大川市大字小保字上町市場40-1","lat":33.20440556,"lng":130.37212778,"geo_status":"db","era":"大正5年頃／平成16年・同28年・令和3年改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0212","desc":"榎津の町並みにある浄土真宗寺院の座敷棟で本堂背面に位置。入母屋造桟瓦葺、続き間座敷の周囲に廊下を巡らし、北西に便所角屋を付す。付け書院床構えの座敷は床脇を廊下に張出して一畳増やした七畳間で、旧吉原家住宅と似た独特な床構えとし、地域色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014548"},{"id":"00014547","register_sub_id":"101","register_pk":"513961","name":"浄福寺本堂","kana":"じょうふくじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県大川市大字小保字上町市場40-1","lat":33.20451667,"lng":130.37223333,"geo_status":"db","era":"天保5年（1834）／平成16年改修","year":1834,"year_source":"db","year_min":1834,"year_max":1834,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積161㎡","structure_material":"木造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"40 - 0211","desc":"木工で知られる榎津の町並みに所在する浄土真宗寺院の本堂。入母屋造平入本瓦葺、正面側に縁を巡らし向拝を付す。向拝廻りや内外陣境欄間等に華やかな彫刻を施す。内部は外陣、矢来内、内陣及び左右に余間を設け、典型的な真宗寺院本堂で歴史的町並みを構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014547"},{"id":"00013660","register_sub_id":"101","register_pk":"505027","name":"世界平和パゴダ","kana":"せかいへいわぱごだ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県北九州市門司区大字門司字与郷松3249-2","lat":33.95469167,"lng":130.97075833,"geo_status":"db","era":"昭和33年","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積197㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"40 － 0176","desc":"門司港を見下ろす和布刈公園に建つ。戦没者慰霊、日緬親善交流、世界平和を祈念して建築されたミャンマー様式の仏塔。鉄筋コンクリート造、半径七・四メートルの円形平面で三面に出入口を突出させる。外壁は石張で上部は金色タイルで飾る。類稀な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013660"},{"id":"00016612","register_sub_id":"101","register_pk":"574974","name":"大正寺積翠庵腰掛待合","kana":"たいしょうじせきすいあんこしかけまちあい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県北九州市八幡東区東台良町519-21","lat":33.86111083,"lng":130.79404583,"geo_status":"db","era":"昭和46年頃","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、人工スレート葺、建築面積4.6㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"40 - 0260","desc":"茶室の南東に位置する腰掛待合。露地に北面して建つ平屋建片流造招屋根付で、屋根は人工スレート葺とする。吹放ちの北面以外は土壁とし、内部の南寄りに腰掛を設ける。柱や桁、母屋に丸太を用いた数寄屋風のつくりとし、重森三玲作の露地と調和した腰掛待合。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016612"},{"id":"00016611","register_sub_id":"101","register_pk":"574973","name":"大正寺積翠庵茶室","kana":"たいしょうじせきすいあんちゃしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"福岡県","address":"福岡県北九州市八幡東区東台良町519-21","lat":33.86111083,"lng":130.79404583,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"木造平屋建、瓦葺一部銅板葺、建築面積84㎡","structure_material":"木造平屋建","registered":"2026.02.10(令和8.02.10)","register_no":"40 - 0259","desc":"皿倉山中腹の臨済宗寺院に八幡茶道文化協会が寄進した修養用茶室。平屋建切妻造桟瓦葺で南東に銅板葺庇を廻らす。広間と小間の茶室、水屋などを配し、円窓や火灯窓風の欄間など各室洗練された意匠。布基礎に色石をあしらい、重森三玲作の露地と調和した茶室。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016611"},{"id":"00016746","register_sub_id":"101","register_pk":"579230","name":"波折神社手水舎","kana":"なみおりじんじゃてみずしゃ","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.790702,"lng":130.461752,"geo_status":"db","era":"大正11年","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造、瓦葺、面積4.7㎡","structure_material":"木造","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0263","desc":"境内中央に位置する手水舎。桁行一間、梁間一間、切妻造桟瓦葺。成の高い礎石に角柱を四方転びに立て、頭貫と内法貫で固め、大斗肘木で桁と虹梁を受け、虹梁上の蟇股で棟木を支持。南に井戸、北に手水鉢を配し、四方を吹放つ。小規模ながら境内景観に寄与。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016746"},{"id":"00016747","register_sub_id":"101","register_pk":"579231","name":"波折神社二ノ鳥居","kana":"なみおりじんじゃにのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.790581,"lng":130.461802,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"石造、間口4.2m、高さ5.5m","structure_material":"石造","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0264","desc":"境内中央に位置する石造の明神鳥居。間口４・２メートル、高さ5・5メートル、花崗岩の円柱を内転びに立てて貫で固め、頂部に笠木と島木を載せ、笠木と島木の全体に反りを付ける。拝殿及び幣殿の再建に伴い建立した丁寧なつくりの鳥居で、境内景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016747"},{"id":"00016745","register_sub_id":"101","register_pk":"579229","name":"波折神社拝殿及び幣殿","kana":"なみおりじんじゃはいでんおよびへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.79083,"lng":130.461831,"geo_status":"db","era":"大正9年／昭和54年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積55㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0262","desc":"本殿の南に建つ拝殿及び幣殿。拝殿は正面三間、側面三間、切妻造妻入銅板葺で、背面に両下造銅板葺の幣殿を接続する。拝殿正面には擬宝珠高欄付の縁を設け、一間向拝を付す。内部は一室の畳敷とし、上部は化粧屋根裏天井で、二重虹梁を現した雄大なつくり。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016745"},{"id":"00016744","register_sub_id":"101","register_pk":"579228","name":"波折神社本殿","kana":"なみおりじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福津市津屋崎四丁目1386","lat":33.790933,"lng":130.461851,"geo_status":"db","era":"明治23年／令和3年改修","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積19㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"40 - 0261","desc":"津屋崎港の東側に位置する神社の本殿。境内の北寄りに南面し、石積基壇に建つ三間社流造で屋根銅板葺、四周に縁を廻らす。柱は円柱で組物は平三斗、軒は二軒繁垂木。妻飾は二重虹梁大瓶束で笈形を付し、唐獅子、麒麟、波涛文などの彫刻で飾る華やかな社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016744"},{"id":"00013008","register_sub_id":"101","register_pk":"368081","name":"日本福音ルーテル久留米教会礼拝堂","kana":"にほんふくいんるーてるくるめきょうかいれいはいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県久留米市日吉町16-3","lat":33.31519167,"lng":130.51346944,"geo_status":"db","era":"大正7年／昭和25年・同29年改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造平屋一部2階建、銅板葺、建築面積165㎡","structure_material":"煉瓦造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 164","desc":"市中心部の教会で、街路南側の敷地西南隅に北面して建つ。煉瓦造、東西棟の切妻造で、東北隅の鐘楼北面に玄関を設ける。内部はシザーズ・トラスをかけ、柱のない礼拝空間をつくる。合理的な平面構成や丁寧な仕上がヴォーリズ初期の設計活動の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013008"},{"id":"00013009","register_sub_id":"101","register_pk":"368082","name":"日本福音ルーテル久留米教会煉瓦塀","kana":"にほんふくいんるーてるくるめきょうかいれんがべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県久留米市日吉町16-3","lat":33.31532778,"lng":130.51357778,"geo_status":"db","era":"昭和2年頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"石造及び煉瓦造、総延長21m","structure_material":"石造及び煉瓦造","registered":"2019.09.10(令和1.09.10)","register_no":"40 － 165","desc":"敷地北面の街路沿いに建つ。煉瓦造、基礎切石積で、敷地中央部を後退して正門を設ける。モルタル笠木付の煉瓦長手積角柱を等間隔に並べ、柱間の塀をモルタル塗とし、壁面に７連アーチ、上端に笠木を表す。礼拝堂と調和し、整然とした表構えを形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013009"},{"id":"00014117","register_sub_id":"101","register_pk":"508377","name":"梅林寺ティーハウス","kana":"ばいりんじてぃーはうす","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県久留米市京町字五丁目209-43","lat":33.32352778,"lng":130.49848611,"geo_status":"db","era":"昭和33年／平成20年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積74㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0195","desc":"筑後川左岸高台の梅林寺外苑に建つ、鉄筋コンクリート造平屋建の茶店。中心軸上に配した丸柱と壁柱で屋根スラブと一体化した大梁を支え、梅園及び筑後川に面する外壁をカーテンウォールとする。特殊な架構で軽快なデザインを実現した菊竹清訓初期作品。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014117"},{"id":"00016450","register_sub_id":"101","register_pk":"536517","name":"福岡縣護国神社大鳥居","kana":"ふくおかけんごこくじんじゃおおとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58206667,"lng":130.38028056,"geo_status":"db","era":"昭和18年／令和5年改修","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造、金属板（チタン）葺、柱間8.9m、高さ13m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0253","desc":"境内北辺の参道入口に建つ木造の明神鳥居。設計は二本松孝蔵。柱間８・９メートル、高さ１２・８メートル、台湾ヒノキの原木を用いた独立柱を内転びに立て、柱上に反りのある島木と笠木を載せる。原木材を用いた国内最大級の鳥居の一つで地域の象徴的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016450"},{"id":"00016444","register_sub_id":"101","register_pk":"536511","name":"福岡縣護国神社祈願殿","kana":"ふくおかけんごこくじんじゃきがんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58196389,"lng":130.38188611,"geo_status":"db","era":"昭和36年／平成12年・同24年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積44㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0247","desc":"拝殿北翼廊の北端に接続し、かつて参拝入口に用いた小舎。設計は角南隆。広場に西面して建つ、鉄筋コンクリート造切妻造妻入銅板葺。内部は一室の土間で、正面側は開放的なつくりとする。南翼舎と一対をなし、拝殿を中心とした左右対称の社殿景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016444"},{"id":"00016448","register_sub_id":"101","register_pk":"536515","name":"福岡縣護国神社北手水舎兼灯篭","kana":"ふくおかけんごこくじんじゃきたてみずしゃけんとうろう","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58178333,"lng":130.38111944,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積4.2㎡","structure_material":"鉄筋コンクリート造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0251","desc":"境内中央の広場の北辺中央に建つ手水舎兼灯篭。設計は角南隆。平面八角形、鉄筋コンクリート造宝形造銅板葺で、隅に緩やかな反りを付す。火袋下方は鉢状につくり手水舎を兼ねる。深い軒ながらも軽快な屋根で、全体に均整の取れた端正な意匠の手水舎兼灯篭。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016448"},{"id":"00016452","register_sub_id":"101","register_pk":"536519","name":"福岡縣護国神社招魂社鳥居","kana":"ふくおかけんごこくじんじゃしょうこんしゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58115278,"lng":130.38191111,"geo_status":"db","era":"明治3年／明治39年頃・同44年頃移築","year":1870,"year_source":"db","year_min":1870,"year_max":1870,"year_label":null,"structure":"石造、柱間2.2m、高さ3.1m","structure_material":"石造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0255","desc":"境内中央広場の南東に建つ石造の明神鳥居。柱間２・２メートル、高さ３・１メートル、石造の独立柱を内転びに立て、柱上部に島木と笠木を載せ、正面に扁額を掲げる。旧妙見招魂社からの移築で、各地の招魂社を束ねて創建した、当社の歴史を伝える貴重な鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016452"},{"id":"00016447","register_sub_id":"101","register_pk":"536514","name":"福岡縣護国神社透塀","kana":"ふくおかけんごこくじんじゃすきべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58188611,"lng":130.38243611,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"コンクリートブロック造及び鉄筋コンクリート造、延長69m、木戸付","structure_material":"コンクリートブロック造及び鉄筋コンクリート造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0250","desc":"本殿及び奉安殿の三方を囲み、拝殿背面に接続する透塀。設計は角南隆。延長６９メートル、柱は鉄筋コンクリート造、柱間はコンクリートブロック造で格子窓を開ける。内側に控壁を付し、頂部に屋根をつくる。本殿及び奉安殿域を画す簡明で静謐な佇まいの透塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016447"},{"id":"00016451","register_sub_id":"101","register_pk":"536518","name":"福岡縣護国神社西鳥居","kana":"ふくおかけんごこくじんじゃにしのとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.580325,"lng":130.38028056,"geo_status":"db","era":"昭和18年","year":1943,"year_source":"db","year_min":1943,"year_max":1943,"year_label":null,"structure":"木造、柱間6.2m、高さ8.5m","structure_material":"木造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0254","desc":"境内西辺の南側に建つ木造の明神鳥居。設計は二本松孝蔵。柱間６・２メートル、高さ８・５メートル、台湾ヒノキの原木を用いた独立柱を内転びに立て、柱上部に島木と笠木を載せて、各端部に反りをつける。都心部にあって戦災焼失を免れた貴重な木造の鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016451"},{"id":"00016443","register_sub_id":"101","register_pk":"536510","name":"福岡縣護国神社拝殿及び翼廊","kana":"ふくおかけんごこくじんじゃはいでんおよびよくろう","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58173056,"lng":130.38213333,"geo_status":"db","era":"昭和36年／平成12年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積346㎡、基壇付","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0246","desc":"半円形の舞台状基壇に西面して建つ拝殿と翼廊。設計は角南隆。鉄筋コンクリート造切妻造妻入銅板葺の正面に切妻造向拝を付す。両脇には切妻造棟を突出して周囲に庇を廻らし、さらに両下造の翼廊を左右前方へＶ字状に延ばす。左右対称の壮麗な姿の大規模社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016443"},{"id":"00016446","register_sub_id":"101","register_pk":"536513","name":"福岡縣護国神社奉安殿","kana":"ふくおかけんごこくじんじゃほうあんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58183611,"lng":130.38234167,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積20㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0249","desc":"本殿の東側に西面して建ち戦没者の名簿を収める社殿。設計は角南隆。鉄筋コンクリート造切妻造妻入銅板葺で正面に階段を設け、戸口上部に庇を付す。円柱の床束、井桁に組む台輪、壁面に横目地を入れるなど、全体を校倉造風に仕上げた堅牢な姿の奉安殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016446"},{"id":"00016442","register_sub_id":"101","register_pk":"536509","name":"福岡縣護国神社本殿","kana":"ふくおかけんごこくじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58181111,"lng":130.38226389,"geo_status":"db","era":"昭和36年","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積41㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0245","desc":"福岡城跡の南に位置する神社の本殿。設計は角南隆。境内東側に西面して建つ、鉄筋コンクリート造切妻造銅板葺で、周囲の庇を錣葺とする。軒裏は垂木形とせず平滑に仕上げて軽快にみせ、外に延ばす軒桁や梁、肘木の先端に竪溝を切るなど、独創的な意匠の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016442"},{"id":"00016449","register_sub_id":"101","register_pk":"536516","name":"福岡縣護国神社南手水舎兼灯篭","kana":"ふくおかけんごこくじんじゃみなみてみずしゃけんとうろう","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.5811,"lng":130.38176667,"geo_status":"db","era":"昭和38年","year":1963,"year_source":"db","year_min":1963,"year_max":1963,"year_label":null,"structure":"鉄筋コンクリート造、銅板葺、面積4.0㎡","structure_material":"鉄筋コンクリート造","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0252","desc":"境内中央の広場の南辺中央に建つ手水舎兼灯篭。設計は角南隆。平面八角形とする鉄筋コンクリート造宝形造銅板葺で隅に緩やかな反りを付す。火袋下方は鉢状につくり手水舎を兼ねる。全体に均整の取れた端正な意匠で、北手水舎兼灯篭と一対で境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016449"},{"id":"00016445","register_sub_id":"101","register_pk":"536512","name":"福岡縣護国神社南翼舎","kana":"ふくおかけんごこくじんじゃみなみよくしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福岡県","address":"福岡県福岡市中央区六本松一丁目1区1-1","lat":33.58148611,"lng":130.38218889,"geo_status":"db","era":"昭和36年／平成12年改修","year":1961,"year_source":"db","year_min":1961,"year_max":1961,"year_label":null,"structure":"鉄筋コンクリート造平屋建、銅板葺、建築面積44㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"40 - 0248","desc":"拝殿南翼廊の南端に接続し、かつて神職の控室に用いた小舎。設計は角南隆。広場に西面して建つ、鉄筋コンクリート造切妻造妻入銅板葺。内部は一室の土間で、正面側は開放的なつくりとする。北翼舎と一対で拝殿を中心とした左右対称の壮大な社殿景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016445"},{"id":"00015519","register_sub_id":"101","register_pk":"533534","name":"水田天満宮西門","kana":"みずたてんまんぐうにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県筑後市大字水田字上町64-1","lat":33.19854722,"lng":130.48511944,"geo_status":"db","era":"嘉永4年（1851）","year":1851,"year_source":"db","year_min":1851,"year_max":1851,"year_label":null,"structure":"木造、瓦葺、間口3.1m、袖塀付","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0240","desc":"境内西面に開く四脚門。切妻造本瓦葺で両脇に桟瓦葺袖塀を付す。本柱は円柱、控柱は角柱で頭貫、腰長押で固め、組物は出組で板支輪を付し、軒は二軒繁棰木、妻飾は虹梁大瓶束笈形付とする。支輪板には地紋彫や梅と波の浮彫彫刻を付すなど装飾華やかな西門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015519"},{"id":"00015518","register_sub_id":"101","register_pk":"533533","name":"水田天満宮東門","kana":"みずたてんまんぐうひがしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県筑後市大字水田字上町64-1","lat":33.19854722,"lng":130.4861,"geo_status":"db","era":"慶応4年（1868）","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0239","desc":"境内東面の中央に開く四脚門。切妻造本瓦葺で、円柱の本柱、角柱の控柱を頭貫、腰長押で固め、組物は大斗絵様肘木、軒は二軒繁垂木、妻飾は虹梁大瓶束笈形付とする。内部は化粧軒裏を現し門口に板扉を開く。全体に質実なつくりで境内東面の景観の要となる門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015518"},{"id":"00015517","register_sub_id":"101","register_pk":"533532","name":"水田天満宮楼門","kana":"みずたてんまんぐうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県筑後市大字水田字上町64-1","lat":33.19824167,"lng":130.48576667,"geo_status":"db","era":"江戸末期／平成12年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積24㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"40 - 0238","desc":"市街地南西に位置する神社の門。境内入口に南面して建つ入母屋造本瓦葺、三間三戸の二重門。大面取の角柱を用い、各層とも組物は大斗肘木、軒は二軒繁垂木とし、上層周囲に刎高欄付縁を廻らす。下層に朱塗の獅子鼻など付し、地域景観の核をなす華やかな楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015517"},{"id":"00014116","register_sub_id":"101","register_pk":"508376","name":"明光寺禅堂","kana":"みょうこうじぜんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"福岡県","address":"福岡県福岡市博多区吉塚三丁目347-2他","lat":33.59940833,"lng":130.42751389,"geo_status":"db","era":"江戸後期／明治43年移築、大正5年・昭和34年頃改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積78㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0194","desc":"本堂の西に南東向きに建つ木造禅堂。入母屋造桟瓦葺妻入で、正面に向唐破風の向拝を付す。正面は中央に引違戸、両脇に花頭窓を開ける。内部は土間で正面入側筋を境に二室に区分し、奥の一室に畳敷の床を側廻りに設ける。境内に残る貴重な江戸後期の禅堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014116"},{"id":"00014115","register_sub_id":"101","register_pk":"508375","name":"明光寺霊屋","kana":"みょうこうじたまや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区吉塚三丁目347-2他","lat":33.59952778,"lng":130.42770833,"geo_status":"db","era":"大正15年／昭和37年頃改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積122㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0193","desc":"本堂の北西に並び建つ位牌堂。鉄筋コンクリート造、入母屋造桟瓦葺。側廻りは円柱に舟肘木を載せ長押を廻し、両妻面三箇所の花頭窓を跨ぐ。内部は一室コンクリート土間、虹梁形内法貫と頭貫を縦横に架ける。本堂と共に初期コンクリート造の様相を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014115"},{"id":"00014114","register_sub_id":"101","register_pk":"508374","name":"明光寺本堂","kana":"みょうこうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県福岡市博多区吉塚三丁目347-2他","lat":33.59937778,"lng":130.4278,"geo_status":"db","era":"大正13年／平成22年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積263㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"40 - 0192","desc":"博多駅北東に位置し南西向きに建つ曹洞宗寺院の鉄筋コンクリート造本堂。入母屋造桟瓦葺で正面に向拝、背面に下屋を付す。外観は軸組を鼠漆喰、壁面白漆喰で塗分ける。内部は六間取で正面に広縁を付す。細部まで施工精度の高い初期鉄筋コンクリート造の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014114"},{"id":"00014432","register_sub_id":"101","register_pk":"511421","name":"若八幡宮拝殿","kana":"わかはちまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県糟屋郡久山町大字久原字口ケ坪3497","lat":33.64721944,"lng":130.50159167,"geo_status":"db","era":"元治2年(1865)／大正１４年・平成13年改修","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0205","desc":"本殿正面に建つ拝殿。桁行三間、梁間三間、切妻造妻入銅板葺で正面に一間の向拝を付す。土台建で、軸部は内法貫、頭貫で固め、組物は大斗肘木、軒は二軒疎垂木とする。妻飾りは二重虹梁蟇股。柱や蟇股など古材を用い、小規模ながら装飾充実した妻入の拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014432"},{"id":"00014433","register_sub_id":"101","register_pk":"511422","name":"若八幡宮幣殿","kana":"わかはちまんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"福岡県","address":"福岡県糟屋郡久山町大字久原字口ケ坪3497","lat":33.64724444,"lng":130.50157222,"geo_status":"db","era":"大正13年／昭和53年改修","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積5.0㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0206","desc":"本殿と拝殿の間を繋ぐ幣殿。桁行一間、梁間一間、両下造銅板葺。土台建で、軸部は頭貫、腰長押、内法長押を廻して固める。組物は背面柱上を大斗肘木とし、虹梁上に板蟇股を立てて化粧棟木を支持し、軒は一軒疎垂木。全体に控えめながら、丁寧な造りの弊殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014433"},{"id":"00014431","register_sub_id":"101","register_pk":"511420","name":"若八幡宮本殿","kana":"わかはちまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"福岡県","address":"福岡県糟屋郡久山町大字久原字口ケ坪3497","lat":33.64727778,"lng":130.501525,"geo_status":"db","era":"寛政11年(1799)／昭和元年改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2022.10.31(令和4.10.31)","register_no":"40 - 0204","desc":"犬鳴山南西麓に位置する神社本殿。境内北西の平坦地に東南向きに建つ三間社流造銅板葺で、正面に三間の向拝を付す。組物は出組で中備は蟇股とし、軒は二軒繁垂木。向拝虹梁廻り、妻飾り、脇障子等を彫刻で華やかに飾る。建立年代明確で、彫刻優秀な本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014431"},{"id":"00008382","register_sub_id":"101","register_pk":"134024","name":"医王寺山門","kana":"いおうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市相知町黒岩183","lat":33.37352251,"lng":130.00672053,"geo_status":"db","era":"文政4年（1821)","year":1821,"year_source":"db","year_min":1821,"year_max":1821,"year_label":null,"structure":"木造、瓦葺、間口3.2m","structure_material":"木造","registered":"2010.09.10(平成22.09.10)","register_no":"41 － 0079","desc":"本堂の正面に位置する。一間薬医門、切妻造桟瓦葺。本柱上、冠木を載せ、前後に女梁・男梁を架け、妻及び中備に板蟇股を置く。一軒疎垂木で、切妻造桟瓦葺とする。控柱は面取方柱で、控柱間の中備に雲紋の蟇股を飾る。全体に木太い印象である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008382"},{"id":"00008381","register_sub_id":"101","register_pk":"134023","name":"医王寺本堂","kana":"いおうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県唐津市相知町黒岩183","lat":33.37352108,"lng":130.00705087,"geo_status":"db","era":"安永7年(1778)／明治43年・昭和38年・昭和56年改修","year":1778,"year_source":"db","year_min":1778,"year_max":1778,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積223㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"41 － 0078","desc":"境内の後方中央に西面して建つ。桁行１５ｍ梁間１４ｍ、入母屋造一重桟瓦葺。六間取方丈形式で、その前方二間通りを広縁と前土間とした。内陣の背面に接して須弥壇を構え、来迎柱に平三斗を組む。内陣とその前の大間境は円柱で虹梁をかける。標準的な曹洞宗本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008381"},{"id":"00014121","register_sub_id":"101","register_pk":"508381","name":"願正寺大玄関","kana":"がんしょうじおおげんかん","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25559444,"lng":130.30417222,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造2階建、瓦葺、建築面積180㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0123","desc":"本堂南東に建つ玄関棟。切妻造桟瓦葺、桁行二四・七メートル、梁間七メートルで、南面西寄に大ぶりの入母屋造玄関を付し、両脇に花頭窓を配し、その東を庇付内玄関とする。内部は広間と南西の寺務室、その二階に八畳二室を配す。無柱の大空間が特徴の大玄関。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014121"},{"id":"00014120","register_sub_id":"101","register_pk":"508380","name":"願正寺大広間","kana":"がんしょうじおおひろま","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25575,"lng":130.30426667,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積288㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0122","desc":"本堂東、貴賓室と大玄関の間に建つ広間棟。南北に長大な平面を持つ切妻造桟瓦葺の建物で、内部は八〇畳の大広間とし北に御内仏と両脇に床を構える。講師室を北に配し両脇は廊下を下屋で通す。小屋組にキングポストトラスを用い大空間を実現した近代の大広間。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014120"},{"id":"00014119","register_sub_id":"101","register_pk":"508379","name":"願正寺貴賓室","kana":"がんしょうじきひんしつ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25583333,"lng":130.30412222,"geo_status":"db","era":"18世紀前期","year":1750,"year_source":"estimated","year_min":1701,"year_max":1750,"year_label":"18世紀前期","structure":"木造平屋建、瓦葺、建築面積109㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0121","desc":"本堂北東に建つ客殿。切妻造桟瓦葺、西の貴賓室一〇畳書院座敷と東の奧の間二〇畳からなり、北に半間幅の廊下、南に一間幅畳敷の鞘の間を付し竹節欄間と絵付杉戸で区画する。繊細な筬欄間、面皮付床柱、漆塗の床框等簡素ながら上質な藩主御成間と伝わる書院。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014119"},{"id":"00014123","register_sub_id":"101","register_pk":"508383","name":"願正寺山門","kana":"がんしょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25530278,"lng":130.30409722,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造、瓦葺、間口4.6m","structure_material":"木造","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0125","desc":"本堂南に建つ切妻造本瓦葺平入の四脚門。本柱を丸柱、控柱を角柱として礎盤上に立て、控柱間に強い渦紋の虹梁を架け挿し肘木で受ける。方立脇の幕板の渦紋彫刻、側面の花狭間、桟唐戸の透彫や鈁金具など随所に浄土真宗寺院らしい華やかな装飾を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014123"},{"id":"00014122","register_sub_id":"101","register_pk":"508382","name":"願正寺鐘楼","kana":"がんしょうじしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25536944,"lng":130.30423611,"geo_status":"db","era":"明和5年(1768)","year":1768,"year_source":"db","year_min":1768,"year_max":1768,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積14㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0124","desc":"本堂の南東に建つ入母屋造本瓦葺の鐘楼。赤石を用いた裾広の切石乱積基壇上に建ち、下層は袴腰、上層は丸柱を長押で固め三斗を受け中備を蟇股とする。高欄付の縁は木鼻状板持送りで受ける。佐賀城下の時鐘として用いられたと伝わる木柄の太い重厚な鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014122"},{"id":"00014118","register_sub_id":"101","register_pk":"508378","name":"願正寺本堂","kana":"がんしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市呉服元町182他","lat":33.25562222,"lng":130.303925,"geo_status":"db","era":"元禄15年(1702)／明和2年（1765）改修","year":1702,"year_source":"db","year_min":1702,"year_max":1702,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積805㎡","structure_material":"木造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"41 - 0120","desc":"佐賀城跡北に建つ真宗寺院本堂。正面九間、奥行八間半、入母屋造本瓦葺。外周は大斗と実肘木、中備蟇股等簡素。平面は標準的だが、内外陣境を欄間彫刻で飾り、矢来前面に長大な虹梁を架けて彫刻で飾る。当地の中心的真宗寺院で九州有数の規模と古さを持つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014118"},{"id":"00001757","register_sub_id":"101","register_pk":"102747","name":"陶山神社鳥居","kana":"すえやまじんじゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県西松浦郡有田町大樽2-1464","lat":33.18894139,"lng":129.89909228,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"磁器製、高さ3.7m","structure_material":"磁器製","registered":"2000.04.28(平成12.04.28)","register_no":"41 － 0015","desc":"有田焼が始まる江戸前期に開かれ、有田の象徴的存在として知られる陶山神社の鳥居。明神鳥居の形式で、高さ３．７ｍ、笠木の長さ３．９ｍの規模を持つ。青色顔料の呉須で唐草文が描かれ、有田焼による大規模磁器製作の技術が遺憾なく発揮されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001757"},{"id":"00001020","register_sub_id":"101","register_pk":"102010","name":"日本福音ルーテル小城教会","kana":"にほんふくいんるーてるおぎきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町170-8","lat":33.29190886,"lng":130.19873638,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造平屋一部２階建，スレート葺，建築面積247㎡","structure_material":"木造平屋一部２階建","registered":"1998.12.11(平成10.12.11)","register_no":"41 － 0010","desc":"切妻屋根の小さな木造教会堂で，東面にホール及び牧師館が雁行型状に接続し一体的に構成される。切妻造の教会堂は，背面の妻壁に聖壇部が円形状に張出す独特の外観をしており，親しまれている。設計はヴォーリズ建築事務所で，施工は辻組である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001020"},{"id":"00009679","register_sub_id":"101","register_pk":"194675","name":"与賀神社本殿・幣殿・拝殿","kana":"よかじんじゃほんでん・へいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"佐賀県","address":"佐賀県佐賀市与賀町92","lat":33.2488065,"lng":130.29488318,"geo_status":"db","era":"本殿 宝暦8、幣殿・拝殿 宝暦9／大正2改修","year":1758,"year_source":"db","year_min":1758,"year_max":1758,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積118㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"41 － 0083","desc":"佐賀城西側の境内中央に西面する権現造社殿。本殿は前室付の五間社流造で、内陣を一室として後方に間口三間の内殿を囲い、内宮三基を祀る。妻飾は瑞獣や雲龍などを主題とした巧緻な彫刻で満たす。拝殿は正面軒唐破風付で、内外の随所を華やかな彫刻で飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009679"},{"id":"00009407","register_sub_id":"101","register_pk":"194200","name":"亀岡神社神楽殿","kana":"かめおかじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡151","lat":33.36766083,"lng":129.55673857,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0102","desc":"本殿ほかの社殿を画す回廊及び瑞垣の前方に位置し、参道に西面して建つ。桁行三間梁間三間、入母屋造本瓦葺、四方吹放しとし、背面に下屋を設けて後座とし、正面に石階を付す。懸魚には波に亀の彫刻を施す。平戸神楽を奉納す当社に欠かせない社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009407"},{"id":"00009406","register_sub_id":"101","register_pk":"194199","name":"亀岡神社拝殿","kana":"かめおかじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡1517","lat":33.36809258,"lng":129.5568786,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積48㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0101","desc":"本殿の南側に建ち、幣殿及び登廊を介して本殿と接続する。桁行三間梁間三間、入母屋造本瓦葺、四周に縁を廻し、正面に石階を付す。内部には合祀した四社のうち三社の扁額が掲げられ神社の歴史を伝えている。均整のとれた外観をもち、中心社殿の正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009406"},{"id":"00009405","register_sub_id":"101","register_pk":"194198","name":"亀岡神社弊殿及び登廊","kana":"かめおかじんじゃへいでんおよびのぼりろう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡1517","lat":33.36816301,"lng":129.55692334,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積9.6㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0100","desc":"拝殿背面に幣殿を連ね、本殿と幣殿の間に登廊を架渡す。幣殿は桁行二間梁間一間、渡廊は桁行三間梁間一間、両下造桟瓦葺である。幣殿の棹縁天井をヴォールト状とし、登廊では太鼓橋状に起りをもたせ側面に欄干を配するなど、本殿と併せて独特の形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009405"},{"id":"00009404","register_sub_id":"101","register_pk":"194197","name":"亀岡神社本殿","kana":"かめおかじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県平戸市岩の上町字亀岡1517","lat":33.36821536,"lng":129.5569557,"geo_status":"db","era":"明治13年","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、鉄板葺一部瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2012.08.13(平成24.08.13)","register_no":"42 － 0099","desc":"平戸城二の丸跡に鎮座する神社で、境内北端中央の高い石垣上に本殿が建つ。桁行三間梁間二間、切妻造平入、鉄板葺で、正側面に縁を廻らし、棟に千木、鰹木を戴く。正面に入母屋造桟瓦葺の向拝を付す。向拝木階の左右に神像を安置するなど独特の形式をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009404"},{"id":"00002101","register_sub_id":"101","register_pk":"103091","name":"馬込教会","kana":"まごめきょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県長崎市伊王島町2-617","lat":32.69752345,"lng":129.78167044,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造平屋建、瓦葺、建築面積340㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2000.12.04(平成12.12.04)","register_no":"42 － 0010","desc":"長崎湾西方に浮かぶ伊王島南部の沖之島地区に建つ３廊式の教会堂で，外部は重層屋根，内部は３層構成，８分割リブ・ヴォールト天井とし，正面をバットレス，尖塔，ピナクル等で賑やかに飾る。地元大工棟梁の工夫の跡が随所に窺われる初期ＲＣ造教会堂建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002101"},{"id":"00000276","register_sub_id":"101","register_pk":"101266","name":"宮地嶽八幡神社陶器製鳥居","kana":"みやじだけはちまんじんじゃとうきせいとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県長崎市八幡町8-6","lat":32.75072637,"lng":129.88510697,"geo_status":"db","era":"明治21","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"陶器製，高さ3.5m，幅4.3m","structure_material":"陶器製","registered":"1997.07.15(平成9.07.15)","register_no":"42 － 0001","desc":"有田磁窯による大型細工でつくられた鳥居。親柱部分に残る銘によって製造人が岩尾久吉，角物細工人が金ヶ江長作，丸物細工人が峰熊一であることが判明する。有田に製作者が同一のものがひとつあるが，他に類例がない稀少的な存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000276"},{"id":"00012077","register_sub_id":"101","register_pk":"211018","name":"青井阿蘇神社禊橋","kana":"あおいあそじんじゃみそぎばし","category":"宗教","subcategory":"土木構造物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県人吉市上青井町字上青井町140-1","lat":32.212699,"lng":130.753224,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"コンクリート造3連アーチ橋、橋長27m、幅員3.8m","structure_material":"コンクリート造3連アーチ橋","registered":"2017.10.27(平成29.10.27)","register_no":"43-168","desc":"門前の蓮池に南北に架けられたコンクリート造の三連アーチ橋。橋長二七メートル、幅員三・八メートルで、赤色塗の高欄を設け、両岸に袖高欄を付す。アーチの輪石部は瘤出仕上げの迫石風とし、要石は洋風意匠とする。県内で現存最古のコンクリート橋梁。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012077"},{"id":"00005057","register_sub_id":"101","register_pk":"106047","name":"大川阿蘇神社農村舞台","kana":"おおかわあそじんじゃのうそんぶたい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県上益城郡山都町大平字宮ノ本120","lat":32.6917603,"lng":131.09088548,"geo_status":"db","era":"昭和28","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積89㎡","structure_material":"木造平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"43 － 0076","desc":"西面する境内地の西部に東面して南北棟で建つ。桁行７間，梁間３間半の規模で，切妻造，鉄板葺，木造平屋建で，東側を舞台とし西側に楽屋を設け，中央に上段を設け，舞台北東隅に浄瑠璃棚を付属する。正面間口全体を開き，上部全幅に梁を渡す特異な構造をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005057"},{"id":"00002102","register_sub_id":"101","register_pk":"103092","name":"シャルトル聖パウロ修道院記念館","kana":"しゃるとるせいぱうろしゅうどういんきねんかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県八代市通町10-8","lat":32.50760376,"lng":130.60312845,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積105㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"43 － 0045","desc":"八代白百合学園高等学校敷地内に東を正面にして建つ。木造２階建下見板張，南北棟の寄棟造洋館で，階下内部は中廊下を挟んで２室づつの４室構成とし，階下階上とも東南の２面にベランダを廻す。ベランダ下見板コロニアルの伝播をとらえる上で貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002102"},{"id":"00012664","register_sub_id":"101","register_pk":"367958","name":"シャルトル聖パウロ修道女会八代修道院煉瓦塀","kana":"しゃるとるせいぱうろしゅうどうじょかいやつしろしゅうどういんれんがべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県八代市通町壱0号7-1","lat":32.50806,"lng":130.604767,"geo_status":"geocoded","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"煉瓦造、延長21m","structure_material":"煉瓦造","registered":"2018.11.02(平成30.11.02)","register_no":"43 － 0174","desc":"市中心部にある修道院の敷地境界塀の一部で、街路に面した敷地東面北半に建つ。高さ1･8メートル、躯体を煉瓦の長手積とし、規則的に柱形をつくり出す。頂部は二段の蛇腹上に煉瓦で切妻屋根をつくる。開発が進む中心市街地の歴史的景観を伝える希少な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012664"},{"id":"00000918","register_sub_id":"101","register_pk":"101908","name":"高寺院毘沙門堂","kana":"たかでらいんびしゃもんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"low","period":"江戸","pref":"熊本県","address":"熊本県球磨郡山江村大字山田甲1640","lat":32.2488061,"lng":130.76169491,"geo_status":"db","era":"承応4","year":1655,"year_source":"db","year_min":1655,"year_max":1655,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積28㎡","structure_material":"木造平屋建","registered":"1998.10.09(平成10.10.09)","register_no":"43 － 0015","desc":"山頂に建つ三間堂。内部は柱を省略し，後方に幅一間の須弥壇を設け，格天井を張る。須弥壇の墨書から承応４年の建立が知られる。反り増しを持つ太い垂木は地域的特色。中世～近世前期の寺社建築が多数現存する球磨地方において時代の指標となる建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000918"},{"id":"00013206","register_sub_id":"101","register_pk":"368430","name":"日本福音ルーテル熊本教会","kana":"にほんふくいんるーてるくまもときょうかい","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県熊本市中央区水道町1-17","lat":32.80295,"lng":130.71296667,"geo_status":"db","era":"昭和25年／平成17年改修","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"木造3階建、金属板葺、建築面積213㎡、階段付","structure_material":"木造3階建","registered":"2019.12.05(令和1.12.05)","register_no":"43 － 0176","desc":"市中心部にある教会堂。木造二階一部三階建、切妻造金属板葺で、南東角に尖頭屋根を戴く塔を配する。一階は集会室、二階は主廊部の南側にのみ側廊が付く礼拝堂で、ハンマービーム・トラスを現し、開口は尖頭アーチで統一する。ヴォーリズ晩年の作品のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013206"},{"id":"00003637","register_sub_id":"101","register_pk":"104627","name":"梅林天満宮鳥居","kana":"ばいりんてんまんぐうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.93371286,"lng":130.58861752,"geo_status":"db","era":"万治2／昭和3改造","year":1659,"year_source":"db","year_min":1659,"year_max":1659,"year_label":null,"structure":"石造、高さ4.8m","structure_material":"石造","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0057","desc":"石造の明神鳥居だが，柱の頂部を台輪状に彫り出している。柱は足元で径約７３ｃｍと太く，また内転びも大きい。各部材も木太く，全体の比例にも地方色があらわれている。数度の改造があるが，神社の正面を飾る堂々とした形態で，地域景観の核となっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003637"},{"id":"00003635","register_sub_id":"101","register_pk":"104625","name":"梅林天満宮拝殿","kana":"ばいりんてんまんぐうはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.9340051,"lng":130.58862466,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0055","desc":"桁行梁間とも３間，入母屋造，平入，銅板葺で，正面には１間向拝を設け，正面と両側面に独特な擬宝珠高欄付の切目縁を廻す。組物は出組で，中備は蟇股，軒は２軒吹寄せ垂木とする。向拝は唐破風造で，透彫の手挟や梅鉢文を彫った大柄な蟇股など見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003635"},{"id":"00003634","register_sub_id":"101","register_pk":"104624","name":"梅林天満宮本殿","kana":"ばいりんてんまんぐうほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.93409245,"lng":130.58862466,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0054","desc":"桁行３間，梁間２間，入母屋造，正面３間向拝付の本殿建築で，正面と両側面に切目縁を廻す。組物は２手先，２軒繁垂木で，屋根は銅板葺。波涛文風彫物の軒支輪，彫物を入れた中備の蟇股，透彫の向拝手挟，頭貫の雲文絵様など，上方に装飾を集めた造形になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003634"},{"id":"00003636","register_sub_id":"101","register_pk":"104626","name":"梅林天満宮楼門","kana":"ばいりんてんまんぐうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県玉名市津留499","lat":32.93378334,"lng":130.58862228,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2003.09.19(平成15.09.19)","register_no":"43 － 0056","desc":"３間１戸の２重門。上重は桁行３間，梁間２間の入母屋造で，４周に擬宝珠高欄付の縁を廻し，尾垂木付の３手先組物で２軒繁垂木の軒を受ける。下重は前後に軒唐破風を設け，菖蒲棟を力神像で支える。全体の比例，高い基壇など，地方色豊かな造形を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003636"},{"id":"00008792","register_sub_id":"101","register_pk":"149513","name":"本妙寺仁王門","kana":"ほんみょうじにおうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県熊本市花園4-128","lat":32.81540897,"lng":130.69250935,"geo_status":"db","era":"大正9年","year":1920,"year_source":"converted","year_min":1920,"year_max":1920,"year_label":null,"structure":"鉄筋コンクリート造、間口13m","structure_material":"鉄筋コンクリート造","registered":"2011.07.25(平成23.07.25)","register_no":"43 － 0112","desc":"本妙寺山麓に位置する。鉄筋コンクリート造の三間三戸八脚門。切妻造で、前後に軒唐破風を付設。総円柱で、大斗組とし、妻は虹梁上に束をたてる。一軒繁垂木。両脇後間の上部に仁王像、中央間境にライオンの阿吽像を飾る。時代を反映した自由な発想が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008792"},{"id":"00000809","register_sub_id":"101","register_pk":"101799","name":"明導寺本堂","kana":"みょうどうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"大正","pref":"熊本県","address":"熊本県球磨郡湯前町買元1955","lat":32.27730308,"lng":130.98203795,"geo_status":"db","era":"大正15","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積292㎡","structure_material":"木造平屋建","registered":"1998.09.02(平成10.09.02)","register_no":"43 － 0014","desc":"特異な意匠の寺院本堂。マンサード屋根，下見板貼りの外壁，ハーフティンバー形式の正面入口，アーチ形が連続する内外陣境，尖頭アーチ形の窓，トラスの小屋組など，各部が洋風になる。京都龍谷大学で学んだ住職の長男が独自に設計したと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000809"},{"id":"00016461","register_sub_id":"101","register_pk":"536528","name":"妙蓮寺鐘楼門","kana":"みょうれんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"熊本県","address":"熊本県菊池市隈府247","lat":32.98292222,"lng":130.81125,"geo_status":"db","era":"江戸中期／寛文12年（1672）移築、大正4年改修","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造2階建、瓦葺、建築面積8.2㎡","structure_material":"木造2階建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0219","desc":"境内北端、通りに面して建つ二重門。入母屋造桟瓦葺で、扉口を棟筋より前面に寄せ、上層の正背面に火灯窓を開け、側廻の柱間に菱格子を建て、周囲に擬宝珠高欄付縁を廻らす。組物は大斗肘木、軒は一軒繁垂木。絵様など古式で境内の表構えをつくる鐘楼門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016461"},{"id":"00016460","register_sub_id":"101","register_pk":"536527","name":"妙蓮寺本堂","kana":"みょうれんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県菊池市隈府247","lat":32.98261944,"lng":130.81141389,"geo_status":"db","era":"明治30年／平成15年・同18年改修","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積211㎡","structure_material":"木造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0218","desc":"隈府の中央部の角地に位置する日蓮宗寺院の本堂。境内南側に北面して建つ入母屋造桟瓦葺で正面向拝付き。内部は内外陣・両脇陣からなり、内陣に須弥壇を配す。向拝は皿斗二重の大斗や雲形肘木など独特で、虹梁形頭貫に龍彫刻を横溢させ、装飾華やかな本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016460"},{"id":"00008385","register_sub_id":"101","register_pk":"134027","name":"老松天満社金刀比羅社","kana":"おいまつてんまんしゃことひらしゃ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20523546,"lng":131.0190443,"geo_status":"db","era":"文政7年(1824)／江戸末期移築","year":1824,"year_source":"db","year_min":1824,"year_max":1824,"year_label":null,"structure":"石造平屋建、建築面積0.7㎡","structure_material":"石造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0181","desc":"拝殿の北方に、石積基壇上に南面して建つ。石造の社殿で、桁行０．７３ｍ梁間０．５５ｍの規模で、正面に唐破風造向拝を付ける入母屋造屋根を載せる。石材は日田石と通称される地元産の凝灰岩。肘木や妻飾なども丁寧に作り出されるなど秀でた技巧が見られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008385"},{"id":"00008386","register_sub_id":"101","register_pk":"134028","name":"老松天満社鳥居","kana":"おいまつてんまんしゃとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20510024,"lng":131.0192555,"geo_status":"db","era":"弘化3年(1846)","year":1846,"year_source":"db","year_min":1846,"year_max":1846,"year_label":null,"structure":"石造、間口2.5m","structure_material":"石造","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0182","desc":"境内の東寄り、参道の正面に位置する。花崗岩を使った石造。内転びのある直径０．４４ｍ胴張りのある円柱を、柱間２．５ｍに建て、貫を通し、一体で作られた島木と笠木を上部に載せる。笠木は勢いのある反りをもち、軸太の柱とよく調和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008386"},{"id":"00008384","register_sub_id":"101","register_pk":"134026","name":"老松天満社拝殿","kana":"おいまつてんまんしゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20512151,"lng":131.01907013,"geo_status":"db","era":"明治31年","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、茅葺、建築面積42㎡、渡殿付","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0180","desc":"本殿の正面に位置する。桁行三間梁間三間、入母屋造、正面に向拝一間と千鳥破風を付ける。茅葺に杉皮を葺き込む特徴的な仕様とする。正面は桟唐戸と蔀戸、背面は蔀戸で、両脇に壇を設ける。内部は拭板敷で、格天井を張る。穏やかな外観が農村景観に融和する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008384"},{"id":"00008383","register_sub_id":"101","register_pk":"134025","name":"老松天満社本殿","kana":"おいまつてんまんしゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県日田市天瀬町出口字中村1183","lat":33.20512758,"lng":131.01894554,"geo_status":"db","era":"明治31年／昭和54年改修","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"44 － 0179","desc":"境内の後方に東面して建つ。三間社流造、銅板葺。組高欄付の切目縁を周囲にまわし、正面に木階を設ける。円柱で出組とし、中備に蟇股を置く。妻は二重虹梁で二段にもち出し、拝みに唐獅子などの彫刻を飾る。均整のとれた外観のなか、彫物装飾が適度に配される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008383"},{"id":"00009090","register_sub_id":"101","register_pk":"162450","name":"春日神社神楽殿","kana":"かすがじんじゃかぐらでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57683522,"lng":131.46845364,"geo_status":"db","era":"天保6年(1835)","year":1835,"year_source":"db","year_min":1835,"year_max":1835,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積32㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0189","desc":"拝殿の東南に西面して建つ。桁行二間梁間一間、入母屋造妻入本瓦葺。正・側面に切目縁をまわし、北面後寄りから斜めに橋掛を延ばす。橋掛は桁行三間梁間一間、両下造桟瓦葺。神楽殿は角柱に舟肘木を載せ、中備に間斗束と絵様実肘木をおく。神社境内に残る神楽殿の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009090"},{"id":"00009089","register_sub_id":"101","register_pk":"162449","name":"春日神社籠り屋","kana":"かすがじんじゃこもりや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57691749,"lng":131.46850988,"geo_status":"db","era":"昭和2年","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0188","desc":"神楽殿の橋掛の先に続く。桁行5.9メートル梁間3.9メートルの木造平屋建、切妻造桟瓦葺で、西正面に瓦庇を付ける。内部は北側にコンクリート土間、南側に八畳の床上部を配する。籠り屋としてとともに神楽殿の楽屋、地域住民の集会所などとして利用される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009089"},{"id":"00009095","register_sub_id":"101","register_pk":"162455","name":"春日神社参道鳥居","kana":"かすがじんじゃさんどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57650481,"lng":131.46817257,"geo_status":"db","era":"享保5年(1720）","year":1720,"year_source":"db","year_min":1720,"year_max":1720,"year_label":null,"structure":"石造、間口3.1m、高さ3.8m","structure_material":"石造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0194","desc":"春日神社境内の南端に位置する。石造の明神鳥居で、幅3.1メートル高さ3.8メートル。礎石の上に内転びで円柱を建て、貫と島木、笠木で固める。笠木の両端に強い反りをもたせ、力強い立面を構成する。深い社叢の正面に建ち、近世以来の歴史的景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009095"},{"id":"00009091","register_sub_id":"101","register_pk":"162451","name":"春日神社鐘楼","kana":"かすがじんじゃしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57683001,"lng":131.46825371,"geo_status":"db","era":"文政13年(1830)","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積7.4㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0190","desc":"拝殿の南方、神楽殿と参道を挟んで対峙する。切石基礎上に建つ方一間袴腰付の鐘楼。入母屋造本瓦葺。方柱上部を頭貫と台輪で固め、三斗を組み、中備に蟇股を飾る。一軒半繁垂木とし、内部も化粧垂木を現す。近世における神仏習合の境内景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009091"},{"id":"00009092","register_sub_id":"101","register_pk":"162452","name":"春日神社神門","kana":"かすがじんじゃしんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57674358,"lng":131.46831307,"geo_status":"db","era":"弘化2年（1845）","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"木造、瓦葺、間口3.4m、左右袖塀付","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0191","desc":"拝殿の前方に位置する四脚門。切妻造本瓦葺。本柱は粽付円柱で、控柱は几帳面取方柱。虹梁状の頭貫や台輪で固め、組物は三斗組。妻は虹梁大瓶束で、二軒繁垂木。四半石敷で、格天井を張る。前間には格子付の棚を設け随身像を安置。威厳ある境内構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009092"},{"id":"00009085","register_sub_id":"101","register_pk":"162445","name":"春日神社摂社厳島神社","kana":"かすがじんじゃせっしゃいつくしまじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57714345,"lng":131.46831411,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0184","desc":"本殿の西に南面して建ち、一間社流造銅板葺である。切石基礎に土台を据えて円柱を立て、長押や貫で固める。組物は舟肘木、軒は二軒繁垂木とし、妻飾を豕叉首とする。擬宝珠高欄付の切目縁を廻らし、正面に木階二級を付ける。小規模ながら丁寧なつくりの社殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009085"},{"id":"00009086","register_sub_id":"101","register_pk":"162446","name":"春日神社摂社八坂神社","kana":"かすがじんじゃせっしゃやさかじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.5771195,"lng":131.46848801,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0185","desc":"本殿の東に南面して建つ。一間社流造銅板葺で、高欄付の切目縁を三方にまわす。切石基礎に土台を据えて円柱を立て、長押や貫で固める。組物は三斗組、軒は二軒繁垂木とし、妻飾は虹梁を省き蟇股のみとする。海老虹梁の身舎側は頭貫木鼻と同様の絵様を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009086"},{"id":"00009096","register_sub_id":"101","register_pk":"162456","name":"春日神社西参道鳥居","kana":"かすがじんじゃにしさんどうとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57726108,"lng":131.4678901,"geo_status":"db","era":"昭和9年","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"石造、間口3.1m、高さ3.9m","structure_material":"石造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0195","desc":"西門へと延びる西参道の入口に建つ。石造の明神鳥居で、幅3.1メートル高さ3.9メートル。径36センチメートルの円柱を内転びに建て、貫と島木、笠木で固める。嶋木や笠木はほぼ同じせいで、全体に反りをもたせ、安定感のある姿をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009096"},{"id":"00009093","register_sub_id":"101","register_pk":"162453","name":"春日神社西門","kana":"かすがじんじゃにしもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57711117,"lng":131.46815062,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造、瓦葺、間口1.9m","structure_material":"木造","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0192","desc":"拝殿の西方に位置する。小規模な一間一戸薬医門で、切妻造本瓦葺。本柱は円柱、控柱は面取角柱で、それぞれを虹梁形頭貫で固め、主・控柱間には男梁を架す。男梁上に虹梁を置き、棟木を支持し、一軒疎垂木を配る。木部は赤色に塗装され、西紅門とも称される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009093"},{"id":"00009088","register_sub_id":"101","register_pk":"162448","name":"春日神社拝殿","kana":"かすがじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57701225,"lng":131.46836513,"geo_status":"db","era":"大正10年","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積103㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0187","desc":"申殿の前方に東西棟で建つ。桁行九間梁間四間、入母屋造本瓦葺で、正面中央に入母屋屋根の一間向拝を付ける。切石積基壇上に方柱を立て、貫で固める。内部は一室で板敷とし、格天井を張る。両側面を土壁とするほかは開口とする、横長で開放的なつくりの拝殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009088"},{"id":"00009084","register_sub_id":"101","register_pk":"162444","name":"春日神社本殿","kana":"かすがじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.57714137,"lng":131.46840366,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、銅板葺、建築面積17㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0183","desc":"境内の中央に南面して建つ。三間社切妻造、向拝一間銅板葺である。周囲に組高欄付切目縁をまわし、正面に蔀、側面前一間に桟唐戸を吊る。妻飾は二重虹梁大瓶束で、組物で二手分持ち出し、小天井と支輪を付ける。たちの高い外観構成になる本殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009084"},{"id":"00009087","register_sub_id":"101","register_pk":"162447","name":"春日神社申殿","kana":"かすがじんじゃもうしでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県豊後高田市草地字三笠山5206","lat":33.5770716,"lng":131.46838075,"geo_status":"db","era":"明治38年","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0186","desc":"本殿正面に位置する。東西棟の切妻造桟瓦葺。桁行一間梁間一間。円柱を長押や頭貫、台輪で固め、組物は三斗とし、妻は束で棟木や母屋を支持する。内部は一室で板敷、格天井を張り、柱間は側面後半を板壁とし、他はガラス戸を建てる。当地方に見られる申殿の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009087"},{"id":"00009094","register_sub_id":"101","register_pk":"162454","name":"春日神社余興舞台","kana":"かすがじんじゃよきょうぶたい","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"大分県","address":"大分県豊後高田市草地字尾園324","lat":33.57541886,"lng":131.46190251,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積115㎡","structure_material":"木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"44 － 0193","desc":"境内から1キロメートルほど離れた御旅所に南を正面として建つ。桁行16メートル梁間7.9メートルの入母屋造セメント瓦葺で、妻面に下屋を付設する。南半部を舞台、北半部を楽屋とする。正面を除き、外壁は下見板張。小屋は和小屋。伝統的な農村舞台建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009094"},{"id":"00009688","register_sub_id":"101","register_pk":"194684","name":"正行寺山門","kana":"しょうぎょうじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1148-1","lat":33.57345493,"lng":131.2054068,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.3m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0204","desc":"本堂正面の参道に建ち、四脚門、切妻造桟瓦葺である。柱頭を、成が高く華やかな絵様を施した梁や頭貫で固め、重厚な軸部を構成する。また妻飾では竜頭を象った大瓶束を立て、妻壁板に笈型を陽刻し雲紋を地紋彫するなど、豊かな装飾が特徴的な、風格ある山門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009688"},{"id":"00009687","register_sub_id":"101","register_pk":"194683","name":"正行寺鐘楼","kana":"しょうぎょうじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1148-1","lat":33.573345,"lng":131.20528164,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、面積8.1㎡","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0203","desc":"境内東寄り、山門の南側に位置し、布石積み基壇上に東西棟で建つ吹放し形式の鐘楼。入母屋造桟瓦葺。軸部は禅宗様を基調とし、石製礎盤に円柱を立て、折上格天井を張る。台輪上に独特なつくりの尾垂木付三斗を詰組とする。真宗寺院伽藍を特徴付ける鐘楼。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009687"},{"id":"00009689","register_sub_id":"101","register_pk":"194685","name":"正行寺袖塀","kana":"しょうぎょうじそでべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1148-1","lat":33.57350538,"lng":131.20543014,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、総延長20m","structure_material":"木造","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0205","desc":"山門の本柱から南北面に矩折れにのびる袖塀。総延長二〇メートル、切妻造桟瓦葺で、北側塀の北面に潜戸を開く。布石基礎上に須柱を立て、壁は腰をモルタル洗い出しとし、上部に五筋の定規線を表す。山門とともに門前の景観を形成し、結界を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009689"},{"id":"00009686","register_sub_id":"101","register_pk":"194682","name":"正行寺本堂","kana":"しょうぎょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県中津市大字永添字城屋敷1190","lat":33.57381613,"lng":131.20479861,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積696㎡","structure_material":"木造平屋建","registered":"2013.06.21(平成25.06.21)","register_no":"44 － 0202","desc":"境内西奥に東面する。総桁行約二七メートル、入母屋造本瓦葺で、正面に向拝三間を設ける。後門形式の平面をもつ真宗本堂で、軸部は良質なケヤキの長大材を用い、組物出組とし、各室に高く折上格天井を張る。細部彫刻も優れた、雄大なつくりの大型本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009686"},{"id":"00007427","register_sub_id":"101","register_pk":"108409","name":"浄土寺一伯公廟","kana":"じょうどじいっぱくこうびょう","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242668,"lng":131.58887059,"geo_status":"db","era":"江戸後期／大正14・昭和49移築","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造平屋建、瓦葺、建築面積7.3㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0153","desc":"本堂の東方に位置する。桁行３．０ｍ梁間２．４ｍ、入母屋造妻入桟瓦葺で、正面に軒唐破風を付ける。粽付円柱を建て、尾垂木付二手先を組み、支輪には雲文様を刻む。組物などの細部意匠は古風。内部は土間の一室で、格天井を張る。近世における廟所建築の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007427"},{"id":"00007428","register_sub_id":"101","register_pk":"108410","name":"浄土寺表門","kana":"じょうどじおもてもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.24274785,"lng":131.58892073,"geo_status":"db","era":"明治後期／昭和26改修・昭和49移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造、瓦葺、間口3.3m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0154","desc":"本堂の正面に南北棟で建つ四脚門。両脇に袖塀を設け、花頭形に穿ち、開戸をたてる。屋根は入母屋造桟瓦葺。控柱とも粽付円柱で、柱上に出組、中備に蟇股を置く。軒は二軒扇垂木で、内部に格天井を張る。龍や貘、唐獅子ほかの彫物により豊かに装飾されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007428"},{"id":"00007429","register_sub_id":"101","register_pk":"108411","name":"浄土寺北門","kana":"じょうどじきたもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.24316,"lng":131.58886487,"geo_status":"db","era":"大正14／昭和49移築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造、瓦葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0155","desc":"境内の北辺、通りに面して建つ四脚門。両脇に袖塀を設け、潜りを開ける。東西棟の切妻造桟瓦葺とし、棟両端に鯱を飾る。本柱は円柱、控柱は方柱。組物は三斗組、妻虹梁蟇股とし、軒は二軒繁垂木。柱上などに皿斗を置き、その上に台輪をまわす特異な仕様になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007429"},{"id":"00007424","register_sub_id":"101","register_pk":"108406","name":"浄土寺庫裏","kana":"じょうどじくり","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242977,"lng":131.588654,"geo_status":"db","era":"江戸後期／江戸末期改修","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積164㎡","structure_material":"木造2階建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0150","desc":"本堂の北方に東面して建つ。桁行８間半梁間４間規模の細長い建物で、寄棟造妻入桟瓦葺とし、四面に庇を付ける。正面から桁行に大きく３分し、西端にトコ付の座敷と奥座敷を並べる。大面取の方柱をほぼ１間ごとに建てるなど古風な仕様を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007424"},{"id":"00007425","register_sub_id":"101","register_pk":"108407","name":"浄土寺玄関及び渡廊下","kana":"じょうどじげんかんおよびわたりろうか","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242882,"lng":131.5886403,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造平屋建、瓦葺、建築面積51㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0151","desc":"本堂と庫裏を繋ぐ南北棟の渡廊下で、東面に入母屋屋根の玄関を付設する。渡廊下は南半部を板敷の高廊下、北半部を畳廊下とする。玄関は前半部を吹放ち、方柱を建て、三斗組とする。本堂や庫裏とともに正面を向けて並び建ち、重厚な伽藍景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007425"},{"id":"00007426","register_sub_id":"101","register_pk":"108408","name":"浄土寺大弁財天石宮","kana":"じょうどじだいべんざいてんせきぐう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.243073,"lng":131.588531,"geo_status":"db","era":"明治44／昭和49移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"石造、面積2.3㎡","structure_material":"石造","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0152","desc":"庫裏の西北、庭園内に建つ石造本殿。小規模な一間社流造で、切石基壇上に建つ。石材は地元産の凝灰岩で、基礎と身舎、向拝、屋根の４石からなる。木鼻や組物、懸魚、垂木など細部まで丁寧な仕上げとなり、技巧的な冴えを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007426"},{"id":"00007423","register_sub_id":"101","register_pk":"108405","name":"浄土寺本堂","kana":"じょうどじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県大分市王子西町93-1","lat":33.242737,"lng":131.588654,"geo_status":"db","era":"嘉永2／昭和55改修","year":1849,"year_source":"db","year_min":1849,"year_max":1849,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積454㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"44 － 0149","desc":"境内地の中央南寄りに東面して建つ大規模な七間堂。入母屋造本瓦葺で、正面に一間向拝を付ける。正・側三方に広縁をまわし、庇柱を建てる。外陣と余間、凸型の内陣からなる浄土宗本堂の典型的な平面をもつ。四天柱上部の組物や支輪など装飾的で見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007423"},{"id":"00007818","register_sub_id":"101","register_pk":"108799","name":"真宗大谷派四日市別院石橋及び水路石垣","kana":"しんしゅうおおたにはよっかいちべついんいしばしおよびすいろいしがき","category":"宗教","subcategory":"土木構造物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53055656,"lng":131.32520382,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"橋 石造桁橋、橋長2.9m、幅9.5m、高欄付、石垣 石造、延長55m","structure_material":"橋 石造桁橋","registered":"2009.08.07(平成21.08.07)","register_no":"44-0170","desc":"境内東辺に南北に水路が流れ、山門前には石橋が架かる。幅９．５ｍ長さ２．９ｍの石造桁橋。上方に反らせた桁を９本架け、板石を並べる。下部に水繰を付ける高欄を両端に置く。石垣は安山岩を割石乱積とする。山門とともに伽藍正面を画し、風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007818"},{"id":"00007815","register_sub_id":"101","register_pk":"108796","name":"真宗大谷派四日市別院経蔵","kana":"しんしゅうおおたにはよっかいちべついんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53017344,"lng":131.32416655,"geo_status":"db","era":"寛政11／明治前期改修","year":1799,"year_source":"db","year_min":1799,"year_max":1799,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積28㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0167","desc":"境内の西南隅に位置する。切石３段を階段状に積み上げた基壇上に建つ方三間の土蔵造。宝形造本瓦葺で、正面に唐破風造銅板葺の一間向拝を付ける。外壁は漆喰仕上げ、内部は目地漆喰の碁盤敷、折上格天井とし、中央に八角輪蔵を置く。丁寧なつくりになる経蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007815"},{"id":"00007816","register_sub_id":"101","register_pk":"108797","name":"真宗大谷派四日市別院太鼓楼","kana":"しんしゅうおおたにはよっかいちべついんたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53095809,"lng":131.32463834,"geo_status":"db","era":"江戸末期／昭和前期増築","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積61㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0168","desc":"境内の北辺中央に位置する。東西棟の入母屋造本瓦葺とする二重二階の太鼓楼で、南に切妻造桟瓦葺の平屋を増築する。 ２階は桁行２．９ｍ梁間２．９ｍ、東・西面の中央に花頭窓を穿ち、内部に太鼓を備える。北半部は当初の形態をよくとどめ、伽藍景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007816"},{"id":"00007817","register_sub_id":"101","register_pk":"108798","name":"真宗大谷派四日市別院土塀及び石垣","kana":"しんしゅうおおたにはよっかいちべついんどべいおよびいしがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53101999,"lng":131.32464336,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"塀 土塀、瓦葺、延長17m、石垣 石造、延長15m","structure_material":"塀 土塀","registered":"2009.08.07(平成21.08.07)","register_no":"44-0169","desc":"境内北辺にあり、太鼓楼の北側に位置する。石垣は県内産の安山岩を割石乱積とする。石垣上に布石を置き、土塀を築く。高さ１．３ｍ厚さ０．５４ｍの練塀で、折曲り延長１７ｍ。白漆喰仕上げとし、桟瓦を葺く。太鼓楼とともに真宗寺院らしい佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007817"},{"id":"00007814","register_sub_id":"101","register_pk":"108795","name":"真宗大谷派四日市別院本堂","kana":"しんしゅうおおたにはよっかいちべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県宇佐市大字四日市字寺町1425-1","lat":33.53063352,"lng":131.32434891,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1086㎡","structure_material":"木造平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"44-0166","desc":"境内後方の中央に東面して建つ。桁行２８ｍ梁間２５ｍ、周囲に軒支柱を建て、三間向拝を付ける。入母屋造とし、平側を本瓦葺、妻側を桟瓦葺とする。真宗本堂の特徴的な平面になり、内陣まわりを漆や彩画、彫物などで飾る。九州における最大級の真宗本堂である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007814"},{"id":"00008221","register_sub_id":"101","register_pk":"132746","name":"長善寺鐘楼門","kana":"ちょうぜんじしょうろうもん","category":"宗教","subcategory":"建築物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県日田市吹上町1233","lat":33.33044516,"lng":130.92870347,"geo_status":"db","era":"正徳3年（1713）/明和3年(1766)・享和3年(1803)・昭和21年改修","year":1713,"year_source":"db","year_min":1713,"year_max":1713,"year_label":null,"structure":"木造2階建、瓦葺、建築面積13㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"44 － 0174","desc":"南面して建つ三間一戸楼門。入母屋造本瓦葺。上層は桁行三間梁間二間、正・背面中央間を開放し、両脇間に花頭窓を穿ち、側面は格子窓とする。方柱で、出組とし、雲紋を彫る板支輪を付ける。二軒繁垂木で、腰組は出三斗。２階階高を抑え、外観に安定感を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008221"},{"id":"00011018","register_sub_id":"101","register_pk":"208988","name":"本願寺四日市別院御成御殿","kana":"ほんがんじよっかいちべついんおなりごてん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531546,"lng":131.325041,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積107㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0211","desc":"門主の控所で対面所背面に渡廊下で接続して建つ。入母屋造桟瓦葺で鉄板葺庇を廻らす。内部は八畳二室を並べ、渡廊下北に四畳半、三畳を置く。南八畳の床まわりは丸太の床柱、床脇の仕切壁や天袋、地袋、明かり窓などに数寄屋風の自由な意匠を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011018"},{"id":"00011020","register_sub_id":"101","register_pk":"208990","name":"本願寺四日市別院経蔵","kana":"ほんがんじよっかいちべついんきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531019,"lng":131.325114,"geo_status":"db","era":"明治18","year":1885,"year_source":"db","year_min":1885,"year_max":1885,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積30㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0213","desc":"本堂南に東面して建つ。六角形平面で、階段状の石積基壇上に建ち、外壁から軒裏まで柱や長押形を現した漆喰塗込とする。屋根は宝形造本瓦葺で、中心に宝珠を据え正面に唐破風玄関を付す。内部には八角輪蔵を据える。類例の少ない六角円堂の経蔵として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011020"},{"id":"00011019","register_sub_id":"101","register_pk":"208989","name":"本願寺四日市別院庫裏及び長御殿","kana":"ほんがんじよっかいちべついんくりおよびながごてん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531647,"lng":131.325444,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階一部平屋建、瓦葺、建築面積530㎡","structure_material":"木造2階一部平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0212","desc":"対面所北に接続する。庫裏は東西棟の入母屋造二階建で、南向に入母屋玄関を開く。東端を土間とし、西寄りに二八畳の香坊と一五畳のオナイブツノマを繋げた広間を配する。庫裏西の長御殿は末寺の陳情活動のための施設で、中廊下の両側に二室ずつを並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011019"},{"id":"00011025","register_sub_id":"101","register_pk":"208995","name":"本願寺四日市別院山門","kana":"ほんがんじよっかいちべついんさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531265,"lng":131.325749,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口4.8m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"44-0218","desc":"境内正面に構える山門。四脚門で屋根は入母屋造桟瓦葺で、格天井を張る。本柱は丸柱、控柱は角柱とし、長押及び頭貫と台輪で固め、出組組物で軒を支える。頭貫や組物の木鼻、頭貫の地紋彫、虹梁の若葉付木瓜形渦紋など軒廻りを華やかに飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011025"},{"id":"00011024","register_sub_id":"101","register_pk":"208994","name":"本願寺四日市別院鐘楼","kana":"ほんがんじよっかいちべついんしょうろう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.53102,"lng":131.325852,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積17㎡","structure_material":"木造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0217","desc":"境内正面の南端に建つ桁行三間、梁間二間の袴腰付鐘楼。下層組物は二手先で、上層の高欄付縁を支える。上層は粽付丸柱の頭を頭貫及び台輪で固め、二手先組物で軒を支持する。屋根は入母屋造桟瓦葺である。太鼓楼とともに、真宗寺院正面の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011024"},{"id":"00011021","register_sub_id":"101","register_pk":"208991","name":"本願寺四日市別院総会所","kana":"ほんがんじよっかいちべついんそうがいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県宇佐市四日市1410-2","lat":33.530898,"lng":131.325438,"geo_status":"db","era":"大正4頃","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積337㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0214","desc":"報恩講の際に用いる総会所で、本堂正面南に北面して建つ。入母屋造桟瓦葺、平入で、正面に大型の唐破風造本瓦葺の玄関を構える。内部は本堂外陣のように四本の独立柱筋で三分割された畳敷の広い部屋とし、中央奥に仏壇を備え欄間に箔押し彫刻欄間を嵌める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011021"},{"id":"00011023","register_sub_id":"101","register_pk":"208993","name":"本願寺四日市別院太鼓楼","kana":"ほんがんじよっかいちべついんたいころう","category":"宗教","subcategory":"建築物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531391,"lng":131.325836,"geo_status":"db","era":"弘化4（1847）","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積16㎡","structure_material":"土蔵造2階建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0216","desc":"境内正面の北端に建つ太鼓楼。二重で石垣基壇上に建ち、下層は方二間、上層は方一間で、上層の各面に花頭窓の開口を開け、内部に太鼓を吊るす。屋根は上層入母屋造、下層葺下ろしで外部は壁、軒裏とも漆喰塗込とするが、柱や長押、桁や腕木形を現す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011023"},{"id":"00011017","register_sub_id":"101","register_pk":"208987","name":"本願寺四日市別院対面所","kana":"ほんがんじよっかいちべついんたいめんしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531515,"lng":131.325242,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積205㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0210","desc":"門主と末寺、門徒との対面所で、本堂北に建つ。入母屋造本瓦葺妻入で、正面に大型の唐破風玄関を構える。内部は玄関から廊下を挟んで一八畳と一〇畳床付の上段を並べ、周囲に畳廊下を廻らす。意匠を凝らした格天井や欄間の繊細な組格子なども上質である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011017"},{"id":"00011022","register_sub_id":"101","register_pk":"208992","name":"本願寺四日市別院茶所","kana":"ほんがんじよっかいちべついんちゃしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531375,"lng":131.325713,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0215","desc":"山門北に本堂に向かい合って建つ。入母屋造桟瓦葺妻入で、正面一間通りを吹放しとする。内部は一室で、背面中央に仏壇、両脇に物入を設け、各欄間には箔押しの彫刻欄間を嵌める。天井は格天井とし、桐と下がり藤の紋を描く。真宗寺院伽藍の構成を示す茶所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011022"},{"id":"00011026","register_sub_id":"101","register_pk":"208996","name":"本願寺四日市別院二之門","kana":"ほんがんじよっかいちべついんにのもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531249,"lng":131.326067,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.2m","structure_material":"木造","registered":"2016.02.25(平成28.02.25)","register_no":"44-0219","desc":"境内正面山門前の参道入口を飾る門。一間一戸の建ちの高い高麗門で、屋根は切妻造桟瓦葺で軒は一軒繁垂木である。親柱は五平の角柱、控柱は角柱で、控柱上部に切妻造の小屋根を付す。中備には彫刻付の蟇股を置き、妻飾りは笈形付大瓶束で棟木を支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011026"},{"id":"00011016","register_sub_id":"101","register_pk":"208986","name":"本願寺四日市別院本堂","kana":"ほんがんじよっかいちべついんほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県宇佐市四日市1410-1","lat":33.531287,"lng":131.325183,"geo_status":"db","era":"安政6（1859）","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積1212㎡","structure_material":"木造平屋建","registered":"2016.02.25(平成28.02.25)","register_no":"44-0209","desc":"境内中央に東面して建つ。本堂は桁行三〇メートルの規模を誇り九州最大の木造建築とされる。外陣は畳敷の大空間で、木太い軸組架構を見せる。内陣は彫刻や金箔、彩色で装飾され、来迎柱に須弥壇を構え、背後に後堂を設けるなど本格的な真宗本堂の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011016"},{"id":"00012263","register_sub_id":"101","register_pk":"353064","name":"妙壽寺経蔵","kana":"みょうじゅじきょうぞう","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.557522,"lng":131.441317,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"土蔵造平屋建、瓦葺、建築面積51㎡、輪蔵付","structure_material":"土蔵造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"44-226","desc":"本堂南に東面して建つ。方三間、土蔵造、向拝一間、宝形造。外壁は柱や内法長押を形作り、軒まで塗込める。内部は磚敷で、天井は格天井に天井画を施し、中央に八角輪蔵を据える。正面両脇間に花頭窓を設け、丸桁に唐草の鏝絵を施し、特徴ある外観をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012263"},{"id":"00012266","register_sub_id":"101","register_pk":"353067","name":"妙壽寺山門","kana":"みょうじゅじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.558149,"lng":131.441617,"geo_status":"db","era":"江戸中期","year":1735,"year_source":"estimated","year_min":1661,"year_max":1751,"year_label":"江戸中期","structure":"木造、瓦葺、間口3.5m、左右袖塀付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"44-229","desc":"境内の東面を画する山門。間口三・五メートルの四脚門で、切妻造、本瓦葺。本柱は円柱、控柱は角柱で、中備蟇股で、両脇に三斗を組む。妻飾は大ぶりの板蟇股を置き、蟇股には波を彫る。中門より小ぶりながら、古式をよく留め、風格ある佇まいをみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012266"},{"id":"00012264","register_sub_id":"101","register_pk":"353065","name":"妙壽寺鐘楼","kana":"みょうじゅじしょうろう","category":"宗教","subcategory":"その他工作物","type_guess":"鐘楼","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.557749,"lng":131.441456,"geo_status":"db","era":"宝暦11年(1761）","year":1761,"year_source":"db","year_min":1761,"year_max":1761,"year_label":null,"structure":"木造、瓦葺、面積11㎡","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"44-227","desc":"本堂南東方に建つ。方一間、入母屋造、本瓦葺。切石基壇上に角柱を四方転びに立て、腰貫、頭貫で固める。組物は支輪付出組で、地紋彫の見切板で折上げた格天井を張る。中備は間口いっぱいに幅広の蟇股で、牡丹の彫刻を施し、独創的な意匠をみせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012264"},{"id":"00012265","register_sub_id":"101","register_pk":"353066","name":"妙壽寺中門","kana":"みょうじゅじちゅうもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県豊後高田市金谷町598-1","lat":33.557993,"lng":131.441464,"geo_status":"db","era":"江戸末期／昭和前期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口4.5m、左右袖塀付","structure_material":"木造","registered":"2018.03.27(平成30.03.27)","register_no":"44-228","desc":"本堂の東方に建つ。間口四・五メートルの四脚門で、入母屋造、本瓦葺。本柱は円柱、控柱は角柱で虹梁形頭貫で固め、組物は出組で、蟇股に菊花を彫刻する。天井は鏡天井。規模が大きく、支輪には地紋彫を施し、獏・獅子・麒麟の木鼻を付け壮麗な意匠の中門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012265"},{"id":"00012262","register_sub_id":"101","register_pk":"353063","name":"妙壽寺本堂","kana":"みょうじゅじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県豊後高田市金谷町599","lat":33.557588,"lng":131.441107,"geo_status":"db","era":"明治35年頃／平成11年改修","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積764㎡","structure_material":"木造平屋建","registered":"2018.03.27(平成30.03.27)","register_no":"44-225","desc":"境内奥に東面して建つ。桁行九間、梁間八間、向拝三間で後堂を付す。軒支柱上に枠肘木を組み、外側を出組にして巻斗、実肘木で丸桁を受ける凝った意匠をみせる。浄土真宗本堂の標準平面で、組物は出組で、外陣格天井を高く張る、規模壮大で優美な意匠の本堂。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012262"},{"id":"00008390","register_sub_id":"101","register_pk":"134032","name":"五百禩神社石橋及び石垣","kana":"いおしじんじゃいしばしおよびいしがき","category":"宗教","subcategory":"土木構造物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62459814,"lng":131.34718802,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石橋 石造桁橋、橋長4.1m、幅員4.2m、石垣 石造、延長43m","structure_material":"石橋 石造桁橋","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0070","desc":"石塀から東方に堀割石垣と石橋が設置される。石橋は中央に橋脚を設け、太鼓状に桁を架け、十本の石材を渡す。幅４．２ｍ、橋長４．１ｍで、両側に低い欄干を設置する。石材は地元の飫肥石。石垣は堀の土留で、切石間知積とし、高さ０．７ｍ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008390"},{"id":"00008389","register_sub_id":"101","register_pk":"134031","name":"五百禩神社石塀","kana":"いおしじんじゃいしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62453908,"lng":131.3469806,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、延長64m","structure_material":"石造","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0069","desc":"拝殿の前方に設けられる。東西に延びる参道途中の石段沿いに２．９ｍ設けられ、最下段から北へ１２ｍ、南は２０ｍで、最南端で東に折れ曲がり、山裾を囲うように設置される。高さ１．５ｍで精緻な切石間知積とする。神殿域を厳然と画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008389"},{"id":"00008388","register_sub_id":"101","register_pk":"134030","name":"五百禩神社神楽殿及び拝殿","kana":"いおしじんじゃかぐらでんおよびはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62464759,"lng":131.34664557,"geo_status":"db","era":"明治9年／明治37年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積49㎡、渡殿付","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0068","desc":"本殿の前方に拝殿と神楽殿が続く。神楽殿は一間向拝付の入母屋造で、桁行三間梁間二間、周囲に縁をまわす。拝殿は神楽殿後方に突出する切妻造桁行三間の建物で、いずれも方柱で、板敷。拝殿背後には渡殿をさらに付設する。整備された礼拝空間を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008388"},{"id":"00008387","register_sub_id":"101","register_pk":"134029","name":"五百禩神社本殿","kana":"いおしじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大字楠原字寺の脇1-1他","lat":31.62467805,"lng":131.34650661,"geo_status":"db","era":"明治9年／明治37年改修","year":1876,"year_source":"db","year_min":1876,"year_max":1876,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積23㎡","structure_material":"木造平屋建","registered":"2010.09.10(平成22.09.10)","register_no":"45 － 0067","desc":"境内の西奥に位置し、東面して建つ。三間社流造、桟瓦葺。正側面に擬宝珠高欄付の縁をまわす。方柱で、直接に桁を受け、妻は豕叉首とする。内部は板敷で、後方に壇を設ける。建ちの高い外観になり、装飾を抑えた清冽な社殿である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008387"},{"id":"00001379","register_sub_id":"101","register_pk":"102369","name":"大御神社幣殿・拝殿","kana":"おおみじんじゃへいでん・はいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日向市大字日知屋字伊勢ヶ浜1","lat":32.41101407,"lng":131.64938942,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積35㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"45 － 0009","desc":"本殿と棟を平行に置いた３間×３間，切妻造平入の拝殿から本殿に向けて直交棟の切妻屋根を架けて幣殿に充て，拝殿寄りの幣殿左右に切妻造の神饌所と神具所を配す。それぞれの社殿機能を表す多彩な屋根構成と均整のとれたヴォリューム構成に見所がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001379"},{"id":"00001378","register_sub_id":"101","register_pk":"102368","name":"大御神社本殿","kana":"おおみじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日向市大字日知屋字伊勢ヶ浜1","lat":32.41094755,"lng":131.64946952,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積25㎡","structure_material":"木造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"45 － 0008","desc":"「日向のお伊勢さま」として知られる神社の本殿。伊勢ヶ浜の日向灘を見下ろす崖上に海を背に，高千穂に正面を向けて建つ。棟持柱を持つ神明造りの三間社で，設計施工は地元の谷山武義。形式・規模等について県社寺課の指導を受けたと伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001378"},{"id":"00004090","register_sub_id":"101","register_pk":"105080","name":"願心寺山門","kana":"がんしんじさんもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県都城市庄内町12467","lat":31.77221007,"lng":131.02226917,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造、瓦葺、間口4.1m、左右袖塀付","structure_material":"木造","registered":"2004.03.02(平成16.03.02)","register_no":"45 － 0024","desc":"入母屋造，銅板葺の四脚門で，左右に築地塀形式の板壁をＬ字型に設ける。四隅の角柱は腰長押より下部を外拡がりとし，出組と蟇股をあげ，二軒繁垂木で前後に軒唐破風をつけた軒を受ける。全体に精緻な技巧を駆使した豪放な門で，寺院の正面景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004090"},{"id":"00004089","register_sub_id":"101","register_pk":"105079","name":"願心寺本堂","kana":"がんしんじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県都城市庄内町12467","lat":31.77248659,"lng":131.02279781,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積674㎡","structure_material":"木造平屋建","registered":"2004.03.02(平成16.03.02)","register_no":"45 － 0023","desc":"入母屋造，桟瓦葺，妻入で，彫刻欄間を備えた本格的な浄土真宗本堂。入母屋造で軒唐破風付の門風につくられた正面の向拝，ペディメントを付けた洋風上げ下げ窓など，要所には類例の少ない特異な造形がみられる。棟札から棟梁は鹿児島県川辺町の中村辰次郎。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004089"},{"id":"00008085","register_sub_id":"101","register_pk":"128916","name":"宮崎神宮石柵","kana":"みやざきじんぐういしさく","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93789117,"lng":131.42312612,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"コンクリート造、延長235m","structure_material":"コンクリート造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0065","desc":"玉垣の東・西端から北に延び拝所や神殿域を囲み、神域背面の船塚古墳の石垣に至り、総延長２３５ｍに及ぶ。布石上に方形の柱を建て、７本おきに太い面取柱とし、鉄製の控えを付ける。上部を笠石を載せて固める。コンクリートによる人造石で造る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008085"},{"id":"00008080","register_sub_id":"101","register_pk":"128911","name":"宮崎神宮御料屋","kana":"みやざきじんぐうごりょうや","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.9384041,"lng":131.42375311,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積47㎡、渡廊付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0060","desc":"幣殿の東方に、桁行五間単廊の渡廊で繋がる。桁行四間梁間三間、南北棟の切妻造銅板葺で、神饌所と同じ規模、形式になる。舟肘木で、妻は豕叉首組とし、軒は一軒疎垂木。平入の幣殿を中心に切妻を正面に見せる二棟を東西に配し、対称性の強い正面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008080"},{"id":"00008079","register_sub_id":"101","register_pk":"128910","name":"宮崎神宮神饌所","kana":"みやざきじんぐうしんせんじょ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93834148,"lng":131.42326908,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積47㎡、渡廊付","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0059","desc":"幣殿の西方に位置し、単廊の渡廊で繋がる。桁行四間梁間三間、南北棟の切妻造銅板葺。基壇上に円柱を建て、地覆や貫、内法長押で固め、柱上舟肘木。妻面は板壁で、平側に連子窓や妻戸を装置する。内部は一室で、北面に奥行の浅い神棚などを設ける。神饌所の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008079"},{"id":"00008076","register_sub_id":"101","register_pk":"128907","name":"宮崎神宮神殿","kana":"みやざきじんぐうしんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93836496,"lng":131.42351501,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積30㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0056","desc":"境内の後方、船塚古墳を背に南面して建つ。切妻造妻入銅板葺で、千木と堅魚木を付ける。桁行三間梁間三間で高く床を張り、周囲に組高欄付の榑縁をまわす。正面中央に幣軸を構え両開戸をたて、他は横板壁。軒の深い緩やかな屋根をもち、安定感のある外観になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008076"},{"id":"00008081","register_sub_id":"101","register_pk":"128912","name":"宮崎神宮透間垣","kana":"みやざきじんぐうすきまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93867743,"lng":131.42345369,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、延長88m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0061","desc":"神饌所と御料屋の北面から、本殿を半八角形状に囲む。延長８８ｍ。基壇上に円柱を建て、地覆や腰長押、内法長押で固め、腰板壁で連子窓を開け、南寄りに両開板戸を設け、出入口とする。柱上部から腕木状の材を出し、板軒を支持。軽快な意匠で、丁寧に造られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008081"},{"id":"00008083","register_sub_id":"101","register_pk":"128914","name":"宮崎神宮正門","kana":"みやざきじんぐうせいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93784287,"lng":131.42361476,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、間口5.5m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0063","desc":"拝所の南方、参道正面に位置する。間口５．５ｍと規模の大きい四脚門。切妻造銅板葺。本柱・控柱とも円柱で、冠木や貫で固め、控柱上には舟肘木を置く。一軒疎垂木とし、豕叉首組、中備に束を建てる。菊紋の大きな金具を飾る板戸両開をたてる。簡明で重厚な門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008083"},{"id":"00008084","register_sub_id":"101","register_pk":"128915","name":"宮崎神宮玉垣","kana":"みやざきじんぐうたまがき","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93781813,"lng":131.42346632,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造、銅板葺、延長119m","structure_material":"木造","registered":"2010.01.15(平成22.01.15)","register_no":"45-0064","desc":"正門の左右から東西に延びる垣で、一度南に折れ、再び東西に続く。総延長１１９ｍ。基壇上に円柱を建て、地覆で固め、柱上に腕木状の材を出して板軒を支持。背面には控えを建て、柱間は木柵とする。屋根は猿頭型の銅板瓦棒葺とする。森厳たる雰囲気で神域を画する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008084"},{"id":"00008086","register_sub_id":"101","register_pk":"128917","name":"宮崎神宮徴古館","kana":"みやざきじんぐうちょうこかん","category":"宗教","subcategory":"建築物","type_guess":"庫裏・客殿","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93745062,"lng":131.4242188,"geo_status":"db","era":"明治42","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"木造2階建、瓦葺、建築面積205㎡","structure_material":"木造2階建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0066","desc":"神門の東南、木立の中に所在する。桁行１８ｍ梁間１１ｍの木造２階建。寄棟造妻入桟瓦葺で、西正面に切妻屋根を付け、玄関とする。外壁は全体を海鼠壁とし、隅と階境に柱型などを造り出し、鉄格子を嵌める上げ下げ窓を等間隔に配する。独特の意匠になる展示館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008086"},{"id":"00008082","register_sub_id":"101","register_pk":"128913","name":"宮崎神宮拝所","kana":"みやざきじんぐうはいしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93807653,"lng":131.42356528,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積42㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0062","desc":"幣殿の南方、正門との中程に位置する。桁行三間梁間三間、切妻造銅板葺。礎石上に円柱を建て、内法貫で固め、舟肘木を置き、桁や梁を支持。小壁を板壁とし、一軒疎垂木。四方吹放ちで、石敷、化粧屋根裏とし、各梁間に豕叉首を組む。大規模で、開放的な拝所。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008082"},{"id":"00008077","register_sub_id":"101","register_pk":"128908","name":"宮崎神宮幣殿","kana":"みやざきじんぐうへいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93854435,"lng":131.42347587,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積141㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0057","desc":"本殿の南に位置する、東西棟の切妻造銅板葺。桁行七間梁間四間、正面に三間向拝を付け、四周に組高欄付榑縁を巡らす。円柱で、舟肘木を置き、一軒繁垂木。中央三間に双折両開板戸、両端二間に蔀を装置。妻は豕叉首で、棟木筋にも豕叉首を組む独特の構法を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008077"},{"id":"00008078","register_sub_id":"101","register_pk":"128909","name":"宮崎神宮渡殿","kana":"みやざきじんぐうわたりでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"low","period":"明治","pref":"宮崎県","address":"宮崎県宮崎市神宮2-485-1他","lat":31.93845955,"lng":131.42349349,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"45-0058","desc":"本殿と幣殿を繋ぐ、南北棟の建物。切妻造銅板葺で南は幣殿屋根に取り付く。桁行四間梁間一間で、高欄付の榑縁を東西に張る。円柱、舟肘木とし、一軒疎垂木。床拭板敷で、化粧屋根裏天井とし、豕叉首組を見せる。吹放ちであるが、腰に蔀を嵌め込むことができる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008078"},{"id":"00005688","register_sub_id":"101","register_pk":"106676","name":"霧島神宮社務所","kana":"きりしまじんぐうしゃむしょ","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"鹿児島県","address":"鹿児島県霧島市霧島田口","lat":31.85789113,"lng":130.86973362,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積548㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"46 － 0024","desc":"南東を向いて建ち，正面中央に切妻造の玄関を突出し，北に座敷飾りを備えた応接室等，南には中廊下式で斎館や事務室等を配する。良材を用いた上質なつくりになる大規模和風建築で，複雑な平面に対応した屋根を巧妙に架け，落ち着いた社頭景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005688"},{"id":"00007154","register_sub_id":"101","register_pk":"108136","name":"新照寺石塀","kana":"しんしょうじいしべい","category":"宗教","subcategory":"その他工作物","type_guess":"塀・手水舎","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.7620026,"lng":130.595026,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、延長58m","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0071","desc":"境内地の南辺と西辺際に流れる水路に沿って築いた城郭風石積擁壁の上に、尺角状の長石を３段に積み、頂部に笠石を載せる。門柱同様に出隅部の笠石に反りをつけるなど凝ったつくりに特徴がある。石塀に嵌め込まれた銘板石から年代が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007154"},{"id":"00007153","register_sub_id":"101","register_pk":"108135","name":"新照寺正門","kana":"しんしょうじせいもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.76193625,"lng":130.59522524,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、間口3.1m、袖塀付","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0070","desc":"本堂正面の南方に位置し、前面道路からの斜路を登りきった地点に建つ。間口３．１ｍ、門柱高３．４ｍで、門柱は几帳面を施した石柱とし、頂部に反りをつけた笠石を載せる。左右には６段積に笠石を載せた袖塀が取り付き、石造の本堂に対応した門構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007153"},{"id":"00007155","register_sub_id":"101","register_pk":"108137","name":"新照寺通用門","kana":"しんしょうじつうようもん","category":"宗教","subcategory":"その他工作物","type_guess":"山門","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.76214519,"lng":130.59502696,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、間口1.1m","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0072","desc":"本堂外陣の西方、石塀北端部に位置し、西側道路から登る９段の石階段の上に建つ。間口１．１ｍ、門柱高２．０ｍの石造門で、１本石の長石を門柱とし、門柱間に屋根型の楣石を載せる。楣石の上面につけた反りが、正門及び石塀と同時期の築造を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007155"},{"id":"00007152","register_sub_id":"101","register_pk":"108134","name":"新照寺本堂","kana":"しんしょうじほんどう","category":"宗教","subcategory":"建築物","type_guess":"本堂","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市住吉字櫻木545","lat":31.76218961,"lng":130.59518169,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積290㎡","structure_material":"石造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0069","desc":"正面梁間１６ｍ桁行１８ｍ、寄棟造妻入桟瓦葺の石造本堂で、正面屋根を切り上げて前面に葺き降ろし向拝とする。外周の石造壁は側・背面に各２ヶ所の控壁を設け、４隅は算木状に突きだした隅石風の意匠を採る。棟札により上棟年代と石工棟梁及び大工棟梁が判明。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007152"},{"id":"00007157","register_sub_id":"101","register_pk":"108139","name":"瀬留カトリック教会司祭館","kana":"せどめかとりっくきょうかいしさいかん","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県大島郡龍郷町大字瀬留字中郷原271-1","lat":28.4239699,"lng":129.59150311,"geo_status":"db","era":"明治41頃／昭和62改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積114㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0074","desc":"教会聖堂の東に位置し、東西棟で建つ。桁行１２ｍ梁間６．０ｍ規模、寄棟造鉄板葺の木造２階建で、北側に平屋建の附属屋を突出させる。外部は下見板張に仕上げる。改造はあるが、教会聖堂とともに奄美大島におけるカトリック布教の足跡の一端を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007157"},{"id":"00007156","register_sub_id":"101","register_pk":"108138","name":"瀬留カトリック教会聖堂","kana":"せどめかとりっくきょうかいせいどう","category":"宗教","subcategory":"建築物","type_guess":"教会","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県大島郡龍郷町大字瀬留字中郷原271-1","lat":28.42384221,"lng":129.59137693,"geo_status":"db","era":"明治41／昭和24・昭和62改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積221㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"46 － 0073","desc":"桁行２０ｍ梁間１１ｍ規模、北側を寄棟造、南側を入母屋造とし、南面に切妻造の玄関を突出させた教会堂で、外部は下見板張とする。正面外観は大きく改造されているが、内部は３廊式で、身廊部を高くし側廊ともに平天井を張り、創建時の面影をよく留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007156"},{"id":"00007942","register_sub_id":"101","register_pk":"128546","name":"都萬神社拝殿","kana":"つまじんじゃはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.4266994,"lng":131.00963421,"geo_status":"db","era":"大正5／平成9改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積66㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0087","desc":"本殿の前方に南面して建つ。桁行四間梁間三間、入母屋造妻入、向拝一間、桟瓦葺。本殿との間に、桁行三間梁間一間の回廊を付ける。方柱で、木鼻付平三斗組とし、中備に蟇股を飾る。一軒疎垂木。回廊も同じ仕様。装飾的な本殿と対照的に簡明な意匠とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007942"},{"id":"00007941","register_sub_id":"101","register_pk":"128545","name":"都萬神社本殿","kana":"つまじんじゃほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42679918,"lng":131.00956124,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積53㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0086","desc":"小高い丘陵地に占める境内地の北寄りに、南面して建つ。桁行正面三間背面四間、梁間三間、入母屋造、向拝一間、桟瓦葺の社殿。組物は平三斗上に絵様肘木を置き、巻斗５個を並べ、前方へ三段に木鼻を出す特殊な形。中備の蟇股には十二支のレリーフを飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007941"},{"id":"00007943","register_sub_id":"101","register_pk":"128547","name":"都萬神社末社伊勢宮","kana":"つまじんじゃまっしゃいせみや","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42682598,"lng":131.00943317,"geo_status":"db","era":"大正5／平成17頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0088","desc":"本殿の西方に南面して建つ社殿。桁行一間梁間一間、入母屋造、向拝一間、銅板葺。円柱で三斗組とし、中備に蟇股を配す。軒は二軒繁垂木。正面に格子戸をたて、側・背面は横板壁とする。向拝の蟇股や組物はやや大振りで、蟇股に夫婦岩を彫る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007943"},{"id":"00007944","register_sub_id":"101","register_pk":"128548","name":"都萬神社末社稲荷神社","kana":"つまじんじゃまっしゃいなりじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42681109,"lng":131.00940189,"geo_status":"db","era":"大正5／平成17改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.1㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0089","desc":"末社伊勢宮の西に南面して建つ。小規模な一間社。流造屋根で銅板葺。円柱を切目長押や内法長押で固め、頭貫を通す。木鼻には雲紋風に絵様を施す。二軒繁垂木。正面中備の蟇股は本殿などと同様の形になり、大正再建の経緯が陰刻される。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007944"},{"id":"00007945","register_sub_id":"101","register_pk":"128549","name":"都萬神社末社五林大明神社","kana":"つまじんじゃまっしゃごりんだいみょうじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42689597,"lng":131.00959995,"geo_status":"db","era":"大正5／平成17頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.53㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0090","desc":"本殿の東に南面して建つ。末社の中で最も小規模な社殿。一間社流見世棚造、銅板葺。方柱で三斗組とし、二軒繁垂木。向拝身舎間には海老虹梁を架けて、固める。向拝は方柱で、柱上に木鼻付平三斗を置く。水引虹梁は二段に折り上げ、中央に蟇股を飾る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007945"},{"id":"00007946","register_sub_id":"101","register_pk":"128550","name":"都萬神社末社山王神社","kana":"つまじんじゃまっしゃさんおうじんじゃ","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"大正","pref":"鹿児島県","address":"鹿児島県曽於郡大崎町假宿字西迫1589","lat":31.42691384,"lng":131.00962378,"geo_status":"db","era":"大正5／平成17頃改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積1.2㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"46-0091","desc":"末社五林大明神社の東に、南面して建つ小規模な社殿。桁行一間梁間一間、入母屋造、向拝一間、銅板葺。円柱で、三斗組とし、中備に蟇股を飾る。二軒繁垂木。向拝には皿斗付大斗を用い、平三斗とする。本殿と同時期の社殿群が、伝統的な境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007946"},{"id":"00005776","register_sub_id":"101","register_pk":"106764","name":"南洲神社電燈","kana":"なんしゅうじんじゃでんとう","category":"宗教","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県鹿児島市上竜尾町2-1","lat":31.606264,"lng":130.559601,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄製2基、高さ4.4m","structure_material":"鉄製2基","registered":"2006.10.18(平成18.10.18)","register_no":"46 － 0033","desc":"南洲神社拝殿の参道，石段を登った両脇に一対立つ。高さ４．４ｍの鋳鉄製で，柱脚は六角形の断面，柱頭は六方に開いた花弁状で飾り，各接合部には繰形などの装飾を付ける。近代日本の礎となった旧集成館が製造した数少ない遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005776"},{"id":"00016762","register_sub_id":"101","register_pk":"579246","name":"島根殿アガリユーヌウトゥーシ","kana":"しまにどぅんあがりゆーぬうとぅーし","category":"宗教","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296201,"lng":127.80777,"geo_status":"db","era":"昭和15年頃","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造平屋建、面積0.6㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0095","desc":"境内の東側に位置し、東方のニライカナイに向かって豊穣を祈願する拝所。高い基壇上に建つ方一間、鉄筋コンクリート造切妻造平入、モルタル洗出仕上。正面中央に透鉄扉を開き、内部の祭壇に香炉を配する。小規模ながら重厚な姿で、独特な境内景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016762"},{"id":"00016763","register_sub_id":"101","register_pk":"579247","name":"島根殿鳥居","kana":"しまにどぅんとりい","category":"宗教","subcategory":"その他工作物","type_guess":"鳥居","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296144,"lng":127.807737,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造、間口2.7m、高さ3.3m","structure_material":"鉄筋コンクリート造","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0096","desc":"本殿と拝殿の軸線上に建つ神明鳥居。全高三・三メートル、柱間二・七メートル、鉄筋コンクリート造、モルタル洗出仕上とする。一対の円柱を立てて、頂部に円柱の笠木形を渡し、貫の楔や額束も設けず、全体に簡素なつくり。境内の歴史的な景観を形成する鳥居。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016763"},{"id":"00016761","register_sub_id":"101","register_pk":"579245","name":"島根殿拝殿","kana":"しまにどぅんはいでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296169,"lng":127.807582,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0094","desc":"本殿の前方に東面して建つ拝殿。木造平屋建入母屋造、琉球赤瓦葺。方三間で角柱を立て、組物は舟肘木。四方とも中央一間を開放とし、両脇間は腰壁を設ける。内部はタイル貼の土間で棹縁天井を張る。滴水瓦で軒先を飾り、地域の特色ある境内景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016761"},{"id":"00016760","register_sub_id":"101","register_pk":"579244","name":"島根殿本殿","kana":"しまにどぅんほんでん","category":"宗教","subcategory":"建築物","type_guess":"本殿・拝殿","type_guess_confidence":"high","period":"明治","pref":"沖縄県","address":"沖縄県中頭郡北中城村字熱田東原68-1","lat":26.296159,"lng":127.80762,"geo_status":"db","era":"昭和15年","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"鉄筋コンクリート造平屋建、建築面積1.9㎡","structure_material":"鉄筋コンクリート造平屋建","registered":"2026.07.09(令和8.07.09)","register_no":"47 - 0093","desc":"集落中心部に位置する旧御嶽を神社化した本殿。鉄筋コンクリート造一間社流造で、屋根に鳥衾付鬼板を載せる。垂木を疎らに配って簡略化した形態とするが、組物や絵様まで精巧につくる。昭和戦前に沖縄で進展した、御嶽の神社化を示す貴重な耐火建築の本殿。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016760"}];
